export enum TransactionType {
  BUY = 'BUY',
  SELL = 'SELL',
  DEPOSIT = 'DEPOSIT',
  WITHDRAW = 'WITHDRAW',
  DIVIDEND = 'DIVIDEND'
}

export enum AssetClass {
  STOCK = 'Stock',
  CRYPTO = 'Crypto',
  FUND = 'Fund',
  GOLD = 'Gold',
  CASH = 'Cash'
}

export interface Transaction {
  id: string;
  date: string;
  type: TransactionType;
  symbol?: string; // e.g., AAPL, BTC
  name?: string; // e.g., Apple Inc.
  assetClass?: AssetClass;
  sector?: string; // e.g., Tech, Finance
  shares?: number;
  price?: number; // Price per share or Amount for Deposit/Withdraw
  fee?: number;
  exchangeRate?: number; // 1 for local currency
  notes?: string;
}

export interface Holding {
  symbol: string;
  name: string;
  assetClass: AssetClass;
  sector: string;
  shares: number;
  avgCost: number;
  totalCost: number;
  currentPrice: number;
  marketValue: number;
  unrealizedPL: number;
  unrealizedPLPercent: number;
  realizedPL: number;
  totalDividends: number;
  totalReturn: number;
}

export interface MonthlyReturn {
  yearMonth: string; // YYYY-MM
  value: number; // Percentage
}

export interface PortfolioState {
  transactions: Transaction[];
  prices: Record<string, number>; // symbol -> current price
  financialGoal: number;
  monthlyReturns: Record<string, number>; // YYYY-MM -> %
}

export interface ChartDataPoint {
  date: string;
  invested: number;
  value: number;
}

import { Transaction, TransactionType, Holding, AssetClass, ChartDataPoint } from './types';

export const formatCurrency = (amount: number) => {
  return new Intl.NumberFormat('en-US', {
    style: 'currency',
    currency: 'USD',
    minimumFractionDigits: 0,
    maximumFractionDigits: 0,
  }).format(amount);
};

export const formatNumber = (num: number, decimals = 2) => {
  return new Intl.NumberFormat('en-US', {
    minimumFractionDigits: decimals,
    maximumFractionDigits: decimals,
  }).format(num);
};

export const generateId = () => Math.random().toString(36).substr(2, 9);

// Calculate holdings based on transaction history
export const calculateHoldings = (transactions: Transaction[], prices: Record<string, number>): Holding[] => {
  const holdingsMap: Record<string, Holding> = {};

  // Sort transactions by date ascending
  const sortedTx = [...transactions].sort((a, b) => new Date(a.date).getTime() - new Date(b.date).getTime());

  sortedTx.forEach(tx => {
    if (!tx.symbol) return;

    if (!holdingsMap[tx.symbol]) {
      holdingsMap[tx.symbol] = {
        symbol: tx.symbol,
        name: tx.name || tx.symbol,
        assetClass: tx.assetClass || AssetClass.STOCK,
        sector: tx.sector || 'General',
        shares: 0,
        avgCost: 0,
        totalCost: 0,
        currentPrice: prices[tx.symbol] || 0,
        marketValue: 0,
        unrealizedPL: 0,
        unrealizedPLPercent: 0,
        realizedPL: 0,
        totalDividends: 0,
        totalReturn: 0
      };
    }

    const h = holdingsMap[tx.symbol];
    const price = tx.price || 0;
    const shares = tx.shares || 0;
    const fee = tx.fee || 0;

    if (tx.type === TransactionType.BUY) {
      const cost = (price * shares) + fee;
      h.totalCost += cost;
      h.shares += shares;
      h.avgCost = h.totalCost / h.shares;
    } else if (tx.type === TransactionType.SELL) {
      const proceeds = (price * shares) - fee;
      const costBasis = h.avgCost * shares;
      h.realizedPL += (proceeds - costBasis);
      h.shares -= shares;
      h.totalCost -= costBasis;
      // Prevent small floating point errors
      if (h.shares < 0.000001) {
        h.shares = 0;
        h.totalCost = 0;
      }
    } else if (tx.type === TransactionType.DIVIDEND) {
      h.totalDividends += (price - fee); // price here acts as total amount
    }
  });

  // Final Calculations based on current price
  return Object.values(holdingsMap).map(h => {
    // If user provided a price, update it, otherwise keep 0 (or last known)
    if (prices[h.symbol]) h.currentPrice = prices[h.symbol];

    h.marketValue = h.shares * h.currentPrice;
    h.unrealizedPL = h.marketValue - h.totalCost;
    h.unrealizedPLPercent = h.totalCost > 0 ? (h.unrealizedPL / h.totalCost) * 100 : 0;
    h.totalReturn = h.unrealizedPL + h.realizedPL + h.totalDividends;

    return h;
  }).filter(h => h.shares > 0 || h.realizedPL !== 0 || h.totalDividends !== 0); // Keep if we have history/shares
};

export const calculatePortfolioHistory = (transactions: Transaction[]): ChartDataPoint[] => {
  const points: ChartDataPoint[] = [];
  const sortedTx = [...transactions].sort((a, b) => new Date(a.date).getTime() - new Date(b.date).getTime());

  if (sortedTx.length === 0) return [];

  let runningInvested = 0;

  // Create a streamlined timeline
  sortedTx.forEach(tx => {
    if (tx.type === TransactionType.DEPOSIT) {
      runningInvested += (tx.price || 0);
    } else if (tx.type === TransactionType.WITHDRAW) {
      runningInvested -= (tx.price || 0);
    }

    // For "Value" line: In a real app we need historical price data.
    // Here we will simulate "Value" tracking "Invested" plus a randomized growth curve
    // simply for visualization since we don't have an API.
    // Ideally, "Value" = Sum(Shares * HistoricalPrice) + Cash

    // NOTE: Simplified simulation for the chart "gap" demonstration
    points.push({
      date: tx.date,
      invested: runningInvested,
      value: runningInvested // Placeholder: Real calculation requires historical prices
    });
  });

  return points;
};

// Simple CAGR calculation
export const calculateCAGR = (startValue: number, endValue: number, years: number) => {
  if (startValue <= 0 || years <= 0) return 0;
  return (Math.pow(endValue / startValue, 1 / years) - 1) * 100;
};

import React, { useState, useEffect } from 'react';
