import React from 'react';
import { Holding, Transaction } from '../types';
import { formatCurrency, formatNumber } from '../utils';
import { 
  AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, 
  PieChart, Pie, Cell, BarChart, Bar 
} from 'recharts';
import { ArrowUpRight, ArrowDownRight, TrendingUp, DollarSign, Target } from 'lucide-react';

interface DashboardProps {
  holdings: Holding[];
  transactions: Transaction[];
  financialGoal: number;
  setFinancialGoal: (val: number) => void;
  investedAmount: number;
  cashBalance: number;
  portfolioValue: number;
}

const COLORS = ['#3b82f6', '#10b981', '#f59e0b', '#ef4444', '#8b5cf6', '#ec4899'];

const Dashboard: React.FC<DashboardProps> = ({ 
  holdings, financialGoal, setFinancialGoal, investedAmount, portfolioValue, cashBalance 
}) => {
  const totalNetWorth = portfolioValue + cashBalance;
  const totalUnrealizedPL = holdings.reduce((sum, h) => sum + h.unrealizedPL, 0);
  const totalPLPercent = investedAmount > 0 ? (totalUnrealizedPL / investedAmount) * 100 : 0;

  // Prepare data for Allocation Chart
  const allocationData = holdings
    .filter(h => h.marketValue > 0)
    .map(h => ({ name: h.assetClass, value: h.marketValue }))
    .reduce((acc: any[], curr) => {
      const existing = acc.find(item => item.name === curr.name);
      if (existing) {
        existing.value += curr.value;
      } else {
        acc.push({ ...curr });
      }
      return acc;
    }, []);

  // Simulating Growth Chart Data (Use Real Invested History in real implementation)
  const growthData = [
     { name: 'Start', invested: investedAmount * 0.2, value: investedAmount * 0.2 },
     { name: 'Q1', invested: investedAmount * 0.4, value: investedAmount * 0.45 },
     { name: 'Q2', invested: investedAmount * 0.6, value: investedAmount * 0.75 },
     { name: 'Q3', invested: investedAmount * 0.8, value: investedAmount * 1.1 },
     { name: 'Now', invested: investedAmount, value: portfolioValue }
  ];

  return (
    <div className="space-y-6">
      {/* Overview Cards */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
        <div className="bg-white dark:bg-slate-800 p-6 rounded-2xl shadow-sm border border-gray-100 dark:border-slate-700">
          <div className="flex justify-between items-start mb-4">
            <div>
              <p className="text-sm text-gray-500 dark:text-gray-400 font-medium">Net Worth</p>
              <h3 className="text-2xl font-bold text-gray-900 dark:text-white mt-1">{formatCurrency(totalNetWorth)}</h3>
            </div>
            <div className="p-2 bg-blue-50 dark:bg-slate-700 rounded-lg text-blue-600 dark:text-blue-400">
              <DollarSign size={20} />
            </div>
          </div>
          <div className="text-xs text-gray-400">Cash: {formatCurrency(cashBalance)}</div>
        </div>

        <div className="bg-white dark:bg-slate-800 p-6 rounded-2xl shadow-sm border border-gray-100 dark:border-slate-700">
          <div className="flex justify-between items-start mb-4">
            <div>
              <p className="text-sm text-gray-500 dark:text-gray-400 font-medium">Unrealized P/L</p>
              <h3 className={`text-2xl font-bold mt-1 ${totalUnrealizedPL >= 0 ? 'text-success' : 'text-danger'}`}>
                {totalUnrealizedPL >= 0 ? '+' : ''}{formatCurrency(totalUnrealizedPL)}
              </h3>
            </div>
            <div className={`p-2 rounded-lg ${totalUnrealizedPL >= 0 ? 'bg-green-50 text-success' : 'bg-red-50 text-danger'}`}>
              {totalUnrealizedPL >= 0 ? <ArrowUpRight size={20} /> : <ArrowDownRight size={20} />}
            </div>
          </div>
          <div className={`text-xs font-medium ${totalPLPercent >= 0 ? 'text-success' : 'text-danger'}`}>
            {totalPLPercent.toFixed(2)}% Return
          </div>
        </div>

        <div className="bg-white dark:bg-slate-800 p-6 rounded-2xl shadow-sm border border-gray-100 dark:border-slate-700">
           <div className="flex justify-between items-start mb-4">
            <div>
              <p className="text-sm text-gray-500 dark:text-gray-400 font-medium">Goal Progress</p>
              <h3 className="text-2xl font-bold text-gray-900 dark:text-white mt-1">
                {financialGoal > 0 ? ((totalNetWorth / financialGoal) * 100).toFixed(1) : 0}%
              </h3>
            </div>
            <button 
              onClick={() => {
                const newGoal = prompt("Set Financial Goal ($):", financialGoal.toString());
                if (newGoal && !isNaN(Number(newGoal))) setFinancialGoal(Number(newGoal));
              }}
              className="p-2 bg-purple-50 dark:bg-slate-700 rounded-lg text-purple-600 dark:text-purple-400 hover:bg-purple-100 dark:hover:bg-slate-600"
            >
              <Target size={20} />
            </button>
          </div>
          <div className="w-full bg-gray-200 dark:bg-slate-700 rounded-full h-1.5 mt-2">
            <div 
              className="bg-purple-600 h-1.5 rounded-full transition-all duration-1000" 
              style={{ width: `${Math.min((totalNetWorth / financialGoal) * 100, 100)}%` }}
            ></div>
          </div>
          <div className="text-xs text-gray-400 mt-2">Target: {formatCurrency(financialGoal)}</div>
        </div>

        <div className="bg-white dark:bg-slate-800 p-6 rounded-2xl shadow-sm border border-gray-100 dark:border-slate-700">
           <div className="flex justify-between items-start mb-4">
            <div>
              <p className="text-sm text-gray-500 dark:text-gray-400 font-medium">CAGR</p>
              <h3 className="text-2xl font-bold text-gray-900 dark:text-white mt-1">12.5%</h3>
            </div>
            <div className="p-2 bg-orange-50 dark:bg-slate-700 rounded-lg text-orange-600 dark:text-orange-400">
              <TrendingUp size={20} />
            </div>
          </div>
          <div className="text-xs text-gray-400">Annualized Growth</div>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        {/* Wealth Growth Chart */}
        <div className="lg:col-span-2 bg-white dark:bg-slate-800 p-6 rounded-2xl shadow-sm border border-gray-100 dark:border-slate-700">
          <h3 className="text-lg font-bold text-gray-900 dark:text-white mb-6">Wealth Growth (Gap Analysis)</h3>
          <div className="h-[300px] w-full">
            <ResponsiveContainer width="100%" height="100%">
              <AreaChart data={growthData}>
                <defs>
                  <linearGradient id="colorValue" x1="0" y1="0" x2="0" y2="1">
                    <stop offset="5%" stopColor="#3b82f6" stopOpacity={0.3}/>
                    <stop offset="95%" stopColor="#3b82f6" stopOpacity={0}/>
                  </linearGradient>
                </defs>
                <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" opacity={0.5} vertical={false} />
                <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fill: '#94a3b8', fontSize: 12}} dy={10} />
                <YAxis axisLine={false} tickLine={false} tick={{fill: '#94a3b8', fontSize: 12}} tickFormatter={(val) => `$${val/1000}k`} />
                <Tooltip 
                  contentStyle={{ backgroundColor: '#1e293b', border: 'none', borderRadius: '8px', color: '#fff' }}
                  itemStyle={{ color: '#fff' }}
                  formatter={(value: number) => formatCurrency(value)}
                />
                <Area type="monotone" dataKey="value" stroke="#3b82f6" strokeWidth={3} fillOpacity={1} fill="url(#colorValue)" name="Market Value" />
                <Area type="monotone" dataKey="invested" stroke="#94a3b8" strokeDasharray="5 5" strokeWidth={2} fill="transparent" name="Net Invested" />
              </AreaChart>
            </ResponsiveContainer>
          </div>
        </div>

        {/* Allocation */}
        <div className="bg-white dark:bg-slate-800 p-6 rounded-2xl shadow-sm border border-gray-100 dark:border-slate-700">
          <h3 className="text-lg font-bold text-gray-900 dark:text-white mb-4">Allocation</h3>
          <div className="h-[200px] w-full flex justify-center">
            {allocationData.length > 0 ? (
               <ResponsiveContainer width="100%" height="100%">
                <PieChart>
                  <Pie
                    data={allocationData}
                    cx="50%"
                    cy="50%"
                    innerRadius={60}
                    outerRadius={80}
                    paddingAngle={5}
                    dataKey="value"
                  >
                    {allocationData.map((entry, index) => (
                      <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                    ))}
                  </Pie>
                  <Tooltip formatter={(value: number) => formatCurrency(value)} />
                </PieChart>
              </ResponsiveContainer>
            ) : (
              <div className="flex items-center justify-center text-gray-400 text-sm">No assets yet</div>
            )}

          </div>
          <div className="mt-4 space-y-2">
             {allocationData.slice(0, 4).map((entry, idx) => (
               <div key={idx} className="flex justify-between text-sm">
                 <div className="flex items-center">
                   <div className="w-3 h-3 rounded-full mr-2" style={{ backgroundColor: COLORS[idx % COLORS.length] }}></div>
                   <span className="text-gray-600 dark:text-gray-300">{entry.name}</span>
                 </div>
                 <span className="font-medium text-gray-900 dark:text-white">
                   {((entry.value / portfolioValue) * 100).toFixed(1)}%
                 </span>
               </div>
             ))}
          </div>
        </div>
      </div>
    </div>
  );
};

export default Dashboard;

