  const [currentFxRate, setCurrentFxRate] = useState<number>(35); // Default assumption, user can change

  // FX Gain Logic
  // Value in Local = Current Portfolio Value (USD) * Current Rate
  // Cost in Local = Net Funding Local
  const currentValueLocal = currentPortfolioValue * currentFxRate;
  const totalGainLocal = currentValueLocal - netFundingLocal;
  const fxGain = (netFundingUSD * currentFxRate) - netFundingLocal; // Gain purely from holding the cash in USD terms? 
