export const formatCurrency = (amount: number, currency = 'USD') => {
  return new Intl.NumberFormat('en-US', {
    style: 'currency',
    currency: currency,
    minimumFractionDigits: 0,
    maximumFractionDigits: 2,
  }).format(amount);
};

export const formatNumber = (num: number, decimals = 2) => {
  return new Intl.NumberFormat('en-US', {
    minimumFractionDigits: decimals,
    maximumFractionDigits: decimals,
  }).format(num);
};

export const generateId = () => Math.random().toString(36).substr(2, 9);

// Calculate holdings based on transaction history
export const calculateHoldings = (transactions: Transaction[], prices: Record<string, number>): Holding[] => {
  const holdingsMap: Record<string, Holding> = {};

  // Sort transactions by date ascending
  const sortedTx = [...transactions].sort((a, b) => new Date(a.date).getTime() - new Date(b.date).getTime());

  sortedTx.forEach(tx => {
    if (!tx.symbol) return;

    if (!holdingsMap[tx.symbol]) {
      holdingsMap[tx.symbol] = {
        symbol: tx.symbol,
        name: tx.name || tx.symbol,
        assetClass: tx.assetClass || AssetClass.STOCK,
        sector: tx.sector || 'General',
        shares: 0,
        avgCost: 0,
        totalCost: 0,
        currentPrice: prices[tx.symbol] || 0,
        marketValue: 0,
        unrealizedPL: 0,
        unrealizedPLPercent: 0,
        realizedPL: 0,
        totalDividends: 0,
        totalReturn: 0
      };
    }

    const h = holdingsMap[tx.symbol];
    const price = tx.price || 0;
    const shares = tx.shares || 0;
    const fee = tx.fee || 0;

    if (tx.type === TransactionType.BUY) {
      const cost = (price * shares) + fee;
      h.totalCost += cost;
      h.shares += shares;
      h.avgCost = h.totalCost / h.shares;
    } else if (tx.type === TransactionType.SELL) {
      const proceeds = (price * shares) - fee;
      const costBasis = h.avgCost * shares;
      h.realizedPL += (proceeds - costBasis);
      h.shares -= shares;
      h.totalCost -= costBasis;
      // Prevent small floating point errors
      if (h.shares < 0.000001) {
        h.shares = 0;
        h.totalCost = 0;
      }
    } else if (tx.type === TransactionType.DIVIDEND) {
      h.totalDividends += (price - fee); // price here acts as total amount
    }
  });

  // Final Calculations based on current price
  return Object.values(holdingsMap).map(h => {
    // If user provided a price, update it, otherwise keep 0 (or last known)
    if (prices[h.symbol]) h.currentPrice = prices[h.symbol];

    h.marketValue = h.shares * h.currentPrice;
    h.unrealizedPL = h.marketValue - h.totalCost;
    h.unrealizedPLPercent = h.totalCost > 0 ? (h.unrealizedPL / h.totalCost) * 100 : 0;
    h.totalReturn = h.unrealizedPL + h.realizedPL + h.totalDividends;

    return h;
  }).filter(h => h.shares > 0 || h.realizedPL !== 0 || h.totalDividends !== 0); // Keep if we have history/shares
};

export const calculatePortfolioHistory = (transactions: Transaction[], currentPrices: Record<string, number>): ChartDataPoint[] => {
  if (transactions.length === 0) return [];

  // Sort by date
  const sortedTx = [...transactions].sort((a, b) => new Date(a.date).getTime() - new Date(b.date).getTime());

  const points: ChartDataPoint[] = [];
  let invested = 0;
  let cash = 0;
  const holdings: Record<string, { shares: number, lastPrice: number }> = {};

  sortedTx.forEach(tx => {
    // Invested Logic
    if (tx.type === TransactionType.DEPOSIT) invested += (tx.price || 0);
    if (tx.type === TransactionType.WITHDRAW) invested -= (tx.price || 0);

    // Cash Logic
    const amount = (tx.price || 0);
    const shares = (tx.shares || 0);
    const fee = (tx.fee || 0);

    if (tx.type === TransactionType.DEPOSIT) cash += amount;
    else if (tx.type === TransactionType.WITHDRAW) cash -= amount;
    else if (tx.type === TransactionType.DIVIDEND) cash += amount;

    // Trade Logic
    if (tx.symbol) {
        if (!holdings[tx.symbol]) holdings[tx.symbol] = { shares: 0, lastPrice: 0 };
        const h = holdings[tx.symbol];

        // Update price from transaction if available (Buy/Sell)
        if (amount > 0 && (tx.type === TransactionType.BUY || tx.type === TransactionType.SELL)) {
            h.lastPrice = amount; // For Buy/Sell, price field is per share
        }

        const tradeTotal = (amount * shares);

        if (tx.type === TransactionType.BUY) {
            cash -= (tradeTotal + fee);
            h.shares += shares;
        } else if (tx.type === TransactionType.SELL) {
            cash += (tradeTotal - fee);
            h.shares -= shares;
        }
    }

    // Calculate Portfolio Value at this point
    let stockValue = 0;
    Object.values(holdings).forEach(h => {
        stockValue += h.shares * h.lastPrice;
    });

    points.push({
        date: tx.date,
        invested: invested,
        value: cash + stockValue
    });
  });

  // Add "Now" point with current market prices
  let currentStockValue = 0;
  Object.keys(holdings).forEach(symbol => {
      const h = holdings[symbol];
      // Use current price from app state if available, else last known transaction price
      const price = currentPrices[symbol] || h.lastPrice; 
      currentStockValue += h.shares * price;
  });

  points.push({
      date: 'Now',
      invested: invested,
      value: cash + currentStockValue
  });

  return points;
};

// Simple CAGR calculation
export const calculateCAGR = (startValue: number, endValue: number, years: number) => {
  if (startValue <= 0 || years <= 0) return 0;
  return (Math.pow(endValue / startValue, 1 / years) - 1) * 100;
};

// --- NEW HELPERS ---

export const getYearlyDividends = (transactions: Transaction[]) => {
  const divs = transactions.filter(t => t.type === TransactionType.DIVIDEND);
  const grouped: Record<string, number> = {}; // "YYYY" -> amount

  divs.forEach(t => {
    const year = t.date.substring(0, 4);
    grouped[year] = (grouped[year] || 0) + (t.price || 0);
  });

  return Object.entries(grouped)
    .map(([year, value]) => ({ year, value }))
    .sort((a, b) => a.year.localeCompare(b.year));
};

export const getMonthlyDividends = (transactions: Transaction[]) => {
  const divs = transactions.filter(t => t.type === TransactionType.DIVIDEND);
  const grouped: Record<string, number> = {}; // "YYYY-MM" -> amount

  divs.forEach(t => {
    const date = t.date.substring(0, 7); // YYYY-MM
    grouped[date] = (grouped[date] || 0) + (t.price || 0);
  });

  // Return last 12 months or all? Let's return all for chart
  return Object.entries(grouped)
    .map(([date, value]) => ({ date, value }))
    .sort((a, b) => a.date.localeCompare(b.date));
};

export const calculateFundingStats = (transactions: Transaction[]) => {
  const fundingTxs = transactions.filter(t => t.type === TransactionType.DEPOSIT || t.type === TransactionType.WITHDRAW);

  let netFundingUSD = 0;
  let netFundingLocal = 0;
  let totalDepositsUSD = 0;
  let totalDepositsLocal = 0;

  fundingTxs.forEach(tx => {
    const amount = tx.price || 0;
    const rate = tx.exchangeRate || 1; // Default to 1 if no rate (assuming base currency)

    if (tx.type === TransactionType.DEPOSIT) {
      netFundingUSD += amount;
      netFundingLocal += amount * rate;
      totalDepositsUSD += amount;
      totalDepositsLocal += amount * rate;
    } else {
      netFundingUSD -= amount;
      netFundingLocal -= amount * rate;
    }
  });

  const avgFxCost = totalDepositsUSD > 0 ? totalDepositsLocal / totalDepositsUSD : 0;

  return { netFundingUSD, netFundingLocal, avgFxCost, fundingTxs };
};

import React, { useState, useEffect, useMemo } from 'react';
import Layout from './components/Layout';
import Dashboard from './components/Dashboard';
import Holdings from './components/Holdings';
import Reports from './components/Reports';
import { Transaction, TransactionType, AssetClass } from './types';
import { calculateHoldings, calculatePortfolioHistory, generateId } from './utils';
import { X, Save } from 'lucide-react';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState('dashboard');
  const [isAddModalOpen, setIsAddModalOpen] = useState(false);

  // --- STATE ---
  const [transactions, setTransactions] = useState<Transaction[]>(() => {
    const saved = localStorage.getItem('transactions');
    return saved ? JSON.parse(saved) : [];
  });

  const [prices, setPrices] = useState<Record<string, number>>(() => {
    const saved = localStorage.getItem('prices');
    return saved ? JSON.parse(saved) : {};
  });

  const [financialGoal, setFinancialGoal] = useState<number>(() => {
    const saved = localStorage.getItem('financialGoal');
    return saved ? parseFloat(saved) : 100000;
  });

  // --- PERSISTENCE ---
  useEffect(() => {
    localStorage.setItem('transactions', JSON.stringify(transactions));
  }, [transactions]);

  useEffect(() => {
    localStorage.setItem('prices', JSON.stringify(prices));
  }, [prices]);

  useEffect(() => {
    localStorage.setItem('financialGoal', financialGoal.toString());
  }, [financialGoal]);

  // --- CALCULATIONS ---
  const holdings = useMemo(() => calculateHoldings(transactions, prices), [transactions, prices]);
  const chartData = useMemo(() => calculatePortfolioHistory(transactions, prices), [transactions, prices]);

  const investedAmount = transactions.reduce((sum, t) => {
    if (t.type === TransactionType.DEPOSIT) return sum + (t.price || 0);
    if (t.type === TransactionType.WITHDRAW) return sum - (t.price || 0);
    return sum;
  }, 0);

  const cashBalance = useMemo(() => {
    let balance = 0;
    transactions.forEach(t => {
      // Logic: 
      // Deposit/Withdraw: price is the total amount.
      // Buy/Sell: price is per share.

      if (t.type === TransactionType.DEPOSIT) balance += (t.price || 0);
      if (t.type === TransactionType.WITHDRAW) balance -= (t.price || 0);
      if (t.type === TransactionType.BUY) balance -= (t.price! * t.shares!) + (t.fee || 0);
      if (t.type === TransactionType.SELL) balance += (t.price! * t.shares!) - (t.fee || 0);
      if (t.type === TransactionType.DIVIDEND) balance += (t.price || 0);
    });
    return balance;
  }, [transactions]);

  const portfolioValue = holdings.reduce((sum, h) => sum + h.marketValue, 0);

  // --- HANDLERS ---
  const handleAddTransaction = (newTx: Transaction) => {
    setTransactions(prev => [...prev, newTx]);
    // If it's a Buy, we might want to update the latest price if provided
    if ((newTx.type === TransactionType.BUY || newTx.type === TransactionType.SELL) && newTx.symbol && newTx.price) {
        setPrices(prev => ({...prev, [newTx.symbol!]: newTx.price!}));
    }
    setIsAddModalOpen(false);
  };

  const handleUpdatePrice = (symbol: string, newPrice: number) => {
    setPrices(prev => ({ ...prev, [symbol]: newPrice }));
  };

  // --- RENDER ---
  return (
    <Layout 
      activeTab={activeTab} 
      setActiveTab={setActiveTab} 
      onOpenAddModal={() => setIsAddModalOpen(true)}
    >
      {activeTab === 'dashboard' && (
        <Dashboard 
          holdings={holdings} 
          transactions={transactions} 
          financialGoal={financialGoal}
          setFinancialGoal={setFinancialGoal}
          investedAmount={investedAmount}
          cashBalance={cashBalance}
          portfolioValue={portfolioValue}
          chartData={chartData}
        />
      )}
      {activeTab === 'holdings' && (
        <Holdings holdings={holdings} onUpdatePrice={handleUpdatePrice} />
      )}
      {activeTab === 'history' && (
        <div className="bg-white dark:bg-slate-800 rounded-2xl shadow-sm border border-gray-100 dark:border-slate-700 overflow-hidden">
          <div className="p-6 border-b border-gray-100 dark:border-slate-700">
             <h2 className="text-xl font-bold text-gray-900 dark:text-white">Transaction History</h2>
          </div>
          <div className="overflow-x-auto">
            <table className="w-full text-left text-sm">
              <thead className="bg-gray-50 dark:bg-slate-700/50 text-gray-500 dark:text-gray-400">
                <tr>
                  <th className="px-6 py-4 font-medium">Date</th>
                  <th className="px-6 py-4 font-medium">Type</th>
                  <th className="px-6 py-4 font-medium">Asset</th>
                  <th className="px-6 py-4 font-medium text-right">Amount/Shares</th>
                  <th className="px-6 py-4 font-medium text-right">Price</th>
                  <th className="px-6 py-4 font-medium text-right">Total</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-gray-100 dark:divide-slate-700">
                {[...transactions].sort((a,b) => new Date(b.date).getTime() - new Date(a.date).getTime()).map(tx => (
                  <tr key={tx.id} className="hover:bg-gray-50 dark:hover:bg-slate-700/50 transition-colors">
                    <td className="px-6 py-4 text-gray-600 dark:text-gray-300">{tx.date}</td>
                    <td className="px-6 py-4">
                      <span className={`px-2 py-1 rounded text-xs font-semibold 
                        ${tx.type === 'BUY' ? 'bg-blue-100 text-blue-700 dark:bg-blue-900/30 dark:text-blue-300' : 
                          tx.type === 'SELL' ? 'bg-red-100 text-red-700 dark:bg-red-900/30 dark:text-red-300' :
                          tx.type === 'DIVIDEND' ? 'bg-green-100 text-green-700 dark:bg-green-900/30 dark:text-green-300' :
                          'bg-gray-100 text-gray-700 dark:bg-gray-700 dark:text-gray-300'
                        }`}>
                        {tx.type}
                      </span>
                    </td>
                    <td className="px-6 py-4 font-medium text-gray-900 dark:text-white">{tx.symbol || '-'}</td>
                    <td className="px-6 py-4 text-right text-gray-600 dark:text-gray-300">
                      {tx.shares ? tx.shares : '-'}
                    </td>
                    <td className="px-6 py-4 text-right text-gray-600 dark:text-gray-300">
                       {tx.price ? new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD' }).format(tx.price) : '-'}
                    </td>
                    <td className="px-6 py-4 text-right font-medium text-gray-900 dark:text-white">
                      {new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD' }).format(
                        (tx.type === 'BUY' || tx.type === 'SELL') 
                          ? (tx.price! * tx.shares!) 
                          : tx.price!
                      )}
                    </td>
                  </tr>
                ))}
                {transactions.length === 0 && (
                  <tr><td colSpan={6} className="px-6 py-8 text-center text-gray-400">No transactions recorded yet.</td></tr>
                )}
              </tbody>
            </table>
          </div>
        </div>
      )}
      {activeTab === 'reports' && (
         <Reports transactions={transactions} currentPortfolioValue={portfolioValue + cashBalance} />
      )}

      {/* ADD TRANSACTION MODAL */}
      {isAddModalOpen && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 backdrop-blur-sm p-4">
          <div className="bg-white dark:bg-slate-800 rounded-2xl shadow-2xl w-full max-w-lg overflow-hidden animate-in fade-in zoom-in-95 duration-200">
            <AddTransactionForm onClose={() => setIsAddModalOpen(false)} onSave={handleAddTransaction} />
          </div>
        </div>
      )}
    </Layout>
  );
};

