           <span className="text-sm text-gray-600 dark:text-gray-400">Current FX Rate (Local/USD):</span>
           <input 
             type="number" 
             value={currentFxRate}
             onChange={(e) => setCurrentFxRate(parseFloat(e.target.value) || 0)}
             className="w-24 px-3 py-1.5 rounded-lg border border-gray-300 dark:border-slate-600 bg-white dark:bg-slate-900 text-right font-medium"
           />
         </div>
       </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
        <div className="bg-white dark:bg-slate-800 p-6 rounded-2xl shadow-sm border border-gray-100 dark:border-slate-700">
          <p className="text-sm text-gray-500 dark:text-gray-400">Net Funding (USD)</p>
          <h3 className="text-2xl font-bold text-gray-900 dark:text-white mt-1">{formatCurrency(netFundingUSD)}</h3>
        </div>
        <div className="bg-white dark:bg-slate-800 p-6 rounded-2xl shadow-sm border border-gray-100 dark:border-slate-700">
          <p className="text-sm text-gray-500 dark:text-gray-400">Net Funding (Local)</p>
          <h3 className="text-2xl font-bold text-gray-900 dark:text-white mt-1">
             {formatNumber(netFundingLocal, 0)} <span className="text-xs text-gray-400 font-normal">THB</span>
          </h3>
        </div>
         <div className="bg-white dark:bg-slate-800 p-6 rounded-2xl shadow-sm border border-gray-100 dark:border-slate-700">
          <p className="text-sm text-gray-500 dark:text-gray-400">Avg FX Cost</p>
          <h3 className="text-2xl font-bold text-orange-500 mt-1">{formatNumber(avgFxCost, 2)}</h3>
        </div>
        <div className="bg-white dark:bg-slate-800 p-6 rounded-2xl shadow-sm border border-gray-100 dark:border-slate-700">
          <p className="text-sm text-gray-500 dark:text-gray-400">FX Gain on Principal</p>
          <div className="flex items-center mt-1">
             <h3 className={`text-2xl font-bold ${fxGainOnPrincipal >= 0 ? 'text-success' : 'text-danger'}`}>
               {fxGainOnPrincipal >= 0 ? '+' : ''}{formatNumber(fxGainOnPrincipal, 0)} 
             </h3>
             <span className="text-xs text-gray-400 ml-2">THB</span>
          </div>
        </div>
      </div>

       {/* Funding History */}
      <div className="bg-white dark:bg-slate-800 rounded-2xl shadow-sm border border-gray-100 dark:border-slate-700 overflow-hidden">
