                </tr>
              ))}
               {fundingTxs.length === 0 && (
                <tr><td colSpan={5} className="px-6 py-8 text-center text-gray-400">No deposits or withdrawals recorded.</td></tr>
              )}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

const GrowthView: React.FC<{ transactions: Transaction[], currentPortfolioValue: number, chartData: ChartDataPoint[] }> = ({ transactions, currentPortfolioValue, chartData }) => {
   const { netFundingUSD } = useMemo(() => calculateFundingStats(transactions), [transactions]);
   const gap = currentPortfolioValue - netFundingUSD;
   const gapPercent = netFundingUSD > 0 ? (gap / netFundingUSD) * 100 : 0;

   // Estimate Time in Market (Days between first transaction and now)
   const firstTxDate = useMemo(() => {
       if(transactions.length === 0) return null;
       const sorted = [...transactions].sort((a, b) => new Date(a.date).getTime() - new Date(b.date).getTime());
       return new Date(sorted[0].date);
   }, [transactions]);

   const daysInMarket = useMemo(() => {
       if(!firstTxDate) return 0;
       const diffTime = Math.abs(new Date().getTime() - firstTxDate.getTime());
       return Math.ceil(diffTime / (1000 * 60 * 60 * 24)); 
   }, [firstTxDate]);

   return (
      <div className="space-y-6 animate-in fade-in slide-in-from-bottom-4 duration-300">
         <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
             <div className="bg-white dark:bg-slate-800 p-6 rounded-2xl shadow-sm border border-gray-100 dark:border-slate-700">
                <p className="text-sm text-gray-500 dark:text-gray-400">Gap Spread (Value - Cost)</p>
                <h3 className={`text-2xl font-bold mt-1 ${gap >= 0 ? 'text-success' : 'text-danger'}`}>
                   {gap >= 0 ? '+' : ''}{formatCurrency(gap)}
                </h3>
                <p className={`text-sm ${gap >= 0 ? 'text-success' : 'text-danger'}`}>{gapPercent.toFixed(2)}% All Time Return</p>
             </div>

             <div className="bg-white dark:bg-slate-800 p-6 rounded-2xl shadow-sm border border-gray-100 dark:border-slate-700">
                <p className="text-sm text-gray-500 dark:text-gray-400">Time in Market</p>
                <h3 className="text-2xl font-bold text-gray-900 dark:text-white mt-1">
                   {daysInMarket} <span className="text-sm font-normal text-gray-400">Days</span>
                </h3>
                <p className="text-xs text-gray-400">Since {firstTxDate?.toLocaleDateString() || '-'}</p>
             </div>

             <div className="bg-white dark:bg-slate-800 p-6 rounded-2xl shadow-sm border border-gray-100 dark:border-slate-700">
                <p className="text-sm text-gray-500 dark:text-gray-400">Invested Capital</p>
                <h3 className="text-2xl font-bold text-gray-900 dark:text-white mt-1">
                   {formatCurrency(netFundingUSD)}
                </h3>
             </div>
         </div>

         {/* Full Wealth Growth Chart */}
         <div className="bg-white dark:bg-slate-800 p-6 rounded-2xl shadow-sm border border-gray-100 dark:border-slate-700">
          <div className="flex justify-between items-center mb-6">
              <h3 className="text-lg font-bold text-gray-900 dark:text-white">Wealth Growth Curve</h3>
              <div className="flex items-center space-x-2 text-sm text-gray-500">
                  <div className="flex items-center"><div className="w-3 h-3 bg-blue-500 rounded-full mr-1"></div> Value</div>
                  <div className="flex items-center"><div className="w-3 h-3 bg-slate-400 rounded-full mr-1 opacity-50"></div> Cost</div>
              </div>
          </div>
          <div className="h-[400px] w-full">
            {chartData.length > 0 ? (
              <ResponsiveContainer width="100%" height="100%">
              <AreaChart data={chartData}>
                <defs>
                  <linearGradient id="colorValueGrowth" x1="0" y1="0" x2="0" y2="1">
                    <stop offset="5%" stopColor="#3b82f6" stopOpacity={0.3}/>
                    <stop offset="95%" stopColor="#3b82f6" stopOpacity={0}/>
                  </linearGradient>
                </defs>
                <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" opacity={0.5} vertical={false} />
                <XAxis dataKey="date" axisLine={false} tickLine={false} tick={{fill: '#94a3b8', fontSize: 12}} dy={10} minTickGap={50} />
                <YAxis axisLine={false} tickLine={false} tick={{fill: '#94a3b8', fontSize: 12}} tickFormatter={(val) => `$${val >= 1000 ? (val/1000).toFixed(0) + 'k' : val}`} />
                <Tooltip 
                  contentStyle={{ backgroundColor: '#1e293b', border: 'none', borderRadius: '8px', color: '#fff' }}
                  itemStyle={{ color: '#fff' }}
                  formatter={(value: number) => formatCurrency(value)}
                  labelFormatter={(label) => `Date: ${label}`}
                />
                <Area type="monotone" dataKey="value" stroke="#3b82f6" strokeWidth={3} fillOpacity={1} fill="url(#colorValueGrowth)" name="Market Value" />
                <Area type="monotone" dataKey="invested" stroke="#94a3b8" strokeDasharray="5 5" strokeWidth={2} fill="transparent" name="Net Invested" />
              </AreaChart>
            </ResponsiveContainer>
            ) : (
              <div className="flex h-full items-center justify-center text-gray-400">
                No transaction data available for chart.
              </div>
            )}
          </div>
        </div>
      </div>
   );
};

export default Reports;

import React, { useState, useEffect, useMemo } from 'react';
import Layout from './components/Layout';
import Dashboard from './components/Dashboard';
import Holdings from './components/Holdings';
import Reports from './components/Reports';
import { Transaction, TransactionType, AssetClass } from './types';
import { calculateHoldings, calculatePortfolioHistory, generateId } from './utils';
import { X, Save } from 'lucide-react';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState('dashboard');
  const [isAddModalOpen, setIsAddModalOpen] = useState(false);

  // --- STATE ---
  const [transactions, setTransactions] = useState<Transaction[]>(() => {
    const saved = localStorage.getItem('transactions');
    return saved ? JSON.parse(saved) : [];
  });

  const [prices, setPrices] = useState<Record<string, number>>(() => {
    const saved = localStorage.getItem('prices');
    return saved ? JSON.parse(saved) : {};
  });

  const [financialGoal, setFinancialGoal] = useState<number>(() => {
    const saved = localStorage.getItem('financialGoal');
    return saved ? parseFloat(saved) : 100000;
  });

  // --- PERSISTENCE ---
  useEffect(() => {
    localStorage.setItem('transactions', JSON.stringify(transactions));
  }, [transactions]);

  useEffect(() => {
    localStorage.setItem('prices', JSON.stringify(prices));
  }, [prices]);

  useEffect(() => {
    localStorage.setItem('financialGoal', financialGoal.toString());
  }, [financialGoal]);

  // --- CALCULATIONS ---
  const holdings = useMemo(() => calculateHoldings(transactions, prices), [transactions, prices]);
  const chartData = useMemo(() => calculatePortfolioHistory(transactions, prices), [transactions, prices]);

  const investedAmount = transactions.reduce((sum, t) => {
    if (t.type === TransactionType.DEPOSIT) return sum + (t.price || 0);
    if (t.type === TransactionType.WITHDRAW) return sum - (t.price || 0);
    return sum;
  }, 0);

  const cashBalance = useMemo(() => {
    let balance = 0;
    transactions.forEach(t => {
      // Logic: 
      // Deposit/Withdraw: price is the total amount.
      // Buy/Sell: price is per share.

      if (t.type === TransactionType.DEPOSIT) balance += (t.price || 0);
      if (t.type === TransactionType.WITHDRAW) balance -= (t.price || 0);
      if (t.type === TransactionType.BUY) balance -= (t.price! * t.shares!) + (t.fee || 0);
      if (t.type === TransactionType.SELL) balance += (t.price! * t.shares!) - (t.fee || 0);
      if (t.type === TransactionType.DIVIDEND) balance += (t.price || 0);
    });
    return balance;
  }, [transactions]);

  const portfolioValue = holdings.reduce((sum, h) => sum + h.marketValue, 0);

  // --- HANDLERS ---
  const handleAddTransaction = (newTx: Transaction) => {
    setTransactions(prev => [...prev, newTx]);
    // If it's a Buy, we might want to update the latest price if provided
    if ((newTx.type === TransactionType.BUY || newTx.type === TransactionType.SELL) && newTx.symbol && newTx.price) {
        setPrices(prev => ({...prev, [newTx.symbol!]: newTx.price!}));
    }
    setIsAddModalOpen(false);
  };

  const handleUpdatePrice = (symbol: string, newPrice: number) => {
    setPrices(prev => ({ ...prev, [symbol]: newPrice }));
  };

  // --- RENDER ---
  return (
    <Layout 
      activeTab={activeTab} 
      setActiveTab={setActiveTab} 
      onOpenAddModal={() => setIsAddModalOpen(true)}
    >
      {activeTab === 'dashboard' && (
        <Dashboard 
          holdings={holdings} 
          transactions={transactions} 
          financialGoal={financialGoal}
          setFinancialGoal={setFinancialGoal}
          investedAmount={investedAmount}
          cashBalance={cashBalance}
          portfolioValue={portfolioValue}
          chartData={chartData}
        />
      )}
      {activeTab === 'holdings' && (
        <Holdings holdings={holdings} onUpdatePrice={handleUpdatePrice} />
      )}
      {activeTab === 'history' && (
        <div className="bg-white dark:bg-slate-800 rounded-2xl shadow-sm border border-gray-100 dark:border-slate-700 overflow-hidden">
          <div className="p-6 border-b border-gray-100 dark:border-slate-700">
             <h2 className="text-xl font-bold text-gray-900 dark:text-white">Transaction History</h2>
          </div>
          <div className="overflow-x-auto">
            <table className="w-full text-left text-sm">
              <thead className="bg-gray-50 dark:bg-slate-700/50 text-gray-500 dark:text-gray-400">
                <tr>
                  <th className="px-6 py-4 font-medium">Date</th>
                  <th className="px-6 py-4 font-medium">Type</th>
                  <th className="px-6 py-4 font-medium">Asset</th>
                  <th className="px-6 py-4 font-medium text-right">Amount/Shares</th>
                  <th className="px-6 py-4 font-medium text-right">Price</th>
                  <th className="px-6 py-4 font-medium text-right">Total</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-gray-100 dark:divide-slate-700">
                {[...transactions].sort((a,b) => new Date(b.date).getTime() - new Date(a.date).getTime()).map(tx => (
                  <tr key={tx.id} className="hover:bg-gray-50 dark:hover:bg-slate-700/50 transition-colors">
                    <td className="px-6 py-4 text-gray-600 dark:text-gray-300">{tx.date}</td>
                    <td className="px-6 py-4">
                      <span className={`px-2 py-1 rounded text-xs font-semibold 
                        ${tx.type === 'BUY' ? 'bg-blue-100 text-blue-700 dark:bg-blue-900/30 dark:text-blue-300' : 
                          tx.type === 'SELL' ? 'bg-red-100 text-red-700 dark:bg-red-900/30 dark:text-red-300' :
                          tx.type === 'DIVIDEND' ? 'bg-green-100 text-green-700 dark:bg-green-900/30 dark:text-green-300' :
                          'bg-gray-100 text-gray-700 dark:bg-gray-700 dark:text-gray-300'
                        }`}>
                        {tx.type}
                      </span>
                    </td>
                    <td className="px-6 py-4 font-medium text-gray-900 dark:text-white">{tx.symbol || '-'}</td>
                    <td className="px-6 py-4 text-right text-gray-600 dark:text-gray-300">
                      {tx.shares ? tx.shares : '-'}
                    </td>
                    <td className="px-6 py-4 text-right text-gray-600 dark:text-gray-300">
                       {tx.price ? new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD' }).format(tx.price) : '-'}
                    </td>
                    <td className="px-6 py-4 text-right font-medium text-gray-900 dark:text-white">
                      {new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD' }).format(
                        (tx.type === 'BUY' || tx.type === 'SELL') 
                          ? (tx.price! * tx.shares!) 
                          : tx.price!
                      )}
                    </td>
                  </tr>
                ))}
                {transactions.length === 0 && (
                  <tr><td colSpan={6} className="px-6 py-8 text-center text-gray-400">No transactions recorded yet.</td></tr>
                )}
              </tbody>
            </table>
          </div>
        </div>
      )}
      {activeTab === 'reports' && (
         <Reports transactions={transactions} currentPortfolioValue={portfolioValue + cashBalance} chartData={chartData} />
      )}

      {/* ADD TRANSACTION MODAL */}
      {isAddModalOpen && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 backdrop-blur-sm p-4">
          <div className="bg-white dark:bg-slate-800 rounded-2xl shadow-2xl w-full max-w-lg overflow-hidden animate-in fade-in zoom-in-95 duration-200">
            <AddTransactionForm onClose={() => setIsAddModalOpen(false)} onSave={handleAddTransaction} />
          </div>
        </div>
      )}
    </Layout>
  );
};

// Sub-component for form to keep App clean
const AddTransactionForm: React.FC<{ onClose: () => void, onSave: (t: Transaction) => void }> = ({ onClose, onSave }) => {
  const [type, setType] = useState<TransactionType>(TransactionType.BUY);
  const [date, setDate] = useState(new Date().toISOString().split('T')[0]);
  const [symbol, setSymbol] = useState('');
  const [shares, setShares] = useState('');
  const [price, setPrice] = useState('');
  const [assetClass, setAssetClass] = useState<AssetClass>(AssetClass.STOCK);
  const [exchangeRate, setExchangeRate] = useState(''); // New State

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    onSave({
      id: generateId(),
      date,
      type,
      symbol: (type === 'DEPOSIT' || type === 'WITHDRAW') ? undefined : symbol.toUpperCase(),
      shares: shares ? parseFloat(shares) : undefined,
      price: parseFloat(price),
      assetClass: (type === 'DEPOSIT' || type === 'WITHDRAW') ? AssetClass.CASH : assetClass,
      exchangeRate: exchangeRate ? parseFloat(exchangeRate) : 1, // Save Exchange Rate
    });
  };

  const isTrade = type === TransactionType.BUY || type === TransactionType.SELL || type === TransactionType.DIVIDEND;
  const isFunding = type === TransactionType.DEPOSIT || type === TransactionType.WITHDRAW;

  return (
    <div className="flex flex-col max-h-[90vh]">
      <div className="flex justify-between items-center p-6 border-b border-gray-100 dark:border-slate-700">
        <h3 className="text-lg font-bold text-gray-900 dark:text-white">Add Transaction</h3>
        <button onClick={onClose} className="text-gray-400 hover:text-gray-600 dark:hover:text-gray-200">
          <X size={24} />
        </button>
      </div>

      <form onSubmit={handleSubmit} className="p-6 space-y-4 overflow-y-auto">
        <div className="grid grid-cols-2 gap-4">
          <div>
            <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">Type</label>
            <select 
              value={type} 
              onChange={(e) => setType(e.target.value as TransactionType)}
              className="w-full bg-gray-50 dark:bg-slate-900 border border-gray-200 dark:border-slate-700 rounded-lg px-3 py-2 text-gray-900 dark:text-white focus:ring-2 focus:ring-blue-500 outline-none"
            >
              {Object.values(TransactionType).map(t => <option key={t} value={t}>{t}</option>)}
            </select>
          </div>
          <div>
             <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">Date</label>
             <input 
              type="date" 
              required
              value={date}
              onChange={(e) => setDate(e.target.value)}
              className="w-full bg-gray-50 dark:bg-slate-900 border border-gray-200 dark:border-slate-700 rounded-lg px-3 py-2 text-gray-900 dark:text-white focus:ring-2 focus:ring-blue-500 outline-none"
            />
          </div>
        </div>

        {isTrade && (
          <div className="grid grid-cols-2 gap-4">
            <div className="col-span-1">
               <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">Symbol</label>
               <input 
                type="text" 
                required
                placeholder="e.g. AAPL"
                value={symbol}
                onChange={(e) => setSymbol(e.target.value)}
                className="w-full bg-gray-50 dark:bg-slate-900 border border-gray-200 dark:border-slate-700 rounded-lg px-3 py-2 text-gray-900 dark:text-white focus:ring-2 focus:ring-blue-500 outline-none uppercase"
              />
            </div>
             <div className="col-span-1">
              <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">Asset Class</label>
              <select 
                value={assetClass} 
                onChange={(e) => setAssetClass(e.target.value as AssetClass)}
                className="w-full bg-gray-50 dark:bg-slate-900 border border-gray-200 dark:border-slate-700 rounded-lg px-3 py-2 text-gray-900 dark:text-white focus:ring-2 focus:ring-blue-500 outline-none"
              >
                {Object.values(AssetClass).filter(a => a !== AssetClass.CASH).map(a => <option key={a} value={a}>{a}</option>)}
              </select>
            </div>
          </div>
        )}

        <div className="grid grid-cols-2 gap-4">
           {isTrade && (
            <div>
              <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">Shares/Units</label>
              <input 
                type="number" 
                step="any"
                required
                placeholder="0.00"
                value={shares}
                onChange={(e) => setShares(e.target.value)}
                className="w-full bg-gray-50 dark:bg-slate-900 border border-gray-200 dark:border-slate-700 rounded-lg px-3 py-2 text-gray-900 dark:text-white focus:ring-2 focus:ring-blue-500 outline-none"
              />
            </div>
           )}
           <div className={!isTrade ? "col-span-2" : ""}>
             <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
               {isTrade ? "Price per Share" : "Amount (USD)"}
             </label>
              <input 
                type="number" 
                step="any"
                required
                placeholder="0.00"
                value={price}
                onChange={(e) => setPrice(e.target.value)}
                className="w-full bg-gray-50 dark:bg-slate-900 border border-gray-200 dark:border-slate-700 rounded-lg px-3 py-2 text-gray-900 dark:text-white focus:ring-2 focus:ring-blue-500 outline-none"
              />
           </div>
        </div>

        {isFunding && (
           <div>
             <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
               Exchange Rate (Local/USD)
             </label>
              <input 
                type="number" 
                step="any"
                placeholder="e.g. 35.00"
                value={exchangeRate}
                onChange={(e) => setExchangeRate(e.target.value)}
                className="w-full bg-gray-50 dark:bg-slate-900 border border-gray-200 dark:border-slate-700 rounded-lg px-3 py-2 text-gray-900 dark:text-white focus:ring-2 focus:ring-blue-500 outline-none"
              />
               <p className="text-xs text-gray-400 mt-1">Leave blank if using base currency (1.0)</p>
           </div>
        )}

        <button 
          type="submit" 
          className="w-full mt-6 bg-blue-600 hover:bg-blue-700 text-white font-semibold py-3 rounded-lg shadow-lg shadow-blue-500/30 transition-all active:scale-95 flex items-center justify-center space-x-2"
        >
          <Save size={18} />
          <span>Save Transaction</span>
        </button>
      </form>
    </div>
  );
};

export default App;

