import { Transaction, TransactionType, AssetClass } from './types';
import { calculateHoldings, calculatePortfolioHistory, generateId } from './utils';
import { X, Save, TrendingUp, TrendingDown, DollarSign, Wallet, Calendar } from 'lucide-react';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState('dashboard');
  const [isAddModalOpen, setIsAddModalOpen] = useState(false);

  // --- STATE ---
  const [transactions, setTransactions] = useState<Transaction[]>(() => {
    const saved = localStorage.getItem('transactions');
    return saved ? JSON.parse(saved) : [];
  });

  const [prices, setPrices] = useState<Record<string, number>>(() => {
    const saved = localStorage.getItem('prices');
    return saved ? JSON.parse(saved) : {};
  });

  const [financialGoal, setFinancialGoal] = useState<number>(() => {
    const saved = localStorage.getItem('financialGoal');
    return saved ? parseFloat(saved) : 100000;
  });

  // --- PERSISTENCE ---
  useEffect(() => {
    localStorage.setItem('transactions', JSON.stringify(transactions));
  }, [transactions]);

  useEffect(() => {
    localStorage.setItem('prices', JSON.stringify(prices));
  }, [prices]);

  useEffect(() => {
    localStorage.setItem('financialGoal', financialGoal.toString());
  }, [financialGoal]);

  // --- CALCULATIONS ---
  const holdings = useMemo(() => calculateHoldings(transactions, prices), [transactions, prices]);
  const chartData = useMemo(() => calculatePortfolioHistory(transactions, prices), [transactions, prices]);

  const investedAmount = transactions.reduce((sum, t) => {
    if (t.type === TransactionType.DEPOSIT) return sum + (t.price || 0);
    if (t.type === TransactionType.WITHDRAW) return sum - (t.price || 0);
    return sum;
  }, 0);

  const cashBalance = useMemo(() => {
    let balance = 0;
    transactions.forEach(t => {
      if (t.type === TransactionType.DEPOSIT) balance += (t.price || 0);
      if (t.type === TransactionType.WITHDRAW) balance -= (t.price || 0);
      if (t.type === TransactionType.BUY) balance -= (t.price! * t.shares!) + (t.fee || 0);
      if (t.type === TransactionType.SELL) balance += (t.price! * t.shares!) - (t.fee || 0);
      if (t.type === TransactionType.DIVIDEND) balance += (t.price || 0);
    });
    return balance;
  }, [transactions]);

  const portfolioValue = holdings.reduce((sum, h) => sum + h.marketValue, 0);

  // --- HANDLERS ---
  const handleAddTransaction = (newTx: Transaction) => {
    setTransactions(prev => [...prev, newTx]);
    if ((newTx.type === TransactionType.BUY || newTx.type === TransactionType.SELL) && newTx.symbol && newTx.price) {
        setPrices(prev => ({...prev, [newTx.symbol!]: newTx.price!}));
    }
    setIsAddModalOpen(false);
  };

  const handleUpdatePrice = (symbol: string, newPrice: number) => {
    setPrices(prev => ({ ...prev, [symbol]: newPrice }));
  };

  // --- RENDER ---
  return (
    <Layout 
      activeTab={activeTab} 
      setActiveTab={setActiveTab} 
      onOpenAddModal={() => setIsAddModalOpen(true)}
    >
      {activeTab === 'dashboard' && (
        <Dashboard 
          holdings={holdings} 
          transactions={transactions} 
          financialGoal={financialGoal}
          setFinancialGoal={setFinancialGoal}
          investedAmount={investedAmount}
          cashBalance={cashBalance}
          portfolioValue={portfolioValue}
          chartData={chartData}
        />
      )}
      {activeTab === 'holdings' && (
        <Holdings holdings={holdings} onUpdatePrice={handleUpdatePrice} />
      )}
      {activeTab === 'history' && (
        <div className="glass-card rounded-2xl overflow-hidden">
          <div className="p-6 border-b border-slate-100 dark:border-slate-800 flex justify-between items-center">
             <h2 className="text-xl font-display font-bold text-slate-900 dark:text-white">Transaction History</h2>
             <div className="text-sm text-slate-500">{transactions.length} records</div>
          </div>
          <div className="overflow-x-auto">
            <table className="w-full text-left text-sm">
              <thead className="bg-slate-50/80 dark:bg-slate-800/50 text-slate-500 dark:text-slate-400">
                <tr>
                  <th className="px-6 py-4 font-semibold">Date</th>
                  <th className="px-6 py-4 font-semibold">Type</th>
                  <th className="px-6 py-4 font-semibold">Asset</th>
                  <th className="px-6 py-4 font-semibold text-right">Shares</th>
                  <th className="px-6 py-4 font-semibold text-right">Price</th>
                  <th className="px-6 py-4 font-semibold text-right">Total Value</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-100 dark:divide-slate-800">
                {[...transactions].sort((a,b) => new Date(b.date).getTime() - new Date(a.date).getTime()).map(tx => (
                  <tr key={tx.id} className="hover:bg-slate-50 dark:hover:bg-slate-800/30 transition-colors group">
                    <td className="px-6 py-4 text-slate-600 dark:text-slate-300 whitespace-nowrap">{tx.date}</td>
                    <td className="px-6 py-4">
                      <span className={`inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-bold border ${
                        tx.type === 'BUY' ? 'bg-blue-50 text-blue-700 border-blue-200 dark:bg-blue-900/20 dark:text-blue-400 dark:border-blue-800' : 
                          tx.type === 'SELL' ? 'bg-rose-50 text-rose-700 border-rose-200 dark:bg-rose-900/20 dark:text-rose-400 dark:border-rose-800' :
                          tx.type === 'DIVIDEND' ? 'bg-emerald-50 text-emerald-700 border-emerald-200 dark:bg-emerald-900/20 dark:text-emerald-400 dark:border-emerald-800' :
                          'bg-slate-100 text-slate-700 border-slate-200 dark:bg-slate-800 dark:text-slate-300 dark:border-slate-700'
                        }`}>
                        {tx.type}
                      </span>
                    </td>
                    <td className="px-6 py-4 font-bold text-slate-900 dark:text-white">{tx.symbol || '-'}</td>
                    <td className="px-6 py-4 text-right text-slate-600 dark:text-slate-300 font-mono">
                      {tx.shares ? tx.shares : '-'}
                    </td>
                    <td className="px-6 py-4 text-right text-slate-600 dark:text-slate-300 font-mono">
                       {tx.price ? new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD' }).format(tx.price) : '-'}
                    </td>
                    <td className="px-6 py-4 text-right font-bold text-slate-900 dark:text-white font-mono">
                      {new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD' }).format(
                        (tx.type === 'BUY' || tx.type === 'SELL') 
                          ? (tx.price! * tx.shares!) 
                          : tx.price!
                      )}
                    </td>
                  </tr>
                ))}
                {transactions.length === 0 && (
                  <tr><td colSpan={6} className="px-6 py-12 text-center text-slate-400">No transactions recorded yet.</td></tr>
                )}
              </tbody>
            </table>
          </div>
        </div>
      )}
      {activeTab === 'reports' && (
         <Reports transactions={transactions} currentPortfolioValue={portfolioValue + cashBalance} chartData={chartData} />
      )}

      {/* ADD TRANSACTION MODAL */}
      {isAddModalOpen && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-sm" onClick={() => setIsAddModalOpen(false)}></div>
          <div className="relative bg-white dark:bg-slate-900 rounded-3xl shadow-2xl w-full max-w-lg overflow-hidden animate-slide-up border border-slate-200 dark:border-slate-800 max-h-[90vh] flex flex-col">
            <AddTransactionForm onClose={() => setIsAddModalOpen(false)} onSave={handleAddTransaction} />
          </div>
        </div>
      )}
    </Layout>
  );
};

const AddTransactionForm: React.FC<{ onClose: () => void, onSave: (t: Transaction) => void }> = ({ onClose, onSave }) => {
  const [type, setType] = useState<TransactionType>(TransactionType.BUY);
  const [date, setDate] = useState(new Date().toISOString().split('T')[0]);
  const [symbol, setSymbol] = useState('');
  const [shares, setShares] = useState('');
  const [price, setPrice] = useState('');
  const [assetClass, setAssetClass] = useState<AssetClass>(AssetClass.STOCK);
  const [exchangeRate, setExchangeRate] = useState(''); 

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    onSave({
      id: generateId(),
      date,
      type,
      symbol: (type === 'DEPOSIT' || type === 'WITHDRAW') ? undefined : symbol.toUpperCase(),
      shares: shares ? parseFloat(shares) : undefined,
      price: parseFloat(price),
      assetClass: (type === 'DEPOSIT' || type === 'WITHDRAW') ? AssetClass.CASH : assetClass,
      exchangeRate: exchangeRate ? parseFloat(exchangeRate) : 1, 
    });
  };

  const isTrade = type === TransactionType.BUY || type === TransactionType.SELL || type === TransactionType.DIVIDEND;
  const isFunding = type === TransactionType.DEPOSIT || type === TransactionType.WITHDRAW;

  return (
    <div className="flex flex-col h-full">
      <div className="flex justify-between items-center p-6 border-b border-slate-100 dark:border-slate-800 bg-slate-50/50 dark:bg-slate-900/50">
        <div>
          <h3 className="text-xl font-display font-bold text-slate-900 dark:text-white">New Transaction</h3>
          <p className="text-sm text-slate-500">Record your investment activity</p>
        </div>
        <button onClick={onClose} className="p-2 rounded-full hover:bg-slate-200 dark:hover:bg-slate-800 text-slate-400 hover:text-slate-600 dark:hover:text-slate-200 transition-colors">
          <X size={24} />
        </button>
      </div>

      <form onSubmit={handleSubmit} className="p-6 space-y-6 overflow-y-auto custom-scrollbar flex-1">

        {/* Transaction Type Selector (Chips) */}
        <div>
           <label className="block text-xs font-bold text-slate-500 uppercase tracking-wider mb-3">Transaction Type</label>
           <div className="grid grid-cols-3 sm:grid-cols-5 gap-2">
              {[
                { id: TransactionType.BUY, icon: <TrendingUp size={16} />, label: 'Buy', color: 'blue' },
                { id: TransactionType.SELL, icon: <TrendingDown size={16} />, label: 'Sell', color: 'rose' },
                { id: TransactionType.DIVIDEND, icon: <DollarSign size={16} />, label: 'Div', color: 'emerald' },
                { id: TransactionType.DEPOSIT, icon: <Wallet size={16} />, label: 'In', color: 'indigo' },
                { id: TransactionType.WITHDRAW, icon: <Wallet size={16} />, label: 'Out', color: 'orange' },
              ].map((t) => (
                <button
                  key={t.id}
                  type="button"
                  onClick={() => setType(t.id)}
                  className={`flex flex-col items-center justify-center p-2 rounded-xl border transition-all duration-200 ${
                    type === t.id
                      ? `bg-${t.color}-50 border-${t.color}-500 text-${t.color}-700 dark:bg-${t.color}-900/30 dark:border-${t.color}-500 dark:text-${t.color}-300 ring-1 ring-${t.color}-500`
                      : 'bg-white dark:bg-slate-800 border-slate-200 dark:border-slate-700 text-slate-500 hover:border-slate-300 dark:hover:border-slate-600'
                  }`}
                >
                  <div className="mb-1">{t.icon}</div>
                  <span className="text-xs font-bold">{t.label}</span>
                </button>
              ))}
           </div>
        </div>

        {/* Date Input */}
        <div>
           <label className="block text-xs font-bold text-slate-500 uppercase tracking-wider mb-2">Date</label>
           <div className="relative">
             <Calendar className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
             <input 
              type="date" 
              required
              value={date}
              onChange={(e) => setDate(e.target.value)}
              className="w-full pl-10 pr-4 py-3 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl text-slate-900 dark:text-white focus:ring-2 focus:ring-blue-500 focus:border-transparent outline-none transition-all font-medium"
            />
           </div>
        </div>

        {isTrade && (
          <div className="grid grid-cols-2 gap-4">
            <div className="col-span-1">
               <label className="block text-xs font-bold text-slate-500 uppercase tracking-wider mb-2">Symbol</label>
               <input 
                type="text" 
                required
                placeholder="e.g. AAPL"
                value={symbol}
                onChange={(e) => setSymbol(e.target.value)}
                className="w-full px-4 py-3 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl text-slate-900 dark:text-white focus:ring-2 focus:ring-blue-500 outline-none uppercase font-bold tracking-wide"
              />
            </div>
             <div className="col-span-1">
              <label className="block text-xs font-bold text-slate-500 uppercase tracking-wider mb-2">Class</label>
              <select 
                value={assetClass} 
                onChange={(e) => setAssetClass(e.target.value as AssetClass)}
                className="w-full px-4 py-3 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl text-slate-900 dark:text-white focus:ring-2 focus:ring-blue-500 outline-none appearance-none"
              >
                {Object.values(AssetClass).filter(a => a !== AssetClass.CASH).map(a => <option key={a} value={a}>{a}</option>)}
              </select>
            </div>
          </div>
        )}

        <div className="grid grid-cols-2 gap-4">
           {isTrade && (
            <div>
              <label className="block text-xs font-bold text-slate-500 uppercase tracking-wider mb-2">Shares</label>
              <input 
                type="number" 
                step="any"
                required
                placeholder="0.00"
                value={shares}
                onChange={(e) => setShares(e.target.value)}
                className="w-full px-4 py-3 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl text-slate-900 dark:text-white focus:ring-2 focus:ring-blue-500 outline-none font-mono"
              />
            </div>
           )}
           <div className={!isTrade ? "col-span-2" : ""}>
             <label className="block text-xs font-bold text-slate-500 uppercase tracking-wider mb-2">
               {isTrade ? "Price / Share" : "Amount ($)"}
             </label>
              <input 
                type="number" 
                step="any"
                required
                placeholder="0.00"
                value={price}
                onChange={(e) => setPrice(e.target.value)}
                className="w-full px-4 py-3 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl text-slate-900 dark:text-white focus:ring-2 focus:ring-blue-500 outline-none font-mono"
              />
           </div>
        </div>

        {isFunding && (
           <div className="bg-blue-50 dark:bg-slate-800/50 p-4 rounded-xl border border-blue-100 dark:border-slate-700">
             <label className="block text-xs font-bold text-slate-500 uppercase tracking-wider mb-2">
               Exchange Rate (Optional)
             </label>
              <div className="flex items-center space-x-2">
                <input 
                  type="number" 
                  step="any"
                  placeholder="1.00"
                  value={exchangeRate}
                  onChange={(e) => setExchangeRate(e.target.value)}
                  className="flex-1 px-4 py-2 bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-600 rounded-lg text-slate-900 dark:text-white focus:ring-2 focus:ring-blue-500 outline-none font-mono text-right"
                />
                <span className="text-sm font-medium text-slate-500">Local / USD</span>
              </div>
           </div>
        )}
      </form>

      <div className="p-6 border-t border-slate-100 dark:border-slate-800 bg-slate-50/50 dark:bg-slate-900/50">
        <button 
          onClick={handleSubmit}
          className="w-full bg-slate-900 dark:bg-blue-600 hover:opacity-90 text-white font-bold py-4 rounded-xl shadow-lg shadow-slate-900/20 dark:shadow-blue-600/20 transition-all active:scale-95 flex items-center justify-center space-x-2 text-lg"
        >
          <Save size={20} />
          <span>Save Transaction</span>
        </button>
      </div>
    </div>
  );
};

export default App;

import React, { useState, useMemo } from 'react';
import { Transaction, TransactionType, AssetClass } from '../types';
import { Search, Calendar, Filter, Trash2, ArrowUpDown, XCircle } from 'lucide-react';
import { formatCurrency } from '../utils';

interface HistoryProps {
  transactions: Transaction[];
  onDelete: (id: string) => void;
}

const History: React.FC<HistoryProps> = ({ transactions, onDelete }) => {
  // Filters State
  const [searchTerm, setSearchTerm] = useState('');
  const [typeFilter, setTypeFilter] = useState<TransactionType | 'ALL'>('ALL');
  const [assetClassFilter, setAssetClassFilter] = useState<AssetClass | 'ALL'>('ALL');
  const [startDate, setStartDate] = useState('');
  const [endDate, setEndDate] = useState('');
  const [sortOrder, setSortOrder] = useState<'desc' | 'asc'>('desc');

  // Logic
  const filteredTransactions = useMemo(() => {
    return transactions.filter(tx => {
      // 1. Search (Symbol, Notes)
      const searchLower = searchTerm.toLowerCase();
      const matchesSearch = 
        (tx.symbol?.toLowerCase().includes(searchLower) ?? false) ||
        (tx.notes?.toLowerCase().includes(searchLower) ?? false) ||
        (tx.type.toLowerCase().includes(searchLower));

      // 2. Type Filter
      const matchesType = typeFilter === 'ALL' || tx.type === typeFilter;

      // 3. Asset Class Filter
      const matchesAsset = assetClassFilter === 'ALL' || tx.assetClass === assetClassFilter;

      // 4. Date Range
      const txDate = new Date(tx.date).getTime();
      const start = startDate ? new Date(startDate).getTime() : -Infinity;
      const end = endDate ? new Date(endDate).getTime() : Infinity;
      const matchesDate = txDate >= start && txDate <= end;

      return matchesSearch && matchesType && matchesAsset && matchesDate;
    }).sort((a, b) => {
      const dateA = new Date(a.date).getTime();
      const dateB = new Date(b.date).getTime();
      return sortOrder === 'desc' ? dateB - dateA : dateA - dateB;
    });
  }, [transactions, searchTerm, typeFilter, assetClassFilter, startDate, endDate, sortOrder]);

  const resetFilters = () => {
    setSearchTerm('');
    setTypeFilter('ALL');
    setAssetClassFilter('ALL');
    setStartDate('');
    setEndDate('');
  };

  const hasActiveFilters = searchTerm || typeFilter !== 'ALL' || assetClassFilter !== 'ALL' || startDate || endDate;

  return (
    <div className="space-y-6">
      {/* Header & Controls */}
      <div className="flex flex-col gap-6">
        <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
           <div>
             <h2 className="text-2xl font-display font-bold text-slate-900 dark:text-white">History</h2>
             <p className="text-slate-500 dark:text-slate-400 text-sm">
               {filteredTransactions.length} transactions found
             </p>
           </div>

           {/* Search Bar */}
           <div className="relative w-full md:w-72">
             <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
             <input 
               type="text" 
               placeholder="Search symbol, notes..." 
               value={searchTerm}
               onChange={(e) => setSearchTerm(e.target.value)}
               className="w-full pl-10 pr-4 py-2.5 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none text-slate-900 dark:text-white shadow-sm"
             />
           </div>
        </div>

        {/* Filters Toolbar */}
        <div className="bg-white dark:bg-slate-800 p-4 rounded-2xl border border-slate-200 dark:border-slate-700 shadow-sm flex flex-col lg:flex-row gap-4">
           <div className="flex items-center text-slate-500 font-medium text-sm">
             <Filter size={16} className="mr-2" /> Filters:
           </div>

           <div className="grid grid-cols-2 md:grid-cols-4 lg:flex gap-3 flex-1">
              {/* Type Select */}
              <select 
                value={typeFilter} 
                onChange={(e) => setTypeFilter(e.target.value as any)}
                className="bg-slate-50 dark:bg-slate-900 border border-slate-200 dark:border-slate-700 text-slate-700 dark:text-slate-300 text-sm rounded-lg px-3 py-2 outline-none focus:ring-2 focus:ring-blue-500"
              >
                <option value="ALL">All Types</option>
                {Object.values(TransactionType).map(t => <option key={t} value={t}>{t}</option>)}
              </select>

              {/* Asset Select */}
              <select 
                value={assetClassFilter} 
                onChange={(e) => setAssetClassFilter(e.target.value as any)}
                className="bg-slate-50 dark:bg-slate-900 border border-slate-200 dark:border-slate-700 text-slate-700 dark:text-slate-300 text-sm rounded-lg px-3 py-2 outline-none focus:ring-2 focus:ring-blue-500"
              >
                <option value="ALL">All Assets</option>
                {Object.values(AssetClass).map(a => <option key={a} value={a}>{a}</option>)}
              </select>

              {/* Date Inputs */}
              <div className="relative">
                 <Calendar className="absolute left-2.5 top-1/2 -translate-y-1/2 text-slate-400 pointer-events-none" size={14} />
                 <input 
                    type="date" 
                    value={startDate}
                    onChange={(e) => setStartDate(e.target.value)}
                    className="w-full pl-8 pr-2 py-2 bg-slate-50 dark:bg-slate-900 border border-slate-200 dark:border-slate-700 text-slate-700 dark:text-slate-300 text-sm rounded-lg outline-none focus:ring-2 focus:ring-blue-500"
                    placeholder="Start Date"
                 />
              </div>
              <div className="relative">
                 <Calendar className="absolute left-2.5 top-1/2 -translate-y-1/2 text-slate-400 pointer-events-none" size={14} />
                 <input 
                    type="date" 
                    value={endDate}
                    onChange={(e) => setEndDate(e.target.value)}
                    className="w-full pl-8 pr-2 py-2 bg-slate-50 dark:bg-slate-900 border border-slate-200 dark:border-slate-700 text-slate-700 dark:text-slate-300 text-sm rounded-lg outline-none focus:ring-2 focus:ring-blue-500"
                 />
              </div>
           </div>

           {hasActiveFilters && (
             <button 
               onClick={resetFilters}
               className="flex items-center justify-center px-4 py-2 text-sm text-rose-500 hover:bg-rose-50 dark:hover:bg-rose-900/20 rounded-lg transition-colors font-medium whitespace-nowrap"
             >
               <XCircle size={16} className="mr-1.5" /> Clear
             </button>
           )}
        </div>
      </div>

      {/* Table */}
      <div className="glass-card rounded-2xl overflow-hidden min-h-[400px]">
        <div className="overflow-x-auto">
          <table className="w-full text-left text-sm">
            <thead className="bg-slate-50/80 dark:bg-slate-800/50 text-slate-500 dark:text-slate-400 border-b border-slate-100 dark:border-slate-700">
              <tr>
                <th className="px-6 py-4 font-semibold whitespace-nowrap">
                  <button onClick={() => setSortOrder(prev => prev === 'desc' ? 'asc' : 'desc')} className="flex items-center hover:text-slate-800 dark:hover:text-slate-200">
                     Date <ArrowUpDown size={14} className="ml-1" />
                  </button>
                </th>
                <th className="px-6 py-4 font-semibold">Type</th>
                <th className="px-6 py-4 font-semibold">Asset</th>
                <th className="px-6 py-4 font-semibold text-right">Shares</th>
                <th className="px-6 py-4 font-semibold text-right">Price</th>
                <th className="px-6 py-4 font-semibold text-right">Total</th>
                <th className="px-6 py-4 font-semibold text-right">Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100 dark:divide-slate-800">
              {filteredTransactions.map(tx => (
                <tr key={tx.id} className="hover:bg-slate-50 dark:hover:bg-slate-800/30 transition-colors group">
                  <td className="px-6 py-4 text-slate-600 dark:text-slate-300 whitespace-nowrap font-medium">{tx.date}</td>
                  <td className="px-6 py-4">
                    <span className={`inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-bold border ${
