  DIVIDEND = 'DIVIDEND',
  SPLIT = 'SPLIT'
}

export enum AssetClass {
  STOCK = 'Stock',
  CRYPTO = 'Crypto',
  FUND = 'Fund',
  GOLD = 'Gold',
  CASH = 'Cash'
}

export interface Transaction {
  id: string;
