          >
            <Plus size={20} strokeWidth={3} />
            <span>Add Transaction</span>
          </button>

          <button
            onClick={toggleDarkMode}
            className="w-full flex items-center justify-between px-4 py-3 rounded-xl border border-slate-200 dark:border-slate-700 text-slate-600 dark:text-slate-300 hover:bg-slate-100 dark:hover:bg-slate-800 transition-colors text-sm font-medium"
          >
            <span className="flex items-center gap-2">
              {darkMode ? <Moon size={16} /> : <Sun size={16} />}
              {darkMode ? 'Dark Mode' : 'Light Mode'}
            </span>
          </button>
        </div>
      </aside>

      {/* Mobile Header */}
      <div className="md:hidden fixed w-full top-0 z-30 glass dark:bg-slate-900/80 border-b border-slate-200 dark:border-slate-800 p-4 flex items-center justify-between">
        <div className="flex items-center space-x-2 overflow-hidden">
           <div className="w-8 h-8 bg-gradient-to-br from-blue-600 to-indigo-600 rounded-lg flex items-center justify-center shrink-0">
            <TrendingUp className="text-white" size={18} />
          </div>
          <div>
             <h1 className="text-sm font-display font-bold text-slate-900 dark:text-white leading-none">Portfolio</h1>
             <p className="text-xs text-slate-500 truncate max-w-[120px]">{activePortfolio?.name}</p>
          </div>
        </div>
        <div className="flex items-center space-x-3">
           <button
            onClick={() => onOpenAddModal()}
            className="w-10 h-10 bg-blue-600 text-white rounded-full flex items-center justify-center shadow-lg active:scale-90 transition-transform"
           >
             <Plus size={24} />
           </button>
          <button onClick={() => setIsMobileMenuOpen(!isMobileMenuOpen)} className="text-slate-600 dark:text-slate-300">
            {isMobileMenuOpen ? <X size={26} /> : <Menu size={26} />}
          </button>
        </div>
      </div>

      {/* Mobile Menu Overlay */}
      {isMobileMenuOpen && (
        <div className="md:hidden fixed inset-0 z-20 bg-white/95 dark:bg-slate-900/95 backdrop-blur-xl pt-24 px-6 animate-fade-in flex flex-col">
           {/* Mobile Portfolio Switcher */}
           <div className="mb-6">
              <p className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-2">Switch Portfolio</p>
              <div className="flex gap-2 overflow-x-auto pb-2">
                 {portfolios.map(p => (
                   <button 
                     key={p.id}
                     onClick={() => {
                       onSwitchPortfolio(p.id);
                       setIsMobileMenuOpen(false);
                     }}
                     className={`px-4 py-2 rounded-lg text-sm font-bold whitespace-nowrap border ${
                       activePortfolioId === p.id 
                       ? 'bg-blue-600 text-white border-blue-600' 
                       : 'bg-white dark:bg-slate-800 text-slate-600 dark:text-slate-300 border-slate-200 dark:border-slate-700'
                     }`}
                   >
                     {p.name}
                   </button>
                 ))}
                 <button 
                   onClick={handleCreateClick}
                   className="px-4 py-2 rounded-lg text-sm font-bold bg-slate-100 dark:bg-slate-800 text-blue-600 border border-transparent"
                 >
                   + New
                 </button>
              </div>
           </div>

           <nav className="space-y-3">
            {navItems.map((item) => (
              <button
                key={item.id}
                onClick={() => {
                  setActiveTab(item.id);
                  setIsMobileMenuOpen(false);
                }}
                className={`w-full flex items-center space-x-4 px-6 py-5 rounded-2xl border transition-all ${
                  activeTab === item.id
                    ? 'border-blue-500/30 bg-blue-50 text-blue-700 dark:bg-blue-900/20 dark:border-blue-500/30 dark:text-blue-400 shadow-sm'
                    : 'border-transparent hover:bg-slate-100 dark:hover:bg-slate-800 text-slate-600 dark:text-slate-400'
                }`}
              >
                {item.icon}
                <span className="text-lg font-semibold">{item.label}</span>
              </button>
            ))}
             <div className="h-px bg-slate-200 dark:bg-slate-800 my-6"></div>
             <button
              onClick={toggleDarkMode}
              className="w-full flex items-center justify-between px-6 py-5 rounded-2xl bg-slate-100 dark:bg-slate-800 text-slate-700 dark:text-slate-300"
            >
              <span className="text-lg font-medium">{darkMode ? 'Switch to Light' : 'Switch to Dark'}</span>
              {darkMode ? <Sun size={24} /> : <Moon size={24} />}
            </button>
          </nav>
        </div>
      )}

      {/* Main Content Area */}
      <main className="flex-1 md:ml-72 p-4 md:p-8 pt-24 md:pt-8 overflow-y-auto overflow-x-hidden min-h-screen">
        <div className="max-w-7xl mx-auto animate-slide-up">
          {children}
        </div>
      </main>
    </div>
  );
};

