import React, { useState, useEffect, useMemo } from 'react';
import Layout from './components/Layout';
import Dashboard from './components/Dashboard';
import Holdings from './components/Holdings';
import Reports from './components/Reports';
import History from './components/History';
import { Transaction, TransactionType, AssetClass, Holding, Portfolio } from './types';
import { calculateHoldings, calculatePortfolioHistory, generateId, formatCurrency, formatNumber } from './utils';
import { X, Save, TrendingUp, TrendingDown, DollarSign, Wallet, Calendar, GitFork, AlertCircle, ArrowRight } from 'lucide-react';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState('dashboard');
  const [isAddModalOpen, setIsAddModalOpen] = useState(false);

  // --- PORTFOLIO MANAGEMENT STATE ---
  const [portfolios, setPortfolios] = useState<Portfolio[]>(() => {
    const saved = localStorage.getItem('portfolios');
    if (saved) return JSON.parse(saved);

    // Migration: If no portfolios exist but we have legacy transactions, create a default one
    const legacyTx = localStorage.getItem('transactions');
    if (legacyTx) {
      return [{ id: 'default', name: 'Main Portfolio' }];
    }

    return [{ id: generateId(), name: 'My First Portfolio' }];
  });

  const [activePortfolioId, setActivePortfolioId] = useState<string>(() => {
    const saved = localStorage.getItem('activePortfolioId');
    // Ensure the saved ID actually exists
    const portfolios = JSON.parse(localStorage.getItem('portfolios') || '[]');
    if (saved && portfolios.some((p: Portfolio) => p.id === saved)) return saved;
    // Fallback to the first portfolio or default
    return portfolios.length > 0 ? portfolios[0].id : 'default';
  });

  // --- DATA STATE (Per Portfolio) ---
  const [transactions, setTransactions] = useState<Transaction[]>([]);
  const [prices, setPrices] = useState<Record<string, number>>({});
  const [financialGoal, setFinancialGoal] = useState<number>(100000);
  const [isDataLoaded, setIsDataLoaded] = useState(false);

  // --- PERSISTENCE: Portfolios List ---
  useEffect(() => {
    localStorage.setItem('portfolios', JSON.stringify(portfolios));
  }, [portfolios]);

  useEffect(() => {
    localStorage.setItem('activePortfolioId', activePortfolioId);
  }, [activePortfolioId]);

  // --- PERSISTENCE: Load Data on Portfolio Switch ---
  useEffect(() => {
    setIsDataLoaded(false); // Prevent saving while loading

    // Construct keys based on ID. 
    // Special handling for 'default' ID to support migration from legacy keys without ID suffix if needed,
    // but for simplicity, we will migrate legacy data to 'transactions_default' below if strictly needed,
    // OR just check if the new key exists, if not check legacy key.

    const txKey = `transactions_${activePortfolioId}`;
    const pricesKey = `prices_${activePortfolioId}`;
    const goalKey = `financialGoal_${activePortfolioId}`;

    // 1. Transactions
    const savedTx = localStorage.getItem(txKey);
    if (savedTx) {
      setTransactions(JSON.parse(savedTx));
    } else if (activePortfolioId === 'default' && localStorage.getItem('transactions')) {
      // Migrate legacy data
      setTransactions(JSON.parse(localStorage.getItem('transactions')!));
    } else {
      setTransactions([]);
    }

    // 2. Prices
    const savedPrices = localStorage.getItem(pricesKey);
    if (savedPrices) {
      setPrices(JSON.parse(savedPrices));
    } else if (activePortfolioId === 'default' && localStorage.getItem('prices')) {
      setPrices(JSON.parse(localStorage.getItem('prices')!));
    } else {
      setPrices({});
    }

    // 3. Goal
    const savedGoal = localStorage.getItem(goalKey);
    if (savedGoal) {
      setFinancialGoal(parseFloat(savedGoal));
    } else if (activePortfolioId === 'default' && localStorage.getItem('financialGoal')) {
      setFinancialGoal(parseFloat(localStorage.getItem('financialGoal')!));
    } else {
      setFinancialGoal(100000);
    }

    setIsDataLoaded(true);
  }, [activePortfolioId]);

  // --- PERSISTENCE: Save Data (Only if loaded) ---
  useEffect(() => {
    if (!isDataLoaded) return;
    localStorage.setItem(`transactions_${activePortfolioId}`, JSON.stringify(transactions));
  }, [transactions, activePortfolioId, isDataLoaded]);

  useEffect(() => {
    if (!isDataLoaded) return;
    localStorage.setItem(`prices_${activePortfolioId}`, JSON.stringify(prices));
  }, [prices, activePortfolioId, isDataLoaded]);

  useEffect(() => {
    if (!isDataLoaded) return;
    localStorage.setItem(`financialGoal_${activePortfolioId}`, financialGoal.toString());
  }, [financialGoal, activePortfolioId, isDataLoaded]);


  // --- CALCULATIONS ---
  const holdings = useMemo(() => calculateHoldings(transactions, prices), [transactions, prices]);
  const chartData = useMemo(() => calculatePortfolioHistory(transactions, prices), [transactions, prices]);

  const investedAmount = transactions.reduce((sum, t) => {
    if (t.type === TransactionType.DEPOSIT) return sum + (t.price || 0);
    if (t.type === TransactionType.WITHDRAW) return sum - (t.price || 0);
    return sum;
  }, 0);

  const cashBalance = useMemo(() => {
    let balance = 0;
    transactions.forEach(t => {
      if (t.type === TransactionType.DEPOSIT) balance += (t.price || 0);
      if (t.type === TransactionType.WITHDRAW) balance -= (t.price || 0);
      if (t.type === TransactionType.BUY) balance -= (t.price! * t.shares!) + (t.fee || 0);
      if (t.type === TransactionType.SELL) balance += (t.price! * t.shares!) - (t.fee || 0);
      if (t.type === TransactionType.DIVIDEND) balance += (t.price || 0);
      // SPLIT does not affect cash balance
    });
    return balance;
  }, [transactions]);

  const portfolioValue = holdings.reduce((sum, h) => sum + h.marketValue, 0);

  // --- HANDLERS ---
  const handleAddTransaction = (newTx: Transaction) => {
    setTransactions(prev => [...prev, newTx]);
    if ((newTx.type === TransactionType.BUY || newTx.type === TransactionType.SELL) && newTx.symbol && newTx.price) {
        setPrices(prev => ({...prev, [newTx.symbol!]: newTx.price!}));
    }
    setIsAddModalOpen(false);
  };

  const handleUpdatePrice = (symbol: string, newPrice: number) => {
    setPrices(prev => ({ ...prev, [symbol]: newPrice }));
  };

  const handleDeleteTransaction = (id: string) => {
    setTransactions(prev => prev.filter(t => t.id !== id));
  };

  const handleCreatePortfolio = (name: string) => {
    const newId = generateId();
    const newPortfolio = { id: newId, name };
    setPortfolios([...portfolios, newPortfolio]);
    setActivePortfolioId(newId);
  };

  const handleDeletePortfolio = (id: string) => {
    if (portfolios.length <= 1) {
      alert("You must have at least one portfolio.");
      return;
    }
    if (window.confirm("Are you sure? This will delete all transactions in this portfolio permanently.")) {
      // Remove data
      localStorage.removeItem(`transactions_${id}`);
      localStorage.removeItem(`prices_${id}`);
      localStorage.removeItem(`financialGoal_${id}`);

      const newPortfolios = portfolios.filter(p => p.id !== id);
      setPortfolios(newPortfolios);

      // If we deleted the active one, switch to the first available
      if (activePortfolioId === id) {
        setActivePortfolioId(newPortfolios[0].id);
      }
    }
  };

  // --- RENDER ---
  return (
    <Layout 
      activeTab={activeTab} 
      setActiveTab={setActiveTab} 
      onOpenAddModal={() => setIsAddModalOpen(true)}
      portfolios={portfolios}
      activePortfolioId={activePortfolioId}
      onSwitchPortfolio={setActivePortfolioId}
      onCreatePortfolio={handleCreatePortfolio}
      onDeletePortfolio={handleDeletePortfolio}
    >
      <div key={activePortfolioId} className="h-full">
        {activeTab === 'dashboard' && (
          <Dashboard 
            holdings={holdings} 
            transactions={transactions} 
            financialGoal={financialGoal}
            setFinancialGoal={setFinancialGoal}
            investedAmount={investedAmount}
            cashBalance={cashBalance}
            portfolioValue={portfolioValue}
            chartData={chartData}
          />
        )}
        {activeTab === 'holdings' && (
          <Holdings holdings={holdings} transactions={transactions} onUpdatePrice={handleUpdatePrice} />
        )}
        {activeTab === 'history' && (
          <History transactions={transactions} onDelete={handleDeleteTransaction} />
        )}
        {activeTab === 'reports' && (
           <Reports transactions={transactions} currentPortfolioValue={portfolioValue + cashBalance} chartData={chartData} />
        )}
      </div>

      {/* ADD TRANSACTION MODAL */}
      {isAddModalOpen && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-sm" onClick={() => setIsAddModalOpen(false)}></div>
          <div className="relative bg-white dark:bg-slate-900 rounded-3xl shadow-2xl w-full max-w-lg overflow-hidden animate-slide-up border border-slate-200 dark:border-slate-800 max-h-[90vh] flex flex-col">
            <AddTransactionForm 
              onClose={() => setIsAddModalOpen(false)} 
              onSave={handleAddTransaction} 
              cashBalance={cashBalance}
              holdings={holdings}
            />
          </div>
        </div>
      )}
    </Layout>
  );
};

interface AddTransactionFormProps {
  onClose: () => void;
  onSave: (t: Transaction) => void;
  cashBalance: number;
  holdings: Holding[];
}

const AddTransactionForm: React.FC<AddTransactionFormProps> = ({ onClose, onSave, cashBalance, holdings }) => {
  const [type, setType] = useState<TransactionType>(TransactionType.BUY);
  const [date, setDate] = useState(new Date().toISOString().split('T')[0]);
  const [symbol, setSymbol] = useState('');
  const [shares, setShares] = useState('');
  const [price, setPrice] = useState('');
  const [assetClass, setAssetClass] = useState<AssetClass>(AssetClass.STOCK);
  const [exchangeRate, setExchangeRate] = useState(''); 
  const [notes, setNotes] = useState('');
  const [error, setError] = useState<string | null>(null);

  const isTrade = type === TransactionType.BUY || type === TransactionType.SELL || type === TransactionType.DIVIDEND;
  const isSplit = type === TransactionType.SPLIT;
  const isFunding = type === TransactionType.DEPOSIT || type === TransactionType.WITHDRAW;

  // --- VALIDATION & SUMMARY LOGIC ---
  const numShares = parseFloat(shares) || 0;
  const numPrice = parseFloat(price) || 0;
  const totalValue = isSplit ? 0 : (isTrade ? numShares * numPrice : numPrice);

  // Determine Impact
  let projectedCash = cashBalance;
  let currentHoldingShares = 0;
  let projectedShares = 0;

  if (symbol) {
    const existing = holdings.find(h => h.symbol === symbol.toUpperCase());
    currentHoldingShares = existing ? existing.shares : 0;
  }

  if (type === TransactionType.BUY) {
    projectedCash = cashBalance - totalValue;
    projectedShares = currentHoldingShares + numShares;
  } else if (type === TransactionType.SELL) {
    projectedCash = cashBalance + totalValue;
    projectedShares = currentHoldingShares - numShares;
  } else if (type === TransactionType.DEPOSIT || type === TransactionType.DIVIDEND) {
    projectedCash = cashBalance + totalValue;
  } else if (type === TransactionType.WITHDRAW) {
    projectedCash = cashBalance - totalValue;
  } else if (type === TransactionType.SPLIT) {
    projectedShares = currentHoldingShares * numShares; // numShares here is ratio
  }

  // Validate on change
  useEffect(() => {
    setError(null);

    // Check 0: Negative/Zero validations
    if (numShares < 0) {
      setError("Shares cannot be negative.");
      return;
    }
    if (numPrice < 0) {
      setError("Amount/Price cannot be negative.");
      return;
    }

    // Check 1: Insufficient Cash for Buy/Withdraw
    if ((type === TransactionType.BUY || type === TransactionType.WITHDRAW) && totalValue > 0) {
      if (totalValue > cashBalance + 0.01) { // 0.01 tolerance for floating point
        setError(`Insufficient funds. You need ${formatCurrency(totalValue)} but only have ${formatCurrency(cashBalance)} available.`);
        return;
      }
    }

    // Check 2: Insufficient Shares for Sell
    if (type === TransactionType.SELL && symbol) {
      if (numShares > currentHoldingShares) {
        setError(`Insufficient position. You own ${formatNumber(currentHoldingShares)} shares of ${symbol.toUpperCase()}, cannot sell ${formatNumber(numShares)}.`);
        return;
      }
    }
  }, [type, totalValue, cashBalance, numShares, currentHoldingShares, symbol, numPrice]);


  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (error) return;

    // Final hard block for zero values on key transaction types
    if ((isTrade || isFunding) && totalValue === 0) {
      return;
    }

    onSave({
      id: generateId(),
      date,
      type,
      symbol: (type === 'DEPOSIT' || type === 'WITHDRAW') ? undefined : symbol.toUpperCase(),
      shares: shares ? parseFloat(shares) : undefined,
      price: type === TransactionType.SPLIT ? 0 : parseFloat(price),
      assetClass: (type === 'DEPOSIT' || type === 'WITHDRAW') ? AssetClass.CASH : assetClass,
      exchangeRate: exchangeRate ? parseFloat(exchangeRate) : 1, 
      notes: notes ? notes : undefined
    });
  };

  return (
    <div className="flex flex-col h-full">
      <div className="flex justify-between items-center p-6 border-b border-slate-100 dark:border-slate-800 bg-slate-50/50 dark:bg-slate-900/50">
        <div>
          <h3 className="text-xl font-display font-bold text-slate-900 dark:text-white">New Transaction</h3>
          <p className="text-sm text-slate-500">Record your investment activity</p>
        </div>
        <button onClick={onClose} className="p-2 rounded-full hover:bg-slate-200 dark:hover:bg-slate-800 text-slate-400 hover:text-slate-600 dark:hover:text-slate-200 transition-colors">
          <X size={24} />
        </button>
      </div>

      <form onSubmit={handleSubmit} className="p-6 space-y-6 overflow-y-auto custom-scrollbar flex-1">

        {/* Transaction Type Selector (Chips) */}
        <div>
           <label className="block text-xs font-bold text-slate-500 uppercase tracking-wider mb-3">Transaction Type</label>
           <div className="grid grid-cols-3 sm:grid-cols-6 gap-2">
              {[
                { id: TransactionType.BUY, icon: <TrendingUp size={16} />, label: 'Buy', color: 'blue' },
                { id: TransactionType.SELL, icon: <TrendingDown size={16} />, label: 'Sell', color: 'rose' },
                { id: TransactionType.DIVIDEND, icon: <DollarSign size={16} />, label: 'Div', color: 'emerald' },
                { id: TransactionType.SPLIT, icon: <GitFork size={16} />, label: 'Split', color: 'purple' },
                { id: TransactionType.DEPOSIT, icon: <Wallet size={16} />, label: 'In', color: 'indigo' },
                { id: TransactionType.WITHDRAW, icon: <Wallet size={16} />, label: 'Out', color: 'orange' },
              ].map((t) => (
                <button
                  key={t.id}
                  type="button"
                  onClick={() => setType(t.id)}
                  className={`flex flex-col items-center justify-center p-2 rounded-xl border transition-all duration-200 ${
                    type === t.id
                      ? `bg-${t.color}-50 border-${t.color}-500 text-${t.color}-700 dark:bg-${t.color}-900/30 dark:border-${t.color}-500 dark:text-${t.color}-300 ring-1 ring-${t.color}-500`
                      : 'bg-white dark:bg-slate-800 border-slate-200 dark:border-slate-700 text-slate-500 hover:border-slate-300 dark:hover:border-slate-600'
                  }`}
                >
                  <div className="mb-1">{t.icon}</div>
                  <span className="text-xs font-bold">{t.label}</span>
                </button>
              ))}
           </div>
        </div>

        {/* Date Input */}
        <div>
           <label className="block text-xs font-bold text-slate-500 uppercase tracking-wider mb-2">Date</label>
           <div className="relative">
             <Calendar className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
             <input 
              type="date" 
              required
              value={date}
              onChange={(e) => setDate(e.target.value)}
              className="w-full pl-10 pr-4 py-3 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl text-slate-900 dark:text-white focus:ring-2 focus:ring-blue-500 focus:border-transparent outline-none transition-all font-medium"
            />
           </div>
        </div>

        {(isTrade || isSplit) && (
          <div className="grid grid-cols-2 gap-4">
            <div className="col-span-1">
               <label className="block text-xs font-bold text-slate-500 uppercase tracking-wider mb-2">Symbol</label>
               <input 
                type="text" 
                required
                placeholder="e.g. AAPL"
                value={symbol}
                onChange={(e) => setSymbol(e.target.value)}
                className="w-full px-4 py-3 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl text-slate-900 dark:text-white focus:ring-2 focus:ring-blue-500 outline-none uppercase font-bold tracking-wide"
              />
            </div>
             <div className="col-span-1">
              <label className="block text-xs font-bold text-slate-500 uppercase tracking-wider mb-2">Class</label>
              <select 
                value={assetClass} 
                onChange={(e) => setAssetClass(e.target.value as AssetClass)}
                className="w-full px-4 py-3 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl text-slate-900 dark:text-white focus:ring-2 focus:ring-blue-500 outline-none appearance-none"
              >
                {Object.values(AssetClass).filter(a => a !== AssetClass.CASH).map(a => <option key={a} value={a}>{a}</option>)}
              </select>
            </div>
          </div>
        )}

        <div className="grid grid-cols-2 gap-4">
           {(isTrade || isSplit) && (
            <div className={isSplit ? "col-span-2" : "col-span-1"}>
              <label className="block text-xs font-bold text-slate-500 uppercase tracking-wider mb-2">
                {isSplit ? "Split Ratio (e.g. 2 for 2:1)" : "Shares"}
              </label>
              <input 
                type="number" 
                step="any"
                min="0"
                required
                placeholder={isSplit ? "2" : "0.00"}
                value={shares}
                onChange={(e) => setShares(e.target.value)}
                className="w-full px-4 py-3 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl text-slate-900 dark:text-white focus:ring-2 focus:ring-blue-500 outline-none font-mono"
              />
              {isSplit && <p className="text-xs text-slate-500 mt-1">For a 2:1 split, enter 2. For a 1:10 reverse split, enter 0.1.</p>}
            </div>
           )}
           {!isSplit && (
             <div className={!isTrade ? "col-span-2" : ""}>
               <label className="block text-xs font-bold text-slate-500 uppercase tracking-wider mb-2">
                 {isTrade ? "Price / Share" : "Amount ($)"}
               </label>
                <input 
                  type="number" 
                  step="any"
                  min="0"
                  required
                  placeholder="0.00"
                  value={price}
                  onChange={(e) => setPrice(e.target.value)}
                  className="w-full px-4 py-3 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl text-slate-900 dark:text-white focus:ring-2 focus:ring-blue-500 outline-none font-mono"
                />
             </div>
           )}
        </div>

        {isFunding && (
           <div className="bg-blue-50 dark:bg-slate-800/50 p-4 rounded-xl border border-blue-100 dark:border-slate-700">
             <label className="block text-xs font-bold text-slate-500 uppercase tracking-wider mb-2">
               Exchange Rate (Optional)
             </label>
              <div className="flex items-center space-x-2">
                <input 
                  type="number" 
                  step="any"
                  min="0"
                  placeholder="1.00"
                  value={exchangeRate}
                  onChange={(e) => setExchangeRate(e.target.value)}
                  className="flex-1 px-4 py-2 bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-600 rounded-lg text-slate-900 dark:text-white focus:ring-2 focus:ring-blue-500 outline-none font-mono text-right"
                />
                <span className="text-sm font-medium text-slate-500">Local / USD</span>
              </div>
           </div>
        )}

        {/* Notes Field */}
        <div>
           <label className="block text-xs font-bold text-slate-500 uppercase tracking-wider mb-2">Notes (Optional)</label>
           <textarea
             rows={2}
             placeholder="Add a memo..."
             value={notes}
             onChange={(e) => setNotes(e.target.value)}
             className="w-full px-4 py-3 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl text-slate-900 dark:text-white focus:ring-2 focus:ring-blue-500 outline-none resize-none font-medium text-sm"
           />
        </div>
      </form>

      {/* SUMMARY SECTION */}
      <div className="px-6 py-4 bg-slate-50/80 dark:bg-slate-800/80 border-t border-slate-200 dark:border-slate-700 backdrop-blur-sm">
         {error ? (
           <div className="bg-red-50 dark:bg-red-900/20 border border-red-200 dark:border-red-800 rounded-xl p-4 flex items-start space-x-3 text-red-600 dark:text-red-400">
             <AlertCircle size={20} className="shrink-0 mt-0.5" />
             <div className="text-sm font-semibold">{error}</div>
           </div>
         ) : (
           <div className="space-y-3">
             <div className="flex justify-between items-center text-sm">
                <span className="text-slate-500 dark:text-slate-400 font-medium">Total Value</span>
                <span className="text-lg font-bold font-display text-slate-900 dark:text-white">
                  {formatCurrency(totalValue)}
                </span>
             </div>

             <div className="flex flex-col gap-2 pt-2 border-t border-slate-200 dark:border-slate-700/50">
               {/* Cash Impact */}
               <div className="flex justify-between items-center text-xs">
                 <span className="text-slate-500">Cash Balance</span>
                 <div className="flex items-center space-x-1.5">
                   <span className="text-slate-500">{formatCurrency(cashBalance)}</span>
                   <ArrowRight size={12} className="text-slate-400" />
                   <span className={`font-bold ${projectedCash < 0 ? 'text-red-500' : 'text-slate-700 dark:text-slate-300'}`}>
                     {formatCurrency(projectedCash)}
                   </span>
                 </div>
               </div>

               {/* Share Impact (Only if symbol selected) */}
               {(isTrade || isSplit) && symbol && (
                 <div className="flex justify-between items-center text-xs">
                   <span className="text-slate-500">Position ({symbol})</span>
                   <div className="flex items-center space-x-1.5">
                     <span className="text-slate-500">{formatNumber(currentHoldingShares)}</span>
                     <ArrowRight size={12} className="text-slate-400" />
                     <span className={`font-bold ${projectedShares < 0 ? 'text-red-500' : 'text-slate-700 dark:text-slate-300'}`}>
                       {formatNumber(projectedShares)}
                     </span>
                   </div>
                 </div>
               )}
             </div>
           </div>
         )}
      </div>

      <div className="p-6 border-t border-slate-100 dark:border-slate-800 bg-white dark:bg-slate-900">
        <button 
          onClick={handleSubmit}
          disabled={!!error}
          className={`w-full font-bold py-4 rounded-xl shadow-lg transition-all flex items-center justify-center space-x-2 text-lg ${
            error 
              ? 'bg-slate-300 dark:bg-slate-700 text-slate-500 cursor-not-allowed' 
              : 'bg-slate-900 dark:bg-blue-600 hover:opacity-90 text-white shadow-slate-900/20 dark:shadow-blue-600/20 active:scale-95'
          }`}
        >
          <Save size={20} />
          <span>Save Transaction</span>
        </button>
      </div>
    </div>
  );
};

