export default History;

import React, { useState, useEffect, useMemo } from 'react';
import Layout from './components/Layout';
import Dashboard from './components/Dashboard';
import Holdings from './components/Holdings';
import Reports from './components/Reports';
import History from './components/History';
import { Transaction, TransactionType, AssetClass, Holding, Portfolio } from './types';
import { calculateHoldings, calculatePortfolioHistory, generateId, formatCurrency, formatNumber } from './utils';
import { X, Save, TrendingUp, TrendingDown, DollarSign, Wallet, Calendar, GitFork, AlertCircle, ArrowRight } from 'lucide-react';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState('dashboard');
  const [isAddModalOpen, setIsAddModalOpen] = useState(false);
  const [editingTransaction, setEditingTransaction] = useState<Transaction | null>(null);

  // --- PORTFOLIO MANAGEMENT STATE ---
  const [portfolios, setPortfolios] = useState<Portfolio[]>(() => {
    const saved = localStorage.getItem('portfolios');
    if (saved) return JSON.parse(saved);

    // Migration: If no portfolios exist but we have legacy transactions, create a default one
    const legacyTx = localStorage.getItem('transactions');
    if (legacyTx) {
      return [{ id: 'default', name: 'Main Portfolio' }];
    }

    return [{ id: generateId(), name: 'My First Portfolio' }];
  });

  const [activePortfolioId, setActivePortfolioId] = useState<string>(() => {
    const saved = localStorage.getItem('activePortfolioId');
    // Ensure the saved ID actually exists
    const portfolios = JSON.parse(localStorage.getItem('portfolios') || '[]');
    if (saved && portfolios.some((p: Portfolio) => p.id === saved)) return saved;
    // Fallback to the first portfolio or default
    return portfolios.length > 0 ? portfolios[0].id : 'default';
  });

  // --- DATA STATE (Per Portfolio) ---
  const [transactions, setTransactions] = useState<Transaction[]>([]);
  const [prices, setPrices] = useState<Record<string, number>>({});
  const [financialGoal, setFinancialGoal] = useState<number>(100000);
  const [isDataLoaded, setIsDataLoaded] = useState(false);

  // --- PERSISTENCE: Portfolios List ---
  useEffect(() => {
    localStorage.setItem('portfolios', JSON.stringify(portfolios));
  }, [portfolios]);

  useEffect(() => {
    localStorage.setItem('activePortfolioId', activePortfolioId);
  }, [activePortfolioId]);

  // --- PERSISTENCE: Load Data on Portfolio Switch ---
  useEffect(() => {
    setIsDataLoaded(false); // Prevent saving while loading

    const txKey = `transactions_${activePortfolioId}`;
    const pricesKey = `prices_${activePortfolioId}`;
    const goalKey = `financialGoal_${activePortfolioId}`;

    // 1. Transactions
    const savedTx = localStorage.getItem(txKey);
    if (savedTx) {
      setTransactions(JSON.parse(savedTx));
    } else if (activePortfolioId === 'default' && localStorage.getItem('transactions')) {
      setTransactions(JSON.parse(localStorage.getItem('transactions')!));
    } else {
      setTransactions([]);
    }

    // 2. Prices
    const savedPrices = localStorage.getItem(pricesKey);
    if (savedPrices) {
      setPrices(JSON.parse(savedPrices));
    } else if (activePortfolioId === 'default' && localStorage.getItem('prices')) {
      setPrices(JSON.parse(localStorage.getItem('prices')!));
    } else {
      setPrices({});
    }

    // 3. Goal
    const savedGoal = localStorage.getItem(goalKey);
    if (savedGoal) {
      setFinancialGoal(parseFloat(savedGoal));
    } else if (activePortfolioId === 'default' && localStorage.getItem('financialGoal')) {
      setFinancialGoal(parseFloat(localStorage.getItem('financialGoal')!));
    } else {
      setFinancialGoal(100000);
    }

    setIsDataLoaded(true);
  }, [activePortfolioId]);

  // --- PERSISTENCE: Save Data (Only if loaded) ---
  useEffect(() => {
    if (!isDataLoaded) return;
    localStorage.setItem(`transactions_${activePortfolioId}`, JSON.stringify(transactions));
  }, [transactions, activePortfolioId, isDataLoaded]);

  useEffect(() => {
    if (!isDataLoaded) return;
    localStorage.setItem(`prices_${activePortfolioId}`, JSON.stringify(prices));
  }, [prices, activePortfolioId, isDataLoaded]);

  useEffect(() => {
    if (!isDataLoaded) return;
    localStorage.setItem(`financialGoal_${activePortfolioId}`, financialGoal.toString());
  }, [financialGoal, activePortfolioId, isDataLoaded]);


  // --- CALCULATIONS ---
  const holdings = useMemo(() => calculateHoldings(transactions, prices), [transactions, prices]);
  const chartData = useMemo(() => calculatePortfolioHistory(transactions, prices), [transactions, prices]);

  const investedAmount = transactions.reduce((sum, t) => {
    if (t.type === TransactionType.DEPOSIT) return sum + (t.price || 0);
    if (t.type === TransactionType.WITHDRAW) return sum - (t.price || 0);
    return sum;
  }, 0);

  const cashBalance = useMemo(() => {
    let balance = 0;
    transactions.forEach(t => {
      if (t.type === TransactionType.DEPOSIT) balance += (t.price || 0);
      if (t.type === TransactionType.WITHDRAW) balance -= (t.price || 0);
      if (t.type === TransactionType.BUY) balance -= (t.price! * t.shares!) + (t.fee || 0);
      if (t.type === TransactionType.SELL) balance += (t.price! * t.shares!) - (t.fee || 0);
      if (t.type === TransactionType.DIVIDEND) balance += (t.price || 0);
    });
    return balance;
  }, [transactions]);

  const portfolioValue = holdings.reduce((sum, h) => sum + h.marketValue, 0);

  // --- HANDLERS ---
  const handleOpenAddModal = () => {
    setEditingTransaction(null);
    setIsAddModalOpen(true);
  };

  const handleOpenEditModal = (tx: Transaction) => {
    setEditingTransaction(tx);
    setIsAddModalOpen(true);
  };

  const handleSaveTransaction = (tx: Transaction) => {
    if (editingTransaction) {
      // Update existing
      setTransactions(prev => prev.map(t => t.id === tx.id ? tx : t));
    } else {
      // Add new
      setTransactions(prev => [...prev, tx]);
    }

    // Update prices if applicable
    if ((tx.type === TransactionType.BUY || tx.type === TransactionType.SELL) && tx.symbol && tx.price) {
        setPrices(prev => ({...prev, [tx.symbol!]: tx.price!}));
    }

    setIsAddModalOpen(false);
    setEditingTransaction(null);
  };

  const handleUpdatePrice = (symbol: string, newPrice: number) => {
    setPrices(prev => ({ ...prev, [symbol]: newPrice }));
  };

  const handleDeleteTransaction = (id: string) => {
    setTransactions(prev => prev.filter(t => t.id !== id));
  };

  const handleCreatePortfolio = (name: string) => {
    const newId = generateId();
    const newPortfolio = { id: newId, name };
    setPortfolios([...portfolios, newPortfolio]);
    setActivePortfolioId(newId);
  };

  const handleRenamePortfolio = (id: string, newName: string) => {
    setPortfolios(prev => prev.map(p => p.id === id ? { ...p, name: newName } : p));
  };

  const handleDeletePortfolio = (id: string) => {
    if (portfolios.length <= 1) {
      alert("You must have at least one portfolio.");
      return;
    }
    if (window.confirm("Are you sure? This will delete all transactions in this portfolio permanently.")) {
      localStorage.removeItem(`transactions_${id}`);
      localStorage.removeItem(`prices_${id}`);
      localStorage.removeItem(`financialGoal_${id}`);

      const newPortfolios = portfolios.filter(p => p.id !== id);
      setPortfolios(newPortfolios);

      if (activePortfolioId === id) {
        setActivePortfolioId(newPortfolios[0].id);
      }
    }
  };

  // --- RENDER ---
  return (
    <Layout 
      activeTab={activeTab} 
      setActiveTab={setActiveTab} 
      onOpenAddModal={handleOpenAddModal}
      portfolios={portfolios}
      activePortfolioId={activePortfolioId}
      onSwitchPortfolio={setActivePortfolioId}
      onCreatePortfolio={handleCreatePortfolio}
      onRenamePortfolio={handleRenamePortfolio}
      onDeletePortfolio={handleDeletePortfolio}
    >
      <div key={activePortfolioId} className="h-full">
        {activeTab === 'dashboard' && (
          <Dashboard 
            holdings={holdings} 
            transactions={transactions} 
            financialGoal={financialGoal}
            setFinancialGoal={setFinancialGoal}
            investedAmount={investedAmount}
            cashBalance={cashBalance}
            portfolioValue={portfolioValue}
            chartData={chartData}
          />
        )}
        {activeTab === 'holdings' && (
          <Holdings holdings={holdings} transactions={transactions} onUpdatePrice={handleUpdatePrice} />
        )}
        {activeTab === 'history' && (
          <History 
            transactions={transactions} 
            onDelete={handleDeleteTransaction}
            onEdit={handleOpenEditModal}
            onAdd={handleOpenAddModal}
          />
        )}
        {activeTab === 'reports' && (
           <Reports transactions={transactions} currentPortfolioValue={portfolioValue + cashBalance} chartData={chartData} />
        )}
      </div>

      {/* ADD/EDIT TRANSACTION MODAL */}
      {isAddModalOpen && (
        <div className="fixed inset-0 z-50 flex items-end sm:items-center justify-center sm:p-4">
          <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-sm" onClick={() => setIsAddModalOpen(false)}></div>
          <div className="relative bg-white dark:bg-slate-900 w-full max-w-lg 
                          rounded-t-3xl sm:rounded-3xl border border-slate-200 dark:border-slate-800 
                          shadow-2xl overflow-hidden animate-slide-up flex flex-col
                          max-h-[90dvh] sm:max-h-[85vh]">
            <AddTransactionForm 
              onClose={() => setIsAddModalOpen(false)} 
              onSave={handleSaveTransaction} 
              cashBalance={cashBalance}
              holdings={holdings}
              transactions={transactions}
              initialData={editingTransaction}
            />
          </div>
        </div>
      )}
    </Layout>
  );
};

interface AddTransactionFormProps {
  onClose: () => void;
  onSave: (t: Transaction) => void;
  cashBalance: number;
  holdings: Holding[];
  transactions: Transaction[];
  initialData: Transaction | null;
}

const AddTransactionForm: React.FC<AddTransactionFormProps> = ({ onClose, onSave, cashBalance, holdings, transactions, initialData }) => {
  const [type, setType] = useState<TransactionType>(TransactionType.BUY);
  const [date, setDate] = useState(new Date().toISOString().split('T')[0]);
  const [symbol, setSymbol] = useState('');
  const [shares, setShares] = useState('');
  const [price, setPrice] = useState('');
  const [fee, setFee] = useState('');
  const [assetClass, setAssetClass] = useState<AssetClass>(AssetClass.STOCK);
  const [exchangeRate, setExchangeRate] = useState(''); 
  const [notes, setNotes] = useState('');
  const [error, setError] = useState<string | null>(null);

  // Populate form if initialData exists (Edit Mode)
  useEffect(() => {
    if (initialData) {
      setType(initialData.type);
      setDate(initialData.date);
      setSymbol(initialData.symbol || '');
      setShares(initialData.shares?.toString() || '');
      setPrice(initialData.price?.toString() || '');
      setFee(initialData.fee?.toString() || '');
      setAssetClass(initialData.assetClass || AssetClass.STOCK);
      setExchangeRate(initialData.exchangeRate?.toString() || '');
      setNotes(initialData.notes || '');
    }
  }, [initialData]);

  const isTrade = type === TransactionType.BUY || type === TransactionType.SELL || type === TransactionType.DIVIDEND;
  const isSplit = type === TransactionType.SPLIT;
  const isFunding = type === TransactionType.DEPOSIT || type === TransactionType.WITHDRAW;

  // --- VALIDATION & SUMMARY LOGIC ---
  const numShares = parseFloat(shares) || 0;
  const numPrice = parseFloat(price) || 0;
  const numFee = parseFloat(fee) || 0;
  const totalValue = isSplit ? 0 : (isTrade ? numShares * numPrice : numPrice);

  // Determine Impact and Validate
  useEffect(() => {
    setError(null);

    // 1. Basic numeric validation
    if (numShares < 0 || numPrice < 0 || numFee < 0) {
      setError("Values cannot be negative.");
      return;
    }

    // 2. Duplicate Check
    // We check if there is an *identical* transaction already, excluding the one currently being edited.
    const isDuplicate = transactions.some(t => {
      // If we are editing, ignore the transaction with the same ID as initialData
      if (initialData && t.id === initialData.id) return false;

      // Check fields for duplication
      return (
        t.date === date &&
        t.type === type &&
        (t.symbol || '') === (symbol.toUpperCase() || '') &&
        (t.shares || 0) === numShares &&
        (t.price || 0) === numPrice
      );
    });

    if (isDuplicate) {
      setError("A duplicate transaction already exists.");
      return;
    }

    // 3. Share Availability Validation (For SELL)
    if (type === TransactionType.SELL && symbol) {
      const holding = holdings.find(h => h.symbol === symbol.toUpperCase());
      let availableShares = holding ? holding.shares : 0;

      // If we are editing a past SELL, we need to add those shares back to the "available" pool
      // to check if the NEW amount is valid.
      // Logic: Current Holding + Shares from this specific SELL transaction (before edit).
      if (initialData && initialData.type === TransactionType.SELL && initialData.symbol === symbol.toUpperCase()) {
         availableShares += (initialData.shares || 0);
      }

      // If we are editing a past BUY, and change it to SELL, available shares is just current holdings.
      // But if we edit a BUY to be lower, we might break *future* sells. That's too complex for this form.
      // We will focus on ensuring this specific SELL is valid relative to *current* final state.

      if (numShares > availableShares + 0.000001) { // Epsilon for float math
         setError(`Insufficient shares. You own ${formatNumber(availableShares, 4)} ${symbol}.`);
         return;
      }
    }

    // 4. Cash Availability Validation (For BUY and WITHDRAW)
    // We validate against the *current* cash balance.
    // If editing, we revert the impact of the *current* version of the transaction to find "Available Cash".
    if (type === TransactionType.BUY || type === TransactionType.WITHDRAW) {
       let availableCash = cashBalance;

       // Add back resources consumed by the transaction we are editing
       if (initialData) {
         if (initialData.type === TransactionType.BUY) {
           availableCash += ((initialData.shares || 0) * (initialData.price || 0)) + (initialData.fee || 0);
         } else if (initialData.type === TransactionType.WITHDRAW) {
           availableCash += (initialData.price || 0);
         } else if (initialData.type === TransactionType.DEPOSIT) {
           availableCash -= (initialData.price || 0); // If we change a deposit to a withdraw, we lose that deposit
         } else if (initialData.type === TransactionType.SELL) {
           availableCash -= ((initialData.shares || 0) * (initialData.price || 0)) - (initialData.fee || 0);
         }
       }

       const needed = totalValue + numFee;

       if (needed > availableCash + 0.01) { // 1 cent tolerance
         setError(`Insufficient funds. Available: ${formatCurrency(availableCash)}.`);
         return;
       }
    }

  }, [type, totalValue, cashBalance, numShares, numPrice, numFee, initialData, transactions, date, symbol, holdings]);

  // Projected Cash Calculation for Display
  let projectedCash = cashBalance;
  // This is purely for display, approximate logic
  if (type === TransactionType.BUY) projectedCash = cashBalance - totalValue - numFee;
  else if (type === TransactionType.SELL) projectedCash = cashBalance + totalValue - numFee;
  else if (type === TransactionType.DEPOSIT || type === TransactionType.DIVIDEND) projectedCash = cashBalance + totalValue;
  else if (type === TransactionType.WITHDRAW) projectedCash = cashBalance - totalValue;


  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (error) return;
    if ((isTrade || isFunding) && totalValue === 0) {
      setError("Amount must be greater than 0");
      return;
    }

    // Check required fields again just in case
    if ((isTrade) && !symbol) {
      setError("Symbol is required");
      return;
    }

    onSave({
      id: initialData ? initialData.id : generateId(), // Use existing ID if editing
      date,
      type,
      symbol: (type === 'DEPOSIT' || type === 'WITHDRAW') ? undefined : symbol.toUpperCase(),
      shares: shares ? parseFloat(shares) : undefined,
      price: type === TransactionType.SPLIT ? 0 : parseFloat(price),
      fee: (fee && (type === TransactionType.BUY || type === TransactionType.SELL)) ? parseFloat(fee) : undefined,
      assetClass: (type === 'DEPOSIT' || type === 'WITHDRAW') ? AssetClass.CASH : assetClass,
      exchangeRate: exchangeRate ? parseFloat(exchangeRate) : 1, 
      notes: notes ? notes : undefined
    });
  };

  return (
    <>
      {/* Header */}
      <div className="shrink-0 flex justify-between items-center p-4 border-b border-slate-100 dark:border-slate-800 bg-slate-50/50 dark:bg-slate-900/50">
        <div>
          <h3 className="text-lg font-display font-bold text-slate-900 dark:text-white">
            {initialData ? 'Edit Transaction' : 'New Transaction'}
          </h3>
          <p className="text-xs text-slate-500">{initialData ? 'Update details' : 'Record your investment activity'}</p>
        </div>
        <button onClick={onClose} className="p-2 rounded-full hover:bg-slate-200 dark:hover:bg-slate-800 text-slate-400 hover:text-slate-600 dark:hover:text-slate-200 transition-colors">
          <X size={20} />
        </button>
      </div>

      {/* Scrollable Form Area */}
      <form onSubmit={handleSubmit} className="flex-1 overflow-y-auto min-h-0 p-4 space-y-4 custom-scrollbar">

        {/* Transaction Type Selector (Compact Grid) */}
        <div>
           <label className="block text-[10px] font-bold text-slate-500 uppercase tracking-wider mb-1.5">Transaction Type</label>
           <div className="grid grid-cols-3 sm:grid-cols-6 gap-2">
              {[
                { id: TransactionType.BUY, icon: <TrendingUp size={14} />, label: 'Buy', color: 'blue' },
                { id: TransactionType.SELL, icon: <TrendingDown size={14} />, label: 'Sell', color: 'rose' },
                { id: TransactionType.DIVIDEND, icon: <DollarSign size={14} />, label: 'Div', color: 'emerald' },
                { id: TransactionType.SPLIT, icon: <GitFork size={14} />, label: 'Split', color: 'purple' },
                { id: TransactionType.DEPOSIT, icon: <Wallet size={14} />, label: 'In', color: 'indigo' },
                { id: TransactionType.WITHDRAW, icon: <Wallet size={14} />, label: 'Out', color: 'orange' },
              ].map((t) => (
                <button
                  key={t.id}
                  type="button"
                  onClick={() => setType(t.id)}
                  className={`flex flex-col items-center justify-center p-2 rounded-lg border transition-all duration-200 ${
                    type === t.id
                      ? `bg-${t.color}-50 border-${t.color}-500 text-${t.color}-700 dark:bg-${t.color}-900/30 dark:border-${t.color}-500 dark:text-${t.color}-300 ring-1 ring-${t.color}-500 shadow-sm`
                      : 'bg-white dark:bg-slate-800 border-slate-200 dark:border-slate-700 text-slate-500 hover:border-slate-300 dark:hover:border-slate-600'
                  }`}
                >
                  <div className="mb-0.5">{t.icon}</div>
                  <span className="text-[10px] font-bold">{t.label}</span>
                </button>
              ))}
           </div>
        </div>

        {/* Date Input */}
        <div>
           <label className="block text-[10px] font-bold text-slate-500 uppercase tracking-wider mb-1.5">Date</label>
           <div className="relative">
             <Calendar className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={16} />
             <input 
              type="date" 
              required
              value={date}
              onChange={(e) => setDate(e.target.value)}
              className="w-full pl-9 pr-3 py-2.5 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl text-slate-900 dark:text-white focus:ring-2 focus:ring-blue-500 focus:border-transparent outline-none transition-all font-medium text-sm"
            />
           </div>
        </div>

        {(isTrade || isSplit) && (
          <div className="grid grid-cols-2 gap-3">
            <div className="col-span-1">
               <label className="block text-[10px] font-bold text-slate-500 uppercase tracking-wider mb-1.5">Symbol</label>
               <input 
                type="text" 
                required
                placeholder="AAPL"
                value={symbol}
                onChange={(e) => setSymbol(e.target.value)}
                className="w-full px-3 py-2.5 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl text-slate-900 dark:text-white focus:ring-2 focus:ring-blue-500 outline-none uppercase font-bold tracking-wide text-sm"
              />
            </div>
             <div className="col-span-1">
              <label className="block text-[10px] font-bold text-slate-500 uppercase tracking-wider mb-1.5">Class</label>
              <select 
                value={assetClass} 
                onChange={(e) => setAssetClass(e.target.value as AssetClass)}
                className="w-full px-3 py-2.5 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl text-slate-900 dark:text-white focus:ring-2 focus:ring-blue-500 outline-none appearance-none text-sm"
              >
                {Object.values(AssetClass).filter(a => a !== AssetClass.CASH).map(a => <option key={a} value={a}>{a}</option>)}
              </select>
            </div>
          </div>
        )}

        <div className="grid grid-cols-2 gap-3">
           {(isTrade || isSplit) && (
            <div className={isSplit ? "col-span-2" : "col-span-1"}>
              <label className="block text-[10px] font-bold text-slate-500 uppercase tracking-wider mb-1.5">
                {isSplit ? "Split Ratio (e.g. 2 for 2:1)" : "Shares"}
              </label>
              <input 
                type="number" 
                step="any"
                min="0"
                required
                placeholder={isSplit ? "2" : "0.00"}
                value={shares}
                onChange={(e) => setShares(e.target.value)}
                className="w-full px-3 py-2.5 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl text-slate-900 dark:text-white focus:ring-2 focus:ring-blue-500 outline-none font-mono text-sm"
              />
              {isSplit && <p className="text-[10px] text-slate-500 mt-1">For a 2:1 split, enter 2.</p>}
            </div>
           )}
           {!isSplit && (
             <div className={!isTrade ? "col-span-2" : ""}>
               <label className="block text-[10px] font-bold text-slate-500 uppercase tracking-wider mb-1.5">
                 {isTrade ? "Price / Share" : "Amount ($)"}
               </label>
                <input 
                  type="number" 
                  step="any"
                  min="0"
                  required
                  placeholder="0.00"
                  value={price}
                  onChange={(e) => setPrice(e.target.value)}
                  className="w-full px-3 py-2.5 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl text-slate-900 dark:text-white focus:ring-2 focus:ring-blue-500 outline-none font-mono text-sm"
                />
             </div>
           )}
        </div>

        {/* Fee Field for Buy/Sell */}
        {(type === TransactionType.BUY || type === TransactionType.SELL) && (
           <div>
              <label className="block text-[10px] font-bold text-slate-500 uppercase tracking-wider mb-1.5">
                Transaction Fee (Optional)
              </label>
              <input 
                type="number" 
                step="any"
                min="0"
                placeholder="0.00"
                value={fee}
                onChange={(e) => setFee(e.target.value)}
                className="w-full px-3 py-2.5 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl text-slate-900 dark:text-white focus:ring-2 focus:ring-blue-500 outline-none font-mono text-sm"
              />
           </div>
        )}

        {isFunding && (
           <div className="bg-blue-50 dark:bg-slate-800/50 p-3 rounded-xl border border-blue-100 dark:border-slate-700">
             <label className="block text-[10px] font-bold text-slate-500 uppercase tracking-wider mb-1.5">
               Exchange Rate (Optional)
             </label>
              <div className="flex items-center space-x-2">
                <input 
                  type="number" 
                  step="any"
                  min="0"
                  placeholder="1.00"
                  value={exchangeRate}
                  onChange={(e) => setExchangeRate(e.target.value)}
                  className="flex-1 px-3 py-2 bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-600 rounded-lg text-slate-900 dark:text-white focus:ring-2 focus:ring-blue-500 outline-none font-mono text-right text-sm"
                />
                <span className="text-xs font-medium text-slate-500">Local / USD</span>
              </div>
           </div>
        )}

        {/* Notes Field */}
        <div>
           <label className="block text-[10px] font-bold text-slate-500 uppercase tracking-wider mb-1.5">Notes (Optional)</label>
           <textarea
             rows={2}
             placeholder="Add a memo..."
             value={notes}
             onChange={(e) => setNotes(e.target.value)}
             className="w-full px-3 py-2.5 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl text-slate-900 dark:text-white focus:ring-2 focus:ring-blue-500 outline-none resize-none font-medium text-sm"
           />
        </div>
      </form>

      {/* SUMMARY & FOOTER (Fixed at bottom) */}
      <div className="shrink-0 bg-slate-50/80 dark:bg-slate-800/80 border-t border-slate-200 dark:border-slate-700 backdrop-blur-sm">
         <div className="px-4 py-2 sm:px-6 sm:py-3">
             {error ? (
               <div className="bg-red-50 dark:bg-red-900/20 border border-red-200 dark:border-red-800 rounded-lg p-2.5 flex items-start space-x-2 text-red-600 dark:text-red-400 animate-slide-up">
                 <AlertCircle size={16} className="shrink-0 mt-0.5" />
                 <div className="text-xs font-semibold">{error}</div>
               </div>
             ) : (
               <div className="flex justify-between items-center text-sm">
                  <div className="flex flex-col">
                      <span className="text-xs text-slate-500 dark:text-slate-400 font-medium">Total Value</span>
                      <span className="text-lg font-bold font-display text-slate-900 dark:text-white leading-tight">
                        {formatCurrency(totalValue)}
                      </span>
                  </div>
                  {/* Compact impact view for mobile */}
                   <div className="text-right">
                       <span className="text-xs text-slate-500">Cash After</span>
                       <div className={`font-bold text-sm ${projectedCash < 0 ? 'text-red-500' : 'text-slate-700 dark:text-slate-300'}`}>
                         {formatCurrency(projectedCash)}
                       </div>
                   </div>
               </div>
             )}
         </div>

          <div className="p-4 pt-2 border-t border-slate-100 dark:border-slate-800 bg-white dark:bg-slate-900">
            <button 
              onClick={handleSubmit}
              disabled={!!error}
              className={`w-full font-bold py-3 rounded-xl shadow-lg transition-all flex items-center justify-center space-x-2 text-base ${
                error 
                  ? 'bg-slate-300 dark:bg-slate-700 text-slate-500 cursor-not-allowed' 
                  : 'bg-slate-900 dark:bg-blue-600 hover:opacity-90 text-white shadow-slate-900/20 dark:shadow-blue-600/20 active:scale-95'
              }`}
            >
              <Save size={18} />
              <span>{initialData ? 'Update Transaction' : 'Save Transaction'}</span>
            </button>
          </div>
      </div>
    </>
  );
};

export default App;

import React, { useState, useMemo } from 'react';
import { Transaction, TransactionType, AssetClass } from '../types';
import { Search, Calendar, Filter, Trash2, ArrowUpDown, XCircle, Edit2, Plus } from 'lucide-react';
import { formatCurrency, formatNumber } from '../utils';

interface HistoryProps {
  transactions: Transaction[];
  onDelete: (id: string) => void;
  onEdit: (tx: Transaction) => void;
  onAdd: () => void;
}

const History: React.FC<HistoryProps> = ({ transactions, onDelete, onEdit, onAdd }) => {
  // Filters State
  const [searchTerm, setSearchTerm] = useState('');
  const [typeFilter, setTypeFilter] = useState<TransactionType | 'ALL'>('ALL');
  const [assetClassFilter, setAssetClassFilter] = useState<AssetClass | 'ALL'>('ALL');
  const [startDate, setStartDate] = useState('');
  const [endDate, setEndDate] = useState('');
  const [sortOrder, setSortOrder] = useState<'desc' | 'asc'>('desc');

  // Logic
  const filteredTransactions = useMemo(() => {
    return transactions.filter(tx => {
      // 1. Search (Symbol, Notes)
      const searchLower = searchTerm.toLowerCase();
      const matchesSearch = 
        (tx.symbol?.toLowerCase().includes(searchLower) ?? false) ||
        (tx.notes?.toLowerCase().includes(searchLower) ?? false) ||
        (tx.type.toLowerCase().includes(searchLower));

      // 2. Type Filter
      const matchesType = typeFilter === 'ALL' || tx.type === typeFilter;

      // 3. Asset Class Filter
      const matchesAsset = assetClassFilter === 'ALL' || tx.assetClass === assetClassFilter;

      // 4. Date Range
      const txDate = new Date(tx.date).getTime();
      const start = startDate ? new Date(startDate).getTime() : -Infinity;
      const end = endDate ? new Date(endDate).getTime() : Infinity;
      const matchesDate = txDate >= start && txDate <= end;

      return matchesSearch && matchesType && matchesAsset && matchesDate;
    }).sort((a, b) => {
      const dateA = new Date(a.date).getTime();
      const dateB = new Date(b.date).getTime();
      return sortOrder === 'desc' ? dateB - dateA : dateA - dateB;
    });
  }, [transactions, searchTerm, typeFilter, assetClassFilter, startDate, endDate, sortOrder]);

  const resetFilters = () => {
    setSearchTerm('');
    setTypeFilter('ALL');
    setAssetClassFilter('ALL');
    setStartDate('');
    setEndDate('');
  };

  const hasActiveFilters = searchTerm || typeFilter !== 'ALL' || assetClassFilter !== 'ALL' || startDate || endDate;

  return (
    <div className="space-y-6">
      {/* Header & Controls */}
      <div className="flex flex-col gap-6">
        <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
           <div className="flex justify-between items-start md:block">
             <div>
                <h2 className="text-2xl font-display font-bold text-slate-900 dark:text-white">History</h2>
                <p className="text-slate-500 dark:text-slate-400 text-sm">
                  {filteredTransactions.length} transactions found
                </p>
             </div>
             {/* Mobile Add Button - Visible only on mobile header row */}
             <button 
               onClick={onAdd}
               className="md:hidden bg-blue-600 text-white p-2 rounded-lg shadow-sm active:scale-95 transition-transform"
             >
               <Plus size={20} />
             </button>
           </div>

           <div className="flex items-center space-x-3 w-full md:w-auto">
             {/* Search Bar */}
             <div className="relative w-full md:w-72">
               <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
               <input 
                 type="text" 
                 placeholder="Search symbol, notes..." 
                 value={searchTerm}
                 onChange={(e) => setSearchTerm(e.target.value)}
                 className="w-full pl-10 pr-4 py-2.5 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none text-slate-900 dark:text-white shadow-sm"
               />
             </div>
             {/* Desktop Add Button */}
             <button 
               onClick={onAdd}
               className="hidden md:flex items-center space-x-2 bg-slate-900 dark:bg-white text-white dark:text-slate-900 px-4 py-2.5 rounded-xl font-bold hover:opacity-90 transition-opacity active:scale-95 shadow-sm whitespace-nowrap"
             >
               <Plus size={18} />
               <span>Add New</span>
             </button>
           </div>
        </div>

        {/* Filters Toolbar */}
        <div className="bg-white dark:bg-slate-800 p-4 rounded-2xl border border-slate-200 dark:border-slate-700 shadow-sm flex flex-col lg:flex-row gap-4">
           <div className="flex items-center text-slate-500 font-medium text-sm">
             <Filter size={16} className="mr-2" /> Filters:
           </div>

           <div className="grid grid-cols-2 md:grid-cols-4 lg:flex gap-3 flex-1">
              {/* Type Select */}
              <select 
                value={typeFilter} 
                onChange={(e) => setTypeFilter(e.target.value as any)}
                className="bg-slate-50 dark:bg-slate-900 border border-slate-200 dark:border-slate-700 text-slate-700 dark:text-slate-300 text-sm rounded-lg px-3 py-2 outline-none focus:ring-2 focus:ring-blue-500"
              >
                <option value="ALL">All Types</option>
                {Object.values(TransactionType).map(t => <option key={t} value={t}>{t}</option>)}
              </select>

              {/* Asset Select */}
              <select 
                value={assetClassFilter} 
                onChange={(e) => setAssetClassFilter(e.target.value as any)}
                className="bg-slate-50 dark:bg-slate-900 border border-slate-200 dark:border-slate-700 text-slate-700 dark:text-slate-300 text-sm rounded-lg px-3 py-2 outline-none focus:ring-2 focus:ring-blue-500"
              >
                <option value="ALL">All Assets</option>
                {Object.values(AssetClass).map(a => <option key={a} value={a}>{a}</option>)}
              </select>

              {/* Date Inputs */}
              <div className="relative">
                 <Calendar className="absolute left-2.5 top-1/2 -translate-y-1/2 text-slate-400 pointer-events-none" size={14} />
                 <input 
                    type="date" 
                    value={startDate}
                    onChange={(e) => setStartDate(e.target.value)}
                    className="w-full pl-8 pr-2 py-2 bg-slate-50 dark:bg-slate-900 border border-slate-200 dark:border-slate-700 text-slate-700 dark:text-slate-300 text-sm rounded-lg outline-none focus:ring-2 focus:ring-blue-500"
                    placeholder="Start Date"
                 />
              </div>
              <div className="relative">
                 <Calendar className="absolute left-2.5 top-1/2 -translate-y-1/2 text-slate-400 pointer-events-none" size={14} />
                 <input 
                    type="date" 
                    value={endDate}
                    onChange={(e) => setEndDate(e.target.value)}
                    className="w-full pl-8 pr-2 py-2 bg-slate-50 dark:bg-slate-900 border border-slate-200 dark:border-slate-700 text-slate-700 dark:text-slate-300 text-sm rounded-lg outline-none focus:ring-2 focus:ring-blue-500"
                 />
              </div>
           </div>

           {hasActiveFilters && (
             <button 
               onClick={resetFilters}
               className="flex items-center justify-center px-4 py-2 text-sm text-rose-500 hover:bg-rose-50 dark:hover:bg-rose-900/20 rounded-lg transition-colors font-medium whitespace-nowrap"
             >
               <XCircle size={16} className="mr-1.5" /> Clear
             </button>
           )}
        </div>
      </div>

      {/* Table / List View */}
      <div className="glass-card rounded-2xl overflow-hidden min-h-[400px] bg-white dark:bg-slate-800/50">

        {/* Desktop Table View */}
        <div className="hidden md:block overflow-x-auto">
          <table className="w-full text-left text-sm">
            <thead className="bg-slate-50/80 dark:bg-slate-800/50 text-slate-500 dark:text-slate-400 border-b border-slate-100 dark:border-slate-700">
              <tr>
                <th className="px-6 py-4 font-semibold whitespace-nowrap">
                  <button onClick={() => setSortOrder(prev => prev === 'desc' ? 'asc' : 'desc')} className="flex items-center hover:text-slate-800 dark:hover:text-slate-200">
                     Date <ArrowUpDown size={14} className="ml-1" />
                  </button>
                </th>
                <th className="px-6 py-4 font-semibold">Type</th>
                <th className="px-6 py-4 font-semibold">Asset</th>
                <th className="px-6 py-4 font-semibold text-right">Shares / Ratio</th>
                <th className="px-6 py-4 font-semibold text-right">Price</th>
