export default History;

import React, { useState, useEffect, useMemo } from 'react';
import Layout from './components/Layout';
import Dashboard from './components/Dashboard';
import Holdings from './components/Holdings';
import Reports from './components/Reports';
import History from './components/History';
import { Transaction, TransactionType, AssetClass, Holding, Portfolio } from './types';
import { calculateHoldings, calculatePortfolioHistory, generateId, formatCurrency, formatNumber } from './utils';
import { X, Save, TrendingUp, TrendingDown, DollarSign, Wallet, Calendar, GitFork, AlertCircle, ArrowRight } from 'lucide-react';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState('dashboard');
  const [isAddModalOpen, setIsAddModalOpen] = useState(false);
  const [editingTransaction, setEditingTransaction] = useState<Transaction | null>(null);
  const [isLoading, setIsLoading] = useState(true); // New loading state

  // --- PORTFOLIO MANAGEMENT STATE ---
  const [portfolios, setPortfolios] = useState<Portfolio[]>(() => {
    const saved = localStorage.getItem('portfolios');
    if (saved) return JSON.parse(saved);

    // Migration: If no portfolios exist but we have legacy transactions, create a default one
    const legacyTx = localStorage.getItem('transactions');
    if (legacyTx) {
      return [{ id: 'default', name: 'Main Portfolio' }];
    }

    return [{ id: generateId(), name: 'My First Portfolio' }];
  });

  const [activePortfolioId, setActivePortfolioId] = useState<string>(() => {
    const saved = localStorage.getItem('activePortfolioId');
    // Ensure the saved ID actually exists
    const portfolios = JSON.parse(localStorage.getItem('portfolios') || '[]');
    if (saved && portfolios.some((p: Portfolio) => p.id === saved)) return saved;
    // Fallback to the first portfolio or default
    return portfolios.length > 0 ? portfolios[0].id : 'default';
  });

  // --- DATA STATE (Per Portfolio) ---
  const [transactions, setTransactions] = useState<Transaction[]>([]);
  const [prices, setPrices] = useState<Record<string, number>>({});
  const [financialGoal, setFinancialGoal] = useState<number>(100000);
  const [isDataLoaded, setIsDataLoaded] = useState(false);

  // --- PERSISTENCE: Portfolios List ---
  useEffect(() => {
    localStorage.setItem('portfolios', JSON.stringify(portfolios));
  }, [portfolios]);

  useEffect(() => {
    localStorage.setItem('activePortfolioId', activePortfolioId);
  }, [activePortfolioId]);

  // --- PERSISTENCE: Load Data on Portfolio Switch ---
  useEffect(() => {
    // Start Loading Animation
    setIsLoading(true);
    setIsDataLoaded(false); 

    const loadData = () => {
        const txKey = `transactions_${activePortfolioId}`;
        const pricesKey = `prices_${activePortfolioId}`;
        const goalKey = `financialGoal_${activePortfolioId}`;

        // 1. Transactions
        const savedTx = localStorage.getItem(txKey);
        if (savedTx) {
        setTransactions(JSON.parse(savedTx));
        } else if (activePortfolioId === 'default' && localStorage.getItem('transactions')) {
        setTransactions(JSON.parse(localStorage.getItem('transactions')!));
        } else {
        setTransactions([]);
        }

        // 2. Prices
        const savedPrices = localStorage.getItem(pricesKey);
        if (savedPrices) {
        setPrices(JSON.parse(savedPrices));
        } else if (activePortfolioId === 'default' && localStorage.getItem('prices')) {
        setPrices(JSON.parse(localStorage.getItem('prices')!));
        } else {
        setPrices({});
        }

        // 3. Goal
        const savedGoal = localStorage.getItem(goalKey);
        if (savedGoal) {
        setFinancialGoal(parseFloat(savedGoal));
        } else if (activePortfolioId === 'default' && localStorage.getItem('financialGoal')) {
        setFinancialGoal(parseFloat(localStorage.getItem('financialGoal')!));
        } else {
        setFinancialGoal(100000);
        }

        setIsDataLoaded(true);
        // Stop Loading Animation after a brief delay to make it feel "fetched"
        setTimeout(() => setIsLoading(false), 600);
    };

    // Simulate network delay slightly for better UX feel
    // In a real app, this would be the fetch call duration
    requestAnimationFrame(loadData);

  }, [activePortfolioId]);

  // --- PERSISTENCE: Save Data (Only if loaded) ---
  useEffect(() => {
    if (!isDataLoaded) return;
    localStorage.setItem(`transactions_${activePortfolioId}`, JSON.stringify(transactions));
  }, [transactions, activePortfolioId, isDataLoaded]);

  useEffect(() => {
    if (!isDataLoaded) return;
    localStorage.setItem(`prices_${activePortfolioId}`, JSON.stringify(prices));
  }, [prices, activePortfolioId, isDataLoaded]);

  useEffect(() => {
    if (!isDataLoaded) return;
    localStorage.setItem(`financialGoal_${activePortfolioId}`, financialGoal.toString());
  }, [financialGoal, activePortfolioId, isDataLoaded]);


  // --- CALCULATIONS ---
  const holdings = useMemo(() => calculateHoldings(transactions, prices), [transactions, prices]);
  const chartData = useMemo(() => calculatePortfolioHistory(transactions, prices), [transactions, prices]);

  const investedAmount = transactions.reduce((sum, t) => {
    if (t.type === TransactionType.DEPOSIT) return sum + (t.price || 0);
    if (t.type === TransactionType.WITHDRAW) return sum - (t.price || 0);
    return sum;
  }, 0);

  const cashBalance = useMemo(() => {
    let balance = 0;
    transactions.forEach(t => {
      if (t.type === TransactionType.DEPOSIT) balance += (t.price || 0);
      if (t.type === TransactionType.WITHDRAW) balance -= (t.price || 0);
      if (t.type === TransactionType.BUY) balance -= (t.price! * t.shares!) + (t.fee || 0);
      if (t.type === TransactionType.SELL) balance += (t.price! * t.shares!) - (t.fee || 0);
      if (t.type === TransactionType.DIVIDEND) balance += (t.price || 0);
    });
    return balance;
  }, [transactions]);

  const portfolioValue = holdings.reduce((sum, h) => sum + h.marketValue, 0);

  // --- HANDLERS ---
  const handleOpenAddModal = () => {
    setEditingTransaction(null);
    setIsAddModalOpen(true);
  };

  const handleOpenEditModal = (tx: Transaction) => {
    setEditingTransaction(tx);
    setIsAddModalOpen(true);
  };

  const handleSaveTransaction = (tx: Transaction) => {
    if (editingTransaction) {
      // Update existing
      setTransactions(prev => prev.map(t => t.id === tx.id ? tx : t));
    } else {
      // Add new
      setTransactions(prev => [...prev, tx]);
    }

    // Update prices if applicable
    if ((tx.type === TransactionType.BUY || tx.type === TransactionType.SELL) && tx.symbol && tx.price) {
        setPrices(prev => ({...prev, [tx.symbol!]: tx.price!}));
    }

    setIsAddModalOpen(false);
    setEditingTransaction(null);
  };

  const handleUpdatePrice = (symbol: string, newPrice: number) => {
    setPrices(prev => ({ ...prev, [symbol]: newPrice }));
  };

  const handleDeleteTransaction = (id: string) => {
    setTransactions(prev => prev.filter(t => t.id !== id));
  };

  const handleCreatePortfolio = (name: string) => {
    const newId = generateId();
    const newPortfolio = { id: newId, name };
    setPortfolios([...portfolios, newPortfolio]);
    setActivePortfolioId(newId);
  };

  const handleRenamePortfolio = (id: string, newName: string) => {
    setPortfolios(prev => prev.map(p => p.id === id ? { ...p, name: newName } : p));
  };

  const handleDeletePortfolio = (id: string) => {
    if (portfolios.length <= 1) {
      alert("You must have at least one portfolio.");
      return;
    }
    if (window.confirm("Are you sure? This will delete all transactions in this portfolio permanently.")) {
      localStorage.removeItem(`transactions_${id}`);
      localStorage.removeItem(`prices_${id}`);
      localStorage.removeItem(`financialGoal_${id}`);

      const newPortfolios = portfolios.filter(p => p.id !== id);
      setPortfolios(newPortfolios);

      if (activePortfolioId === id) {
        setActivePortfolioId(newPortfolios[0].id);
      }
    }
  };

  // --- RENDER ---
  return (
    <Layout 
      activeTab={activeTab} 
      setActiveTab={setActiveTab} 
      onOpenAddModal={handleOpenAddModal}
      portfolios={portfolios}
      activePortfolioId={activePortfolioId}
      onSwitchPortfolio={setActivePortfolioId}
      onCreatePortfolio={handleCreatePortfolio}
      onRenamePortfolio={handleRenamePortfolio}
      onDeletePortfolio={handleDeletePortfolio}
    >
      <div key={activePortfolioId} className="h-full">
        {activeTab === 'dashboard' && (
          <Dashboard 
            isLoading={isLoading}
            holdings={holdings} 
            transactions={transactions} 
            financialGoal={financialGoal}
            setFinancialGoal={setFinancialGoal}
            investedAmount={investedAmount}
            cashBalance={cashBalance}
            portfolioValue={portfolioValue}
            chartData={chartData}
          />
        )}
        {activeTab === 'holdings' && (
          <Holdings 
            isLoading={isLoading}
            holdings={holdings} 
            transactions={transactions} 
            onUpdatePrice={handleUpdatePrice} 
          />
        )}
        {activeTab === 'history' && (
          <History 
            isLoading={isLoading}
            transactions={transactions} 
            onDelete={handleDeleteTransaction}
            onEdit={handleOpenEditModal}
            onAdd={handleOpenAddModal}
          />
        )}
        {activeTab === 'reports' && (
           <Reports 
             isLoading={isLoading}
             transactions={transactions} 
             currentPortfolioValue={portfolioValue + cashBalance} 
             chartData={chartData} 
           />
        )}
      </div>

      {/* ADD/EDIT TRANSACTION MODAL */}
      {isAddModalOpen && (
        <div className="fixed inset-0 z-50 flex items-end sm:items-center justify-center sm:p-4">
          <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-sm" onClick={() => setIsAddModalOpen(false)}></div>
          <div className="relative bg-white dark:bg-slate-900 w-full max-w-lg 
                          rounded-t-3xl sm:rounded-3xl border border-slate-200 dark:border-slate-800 
                          shadow-2xl overflow-hidden animate-slide-up flex flex-col
                          max-h-[90dvh] sm:max-h-[85vh]">
            <AddTransactionForm 
              onClose={() => setIsAddModalOpen(false)} 
              onSave={handleSaveTransaction} 
              cashBalance={cashBalance}
              holdings={holdings}
              transactions={transactions}
              initialData={editingTransaction}
            />
          </div>
        </div>
      )}
    </Layout>
  );
};

interface AddTransactionFormProps {
  onClose: () => void;
  onSave: (t: Transaction) => void;
  cashBalance: number;
  holdings: Holding[];
  transactions: Transaction[];
  initialData: Transaction | null;
}

const AddTransactionForm: React.FC<AddTransactionFormProps> = ({ onClose, onSave, cashBalance, holdings, transactions, initialData }) => {
  const [type, setType] = useState<TransactionType>(TransactionType.BUY);
  const [date, setDate] = useState(new Date().toISOString().split('T')[0]);
  const [symbol, setSymbol] = useState('');
  const [shares, setShares] = useState('');
  const [price, setPrice] = useState('');
  const [fee, setFee] = useState('');
  const [assetClass, setAssetClass] = useState<AssetClass>(AssetClass.STOCK);
  const [exchangeRate, setExchangeRate] = useState(''); 
  const [notes, setNotes] = useState('');
  const [error, setError] = useState<string | null>(null);

  // Populate form if initialData exists (Edit Mode)
  useEffect(() => {
    if (initialData) {
      setType(initialData.type);
      setDate(initialData.date);
      setSymbol(initialData.symbol || '');
      setShares(initialData.shares?.toString() || '');
      setPrice(initialData.price?.toString() || '');
      setFee(initialData.fee?.toString() || '');
      setAssetClass(initialData.assetClass || AssetClass.STOCK);
      setExchangeRate(initialData.exchangeRate?.toString() || '');
      setNotes(initialData.notes || '');
    }
  }, [initialData]);

  const isTrade = type === TransactionType.BUY || type === TransactionType.SELL || type === TransactionType.DIVIDEND;
  const isSplit = type === TransactionType.SPLIT;
  const isFunding = type === TransactionType.DEPOSIT || type === TransactionType.WITHDRAW;

  // --- VALIDATION & SUMMARY LOGIC ---
  const numShares = parseFloat(shares) || 0;
  const numPrice = parseFloat(price) || 0;
  const numFee = parseFloat(fee) || 0;
  const totalValue = isSplit ? 0 : (isTrade ? numShares * numPrice : numPrice);

  // Determine Impact and Validate
  useEffect(() => {
    setError(null);

    // 1. Basic numeric validation
    if (numShares < 0 || numPrice < 0 || numFee < 0) {
      setError("Values cannot be negative.");
      return;
    }

    // 2. Duplicate Check
    // We check if there is an *identical* transaction already, excluding the one currently being edited.
    const isDuplicate = transactions.some(t => {
      // If we are editing, ignore the transaction with the same ID as initialData
      if (initialData && t.id === initialData.id) return false;

      // Check fields for duplication
      return (
        t.date === date &&
        t.type === type &&
        (t.symbol || '') === (symbol.toUpperCase() || '') &&
        (t.shares || 0) === numShares &&
        (t.price || 0) === numPrice
      );
    });

    if (isDuplicate) {
      setError("A duplicate transaction already exists.");
      return;
    }

    // 3. Share Availability Validation (For SELL)
    if (type === TransactionType.SELL && symbol) {
      const holding = holdings.find(h => h.symbol === symbol.toUpperCase());
      let availableShares = holding ? holding.shares : 0;

      // If we are editing a past SELL, we need to add those shares back to the "available" pool
      // to check if the NEW amount is valid.
      // Logic: Current Holding + Shares from this specific SELL transaction (before edit).
      if (initialData && initialData.type === TransactionType.SELL && initialData.symbol === symbol.toUpperCase()) {
         availableShares += (initialData.shares || 0);
      }

      if (numShares > availableShares + 0.000001) { // Epsilon for float math
         setError(`Insufficient shares. You own ${formatNumber(availableShares, 4)} ${symbol}.`);
         return;
      }
    }

    // 4. Cash Availability Validation (For BUY and WITHDRAW)
    // We validate against the *current* cash balance.
    // If editing, we revert the impact of the *current* version of the transaction to find "Available Cash".
    if (type === TransactionType.BUY || type === TransactionType.WITHDRAW) {
       let availableCash = cashBalance;

       // Add back resources consumed by the transaction we are editing
       if (initialData) {
         if (initialData.type === TransactionType.BUY) {
           availableCash += ((initialData.shares || 0) * (initialData.price || 0)) + (initialData.fee || 0);
         } else if (initialData.type === TransactionType.WITHDRAW) {
           availableCash += (initialData.price || 0);
         } else if (initialData.type === TransactionType.DEPOSIT) {
           availableCash -= (initialData.price || 0); // If we change a deposit to a withdraw, we lose that deposit
         } else if (initialData.type === TransactionType.SELL) {
           availableCash -= ((initialData.shares || 0) * (initialData.price || 0)) - (initialData.fee || 0);
         }
       }

       const needed = totalValue + numFee;

       if (needed > availableCash + 0.01) { // 1 cent tolerance
         setError(`Insufficient funds. Available: ${formatCurrency(availableCash)}.`);
         return;
       }
    }

  }, [type, totalValue, cashBalance, numShares, numPrice, numFee, initialData, transactions, date, symbol, holdings]);

  // Projected Cash Calculation for Display
  let projectedCash = cashBalance;
  // This is purely for display, approximate logic
  if (type === TransactionType.BUY) projectedCash = cashBalance - totalValue - numFee;
  else if (type === TransactionType.SELL) projectedCash = cashBalance + totalValue - numFee;
  else if (type === TransactionType.DEPOSIT || type === TransactionType.DIVIDEND) projectedCash = cashBalance + totalValue;
  else if (type === TransactionType.WITHDRAW) projectedCash = cashBalance - totalValue;


  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (error) return;
    if ((isTrade || isFunding) && totalValue === 0) {
      setError("Amount must be greater than 0");
      return;
    }

    // Check required fields again just in case
    if ((isTrade) && !symbol) {
      setError("Symbol is required");
      return;
    }

    onSave({
      id: initialData ? initialData.id : generateId(), // Use existing ID if editing
      date,
      type,
      symbol: (type === 'DEPOSIT' || type === 'WITHDRAW') ? undefined : symbol.toUpperCase(),
      shares: shares ? parseFloat(shares) : undefined,
      price: type === TransactionType.SPLIT ? 0 : parseFloat(price),
      fee: (fee && (type === TransactionType.BUY || type === TransactionType.SELL)) ? parseFloat(fee) : undefined,
      assetClass: (type === 'DEPOSIT' || type === 'WITHDRAW') ? AssetClass.CASH : assetClass,
      exchangeRate: exchangeRate ? parseFloat(exchangeRate) : 1, 
      notes: notes ? notes : undefined
    });
  };

  return (
    <>
      {/* Header */}
      <div className="shrink-0 flex justify-between items-center p-4 border-b border-slate-100 dark:border-slate-800 bg-slate-50/50 dark:bg-slate-900/50">
        <div>
          <h3 className="text-lg font-display font-bold text-slate-900 dark:text-white">
            {initialData ? 'Edit Transaction' : 'New Transaction'}
          </h3>
          <p className="text-xs text-slate-500">{initialData ? 'Update details' : 'Record your investment activity'}</p>
        </div>
        <button onClick={onClose} className="p-2 rounded-full hover:bg-slate-200 dark:hover:bg-slate-800 text-slate-400 hover:text-slate-600 dark:hover:text-slate-200 transition-colors">
          <X size={20} />
        </button>
      </div>

      {/* Scrollable Form Area */}
      <form onSubmit={handleSubmit} className="flex-1 overflow-y-auto min-h-0 p-4 space-y-4 custom-scrollbar">
        {/* ... form content ... */}
        {/* Transaction Type Selector (Compact Grid) */}
        <div>
           <label className="block text-[10px] font-bold text-slate-500 uppercase tracking-wider mb-1.5">Transaction Type</label>
           <div className="grid grid-cols-3 sm:grid-cols-6 gap-2">
              {[
                { id: TransactionType.BUY, icon: <TrendingUp size={14} />, label: 'Buy', color: 'blue' },
                { id: TransactionType.SELL, icon: <TrendingDown size={14} />, label: 'Sell', color: 'rose' },
                { id: TransactionType.DIVIDEND, icon: <DollarSign size={14} />, label: 'Div', color: 'emerald' },
                { id: TransactionType.SPLIT, icon: <GitFork size={14} />, label: 'Split', color: 'purple' },
                { id: TransactionType.DEPOSIT, icon: <Wallet size={14} />, label: 'In', color: 'indigo' },
                { id: TransactionType.WITHDRAW, icon: <Wallet size={14} />, label: 'Out', color: 'orange' },
              ].map((t) => (
                <button
                  key={t.id}
                  type="button"
                  onClick={() => setType(t.id)}
                  className={`flex flex-col items-center justify-center p-2 rounded-lg border transition-all duration-200 ${
                    type === t.id
                      ? `bg-${t.color}-50 border-${t.color}-500 text-${t.color}-700 dark:bg-${t.color}-900/30 dark:border-${t.color}-500 dark:text-${t.color}-300 ring-1 ring-${t.color}-500 shadow-sm`
                      : 'bg-white dark:bg-slate-800 border-slate-200 dark:border-slate-700 text-slate-500 hover:border-slate-300 dark:hover:border-slate-600'
                  }`}
                >
                  <div className="mb-0.5">{t.icon}</div>
                  <span className="text-[10px] font-bold">{t.label}</span>
                </button>
              ))}
           </div>
        </div>

        {/* Date Input */}
        <div>
           <label className="block text-[10px] font-bold text-slate-500 uppercase tracking-wider mb-1.5">Date</label>
           <div className="relative">
             <Calendar className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={16} />
             <input 
              type="date" 
              required
              value={date}
              onChange={(e) => setDate(e.target.value)}
              className="w-full pl-9 pr-3 py-2.5 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl text-slate-900 dark:text-white focus:ring-2 focus:ring-blue-500 focus:border-transparent outline-none transition-all font-medium text-sm"
            />
           </div>
        </div>

        {(isTrade || isSplit) && (
          <div className="grid grid-cols-2 gap-3">
            <div className="col-span-1">
               <label className="block text-[10px] font-bold text-slate-500 uppercase tracking-wider mb-1.5">Symbol</label>
               <input 
                type="text" 
                required
                placeholder="AAPL"
                value={symbol}
                onChange={(e) => setSymbol(e.target.value)}
                className="w-full px-3 py-2.5 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl text-slate-900 dark:text-white focus:ring-2 focus:ring-blue-500 outline-none uppercase font-bold tracking-wide text-sm"
              />
            </div>
             <div className="col-span-1">
              <label className="block text-[10px] font-bold text-slate-500 uppercase tracking-wider mb-1.5">Class</label>
              <select 
                value={assetClass} 
                onChange={(e) => setAssetClass(e.target.value as AssetClass)}
                className="w-full px-3 py-2.5 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl text-slate-900 dark:text-white focus:ring-2 focus:ring-blue-500 outline-none appearance-none text-sm"
              >
                {Object.values(AssetClass).filter(a => a !== AssetClass.CASH).map(a => <option key={a} value={a}>{a}</option>)}
              </select>
            </div>
          </div>
        )}

        <div className="grid grid-cols-2 gap-3">
           {(isTrade || isSplit) && (
            <div className={isSplit ? "col-span-2" : "col-span-1"}>
              <label className="block text-[10px] font-bold text-slate-500 uppercase tracking-wider mb-1.5">
                {isSplit ? "Split Ratio (e.g. 2 for 2:1)" : "Shares"}
              </label>
              <input 
                type="number" 
                step="any"
                min="0"
                required
                placeholder={isSplit ? "2" : "0.00"}
                value={shares}
                onChange={(e) => setShares(e.target.value)}
                className="w-full px-3 py-2.5 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl text-slate-900 dark:text-white focus:ring-2 focus:ring-blue-500 outline-none font-mono text-sm"
              />
              {isSplit && <p className="text-[10px] text-slate-500 mt-1">For a 2:1 split, enter 2.</p>}
            </div>
           )}
           {!isSplit && (
             <div className={!isTrade ? "col-span-2" : ""}>
               <label className="block text-[10px] font-bold text-slate-500 uppercase tracking-wider mb-1.5">
                 {isTrade ? "Price / Share" : "Amount ($)"}
               </label>
                <input 
                  type="number" 
                  step="any"
                  min="0"
                  required
                  placeholder="0.00"
                  value={price}
                  onChange={(e) => setPrice(e.target.value)}
                  className="w-full px-3 py-2.5 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl text-slate-900 dark:text-white focus:ring-2 focus:ring-blue-500 outline-none font-mono text-sm"
                />
             </div>
           )}
        </div>

        {/* Fee Field for Buy/Sell */}
        {(type === TransactionType.BUY || type === TransactionType.SELL) && (
           <div>
              <label className="block text-[10px] font-bold text-slate-500 uppercase tracking-wider mb-1.5">
                Transaction Fee (Optional)
              </label>
              <input 
                type="number" 
                step="any"
                min="0"
                placeholder="0.00"
                value={fee}
                onChange={(e) => setFee(e.target.value)}
                className="w-full px-3 py-2.5 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl text-slate-900 dark:text-white focus:ring-2 focus:ring-blue-500 outline-none font-mono text-sm"
              />
           </div>
        )}

        {isFunding && (
           <div className="bg-blue-50 dark:bg-slate-800/50 p-3 rounded-xl border border-blue-100 dark:border-slate-700">
             <label className="block text-[10px] font-bold text-slate-500 uppercase tracking-wider mb-1.5">
               Exchange Rate (Optional)
             </label>
              <div className="flex items-center space-x-2">
                <input 
                  type="number" 
                  step="any"
                  min="0"
                  placeholder="1.00"
                  value={exchangeRate}
                  onChange={(e) => setExchangeRate(e.target.value)}
                  className="flex-1 px-3 py-2 bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-600 rounded-lg text-slate-900 dark:text-white focus:ring-2 focus:ring-blue-500 outline-none font-mono text-right text-sm"
                />
                <span className="text-xs font-medium text-slate-500">Local / USD</span>
              </div>
           </div>
        )}

        {/* Notes Field */}
        <div>
           <label className="block text-[10px] font-bold text-slate-500 uppercase tracking-wider mb-1.5">Notes (Optional)</label>
           <textarea
             rows={2}
             placeholder="Add a memo..."
             value={notes}
             onChange={(e) => setNotes(e.target.value)}
             className="w-full px-3 py-2.5 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl text-slate-900 dark:text-white focus:ring-2 focus:ring-blue-500 outline-none resize-none font-medium text-sm"
           />
        </div>
      </form>

      {/* SUMMARY & FOOTER (Fixed at bottom) */}
      <div className="shrink-0 bg-slate-50/80 dark:bg-slate-800/80 border-t border-slate-200 dark:border-slate-700 backdrop-blur-sm">
         <div className="px-4 py-2 sm:px-6 sm:py-3">
             {error ? (
               <div className="bg-red-50 dark:bg-red-900/20 border border-red-200 dark:border-red-800 rounded-lg p-2.5 flex items-start space-x-2 text-red-600 dark:text-red-400 animate-slide-up">
                 <AlertCircle size={16} className="shrink-0 mt-0.5" />
                 <div className="text-xs font-semibold">{error}</div>
               </div>
             ) : (
               <div className="flex justify-between items-center text-sm">
                  <div className="flex flex-col">
                      <span className="text-xs text-slate-500 dark:text-slate-400 font-medium">Total Value</span>
                      <span className="text-lg font-bold font-display text-slate-900 dark:text-white leading-tight">
                        {formatCurrency(totalValue)}
                      </span>
                  </div>
                  {/* Compact impact view for mobile */}
                   <div className="text-right">
                       <span className="text-xs text-slate-500">Cash After</span>
                       <div className={`font-bold text-sm ${projectedCash < 0 ? 'text-red-500' : 'text-slate-700 dark:text-slate-300'}`}>
                         {formatCurrency(projectedCash)}
                       </div>
                   </div>
               </div>
             )}
         </div>

          <div className="p-4 pt-2 border-t border-slate-100 dark:border-slate-800 bg-white dark:bg-slate-900">
            <button 
              onClick={handleSubmit}
              disabled={!!error}
              className={`w-full font-bold py-3 rounded-xl shadow-lg transition-all flex items-center justify-center space-x-2 text-base ${
                error 
                  ? 'bg-slate-300 dark:bg-slate-700 text-slate-500 cursor-not-allowed' 
                  : 'bg-slate-900 dark:bg-blue-600 hover:opacity-90 text-white shadow-slate-900/20 dark:shadow-blue-600/20 active:scale-95'
              }`}
            >
              <Save size={18} />
              <span>{initialData ? 'Update Transaction' : 'Save Transaction'}</span>
            </button>
          </div>
      </div>
    </>
  );
};

export default App;

import React, { useMemo } from 'react';
import { Holding, Transaction, ChartDataPoint } from '../types';
import { formatCurrency, formatNumber } from '../utils';
import { 
  AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, 
  PieChart, Pie, Cell
} from 'recharts';
import { ArrowUpRight, ArrowDownRight, TrendingUp, Wallet, Target, Activity } from 'lucide-react';
import { DashboardSkeleton } from './LoadingSkeletons';

interface DashboardProps {
  holdings: Holding[];
  transactions: Transaction[];
  financialGoal: number;
  setFinancialGoal: (val: number) => void;
  investedAmount: number;
  cashBalance: number;
  portfolioValue: number;
  chartData: ChartDataPoint[];
  isLoading?: boolean;
}

const COLORS = ['#3b82f6', '#10b981', '#f59e0b', '#ef4444', '#8b5cf6', '#ec4899'];

const Dashboard: React.FC<DashboardProps> = ({ 
  holdings, transactions, financialGoal, setFinancialGoal, investedAmount, portfolioValue, cashBalance, chartData, isLoading 
}) => {
  const totalNetWorth = portfolioValue + cashBalance;
  const totalUnrealizedPL = holdings.reduce((sum, h) => sum + h.unrealizedPL, 0);
  const totalPLPercent = investedAmount > 0 ? (totalUnrealizedPL / investedAmount) * 100 : 0;

  // Prepare data for Allocation Chart
  const allocationData = holdings
    .filter(h => h.marketValue > 0)
    .map(h => ({ name: h.assetClass, value: h.marketValue }))
    .reduce((acc: any[], curr) => {
      const existing = acc.find(item => item.name === curr.name);
      if (existing) {
        existing.value += curr.value;
      } else {
        acc.push({ ...curr });
      }
      return acc;
    }, []);

  // --- CAGR / PERFORMANCE CALCULATION ---
  const performanceMetric = useMemo(() => {
    if (investedAmount <= 0 || transactions.length === 0) {
      return { label: 'Total Return', value: 0 };
    }

    // Find first transaction date
    let minDate = new Date().getTime();
    let hasTx = false;

    transactions.forEach(t => {
       const txDate = new Date(t.date).getTime();
       if (txDate < minDate) {
         minDate = txDate;
         hasTx = true;
       }
    });

    if (!hasTx) return { label: 'Total Return', value: 0 };

    const now = new Date().getTime();
    const daysElapsed = (now - minDate) / (1000 * 60 * 60 * 24);
    const years = daysElapsed / 365.25;

    // If invested less than 1 year, show Absolute Return instead of CAGR to avoid crazy annualized numbers
    if (years < 1) {
       const absReturn = ((totalNetWorth - investedAmount) / investedAmount) * 100;
       return { label: 'Total Return (Abs)', value: absReturn };
    } else {
       // CAGR Formula: (End Value / Start Value)^(1/n) - 1
       // We use InvestedAmount as the proxy for Start Value (Principal)
       if (totalNetWorth <= 0) return { label: 'Annual Growth (CAGR)', value: -100 };

       const cagr = (Math.pow(totalNetWorth / investedAmount, 1 / years) - 1) * 100;
       return { label: 'Annual Growth (CAGR)', value: cagr };
    }
  }, [transactions, investedAmount, totalNetWorth]);

  if (isLoading) {
    return <DashboardSkeleton />;
  }

  return (
    <div className="space-y-8 animate-fade-in">
      {/* Header */}
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
           <h2 className="text-3xl font-display font-bold text-slate-900 dark:text-white">Dashboard</h2>
           <p className="text-slate-500 dark:text-slate-400 mt-1">Overview of your financial performance</p>
        </div>
        <div className="flex items-center space-x-2 text-sm text-slate-500 dark:text-slate-400 bg-white dark:bg-slate-800 px-3 py-1.5 rounded-full shadow-sm border border-slate-200 dark:border-slate-700 animate-slide-in-right">
           <div className="w-2 h-2 rounded-full bg-emerald-500 animate-pulse"></div>
           <span>Live Market Data</span>
        </div>
      </div>

      {/* Overview Cards */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        {/* Net Worth Card - Primary */}
        <div className="glass-card relative overflow-hidden rounded-2xl p-6 group animate-slide-up" style={{ animationDelay: '0ms' }}>
          <div className="absolute top-0 right-0 p-4 opacity-10 group-hover:opacity-20 transition-opacity animate-float">
            <Wallet size={80} />
          </div>
          <div className="relative z-10">
            <p className="text-sm font-medium text-slate-500 dark:text-slate-400 mb-2">Net Worth</p>
            <h3 className="text-3xl font-display font-bold text-slate-900 dark:text-white tracking-tight">
              {formatCurrency(totalNetWorth)}
            </h3>
            <div className="mt-4 flex items-center text-xs font-medium text-slate-500 dark:text-slate-400">
              <span className="bg-slate-100 dark:bg-slate-800 px-2 py-1 rounded-md">Cash: {formatCurrency(cashBalance)}</span>
            </div>
          </div>
          <div className="absolute bottom-0 left-0 w-full h-1 bg-gradient-to-r from-blue-500 to-indigo-500"></div>
        </div>

        {/* P/L Card */}
        <div className="glass-card rounded-2xl p-6 animate-slide-up" style={{ animationDelay: '100ms' }}>
          <div className="flex justify-between items-start mb-2">
            <p className="text-sm font-medium text-slate-500 dark:text-slate-400">Unrealized P/L</p>
            <div className={`p-1.5 rounded-lg ${totalUnrealizedPL >= 0 ? 'bg-emerald-500/10 text-emerald-600 dark:text-emerald-400' : 'bg-rose-500/10 text-rose-600 dark:text-rose-400'}`}>
              {totalUnrealizedPL >= 0 ? <ArrowUpRight size={18} /> : <ArrowDownRight size={18} />}
            </div>
          </div>
          <h3 className={`text-3xl font-display font-bold tracking-tight ${totalUnrealizedPL >= 0 ? 'text-emerald-600 dark:text-emerald-400' : 'text-rose-600 dark:text-rose-400'}`}>
            {totalUnrealizedPL >= 0 ? '+' : ''}{formatCurrency(totalUnrealizedPL)}
          </h3>
          <p className={`mt-2 text-sm font-medium ${totalPLPercent >= 0 ? 'text-emerald-600 dark:text-emerald-400' : 'text-rose-600 dark:text-rose-400'}`}>
            {totalPLPercent >= 0 ? '▲' : '▼'} {Math.abs(totalPLPercent).toFixed(2)}% All Time
          </p>
        </div>

        {/* Goal Card */}
        <div className="glass-card rounded-2xl p-6 flex flex-col justify-between animate-slide-up" style={{ animationDelay: '200ms' }}>
           <div className="flex justify-between items-start">
            <div>
              <p className="text-sm font-medium text-slate-500 dark:text-slate-400">Goal Progress</p>
              <h3 className="text-2xl font-display font-bold text-slate-900 dark:text-white mt-1">
                {financialGoal > 0 ? ((totalNetWorth / financialGoal) * 100).toFixed(1) : 0}%
              </h3>
            </div>
            <button 
              onClick={() => {
                const newGoal = prompt("Set Financial Goal ($):", financialGoal.toString());
                if (newGoal && !isNaN(Number(newGoal))) setFinancialGoal(Number(newGoal));
              }}
              className="text-slate-400 hover:text-blue-500 transition-colors p-1 hover:bg-slate-100 dark:hover:bg-slate-700 rounded-lg"
            >
              <Target size={20} />
            </button>
          </div>
          <div className="mt-4">
            <div className="w-full bg-slate-100 dark:bg-slate-700 rounded-full h-2 overflow-hidden">
              <div 
                className="bg-gradient-to-r from-purple-500 to-pink-500 h-2 rounded-full transition-all duration-1000 ease-out animate-pulse-slow" 
                style={{ width: `${Math.min((totalNetWorth / financialGoal) * 100, 100)}%` }}
              ></div>
            </div>
            <p className="text-xs text-slate-400 mt-2 text-right">Target: {formatCurrency(financialGoal)}</p>
          </div>
        </div>

        {/* Dynamic Performance Card (CAGR or Abs Return) */}
        <div className="glass-card rounded-2xl p-6 relative overflow-hidden animate-slide-up" style={{ animationDelay: '300ms' }}>
          <div className="flex justify-between items-start">
             <div>
               <p className="text-sm font-medium text-slate-500 dark:text-slate-400">{performanceMetric.label}</p>
               <h3 className={`text-3xl font-display font-bold mt-2 ${performanceMetric.value >= 0 ? 'text-emerald-600 dark:text-emerald-400' : 'text-rose-600 dark:text-rose-400'}`}>
                 {performanceMetric.value > 0 ? '+' : ''}{formatNumber(performanceMetric.value, 2)}%
               </h3>
             </div>
             <Activity className={performanceMetric.value >= 0 ? "text-emerald-500" : "text-rose-500"} size={24} />
          </div>
          <div className="mt-4 text-xs text-slate-400">
             {performanceMetric.label === 'Annual Growth (CAGR)' ? 'Compound Annual Growth Rate' : 'Absolute Return on Investment'}
          </div>
          <div className="absolute -bottom-4 -right-4 opacity-5 animate-float" style={{ animationDelay: '1s' }}>
             <Activity size={100} />
          </div>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        {/* Wealth Growth Chart */}
        <div className="lg:col-span-2 glass-card p-6 rounded-2xl animate-zoom-in" style={{ animationDelay: '400ms' }}>
          <div className="flex items-center justify-between mb-6">
            <h3 className="text-lg font-bold font-display text-slate-900 dark:text-white">Wealth Growth</h3>
             <div className="flex items-center space-x-4 text-xs font-medium">
                <div className="flex items-center"><div className="w-2 h-2 rounded-full bg-blue-500 mr-2"></div> Market Value</div>
                <div className="flex items-center"><div className="w-2 h-2 rounded-full bg-slate-400 mr-2 opacity-50"></div> Net Invested</div>
             </div>
          </div>

          <div className="h-[350px] w-full">
            {chartData.length > 0 ? (
              <ResponsiveContainer width="100%" height="100%">
              <AreaChart data={chartData} margin={{ top: 10, right: 10, left: 0, bottom: 0 }}>
                <defs>
                  <linearGradient id="colorValue" x1="0" y1="0" x2="0" y2="1">
                    <stop offset="5%" stopColor="#3b82f6" stopOpacity={0.3}/>
                    <stop offset="95%" stopColor="#3b82f6" stopOpacity={0}/>
                  </linearGradient>
                </defs>
                <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" opacity={0.2} vertical={false} />
                <XAxis 
                  dataKey="date" 
                  axisLine={false} 
                  tickLine={false} 
                  tick={{fill: '#94a3b8', fontSize: 11, fontWeight: 500}} 
                  dy={15} 
                  minTickGap={40} 
                />
                <YAxis 
                  axisLine={false} 
                  tickLine={false} 
                  tick={{fill: '#94a3b8', fontSize: 11, fontWeight: 500}} 
                  tickFormatter={(val) => val >= 1000 ? (val/1000).toFixed(0) + 'k' : val}
                />
                <Tooltip 
                  contentStyle={{ 
                    backgroundColor: 'rgba(15, 23, 42, 0.9)', 
                    backdropFilter: 'blur(8px)',
                    border: '1px solid rgba(255,255,255,0.1)', 
                    borderRadius: '12px', 
                    color: '#fff',
                    boxShadow: '0 10px 15px -3px rgba(0, 0, 0, 0.1)'
                  }}
                  itemStyle={{ color: '#fff', fontSize: '12px' }}
                  labelStyle={{ color: '#94a3b8', fontSize: '12px', marginBottom: '8px' }}
                  formatter={(value: number) => [formatCurrency(value), '']}
                />
                <Area 
                  type="monotone" 
                  dataKey="value" 
                  stroke="#3b82f6" 
                  strokeWidth={3} 
                  fillOpacity={1} 
                  fill="url(#colorValue)" 
                  activeDot={{ r: 6, strokeWidth: 0, fill: '#fff' }}
                  isAnimationActive={true}
                  animationDuration={1500}
                />
                <Area 
                  type="monotone" 
                  dataKey="invested" 
                  stroke="#94a3b8" 
                  strokeDasharray="5 5" 
                  strokeWidth={2} 
                  fill="transparent" 
                  isAnimationActive={true}
                  animationDuration={1500}
                />
              </AreaChart>
            </ResponsiveContainer>
            ) : (
              <div className="flex h-full flex-col items-center justify-center text-slate-400 bg-slate-50/50 dark:bg-slate-800/50 rounded-xl border border-dashed border-slate-200 dark:border-slate-700">
                <Activity className="mb-2 opacity-50" size={32} />
                <p>No transaction data available yet.</p>
              </div>
            )}
          </div>
        </div>

        {/* Allocation */}
        <div className="glass-card p-6 rounded-2xl flex flex-col animate-zoom-in" style={{ animationDelay: '500ms' }}>
          <h3 className="text-lg font-bold font-display text-slate-900 dark:text-white mb-2">Asset Allocation</h3>
          <p className="text-sm text-slate-500 mb-6">Distribution by asset class</p>

          <div className="flex-1 flex flex-col justify-center">
            <div className="h-[220px] w-full relative">
              {allocationData.length > 0 ? (
                 <ResponsiveContainer width="100%" height="100%">
                  <PieChart>
                    <Pie
                      data={allocationData}
                      cx="50%"
                      cy="50%"
                      innerRadius={60}
                      outerRadius={80}
                      paddingAngle={5}
                      dataKey="value"
                      cornerRadius={6}
                      isAnimationActive={true}
                      animationDuration={1000}
                    >
                      {allocationData.map((entry, index) => (
                        <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} strokeWidth={0} />
                      ))}
                    </Pie>
                    <Tooltip 
                       contentStyle={{ 
                        backgroundColor: 'rgba(15, 23, 42, 0.9)', 
                        border: 'none', 
                        borderRadius: '8px', 
                        color: '#fff',
                        fontSize: '12px'
                      }}
                      formatter={(value: number) => formatCurrency(value)} 
                    />
                  </PieChart>
                </ResponsiveContainer>
              ) : (
                <div className="absolute inset-0 flex items-center justify-center text-slate-400 text-sm">
                   Add assets to see breakdown
                </div>
              )}
              {/* Center Text */}
              {allocationData.length > 0 && (
                 <div className="absolute inset-0 flex flex-col items-center justify-center pointer-events-none animate-fade-in">
                    <span className="text-xs text-slate-400 font-medium uppercase">Total</span>
                    <span className="text-lg font-bold text-slate-900 dark:text-white">{formatNumber(allocationData.length, 0)} Assets</span>
                 </div>
              )}
            </div>
          </div>

          <div className="mt-6 space-y-3">
             {allocationData.slice(0, 4).map((entry, idx) => (
               <div key={idx} className="flex justify-between items-center text-sm p-2 rounded-lg hover:bg-slate-50 dark:hover:bg-slate-800/50 transition-colors cursor-default">
                 <div className="flex items-center">
                   <div className="w-3 h-3 rounded-full mr-3 animate-pulse" style={{ backgroundColor: COLORS[idx % COLORS.length] }}></div>
                   <span className="text-slate-600 dark:text-slate-300 font-medium">{entry.name}</span>
                 </div>
                 <div className="flex items-center space-x-3">
                    <span className="text-slate-900 dark:text-white font-bold">
                      {((entry.value / portfolioValue) * 100).toFixed(1)}%
                    </span>
                    <span className="text-slate-400 text-xs w-16 text-right">{formatCurrency(entry.value).split('.')[0]}</span>
                 </div>
               </div>
             ))}
          </div>
        </div>
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState } from 'react';
import { Holding, Transaction } from '../types';
import { formatCurrency, formatNumber } from '../utils';
import { RefreshCw, Briefcase } from 'lucide-react';
import { LineChart, Line, ResponsiveContainer, YAxis } from 'recharts';
import { HoldingsSkeleton } from './LoadingSkeletons';

interface HoldingsProps {
  holdings: Holding[];
  transactions: Transaction[];
  onUpdatePrice: (symbol: string, newPrice: number) => void;
  isLoading?: boolean;
}

const Holdings: React.FC<HoldingsProps> = ({ holdings, transactions, onUpdatePrice, isLoading }) => {
  const [editingPrice, setEditingPrice] = useState<string | null>(null);
  const [tempPrice, setTempPrice] = useState<string>('');

  const handleEditClick = (symbol: string, currentPrice: number) => {
    setEditingPrice(symbol);
    setTempPrice(currentPrice.toString());
  };

  const handleSavePrice = (symbol: string) => {
    const price = parseFloat(tempPrice);
    if (!isNaN(price) && price >= 0) {
      onUpdatePrice(symbol, price);
    }
    setEditingPrice(null);
  };

  if (isLoading) {
    return <HoldingsSkeleton />;
  }

  return (
    <div className="space-y-6 animate-fade-in">
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
           <h2 className="text-2xl font-display font-bold text-slate-900 dark:text-white">Portfolio Holdings</h2>
           <p className="text-slate-500 dark:text-slate-400 text-sm">Manage your assets and update prices</p>
        </div>
        <button className="text-sm bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 text-slate-700 dark:text-slate-300 px-4 py-2.5 rounded-xl font-semibold shadow-sm hover:bg-slate-50 dark:hover:bg-slate-700 transition-colors flex items-center space-x-2 active:scale-95 duration-200">
          <Briefcase size={16} />
          <span>Rebalance Analysis</span>
        </button>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">
        {holdings.map((h, index) => {
          // Calculate sparkline data
          const sparklineData = transactions
            .filter(t => t.symbol === h.symbol && (t.type === 'BUY' || t.type === 'SELL') && (t.price || 0) > 0)
            .sort((a, b) => new Date(a.date).getTime() - new Date(b.date).getTime())
            .map((t, i) => ({ i, price: t.price! }));

          // Add current price as last point if distinct
          if (h.currentPrice > 0 && (sparklineData.length === 0 || sparklineData[sparklineData.length-1].price !== h.currentPrice)) {
              sparklineData.push({ i: sparklineData.length, price: h.currentPrice });
          }

          const isUp = sparklineData.length > 1 ? sparklineData[sparklineData.length - 1].price >= sparklineData[0].price : true;
          const strokeColor = isUp ? '#10b981' : '#ef4444';

          return (
            <div 
              key={h.symbol} 
              className="glass-card rounded-2xl p-5 hover:border-blue-300 dark:hover:border-blue-700 transition-all duration-300 group relative animate-slide-up"
              style={{ animationDelay: `${index * 50}ms`, animationFillMode: 'both' }}
            >

              {/* Header */}
              <div className="flex justify-between items-start mb-2">
                <div className="flex items-start space-x-3">
                   <div className="w-10 h-10 rounded-lg bg-slate-100 dark:bg-slate-800 flex items-center justify-center font-bold text-slate-700 dark:text-slate-300 text-sm border border-slate-200 dark:border-slate-700 shrink-0 transition-transform group-hover:scale-110 duration-300">
                      {h.symbol.substring(0, 2)}
                   </div>
                   <div className="overflow-hidden">
                      <h3 className="font-bold text-slate-900 dark:text-white leading-tight truncate">{h.symbol}</h3>
                      <p className="text-xs text-slate-500 dark:text-slate-400 truncate max-w-[100px]">{h.name}</p>
                   </div>
                </div>
                <span className="px-2.5 py-1 text-[10px] font-bold uppercase tracking-wide bg-slate-100 dark:bg-slate-800 text-slate-500 dark:text-slate-400 rounded-md border border-slate-200 dark:border-slate-700">
                  {h.assetClass}
                </span>
              </div>

              {/* Sparkline */}
              <div className="h-10 w-full mb-3 -ml-1 opacity-80 group-hover:opacity-100 transition-opacity">
                 {sparklineData.length > 1 ? (
                   <ResponsiveContainer width="100%" height="100%">
                     <LineChart data={sparklineData}>
                       <Line 
                         type="monotone" 
                         dataKey="price" 
                         stroke={strokeColor} 
                         strokeWidth={2} 
                         dot={false} 
                         isAnimationActive={true}
                         animationDuration={1500}
                       />
                       <YAxis domain={['dataMin', 'dataMax']} hide />
                     </LineChart>
                   </ResponsiveContainer>
                 ) : (
                   <div className="h-full flex items-center text-xs text-slate-300 px-2 italic">No history</div>
                 )}
              </div>

              {/* Stats Grid */}
              <div className="space-y-3">
                 <div className="flex justify-between items-end">
                    <span className="text-xs text-slate-500">Market Value</span>
                    <span className="text-lg font-display font-bold text-slate-900 dark:text-white group-hover:text-blue-600 dark:group-hover:text-blue-400 transition-colors">
                      {formatCurrency(h.marketValue)}
                    </span>
                 </div>

                 <div className="grid grid-cols-2 gap-y-3 gap-x-2 py-3 border-t border-slate-100 dark:border-slate-700/50">
                    {/* Row 1: Qty | Unrealized */}
                    <div>
                      <p className="text-[10px] uppercase text-slate-400 font-semibold mb-0.5">Quantity</p>
                      <p className="text-sm font-medium text-slate-700 dark:text-slate-300">{formatNumber(h.shares, 2)}</p>
                    </div>
                    <div className="text-right">
                      <p className="text-[10px] uppercase text-slate-400 font-semibold mb-0.5">Unrealized P/L</p>
                      <p className={`text-sm font-bold ${h.unrealizedPL >= 0 ? 'text-emerald-500' : 'text-rose-500'}`}>
                         {h.unrealizedPL >= 0 ? '+' : ''}{formatCurrency(h.unrealizedPL)}
                      </p>
                    </div>

                    {/* Row 2: Dividends | Realized */}
                    <div>
                       <p className="text-[10px] uppercase text-slate-400 font-semibold mb-0.5">Dividends</p>
                       <p className="text-sm font-medium text-emerald-600 dark:text-emerald-400">
                         +{formatCurrency(h.totalDividends)}
                       </p>
                    </div>
                    <div className="text-right">
                       <p className="text-[10px] uppercase text-slate-400 font-semibold mb-0.5">Realized P/L</p>
                       <p className={`text-sm font-bold ${h.realizedPL >= 0 ? 'text-emerald-500' : 'text-rose-500'}`}>
                         {h.realizedPL >= 0 ? '+' : ''}{formatCurrency(h.realizedPL)}
                       </p>
                    </div>
                 </div>
              </div>

              {/* Footer: Price Updating */}
              <div className="flex items-center justify-between pt-3 border-t border-slate-100 dark:border-slate-700/50 mt-1">
                 <div className="flex flex-col">
                    <span className="text-[10px] text-slate-400 uppercase font-semibold">Current Price</span>
                    {editingPrice === h.symbol ? (
                      <div className="flex items-center mt-1 animate-zoom-in">
                        <input 
                          type="number" 
                          value={tempPrice} 
                          onChange={(e) => setTempPrice(e.target.value)}
                          className="w-20 px-2 py-0.5 text-sm border border-blue-500 rounded bg-white dark:bg-slate-900 dark:text-white focus:outline-none focus:ring-2 focus:ring-blue-500/20"
                          autoFocus
                          onBlur={() => handleSavePrice(h.symbol)}
                          onKeyDown={(e) => e.key === 'Enter' && handleSavePrice(h.symbol)}
                        />
                      </div>
                    ) : (
                      <button 
                        className="group/price flex items-center space-x-1.5 mt-0.5 hover:text-blue-600 transition-colors text-left"
                        onClick={() => handleEditClick(h.symbol, h.currentPrice)}
                      >
                        <span className="text-sm font-bold text-slate-700 dark:text-slate-200">{formatCurrency(h.currentPrice)}</span>
                        <RefreshCw size={12} className="text-slate-300 group-hover/price:text-blue-500 transition-colors group-hover/price:rotate-180 duration-500" />
                      </button>
                    )}
                 </div>

                 <div className="flex flex-col items-end">
                    <span className="text-[10px] text-slate-400 uppercase font-semibold">Avg Cost</span>
                    <span className="text-sm font-medium text-slate-600 dark:text-slate-400">{formatCurrency(h.avgCost)}</span>
                 </div>
              </div>

              {/* Hover Effect Gradient */}
              <div className="absolute inset-0 bg-gradient-to-tr from-blue-500/5 to-purple-500/5 rounded-2xl opacity-0 group-hover:opacity-100 pointer-events-none transition-opacity duration-300"></div>
            </div>
          );
        })}

        {/* Empty State */}
        {holdings.length === 0 && (
          <div className="col-span-full py-20 flex flex-col items-center justify-center text-center p-8 rounded-3xl border-2 border-dashed border-slate-200 dark:border-slate-700 bg-slate-50/50 dark:bg-slate-800/50 animate-zoom-in">
            <div className="w-16 h-16 bg-slate-100 dark:bg-slate-800 rounded-full flex items-center justify-center mb-4">
               <Briefcase size={32} className="text-slate-400" />
            </div>
            <h3 className="text-lg font-bold text-slate-900 dark:text-white">No Assets Found</h3>
            <p className="text-slate-500 dark:text-slate-400 max-w-md mt-2">
              Your portfolio is currently empty. Start by adding your first buy transaction to track your wealth.
            </p>
          </div>
        )}
      </div>
    </div>
  );
};

export default Holdings;

import React, { useState, useMemo } from 'react';
import { Transaction, TransactionType, AssetClass } from '../types';
import { Search, Calendar, Filter, Trash2, ArrowUpDown, XCircle, Edit2, Plus } from 'lucide-react';
import { formatCurrency, formatNumber } from '../utils';
import { HistorySkeleton } from './LoadingSkeletons';

interface HistoryProps {
  transactions: Transaction[];
  onDelete: (id: string) => void;
  onEdit: (tx: Transaction) => void;
  onAdd: () => void;
  isLoading?: boolean;
}

const History: React.FC<HistoryProps> = ({ transactions, onDelete, onEdit, onAdd, isLoading }) => {
  // Filters State
  const [searchTerm, setSearchTerm] = useState('');
  const [typeFilter, setTypeFilter] = useState<TransactionType | 'ALL'>('ALL');
  const [assetClassFilter, setAssetClassFilter] = useState<AssetClass | 'ALL'>('ALL');
  const [startDate, setStartDate] = useState('');
  const [endDate, setEndDate] = useState('');
  const [sortOrder, setSortOrder] = useState<'desc' | 'asc'>('desc');

  // Logic
  const filteredTransactions = useMemo(() => {
    return transactions.filter(tx => {
      // 1. Search (Symbol, Notes)
      const searchLower = searchTerm.toLowerCase();
      const matchesSearch = 
        (tx.symbol?.toLowerCase().includes(searchLower) ?? false) ||
        (tx.notes?.toLowerCase().includes(searchLower) ?? false) ||
        (tx.type.toLowerCase().includes(searchLower));

      // 2. Type Filter
      const matchesType = typeFilter === 'ALL' || tx.type === typeFilter;

      // 3. Asset Class Filter
      const matchesAsset = assetClassFilter === 'ALL' || tx.assetClass === assetClassFilter;

      // 4. Date Range
      const txDate = new Date(tx.date).getTime();
      const start = startDate ? new Date(startDate).getTime() : -Infinity;
      const end = endDate ? new Date(endDate).getTime() : Infinity;
      const matchesDate = txDate >= start && txDate <= end;

      return matchesSearch && matchesType && matchesAsset && matchesDate;
    }).sort((a, b) => {
      const dateA = new Date(a.date).getTime();
      const dateB = new Date(b.date).getTime();
      return sortOrder === 'desc' ? dateB - dateA : dateA - dateB;
    });
  }, [transactions, searchTerm, typeFilter, assetClassFilter, startDate, endDate, sortOrder]);

  const resetFilters = () => {
    setSearchTerm('');
    setTypeFilter('ALL');
    setAssetClassFilter('ALL');
    setStartDate('');
    setEndDate('');
  };

  if (isLoading) {
    return <HistorySkeleton />;
  }

  const hasActiveFilters = searchTerm || typeFilter !== 'ALL' || assetClassFilter !== 'ALL' || startDate || endDate;

  return (
    <div className="space-y-6 animate-fade-in">
      {/* Header & Controls */}
      <div className="flex flex-col gap-6">
        <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
           <div className="flex justify-between items-start md:block">
             <div>
                <h2 className="text-2xl font-display font-bold text-slate-900 dark:text-white">History</h2>
                <p className="text-slate-500 dark:text-slate-400 text-sm">
                  {filteredTransactions.length} transactions found
                </p>
             </div>
             {/* Mobile Add Button - Visible only on mobile header row */}
             <button 
               onClick={onAdd}
               className="md:hidden bg-blue-600 text-white p-2 rounded-lg shadow-sm active:scale-95 transition-transform"
             >
               <Plus size={20} />
             </button>
           </div>

           <div className="flex items-center space-x-3 w-full md:w-auto">
             {/* Search Bar */}
             <div className="relative w-full md:w-72">
               <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
               <input 
                 type="text" 
                 placeholder="Search symbol, notes..." 
                 value={searchTerm}
                 onChange={(e) => setSearchTerm(e.target.value)}
                 className="w-full pl-10 pr-4 py-2.5 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none text-slate-900 dark:text-white shadow-sm"
               />
             </div>
             {/* Desktop Add Button */}
             <button 
               onClick={onAdd}
               className="hidden md:flex items-center space-x-2 bg-slate-900 dark:bg-white text-white dark:text-slate-900 px-4 py-2.5 rounded-xl font-bold hover:opacity-90 transition-opacity active:scale-95 shadow-sm whitespace-nowrap"
             >
               <Plus size={18} />
               <span>Add New</span>
             </button>
           </div>
        </div>

        {/* Filters Toolbar */}
        <div className="bg-white dark:bg-slate-800 p-4 rounded-2xl border border-slate-200 dark:border-slate-700 shadow-sm flex flex-col lg:flex-row gap-4">
           <div className="flex items-center text-slate-500 font-medium text-sm">
             <Filter size={16} className="mr-2" /> Filters:
           </div>

           <div className="grid grid-cols-2 md:grid-cols-4 lg:flex gap-3 flex-1">
              {/* Type Select */}
              <select 
                value={typeFilter} 
                onChange={(e) => setTypeFilter(e.target.value as any)}
                className="bg-slate-50 dark:bg-slate-900 border border-slate-200 dark:border-slate-700 text-slate-700 dark:text-slate-300 text-sm rounded-lg px-3 py-2 outline-none focus:ring-2 focus:ring-blue-500"
              >
                <option value="ALL">All Types</option>
                {Object.values(TransactionType).map(t => <option key={t} value={t}>{t}</option>)}
              </select>

              {/* Asset Select */}
              <select 
                value={assetClassFilter} 
                onChange={(e) => setAssetClassFilter(e.target.value as any)}
                className="bg-slate-50 dark:bg-slate-900 border border-slate-200 dark:border-slate-700 text-slate-700 dark:text-slate-300 text-sm rounded-lg px-3 py-2 outline-none focus:ring-2 focus:ring-blue-500"
              >
                <option value="ALL">All Assets</option>
                {Object.values(AssetClass).map(a => <option key={a} value={a}>{a}</option>)}
              </select>

              {/* Date Inputs */}
              <div className="relative">
                 <Calendar className="absolute left-2.5 top-1/2 -translate-y-1/2 text-slate-400 pointer-events-none" size={14} />
                 <input 
                    type="date" 
                    value={startDate}
                    onChange={(e) => setStartDate(e.target.value)}
                    className="w-full pl-8 pr-2 py-2 bg-slate-50 dark:bg-slate-900 border border-slate-200 dark:border-slate-700 text-slate-700 dark:text-slate-300 text-sm rounded-lg outline-none focus:ring-2 focus:ring-blue-500"
                    placeholder="Start Date"
                 />
              </div>
              <div className="relative">
                 <Calendar className="absolute left-2.5 top-1/2 -translate-y-1/2 text-slate-400 pointer-events-none" size={14} />
                 <input 
                    type="date" 
                    value={endDate}
                    onChange={(e) => setEndDate(e.target.value)}
                    className="w-full pl-8 pr-2 py-2 bg-slate-50 dark:bg-slate-900 border border-slate-200 dark:border-slate-700 text-slate-700 dark:text-slate-300 text-sm rounded-lg outline-none focus:ring-2 focus:ring-blue-500"
                 />
              </div>
           </div>

           {hasActiveFilters && (
             <button 
               onClick={resetFilters}
               className="flex items-center justify-center px-4 py-2 text-sm text-rose-500 hover:bg-rose-50 dark:hover:bg-rose-900/20 rounded-lg transition-colors font-medium whitespace-nowrap"
             >
               <XCircle size={16} className="mr-1.5" /> Clear
             </button>
           )}
        </div>
      </div>

      {/* Table / List View */}
      <div className="glass-card rounded-2xl overflow-hidden min-h-[400px] bg-white dark:bg-slate-800/50">

        {/* Desktop Table View */}
        <div className="hidden md:block overflow-x-auto">
          <table className="w-full text-left text-sm">
            <thead className="bg-slate-50/80 dark:bg-slate-800/50 text-slate-500 dark:text-slate-400 border-b border-slate-100 dark:border-slate-700">
              <tr>
                <th className="px-6 py-4 font-semibold whitespace-nowrap">
                  <button onClick={() => setSortOrder(prev => prev === 'desc' ? 'asc' : 'desc')} className="flex items-center hover:text-slate-800 dark:hover:text-slate-200">
                     Date <ArrowUpDown size={14} className="ml-1" />
                  </button>
                </th>
                <th className="px-6 py-4 font-semibold">Type</th>
                <th className="px-6 py-4 font-semibold">Asset</th>
                <th className="px-6 py-4 font-semibold text-right">Shares / Ratio</th>
                <th className="px-6 py-4 font-semibold text-right">Price</th>
                <th className="px-6 py-4 font-semibold text-right">Total</th>
                <th className="px-6 py-4 font-semibold text-right">Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100 dark:divide-slate-800">
              {filteredTransactions.map(tx => (
                <tr key={tx.id} className="hover:bg-slate-50 dark:hover:bg-slate-800/30 transition-colors group">
                  <td className="px-6 py-4 text-slate-600 dark:text-slate-300 whitespace-nowrap font-medium">{tx.date}</td>
                  <td className="px-6 py-4">
                    <span className={`inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-bold border ${
                      tx.type === 'BUY' ? 'bg-blue-50 text-blue-700 border-blue-200 dark:bg-blue-900/20 dark:text-blue-400 dark:border-blue-800' : 
                        tx.type === 'SELL' ? 'bg-rose-50 text-rose-700 border-rose-200 dark:bg-rose-900/20 dark:text-rose-400 dark:border-rose-800' :
                        tx.type === 'DIVIDEND' ? 'bg-emerald-50 text-emerald-700 border-emerald-200 dark:bg-emerald-900/20 dark:text-emerald-400 dark:border-emerald-800' :
                        tx.type === 'SPLIT' ? 'bg-purple-50 text-purple-700 border-purple-200 dark:bg-purple-900/20 dark:text-purple-400 dark:border-purple-800' :
                        'bg-slate-100 text-slate-700 border-slate-200 dark:bg-slate-800 dark:text-slate-300 dark:border-slate-700'
                      }`}>
                      {tx.type}
                    </span>
                  </td>
                  <td className="px-6 py-4">
                     <div className="font-bold text-slate-900 dark:text-white">{tx.symbol || '-'}</div>
                     {tx.assetClass && <div className="text-xs text-slate-400">{tx.assetClass}</div>}
                  </td>
                  <td className="px-6 py-4 text-right text-slate-600 dark:text-slate-300 font-mono">
                    {tx.type === TransactionType.SPLIT 
                      ? `${tx.shares} : 1` 
                      : (tx.shares ? formatNumber(tx.shares) : '-')}
                  </td>
                  <td className="px-6 py-4 text-right text-slate-600 dark:text-slate-300 font-mono">
                     {tx.type === TransactionType.SPLIT ? '-' : (tx.price ? formatCurrency(tx.price) : '-')}
                  </td>
                  <td className="px-6 py-4 text-right font-bold text-slate-900 dark:text-white font-mono">
                    {tx.type === TransactionType.SPLIT ? '-' : formatCurrency(
                      (tx.type === 'BUY' || tx.type === 'SELL') 
                        ? (tx.price! * tx.shares!) 
                        : tx.price!
                    )}
                  </td>
                  <td className="px-6 py-4 text-right">
                    <div className="flex items-center justify-end space-x-1">
                      <button 
                        onClick={(e) => {
                          e.stopPropagation();
                          onEdit(tx);
                        }}
                        className="text-slate-400 hover:text-blue-500 transition-colors p-2 hover:bg-blue-50 dark:hover:bg-blue-900/20 rounded-lg"
                        title="Edit"
                      >
                        <Edit2 size={16} />
                      </button>
                      <button 
                        onClick={(e) => {
                          e.stopPropagation();
                          if(window.confirm('Are you sure you want to delete this transaction?')) {
                            onDelete(tx.id);
                          }
                        }}
                        className="text-slate-400 hover:text-rose-500 transition-colors p-2 hover:bg-rose-50 dark:hover:bg-rose-900/20 rounded-lg"
                        title="Delete"
                      >
                        <Trash2 size={16} />
                      </button>
                    </div>
                  </td>
                </tr>
              ))}
              {filteredTransactions.length === 0 && (
