             <span className="text-xs font-semibold px-2 text-slate-500">History:</span>
             {[3, 6, 12, 99].map((val) => (
               <button
                 key={val}
                 onClick={() => setRange(val)}
                 className={`px-3 py-1 text-xs rounded-md transition-colors ${
                   range === val 
                   ? 'bg-slate-100 dark:bg-slate-700 text-slate-900 dark:text-white font-bold' 
                   : 'text-slate-500 hover:bg-slate-50 dark:hover:bg-slate-800'
                 }`}
               >
                 {val === 99 ? 'All' : `${val}M`}
               </button>
             ))}
         </div>
      </div>

      {/* Comparison Cards */}
      <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          {/* Investment Volume Comparison */}
          <div className="bg-white dark:bg-slate-800 p-6 rounded-2xl shadow-sm border border-slate-200 dark:border-slate-700">
              <div className="flex justify-between items-start mb-4">
                 <div>
                    <p className="text-sm text-slate-500 dark:text-slate-400 font-medium">Invested This Month</p>
                    <h3 className="text-2xl font-bold text-slate-900 dark:text-white mt-1">
                      {formatCurrency(current.buyVolume)}
                    </h3>
                 </div>
                 <div className="p-2 bg-blue-50 dark:bg-blue-900/20 rounded-lg">
                    <TrendingUp size={20} className="text-blue-600 dark:text-blue-400" />
                 </div>
              </div>

              <div className="flex items-center text-sm">
                 <span className={`flex items-center font-bold mr-2 ${buyDiff >= 0 ? 'text-emerald-500' : 'text-slate-500'}`}>
                    {buyDiff > 0 ? <ArrowUpRight size={16} className="mr-1"/> : buyDiff < 0 ? <ArrowDownRight size={16} className="mr-1"/> : <Minus size={16} className="mr-1"/>}
                    {Math.abs(buyDiffPercent).toFixed(1)}%
                 </span>
                 <span className="text-slate-400">vs Previous Month ({formatCurrency(previous.buyVolume)})</span>
              </div>
          </div>

           {/* Income Comparison */}
           <div className="bg-white dark:bg-slate-800 p-6 rounded-2xl shadow-sm border border-slate-200 dark:border-slate-700">
              <div className="flex justify-between items-start mb-4">
                 <div>
                    <p className="text-sm text-slate-500 dark:text-slate-400 font-medium">Income This Month</p>
                    <h3 className="text-2xl font-bold text-slate-900 dark:text-white mt-1">
                      {formatCurrency(current.dividendIncome)}
                    </h3>
                 </div>
                 <div className="p-2 bg-emerald-50 dark:bg-emerald-900/20 rounded-lg">
                    <DollarSign size={20} className="text-emerald-600 dark:text-emerald-400" />
                 </div>
              </div>

              <div className="flex items-center text-sm">
                 <span className={`flex items-center font-bold mr-2 ${divDiff >= 0 ? 'text-emerald-500' : 'text-rose-500'}`}>
                    {divDiff > 0 ? <ArrowUpRight size={16} className="mr-1"/> : divDiff < 0 ? <ArrowDownRight size={16} className="mr-1"/> : <Minus size={16} className="mr-1"/>}
