             {formatNumber(netFundingLocal, 0)} <span className="text-xs text-gray-400 font-normal">THB</span>
          </h3>
        </div>

        {/* Prominent FX Cost Card */}
         <div className="bg-gradient-to-br from-orange-50 to-orange-100 dark:from-orange-900/20 dark:to-orange-900/10 p-6 rounded-2xl shadow-sm border border-orange-200 dark:border-orange-800/50 relative overflow-hidden">
          <div className="relative z-10">
