                         'bg-slate-100 text-slate-700 border-slate-200 dark:bg-slate-800 dark:text-slate-300 dark:border-slate-700'
                       }`}>
                         {tx.type}
                       </span>
                    </div>

                    {/* Details Grid */}
                    <div className="grid grid-cols-2 gap-2 text-sm">
                       <div className="bg-slate-50 dark:bg-slate-800/50 p-2 rounded-lg">
                          <div className="text-xs text-slate-400 mb-1">Quantity</div>
                          <div className="font-mono text-slate-700 dark:text-slate-300">
                             {tx.type === TransactionType.SPLIT ? `${tx.shares} : 1` : (tx.shares ? formatNumber(tx.shares) : '-')}
                          </div>
                       </div>
                       <div className="bg-slate-50 dark:bg-slate-800/50 p-2 rounded-lg text-right">
                          <div className="text-xs text-slate-400 mb-1">Total Value</div>
                          <div className="font-mono font-bold text-slate-900 dark:text-white">
                             {tx.type === TransactionType.SPLIT ? '-' : formatCurrency((tx.type === 'BUY' || tx.type === 'SELL') ? (tx.price! * tx.shares!) : tx.price!)}
                          </div>
                       </div>
                    </div>

                    {/* Footer */}
                    <div className="flex justify-between items-center pt-1">
                       <div className="text-xs text-slate-400">{tx.assetClass}</div>
                       <div className="flex items-center space-x-2">
                          <button 
                             onClick={(e) => {
                               e.stopPropagation();
                               onEdit(tx);
                             }}
                             className="text-blue-500 text-xs flex items-center bg-blue-50 dark:bg-blue-900/10 px-2 py-1.5 rounded-md active:scale-95 transition-transform"
                           >
                              <Edit2 size={12} className="mr-1" /> Edit
                           </button>
                           <button 
                             onClick={(e) => {
                               e.stopPropagation();
                               if (window.confirm("Are you sure you want to delete this transaction?")) {
                                 onDelete(tx.id);
                               }
                             }}
                             className="text-rose-500 text-xs flex items-center bg-rose-50 dark:bg-rose-900/10 px-2 py-1.5 rounded-md active:scale-95 transition-transform"
                           >
                              <Trash2 size={12} className="mr-1" /> Delete
                           </button>
                       </div>
                    </div>
                 </div>
              ))}
              {filteredTransactions.length === 0 && (
                 <div className="p-8 text-center text-slate-400 text-sm">
                   {transactions.length === 0 ? "No transactions recorded yet." : "No transactions match your filters."}
                 </div>
              )}
           </div>
        </div>

      </div>
    </div>
  );
};

