                 onClick={() => !selectedCategory && setSelectedCategory(entry.name)}
                 className={`w-full flex justify-between items-center text-sm p-2 rounded-lg transition-colors group ${
                   !selectedCategory ? 'hover:bg-slate-50 dark:hover:bg-slate-800/50 cursor-pointer' : 'cursor-default'
                 }`}
               >
                 <div className="flex items-center overflow-hidden">
                   <div className="w-3 h-3 rounded-full mr-3 shrink-0" style={{ backgroundColor: COLORS[idx % COLORS.length] }}></div>
                   <div className="flex flex-col items-start overflow-hidden">
                      <span className="text-slate-700 dark:text-slate-200 font-medium truncate w-full text-left">{entry.name}</span>
                      {/* Show Full Name if in drill-down mode */}
                      {selectedCategory && (entry as any).fullName !== entry.name && (
                          <span className="text-[10px] text-slate-400 truncate w-full text-left">{(entry as any).fullName}</span>
                      )}
                   </div>
                 </div>
                 <div className="flex items-center space-x-3 shrink-0">
                    <span className="text-slate-900 dark:text-white font-bold">
                      {percentage.toFixed(1)}%
                    </span>
                    <span className="text-slate-400 text-xs w-16 text-right tabular-nums">{formatCurrency(entry.value).split('.')[0]}</span>
                 </div>
               </button>
             )})}
          </div>
        </div>
      </div>
    </div>
  );
};

