import React, { useState, useEffect, useRef } from 'react';
import { LayoutDashboard, PieChart, History, FileText, Menu, X, Sun, Moon, Plus, TrendingUp, ChevronDown, Trash2, Briefcase, Check, Edit2 } from 'lucide-react';
import { TransactionType, Portfolio } from '../types';

interface LayoutProps {
  children: React.ReactNode;
  activeTab: string;
  setActiveTab: (tab: string) => void;
  onOpenAddModal: () => void;
  // New Props for Portfolio Management
  portfolios: Portfolio[];
  activePortfolioId: string;
  onSwitchPortfolio: (id: string) => void;
  onCreatePortfolio: (name: string) => void;
  onRenamePortfolio: (id: string, newName: string) => void;
  onDeletePortfolio: (id: string) => void;
}

const Layout: React.FC<LayoutProps> = ({ 
  children, activeTab, setActiveTab, onOpenAddModal,
  portfolios, activePortfolioId, onSwitchPortfolio, onCreatePortfolio, onRenamePortfolio, onDeletePortfolio
}) => {
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const [darkMode, setDarkMode] = useState(false);

  // Portfolio Dropdown & Modal State
  const [isPortfolioDropdownOpen, setIsPortfolioDropdownOpen] = useState(false);
  const [isCreateModalOpen, setIsCreateModalOpen] = useState(false);
  const [newPortfolioName, setNewPortfolioName] = useState('');

  // Rename State
  const [isRenameModalOpen, setIsRenameModalOpen] = useState(false);
  const [portfolioToRename, setPortfolioToRename] = useState<Portfolio | null>(null);
  const [renameValue, setRenameValue] = useState('');

  const dropdownRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    // Check local storage or system preference
    if (localStorage.getItem('theme') === 'dark' || (!localStorage.getItem('theme') && window.matchMedia('(prefers-color-scheme: dark)').matches)) {
      setDarkMode(true);
      document.documentElement.classList.add('dark');
    } else {
      setDarkMode(false);
      document.documentElement.classList.remove('dark');
    }
  }, []);

  // Close dropdown when clicking outside
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
        setIsPortfolioDropdownOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const toggleDarkMode = () => {
    const newMode = !darkMode;
    setDarkMode(newMode);
    if (newMode) {
      document.documentElement.classList.add('dark');
      localStorage.setItem('theme', 'dark');
    } else {
      document.documentElement.classList.remove('dark');
      localStorage.setItem('theme', 'light');
    }
  };

  const navItems = [
    { id: 'dashboard', label: 'Dashboard', icon: <LayoutDashboard size={18} /> },
    { id: 'holdings', label: 'Holdings', icon: <PieChart size={18} /> },
    { id: 'reports', label: 'Reports', icon: <FileText size={18} /> },
    { id: 'history', label: 'History', icon: <History size={18} /> },
  ];

  const activePortfolio = portfolios.find(p => p.id === activePortfolioId) || portfolios[0];

  const handleCreateClick = () => {
    setNewPortfolioName('');
    setIsCreateModalOpen(true);
    setIsPortfolioDropdownOpen(false);
  };

  const handleCreateSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (newPortfolioName.trim()) {
      onCreatePortfolio(newPortfolioName.trim());
      setIsCreateModalOpen(false);
    }
  };

  const handleRenameClick = (e: React.MouseEvent, p: Portfolio) => {
    e.stopPropagation();
    setPortfolioToRename(p);
    setRenameValue(p.name);
    setIsRenameModalOpen(true);
    setIsPortfolioDropdownOpen(false);
  };

  const handleRenameSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (portfolioToRename && renameValue.trim()) {
      onRenamePortfolio(portfolioToRename.id, renameValue.trim());
      setIsRenameModalOpen(false);
      setPortfolioToRename(null);
    }
  };

  return (
    <div className="min-h-screen flex flex-col bg-slate-50 dark:bg-[#0b1120] transition-colors duration-300">

      {/* TOP NAVIGATION BAR */}
      <header className="sticky top-0 z-40 w-full glass dark:bg-slate-900/80 border-b border-slate-200 dark:border-slate-800">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex items-center justify-between h-16">

            {/* Left: Branding & Portfolio Switcher */}
            <div className="flex items-center space-x-4 md:space-x-8">
              {/* Logo */}
              <div className="flex items-center space-x-2 shrink-0">
                <div className="w-8 h-8 bg-gradient-to-br from-blue-600 to-indigo-600 rounded-lg flex items-center justify-center shadow-lg shadow-blue-500/20">
                  <TrendingUp className="text-white" size={18} />
                </div>
                <span className="hidden md:block text-lg font-display font-bold text-slate-900 dark:text-white tracking-tight">Portfolio</span>
              </div>

              {/* Desktop Nav Items */}
              <nav className="hidden md:flex items-center space-x-1">
                {navItems.map((item) => (
                  <button
                    key={item.id}
                    onClick={() => setActiveTab(item.id)}
                    className={`flex items-center space-x-2 px-3 py-2 rounded-lg text-sm font-medium transition-all ${
                      activeTab === item.id
                        ? 'bg-slate-100 dark:bg-slate-800 text-slate-900 dark:text-white'
                        : 'text-slate-500 dark:text-slate-400 hover:bg-slate-50 dark:hover:bg-slate-800/50 hover:text-slate-700 dark:hover:text-slate-200'
                    }`}
                  >
                    {item.icon}
                    <span>{item.label}</span>
                  </button>
                ))}
              </nav>
            </div>

            {/* Right: Actions */}
            <div className="flex items-center space-x-2 sm:space-x-4">

              {/* Portfolio Switcher (Compact Dropdown) */}
              <div className="relative" ref={dropdownRef}>
                 <button 
                   onClick={() => setIsPortfolioDropdownOpen(!isPortfolioDropdownOpen)}
                   className="flex items-center space-x-2 px-3 py-1.5 rounded-lg border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-slate-800 transition-colors"
                 >
                    <Briefcase size={16} className="text-slate-500" />
                    <span className="hidden sm:block text-sm font-medium text-slate-700 dark:text-slate-200 max-w-[120px] truncate">{activePortfolio?.name}</span>
                    <ChevronDown size={14} className="text-slate-400" />
                 </button>

                  {isPortfolioDropdownOpen && (
                    <div className="absolute top-full right-0 mt-2 w-64 bg-white dark:bg-slate-800 rounded-xl shadow-xl border border-slate-200 dark:border-slate-700 overflow-hidden z-50 animate-in fade-in zoom-in-95 duration-200">
                      <div className="max-h-60 overflow-y-auto custom-scrollbar p-1 space-y-0.5">
