              >
                <Plus size={18} strokeWidth={3} />
                <span>Add</span>
              </button>

               {/* Mobile Add Button (Icon only) */}
              <button
                onClick={() => onOpenAddModal()}
                className="sm:hidden flex items-center justify-center w-9 h-9 bg-slate-900 dark:bg-white text-white dark:text-slate-900 rounded-full shadow-lg"
              >
                <Plus size={20} strokeWidth={3} />
              </button>

              {/* Mobile Menu Toggle */}
              <button 
                onClick={() => setIsMobileMenuOpen(!isMobileMenuOpen)} 
                className="md:hidden p-2 text-slate-600 dark:text-slate-300"
              >
                {isMobileMenuOpen ? <X size={24} /> : <Menu size={24} />}
              </button>
            </div>
          </div>
        </div>

        {/* Mobile Navigation Menu */}
        {isMobileMenuOpen && (
          <div className="md:hidden border-t border-slate-200 dark:border-slate-800 bg-white/95 dark:bg-slate-900/95 backdrop-blur-xl absolute w-full left-0 z-50 animate-slide-up shadow-xl rounded-b-2xl">
            <div className="px-4 py-4 space-y-2">
              {navItems.map((item) => (
                <button
                  key={item.id}
                  onClick={() => {
                    setActiveTab(item.id);
                    setIsMobileMenuOpen(false);
                  }}
                  className={`w-full flex items-center space-x-3 px-4 py-3 rounded-xl transition-all ${
                    activeTab === item.id
                      ? 'bg-blue-50 text-blue-600 dark:bg-blue-900/20 dark:text-blue-400'
