           </div>
         )}

          <div className="flex gap-3">
            {initialData && onDelete && (
               <button
                 type="button"
                 onClick={() => onDelete(initialData.id)}
                 className="px-4 py-3 rounded-xl font-bold bg-rose-50 text-rose-500 hover:bg-rose-100 dark:bg-rose-900/20 dark:text-rose-400 transition-colors"
               >
                 <Trash2 size={20} />
