                         <div key={goal.id} className={`p-4 rounded-xl border ${isActive ? 'bg-white dark:bg-slate-800 border-blue-200 dark:border-blue-900 shadow-sm' : 'bg-white dark:bg-slate-800 border-slate-200 dark:border-slate-700 opacity-80'}`}>
