                    </h3>
                    {editingGoal && (
                       <button 
                         onClick={resetForm} 
                         className="text-xs font-medium text-slate-500 hover:text-slate-700 dark:text-slate-400 dark:hover:text-white underline"
                       >
                         Cancel Edit
                       </button>
                    )}
                 </div>

                 <form onSubmit={handleSubmit} className="space-y-4">
                    <div>
                      <label className="block text-xs font-bold text-slate-500 uppercase tracking-wider mb-1.5">Target Amount</label>
                      <div className="relative">
                        <span className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400 font-bold">$</span>
                        <input 
                          type="number" 
                          required
                          min="1"
                          placeholder="e.g. 100000"
                          value={amount}
                          onChange={(e) => setAmount(e.target.value)}
                          className="w-full pl-8 pr-4 py-3 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl text-slate-900 dark:text-white focus:ring-2 focus:ring-blue-500 outline-none font-bold text-lg"
                        />
                      </div>
                    </div>

                    {/* Show Date Picker only if Editing (to fix history) or if creating new one (optional, defaults to today) */}
                    {editingGoal && (
                       <div>
                         <label className="block text-xs font-bold text-slate-500 uppercase tracking-wider mb-1.5">Start Date</label>
                         <div className="relative">
                           <Calendar className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={16} />
                           <input 
                             type="date"
                             required
                             value={startDate}
                             onChange={(e) => setStartDate(e.target.value)}
                             className="w-full pl-10 pr-4 py-3 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl text-slate-900 dark:text-white focus:ring-2 focus:ring-blue-500 outline-none font-medium text-sm"
                           />
                         </div>
                       </div>
                    )}

                    <div>
                      <label className="block text-xs font-bold text-slate-500 uppercase tracking-wider mb-1.5">Notes (Optional)</label>
                      <textarea 
                        rows={editingGoal ? 3 : 2}
                        placeholder="What are you saving for?"
                        value={notes}
                        onChange={(e) => setNotes(e.target.value)}
                        className="w-full px-4 py-3 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl text-slate-900 dark:text-white focus:ring-2 focus:ring-blue-500 outline-none text-sm resize-none"
                      />
                    </div>

                    <button 
                      type="submit"
                      className={`w-full py-3 text-white font-bold rounded-xl hover:opacity-90 transition-opacity flex items-center justify-center space-x-2 shadow-lg shadow-blue-500/20 ${editingGoal ? 'bg-amber-500' : 'bg-slate-900 dark:bg-blue-600'}`}
                    >
                      {editingGoal ? <Save size={18} /> : <Target size={18} />}
                      <span>{editingGoal ? 'Update Goal' : (activeGoal ? 'Start New Goal' : 'Set Goal')}</span>
                    </button>
                    {!editingGoal && activeGoal && (
                       <p className="text-center text-xs text-slate-400 mt-2">
                         Starting a new goal will mark the current one as completed/ended.
                       </p>
                    )}
                 </form>
              </div>
           </div>

           {/* Right Column: History */}
           <div className="flex-1 bg-slate-50 dark:bg-slate-800/30 p-6 flex flex-col overflow-hidden min-h-[300px]">
              <div className="flex items-center justify-between mb-4">
                 <div className="flex items-center space-x-2 text-slate-500 dark:text-slate-400">
                    <History size={18} />
                    <span className="font-bold text-sm uppercase tracking-wider">Goal History</span>
                 </div>
                 <span className="text-xs font-medium text-slate-400">{goals.length} records</span>
              </div>

              <div className="space-y-4 overflow-y-auto custom-scrollbar pr-2 flex-1 pb-4">
                 {sortedGoals.map((goal) => {
                    const isActive = !goal.endDate;
                    const isEditing = editingGoal?.id === goal.id;
                    return (
                      <div 
                        key={goal.id} 
                        className={`p-4 rounded-xl border transition-all group ${
                           isEditing 
                           ? 'bg-amber-50 dark:bg-amber-900/20 border-amber-400 ring-1 ring-amber-400'
                           : isActive 
                              ? 'bg-white dark:bg-slate-800 border-blue-200 dark:border-blue-900 shadow-sm' 
                              : 'bg-white dark:bg-slate-800 border-slate-200 dark:border-slate-700 opacity-80 hover:opacity-100'
                        }`}
                      >
                         <div className="flex justify-between items-start mb-2">
                            <div>
                               <div className="text-lg font-bold font-display text-slate-900 dark:text-white">
                                 {formatCurrency(goal.targetAmount)}
                               </div>
                               <div className="mt-1">
                                  {isActive ? (
                                    <span className="text-[10px] font-bold bg-blue-100 dark:bg-blue-900/30 text-blue-600 dark:text-blue-400 px-2 py-0.5 rounded-full">ACTIVE</span>
                                  ) : (
                                     goal.isAchieved ? (
                                       <span className="text-[10px] font-bold bg-emerald-100 dark:bg-emerald-900/30 text-emerald-600 dark:text-emerald-400 px-2 py-0.5 rounded-full flex items-center w-fit">
                                         <CheckCircle2 size={10} className="mr-1" /> REACHED
                                       </span>
                                     ) : (
                                       <span className="text-[10px] font-bold bg-slate-100 dark:bg-slate-700 text-slate-500 dark:text-slate-400 px-2 py-0.5 rounded-full flex items-center w-fit">
                                         <XCircle size={10} className="mr-1" /> ENDED
                                       </span>
                                     )
                                  )}
                               </div>
                            </div>

                            {/* Actions */}
                            <div className="flex space-x-1 opacity-100 sm:opacity-0 sm:group-hover:opacity-100 transition-opacity">
                               <button 
                                 onClick={() => handleEditClick(goal)}
                                 className="p-2 text-slate-400 hover:text-blue-500 hover:bg-blue-50 dark:hover:bg-blue-900/20 rounded-lg transition-colors"
                                 title="Edit"
                               >
                                 <Edit2 size={14} />
                               </button>
                               <button 
                                 onClick={() => handleDeleteClick(goal.id)}
                                 className="p-2 text-slate-400 hover:text-rose-500 hover:bg-rose-50 dark:hover:bg-rose-900/20 rounded-lg transition-colors"
                                 title="Delete"
                               >
                                 <Trash2 size={14} />
                               </button>
                            </div>
                         </div>

                         <div className="flex items-center text-xs text-slate-500 dark:text-slate-400 mb-2 mt-2">
                            <Calendar size={12} className="mr-1.5" />
                            <span>{new Date(goal.startDate).toLocaleDateString()}</span>
                            {goal.endDate && (
                              <>
                                <ArrowRight size={12} className="mx-1" />
                                <span>{new Date(goal.endDate).toLocaleDateString()}</span>
                              </>
                            )}
                         </div>

                         {goal.notes && (
                           <p className="text-xs text-slate-600 dark:text-slate-300 bg-slate-50 dark:bg-slate-700/50 p-2 rounded-lg italic">
                             "{goal.notes}"
                           </p>
                         )}
                      </div>
                    );
                 })}
                 {sortedGoals.length === 0 && (
                   <div className="text-center py-10 text-slate-400 text-sm">
                     No history yet. Set your first goal!
                   </div>
                 )}
              </div>
           </div>

        </div>
      </div>
    </div>
  );
};

export default GoalModal;

import React, { useState, useEffect, useMemo } from 'react';
import Layout from './components/Layout';
import Dashboard from './components/Dashboard';
import Holdings from './components/Holdings';
import Reports from './components/Reports';
import History from './components/History';
import GoalModal from './components/GoalModal';
import { Transaction, TransactionType, AssetClass, Holding, Portfolio, FinancialGoal } from './types';
import { calculateHoldings, calculatePortfolioHistory, generateId, formatCurrency, formatNumber } from './utils';
import { X, Save, TrendingUp, TrendingDown, DollarSign, Wallet, Calendar, GitFork, AlertCircle, ArrowRight, Trash2, Zap, Calculator } from 'lucide-react';
import { Spinner } from './components/LoadingSkeletons';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState('dashboard');
  const [isAddModalOpen, setIsAddModalOpen] = useState(false);
  const [editingTransaction, setEditingTransaction] = useState<Transaction | null>(null);
  const [isLoading, setIsLoading] = useState(true); 

  // Goal Modal State
  const [isGoalModalOpen, setIsGoalModalOpen] = useState(false);

  // --- CONFIRMATION MODAL STATE ---
  const [confirmConfig, setConfirmConfig] = useState<{
    isOpen: boolean;
    title: string;
    message: string;
    onConfirm: () => void;
  }>({
    isOpen: false,
    title: '',
    message: '',
    onConfirm: () => {},
  });

  // --- PORTFOLIO MANAGEMENT STATE ---
  const [portfolios, setPortfolios] = useState<Portfolio[]>(() => {
    const saved = localStorage.getItem('portfolios');
    if (saved) return JSON.parse(saved);

    // Migration: If no portfolios exist but we have legacy transactions, create a default one
    const legacyTx = localStorage.getItem('transactions');
    if (legacyTx) {
      return [{ id: 'default', name: 'Main Portfolio' }];
    }

    return [{ id: generateId(), name: 'My First Portfolio' }];
  });

  const [activePortfolioId, setActivePortfolioId] = useState<string>(() => {
    const saved = localStorage.getItem('activePortfolioId');
    const portfolios = JSON.parse(localStorage.getItem('portfolios') || '[]');
    if (saved && portfolios.some((p: Portfolio) => p.id === saved)) return saved;
    return portfolios.length > 0 ? portfolios[0].id : 'default';
  });

  // --- DATA STATE (Per Portfolio) ---
  const [transactions, setTransactions] = useState<Transaction[]>([]);
  const [prices, setPrices] = useState<Record<string, number>>({});

  // New Goals State
  const [goals, setGoals] = useState<FinancialGoal[]>([]);

  const [isDataLoaded, setIsDataLoaded] = useState(false);

  // --- PERSISTENCE: Portfolios List ---
  useEffect(() => {
    localStorage.setItem('portfolios', JSON.stringify(portfolios));
  }, [portfolios]);

  useEffect(() => {
    localStorage.setItem('activePortfolioId', activePortfolioId);
  }, [activePortfolioId]);

  // --- PERSISTENCE: Load Data on Portfolio Switch ---
  useEffect(() => {
    setIsLoading(true);
    setIsDataLoaded(false); 

    const loadData = () => {
        const txKey = `transactions_${activePortfolioId}`;
        const pricesKey = `prices_${activePortfolioId}`;
        const goalsKey = `goals_${activePortfolioId}`;
        // Legacy goal key support
        const legacyGoalKey = `financialGoal_${activePortfolioId}`;

        // Load Transactions
        const savedTx = localStorage.getItem(txKey);
        if (savedTx) {
          setTransactions(JSON.parse(savedTx));
        } else if (activePortfolioId === 'default' && localStorage.getItem('transactions')) {
          setTransactions(JSON.parse(localStorage.getItem('transactions')!));
        } else {
          setTransactions([]);
        }

        // Load Prices
        const savedPrices = localStorage.getItem(pricesKey);
        if (savedPrices) {
          setPrices(JSON.parse(savedPrices));
        } else if (activePortfolioId === 'default' && localStorage.getItem('prices')) {
          setPrices(JSON.parse(localStorage.getItem('prices')!));
        } else {
          setPrices({});
        }

        // Load Goals with Legacy Migration
        const savedGoals = localStorage.getItem(goalsKey);
        if (savedGoals) {
           setGoals(JSON.parse(savedGoals));
        } else {
           // Check for legacy goal
           let legacyGoal = 100000;
           const savedLegacy = localStorage.getItem(legacyGoalKey);
           if (savedLegacy) {
             legacyGoal = parseFloat(savedLegacy);
           } else if (activePortfolioId === 'default' && localStorage.getItem('financialGoal')) {
             legacyGoal = parseFloat(localStorage.getItem('financialGoal')!);
           }

           // Create initial goal from legacy
           const initialGoal: FinancialGoal = {
             id: generateId(),
             targetAmount: legacyGoal,
             startDate: new Date().toISOString(),
             isAchieved: false,
             notes: 'Initial Goal'
           };
           setGoals([initialGoal]);
        }

        setIsDataLoaded(true);
        setTimeout(() => setIsLoading(false), 600);
    };

    requestAnimationFrame(loadData);

  }, [activePortfolioId]);

  useEffect(() => {
    if (!isDataLoaded) return;
    localStorage.setItem(`transactions_${activePortfolioId}`, JSON.stringify(transactions));
  }, [transactions, activePortfolioId, isDataLoaded]);

  useEffect(() => {
    if (!isDataLoaded) return;
    localStorage.setItem(`prices_${activePortfolioId}`, JSON.stringify(prices));
  }, [prices, activePortfolioId, isDataLoaded]);

  useEffect(() => {
    if (!isDataLoaded) return;
    localStorage.setItem(`goals_${activePortfolioId}`, JSON.stringify(goals));
  }, [goals, activePortfolioId, isDataLoaded]);


  // --- CALCULATIONS ---
  const holdings = useMemo(() => calculateHoldings(transactions, prices), [transactions, prices]);
  const chartData = useMemo(() => calculatePortfolioHistory(transactions, prices), [transactions, prices]);

  const investedAmount = transactions.reduce((sum, t) => {
    if (t.type === TransactionType.DEPOSIT) return sum + (t.price || 0);
    if (t.type === TransactionType.WITHDRAW) return sum - (t.price || 0);
    return sum;
  }, 0);

  const cashBalance = useMemo(() => {
    let balance = 0;
    transactions.forEach(t => {
      if (t.type === TransactionType.DEPOSIT) balance += (t.price || 0);
      if (t.type === TransactionType.WITHDRAW) balance -= (t.price || 0);
      if (t.type === TransactionType.BUY) balance -= (t.price! * t.shares!) + (t.fee || 0);
      if (t.type === TransactionType.SELL) balance += (t.price! * t.shares!) - (t.fee || 0);
      if (t.type === TransactionType.DIVIDEND) balance += (t.price || 0);
    });
    return balance;
  }, [transactions]);

  const portfolioValue = holdings.reduce((sum, h) => sum + h.marketValue, 0);
  const totalNetWorth = portfolioValue + cashBalance;

  // Active Goal Logic
  const activeGoal = useMemo(() => {
    return goals.find(g => !g.endDate) || { targetAmount: 100000 } as FinancialGoal;
  }, [goals]);

  // --- HANDLERS ---
  const handleOpenAddModal = () => {
    setEditingTransaction(null);
    setIsAddModalOpen(true);
  };

  const handleOpenEditModal = (tx: Transaction) => {
    setEditingTransaction(tx);
    setIsAddModalOpen(true);
  };

  const handleSaveTransaction = (tx: Transaction) => {
    // Simulate slight delay for better UX (loading state)
    return new Promise<void>((resolve) => {
      setTimeout(() => {
        if (editingTransaction) {
          setTransactions(prev => prev.map(t => t.id === tx.id ? tx : t));
        } else {
          setTransactions(prev => [...prev, tx]);
        }

        if ((tx.type === TransactionType.BUY || tx.type === TransactionType.SELL) && tx.symbol && tx.price) {
            setPrices(prev => ({...prev, [tx.symbol!]: tx.price!}));
        }

        setIsAddModalOpen(false);
        setEditingTransaction(null);
        resolve();
      }, 500);
    });
  };

  const handleUpdatePrice = (symbol: string, newPrice: number) => {
    setPrices(prev => ({ ...prev, [symbol]: newPrice }));
  };

  const handleDeleteTransaction = (id: string) => {
    setTransactions(prev => prev.filter(t => t.id !== id));
    if (editingTransaction && editingTransaction.id === id) {
       setIsAddModalOpen(false);
       setEditingTransaction(null);
    }
  };

  const handleRequestDelete = (id: string) => {
      setConfirmConfig({
          isOpen: true,
          title: 'Delete Transaction',
          message: 'Are you sure you want to delete this transaction? This action cannot be undone.',
          onConfirm: () => {
              handleDeleteTransaction(id);
              setConfirmConfig(prev => ({ ...prev, isOpen: false }));
          }
      });
  };

  const handleImportTransactions = (importedTxs: Transaction[]) => {
      // Merge logic: Update if exists, Add if not
      setTransactions(prev => {
          const currentMap = new Map(prev.map(t => [t.id, t]));
          importedTxs.forEach(t => {
              currentMap.set(t.id, t);
          });
          return Array.from(currentMap.values());
      });
      alert(`Imported ${importedTxs.length} transactions successfully.`);
  };

  // Portfolio Management Handlers
  const handleCreatePortfolio = (name: string) => {
    const newId = generateId();
    const newPortfolio = { id: newId, name };
    setPortfolios([...portfolios, newPortfolio]);
    setActivePortfolioId(newId);
  };

  const handleRenamePortfolio = (id: string, newName: string) => {
    setPortfolios(prev => prev.map(p => p.id === id ? { ...p, name: newName } : p));
  };

  const handleDeletePortfolio = (id: string) => {
    if (portfolios.length <= 1) {
      alert("You must have at least one portfolio.");
      return;
    }
    setConfirmConfig({
        isOpen: true,
        title: 'Delete Portfolio',
        message: 'Are you sure you want to delete this entire portfolio? All transactions within it will be permanently lost.',
        onConfirm: () => {
             localStorage.removeItem(`transactions_${id}`);
             localStorage.removeItem(`prices_${id}`);
             localStorage.removeItem(`goals_${id}`);
             localStorage.removeItem(`financialGoal_${id}`);

             const newPortfolios = portfolios.filter(p => p.id !== id);
             setPortfolios(newPortfolios);

             if (activePortfolioId === id) {
               setActivePortfolioId(newPortfolios[0].id);
             }
             setConfirmConfig(prev => ({ ...prev, isOpen: false }));
        }
    });
  };

  // Goals Handler
  const handleSetNewGoal = (targetAmount: number, notes: string) => {
    const now = new Date().toISOString();

    setGoals(prev => {
      const updatedGoals = prev.map(g => {
        // If there's an active goal, end it.
        if (!g.endDate) {
           const achieved = totalNetWorth >= g.targetAmount;
           return { ...g, endDate: now, isAchieved: achieved };
        }
        return g;
      });

      const newGoal: FinancialGoal = {
        id: generateId(),
        targetAmount,
        startDate: now,
        isAchieved: false,
        notes
      };

      return [...updatedGoals, newGoal];
    });
  };

  const handleEditGoal = (updatedGoal: FinancialGoal) => {
      setGoals(prev => prev.map(g => g.id === updatedGoal.id ? updatedGoal : g));
  };

  const handleDeleteGoal = (id: string) => {
      setGoals(prev => prev.filter(g => g.id !== id));
  };

  return (
    <Layout 
      activeTab={activeTab} 
      setActiveTab={setActiveTab} 
      onOpenAddModal={handleOpenAddModal}
      portfolios={portfolios}
      activePortfolioId={activePortfolioId}
      onSwitchPortfolio={setActivePortfolioId}
      onCreatePortfolio={handleCreatePortfolio}
      onRenamePortfolio={handleRenamePortfolio}
      onDeletePortfolio={handleDeletePortfolio}
    >
      <div key={activePortfolioId} className="h-full">
        {activeTab === 'dashboard' && (
          <Dashboard 
            isLoading={isLoading}
            holdings={holdings} 
            transactions={transactions} 
            financialGoal={activeGoal.targetAmount}
            onOpenGoalModal={() => setIsGoalModalOpen(true)}
            investedAmount={investedAmount}
            cashBalance={cashBalance}
            portfolioValue={portfolioValue}
            chartData={chartData}
          />
        )}
        {activeTab === 'holdings' && (
          <Holdings 
            isLoading={isLoading}
            holdings={holdings} 
            transactions={transactions} 
            onUpdatePrice={handleUpdatePrice} 
          />
        )}
        {activeTab === 'history' && (
          <History 
            isLoading={isLoading}
            transactions={transactions} 
            onDelete={handleRequestDelete}
            onEdit={handleOpenEditModal}
            onAdd={handleOpenAddModal}
            onImport={handleImportTransactions}
          />
        )}
        {activeTab === 'reports' && (
           <Reports 
             isLoading={isLoading}
             transactions={transactions} 
             currentPortfolioValue={portfolioValue + cashBalance} 
             chartData={chartData} 
           />
        )}
      </div>

      {isAddModalOpen && (
        <div className="fixed inset-0 z-50 flex items-end sm:items-center justify-center sm:p-4">
          <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-sm animate-fade-in" onClick={() => setIsAddModalOpen(false)}></div>
          <div className="relative bg-white dark:bg-slate-900 w-full max-w-lg 
                          rounded-t-3xl sm:rounded-3xl border border-slate-200 dark:border-slate-800 
                          shadow-2xl overflow-hidden animate-slide-up flex flex-col
                          max-h-[90dvh] sm:max-h-[85vh]">
            <AddTransactionForm 
              onClose={() => setIsAddModalOpen(false)} 
              onSave={handleSaveTransaction} 
              onDelete={handleRequestDelete}
              cashBalance={cashBalance}
              holdings={holdings}
              prices={prices}
              transactions={transactions}
              initialData={editingTransaction}
            />
          </div>
        </div>
      )}

      <GoalModal 
        isOpen={isGoalModalOpen}
        onClose={() => setIsGoalModalOpen(false)}
        goals={goals}
        currentNetWorth={totalNetWorth}
        onSetGoal={handleSetNewGoal}
        onEditGoal={handleEditGoal}
        onDeleteGoal={handleDeleteGoal}
      />

      {confirmConfig.isOpen && (
        <div className="fixed inset-0 z-[70] flex items-center justify-center p-4 animate-fade-in">
          <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-sm" onClick={() => setConfirmConfig(prev => ({ ...prev, isOpen: false }))}></div>
          <div className="relative bg-white dark:bg-slate-900 rounded-2xl shadow-2xl w-full max-w-sm overflow-hidden animate-zoom-in border border-slate-200 dark:border-slate-700">
            <div className="p-6">
              <div className="w-12 h-12 rounded-full bg-rose-100 dark:bg-rose-900/30 flex items-center justify-center text-rose-600 dark:text-rose-400 mb-4 mx-auto">
                 <Trash2 size={24} />
              </div>
              <h3 className="text-lg font-bold font-display text-slate-900 dark:text-white mb-2 text-center">{confirmConfig.title}</h3>
              <p className="text-sm text-slate-500 dark:text-slate-400 mb-6 text-center">{confirmConfig.message}</p>
              <div className="flex space-x-3">
                <button 
                  onClick={() => setConfirmConfig(prev => ({ ...prev, isOpen: false }))} 
                  className="flex-1 py-3 rounded-xl font-bold text-slate-600 dark:text-slate-400 hover:bg-slate-100 dark:hover:bg-slate-800 transition-colors"
                >
                  Cancel
                </button>
                <button 
                  onClick={confirmConfig.onConfirm} 
                  className="flex-1 py-3 rounded-xl font-bold bg-rose-600 text-white hover:bg-rose-700 transition-colors shadow-lg shadow-rose-600/20"
                >
                  Delete
                </button>
              </div>
            </div>
          </div>
        </div>
      )}
    </Layout>
  );
};

interface AddTransactionFormProps {
  onClose: () => void;
  onSave: (t: Transaction) => Promise<void>;
  onDelete?: (id: string) => void;
  cashBalance: number;
  holdings: Holding[];
  prices: Record<string, number>;
  transactions: Transaction[];
  initialData: Transaction | null;
}

const AddTransactionForm: React.FC<AddTransactionFormProps> = ({ onClose, onSave, onDelete, cashBalance, holdings, prices, transactions, initialData }) => {
  const [type, setType] = useState<TransactionType>(TransactionType.BUY);
  const [date, setDate] = useState(new Date().toISOString().split('T')[0]);
  const [symbol, setSymbol] = useState('');

  // Advanced Input State
  const [shares, setShares] = useState('');
  const [price, setPrice] = useState(''); // Price per share
  const [totalAmount, setTotalAmount] = useState(''); // Total transaction value

  const [fee, setFee] = useState('');
  const [assetClass, setAssetClass] = useState<AssetClass>(AssetClass.STOCK);
  const [exchangeRate, setExchangeRate] = useState(''); 
  const [notes, setNotes] = useState('');
  const [error, setError] = useState<string | null>(null);
  const [isSaving, setIsSaving] = useState(false);

  // Auto-Calc Lock (prevent circular updates)
  const [activeInput, setActiveInput] = useState<'shares' | 'price' | 'total' | null>(null);

  useEffect(() => {
    if (initialData) {
      setType(initialData.type);
      setDate(initialData.date);
      setSymbol(initialData.symbol || '');
      setShares(initialData.shares?.toString() || '');
      setPrice(initialData.price?.toString() || '');
      setFee(initialData.fee?.toString() || '');
      setAssetClass(initialData.assetClass || AssetClass.STOCK);
      setExchangeRate(initialData.exchangeRate?.toString() || '');
      setNotes(initialData.notes || '');

      // Init Total Amount
      if (initialData.shares && initialData.price && (initialData.type === TransactionType.BUY || initialData.type === TransactionType.SELL)) {
         setTotalAmount((initialData.shares * initialData.price).toFixed(2));
      } else if (initialData.price) {
         setTotalAmount(initialData.price.toString());
      }
    }
  }, [initialData]);

  // --- SMART AUTO-FILL ---
  // When symbol changes, try to fetch last price and asset class
  useEffect(() => {
    if (!initialData && symbol && !price && !activeInput) {
       const upperSymbol = symbol.toUpperCase();

       // 1. Try to find in current holdings first (most accurate for asset class)
       const holding = holdings.find(h => h.symbol === upperSymbol);
       if (holding) {
          setAssetClass(holding.assetClass);
          if (holding.currentPrice > 0) {
             setPrice(holding.currentPrice.toString());
          }
       } else {
          // 2. Try to find in known prices history
          const knownPrice = prices[upperSymbol];
          if (knownPrice) {
             setPrice(knownPrice.toString());
          }
       }
    }
  }, [symbol, initialData, holdings, prices, activeInput, price]);


  // --- AUTO CALCULATION LOGIC ---
  useEffect(() => {
    const s = parseFloat(shares) || 0;
    const p = parseFloat(price) || 0;
    const t = parseFloat(totalAmount) || 0;

    // 1. If User edits Shares or Price -> Update Total
    if (activeInput === 'shares' || activeInput === 'price') {
       if (s > 0 && p > 0) {
         setTotalAmount((s * p).toFixed(2));
       } else if (s === 0 || p === 0) {
          // Don't clear total immediately if one is missing, acts weird
       }
    }

    // 2. If User edits Total -> Update Shares (if Price exists)
    if (activeInput === 'total') {
       if (t > 0 && p > 0) {
          setShares((t / p).toFixed(4)); // 4 decimals for shares
       }
    }
  }, [shares, price, totalAmount, activeInput]);


  const needsSymbol = [TransactionType.BUY, TransactionType.SELL, TransactionType.DIVIDEND, TransactionType.SPLIT].includes(type);
  const needsShares = [TransactionType.BUY, TransactionType.SELL, TransactionType.SPLIT].includes(type);
  const needsPrice = type !== TransactionType.SPLIT;
  const isFunding = type === TransactionType.DEPOSIT || type === TransactionType.WITHDRAW;

  // Validation Vars
  const numShares = parseFloat(shares) || 0;
  const numPrice = parseFloat(price) || 0;
  const numFee = parseFloat(fee) || 0;

  // Derived Total (re-calculate for validation integrity)
  const calcTotal = (type === TransactionType.SPLIT) ? 0 : (needsShares ? numShares * numPrice : numPrice);

  let netAmount = 0;
  if (type === TransactionType.BUY) netAmount = -(calcTotal + numFee);
  else if (type === TransactionType.SELL) netAmount = (calcTotal - numFee);
  else if (type === TransactionType.DIVIDEND) netAmount = calcTotal;
  else if (type === TransactionType.DEPOSIT) netAmount = calcTotal;
  else if (type === TransactionType.WITHDRAW) netAmount = -calcTotal;

  // --- VALIDATION EFFECTS ---
  useEffect(() => {
    setError(null);
    if (needsShares && numShares < 0) { setError("Shares cannot be negative."); return; }
    if (needsPrice && numPrice < 0) { setError("Price cannot be negative."); return; }
    if (numFee < 0) { setError("Fee cannot be negative."); return; }

    // Duplicate Check
    const isDuplicate = transactions.some(t => {
      if (initialData && t.id === initialData.id) return false;
      return (
        t.date === date && t.type === type && (t.symbol || '') === (symbol.toUpperCase() || '') &&
        (t.shares || 0) === numShares && (t.price || 0) === numPrice
      );
    });
    if (isDuplicate) { setError("Duplicate transaction detected."); return; }

    // Sell Validation
    if (type === TransactionType.SELL && symbol) {
      const holding = holdings.find(h => h.symbol === symbol.toUpperCase());
      let available = holding ? holding.shares : 0;
      if (initialData && initialData.type === TransactionType.SELL && initialData.symbol === symbol.toUpperCase()) {
         available += (initialData.shares || 0);
      }
      if (numShares > available + 0.00001) {
         setError(`Insufficient shares. Owned: ${formatNumber(available, 4)}`);
         return;
      }
    }

    // Cash Validation
    if (type === TransactionType.BUY || type === TransactionType.WITHDRAW) {
       let available = cashBalance;
       if (initialData) {
         // Logic to reverse old tx impact on cash (simplified)
         if (initialData.type === TransactionType.BUY) available += ((initialData.shares||0)*(initialData.price||0)) + (initialData.fee||0);
         else if (initialData.type === TransactionType.WITHDRAW) available += (initialData.price||0);
         else if (initialData.type === TransactionType.DEPOSIT) available -= (initialData.price||0);
         else if (initialData.type === TransactionType.SELL) available -= ((initialData.shares||0)*(initialData.price||0)) - (initialData.fee||0);
         else if (initialData.type === TransactionType.DIVIDEND) available -= (initialData.price||0);
       }
       if (Math.abs(netAmount) > available + 0.01) {
         setError(`Insufficient funds. Available: ${formatCurrency(available)}`);
         return;
       }
    }
  }, [type, calcTotal, cashBalance, numShares, numPrice, numFee, initialData, transactions, date, symbol, holdings, netAmount]);

  let projectedCash = cashBalance;
  if (initialData) {
     let oldImpact = 0;
     // Simplified reversal logic
     if (initialData.type === TransactionType.BUY) oldImpact = -(((initialData.shares||0)*(initialData.price||0)) + (initialData.fee||0));
     else if (initialData.type === TransactionType.SELL) oldImpact = ((initialData.shares||0)*(initialData.price||0)) - (initialData.fee||0);
     else if (initialData.type === TransactionType.DEPOSIT) oldImpact = (initialData.price||0);
     else if (initialData.type === TransactionType.WITHDRAW) oldImpact = -(initialData.price||0);
     else if (initialData.type === TransactionType.DIVIDEND) oldImpact = (initialData.price||0);
     projectedCash = (cashBalance - oldImpact) + netAmount;
  } else {
     projectedCash = cashBalance + netAmount;
  }

  const handleQuickAdd = (h: Holding) => {
    setSymbol(h.symbol);
    setAssetClass(h.assetClass);
    if(h.currentPrice) setPrice(h.currentPrice.toString());
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (error) return;
    // needsPrice is defined as type !== SPLIT. isFunding is included in that set.
    if (needsPrice && calcTotal === 0) {
      setError("Value must be > 0");
      return;
    }
    if (needsSymbol && !symbol) {
      setError("Symbol required");
      return;
    }

    setIsSaving(true);
    await onSave({
      id: initialData ? initialData.id : generateId(),
      date, type,
      symbol: (needsSymbol) ? symbol.toUpperCase() : undefined,
      shares: needsShares ? parseFloat(shares) : undefined,
      price: type === TransactionType.SPLIT ? 0 : parseFloat(price),
      fee: (fee && (type === TransactionType.BUY || type === TransactionType.SELL)) ? parseFloat(fee) : undefined,
      assetClass: (!needsSymbol) ? AssetClass.CASH : assetClass,
      exchangeRate: exchangeRate ? parseFloat(exchangeRate) : 1, 
      notes: notes ? notes : undefined
    });
    setIsSaving(false);
  };

  // Top Holdings for Quick Add
  const quickHoldings = useMemo(() => {
     return [...holdings].sort((a,b) => b.marketValue - a.marketValue).slice(0, 4);
  }, [holdings]);

  return (
    <>
      <div className="shrink-0 flex justify-between items-center p-4 border-b border-slate-100 dark:border-slate-800 bg-slate-50/50 dark:bg-slate-900/50">
        <div>
          <h3 className="text-lg font-display font-bold text-slate-900 dark:text-white">
            {initialData ? 'Edit Transaction' : 'New Transaction'}
          </h3>
          <p className="text-xs text-slate-500">{initialData ? 'Update details' : 'Record your investment activity'}</p>
        </div>
        <button onClick={onClose} className="p-2 rounded-full hover:bg-slate-200 dark:hover:bg-slate-800 text-slate-400 hover:text-slate-600 dark:hover:text-slate-200 transition-colors">
          <X size={20} />
        </button>
      </div>

      <form onSubmit={handleSubmit} className="flex-1 overflow-y-auto min-h-0 p-4 space-y-5 custom-scrollbar">

        {/* Type Selector */}
        <div>
           <div className="grid grid-cols-3 sm:grid-cols-6 gap-2">
              {[
                { id: TransactionType.BUY, icon: <TrendingUp size={14} />, label: 'Buy', color: 'blue' },
                { id: TransactionType.SELL, icon: <TrendingDown size={14} />, label: 'Sell', color: 'rose' },
                { id: TransactionType.DIVIDEND, icon: <DollarSign size={14} />, label: 'Div', color: 'emerald' },
                { id: TransactionType.SPLIT, icon: <GitFork size={14} />, label: 'Split', color: 'purple' },
                { id: TransactionType.DEPOSIT, icon: <Wallet size={14} />, label: 'In', color: 'indigo' },
                { id: TransactionType.WITHDRAW, icon: <Wallet size={14} />, label: 'Out', color: 'orange' },
              ].map((t) => (
                <button
                  key={t.id}
                  type="button"
                  onClick={() => setType(t.id)}
                  className={`flex flex-col items-center justify-center p-2 rounded-lg border transition-all duration-200 ${
                    type === t.id
                      ? `bg-${t.color}-50 border-${t.color}-500 text-${t.color}-700 dark:bg-${t.color}-900/30 dark:border-${t.color}-500 dark:text-${t.color}-300 ring-1 ring-${t.color}-500 shadow-sm`
                      : 'bg-white dark:bg-slate-800 border-slate-200 dark:border-slate-700 text-slate-500 hover:border-slate-300 dark:hover:border-slate-600'
                  }`}
                >
                  <div className="mb-0.5">{t.icon}</div>
                  <span className="text-[10px] font-bold">{t.label}</span>
                </button>
              ))}
           </div>
        </div>

        {/* Date */}
        <div>
           <div className="relative">
             <Calendar className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={16} />
             <input 
              type="date" 
              required
              value={date}
              onChange={(e) => setDate(e.target.value)}
              className="w-full pl-9 pr-3 py-2.5 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl text-slate-900 dark:text-white focus:ring-2 focus:ring-blue-500 outline-none transition-all font-medium text-sm"
            />
           </div>
        </div>

        {needsSymbol && (
          <div className="space-y-2">
            <div className="grid grid-cols-2 gap-3">
              <div className="col-span-1">
                 <label className="block text-[10px] font-bold text-slate-500 uppercase tracking-wider mb-1.5">Symbol</label>
                 <input 
                  type="text" 
                  required
                  placeholder="AAPL"
                  value={symbol}
                  onChange={(e) => setSymbol(e.target.value)}
                  className="w-full px-3 py-2.5 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl text-slate-900 dark:text-white focus:ring-2 focus:ring-blue-500 outline-none uppercase font-bold tracking-wide text-sm"
                />
              </div>
               <div className="col-span-1">
                <label className="block text-[10px] font-bold text-slate-500 uppercase tracking-wider mb-1.5">Class</label>
                <select 
                  value={assetClass} 
                  onChange={(e) => setAssetClass(e.target.value as AssetClass)}
                  className="w-full px-3 py-2.5 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl text-slate-900 dark:text-white focus:ring-2 focus:ring-blue-500 outline-none appearance-none text-sm"
                >
                  {Object.values(AssetClass).filter(a => a !== AssetClass.CASH).map(a => <option key={a} value={a}>{a}</option>)}
                </select>
              </div>
            </div>
            {/* Quick Add Chips */}
            {!initialData && quickHoldings.length > 0 && (
               <div className="flex items-center space-x-2 overflow-x-auto pb-1 no-scrollbar">
                  <Zap size={12} className="text-amber-500 shrink-0" />
                  {quickHoldings.map(h => (
                     <button
                       key={h.symbol}
                       type="button"
                       onClick={() => handleQuickAdd(h)}
                       className="px-2 py-1 bg-slate-100 dark:bg-slate-800 hover:bg-blue-50 dark:hover:bg-blue-900/30 text-xs font-medium text-slate-600 dark:text-slate-300 rounded-md transition-colors border border-transparent hover:border-blue-200 dark:hover:border-blue-800 whitespace-nowrap"
                     >
                       {h.symbol}
                     </button>
                  ))}
               </div>
            )}
          </div>
        )}

        <div className="grid grid-cols-2 gap-3">
           {needsShares && (
            <div className={type === TransactionType.SPLIT ? "col-span-2" : "col-span-1"}>
              <label className="block text-[10px] font-bold text-slate-500 uppercase tracking-wider mb-1.5">
                {type === TransactionType.SPLIT ? "Split Ratio (e.g. 2 for 2:1)" : "Shares"}
              </label>
              <input 
                type="number" 
                step="any"
                min="0"
                required
                placeholder={type === TransactionType.SPLIT ? "2" : "0.00"}
                value={shares}
                onFocus={() => setActiveInput('shares')}
                onChange={(e) => setShares(e.target.value)}
                className="w-full px-3 py-2.5 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl text-slate-900 dark:text-white focus:ring-2 focus:ring-blue-500 outline-none font-mono text-sm"
              />
            </div>
           )}
           {needsPrice && (
             <div className={!needsShares ? "col-span-2" : ""}>
               <label className="block text-[10px] font-bold text-slate-500 uppercase tracking-wider mb-1.5">
                 {needsShares ? "Price / Share" : "Amount ($)"}
               </label>
                <div className="relative">
                  <input 
                    type="number" 
                    step="any"
                    min="0"
                    required
                    placeholder="0.00"
                    value={price}
                    onFocus={() => setActiveInput('price')}
                    onChange={(e) => setPrice(e.target.value)}
                    className="w-full px-3 py-2.5 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl text-slate-900 dark:text-white focus:ring-2 focus:ring-blue-500 outline-none font-mono text-sm"
                  />
                </div>
             </div>
           )}
        </div>

        {/* Total Amount Calculator Field */}
        {needsShares && needsPrice && (
           <div className="bg-blue-50/50 dark:bg-slate-800/50 p-3 rounded-xl border border-blue-100 dark:border-slate-700/50 flex items-center justify-between">
              <div className="flex items-center space-x-2 text-slate-500">
                 <Calculator size={14} />
                 <span className="text-xs font-bold uppercase">Total Amount</span>
              </div>
              <div className="flex items-center space-x-2 w-1/2">
                 <span className="text-slate-400">$</span>
                 <input 
                   type="number"
                   step="any"
                   min="0"
                   value={totalAmount}
                   onFocus={() => setActiveInput('total')}
                   onChange={(e) => setTotalAmount(e.target.value)}
                   placeholder="0.00"
                   className="w-full bg-transparent border-b border-slate-300 dark:border-slate-600 focus:border-blue-500 outline-none text-right font-mono font-bold text-slate-900 dark:text-white"
                 />
              </div>
           </div>
        )}

        {(type === TransactionType.BUY || type === TransactionType.SELL) && (
           <div>
              <label className="block text-[10px] font-bold text-slate-500 uppercase tracking-wider mb-1.5">
                Fee (Optional)
              </label>
              <input 
                type="number" 
                step="any"
                min="0"
                placeholder="0.00"
                value={fee}
                onChange={(e) => setFee(e.target.value)}
                className="w-full px-3 py-2.5 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl text-slate-900 dark:text-white focus:ring-2 focus:ring-blue-500 outline-none font-mono text-sm"
              />
           </div>
        )}

        {isFunding && (
           <div className="bg-blue-50 dark:bg-slate-800/50 p-3 rounded-xl border border-blue-100 dark:border-slate-700">
             <label className="block text-[10px] font-bold text-slate-500 uppercase tracking-wider mb-1.5">
               Exchange Rate (Optional)
             </label>
              <div className="flex items-center space-x-2">
                <input 
                  type="number" 
                  step="any"
                  min="0"
                  placeholder="1.00"
                  value={exchangeRate}
                  onChange={(e) => setExchangeRate(e.target.value)}
                  className="flex-1 px-3 py-2 bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-600 rounded-lg text-slate-900 dark:text-white focus:ring-2 focus:ring-blue-500 outline-none font-mono text-right text-sm"
                />
                <span className="text-xs font-medium text-slate-500">Local / USD</span>
              </div>
           </div>
        )}

        <div>
           <label className="block text-[10px] font-bold text-slate-500 uppercase tracking-wider mb-1.5">Notes (Optional)</label>
           <textarea
             rows={2}
             placeholder="Add a memo..."
             value={notes}
             onChange={(e) => setNotes(e.target.value)}
             className="w-full px-3 py-2.5 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl text-slate-900 dark:text-white focus:ring-2 focus:ring-blue-500 outline-none resize-none font-medium text-sm"
           />
        </div>
      </form>

      <div className="shrink-0 bg-white dark:bg-slate-900 border-t border-slate-100 dark:border-slate-800 p-4 shadow-[0_-4px_6px_-1px_rgba(0,0,0,0.05)] z-10">
         <div className="flex flex-col space-y-3 mb-4">
               {/* Main Details */}
               <div className="flex justify-between items-center">
                   <div>
                      <p className="text-xs text-slate-500 dark:text-slate-400 font-medium uppercase tracking-wider mb-0.5">Net Amount</p>
                      <div className="flex items-baseline space-x-2">
                         <span className={`text-2xl font-bold font-display ${
                             netAmount > 0 ? 'text-emerald-600 dark:text-emerald-400' : 
                             netAmount < 0 ? 'text-slate-900 dark:text-white' : 'text-slate-500'
                         }`}>
                            {netAmount > 0 ? '+' : ''}{formatCurrency(netAmount)}
                         </span>
                      </div>
                   </div>
                   <div className="text-right">
                      <p className="text-xs text-slate-500 dark:text-slate-400 font-medium uppercase tracking-wider mb-0.5">Cash Balance</p>
                      <div className="flex items-center justify-end space-x-2 text-sm">
                         <span className="text-slate-400 line-through decoration-slate-300 dark:decoration-slate-600">{formatCurrency(cashBalance)}</span>
                         <ArrowRight size={14} className="text-slate-300" />
                         <span className={`font-bold ${projectedCash < 0 ? 'text-rose-500' : 'text-slate-700 dark:text-slate-300'}`}>
                            {formatCurrency(projectedCash)}
                         </span>
                      </div>
                   </div>
               </div>
         </div>

         {error && (
           <div className="bg-rose-50 dark:bg-rose-900/20 border border-rose-200 dark:border-rose-800 rounded-xl p-3 mb-4 flex items-start space-x-3 text-rose-600 dark:text-rose-400 animate-slide-up">
               <AlertCircle size={18} className="shrink-0 mt-0.5" />
               <div className="text-sm font-semibold">{error}</div>
           </div>
         )}

          <div className="flex gap-3">
            {initialData && onDelete && (
               <button
                 type="button"
                 onClick={() => onDelete(initialData.id)}
                 className="px-4 py-3 rounded-xl font-bold bg-rose-50 text-rose-500 hover:bg-rose-100 dark:bg-rose-900/20 dark:text-rose-400 transition-colors"
               >
                 <Trash2 size={20} />
               </button>
            )}

            <button 
              onClick={handleSubmit}
              disabled={!!error || isSaving}
              className={`flex-1 font-bold py-3 rounded-xl shadow-lg transition-all flex items-center justify-center space-x-2 text-base ${
                error || isSaving
                  ? 'bg-slate-300 dark:bg-slate-700 text-slate-500 cursor-not-allowed' 
                  : 'bg-slate-900 dark:bg-blue-600 hover:opacity-90 text-white shadow-slate-900/20 dark:shadow-blue-600/20 active:scale-95'
              }`}
            >
              {isSaving ? (
                <Spinner className="text-white" />
              ) : (
                <>
                  <Save size={18} />
                  <span>{initialData ? 'Update Transaction' : 'Save Transaction'}</span>
                </>
              )}
            </button>
          </div>
      </div>
    </>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { FinancialGoal } from '../types';
import { X, Target, Save, CheckCircle2, XCircle, Calendar, ArrowRight, History, TrendingUp, Edit2, Trash2, Plus, AlertTriangle } from 'lucide-react';
import { formatCurrency } from '../utils';

interface GoalModalProps {
  isOpen: boolean;
  onClose: () => void;
  goals: FinancialGoal[];
  currentNetWorth: number;
  onSetGoal: (amount: number, notes: string) => void;
  onEditGoal: (goal: FinancialGoal) => void;
  onDeleteGoal: (id: string) => void;
}

const GoalModal: React.FC<GoalModalProps> = ({ isOpen, onClose, goals, currentNetWorth, onSetGoal, onEditGoal, onDeleteGoal }) => {
  // Form State
  const [amount, setAmount] = useState<string>('');
  const [notes, setNotes] = useState('');
  const [startDate, setStartDate] = useState('');
  const [isEndDateSet, setIsEndDateSet] = useState(false); // For editing purely

  // Edit Mode State
  const [editingGoal, setEditingGoal] = useState<FinancialGoal | null>(null);

  // Delete Confirmation State
  const [deleteId, setDeleteId] = useState<string | null>(null);

  useEffect(() => {
    if (isOpen) {
      resetForm();
    }
  }, [isOpen]);

  const resetForm = () => {
    setEditingGoal(null);
    setAmount('');
    setNotes('');
    setStartDate(new Date().toISOString().split('T')[0]);
    setIsEndDateSet(false);
    setDeleteId(null);
  };

  const handleEditClick = (goal: FinancialGoal) => {
    setEditingGoal(goal);
    setAmount(goal.targetAmount.toString());
    setNotes(goal.notes || '');
    setStartDate(goal.startDate.split('T')[0]);
    setIsEndDateSet(!!goal.endDate);
  };

  const onRequestDelete = (id: string) => {
    setDeleteId(id);
  };

  const confirmDelete = () => {
    if (deleteId) {
      onDeleteGoal(deleteId);
      if (editingGoal && editingGoal.id === deleteId) {
        resetForm();
      }
      setDeleteId(null);
    }
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const numAmount = parseFloat(amount);

    if (numAmount > 0) {
      if (editingGoal) {
        // Update existing
        onEditGoal({
          ...editingGoal,
          targetAmount: numAmount,
          notes: notes,
          startDate: startDate // Update start date if changed
        });
        resetForm();
      } else {
        // Create new
        onSetGoal(numAmount, notes);
        resetForm();
        onClose();
      }
    }
  };

  if (!isOpen) return null;

  // Sort goals: Active first, then by end date descending
  const sortedGoals = [...goals].sort((a, b) => {
    if (!a.endDate && b.endDate) return -1;
    if (a.endDate && !b.endDate) return 1;
    return new Date(b.startDate).getTime() - new Date(a.startDate).getTime();
  });

  const activeGoal = goals.find(g => !g.endDate);

  // Calculate progress for the *currently viewed/edited* goal context or the active goal
  const displayGoal = editingGoal || activeGoal;
  const progressPercentage = displayGoal ? Math.min((currentNetWorth / displayGoal.targetAmount) * 100, 100) : 0;

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
      <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-sm animate-fade-in" onClick={onClose}></div>
      <div className="relative bg-white dark:bg-slate-900 w-full max-w-4xl rounded-3xl shadow-2xl overflow-hidden animate-zoom-in border border-slate-200 dark:border-slate-800 flex flex-col max-h-[90vh]">

        {/* Internal Delete Confirmation Overlay */}
        {deleteId && (
          <div className="absolute inset-0 z-10 bg-white/90 dark:bg-slate-900/90 backdrop-blur-sm flex items-center justify-center p-6 animate-fade-in">
             <div className="bg-white dark:bg-slate-800 rounded-2xl shadow-2xl border border-slate-200 dark:border-slate-700 p-6 max-w-sm w-full animate-zoom-in">
                <div className="w-12 h-12 rounded-full bg-rose-100 dark:bg-rose-900/30 flex items-center justify-center text-rose-600 dark:text-rose-400 mb-4 mx-auto">
                   <AlertTriangle size={24} />
                </div>
                <h3 className="text-lg font-bold font-display text-slate-900 dark:text-white mb-2 text-center">Delete Goal?</h3>
                <p className="text-sm text-slate-500 dark:text-slate-400 mb-6 text-center">
                  Are you sure you want to remove this goal from your history? This action cannot be undone.
                </p>
                <div className="flex space-x-3">
                  <button 
                    onClick={() => setDeleteId(null)}
                    className="flex-1 py-2.5 rounded-xl font-bold text-slate-600 dark:text-slate-400 hover:bg-slate-100 dark:hover:bg-slate-700 transition-colors"
                  >
                    Cancel
                  </button>
                  <button 
                    onClick={confirmDelete}
                    className="flex-1 py-2.5 rounded-xl font-bold bg-rose-600 text-white hover:bg-rose-700 transition-colors shadow-lg shadow-rose-600/20"
                  >
                    Delete
                  </button>
                </div>
             </div>
          </div>
        )}

        {/* Header */}
        <div className="flex justify-between items-center p-6 border-b border-slate-100 dark:border-slate-800 bg-slate-50/50 dark:bg-slate-900/50 shrink-0">
           <div className="flex items-center space-x-3">
             <div className="bg-blue-100 dark:bg-blue-900/30 p-2 rounded-xl text-blue-600 dark:text-blue-400">
               <Target size={24} />
             </div>
             <div>
               <h2 className="text-xl font-display font-bold text-slate-900 dark:text-white">Financial Goal</h2>
               <p className="text-sm text-slate-500">Set targets and track your journey</p>
             </div>
           </div>
           <button onClick={onClose} className="p-2 rounded-full hover:bg-slate-200 dark:hover:bg-slate-800 transition-colors text-slate-500">
             <X size={20} />
           </button>
        </div>

        <div className="overflow-hidden flex flex-col md:flex-row flex-1 min-h-0">

           {/* Left Column: Form & Current Status */}
           <div className="flex-1 flex flex-col p-6 overflow-y-auto custom-scrollbar border-b md:border-b-0 md:border-r border-slate-100 dark:border-slate-800">

              {/* Status Card (Visualizes either the Active Goal or the one being edited) */}
              {displayGoal && (
                 <div className={`p-5 rounded-2xl border mb-6 transition-all ${
                    editingGoal 
                      ? 'bg-amber-50 dark:bg-amber-900/10 border-amber-200 dark:border-amber-800/30' 
                      : 'bg-slate-50 dark:bg-slate-800/50 border-slate-200 dark:border-slate-700'
                 }`}>
                    <div className="flex justify-between items-start mb-4">
                       <span className={`text-xs font-bold uppercase tracking-wider ${editingGoal ? 'text-amber-600 dark:text-amber-500' : 'text-slate-500'}`}>
                          {editingGoal ? 'Editing Goal Record' : 'Current Target'}
                       </span>
                       {!displayGoal.endDate ? (
                         <span className="px-2 py-0.5 bg-emerald-100 dark:bg-emerald-900/30 text-emerald-700 dark:text-emerald-400 text-[10px] font-bold uppercase rounded-full flex items-center">
                           <TrendingUp size={12} className="mr-1" /> Ongoing
                         </span>
                       ) : (
                         <span className="px-2 py-0.5 bg-slate-200 dark:bg-slate-700 text-slate-600 dark:text-slate-400 text-[10px] font-bold uppercase rounded-full">
                           Past Record
                         </span>
                       )}
                    </div>

                    <div className="flex items-baseline space-x-2 mb-1">
                      <div className="text-3xl font-display font-bold text-slate-900 dark:text-white">
                        {formatCurrency(displayGoal.targetAmount)}
                      </div>
                    </div>

                    <div className="text-sm text-slate-500 dark:text-slate-400 mb-4 flex items-center">
                      <Calendar size={12} className="mr-1.5" />
                      Started {new Date(displayGoal.startDate).toLocaleDateString()}
                    </div>

                    {/* Progress Bar (Only meaningful for active goals or active context) */}
                    <div className="relative pt-1">
                      <div className="flex mb-2 items-center justify-between">
                        <span className="text-xs font-semibold inline-block text-blue-600 dark:text-blue-400">
                          {progressPercentage.toFixed(1)}% Achieved
                        </span>
                         <span className="text-xs font-medium text-slate-400">
                           Current: {formatCurrency(currentNetWorth)}
                         </span>
                      </div>
                      <div className="overflow-hidden h-2 mb-1 text-xs flex rounded-full bg-slate-200 dark:bg-slate-700">
                        <div style={{ width: `${progressPercentage}%` }} className="shadow-none flex flex-col text-center whitespace-nowrap text-white justify-center bg-blue-500 transition-all duration-1000"></div>
                      </div>
                    </div>
                 </div>
              )}

              {/* Form Section */}
              <div className="flex-1 flex flex-col justify-end">
                 <div className="flex items-center justify-between mb-4">
                    <h3 className="font-bold text-slate-900 dark:text-white flex items-center">
                       {editingGoal ? <Edit2 size={16} className="mr-2 text-amber-500"/> : <Plus size={16} className="mr-2 text-blue-500"/>}
                       {editingGoal ? 'Update Goal Details' : 'Set New Target'}
                    </h3>
                    {editingGoal && (
                       <button 
                         onClick={resetForm} 
                         className="text-xs font-medium text-slate-500 hover:text-slate-700 dark:text-slate-400 dark:hover:text-white underline"
                       >
                         Cancel Edit
                       </button>
                    )}
                 </div>

                 <form onSubmit={handleSubmit} className="space-y-4">
                    <div>
                      <label className="block text-xs font-bold text-slate-500 uppercase tracking-wider mb-1.5">Target Amount</label>
                      <div className="relative">
                        <span className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400 font-bold">$</span>
                        <input 
                          type="number" 
                          required
                          min="1"
                          placeholder="e.g. 100000"
                          value={amount}
                          onChange={(e) => setAmount(e.target.value)}
                          className="w-full pl-8 pr-4 py-3 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl text-slate-900 dark:text-white focus:ring-2 focus:ring-blue-500 outline-none font-bold text-lg"
                        />
                      </div>
                    </div>

                    {/* Show Date Picker only if Editing (to fix history) or if creating new one (optional, defaults to today) */}
                    {editingGoal && (
                       <div>
                         <label className="block text-xs font-bold text-slate-500 uppercase tracking-wider mb-1.5">Start Date</label>
                         <div className="relative">
                           <Calendar className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={16} />
                           <input 
                             type="date"
                             required
                             value={startDate}
                             onChange={(e) => setStartDate(e.target.value)}
                             className="w-full pl-10 pr-4 py-3 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl text-slate-900 dark:text-white focus:ring-2 focus:ring-blue-500 outline-none font-medium text-sm"
                           />
                         </div>
                       </div>
                    )}

                    <div>
                      <label className="block text-xs font-bold text-slate-500 uppercase tracking-wider mb-1.5">Notes (Optional)</label>
                      <textarea 
                        rows={editingGoal ? 3 : 2}
                        placeholder="What are you saving for?"
                        value={notes}
                        onChange={(e) => setNotes(e.target.value)}
                        className="w-full px-4 py-3 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl text-slate-900 dark:text-white focus:ring-2 focus:ring-blue-500 outline-none text-sm resize-none"
                      />
                    </div>

                    <button 
                      type="submit"
                      className={`w-full py-3 text-white font-bold rounded-xl hover:opacity-90 transition-opacity flex items-center justify-center space-x-2 shadow-lg shadow-blue-500/20 ${editingGoal ? 'bg-amber-500' : 'bg-slate-900 dark:bg-blue-600'}`}
                    >
                      {editingGoal ? <Save size={18} /> : <Target size={18} />}
                      <span>{editingGoal ? 'Update Goal' : (activeGoal ? 'Start New Goal' : 'Set Goal')}</span>
                    </button>
                    {!editingGoal && activeGoal && (
                       <p className="text-center text-xs text-slate-400 mt-2">
                         Starting a new goal will mark the current one as completed/ended.
                       </p>
                    )}
                 </form>
              </div>
           </div>

           {/* Right Column: History */}
           <div className="flex-1 bg-slate-50 dark:bg-slate-800/30 p-6 flex flex-col overflow-hidden min-h-[300px]">
              <div className="flex items-center justify-between mb-4">
                 <div className="flex items-center space-x-2 text-slate-500 dark:text-slate-400">
                    <History size={18} />
                    <span className="font-bold text-sm uppercase tracking-wider">Goal History</span>
                 </div>
                 <span className="text-xs font-medium text-slate-400">{goals.length} records</span>
              </div>

              <div className="space-y-4 overflow-y-auto custom-scrollbar pr-2 flex-1 pb-4">
                 {sortedGoals.map((goal) => {
                    const isActive = !goal.endDate;
                    const isEditing = editingGoal?.id === goal.id;
                    return (
                      <div 
                        key={goal.id} 
                        className={`p-4 rounded-xl border transition-all group ${
                           isEditing 
                           ? 'bg-amber-50 dark:bg-amber-900/20 border-amber-400 ring-1 ring-amber-400'
                           : isActive 
                              ? 'bg-white dark:bg-slate-800 border-blue-200 dark:border-blue-900 shadow-sm' 
                              : 'bg-white dark:bg-slate-800 border-slate-200 dark:border-slate-700 opacity-80 hover:opacity-100'
                        }`}
                      >
                         <div className="flex justify-between items-start mb-2">
                            <div>
                               <div className="text-lg font-bold font-display text-slate-900 dark:text-white">
                                 {formatCurrency(goal.targetAmount)}
                               </div>
                               <div className="mt-1">
                                  {isActive ? (
                                    <span className="text-[10px] font-bold bg-blue-100 dark:bg-blue-900/30 text-blue-600 dark:text-blue-400 px-2 py-0.5 rounded-full">ACTIVE</span>
                                  ) : (
                                     goal.isAchieved ? (
                                       <span className="text-[10px] font-bold bg-emerald-100 dark:bg-emerald-900/30 text-emerald-600 dark:text-emerald-400 px-2 py-0.5 rounded-full flex items-center w-fit">
                                         <CheckCircle2 size={10} className="mr-1" /> REACHED
                                       </span>
                                     ) : (
                                       <span className="text-[10px] font-bold bg-slate-100 dark:bg-slate-700 text-slate-500 dark:text-slate-400 px-2 py-0.5 rounded-full flex items-center w-fit">
                                         <XCircle size={10} className="mr-1" /> ENDED
                                       </span>
                                     )
                                  )}
                               </div>
                            </div>

                            {/* Actions */}
                            <div className="flex space-x-1 opacity-100 sm:opacity-0 sm:group-hover:opacity-100 transition-opacity">
                               <button 
                                 onClick={() => handleEditClick(goal)}
                                 className="p-2 text-slate-400 hover:text-blue-500 hover:bg-blue-50 dark:hover:bg-blue-900/20 rounded-lg transition-colors"
                                 title="Edit"
                               >
                                 <Edit2 size={14} />
                               </button>
                               <button 
                                 onClick={() => onRequestDelete(goal.id)}
                                 className="p-2 text-slate-400 hover:text-rose-500 hover:bg-rose-50 dark:hover:bg-rose-900/20 rounded-lg transition-colors"
                                 title="Delete"
                               >
                                 <Trash2 size={14} />
                               </button>
                            </div>
                         </div>

                         <div className="flex items-center text-xs text-slate-500 dark:text-slate-400 mb-2 mt-2">
                            <Calendar size={12} className="mr-1.5" />
                            <span>{new Date(goal.startDate).toLocaleDateString()}</span>
                            {goal.endDate && (
                              <>
                                <ArrowRight size={12} className="mx-1" />
                                <span>{new Date(goal.endDate).toLocaleDateString()}</span>
                              </>
                            )}
                         </div>

                         {goal.notes && (
                           <p className="text-xs text-slate-600 dark:text-slate-300 bg-slate-50 dark:bg-slate-700/50 p-2 rounded-lg italic">
                             "{goal.notes}"
                           </p>
                         )}
                      </div>
                    );
                 })}
                 {sortedGoals.length === 0 && (
                   <div className="text-center py-10 text-slate-400 text-sm">
                     No history yet. Set your first goal!
                   </div>
                 )}
              </div>
           </div>

        </div>
      </div>
    </div>
  );
};

