import React, { useState, useEffect, useMemo } from 'react';
import Layout from './components/Layout';
import Dashboard from './components/Dashboard';
import Holdings from './components/Holdings';
import Reports from './components/Reports';
import History from './components/History';
import GoalModal from './components/GoalModal';
import { Transaction, TransactionType, AssetClass, Holding, Portfolio, FinancialGoal } from './types';
import { calculateHoldings, calculatePortfolioHistory, generateId, formatCurrency, formatNumber } from './utils';
import { X, Save, TrendingUp, TrendingDown, DollarSign, Wallet, Calendar, GitFork, AlertCircle, ArrowRight, Trash2, Zap, Calculator } from 'lucide-react';
import { Spinner } from './components/LoadingSkeletons';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState('dashboard');
  const [isAddModalOpen, setIsAddModalOpen] = useState(false);
  const [editingTransaction, setEditingTransaction] = useState<Transaction | null>(null);
  const [isLoading, setIsLoading] = useState(true); 

  // Goal Modal State
  const [isGoalModalOpen, setIsGoalModalOpen] = useState(false);

  // --- CONFIRMATION MODAL STATE ---
  const [confirmConfig, setConfirmConfig] = useState<{
    isOpen: boolean;
    title: string;
    message: string;
    onConfirm: () => void;
  }>({
    isOpen: false,
    title: '',
    message: '',
    onConfirm: () => {},
  });

  // --- PORTFOLIO MANAGEMENT STATE ---
  const [portfolios, setPortfolios] = useState<Portfolio[]>(() => {
    const saved = localStorage.getItem('portfolios');
    if (saved) return JSON.parse(saved);

    // Migration: If no portfolios exist but we have legacy transactions, create a default one
    const legacyTx = localStorage.getItem('transactions');
    if (legacyTx) {
      return [{ id: 'default', name: 'Main Portfolio' }];
    }

    return [{ id: generateId(), name: 'My First Portfolio' }];
  });

  const [activePortfolioId, setActivePortfolioId] = useState<string>(() => {
    const saved = localStorage.getItem('activePortfolioId');
    const portfolios = JSON.parse(localStorage.getItem('portfolios') || '[]');
    if (saved && portfolios.some((p: Portfolio) => p.id === saved)) return saved;
    return portfolios.length > 0 ? portfolios[0].id : 'default';
  });

  // --- DATA STATE (Per Portfolio) ---
  const [transactions, setTransactions] = useState<Transaction[]>([]);
  const [prices, setPrices] = useState<Record<string, number>>({});

  // New Goals State
  const [goals, setGoals] = useState<FinancialGoal[]>([]);

  const [isDataLoaded, setIsDataLoaded] = useState(false);

  // --- PERSISTENCE: Portfolios List ---
  useEffect(() => {
    localStorage.setItem('portfolios', JSON.stringify(portfolios));
  }, [portfolios]);

  useEffect(() => {
    localStorage.setItem('activePortfolioId', activePortfolioId);
  }, [activePortfolioId]);

  // --- PERSISTENCE: Load Data on Portfolio Switch ---
  useEffect(() => {
    setIsLoading(true);
    setIsDataLoaded(false); 

    const loadData = () => {
        const txKey = `transactions_${activePortfolioId}`;
        const pricesKey = `prices_${activePortfolioId}`;
        const goalsKey = `goals_${activePortfolioId}`;
        // Legacy goal key support
        const legacyGoalKey = `financialGoal_${activePortfolioId}`;

        // Load Transactions
        const savedTx = localStorage.getItem(txKey);
        if (savedTx) {
          setTransactions(JSON.parse(savedTx));
        } else if (activePortfolioId === 'default' && localStorage.getItem('transactions')) {
          setTransactions(JSON.parse(localStorage.getItem('transactions')!));
        } else {
          setTransactions([]);
        }

        // Load Prices
        const savedPrices = localStorage.getItem(pricesKey);
        if (savedPrices) {
          setPrices(JSON.parse(savedPrices));
        } else if (activePortfolioId === 'default' && localStorage.getItem('prices')) {
          setPrices(JSON.parse(localStorage.getItem('prices')!));
        } else {
          setPrices({});
        }

        // Load Goals with Legacy Migration
        const savedGoals = localStorage.getItem(goalsKey);
        if (savedGoals) {
           setGoals(JSON.parse(savedGoals));
        } else {
           // Check for legacy goal
           let legacyGoal = 100000;
           const savedLegacy = localStorage.getItem(legacyGoalKey);
           if (savedLegacy) {
             legacyGoal = parseFloat(savedLegacy);
           } else if (activePortfolioId === 'default' && localStorage.getItem('financialGoal')) {
             legacyGoal = parseFloat(localStorage.getItem('financialGoal')!);
           }

           // Create initial goal from legacy
           const initialGoal: FinancialGoal = {
             id: generateId(),
             targetAmount: legacyGoal,
             startDate: new Date().toISOString(),
             isAchieved: false,
             notes: 'Initial Goal'
           };
           setGoals([initialGoal]);
        }

        setIsDataLoaded(true);
        setTimeout(() => setIsLoading(false), 600);
    };

    requestAnimationFrame(loadData);

  }, [activePortfolioId]);

  useEffect(() => {
    if (!isDataLoaded) return;
    localStorage.setItem(`transactions_${activePortfolioId}`, JSON.stringify(transactions));
  }, [transactions, activePortfolioId, isDataLoaded]);

  useEffect(() => {
    if (!isDataLoaded) return;
    localStorage.setItem(`prices_${activePortfolioId}`, JSON.stringify(prices));
  }, [prices, activePortfolioId, isDataLoaded]);

  useEffect(() => {
    if (!isDataLoaded) return;
    localStorage.setItem(`goals_${activePortfolioId}`, JSON.stringify(goals));
  }, [goals, activePortfolioId, isDataLoaded]);


  // --- CALCULATIONS ---
  const holdings = useMemo(() => calculateHoldings(transactions, prices), [transactions, prices]);
  const chartData = useMemo(() => calculatePortfolioHistory(transactions, prices), [transactions, prices]);

  const investedAmount = transactions.reduce((sum, t) => {
    if (t.type === TransactionType.DEPOSIT) return sum + (t.price || 0);
    if (t.type === TransactionType.WITHDRAW) return sum - (t.price || 0);
    return sum;
  }, 0);

  const cashBalance = useMemo(() => {
    let balance = 0;
    transactions.forEach(t => {
      if (t.type === TransactionType.DEPOSIT) balance += (t.price || 0);
      if (t.type === TransactionType.WITHDRAW) balance -= (t.price || 0);
      if (t.type === TransactionType.BUY) balance -= (t.price! * t.shares!) + (t.fee || 0);
      if (t.type === TransactionType.SELL) balance += (t.price! * t.shares!) - (t.fee || 0);
      if (t.type === TransactionType.DIVIDEND) balance += (t.price || 0);
    });
    return balance;
  }, [transactions]);

  const portfolioValue = holdings.reduce((sum, h) => sum + h.marketValue, 0);
  const totalNetWorth = portfolioValue + cashBalance;

  // Active Goal Logic
  const activeGoal = useMemo(() => {
    return goals.find(g => !g.endDate) || { targetAmount: 100000 } as FinancialGoal;
  }, [goals]);

  // --- HANDLERS ---
  const handleOpenAddModal = () => {
    setEditingTransaction(null);
    setIsAddModalOpen(true);
  };

  const handleOpenEditModal = (tx: Transaction) => {
    setEditingTransaction(tx);
    setIsAddModalOpen(true);
  };

  const handleSaveTransaction = (tx: Transaction) => {
    // Simulate slight delay for better UX (loading state)
    return new Promise<void>((resolve) => {
      setTimeout(() => {
        if (editingTransaction) {
          setTransactions(prev => prev.map(t => t.id === tx.id ? tx : t));
        } else {
          setTransactions(prev => [...prev, tx]);
        }

        if ((tx.type === TransactionType.BUY || tx.type === TransactionType.SELL) && tx.symbol && tx.price) {
            setPrices(prev => ({...prev, [tx.symbol!]: tx.price!}));
        }

        setIsAddModalOpen(false);
        setEditingTransaction(null);
        resolve();
      }, 500);
    });
  };

  const handleUpdatePrice = (symbol: string, newPrice: number) => {
    setPrices(prev => ({ ...prev, [symbol]: newPrice }));
  };

  const handleDeleteTransaction = (id: string) => {
    setTransactions(prev => prev.filter(t => t.id !== id));
    if (editingTransaction && editingTransaction.id === id) {
       setIsAddModalOpen(false);
       setEditingTransaction(null);
    }
  };

  const handleRequestDelete = (id: string) => {
      setConfirmConfig({
          isOpen: true,
          title: 'Delete Transaction',
          message: 'Are you sure you want to delete this transaction? This action cannot be undone.',
          onConfirm: () => {
              handleDeleteTransaction(id);
              setConfirmConfig(prev => ({ ...prev, isOpen: false }));
          }
      });
  };

  const handleImportTransactions = (importedTxs: Transaction[]) => {
      // Merge logic: Update if exists, Add if not
      setTransactions(prev => {
          const currentMap = new Map(prev.map(t => [t.id, t]));
          importedTxs.forEach(t => {
              currentMap.set(t.id, t);
          });
          return Array.from(currentMap.values());
      });
      alert(`Imported ${importedTxs.length} transactions successfully.`);
  };

  // Portfolio Management Handlers
  const handleCreatePortfolio = (name: string) => {
    const newId = generateId();
    const newPortfolio = { id: newId, name };
    setPortfolios([...portfolios, newPortfolio]);
    setActivePortfolioId(newId);
  };

  const handleRenamePortfolio = (id: string, newName: string) => {
    setPortfolios(prev => prev.map(p => p.id === id ? { ...p, name: newName } : p));
  };

  const handleDeletePortfolio = (id: string) => {
    if (portfolios.length <= 1) {
      alert("You must have at least one portfolio.");
      return;
    }
    setConfirmConfig({
        isOpen: true,
        title: 'Delete Portfolio',
        message: 'Are you sure you want to delete this entire portfolio? All transactions within it will be permanently lost.',
        onConfirm: () => {
             localStorage.removeItem(`transactions_${id}`);
             localStorage.removeItem(`prices_${id}`);
             localStorage.removeItem(`goals_${id}`);
             localStorage.removeItem(`financialGoal_${id}`);

             const newPortfolios = portfolios.filter(p => p.id !== id);
             setPortfolios(newPortfolios);

             if (activePortfolioId === id) {
               setActivePortfolioId(newPortfolios[0].id);
             }
             setConfirmConfig(prev => ({ ...prev, isOpen: false }));
        }
    });
  };

  // Goals Handler
  const handleSetNewGoal = (targetAmount: number, notes: string) => {
    const now = new Date().toISOString();

    setGoals(prev => {
      const updatedGoals = prev.map(g => {
        // If there's an active goal, end it.
        if (!g.endDate) {
           const achieved = totalNetWorth >= g.targetAmount;
           return { ...g, endDate: now, isAchieved: achieved };
        }
        return g;
      });

      const newGoal: FinancialGoal = {
        id: generateId(),
        targetAmount,
        startDate: now,
        isAchieved: false,
        notes
      };

      return [...updatedGoals, newGoal];
    });
  };

  const handleEditGoal = (updatedGoal: FinancialGoal) => {
      setGoals(prev => prev.map(g => g.id === updatedGoal.id ? updatedGoal : g));
  };

  const handleDeleteGoal = (id: string) => {
      setGoals(prev => prev.filter(g => g.id !== id));
  };

  return (
    <Layout 
      activeTab={activeTab} 
      setActiveTab={setActiveTab} 
      onOpenAddModal={handleOpenAddModal}
      portfolios={portfolios}
      activePortfolioId={activePortfolioId}
      onSwitchPortfolio={setActivePortfolioId}
      onCreatePortfolio={handleCreatePortfolio}
      onRenamePortfolio={handleRenamePortfolio}
      onDeletePortfolio={handleDeletePortfolio}
    >
      <div key={activePortfolioId} className="h-full">
        {activeTab === 'dashboard' && (
          <Dashboard 
            isLoading={isLoading}
            holdings={holdings} 
            transactions={transactions} 
            financialGoal={activeGoal.targetAmount}
            onOpenGoalModal={() => setIsGoalModalOpen(true)}
            investedAmount={investedAmount}
            cashBalance={cashBalance}
            portfolioValue={portfolioValue}
            chartData={chartData}
          />
        )}
        {activeTab === 'holdings' && (
          <Holdings 
            isLoading={isLoading}
            holdings={holdings} 
            transactions={transactions} 
            onUpdatePrice={handleUpdatePrice} 
          />
        )}
        {activeTab === 'history' && (
          <History 
            isLoading={isLoading}
            transactions={transactions} 
            onDelete={handleRequestDelete}
            onEdit={handleOpenEditModal}
            onAdd={handleOpenAddModal}
            onImport={handleImportTransactions}
          />
        )}
        {activeTab === 'reports' && (
           <Reports 
             isLoading={isLoading}
             transactions={transactions} 
             currentPortfolioValue={portfolioValue + cashBalance} 
             chartData={chartData} 
           />
        )}
      </div>

      {isAddModalOpen && (
        <div className="fixed inset-0 z-50 flex items-end sm:items-center justify-center sm:p-4">
          <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-sm animate-fade-in" onClick={() => setIsAddModalOpen(false)}></div>
          <div className="relative bg-white dark:bg-slate-900 w-full max-w-lg 
                          rounded-t-3xl sm:rounded-3xl border border-slate-200 dark:border-slate-800 
                          shadow-2xl overflow-hidden animate-slide-up flex flex-col
                          max-h-[90dvh] sm:max-h-[85vh]">
            <AddTransactionForm 
              onClose={() => setIsAddModalOpen(false)} 
              onSave={handleSaveTransaction} 
              onDelete={handleRequestDelete}
              cashBalance={cashBalance}
              holdings={holdings}
              prices={prices}
              transactions={transactions}
              initialData={editingTransaction}
            />
          </div>
        </div>
      )}

      <GoalModal 
        isOpen={isGoalModalOpen}
        onClose={() => setIsGoalModalOpen(false)}
        goals={goals}
        currentNetWorth={totalNetWorth}
        onSetGoal={handleSetNewGoal}
        onEditGoal={handleEditGoal}
        onDeleteGoal={handleDeleteGoal}
      />

      {confirmConfig.isOpen && (
        <div className="fixed inset-0 z-[70] flex items-center justify-center p-4 animate-fade-in">
          <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-sm" onClick={() => setConfirmConfig(prev => ({ ...prev, isOpen: false }))}></div>
          <div className="relative bg-white dark:bg-slate-900 rounded-2xl shadow-2xl w-full max-w-sm overflow-hidden animate-zoom-in border border-slate-200 dark:border-slate-700">
            <div className="p-6">
              <div className="w-12 h-12 rounded-full bg-rose-100 dark:bg-rose-900/30 flex items-center justify-center text-rose-600 dark:text-rose-400 mb-4 mx-auto">
                 <Trash2 size={24} />
              </div>
              <h3 className="text-lg font-bold font-display text-slate-900 dark:text-white mb-2 text-center">{confirmConfig.title}</h3>
              <p className="text-sm text-slate-500 dark:text-slate-400 mb-6 text-center">{confirmConfig.message}</p>
              <div className="flex space-x-3">
                <button 
                  onClick={() => setConfirmConfig(prev => ({ ...prev, isOpen: false }))} 
                  className="flex-1 py-3 rounded-xl font-bold text-slate-600 dark:text-slate-400 hover:bg-slate-100 dark:hover:bg-slate-800 transition-colors"
                >
                  Cancel
                </button>
                <button 
                  onClick={confirmConfig.onConfirm} 
                  className="flex-1 py-3 rounded-xl font-bold bg-rose-600 text-white hover:bg-rose-700 transition-colors shadow-lg shadow-rose-600/20"
                >
                  Delete
                </button>
              </div>
            </div>
          </div>
        </div>
      )}
    </Layout>
  );
};

interface AddTransactionFormProps {
  onClose: () => void;
  onSave: (t: Transaction) => Promise<void>;
  onDelete?: (id: string) => void;
  cashBalance: number;
  holdings: Holding[];
  prices: Record<string, number>;
  transactions: Transaction[];
  initialData: Transaction | null;
}

const AddTransactionForm: React.FC<AddTransactionFormProps> = ({ onClose, onSave, onDelete, cashBalance, holdings, prices, transactions, initialData }) => {
  const [type, setType] = useState<TransactionType>(TransactionType.BUY);
  const [date, setDate] = useState(new Date().toISOString().split('T')[0]);
  const [symbol, setSymbol] = useState('');

  // Advanced Input State
  const [shares, setShares] = useState('');
  const [price, setPrice] = useState(''); // Price per share
  const [totalAmount, setTotalAmount] = useState(''); // Total transaction value

  const [fee, setFee] = useState('');
  const [assetClass, setAssetClass] = useState<AssetClass>(AssetClass.STOCK);
  const [exchangeRate, setExchangeRate] = useState(''); 
  const [notes, setNotes] = useState('');
  const [error, setError] = useState<string | null>(null);
  const [isSaving, setIsSaving] = useState(false);

  // Auto-Calc Lock (prevent circular updates)
  const [activeInput, setActiveInput] = useState<'shares' | 'price' | 'total' | null>(null);

  // Helper to block negative inputs
  const blockInvalidChar = (e: React.KeyboardEvent<HTMLInputElement>) => {
    if (['-', '+', 'e', 'E'].includes(e.key)) {
      e.preventDefault();
    }
  };

  useEffect(() => {
    if (initialData) {
      setType(initialData.type);
      setDate(initialData.date);
      setSymbol(initialData.symbol || '');
      setShares(initialData.shares?.toString() || '');
      setPrice(initialData.price?.toString() || '');
      setFee(initialData.fee?.toString() || '');
      setAssetClass(initialData.assetClass || AssetClass.STOCK);
      setExchangeRate(initialData.exchangeRate?.toString() || '');
      setNotes(initialData.notes || '');

      // Init Total Amount
      if (initialData.shares && initialData.price && (initialData.type === TransactionType.BUY || initialData.type === TransactionType.SELL)) {
         setTotalAmount((initialData.shares * initialData.price).toFixed(2));
      } else if (initialData.price) {
         setTotalAmount(initialData.price.toString());
      }
    }
  }, [initialData]);

  // --- SMART AUTO-FILL ---
  // When symbol changes, try to fetch last price and asset class
  useEffect(() => {
    if (!initialData && symbol && !price && !activeInput) {
       const upperSymbol = symbol.toUpperCase();

       // 1. Try to find in current holdings first (most accurate for asset class)
       const holding = holdings.find(h => h.symbol === upperSymbol);
       if (holding) {
          setAssetClass(holding.assetClass);
          if (holding.currentPrice > 0) {
             setPrice(holding.currentPrice.toString());
          }
       } else {
          // 2. Try to find in known prices history
          const knownPrice = prices[upperSymbol];
          if (knownPrice) {
             setPrice(knownPrice.toString());
          }
       }
    }
  }, [symbol, initialData, holdings, prices, activeInput, price]);


  // --- AUTO CALCULATION LOGIC ---
  useEffect(() => {
    const s = parseFloat(shares) || 0;
    const p = parseFloat(price) || 0;
    const t = parseFloat(totalAmount) || 0;

    // 1. If User edits Shares or Price -> Update Total
    if (activeInput === 'shares' || activeInput === 'price') {
       if (s > 0 && p > 0) {
         setTotalAmount((s * p).toFixed(2));
       } else if (s === 0 || p === 0) {
          // Don't clear total immediately if one is missing, acts weird
       }
    }

    // 2. If User edits Total -> Update Shares (if Price exists)
    if (activeInput === 'total') {
       if (t > 0 && p > 0) {
          setShares((t / p).toFixed(4)); // 4 decimals for shares
       }
    }
  }, [shares, price, totalAmount, activeInput]);


  const needsSymbol = [TransactionType.BUY, TransactionType.SELL, TransactionType.DIVIDEND, TransactionType.SPLIT].includes(type);
  const needsShares = [TransactionType.BUY, TransactionType.SELL, TransactionType.SPLIT].includes(type);
  const needsPrice = type !== TransactionType.SPLIT;
  const isFunding = type === TransactionType.DEPOSIT || type === TransactionType.WITHDRAW;

  // Validation Vars
  const numShares = parseFloat(shares) || 0;
  const numPrice = parseFloat(price) || 0;
  const numFee = parseFloat(fee) || 0;

  // Derived Total (re-calculate for validation integrity)
  const calcTotal = (type === TransactionType.SPLIT) ? 0 : (needsShares ? numShares * numPrice : numPrice);

  let netAmount = 0;
  if (type === TransactionType.BUY) netAmount = -(calcTotal + numFee);
  else if (type === TransactionType.SELL) netAmount = (calcTotal - numFee);
  else if (type === TransactionType.DIVIDEND) netAmount = calcTotal;
  else if (type === TransactionType.DEPOSIT) netAmount = calcTotal;
  else if (type === TransactionType.WITHDRAW) netAmount = -calcTotal;

  // --- VALIDATION EFFECTS ---
  useEffect(() => {
    setError(null);
    if (needsShares && numShares < 0) { setError("Shares cannot be negative."); return; }
    if (needsPrice && numPrice < 0) { setError("Price cannot be negative."); return; }
    if (numFee < 0) { setError("Fee cannot be negative."); return; }

    // Duplicate Check
    const isDuplicate = transactions.some(t => {
      if (initialData && t.id === initialData.id) return false;
      return (
        t.date === date && t.type === type && (t.symbol || '') === (symbol.toUpperCase() || '') &&
        (t.shares || 0) === numShares && (t.price || 0) === numPrice
      );
    });
    if (isDuplicate) { setError("Duplicate transaction detected."); return; }

    // Sell Validation
    if (type === TransactionType.SELL && symbol) {
      const holding = holdings.find(h => h.symbol === symbol.toUpperCase());
      let available = holding ? holding.shares : 0;
      if (initialData && initialData.type === TransactionType.SELL && initialData.symbol === symbol.toUpperCase()) {
         available += (initialData.shares || 0);
      }
      if (numShares > available + 0.00001) {
         setError(`Insufficient shares. Owned: ${formatNumber(available, 4)}`);
         return;
      }
    }

    // Cash Validation
    if (type === TransactionType.BUY || type === TransactionType.WITHDRAW) {
       let available = cashBalance;
       if (initialData) {
         // Logic to reverse old tx impact on cash (simplified)
         if (initialData.type === TransactionType.BUY) available += ((initialData.shares||0)*(initialData.price||0)) + (initialData.fee||0);
         else if (initialData.type === TransactionType.WITHDRAW) available += (initialData.price||0);
         else if (initialData.type === TransactionType.DEPOSIT) available -= (initialData.price||0);
         else if (initialData.type === TransactionType.SELL) available -= ((initialData.shares||0)*(initialData.price||0)) - (initialData.fee||0);
         else if (initialData.type === TransactionType.DIVIDEND) available -= (initialData.price||0);
       }
       if (Math.abs(netAmount) > available + 0.01) {
         setError(`Insufficient funds. Available: ${formatCurrency(available)}`);
         return;
       }
    }
  }, [type, calcTotal, cashBalance, numShares, numPrice, numFee, initialData, transactions, date, symbol, holdings, netAmount]);

  let projectedCash = cashBalance;
  if (initialData) {
     let oldImpact = 0;
     // Simplified reversal logic
     if (initialData.type === TransactionType.BUY) oldImpact = -(((initialData.shares||0)*(initialData.price||0)) + (initialData.fee||0));
     else if (initialData.type === TransactionType.SELL) oldImpact = ((initialData.shares||0)*(initialData.price||0)) - (initialData.fee||0);
     else if (initialData.type === TransactionType.DEPOSIT) oldImpact = (initialData.price||0);
     else if (initialData.type === TransactionType.WITHDRAW) oldImpact = -(initialData.price||0);
     else if (initialData.type === TransactionType.DIVIDEND) oldImpact = (initialData.price||0);
     projectedCash = (cashBalance - oldImpact) + netAmount;
  } else {
     projectedCash = cashBalance + netAmount;
  }

  const handleQuickAdd = (h: Holding) => {
    setSymbol(h.symbol);
    setAssetClass(h.assetClass);
    if(h.currentPrice) setPrice(h.currentPrice.toString());
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (error) return;
    // needsPrice is defined as type !== SPLIT. isFunding is included in that set.
    if (needsPrice && calcTotal === 0) {
      setError("Value must be > 0");
      return;
    }
    if (needsSymbol && !symbol) {
      setError("Symbol required");
      return;
    }

    setIsSaving(true);
    await onSave({
      id: initialData ? initialData.id : generateId(),
      date, type,
      symbol: (needsSymbol) ? symbol.toUpperCase() : undefined,
      shares: needsShares ? parseFloat(shares) : undefined,
      price: type === TransactionType.SPLIT ? 0 : parseFloat(price),
      fee: (fee && (type === TransactionType.BUY || type === TransactionType.SELL)) ? parseFloat(fee) : undefined,
      assetClass: (!needsSymbol) ? AssetClass.CASH : assetClass,
      exchangeRate: exchangeRate ? parseFloat(exchangeRate) : 1, 
      notes: notes ? notes : undefined
    });
    setIsSaving(false);
  };

  // Top Holdings for Quick Add
  const quickHoldings = useMemo(() => {
     return [...holdings].sort((a,b) => b.marketValue - a.marketValue).slice(0, 4);
  }, [holdings]);

  return (
    <>
      <div className="shrink-0 flex justify-between items-center p-4 border-b border-slate-100 dark:border-slate-800 bg-slate-50/50 dark:bg-slate-900/50">
        <div>
          <h3 className="text-lg font-display font-bold text-slate-900 dark:text-white">
            {initialData ? 'Edit Transaction' : 'New Transaction'}
          </h3>
          <p className="text-xs text-slate-500">{initialData ? 'Update details' : 'Record your investment activity'}</p>
        </div>
        <button onClick={onClose} className="p-2 rounded-full hover:bg-slate-200 dark:hover:bg-slate-800 text-slate-400 hover:text-slate-600 dark:hover:text-slate-200 transition-colors">
          <X size={20} />
        </button>
      </div>

      <form onSubmit={handleSubmit} className="flex-1 overflow-y-auto min-h-0 p-4 space-y-5 custom-scrollbar">

        {/* Type Selector */}
        <div>
           <div className="grid grid-cols-3 sm:grid-cols-6 gap-2">
              {[
                { id: TransactionType.BUY, icon: <TrendingUp size={14} />, label: 'Buy', color: 'blue' },
                { id: TransactionType.SELL, icon: <TrendingDown size={14} />, label: 'Sell', color: 'rose' },
                { id: TransactionType.DIVIDEND, icon: <DollarSign size={14} />, label: 'Div', color: 'emerald' },
                { id: TransactionType.SPLIT, icon: <GitFork size={14} />, label: 'Split', color: 'purple' },
                { id: TransactionType.DEPOSIT, icon: <Wallet size={14} />, label: 'In', color: 'indigo' },
                { id: TransactionType.WITHDRAW, icon: <Wallet size={14} />, label: 'Out', color: 'orange' },
              ].map((t) => (
                <button
                  key={t.id}
                  type="button"
                  onClick={() => setType(t.id)}
                  className={`flex flex-col items-center justify-center p-2 rounded-lg border transition-all duration-200 ${
                    type === t.id
                      ? `bg-${t.color}-50 border-${t.color}-500 text-${t.color}-700 dark:bg-${t.color}-900/30 dark:border-${t.color}-500 dark:text-${t.color}-300 ring-1 ring-${t.color}-500 shadow-sm`
                      : 'bg-white dark:bg-slate-800 border-slate-200 dark:border-slate-700 text-slate-500 hover:border-slate-300 dark:hover:border-slate-600'
                  }`}
                >
                  <div className="mb-0.5">{t.icon}</div>
                  <span className="text-[10px] font-bold">{t.label}</span>
                </button>
              ))}
           </div>
        </div>

        {/* Date */}
        <div>
           <div className="relative">
             <Calendar className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={16} />
             <input 
              type="date" 
              required
              value={date}
              onChange={(e) => setDate(e.target.value)}
              className="w-full pl-9 pr-3 py-2.5 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl text-slate-900 dark:text-white focus:ring-2 focus:ring-blue-500 outline-none transition-all font-medium text-sm"
            />
           </div>
        </div>

        {needsSymbol && (
          <div className="space-y-2">
            <div className="grid grid-cols-2 gap-3">
              <div className="col-span-1">
                 <label className="block text-[10px] font-bold text-slate-500 uppercase tracking-wider mb-1.5">Symbol</label>
                 <input 
                  type="text" 
                  required
                  placeholder="AAPL"
                  value={symbol}
                  onChange={(e) => setSymbol(e.target.value)}
                  className="w-full px-3 py-2.5 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl text-slate-900 dark:text-white focus:ring-2 focus:ring-blue-500 outline-none uppercase font-bold tracking-wide text-sm"
                />
              </div>
               <div className="col-span-1">
                <label className="block text-[10px] font-bold text-slate-500 uppercase tracking-wider mb-1.5">Class</label>
                <select 
                  value={assetClass} 
                  onChange={(e) => setAssetClass(e.target.value as AssetClass)}
                  className="w-full px-3 py-2.5 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl text-slate-900 dark:text-white focus:ring-2 focus:ring-blue-500 outline-none appearance-none text-sm"
                >
                  {Object.values(AssetClass).filter(a => a !== AssetClass.CASH).map(a => <option key={a} value={a}>{a}</option>)}
                </select>
              </div>
            </div>
            {/* Quick Add Chips */}
            {!initialData && quickHoldings.length > 0 && (
               <div className="flex items-center space-x-2 overflow-x-auto pb-1 no-scrollbar">
                  <Zap size={12} className="text-amber-500 shrink-0" />
                  {quickHoldings.map(h => (
                     <button
                       key={h.symbol}
                       type="button"
                       onClick={() => handleQuickAdd(h)}
                       className="px-2 py-1 bg-slate-100 dark:bg-slate-800 hover:bg-blue-50 dark:hover:bg-blue-900/30 text-xs font-medium text-slate-600 dark:text-slate-300 rounded-md transition-colors border border-transparent hover:border-blue-200 dark:hover:border-blue-800 whitespace-nowrap"
                     >
                       {h.symbol}
                     </button>
                  ))}
               </div>
            )}
          </div>
        )}

        <div className="grid grid-cols-2 gap-3">
           {needsShares && (
            <div className={type === TransactionType.SPLIT ? "col-span-2" : "col-span-1"}>
              <label className="block text-[10px] font-bold text-slate-500 uppercase tracking-wider mb-1.5">
                {type === TransactionType.SPLIT ? "Split Ratio (e.g. 2 for 2:1)" : "Shares"}
              </label>
              <input 
                type="number" 
                step="any"
                min="0"
                required
                onKeyDown={blockInvalidChar}
                placeholder={type === TransactionType.SPLIT ? "2" : "0.00"}
                value={shares}
                onFocus={() => setActiveInput('shares')}
                onChange={(e) => setShares(e.target.value)}
                className="w-full px-3 py-2.5 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl text-slate-900 dark:text-white focus:ring-2 focus:ring-blue-500 outline-none font-mono text-sm"
              />
            </div>
           )}
           {needsPrice && (
             <div className={!needsShares ? "col-span-2" : ""}>
               <label className="block text-[10px] font-bold text-slate-500 uppercase tracking-wider mb-1.5">
                 {needsShares ? "Price / Share" : "Amount ($)"}
               </label>
                <div className="relative">
                  <input 
                    type="number" 
                    step="any"
                    min="0"
                    required
                    onKeyDown={blockInvalidChar}
                    placeholder="0.00"
                    value={price}
                    onFocus={() => setActiveInput('price')}
                    onChange={(e) => setPrice(e.target.value)}
                    className="w-full px-3 py-2.5 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl text-slate-900 dark:text-white focus:ring-2 focus:ring-blue-500 outline-none font-mono text-sm"
                  />
                </div>
             </div>
           )}
        </div>

        {/* Total Amount Calculator Field */}
        {needsShares && needsPrice && (
           <div className="bg-blue-50/50 dark:bg-slate-800/50 p-3 rounded-xl border border-blue-100 dark:border-slate-700/50 flex items-center justify-between">
              <div className="flex items-center space-x-2 text-slate-500">
                 <Calculator size={14} />
                 <span className="text-xs font-bold uppercase">Total Amount</span>
              </div>
              <div className="flex items-center space-x-2 w-1/2">
                 <span className="text-slate-400">$</span>
                 <input 
                   type="number"
                   step="any"
                   min="0"
                   onKeyDown={blockInvalidChar}
                   value={totalAmount}
                   onFocus={() => setActiveInput('total')}
                   onChange={(e) => setTotalAmount(e.target.value)}
                   placeholder="0.00"
                   className="w-full bg-transparent border-b border-slate-300 dark:border-slate-600 focus:border-blue-500 outline-none text-right font-mono font-bold text-slate-900 dark:text-white"
                 />
              </div>
           </div>
        )}

        {(type === TransactionType.BUY || type === TransactionType.SELL) && (
           <div>
              <label className="block text-[10px] font-bold text-slate-500 uppercase tracking-wider mb-1.5">
                Fee (Optional)
              </label>
              <input 
                type="number" 
                step="any"
                min="0"
                onKeyDown={blockInvalidChar}
                placeholder="0.00"
                value={fee}
                onChange={(e) => setFee(e.target.value)}
                className="w-full px-3 py-2.5 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl text-slate-900 dark:text-white focus:ring-2 focus:ring-blue-500 outline-none font-mono text-sm"
              />
           </div>
        )}

        {isFunding && (
           <div className="bg-blue-50 dark:bg-slate-800/50 p-3 rounded-xl border border-blue-100 dark:border-slate-700">
             <label className="block text-[10px] font-bold text-slate-500 uppercase tracking-wider mb-1.5">
               Exchange Rate (Optional)
             </label>
              <div className="flex items-center space-x-2">
                <input 
                  type="number" 
                  step="any"
                  min="0"
                  onKeyDown={blockInvalidChar}
                  placeholder="1.00"
                  value={exchangeRate}
                  onChange={(e) => setExchangeRate(e.target.value)}
                  className="flex-1 px-3 py-2 bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-600 rounded-lg text-slate-900 dark:text-white focus:ring-2 focus:ring-blue-500 outline-none font-mono text-right text-sm"
                />
                <span className="text-xs font-medium text-slate-500">Local / USD</span>
              </div>
           </div>
        )}

        <div>
           <label className="block text-[10px] font-bold text-slate-500 uppercase tracking-wider mb-1.5">Notes (Optional)</label>
           <textarea
             rows={2}
             placeholder="Add a memo..."
             value={notes}
             onChange={(e) => setNotes(e.target.value)}
             className="w-full px-3 py-2.5 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl text-slate-900 dark:text-white focus:ring-2 focus:ring-blue-500 outline-none resize-none font-medium text-sm"
           />
        </div>
      </form>

      <div className="shrink-0 bg-white dark:bg-slate-900 border-t border-slate-100 dark:border-slate-800 p-4 shadow-[0_-4px_6px_-1px_rgba(0,0,0,0.05)] z-10">
         <div className="flex flex-col space-y-3 mb-4">
               {/* Main Details */}
               <div className="flex justify-between items-center">
                   <div>
                      <p className="text-xs text-slate-500 dark:text-slate-400 font-medium uppercase tracking-wider mb-0.5">Net Amount</p>
                      <div className="flex items-baseline space-x-2">
                         <span className={`text-2xl font-bold font-display ${
                             netAmount > 0 ? 'text-emerald-600 dark:text-emerald-400' : 
                             netAmount < 0 ? 'text-slate-900 dark:text-white' : 'text-slate-500'
                         }`}>
                            {netAmount > 0 ? '+' : ''}{formatCurrency(netAmount)}
                         </span>
                      </div>
                   </div>
                   <div className="text-right">
                      <p className="text-xs text-slate-500 dark:text-slate-400 font-medium uppercase tracking-wider mb-0.5">Cash Balance</p>
                      <div className="flex items-center justify-end space-x-2 text-sm">
                         <span className="text-slate-400 line-through decoration-slate-300 dark:decoration-slate-600">{formatCurrency(cashBalance)}</span>
                         <ArrowRight size={14} className="text-slate-300" />
                         <span className={`font-bold ${projectedCash < 0 ? 'text-rose-500' : 'text-slate-700 dark:text-slate-300'}`}>
                            {formatCurrency(projectedCash)}
                         </span>
                      </div>
                   </div>
               </div>
         </div>

         {error && (
           <div className="bg-rose-50 dark:bg-rose-900/20 border border-rose-200 dark:border-rose-800 rounded-xl p-3 mb-4 flex items-start space-x-3 text-rose-600 dark:text-rose-400 animate-slide-up">
               <AlertCircle size={18} className="shrink-0 mt-0.5" />
               <div className="text-sm font-semibold">{error}</div>
           </div>
         )}

          <div className="flex gap-3">
            {initialData && onDelete && (
               <button
                 type="button"
                 onClick={() => onDelete(initialData.id)}
                 className="px-4 py-3 rounded-xl font-bold bg-rose-50 text-rose-500 hover:bg-rose-100 dark:bg-rose-900/20 dark:text-rose-400 transition-colors"
               >
                 <Trash2 size={20} />
               </button>
            )}

            <button 
              onClick={handleSubmit}
              disabled={!!error || isSaving}
              className={`flex-1 font-bold py-3 rounded-xl shadow-lg transition-all flex items-center justify-center space-x-2 text-base ${
                error || isSaving
                  ? 'bg-slate-300 dark:bg-slate-700 text-slate-500 cursor-not-allowed' 
                  : 'bg-slate-900 dark:bg-blue-600 hover:opacity-90 text-white shadow-slate-900/20 dark:shadow-blue-600/20 active:scale-95'
              }`}
            >
              {isSaving ? (
                <Spinner className="text-white" />
              ) : (
                <>
                  <Save size={18} />
                  <span>{initialData ? 'Update Transaction' : 'Save Transaction'}</span>
                </>
              )}
            </button>
          </div>
      </div>
    </>
  );
};

export default App;

import React, { useMemo, useState } from 'react';
import { Holding, Transaction, ChartDataPoint, AssetClass } from '../types';
import { formatCurrency, formatNumber } from '../utils';
import { 
  AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, 
  PieChart, Pie, Cell, Brush
} from 'recharts';
import { ArrowUpRight, ArrowDownRight, TrendingUp, Wallet, Target, Activity, ChevronLeft, PieChart as PieChartIcon, ZoomIn } from 'lucide-react';
import { DashboardSkeleton } from './LoadingSkeletons';

interface DashboardProps {
  holdings: Holding[];
  transactions: Transaction[];
  financialGoal: number;
  setFinancialGoal?: (val: number) => void; // Optional/Deprecated
  onOpenGoalModal: () => void;
  investedAmount: number;
  cashBalance: number;
  portfolioValue: number;
  chartData: ChartDataPoint[];
  isLoading?: boolean;
}

const COLORS = ['#3b82f6', '#10b981', '#f59e0b', '#ef4444', '#8b5cf6', '#ec4899', '#6366f1', '#14b8a6'];

const Dashboard: React.FC<DashboardProps> = ({ 
  holdings, transactions, financialGoal, onOpenGoalModal, investedAmount, portfolioValue, cashBalance, chartData, isLoading 
}) => {
  const [selectedCategory, setSelectedCategory] = useState<string | null>(null);

  const totalNetWorth = portfolioValue + cashBalance;
  const totalUnrealizedPL = holdings.reduce((sum, h) => sum + h.unrealizedPL, 0);
  const totalPLPercent = investedAmount > 0 ? (totalUnrealizedPL / investedAmount) * 100 : 0;

  // 1. Prepare Main Allocation Data (By Category)
  const categoryData = useMemo(() => {
    return holdings
      .filter(h => h.marketValue > 0)
      .map(h => ({ name: h.assetClass, value: h.marketValue }))
      .reduce((acc: any[], curr) => {
        const existing = acc.find(item => item.name === curr.name);
        if (existing) {
          existing.value += curr.value;
        } else {
          acc.push({ ...curr });
        }
        return acc;
      }, [])
      .sort((a, b) => b.value - a.value);
  }, [holdings]);

  // 2. Prepare Drill-down Data (Assets within selected Category)
  const assetData = useMemo(() => {
    if (!selectedCategory) return [];
    return holdings
      .filter(h => h.assetClass === selectedCategory && h.marketValue > 0)
      .map(h => ({ name: h.symbol, value: h.marketValue, fullName: h.name }))
      .sort((a, b) => b.value - a.value);
  }, [holdings, selectedCategory]);

  // Determine which data to show
  const activeChartData = selectedCategory ? assetData : categoryData;

  // Determine the denominator for percentage calculation
  // If viewing main: Denom is Portfolio Value.
  // If viewing category: Denom is Total Value of that Category.
  const activeTotalValue = selectedCategory 
    ? assetData.reduce((sum, item) => sum + item.value, 0)
    : portfolioValue;

  // --- CAGR / PERFORMANCE CALCULATION ---
  const performanceMetric = useMemo(() => {
    if (investedAmount <= 0 || transactions.length === 0) {
      return { label: 'Total Return', value: 0 };
    }

    // Find first transaction date
    let minDate = new Date().getTime();
    let hasTx = false;

    transactions.forEach(t => {
       const txDate = new Date(t.date).getTime();
       if (txDate < minDate) {
         minDate = txDate;
         hasTx = true;
       }
    });

    if (!hasTx) return { label: 'Total Return', value: 0 };

    const now = new Date().getTime();
    const daysElapsed = (now - minDate) / (1000 * 60 * 60 * 24);
    const years = daysElapsed / 365.25;

    // If invested less than 1 year, show Absolute Return instead of CAGR to avoid crazy annualized numbers
    if (years < 1) {
       const absReturn = ((totalNetWorth - investedAmount) / investedAmount) * 100;
       return { label: 'Total Return (Abs)', value: absReturn };
    } else {
       // CAGR Formula: (End Value / Start Value)^(1/n) - 1
       // We use InvestedAmount as the proxy for Start Value (Principal)
       if (totalNetWorth <= 0) return { label: 'Annual Growth (CAGR)', value: -100 };

       const cagr = (Math.pow(totalNetWorth / investedAmount, 1 / years) - 1) * 100;
       return { label: 'Annual Growth (CAGR)', value: cagr };
    }
  }, [transactions, investedAmount, totalNetWorth]);

  if (isLoading) {
    return <DashboardSkeleton />;
  }

  return (
    <div className="space-y-8 animate-fade-in">
      {/* Header */}
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
           <h2 className="text-3xl font-display font-bold text-slate-900 dark:text-white">Dashboard</h2>
           <p className="text-slate-500 dark:text-slate-400 mt-1">Overview of your financial performance</p>
        </div>
        <div className="flex items-center space-x-2 text-sm text-slate-500 dark:text-slate-400 bg-white dark:bg-slate-800 px-3 py-1.5 rounded-full shadow-sm border border-slate-200 dark:border-slate-700 animate-slide-in-right">
           <div className="w-2 h-2 rounded-full bg-emerald-500 animate-pulse"></div>
           <span>Live Market Data</span>
        </div>
      </div>

      {/* Overview Cards */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        {/* Net Worth Card - Primary */}
        <div className="glass-card relative overflow-hidden rounded-2xl p-6 group animate-slide-up" style={{ animationDelay: '0ms' }}>
          <div className="absolute top-0 right-0 p-4 opacity-10 group-hover:opacity-20 transition-opacity animate-float">
            <Wallet size={80} />
          </div>
          <div className="relative z-10">
            <p className="text-sm font-medium text-slate-500 dark:text-slate-400 mb-2">Net Worth</p>
            <h3 className="text-3xl font-display font-bold text-slate-900 dark:text-white tracking-tight">
              {formatCurrency(totalNetWorth)}
            </h3>
            <div className="mt-4 flex items-center text-xs font-medium text-slate-500 dark:text-slate-400">
              <span className="bg-slate-100 dark:bg-slate-800 px-2 py-1 rounded-md">Cash: {formatCurrency(cashBalance)}</span>
            </div>
          </div>
          <div className="absolute bottom-0 left-0 w-full h-1 bg-gradient-to-r from-blue-500 to-indigo-500"></div>
        </div>

        {/* P/L Card */}
        <div className="glass-card rounded-2xl p-6 animate-slide-up" style={{ animationDelay: '100ms' }}>
          <div className="flex justify-between items-start mb-2">
            <p className="text-sm font-medium text-slate-500 dark:text-slate-400">Unrealized P/L</p>
            <div className={`p-1.5 rounded-lg ${totalUnrealizedPL >= 0 ? 'bg-emerald-500/10 text-emerald-600 dark:text-emerald-400' : 'bg-rose-500/10 text-rose-600 dark:text-rose-400'}`}>
              {totalUnrealizedPL >= 0 ? <ArrowUpRight size={18} /> : <ArrowDownRight size={18} />}
            </div>
          </div>
          <h3 className={`text-3xl font-display font-bold tracking-tight ${totalUnrealizedPL >= 0 ? 'text-emerald-600 dark:text-emerald-400' : 'text-rose-600 dark:text-rose-400'}`}>
            {totalUnrealizedPL >= 0 ? '+' : ''}{formatCurrency(totalUnrealizedPL)}
          </h3>
          <p className={`mt-2 text-sm font-medium ${totalPLPercent >= 0 ? 'text-emerald-600 dark:text-emerald-400' : 'text-rose-600 dark:text-rose-400'}`}>
            {totalPLPercent >= 0 ? '▲' : '▼'} {Math.abs(totalPLPercent).toFixed(2)}% All Time
          </p>
        </div>

        {/* Goal Card */}
        <div className="glass-card rounded-2xl p-6 flex flex-col justify-between animate-slide-up" style={{ animationDelay: '200ms' }}>
           <div className="flex justify-between items-start">
            <div>
              <p className="text-sm font-medium text-slate-500 dark:text-slate-400">Goal Progress</p>
              <h3 className="text-2xl font-display font-bold text-slate-900 dark:text-white mt-1">
                {financialGoal > 0 ? ((totalNetWorth / financialGoal) * 100).toFixed(1) : 0}%
              </h3>
            </div>
            <button 
              onClick={onOpenGoalModal}
              className="text-slate-400 hover:text-blue-500 transition-colors p-1 hover:bg-slate-100 dark:hover:bg-slate-700 rounded-lg"
              title="Edit Goal"
            >
              <Target size={20} />
            </button>
          </div>
          <div className="mt-4">
            <div className="w-full bg-slate-100 dark:bg-slate-700 rounded-full h-2 overflow-hidden">
              <div 
                className="bg-gradient-to-r from-purple-500 to-pink-500 h-2 rounded-full transition-all duration-1000 ease-out animate-pulse-slow" 
                style={{ width: `${Math.min((totalNetWorth / financialGoal) * 100, 100)}%` }}
              ></div>
            </div>
            <p className="text-xs text-slate-400 mt-2 text-right">Target: {formatCurrency(financialGoal)}</p>
          </div>
        </div>

        {/* Dynamic Performance Card (CAGR or Abs Return) */}
        <div className="glass-card rounded-2xl p-6 relative overflow-hidden animate-slide-up" style={{ animationDelay: '300ms' }}>
          <div className="flex justify-between items-start">
             <div>
               <p className="text-sm font-medium text-slate-500 dark:text-slate-400">{performanceMetric.label}</p>
               <h3 className={`text-3xl font-display font-bold mt-2 ${performanceMetric.value >= 0 ? 'text-emerald-600 dark:text-emerald-400' : 'text-rose-600 dark:text-rose-400'}`}>
                 {performanceMetric.value > 0 ? '+' : ''}{formatNumber(performanceMetric.value, 2)}%
               </h3>
             </div>
             <Activity className={performanceMetric.value >= 0 ? "text-emerald-500" : "text-rose-500"} size={24} />
          </div>
          <div className="mt-4 text-xs text-slate-400">
             {performanceMetric.label === 'Annual Growth (CAGR)' ? 'Compound Annual Growth Rate' : 'Absolute Return on Investment'}
          </div>
          <div className="absolute -bottom-4 -right-4 opacity-5 animate-float" style={{ animationDelay: '1s' }}>
             <Activity size={100} />
          </div>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        {/* Wealth Growth Chart */}
        <div className="lg:col-span-2 glass-card p-6 rounded-2xl animate-zoom-in" style={{ animationDelay: '400ms' }}>
          <div className="flex items-center justify-between mb-6">
            <h3 className="text-lg font-bold font-display text-slate-900 dark:text-white">Wealth Growth</h3>
             <div className="flex items-center space-x-4 text-xs font-medium">
                <div className="flex items-center"><div className="w-2 h-2 rounded-full bg-blue-500 mr-2"></div> Market Value</div>
                <div className="flex items-center"><div className="w-2 h-2 rounded-full bg-slate-400 mr-2 opacity-50"></div> Net Invested</div>
                <div className="flex items-center text-slate-400"><ZoomIn size={12} className="mr-1" /> Zoom/Pan</div>
             </div>
          </div>

          <div className="h-[350px] w-full">
            {chartData.length > 0 ? (
              <ResponsiveContainer width="100%" height="100%">
              <AreaChart data={chartData} margin={{ top: 10, right: 10, left: 0, bottom: 0 }}>
                <defs>
                  <linearGradient id="colorValue" x1="0" y1="0" x2="0" y2="1">
                    <stop offset="5%" stopColor="#3b82f6" stopOpacity={0.3}/>
                    <stop offset="95%" stopColor="#3b82f6" stopOpacity={0}/>
                  </linearGradient>
                </defs>
                <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" opacity={0.2} vertical={false} />
                <XAxis 
                  dataKey="date" 
                  axisLine={false} 
                  tickLine={false} 
                  tick={{fill: '#94a3b8', fontSize: 11, fontWeight: 500}} 
                  dy={15} 
                  minTickGap={40} 
                />
                <YAxis 
                  axisLine={false} 
                  tickLine={false} 
                  tick={{fill: '#94a3b8', fontSize: 11, fontWeight: 500}} 
                  tickFormatter={(val) => val >= 1000 ? (val/1000).toFixed(0) + 'k' : val}
                />
                <Tooltip 
                  contentStyle={{ 
                    backgroundColor: 'rgba(15, 23, 42, 0.95)', 
                    backdropFilter: 'blur(8px)',
                    border: '1px solid rgba(255,255,255,0.1)', 
                    borderRadius: '12px', 
                    color: '#fff',
                    boxShadow: '0 10px 15px -3px rgba(0, 0, 0, 0.1)'
                  }}
                  itemStyle={{ color: '#fff', fontSize: '12px', paddingBottom: '2px' }}
                  labelStyle={{ color: '#94a3b8', fontSize: '11px', marginBottom: '8px', textTransform: 'uppercase', letterSpacing: '0.05em' }}
                  formatter={(value: number, name: string) => [
                    formatCurrency(value), 
                    name === 'value' ? 'Market Value' : 'Net Invested'
                  ]}
                />
                <Area 
                  type="monotone" 
                  dataKey="value" 
                  stroke="#3b82f6" 
                  strokeWidth={3} 
                  fillOpacity={1} 
                  fill="url(#colorValue)" 
                  activeDot={{ r: 6, strokeWidth: 0, fill: '#fff' }}
                  isAnimationActive={true}
                  animationDuration={1500}
                />
                <Area 
                  type="monotone" 
                  dataKey="invested" 
                  stroke="#94a3b8" 
                  strokeDasharray="5 5" 
                  strokeWidth={2} 
                  fill="transparent" 
                  isAnimationActive={true}
                  animationDuration={1500}
                />
                <Brush 
                  dataKey="date" 
                  height={30} 
                  stroke="#3b82f6" 
                  fill="transparent" 
                  tickFormatter={() => ''}
                  className="opacity-50"
                />
              </AreaChart>
            </ResponsiveContainer>
            ) : (
              <div className="flex h-full flex-col items-center justify-center text-slate-400 bg-slate-50/50 dark:bg-slate-800/50 rounded-xl border border-dashed border-slate-200 dark:border-slate-700">
                <Activity className="mb-2 opacity-50" size={32} />
                <p>No transaction data available yet.</p>
              </div>
            )}
          </div>
        </div>

        {/* Allocation */}
        <div className="glass-card p-6 rounded-2xl flex flex-col animate-zoom-in relative" style={{ animationDelay: '500ms' }}>
          {/* Allocation Header with Back Button */}
          <div className="flex items-center space-x-2 mb-2">
            {selectedCategory ? (
              <button 
                onClick={() => setSelectedCategory(null)}
                className="p-1 rounded-full hover:bg-slate-100 dark:hover:bg-slate-700 transition-colors text-slate-500 dark:text-slate-400"
              >
                <ChevronLeft size={20} />
              </button>
            ) : (
               <div className="w-7"></div> // Spacer to align text
            )}
            <div>
              <h3 className="text-lg font-bold font-display text-slate-900 dark:text-white leading-tight">
                {selectedCategory ? `${selectedCategory} Assets` : 'Asset Allocation'}
              </h3>
              <p className="text-xs text-slate-500">
                {selectedCategory ? `Breakdown of ${selectedCategory} holdings` : 'Click on a slice to see details'}
              </p>
            </div>
          </div>

          <div className="flex-1 flex flex-col justify-center">
            <div className="h-[220px] w-full relative">
              {activeChartData.length > 0 ? (
                 <ResponsiveContainer width="100%" height="100%">
                  <PieChart>
                    <Pie
                      data={activeChartData}
                      cx="50%"
                      cy="50%"
                      innerRadius={60}
                      outerRadius={80}
                      paddingAngle={selectedCategory ? 2 : 5}
                      dataKey="value"
                      cornerRadius={6}
                      isAnimationActive={true}
                      animationDuration={1000}
                      onClick={(data) => {
                         // Robustly check for name in data or payload
                         const clickedName = data.name || data.payload?.name;
                         // Only drill down if not already selected
                         if (!selectedCategory && clickedName) {
                             setSelectedCategory(clickedName);
                         }
                      }}
                      className={!selectedCategory ? 'cursor-pointer' : ''}
                    >
                      {activeChartData.map((entry, index) => (
                        <Cell 
                          key={`cell-${index}`} 
                          fill={COLORS[index % COLORS.length]} 
                          strokeWidth={0} 
                          className={!selectedCategory ? "hover:opacity-80 transition-opacity cursor-pointer" : ""}
                        />
                      ))}
                    </Pie>
                    <Tooltip 
                       contentStyle={{ 
                        backgroundColor: 'rgba(15, 23, 42, 0.9)', 
                        border: 'none', 
                        borderRadius: '8px', 
                        color: '#fff',
                        fontSize: '12px'
                      }}
                      formatter={(value: number) => formatCurrency(value)} 
                    />
                  </PieChart>
                </ResponsiveContainer>
              ) : (
                <div className="absolute inset-0 flex flex-col items-center justify-center text-slate-400 text-sm">
                   <PieChartIcon size={24} className="mb-2 opacity-50" />
                   <span>No assets found</span>
                </div>
              )}
              {/* Center Text */}
              {activeChartData.length > 0 && (
                 <div className="absolute inset-0 flex flex-col items-center justify-center pointer-events-none animate-fade-in">
                    <span className="text-xs text-slate-400 font-medium uppercase">Total</span>
                    <span className="text-lg font-bold text-slate-900 dark:text-white">{formatCurrency(activeTotalValue)}</span>
                 </div>
              )}
            </div>
          </div>

          <div className="mt-6 space-y-2 max-h-[160px] overflow-y-auto custom-scrollbar pr-1">
             {activeChartData.map((entry, idx) => {
               const percentage = activeTotalValue > 0 ? (entry.value / activeTotalValue) * 100 : 0;
               return (
               <button 
                 key={idx} 
                 onClick={() => !selectedCategory && setSelectedCategory(entry.name)}
                 className={`w-full flex justify-between items-center text-sm p-2 rounded-lg transition-colors group ${
                   !selectedCategory ? 'hover:bg-slate-50 dark:hover:bg-slate-800/50 cursor-pointer' : 'cursor-default'
                 }`}
               >
                 <div className="flex items-center overflow-hidden">
                   <div className="w-3 h-3 rounded-full mr-3 shrink-0" style={{ backgroundColor: COLORS[idx % COLORS.length] }}></div>
                   <div className="flex flex-col items-start overflow-hidden">
                      <span className="text-slate-700 dark:text-slate-200 font-medium truncate w-full text-left">{entry.name}</span>
                      {/* Show Full Name if in drill-down mode */}
                      {selectedCategory && (entry as any).fullName !== entry.name && (
                          <span className="text-[10px] text-slate-400 truncate w-full text-left">{(entry as any).fullName}</span>
                      )}
                   </div>
                 </div>
                 <div className="flex items-center space-x-3 shrink-0">
                    <span className="text-slate-900 dark:text-white font-bold">
                      {percentage.toFixed(1)}%
                    </span>
                    <span className="text-slate-400 text-xs w-16 text-right tabular-nums">{formatCurrency(entry.value).split('.')[0]}</span>
                 </div>
               </button>
             )})}
          </div>
        </div>
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState, useMemo } from 'react';
import { Transaction, TransactionType, ChartDataPoint } from '../types';
import { getYearlyDividends, getMonthlyDividends, calculateFundingStats, calculateMonthlyActivity, formatCurrency, formatNumber } from '../utils';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, LineChart, Line, AreaChart, Area } from 'recharts';
import { DollarSign, TrendingUp, TrendingDown, Calendar, ArrowUpRight, ArrowDownRight, RefreshCcw, Clock, ArrowRight, Minus, ChevronDown, ChevronUp, Wallet, GitFork, ChevronRight } from 'lucide-react';
import { ReportsSkeleton } from './LoadingSkeletons';

interface ReportsProps {
  transactions: Transaction[];
  currentPortfolioValue: number;
  chartData: ChartDataPoint[];
  isLoading?: boolean;
}

const Reports: React.FC<ReportsProps> = ({ transactions, currentPortfolioValue, chartData, isLoading }) => {
  const [activeTab, setActiveTab] = useState<'growth' | 'dividends' | 'funding' | 'monthly'>('monthly');

  if (isLoading) {
    return <ReportsSkeleton />;
  }

  return (
    <div className="space-y-6 animate-fade-in">
      {/* Tab Navigation */}
      <div className="flex space-x-1 bg-white dark:bg-slate-800 p-1 rounded-xl w-fit shadow-sm border border-gray-100 dark:border-slate-700 overflow-x-auto">
        {['monthly', 'dividends', 'funding', 'growth'].map((tab) => (
          <button
            key={tab}
            onClick={() => setActiveTab(tab as any)}
            className={`px-4 py-2 rounded-lg text-sm font-medium transition-all whitespace-nowrap ${
              activeTab === tab
                ? 'bg-blue-50 text-blue-600 dark:bg-slate-700 dark:text-blue-400 shadow-sm'
                : 'text-gray-500 hover:text-gray-900 dark:text-gray-400 dark:hover:text-gray-200'
            }`}
          >
            {tab.charAt(0).toUpperCase() + tab.slice(1)}
          </button>
        ))}
      </div>

      {activeTab === 'dividends' && <DividendsView transactions={transactions} />}
      {activeTab === 'funding' && <FundingView transactions={transactions} currentPortfolioValue={currentPortfolioValue} />}
      {activeTab === 'growth' && <GrowthView transactions={transactions} currentPortfolioValue={currentPortfolioValue} chartData={chartData} />}
      {activeTab === 'monthly' && <MonthlyActivityView transactions={transactions} />}
    </div>
  );
};

// --- SUB-VIEWS ---

const MonthlyActivityView: React.FC<{ transactions: Transaction[] }> = ({ transactions }) => {
  const [range, setRange] = useState<number>(6); // Default 6 months
  const [expandedMonth, setExpandedMonth] = useState<string | null>(null);

  const monthlyData = useMemo(() => calculateMonthlyActivity(transactions), [transactions]);
  const displayData = range === 999 ? monthlyData : monthlyData.slice(0, range);

  // Current Month vs Previous Month (Always based on most recent data regardless of filter)
  const current = monthlyData[0] || { buyVolume: 0, dividendIncome: 0, yearMonth: 'N/A' };
  const previous = monthlyData[1] || { buyVolume: 0, dividendIncome: 0 };

  const buyDiff = current.buyVolume - previous.buyVolume;
  const buyDiffPercent = previous.buyVolume > 0 ? (buyDiff / previous.buyVolume) * 100 : 0;

  const divDiff = current.dividendIncome - previous.dividendIncome;
  const divDiffPercent = previous.dividendIncome > 0 ? (divDiff / previous.dividendIncome) * 100 : 0;

  const toggleMonth = (ym: string) => {
    if (expandedMonth === ym) setExpandedMonth(null);
    else setExpandedMonth(ym);
  };

  const renderTransactionDetails = (yearMonth: string) => {
    const monthTxs = transactions.filter(t => t.date.startsWith(yearMonth))
                                 .sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());

    if (monthTxs.length === 0) return <div className="p-4 text-center text-sm text-slate-400 italic">No transactions found for this period.</div>;

    return (
      <div className="bg-slate-50/80 dark:bg-slate-900/40 p-3 -mx-6 mt-4 border-t border-b border-slate-100 dark:border-slate-700 shadow-inner">
         <h4 className="text-[10px] font-bold uppercase text-slate-400 mb-2 px-1 tracking-wider">Transaction Breakdown</h4>
         <div className="space-y-2">
            {monthTxs.map(tx => {
               const totalVal = (tx.type === TransactionType.BUY || tx.type === TransactionType.SELL) 
                                ? (tx.price || 0) * (tx.shares || 0) 
                                : (tx.price || 0);

               return (
                 <div key={tx.id} className="flex items-center justify-between p-2.5 bg-white dark:bg-slate-800 rounded-lg border border-slate-200 dark:border-slate-700 shadow-sm">
                    <div className="flex items-center gap-3">
                       <div className={`w-8 h-8 rounded-lg flex items-center justify-center shrink-0 ${
                          tx.type === TransactionType.BUY ? 'bg-blue-100 text-blue-600 dark:bg-blue-900/30 dark:text-blue-400' :
                          tx.type === TransactionType.SELL ? 'bg-rose-100 text-rose-600 dark:bg-rose-900/30 dark:text-rose-400' :
                          tx.type === TransactionType.DIVIDEND ? 'bg-emerald-100 text-emerald-600 dark:bg-emerald-900/30 dark:text-emerald-400' :
                          tx.type === TransactionType.SPLIT ? 'bg-purple-100 text-purple-600 dark:bg-purple-900/30 dark:text-purple-400' :
                          'bg-slate-100 text-slate-600 dark:bg-slate-800 dark:text-slate-400'
                       }`}>
                          {tx.type === TransactionType.BUY ? <TrendingUp size={14} /> :
                           tx.type === TransactionType.SELL ? <TrendingDown size={14} /> :
                           tx.type === TransactionType.DIVIDEND ? <DollarSign size={14} /> :
                           tx.type === TransactionType.SPLIT ? <GitFork size={14} /> :
                           <Wallet size={14} />}
                       </div>
                       <div>
                          <div className="flex items-center gap-2">
                             <span className="font-bold text-sm text-slate-900 dark:text-white">{tx.symbol || (tx.type === 'DEPOSIT' || tx.type === 'WITHDRAW' ? 'Cash' : 'N/A')}</span>
                             <span className={`text-[10px] font-bold px-1.5 py-0.5 rounded ${
                                tx.type === TransactionType.BUY ? 'bg-blue-50 text-blue-600 dark:bg-blue-900/20' :
                                tx.type === TransactionType.SELL ? 'bg-rose-50 text-rose-600 dark:bg-rose-900/20' :
                                'bg-slate-100 text-slate-500 dark:bg-slate-800'
                             }`}>{tx.type}</span>
                          </div>
                          <div className="text-xs text-slate-400">{new Date(tx.date).toLocaleDateString()}</div>
                       </div>
                    </div>
                    <div className="text-right">
                       <div className="font-mono text-sm font-medium text-slate-900 dark:text-white">
                          {tx.type === TransactionType.SPLIT ? '-' : formatCurrency(totalVal)}
                       </div>
                       <div className="text-xs text-slate-400">
                          {tx.type === TransactionType.SPLIT ? `${tx.shares} : 1` : (tx.shares && tx.shares > 0 ? `${formatNumber(tx.shares)} shares` : '')}
                       </div>
                    </div>
                 </div>
               );
            })}
         </div>
      </div>
    );
  };

  return (
    <div className="space-y-6 animate-in fade-in slide-in-from-bottom-4 duration-300">
      {/* Controls */}
      <div className="flex justify-end">
         <div className="flex items-center space-x-1 bg-white dark:bg-slate-800 p-1 rounded-xl border border-slate-200 dark:border-slate-700 shadow-sm">
             {[
               { label: '1M', val: 1 },
               { label: '3M', val: 3 },
               { label: '6M', val: 6 },
               { label: '1Y', val: 12 },
               { label: 'All', val: 999 }
             ].map((opt) => (
               <button
                 key={opt.label}
                 onClick={() => setRange(opt.val)}
                 className={`px-3 py-1.5 text-xs rounded-lg transition-all font-medium ${
                   range === opt.val 
                   ? 'bg-slate-900 text-white dark:bg-white dark:text-slate-900 shadow-md' 
                   : 'text-slate-500 hover:bg-slate-100 dark:hover:bg-slate-700 hover:text-slate-900 dark:hover:text-white'
                 }`}
               >
                 {opt.label}
               </button>
             ))}
         </div>
      </div>

      {/* Comparison Cards */}
      <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          {/* Investment Volume Comparison */}
          <div className="bg-white dark:bg-slate-800 p-6 rounded-2xl shadow-sm border border-slate-200 dark:border-slate-700">
              <div className="flex justify-between items-start mb-4">
                 <div>
                    <p className="text-sm text-slate-500 dark:text-slate-400 font-medium">Invested This Month</p>
                    <h3 className="text-2xl font-bold text-slate-900 dark:text-white mt-1">
                      {formatCurrency(current.buyVolume)}
                    </h3>
                 </div>
                 <div className="p-2 bg-blue-50 dark:bg-blue-900/20 rounded-lg">
                    <TrendingUp size={20} className="text-blue-600 dark:text-blue-400" />
                 </div>
              </div>

              <div className="flex items-center text-sm">
                 <span className={`flex items-center font-bold mr-2 ${buyDiff >= 0 ? 'text-emerald-500' : 'text-slate-500'}`}>
                    {buyDiff > 0 ? <ArrowUpRight size={16} className="mr-1"/> : buyDiff < 0 ? <ArrowDownRight size={16} className="mr-1"/> : <Minus size={16} className="mr-1"/>}
                    {Math.abs(buyDiffPercent).toFixed(1)}%
                 </span>
                 <span className="text-slate-400">vs Previous Month ({formatCurrency(previous.buyVolume)})</span>
              </div>
          </div>

           {/* Income Comparison */}
           <div className="bg-white dark:bg-slate-800 p-6 rounded-2xl shadow-sm border border-slate-200 dark:border-slate-700">
              <div className="flex justify-between items-start mb-4">
                 <div>
                    <p className="text-sm text-slate-500 dark:text-slate-400 font-medium">Income This Month</p>
                    <h3 className="text-2xl font-bold text-slate-900 dark:text-white mt-1">
                      {formatCurrency(current.dividendIncome)}
                    </h3>
                 </div>
                 <div className="p-2 bg-emerald-50 dark:bg-emerald-900/20 rounded-lg">
                    <DollarSign size={20} className="text-emerald-600 dark:text-emerald-400" />
                 </div>
              </div>

              <div className="flex items-center text-sm">
                 <span className={`flex items-center font-bold mr-2 ${divDiff >= 0 ? 'text-emerald-500' : 'text-rose-500'}`}>
                    {divDiff > 0 ? <ArrowUpRight size={16} className="mr-1"/> : divDiff < 0 ? <ArrowDownRight size={16} className="mr-1"/> : <Minus size={16} className="mr-1"/>}
                    {Math.abs(divDiffPercent).toFixed(1)}%
                 </span>
                 <span className="text-slate-400">vs Previous Month ({formatCurrency(previous.dividendIncome)})</span>
              </div>
          </div>
      </div>

      {/* Detailed Table */}
      <div className="bg-white dark:bg-slate-800 rounded-2xl shadow-sm border border-slate-200 dark:border-slate-700 overflow-hidden">
        <div className="p-6 border-b border-slate-100 dark:border-slate-700">
          <h3 className="text-lg font-bold text-slate-900 dark:text-white">Monthly Breakdown</h3>
          <p className="text-xs text-slate-500 mt-1">Click on a row to see transaction details</p>
        </div>
        <div className="overflow-x-auto">
          <table className="w-full text-left text-sm">
            <thead className="bg-slate-50 dark:bg-slate-700/50 text-slate-500 dark:text-slate-400">
              <tr>
                <th className="px-6 py-4 font-medium w-10"></th>
                <th className="px-6 py-4 font-medium">Month</th>
                <th className="px-6 py-4 font-medium text-right text-blue-600 dark:text-blue-400">Invested (Buy)</th>
                <th className="px-6 py-4 font-medium text-right text-rose-600 dark:text-rose-400">Sold</th>
                <th className="px-6 py-4 font-medium text-right text-emerald-600 dark:text-emerald-400">Dividends</th>
                <th className="px-6 py-4 font-medium text-right">Net Flow</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100 dark:divide-slate-700">
              {displayData.map((data) => {
                 // Net Flow = Divs + Sold - Bought (Cashflow perspective)
                 const netFlow = data.dividendIncome + data.sellVolume - data.buyVolume;
                 const isExpanded = expandedMonth === data.yearMonth;

                 return (
                   <React.Fragment key={data.yearMonth}>
                    <tr 
                      className={`hover:bg-slate-50 dark:hover:bg-slate-700/50 cursor-pointer transition-colors ${isExpanded ? 'bg-slate-50 dark:bg-slate-700/30' : ''}`}
                      onClick={() => toggleMonth(data.yearMonth)}
                    >
                      <td className="px-6 py-4 text-slate-400">
                        {isExpanded ? <ChevronDown size={16} /> : <ChevronRight size={16} />}
                      </td>
                      <td className="px-6 py-4 font-bold text-slate-700 dark:text-slate-200">{data.yearMonth}</td>
                      <td className="px-6 py-4 text-right text-slate-700 dark:text-slate-300 font-mono">
                        {data.buyVolume > 0 ? formatCurrency(data.buyVolume) : '-'}
                      </td>
                      <td className="px-6 py-4 text-right text-slate-700 dark:text-slate-300 font-mono">
                        {data.sellVolume > 0 ? formatCurrency(data.sellVolume) : '-'}
                      </td>
                      <td className="px-6 py-4 text-right text-emerald-600 dark:text-emerald-400 font-bold font-mono">
                        {data.dividendIncome > 0 ? '+' + formatCurrency(data.dividendIncome) : '-'}
                      </td>
                      <td className="px-6 py-4 text-right font-medium font-mono">
                         <span className={netFlow > 0 ? 'text-emerald-500' : netFlow < 0 ? 'text-slate-500' : 'text-slate-300'}>
                           {netFlow > 0 ? '+' : ''}{formatCurrency(netFlow)}
                         </span>
                      </td>
                    </tr>
                    {isExpanded && (
                      <tr>
                        <td colSpan={6} className="p-0 border-b border-slate-100 dark:border-slate-700">
                           {renderTransactionDetails(data.yearMonth)}
                        </td>
                      </tr>
                    )}
                   </React.Fragment>
                 );
              })}
              {displayData.length === 0 && (
                <tr><td colSpan={6} className="px-6 py-8 text-center text-slate-400">No activity recorded for this period.</td></tr>
              )}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

const DividendsView: React.FC<{ transactions: Transaction[] }> = ({ transactions }) => {
  const yearlyData = useMemo(() => getYearlyDividends(transactions), [transactions]);
  const monthlyData = useMemo(() => getMonthlyDividends(transactions), [transactions]);

  const totalDividends = yearlyData.reduce((sum, d) => sum + d.value, 0);
  const avgMonthly = monthlyData.length > 0 ? totalDividends / monthlyData.length : 0; // Simple average

  // Last 12 Months
  const last12M = monthlyData.slice(-12).reduce((sum, d) => sum + d.value, 0);

  const recentDividends = [...transactions]
    .filter(t => t.type === TransactionType.DIVIDEND)
    .sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime())
    .slice(0, 10);

  return (
    <div className="space-y-6 animate-in fade-in slide-in-from-bottom-4 duration-300">
      {/* Stats Cards */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
        <div className="bg-white dark:bg-slate-800 p-6 rounded-2xl shadow-sm border border-gray-100 dark:border-slate-700">
          <p className="text-sm text-gray-500 dark:text-gray-400">Total Dividends</p>
          <h3 className="text-2xl font-bold text-gray-900 dark:text-white mt-1">{formatCurrency(totalDividends)}</h3>
        </div>
        <div className="bg-white dark:bg-slate-800 p-6 rounded-2xl shadow-sm border border-gray-100 dark:border-slate-700">
          <p className="text-sm text-gray-500 dark:text-gray-400">Last 12 Months</p>
          <h3 className="text-2xl font-bold text-success mt-1">+{formatCurrency(last12M)}</h3>
        </div>
        <div className="bg-white dark:bg-slate-800 p-6 rounded-2xl shadow-sm border border-gray-100 dark:border-slate-700">
          <p className="text-sm text-gray-500 dark:text-gray-400">Monthly Average</p>
          <h3 className="text-2xl font-bold text-blue-600 dark:text-blue-400 mt-1">{formatCurrency(avgMonthly)}</h3>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        {/* Yearly Chart */}
        <div className="bg-white dark:bg-slate-800 p-6 rounded-2xl shadow-sm border border-gray-100 dark:border-slate-700">
          <h3 className="text-lg font-bold text-gray-900 dark:text-white mb-6">Yearly History</h3>
          <div className="h-[300px] w-full">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={yearlyData}>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#e2e8f0" opacity={0.5} />
                <XAxis dataKey="year" axisLine={false} tickLine={false} tick={{fill: '#94a3b8', fontSize: 12}} dy={10} />
                <YAxis axisLine={false} tickLine={false} tick={{fill: '#94a3b8', fontSize: 12}} />
                <Tooltip 
                   cursor={{fill: 'transparent'}}
                   contentStyle={{ backgroundColor: '#1e293b', border: 'none', borderRadius: '8px', color: '#fff' }}
                   formatter={(value: number) => [formatCurrency(value), 'Dividends']}
                />
                <Bar dataKey="value" fill="#3b82f6" radius={[4, 4, 0, 0]} maxBarSize={60} />
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>

        {/* Monthly Chart */}
        <div className="bg-white dark:bg-slate-800 p-6 rounded-2xl shadow-sm border border-gray-100 dark:border-slate-700">
          <h3 className="text-lg font-bold text-gray-900 dark:text-white mb-6">Recent Monthly Breakdown</h3>
          <div className="h-[300px] w-full">
             <ResponsiveContainer width="100%" height="100%">
              <BarChart data={monthlyData.slice(-12)}>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#e2e8f0" opacity={0.5} />
                <XAxis dataKey="date" axisLine={false} tickLine={false} tick={{fill: '#94a3b8', fontSize: 12}} dy={10} tickFormatter={(val) => val.split('-')[1]} />
