                        tx.type === 'DIVIDEND' ? 'bg-emerald-50 text-emerald-700 border-emerald-200 dark:bg-emerald-900/20 dark:text-emerald-400 dark:border-emerald-800' :
                        tx.type === 'SPLIT' ? 'bg-purple-50 text-purple-700 border-purple-200 dark:bg-purple-900/20 dark:text-purple-400 dark:border-purple-800' :
                        'bg-slate-100 text-slate-700 border-slate-200 dark:bg-slate-800 dark:text-slate-300 dark:border-slate-700'
                      }`}>
                      {tx.type}
                    </span>
                  </td>
                  <td className="px-6 py-4">
                     <div className="font-bold text-slate-900 dark:text-white">{tx.symbol || '-'}</div>
                     {tx.assetClass && <div className="text-xs text-slate-400">{tx.assetClass}</div>}
                  </td>
                  <td className="px-6 py-4 text-right text-slate-600 dark:text-slate-300 font-mono">
                    {tx.type === TransactionType.SPLIT 
                      ? `${tx.shares} : 1` 
                      : (tx.shares ? formatNumber(tx.shares) : '-')}
                  </td>
                  <td className="px-6 py-4 text-right text-slate-600 dark:text-slate-300 font-mono">
                     {tx.type === TransactionType.SPLIT ? '-' : (tx.price ? formatCurrency(tx.price) : '-')}
                  </td>
                  <td className="px-6 py-4 text-right font-bold text-slate-900 dark:text-white font-mono">
                    {tx.type === TransactionType.SPLIT ? '-' : formatCurrency(
                      (tx.type === 'BUY' || tx.type === 'SELL') 
                        ? (tx.price! * tx.shares!) 
                        : tx.price!
                    )}
                  </td>
                  <td className="px-6 py-4 text-right">
                    <div className="flex items-center justify-end space-x-1">
                      <button 
                        onClick={(e) => {
                          e.stopPropagation();
                          onEdit(tx);
                        }}
                        className="text-slate-400 hover:text-blue-500 transition-colors p-2 hover:bg-blue-50 dark:hover:bg-blue-900/20 rounded-lg"
                        title="Edit"
                      >
                        <Edit2 size={16} />
                      </button>
                      <button 
                        onClick={(e) => handleDeleteClick(e, tx.id)}
                        className="text-slate-400 hover:text-rose-500 transition-colors p-2 hover:bg-rose-50 dark:hover:bg-rose-900/20 rounded-lg"
                        title="Delete"
                      >
                        <Trash2 size={16} />
                      </button>
                    </div>
                  </td>
                </tr>
              ))}
              {filteredTransactions.length === 0 && (
                <tr><td colSpan={7} className="px-6 py-12 text-center text-slate-400">
                  {transactions.length === 0 ? "No transactions recorded yet." : "No transactions match your filters."}
                </td></tr>
              )}
            </tbody>
          </table>
        </div>

        {/* Mobile Card View */}
        <div className="md:hidden">
           <div className="divide-y divide-slate-100 dark:divide-slate-800">
              {filteredTransactions.map(tx => (
                 <div key={tx.id} className="p-4 space-y-3 active:bg-slate-50 dark:active:bg-slate-800/50" onClick={() => onEdit(tx)}>
                    {/* Header: Date & Type */}
                    <div className="flex justify-between items-start">
                       <div>
                         <div className="font-bold text-slate-700 dark:text-slate-300 text-sm">{tx.date}</div>
                         <div className="font-bold text-lg text-slate-900 dark:text-white mt-0.5">{tx.symbol || (tx.type === 'DEPOSIT' || tx.type === 'WITHDRAW' ? 'Cash' : '-')}</div>
                       </div>
                       <span className={`px-2.5 py-1 rounded-lg text-xs font-bold border ${
                         tx.type === 'BUY' ? 'bg-blue-50 text-blue-700 border-blue-200 dark:bg-blue-900/20 dark:text-blue-400 dark:border-blue-800' : 
                         tx.type === 'SELL' ? 'bg-rose-50 text-rose-700 border-rose-200 dark:bg-rose-900/20 dark:text-rose-400 dark:border-rose-800' :
                         tx.type === 'DIVIDEND' ? 'bg-emerald-50 text-emerald-700 border-emerald-200 dark:bg-emerald-900/20 dark:text-emerald-400 dark:border-emerald-800' :
                         tx.type === 'SPLIT' ? 'bg-purple-50 text-purple-700 border-purple-200 dark:bg-purple-900/20 dark:text-purple-400 dark:border-purple-800' :
                         'bg-slate-100 text-slate-700 border-slate-200 dark:bg-slate-800 dark:text-slate-300 dark:border-slate-700'
                       }`}>
                         {tx.type}
                       </span>
                    </div>

                    {/* Details Grid */}
                    <div className="grid grid-cols-2 gap-2 text-sm">
                       <div className="bg-slate-50 dark:bg-slate-800/50 p-2 rounded-lg">
                          <div className="text-xs text-slate-400 mb-1">Quantity</div>
                          <div className="font-mono text-slate-700 dark:text-slate-300">
                             {tx.type === TransactionType.SPLIT ? `${tx.shares} : 1` : (tx.shares ? formatNumber(tx.shares) : '-')}
                          </div>
                       </div>
                       <div className="bg-slate-50 dark:bg-slate-800/50 p-2 rounded-lg text-right">
                          <div className="text-xs text-slate-400 mb-1">Total Value</div>
                          <div className="font-mono font-bold text-slate-900 dark:text-white">
                             {tx.type === TransactionType.SPLIT ? '-' : formatCurrency((tx.type === 'BUY' || tx.type === 'SELL') ? (tx.price! * tx.shares!) : tx.price!)}
                          </div>
                       </div>
                    </div>

                    {/* Footer */}
                    <div className="flex justify-between items-center pt-1">
                       <div className="text-xs text-slate-400">{tx.assetClass}</div>
                       <div className="flex items-center space-x-2">
                          <button 
                             onClick={(e) => {
                               e.stopPropagation();
                               onEdit(tx);
                             }}
                             className="text-blue-500 text-xs flex items-center bg-blue-50 dark:bg-blue-900/10 px-2 py-1.5 rounded-md active:scale-95 transition-transform"
                           >
                              <Edit2 size={12} className="mr-1" /> Edit
                           </button>
                           <button 
                             onClick={(e) => handleDeleteClick(e, tx.id)}
                             className="text-rose-500 text-xs flex items-center bg-rose-50 dark:bg-rose-900/10 px-2 py-1.5 rounded-md active:scale-95 transition-transform"
                           >
                              <Trash2 size={12} className="mr-1" /> Delete
                           </button>
                       </div>
                    </div>
                 </div>
              ))}
              {filteredTransactions.length === 0 && (
                 <div className="p-8 text-center text-slate-400 text-sm">
                   {transactions.length === 0 ? "No transactions recorded yet." : "No transactions match your filters."}
                 </div>
              )}
           </div>
        </div>

      </div>
    </div>
  );
};

export default History;

import React, { useState, useMemo } from 'react';
import { Holding, Transaction, AssetClass } from '../types';
import { formatCurrency, formatNumber } from '../utils';
import { RefreshCw, Briefcase, LayoutGrid, List, Layers, PieChart, ArrowUpRight, ArrowDownRight, MoreHorizontal, Filter, Wallet } from 'lucide-react';
import { LineChart, Line, ResponsiveContainer, YAxis } from 'recharts';
import { HoldingsSkeleton } from './LoadingSkeletons';

interface HoldingsProps {
  holdings: Holding[];
  transactions: Transaction[];
  onUpdatePrice: (symbol: string, newPrice: number) => void;
  isLoading?: boolean;
}

const Holdings: React.FC<HoldingsProps> = ({ holdings, transactions, onUpdatePrice, isLoading }) => {
  const [activeView, setActiveView] = useState<'holdings' | 'allocation'>('holdings');
  const [viewMode, setViewMode] = useState<'grid' | 'list'>('list');
  const [groupByCategory, setGroupByCategory] = useState(false);

  // Price Editing State
  const [editingPrice, setEditingPrice] = useState<string | null>(null);
  const [tempPrice, setTempPrice] = useState<string>('');

  const handleEditClick = (symbol: string, currentPrice: number) => {
    setEditingPrice(symbol);
    setTempPrice(currentPrice.toString());
  };

  const handleSavePrice = (symbol: string) => {
    const price = parseFloat(tempPrice);
    if (!isNaN(price) && price >= 0) {
      onUpdatePrice(symbol, price);
    }
    setEditingPrice(null);
  };

  // --- DATA PROCESSING ---

  // 1. Group Holdings by Asset Class
  const groupedHoldings = useMemo(() => {
    const groups: Partial<Record<AssetClass, Holding[]>> = {};
    holdings.forEach(h => {
      if (!groups[h.assetClass]) groups[h.assetClass] = [];
      groups[h.assetClass]?.push(h);
    });
    return groups;
  }, [holdings]);

  // 2. Allocation Stats
  const allocationStats = useMemo(() => {
    const totalPortfolioValue = holdings.reduce((sum, h) => sum + h.marketValue, 0);

    return Object.values(AssetClass).map(ac => {
      const classHoldings = holdings.filter(h => h.assetClass === ac);
      if (classHoldings.length === 0) return null;

      const marketValue = classHoldings.reduce((sum, h) => sum + h.marketValue, 0);
      const totalCost = classHoldings.reduce((sum, h) => sum + h.totalCost, 0);
      const unrealizedPL = marketValue - totalCost;
      const weight = totalPortfolioValue > 0 ? (marketValue / totalPortfolioValue) * 100 : 0;
      const count = classHoldings.length;

      return { assetClass: ac, marketValue, totalCost, unrealizedPL, weight, count };
    }).filter(Boolean) as { assetClass: AssetClass, marketValue: number, totalCost: number, unrealizedPL: number, weight: number, count: number }[];
  }, [holdings]);

  // 3. Global Stats for Summary Header
  const { totalMarketValue, totalCost, totalUnrealizedPL, totalReturnPercent } = useMemo(() => {
    const mv = holdings.reduce((sum, h) => sum + h.marketValue, 0);
    const cost = holdings.reduce((sum, h) => sum + h.totalCost, 0);
    const pl = mv - cost;
    const pct = cost > 0 ? (pl / cost) * 100 : 0;
    return { totalMarketValue: mv, totalCost: cost, totalUnrealizedPL: pl, totalReturnPercent: pct };
  }, [holdings]);


  if (isLoading) {
    return <HoldingsSkeleton />;
  }

  // --- RENDER HELPERS ---

  const renderSparkline = (h: Holding) => {
    const sparklineData = transactions
      .filter(t => t.symbol === h.symbol && (t.type === 'BUY' || t.type === 'SELL') && (t.price || 0) > 0)
      .sort((a, b) => new Date(a.date).getTime() - new Date(b.date).getTime())
      .map((t, i) => ({ i, price: t.price! }));

    if (h.currentPrice > 0 && (sparklineData.length === 0 || sparklineData[sparklineData.length-1].price !== h.currentPrice)) {
        sparklineData.push({ i: sparklineData.length, price: h.currentPrice });
    }

    const isUp = sparklineData.length > 1 ? sparklineData[sparklineData.length - 1].price >= sparklineData[0].price : true;
    const strokeColor = isUp ? '#10b981' : '#ef4444';

    if (sparklineData.length <= 1) return <div className="text-[10px] text-slate-300 italic">No Data</div>;

    return (
      <ResponsiveContainer width="100%" height="100%">
        <LineChart data={sparklineData}>
          <Line type="monotone" dataKey="price" stroke={strokeColor} strokeWidth={2} dot={false} isAnimationActive={false} />
          <YAxis domain={['dataMin', 'dataMax']} hide />
        </LineChart>
      </ResponsiveContainer>
    );
  };

  const renderCard = (h: Holding) => (
    <div key={h.symbol} className="glass-card rounded-2xl p-5 hover:border-blue-300 dark:hover:border-blue-700 transition-all duration-300 group relative">
       {/* Card Header */}
       <div className="flex justify-between items-start mb-2">
         <div className="flex items-start space-x-3">
            <div className="w-10 h-10 rounded-lg bg-slate-100 dark:bg-slate-800 flex items-center justify-center font-bold text-slate-700 dark:text-slate-300 text-sm border border-slate-200 dark:border-slate-700 shrink-0">
               {h.symbol.substring(0, 2)}
            </div>
            <div className="overflow-hidden">
               <h3 className="font-bold text-slate-900 dark:text-white leading-tight truncate">{h.symbol}</h3>
               <p className="text-xs text-slate-500 dark:text-slate-400 truncate max-w-[100px]">{h.name}</p>
            </div>
         </div>
         <span className="px-2.5 py-1 text-[10px] font-bold uppercase tracking-wide bg-slate-100 dark:bg-slate-800 text-slate-500 dark:text-slate-400 rounded-md border border-slate-200 dark:border-slate-700">
           {h.assetClass}
         </span>
       </div>

       {/* Sparkline */}
       <div className="h-10 w-full mb-3 -ml-1 opacity-80 group-hover:opacity-100 transition-opacity">
          {renderSparkline(h)}
       </div>

       {/* Stats */}
       <div className="space-y-3">
          <div className="flex justify-between items-end">
             <span className="text-xs text-slate-500">Market Value</span>
             <span className="text-lg font-display font-bold text-slate-900 dark:text-white">
