import React, { useState, useMemo } from 'react';
import { Transaction, TransactionType, ChartDataPoint } from '../types';
import { getYearlyDividends, getMonthlyDividends, calculateFundingStats, calculateMonthlyActivity, formatCurrency, formatNumber } from '../utils';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, LineChart, Line, AreaChart, Area } from 'recharts';
import { DollarSign, TrendingUp, TrendingDown, Calendar, ArrowUpRight, ArrowDownRight, RefreshCcw, Clock, ArrowRight, Minus, ChevronDown, ChevronUp, Wallet, GitFork, ChevronRight } from 'lucide-react';
import { ReportsSkeleton } from './LoadingSkeletons';

interface ReportsProps {
  transactions: Transaction[];
  currentPortfolioValue: number;
  chartData: ChartDataPoint[];
  isLoading?: boolean;
}

const Reports: React.FC<ReportsProps> = ({ transactions, currentPortfolioValue, chartData, isLoading }) => {
  const [activeTab, setActiveTab] = useState<'growth' | 'dividends' | 'funding' | 'monthly'>('monthly');

  if (isLoading) {
    return <ReportsSkeleton />;
  }

  return (
    <div className="space-y-6 animate-fade-in">
      {/* Tab Navigation */}
      <div className="flex space-x-1 bg-white dark:bg-slate-800 p-1 rounded-xl w-fit shadow-sm border border-gray-100 dark:border-slate-700 overflow-x-auto">
        {['monthly', 'dividends', 'funding', 'growth'].map((tab) => (
          <button
            key={tab}
            onClick={() => setActiveTab(tab as any)}
            className={`px-4 py-2 rounded-lg text-sm font-medium transition-all whitespace-nowrap ${
              activeTab === tab
                ? 'bg-blue-50 text-blue-600 dark:bg-slate-700 dark:text-blue-400 shadow-sm'
                : 'text-gray-500 hover:text-gray-900 dark:text-gray-400 dark:hover:text-gray-200'
            }`}
          >
            {tab.charAt(0).toUpperCase() + tab.slice(1)}
          </button>
        ))}
      </div>

      {activeTab === 'dividends' && <DividendsView transactions={transactions} />}
      {activeTab === 'funding' && <FundingView transactions={transactions} currentPortfolioValue={currentPortfolioValue} />}
      {activeTab === 'growth' && <GrowthView transactions={transactions} currentPortfolioValue={currentPortfolioValue} chartData={chartData} />}
      {activeTab === 'monthly' && <MonthlyActivityView transactions={transactions} />}
    </div>
  );
};

// --- SUB-VIEWS ---

const MonthlyActivityView: React.FC<{ transactions: Transaction[] }> = ({ transactions }) => {
  const [range, setRange] = useState<number>(6); // Default 6 months
  const [expandedMonth, setExpandedMonth] = useState<string | null>(null);

  const monthlyData = useMemo(() => calculateMonthlyActivity(transactions), [transactions]);
  const displayData = range === 999 ? monthlyData : monthlyData.slice(0, range);

  // Current Month vs Previous Month (Always based on most recent data regardless of filter)
  const current = monthlyData[0] || { buyVolume: 0, dividendIncome: 0, yearMonth: 'N/A' };
  const previous = monthlyData[1] || { buyVolume: 0, dividendIncome: 0 };

  const buyDiff = current.buyVolume - previous.buyVolume;
  const buyDiffPercent = previous.buyVolume > 0 ? (buyDiff / previous.buyVolume) * 100 : 0;

  const divDiff = current.dividendIncome - previous.dividendIncome;
  const divDiffPercent = previous.dividendIncome > 0 ? (divDiff / previous.dividendIncome) * 100 : 0;

  const toggleMonth = (ym: string) => {
    if (expandedMonth === ym) setExpandedMonth(null);
    else setExpandedMonth(ym);
  };

  const renderTransactionDetails = (yearMonth: string) => {
    const monthTxs = transactions.filter(t => t.date.startsWith(yearMonth))
                                 .sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());

    if (monthTxs.length === 0) return <div className="p-4 text-center text-sm text-slate-400 italic">No transactions found for this period.</div>;

    return (
      <div className="bg-slate-50/80 dark:bg-slate-900/40 p-3 -mx-6 mt-4 border-t border-b border-slate-100 dark:border-slate-700 shadow-inner">
         <h4 className="text-[10px] font-bold uppercase text-slate-400 mb-2 px-1 tracking-wider">Transaction Breakdown</h4>
         <div className="space-y-2">
            {monthTxs.map(tx => {
               const totalVal = (tx.type === TransactionType.BUY || tx.type === TransactionType.SELL) 
                                ? (tx.price || 0) * (tx.shares || 0) 
                                : (tx.price || 0);

               return (
                 <div key={tx.id} className="flex items-center justify-between p-2.5 bg-white dark:bg-slate-800 rounded-lg border border-slate-200 dark:border-slate-700 shadow-sm">
                    <div className="flex items-center gap-3">
                       <div className={`w-8 h-8 rounded-lg flex items-center justify-center shrink-0 ${
                          tx.type === TransactionType.BUY ? 'bg-blue-100 text-blue-600 dark:bg-blue-900/30 dark:text-blue-400' :
                          tx.type === TransactionType.SELL ? 'bg-rose-100 text-rose-600 dark:bg-rose-900/30 dark:text-rose-400' :
                          tx.type === TransactionType.DIVIDEND ? 'bg-emerald-100 text-emerald-600 dark:bg-emerald-900/30 dark:text-emerald-400' :
                          tx.type === TransactionType.SPLIT ? 'bg-purple-100 text-purple-600 dark:bg-purple-900/30 dark:text-purple-400' :
                          'bg-slate-100 text-slate-600 dark:bg-slate-800 dark:text-slate-400'
                       }`}>
                          {tx.type === TransactionType.BUY ? <TrendingUp size={14} /> :
                           tx.type === TransactionType.SELL ? <TrendingDown size={14} /> :
                           tx.type === TransactionType.DIVIDEND ? <DollarSign size={14} /> :
                           tx.type === TransactionType.SPLIT ? <GitFork size={14} /> :
                           <Wallet size={14} />}
                       </div>
                       <div>
                          <div className="flex items-center gap-2">
                             <span className="font-bold text-sm text-slate-900 dark:text-white">{tx.symbol || (tx.type === 'DEPOSIT' || tx.type === 'WITHDRAW' ? 'Cash' : 'N/A')}</span>
                             <span className={`text-[10px] font-bold px-1.5 py-0.5 rounded ${
