   );
};

export default Reports;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import Layout from './components/Layout';
import Dashboard from './components/Dashboard';
import Holdings from './components/Holdings';
import Reports from './components/Reports';
import History from './components/History';
import GoalModal from './components/GoalModal';
import { Transaction, TransactionType, AssetClass, Holding, Portfolio, FinancialGoal } from './types';
import { calculateHoldings, calculatePortfolioHistory, generateId, formatCurrency, formatNumber } from './utils';
import { X, Save, TrendingUp, TrendingDown, DollarSign, Wallet, Calendar, GitFork, AlertCircle, ArrowRight, Trash2, Zap, Calculator, Search } from 'lucide-react';
import { Spinner } from './components/LoadingSkeletons';

const POPULAR_SYMBOLS = [
  'AAPL', 'MSFT', 'GOOGL', 'AMZN', 'NVDA', 'TSLA', 'META', 'BRK.B', 'V', 'JNJ', 'WMT', 'JPM', // Tech/Blue Chip
  'VOO', 'VTI', 'QQQ', 'IVV', 'SCHD', 'JEPI', 'VUG', 'VTV', // ETFs
  'BTC', 'ETH', 'SOL', 'USDT', 'BNB', 'XRP', 'ADA' // Crypto
];

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState('dashboard');
  const [isAddModalOpen, setIsAddModalOpen] = useState(false);
  const [editingTransaction, setEditingTransaction] = useState<Transaction | null>(null);

  // Goal Modal State
  const [isGoalModalOpen, setIsGoalModalOpen] = useState(false);

  // --- CONFIRMATION MODAL STATE ---
  const [confirmConfig, setConfirmConfig] = useState<{
    isOpen: boolean;
    title: string;
    message: string;
    onConfirm: () => void;
  }>({
    isOpen: false,
    title: '',
    message: '',
    onConfirm: () => {},
  });

  // --- PORTFOLIO MANAGEMENT STATE ---
  const [portfolios, setPortfolios] = useState<Portfolio[]>(() => {
    const saved = localStorage.getItem('portfolios');
    if (saved) return JSON.parse(saved);

    // Migration: If no portfolios exist but we have legacy transactions, create a default one
    const legacyTx = localStorage.getItem('transactions');
    if (legacyTx) {
      return [{ id: 'default', name: 'Main Portfolio' }];
    }

    return [{ id: generateId(), name: 'My First Portfolio' }];
  });

  const [activePortfolioId, setActivePortfolioId] = useState<string>(() => {
    const saved = localStorage.getItem('activePortfolioId');
    const portfolios = JSON.parse(localStorage.getItem('portfolios') || '[]');
    if (saved && portfolios.some((p: Portfolio) => p.id === saved)) return saved;
    return portfolios.length > 0 ? portfolios[0].id : 'default';
  });

  // --- DATA STATE (Per Portfolio) - Synchronous Initialization ---

  const [transactions, setTransactions] = useState<Transaction[]>(() => {
    const key = `transactions_${activePortfolioId}`;
    const saved = localStorage.getItem(key);
    if (saved) return JSON.parse(saved);

    // Legacy fallback
    if (activePortfolioId === 'default') {
      const legacy = localStorage.getItem('transactions');
      if (legacy) return JSON.parse(legacy);
    }
    return [];
  });

  const [prices, setPrices] = useState<Record<string, number>>(() => {
    const key = `prices_${activePortfolioId}`;
    const saved = localStorage.getItem(key);
    if (saved) return JSON.parse(saved);

    // Legacy fallback
    if (activePortfolioId === 'default') {
      const legacy = localStorage.getItem('prices');
      if (legacy) return JSON.parse(legacy);
    }
    return {};
  });

  const [goals, setGoals] = useState<FinancialGoal[]>(() => {
    const key = `goals_${activePortfolioId}`;
    const saved = localStorage.getItem(key);
    if (saved) return JSON.parse(saved);

    // Legacy fallback logic
    let legacyGoal = 100000;
    const legacyKey = `financialGoal_${activePortfolioId}`;
    const savedLegacy = localStorage.getItem(legacyKey);

    if (savedLegacy) {
      legacyGoal = parseFloat(savedLegacy);
    } else if (activePortfolioId === 'default') {
      const oldGlobal = localStorage.getItem('financialGoal');
      if (oldGlobal) legacyGoal = parseFloat(oldGlobal);
    }

    return [{
      id: generateId(),
      targetAmount: legacyGoal,
      startDate: new Date().toISOString(),
      isAchieved: false,
      notes: 'Initial Goal'
    }];
  });

  const [isDataLoaded, setIsDataLoaded] = useState(true); // Started true because we loaded synchronously
  const [isLoading, setIsLoading] = useState(false); // Started false, ready to render
  const isFirstMount = useRef(true);

  // --- PERSISTENCE: Portfolios List ---
  useEffect(() => {
    localStorage.setItem('portfolios', JSON.stringify(portfolios));
  }, [portfolios]);

  useEffect(() => {
    localStorage.setItem('activePortfolioId', activePortfolioId);
  }, [activePortfolioId]);

  // --- PERSISTENCE: Load Data on Portfolio Switch ONLY ---
  useEffect(() => {
    // Skip the first run because we already initialized state synchronously
    if (isFirstMount.current) {
      isFirstMount.current = false;
      return;
    }

    setIsLoading(true);
    setIsDataLoaded(false);

    const loadData = () => {
        const txKey = `transactions_${activePortfolioId}`;
        const pricesKey = `prices_${activePortfolioId}`;
        const goalsKey = `goals_${activePortfolioId}`;
        const legacyGoalKey = `financialGoal_${activePortfolioId}`;

        // Load Transactions
        const savedTx = localStorage.getItem(txKey);
        if (savedTx) {
          setTransactions(JSON.parse(savedTx));
        } else if (activePortfolioId === 'default' && localStorage.getItem('transactions')) {
          setTransactions(JSON.parse(localStorage.getItem('transactions')!));
        } else {
          setTransactions([]);
        }

        // Load Prices
        const savedPrices = localStorage.getItem(pricesKey);
        if (savedPrices) {
          setPrices(JSON.parse(savedPrices));
        } else if (activePortfolioId === 'default' && localStorage.getItem('prices')) {
          setPrices(JSON.parse(localStorage.getItem('prices')!));
        } else {
          setPrices({});
        }

        // Load Goals
        const savedGoals = localStorage.getItem(goalsKey);
        if (savedGoals) {
           setGoals(JSON.parse(savedGoals));
        } else {
           let legacyGoal = 100000;
           const savedLegacy = localStorage.getItem(legacyGoalKey);
           if (savedLegacy) {
             legacyGoal = parseFloat(savedLegacy);
           } else if (activePortfolioId === 'default' && localStorage.getItem('financialGoal')) {
             legacyGoal = parseFloat(localStorage.getItem('financialGoal')!);
           }

           setGoals([{
             id: generateId(),
             targetAmount: legacyGoal,
             startDate: new Date().toISOString(),
             isAchieved: false,
             notes: 'Initial Goal'
           }]);
        }

        setIsDataLoaded(true);
        setTimeout(() => setIsLoading(false), 500); // Small delay for UX transition
    };

    // Use requestAnimationFrame to ensure we don't block main thread if data is huge
    requestAnimationFrame(loadData);

  }, [activePortfolioId]);

  // --- PERSISTENCE: Save Data on Change ---
  useEffect(() => {
    if (!isDataLoaded) return;
    localStorage.setItem(`transactions_${activePortfolioId}`, JSON.stringify(transactions));
  }, [transactions, activePortfolioId, isDataLoaded]);

  useEffect(() => {
    if (!isDataLoaded) return;
    localStorage.setItem(`prices_${activePortfolioId}`, JSON.stringify(prices));
  }, [prices, activePortfolioId, isDataLoaded]);

  useEffect(() => {
    if (!isDataLoaded) return;
    localStorage.setItem(`goals_${activePortfolioId}`, JSON.stringify(goals));
  }, [goals, activePortfolioId, isDataLoaded]);


  // --- CALCULATIONS ---
  const holdings = useMemo(() => calculateHoldings(transactions, prices), [transactions, prices]);
  const chartData = useMemo(() => calculatePortfolioHistory(transactions, prices), [transactions, prices]);

  const investedAmount = transactions.reduce((sum, t) => {
    if (t.type === TransactionType.DEPOSIT) return sum + (t.price || 0);
    if (t.type === TransactionType.WITHDRAW) return sum - (t.price || 0);
    return sum;
  }, 0);

  const cashBalance = useMemo(() => {
    let balance = 0;
    transactions.forEach(t => {
      if (t.type === TransactionType.DEPOSIT) balance += (t.price || 0);
      if (t.type === TransactionType.WITHDRAW) balance -= (t.price || 0);
      if (t.type === TransactionType.BUY) balance -= (t.price! * t.shares!) + (t.fee || 0);
      if (t.type === TransactionType.SELL) balance += (t.price! * t.shares!) - (t.fee || 0);
      if (t.type === TransactionType.DIVIDEND) balance += (t.price || 0);
    });
    return balance;
  }, [transactions]);

  const portfolioValue = holdings.reduce((sum, h) => sum + h.marketValue, 0);
  const totalNetWorth = portfolioValue + cashBalance;

  // Active Goal Logic
  const activeGoal = useMemo(() => {
    return goals.find(g => !g.endDate) || { targetAmount: 100000 } as FinancialGoal;
  }, [goals]);

  // --- HANDLERS ---
  const handleOpenAddModal = () => {
    setEditingTransaction(null);
    setIsAddModalOpen(true);
  };

  const handleOpenEditModal = (tx: Transaction) => {
    setEditingTransaction(tx);
    setIsAddModalOpen(true);
  };

  const handleSaveTransaction = (tx: Transaction) => {
    // Optimistic Update
    return new Promise<void>((resolve) => {
      if (editingTransaction) {
        setTransactions(prev => prev.map(t => t.id === tx.id ? tx : t));
      } else {
        setTransactions(prev => [...prev, tx]);
      }

      if ((tx.type === TransactionType.BUY || tx.type === TransactionType.SELL) && tx.symbol && tx.price) {
          setPrices(prev => ({...prev, [tx.symbol!]: tx.price!}));
      }

      setIsAddModalOpen(false);
      setEditingTransaction(null);
      resolve();
    });
  };

  const handleUpdatePrice = (symbol: string, newPrice: number) => {
    setPrices(prev => ({ ...prev, [symbol]: newPrice }));
  };

  const handleDeleteTransaction = (id: string) => {
    setTransactions(prev => prev.filter(t => t.id !== id));
    if (editingTransaction && editingTransaction.id === id) {
       setIsAddModalOpen(false);
       setEditingTransaction(null);
    }
  };

  const handleRequestDelete = (id: string) => {
      setConfirmConfig({
          isOpen: true,
          title: 'Delete Transaction',
          message: 'Are you sure you want to delete this transaction? This action cannot be undone.',
          onConfirm: () => {
              handleDeleteTransaction(id);
              setConfirmConfig(prev => ({ ...prev, isOpen: false }));
          }
      });
  };

  const handleImportTransactions = (importedTxs: Transaction[]) => {
      // Merge logic: Update if exists, Add if not
      setTransactions(prev => {
          const currentMap = new Map(prev.map(t => [t.id, t]));
          importedTxs.forEach(t => {
              currentMap.set(t.id, t);
          });
          return Array.from(currentMap.values());
      });
      alert(`Imported ${importedTxs.length} transactions successfully.`);
  };

  // Portfolio Management Handlers
  const handleCreatePortfolio = (name: string) => {
    const newId = generateId();
    const newPortfolio = { id: newId, name };
    setPortfolios([...portfolios, newPortfolio]);
    setActivePortfolioId(newId);
  };

  const handleRenamePortfolio = (id: string, newName: string) => {
    setPortfolios(prev => prev.map(p => p.id === id ? { ...p, name: newName } : p));
  };

  const handleDeletePortfolio = (id: string) => {
    if (portfolios.length <= 1) {
      alert("You must have at least one portfolio.");
      return;
    }
    setConfirmConfig({
        isOpen: true,
        title: 'Delete Portfolio',
        message: 'Are you sure you want to delete this entire portfolio? All transactions within it will be permanently lost.',
        onConfirm: () => {
             localStorage.removeItem(`transactions_${id}`);
             localStorage.removeItem(`prices_${id}`);
             localStorage.removeItem(`goals_${id}`);
             localStorage.removeItem(`financialGoal_${id}`);

             const newPortfolios = portfolios.filter(p => p.id !== id);
             setPortfolios(newPortfolios);

             if (activePortfolioId === id) {
               setActivePortfolioId(newPortfolios[0].id);
             }
             setConfirmConfig(prev => ({ ...prev, isOpen: false }));
        }
    });
  };

  // Goals Handler
  const handleSetNewGoal = (targetAmount: number, notes: string) => {
    const now = new Date().toISOString();

    setGoals(prev => {
      const updatedGoals = prev.map(g => {
        // If there's an active goal, end it.
        if (!g.endDate) {
           const achieved = totalNetWorth >= g.targetAmount;
           return { ...g, endDate: now, isAchieved: achieved };
        }
        return g;
      });

      const newGoal: FinancialGoal = {
        id: generateId(),
        targetAmount,
        startDate: now,
        isAchieved: false,
        notes
      };

      return [...updatedGoals, newGoal];
    });
  };

  const handleEditGoal = (updatedGoal: FinancialGoal) => {
      setGoals(prev => prev.map(g => g.id === updatedGoal.id ? updatedGoal : g));
  };

  const handleDeleteGoal = (id: string) => {
      setGoals(prev => prev.filter(g => g.id !== id));
  };

  return (
    <Layout 
      activeTab={activeTab} 
      setActiveTab={setActiveTab} 
      onOpenAddModal={handleOpenAddModal}
      portfolios={portfolios}
      activePortfolioId={activePortfolioId}
      onSwitchPortfolio={setActivePortfolioId}
      onCreatePortfolio={handleCreatePortfolio}
      onRenamePortfolio={handleRenamePortfolio}
      onDeletePortfolio={handleDeletePortfolio}
    >
      <div key={activePortfolioId} className="h-full">
        {activeTab === 'dashboard' && (
          <Dashboard 
            isLoading={isLoading}
            holdings={holdings} 
            transactions={transactions} 
            financialGoal={activeGoal.targetAmount}
            onOpenGoalModal={() => setIsGoalModalOpen(true)}
            investedAmount={investedAmount}
            cashBalance={cashBalance}
            portfolioValue={portfolioValue}
            chartData={chartData}
          />
        )}
        {activeTab === 'holdings' && (
          <Holdings 
            isLoading={isLoading}
            holdings={holdings} 
            transactions={transactions} 
            onUpdatePrice={handleUpdatePrice} 
          />
        )}
        {activeTab === 'history' && (
          <History 
            isLoading={isLoading}
            transactions={transactions} 
            onDelete={handleRequestDelete}
            onEdit={handleOpenEditModal}
            onAdd={handleOpenAddModal}
            onImport={handleImportTransactions}
          />
        )}
        {activeTab === 'reports' && (
           <Reports 
             isLoading={isLoading}
             transactions={transactions} 
             currentPortfolioValue={portfolioValue + cashBalance} 
             chartData={chartData} 
           />
        )}
      </div>

      {isAddModalOpen && (
        <div className="fixed inset-0 z-50 flex items-end sm:items-center justify-center sm:p-4">
          <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-sm animate-fade-in" onClick={() => setIsAddModalOpen(false)}></div>
          <div className="relative bg-white dark:bg-slate-900 w-full max-w-lg 
                          rounded-t-3xl sm:rounded-3xl border border-slate-200 dark:border-slate-800 
                          shadow-2xl overflow-hidden animate-slide-up flex flex-col
                          max-h-[90dvh] sm:max-h-[85vh]">
            <AddTransactionForm 
              onClose={() => setIsAddModalOpen(false)} 
              onSave={handleSaveTransaction} 
              onDelete={handleRequestDelete}
              cashBalance={cashBalance}
              holdings={holdings}
              prices={prices}
              transactions={transactions}
              initialData={editingTransaction}
            />
          </div>
        </div>
      )}

      <GoalModal 
        isOpen={isGoalModalOpen}
        onClose={() => setIsGoalModalOpen(false)}
        goals={goals}
        currentNetWorth={totalNetWorth}
        onSetGoal={handleSetNewGoal}
        onEditGoal={handleEditGoal}
        onDeleteGoal={handleDeleteGoal}
      />

      {confirmConfig.isOpen && (
        <div className="fixed inset-0 z-[70] flex items-center justify-center p-4 animate-fade-in">
          <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-sm" onClick={() => setConfirmConfig(prev => ({ ...prev, isOpen: false }))}></div>
          <div className="relative bg-white dark:bg-slate-900 rounded-2xl shadow-2xl w-full max-w-sm overflow-hidden animate-zoom-in border border-slate-200 dark:border-slate-700">
            <div className="p-6">
              <div className="w-12 h-12 rounded-full bg-rose-100 dark:bg-rose-900/30 flex items-center justify-center text-rose-600 dark:text-rose-400 mb-4 mx-auto">
                 <Trash2 size={24} />
              </div>
              <h3 className="text-lg font-bold font-display text-slate-900 dark:text-white mb-2 text-center">{confirmConfig.title}</h3>
              <p className="text-sm text-slate-500 dark:text-slate-400 mb-6 text-center">{confirmConfig.message}</p>
              <div className="flex space-x-3">
                <button 
                  onClick={() => setConfirmConfig(prev => ({ ...prev, isOpen: false }))} 
                  className="flex-1 py-3 rounded-xl font-bold text-slate-600 dark:text-slate-400 hover:bg-slate-100 dark:hover:bg-slate-800 transition-colors"
                >
                  Cancel
                </button>
                <button 
                  onClick={confirmConfig.onConfirm} 
                  className="flex-1 py-3 rounded-xl font-bold bg-rose-600 text-white hover:bg-rose-700 transition-colors shadow-lg shadow-rose-600/20"
                >
                  Delete
                </button>
              </div>
            </div>
          </div>
        </div>
      )}
    </Layout>
  );
};

interface AddTransactionFormProps {
  onClose: () => void;
  onSave: (t: Transaction) => Promise<void>;
  onDelete?: (id: string) => void;
  cashBalance: number;
  holdings: Holding[];
  prices: Record<string, number>;
  transactions: Transaction[];
  initialData: Transaction | null;
}

const AddTransactionForm: React.FC<AddTransactionFormProps> = ({ onClose, onSave, onDelete, cashBalance, holdings, prices, transactions, initialData }) => {
  const [type, setType] = useState<TransactionType>(TransactionType.BUY);
  const [date, setDate] = useState(new Date().toISOString().split('T')[0]);
  const [symbol, setSymbol] = useState('');

  // Advanced Input State
  const [shares, setShares] = useState('');
  const [price, setPrice] = useState(''); // Price per share
  const [totalAmount, setTotalAmount] = useState(''); // Total transaction value

  const [fee, setFee] = useState('');
  const [assetClass, setAssetClass] = useState<AssetClass>(AssetClass.STOCK);
  const [exchangeRate, setExchangeRate] = useState(''); 
  const [notes, setNotes] = useState('');
  const [error, setError] = useState<string | null>(null);
  const [isSaving, setIsSaving] = useState(false);

  // Auto-Calc Lock (prevent circular updates)
  const [activeInput, setActiveInput] = useState<'shares' | 'price' | 'total' | null>(null);

  // Autocomplete State
  const [showSuggestions, setShowSuggestions] = useState(false);
  const wrapperRef = useRef<HTMLDivElement>(null);

  // Close suggestions on outside click
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (wrapperRef.current && !wrapperRef.current.contains(event.target as Node)) {
        setShowSuggestions(false);
      }
    };
    document.addEventListener("mousedown", handleClickOutside);
    return () => document.removeEventListener("mousedown", handleClickOutside);
  }, []);

  // Helper to block negative inputs
  const blockInvalidChar = (e: React.KeyboardEvent<HTMLInputElement>) => {
    if (['-', '+', 'e', 'E'].includes(e.key)) {
      e.preventDefault();
    }
  };

  useEffect(() => {
    if (initialData) {
      setType(initialData.type);
      setDate(initialData.date);
      setSymbol(initialData.symbol || '');
      setShares(initialData.shares?.toString() || '');
      setPrice(initialData.price?.toString() || '');
      setFee(initialData.fee?.toString() || '');
      setAssetClass(initialData.assetClass || AssetClass.STOCK);
      setExchangeRate(initialData.exchangeRate?.toString() || '');
      setNotes(initialData.notes || '');

      // Init Total Amount
      if (initialData.shares && initialData.price && (initialData.type === TransactionType.BUY || initialData.type === TransactionType.SELL)) {
         setTotalAmount((initialData.shares * initialData.price).toFixed(2));
      } else if (initialData.price) {
         setTotalAmount(initialData.price.toString());
      }
    }
  }, [initialData]);

  // --- SMART AUTO-FILL ---
  // When symbol changes, try to fetch last price and asset class
  useEffect(() => {
    if (!initialData && symbol && !price && !activeInput) {
       const upperSymbol = symbol.toUpperCase();

       // 1. Try to find in current holdings first (most accurate for asset class)
       const holding = holdings.find(h => h.symbol === upperSymbol);
       if (holding) {
          setAssetClass(holding.assetClass);
          if (holding.currentPrice > 0) {
             setPrice(holding.currentPrice.toString());
          }
       } else {
          // 2. Try to find in known prices history
          const knownPrice = prices[upperSymbol];
          if (knownPrice) {
             setPrice(knownPrice.toString());
          }
       }
    }
  }, [symbol, initialData, holdings, prices, activeInput, price]);


  // --- AUTO CALCULATION LOGIC ---
  useEffect(() => {
    const s = parseFloat(shares) || 0;
    const p = parseFloat(price) || 0;
    const t = parseFloat(totalAmount) || 0;

    // 1. If User edits Shares or Price -> Update Total
    if (activeInput === 'shares' || activeInput === 'price') {
       if (s > 0 && p > 0) {
         setTotalAmount((s * p).toFixed(2));
       } else if (s === 0 || p === 0) {
          // Don't clear total immediately if one is missing, acts weird
       }
    }

    // 2. If User edits Total -> Update Shares (if Price exists)
    if (activeInput === 'total') {
       if (t > 0 && p > 0) {
          setShares((t / p).toFixed(4)); // 4 decimals for shares
       }
    }
  }, [shares, price, totalAmount, activeInput]);

  const needsSymbol = [TransactionType.BUY, TransactionType.SELL, TransactionType.DIVIDEND, TransactionType.SPLIT].includes(type);
  const needsShares = [TransactionType.BUY, TransactionType.SELL, TransactionType.SPLIT].includes(type);
  const needsPrice = type !== TransactionType.SPLIT;
  const isFunding = type === TransactionType.DEPOSIT || type === TransactionType.WITHDRAW;

  // Validation Vars
  const numShares = parseFloat(shares) || 0;
  const numPrice = parseFloat(price) || 0;
  const numFee = parseFloat(fee) || 0;

  // Derived Total (re-calculate for validation integrity)
  const calcTotal = (type === TransactionType.SPLIT) ? 0 : (needsShares ? numShares * numPrice : numPrice);

  let netAmount = 0;
  if (type === TransactionType.BUY) netAmount = -(calcTotal + numFee);
  else if (type === TransactionType.SELL) netAmount = (calcTotal - numFee);
  else if (type === TransactionType.DIVIDEND) netAmount = calcTotal;
  else if (type === TransactionType.DEPOSIT) netAmount = calcTotal;
  else if (type === TransactionType.WITHDRAW) netAmount = -calcTotal;

  // --- VALIDATION EFFECTS ---
  useEffect(() => {
    setError(null);
    if (needsShares && numShares < 0) { setError("Shares cannot be negative."); return; }
    if (needsPrice && numPrice < 0) { setError("Price cannot be negative."); return; }
    if (numFee < 0) { setError("Fee cannot be negative."); return; }

    // Duplicate Check
    const isDuplicate = transactions.some(t => {
      if (initialData && t.id === initialData.id) return false;
      return (
        t.date === date && t.type === type && (t.symbol || '') === (symbol.toUpperCase() || '') &&
        (t.shares || 0) === numShares && (t.price || 0) === numPrice
      );
    });
    if (isDuplicate) { setError("Duplicate transaction detected."); return; }

    // Sell Validation
    if (type === TransactionType.SELL && symbol) {
      const holding = holdings.find(h => h.symbol === symbol.toUpperCase());
      let available = holding ? holding.shares : 0;
      if (initialData && initialData.type === TransactionType.SELL && initialData.symbol === symbol.toUpperCase()) {
         available += (initialData.shares || 0);
      }
      if (numShares > available + 0.00001) {
         setError(`Insufficient shares. Owned: ${formatNumber(available, 4)}`);
         return;
      }
    }

    // Cash Validation
    if (type === TransactionType.BUY || type === TransactionType.WITHDRAW) {
       let available = cashBalance;
       if (initialData) {
         // Logic to reverse old tx impact on cash (simplified)
         if (initialData.type === TransactionType.BUY) available += ((initialData.shares||0)*(initialData.price||0)) + (initialData.fee||0);
         else if (initialData.type === TransactionType.WITHDRAW) available += (initialData.price||0);
         else if (initialData.type === TransactionType.DEPOSIT) available -= (initialData.price||0);
         else if (initialData.type === TransactionType.SELL) available -= ((initialData.shares||0)*(initialData.price||0)) - (initialData.fee||0);
         else if (initialData.type === TransactionType.DIVIDEND) available -= (initialData.price||0);
       }
       if (Math.abs(netAmount) > available + 0.01) {
         setError(`Insufficient funds. Available: ${formatCurrency(available)}`);
         return;
       }
    }
  }, [type, calcTotal, cashBalance, numShares, numPrice, numFee, initialData, transactions, date, symbol, holdings, netAmount]);

  let projectedCash = cashBalance;
  if (initialData) {
     let oldImpact = 0;
     // Simplified reversal logic
     if (initialData.type === TransactionType.BUY) oldImpact = -(((initialData.shares||0)*(initialData.price||0)) + (initialData.fee||0));
     else if (initialData.type === TransactionType.SELL) oldImpact = ((initialData.shares||0)*(initialData.price||0)) - (initialData.fee||0);
     else if (initialData.type === TransactionType.DEPOSIT) oldImpact = (initialData.price||0);
     else if (initialData.type === TransactionType.WITHDRAW) oldImpact = -(initialData.price||0);
     else if (initialData.type === TransactionType.DIVIDEND) oldImpact = (initialData.price||0);
     projectedCash = (cashBalance - oldImpact) + netAmount;
  } else {
     projectedCash = cashBalance + netAmount;
  }

  const handleQuickAdd = (h: Holding) => {
    setSymbol(h.symbol);
    setAssetClass(h.assetClass);
    if(h.currentPrice) setPrice(h.currentPrice.toString());
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (error) return;
    // needsPrice is defined as type !== SPLIT. isFunding is included in that set.
    if (needsPrice && calcTotal === 0) {
      setError("Value must be > 0");
      return;
    }
    if (needsSymbol && !symbol) {
      setError("Symbol required");
      return;
    }

    setIsSaving(true);
    await onSave({
      id: initialData ? initialData.id : generateId(),
      date, type,
      symbol: (needsSymbol) ? symbol.toUpperCase() : undefined,
      shares: needsShares ? parseFloat(shares) : undefined,
      price: type === TransactionType.SPLIT ? 0 : parseFloat(price),
      fee: (fee && (type === TransactionType.BUY || type === TransactionType.SELL)) ? parseFloat(fee) : undefined,
      assetClass: (!needsSymbol) ? AssetClass.CASH : assetClass,
      exchangeRate: exchangeRate ? parseFloat(exchangeRate) : 1, 
      notes: notes ? notes : undefined
    });
    setIsSaving(false);
  };

  // Top Holdings for Quick Add
  const quickHoldings = useMemo(() => {
     return [...holdings].sort((a,b) => b.marketValue - a.marketValue).slice(0, 4);
  }, [holdings]);

  // Autocomplete Suggestions
  const suggestions = useMemo(() => {
    if (!symbol || symbol.length < 1) return [];

    const inputUpper = symbol.toUpperCase();

    // Combine existing holdings symbols with popular list (Set for uniqueness)
    const holdingSymbols = holdings.map(h => h.symbol);
    const combined = Array.from(new Set([...holdingSymbols, ...POPULAR_SYMBOLS]));

    return combined
        .filter(s => s.includes(inputUpper))
        .sort((a, b) => {
           // Prioritize startsWith matches
           const aStarts = a.startsWith(inputUpper);
           const bStarts = b.startsWith(inputUpper);
           if (aStarts && !bStarts) return -1;
           if (!aStarts && bStarts) return 1;
           return a.localeCompare(b);
        })
        .slice(0, 6); // Limit to top 6
  }, [symbol, holdings]);

  const selectSuggestion = (s: string) => {
    setSymbol(s);
    setShowSuggestions(false);
  };

  return (
    <>
      <div className="shrink-0 flex justify-between items-center p-4 border-b border-slate-100 dark:border-slate-800 bg-slate-50/50 dark:bg-slate-900/50">
        <div>
          <h3 className="text-lg font-display font-bold text-slate-900 dark:text-white">
            {initialData ? 'Edit Transaction' : 'New Transaction'}
          </h3>
          <p className="text-xs text-slate-500">{initialData ? 'Update details' : 'Record your investment activity'}</p>
        </div>
        <button onClick={onClose} className="p-2 rounded-full hover:bg-slate-200 dark:hover:bg-slate-800 text-slate-400 hover:text-slate-600 dark:hover:text-slate-200 transition-colors">
          <X size={20} />
        </button>
      </div>

      <form onSubmit={handleSubmit} className="flex-1 overflow-y-auto min-h-0 p-4 space-y-5 custom-scrollbar">

        {/* Type Selector */}
        <div>
           <div className="grid grid-cols-3 sm:grid-cols-6 gap-2">
              {[
                { id: TransactionType.BUY, icon: <TrendingUp size={14} />, label: 'Buy', color: 'blue' },
                { id: TransactionType.SELL, icon: <TrendingDown size={14} />, label: 'Sell', color: 'rose' },
                { id: TransactionType.DIVIDEND, icon: <DollarSign size={14} />, label: 'Div', color: 'emerald' },
                { id: TransactionType.SPLIT, icon: <GitFork size={14} />, label: 'Split', color: 'purple' },
                { id: TransactionType.DEPOSIT, icon: <Wallet size={14} />, label: 'In', color: 'indigo' },
                { id: TransactionType.WITHDRAW, icon: <Wallet size={14} />, label: 'Out', color: 'orange' },
              ].map((t) => (
                <button
                  key={t.id}
                  type="button"
                  onClick={() => setType(t.id)}
                  className={`flex flex-col items-center justify-center p-2 rounded-lg border transition-all duration-200 ${
                    type === t.id
                      ? `bg-${t.color}-50 border-${t.color}-500 text-${t.color}-700 dark:bg-${t.color}-900/30 dark:border-${t.color}-500 dark:text-${t.color}-300 ring-1 ring-${t.color}-500 shadow-sm`
                      : 'bg-white dark:bg-slate-800 border-slate-200 dark:border-slate-700 text-slate-500 hover:border-slate-300 dark:hover:border-slate-600'
                  }`}
                >
                  <div className="mb-0.5">{t.icon}</div>
                  <span className="text-[10px] font-bold">{t.label}</span>
                </button>
              ))}
           </div>
        </div>

        {/* Date */}
        <div>
           <div className="relative">
             <Calendar className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={16} />
             <input 
              type="date" 
              required
              value={date}
              onChange={(e) => setDate(e.target.value)}
              className="w-full pl-9 pr-3 py-2.5 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl text-slate-900 dark:text-white focus:ring-2 focus:ring-blue-500 outline-none transition-all font-medium text-sm"
            />
           </div>
        </div>

        {needsSymbol && (
          <div className="space-y-2" ref={wrapperRef}>
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
              <div className="col-span-1 relative">
                 <label className="block text-[10px] font-bold text-slate-500 uppercase tracking-wider mb-1.5">Symbol</label>
                 <div className="relative">
                   <input 
                    type="text" 
                    required
                    placeholder="AAPL"
                    value={symbol}
                    onChange={(e) => {
                      setSymbol(e.target.value);
                      setShowSuggestions(true);
                    }}
                    onFocus={() => setShowSuggestions(true)}
                    className="w-full px-3 py-2.5 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl text-slate-900 dark:text-white focus:ring-2 focus:ring-blue-500 outline-none uppercase font-bold tracking-wide text-sm"
                   />
                   {/* Autocomplete Dropdown */}
                   {showSuggestions && suggestions.length > 0 && (
                      <ul className="absolute z-50 left-0 right-0 mt-1 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl shadow-xl overflow-hidden animate-slide-up">
                        {suggestions.map((s, idx) => (
                           <li 
                             key={s}
                             onMouseDown={(e) => {
                               // Use onMouseDown to prevent blur from firing before click
                               e.preventDefault(); 
                               selectSuggestion(s);
                             }}
                             className={`px-4 py-2 hover:bg-slate-50 dark:hover:bg-slate-700 cursor-pointer text-sm font-bold text-slate-700 dark:text-slate-200 flex items-center justify-between ${idx !== suggestions.length -1 ? 'border-b border-slate-100 dark:border-slate-700/50' : ''}`}
                           >
                             <span>{s}</span>
                             {holdings.some(h => h.symbol === s) && (
                                <span className="text-[10px] font-normal text-slate-400 bg-slate-100 dark:bg-slate-900 px-1.5 py-0.5 rounded">Owned</span>
                             )}
                           </li>
                        ))}
                      </ul>
                   )}
                 </div>
              </div>
               <div className="col-span-1">
                <label className="block text-[10px] font-bold text-slate-500 uppercase tracking-wider mb-1.5">Class</label>
                <select 
                  value={assetClass} 
                  onChange={(e) => setAssetClass(e.target.value as AssetClass)}
                  className="w-full px-3 py-2.5 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl text-slate-900 dark:text-white focus:ring-2 focus:ring-blue-500 outline-none appearance-none text-sm"
                >
                  {Object.values(AssetClass).filter(a => a !== AssetClass.CASH).map(a => <option key={a} value={a}>{a}</option>)}
                </select>
              </div>
            </div>
            {/* Quick Add Chips */}
            {!initialData && quickHoldings.length > 0 && (
               <div className="flex items-center space-x-2 overflow-x-auto pb-1 no-scrollbar">
                  <Zap size={12} className="text-amber-500 shrink-0" />
                  {quickHoldings.map(h => (
                     <button
                       key={h.symbol}
                       type="button"
                       onClick={() => handleQuickAdd(h)}
                       className="px-2 py-1 bg-slate-100 dark:bg-slate-800 hover:bg-blue-50 dark:hover:bg-blue-900/30 text-xs font-medium text-slate-600 dark:text-slate-300 rounded-md transition-colors border border-transparent hover:border-blue-200 dark:hover:border-blue-800 whitespace-nowrap"
                     >
                       {h.symbol}
                     </button>
                  ))}
               </div>
            )}
          </div>
        )}

        <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
           {needsShares && (
            <div className={type === TransactionType.SPLIT ? "col-span-1 sm:col-span-2" : "col-span-1"}>
              <label className="block text-[10px] font-bold text-slate-500 uppercase tracking-wider mb-1.5">
                {type === TransactionType.SPLIT ? "Split Ratio (e.g. 2 for 2:1)" : "Shares"}
              </label>
              <input 
                type="number" 
                step="any"
                min="0"
                required
                onKeyDown={blockInvalidChar}
                placeholder={type === TransactionType.SPLIT ? "2" : "0.00"}
                value={shares}
                onFocus={() => setActiveInput('shares')}
                onChange={(e) => setShares(e.target.value)}
                className="w-full px-3 py-2.5 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl text-slate-900 dark:text-white focus:ring-2 focus:ring-blue-500 outline-none font-mono text-sm"
              />
            </div>
           )}
           {needsPrice && (
             <div className={!needsShares ? "col-span-1 sm:col-span-2" : ""}>
               <label className="block text-[10px] font-bold text-slate-500 uppercase tracking-wider mb-1.5">
                 {needsShares ? "Price / Share" : "Amount ($)"}
               </label>
                <div className="relative">
                  <input 
                    type="number" 
                    step="any"
                    min="0"
                    required
                    onKeyDown={blockInvalidChar}
                    placeholder="0.00"
                    value={price}
                    onFocus={() => setActiveInput('price')}
                    onChange={(e) => setPrice(e.target.value)}
                    className="w-full px-3 py-2.5 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl text-slate-900 dark:text-white focus:ring-2 focus:ring-blue-500 outline-none font-mono text-sm"
                  />
                </div>
             </div>
           )}
        </div>

        {/* Total Amount Calculator Field */}
        {needsShares && needsPrice && (
           <div className="bg-blue-50/50 dark:bg-slate-800/50 p-3 rounded-xl border border-blue-100 dark:border-slate-700/50 flex flex-col sm:flex-row items-start sm:items-center justify-between gap-2">
              <div className="flex items-center space-x-2 text-slate-500 w-full sm:w-auto">
                 <Calculator size={14} />
                 <span className="text-xs font-bold uppercase">Total Amount</span>
              </div>
              <div className="flex items-center space-x-2 w-full sm:w-1/2">
                 <span className="text-slate-400">$</span>
                 <input 
                   type="number"
                   step="any"
                   min="0"
                   onKeyDown={blockInvalidChar}
                   value={totalAmount}
                   onFocus={() => setActiveInput('total')}
                   onChange={(e) => setTotalAmount(e.target.value)}
                   placeholder="0.00"
                   className="w-full bg-transparent border-b border-slate-300 dark:border-slate-600 focus:border-blue-500 outline-none text-right font-mono font-bold text-slate-900 dark:text-white"
                 />
              </div>
           </div>
        )}

        {(type === TransactionType.BUY || type === TransactionType.SELL) && (
           <div>
              <label className="block text-[10px] font-bold text-slate-500 uppercase tracking-wider mb-1.5">
                Fee (Optional)
              </label>
              <input 
                type="number" 
                step="any"
                min="0"
                onKeyDown={blockInvalidChar}
                placeholder="0.00"
                value={fee}
                onChange={(e) => setFee(e.target.value)}
                className="w-full px-3 py-2.5 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl text-slate-900 dark:text-white focus:ring-2 focus:ring-blue-500 outline-none font-mono text-sm"
              />
           </div>
        )}

        {isFunding && (
           <div className="bg-blue-50 dark:bg-slate-800/50 p-3 rounded-xl border border-blue-100 dark:border-slate-700">
             <label className="block text-[10px] font-bold text-slate-500 uppercase tracking-wider mb-1.5">
               Exchange Rate (Optional)
             </label>
              <div className="flex items-center space-x-2">
                <input 
                  type="number" 
                  step="any"
                  min="0"
                  onKeyDown={blockInvalidChar}
                  placeholder="1.00"
                  value={exchangeRate}
                  onChange={(e) => setExchangeRate(e.target.value)}
                  className="flex-1 px-3 py-2 bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-600 rounded-lg text-slate-900 dark:text-white focus:ring-2 focus:ring-blue-500 outline-none font-mono text-right text-sm"
                />
                <span className="text-xs font-medium text-slate-500">Local / USD</span>
              </div>
           </div>
        )}

        <div>
           <label className="block text-[10px] font-bold text-slate-500 uppercase tracking-wider mb-1.5">Notes (Optional)</label>
           <textarea
             rows={2}
             placeholder="Add a memo..."
             value={notes}
             onChange={(e) => setNotes(e.target.value)}
             className="w-full px-3 py-2.5 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl text-slate-900 dark:text-white focus:ring-2 focus:ring-blue-500 outline-none resize-none font-medium text-sm"
           />
        </div>
      </form>

      <div className="shrink-0 bg-white dark:bg-slate-900 border-t border-slate-100 dark:border-slate-800 p-4 shadow-[0_-4px_6px_-1px_rgba(0,0,0,0.05)] z-10">
         <div className="flex flex-col space-y-3 mb-4">
               {/* Main Details */}
               <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-3">
                   <div className="w-full sm:w-auto flex justify-between sm:block">
                      <p className="text-xs text-slate-500 dark:text-slate-400 font-medium uppercase tracking-wider mb-0.5">Net Amount</p>
                      <div className="flex items-baseline space-x-2">
                         <span className={`text-2xl font-bold font-display ${
                             netAmount > 0 ? 'text-emerald-600 dark:text-emerald-400' : 
                             netAmount < 0 ? 'text-slate-900 dark:text-white' : 'text-slate-500'
                         }`}>
                            {netAmount > 0 ? '+' : ''}{formatCurrency(netAmount)}
                         </span>
                      </div>
                   </div>
                   <div className="text-left sm:text-right w-full sm:w-auto flex flex-row sm:flex-col justify-between sm:justify-start items-center sm:items-end">
                      <p className="text-xs text-slate-500 dark:text-slate-400 font-medium uppercase tracking-wider mb-0.5">Cash Balance</p>
                      <div className="flex items-center justify-end space-x-2 text-sm">
                         <span className="text-slate-400 line-through decoration-slate-300 dark:decoration-slate-600">{formatCurrency(cashBalance)}</span>
                         <ArrowRight size={14} className="text-slate-300" />
                         <span className={`font-bold ${projectedCash < 0 ? 'text-rose-500' : 'text-slate-700 dark:text-slate-300'}`}>
                            {formatCurrency(projectedCash)}
                         </span>
                      </div>
                   </div>
               </div>
         </div>

         {error && (
           <div className="bg-rose-50 dark:bg-rose-900/20 border border-rose-200 dark:border-rose-800 rounded-xl p-3 mb-4 flex items-start space-x-3 text-rose-600 dark:text-rose-400 animate-slide-up">
               <AlertCircle size={18} className="shrink-0 mt-0.5" />
               <div className="text-sm font-semibold">{error}</div>
           </div>
         )}

          <div className="flex gap-3">
            {initialData && onDelete && (
               <button
                 type="button"
                 onClick={() => onDelete(initialData.id)}
                 className="px-4 py-3 rounded-xl font-bold bg-rose-50 text-rose-500 hover:bg-rose-100 dark:bg-rose-900/20 dark:text-rose-400 transition-colors"
               >
                 <Trash2 size={20} />
               </button>
            )}

            <button 
              onClick={handleSubmit}
              disabled={!!error || isSaving}
              className={`flex-1 font-bold py-3 rounded-xl shadow-lg transition-all flex items-center justify-center space-x-2 text-base ${
                error || isSaving
                  ? 'bg-slate-300 dark:bg-slate-700 text-slate-500 cursor-not-allowed' 
                  : 'bg-slate-900 dark:bg-blue-600 hover:opacity-90 text-white shadow-slate-900/20 dark:shadow-blue-600/20 active:scale-95'
              }`}
            >
              {isSaving ? (
                <Spinner className="text-white" />
              ) : (
                <>
                  <Save size={18} />
                  <span>{initialData ? 'Update Transaction' : 'Save Transaction'}</span>
                </>
              )}
            </button>
          </div>
      </div>
    </>
  );
};

export default App;

import React, { useState, useMemo } from 'react';
import { Holding, Transaction, AssetClass } from '../types';
import { formatCurrency, formatNumber } from '../utils';
import { RefreshCw, Briefcase, LayoutGrid, List, Layers, PieChart, ArrowUpRight, ArrowDownRight, Eye, EyeOff, Wallet } from 'lucide-react';
import { LineChart, Line, ResponsiveContainer, YAxis } from 'recharts';
import { HoldingsSkeleton } from './LoadingSkeletons';

interface HoldingsProps {
  holdings: Holding[];
  transactions: Transaction[];
  onUpdatePrice: (symbol: string, newPrice: number) => void;
  isLoading?: boolean;
}

const Holdings: React.FC<HoldingsProps> = ({ holdings, transactions, onUpdatePrice, isLoading }) => {
  const [activeView, setActiveView] = useState<'holdings' | 'allocation'>('holdings');
  const [viewMode, setViewMode] = useState<'grid' | 'list'>('list');
  const [groupByCategory, setGroupByCategory] = useState(false);
  const [hideClosed, setHideClosed] = useState(false);

  // Price Editing State
  const [editingPrice, setEditingPrice] = useState<string | null>(null);
  const [tempPrice, setTempPrice] = useState<string>('');

  const handleEditClick = (symbol: string, currentPrice: number) => {
    setEditingPrice(symbol);
    setTempPrice(currentPrice.toString());
  };

  const handleSavePrice = (symbol: string) => {
    const price = parseFloat(tempPrice);
    if (!isNaN(price) && price >= 0) {
      onUpdatePrice(symbol, price);
    }
    setEditingPrice(null);
  };

  // --- DATA PROCESSING ---

  // 0. Filter Holdings based on Visibility Toggle
  const displayHoldings = useMemo(() => {
    return hideClosed 
      ? holdings.filter(h => h.shares > 0.000001) 
      : holdings;
  }, [holdings, hideClosed]);

  // 1. Group Holdings by Asset Class
  const groupedHoldings = useMemo(() => {
    const groups: Partial<Record<AssetClass, Holding[]>> = {};
    displayHoldings.forEach(h => {
      if (!groups[h.assetClass]) groups[h.assetClass] = [];
      groups[h.assetClass]?.push(h);
    });
    return groups;
  }, [displayHoldings]);

  // 2. Allocation Stats
  const allocationStats = useMemo(() => {
    const totalPortfolioValue = displayHoldings.reduce((sum, h) => sum + h.marketValue, 0);

    return Object.values(AssetClass).map(ac => {
      const classHoldings = displayHoldings.filter(h => h.assetClass === ac);
      if (classHoldings.length === 0) return null;

      const marketValue = classHoldings.reduce((sum, h) => sum + h.marketValue, 0);
      const totalCost = classHoldings.reduce((sum, h) => sum + h.totalCost, 0);
      const unrealizedPL = marketValue - totalCost;
      const weight = totalPortfolioValue > 0 ? (marketValue / totalPortfolioValue) * 100 : 0;
      const count = classHoldings.length;

      return { assetClass: ac, marketValue, totalCost, unrealizedPL, weight, count };
    }).filter(Boolean) as { assetClass: AssetClass, marketValue: number, totalCost: number, unrealizedPL: number, weight: number, count: number }[];
  }, [displayHoldings]);

  // 3. Global Stats for Summary Header
  // Note: We typically want the summary header to reflect the ACTIVE portfolio value, 
  // but showing Realized P/L of closed positions might be desired in a "History" context.
  // For "Assets" view, filtering usually implies we only want to see what we have now.
  const { totalMarketValue, totalCost, totalUnrealizedPL, totalReturnPercent } = useMemo(() => {
    const mv = displayHoldings.reduce((sum, h) => sum + h.marketValue, 0);
    const cost = displayHoldings.reduce((sum, h) => sum + h.totalCost, 0);
    const pl = mv - cost;
    const pct = cost > 0 ? (pl / cost) * 100 : 0;
    return { totalMarketValue: mv, totalCost: cost, totalUnrealizedPL: pl, totalReturnPercent: pct };
  }, [displayHoldings]);


  if (isLoading) {
    return <HoldingsSkeleton />;
  }

  // --- RENDER HELPERS ---

  const renderSparkline = (h: Holding) => {
    const sparklineData = transactions
      .filter(t => t.symbol === h.symbol && (t.type === 'BUY' || t.type === 'SELL') && (t.price || 0) > 0)
      .sort((a, b) => new Date(a.date).getTime() - new Date(b.date).getTime())
      .map((t, i) => ({ i, price: t.price! }));

    if (h.currentPrice > 0 && (sparklineData.length === 0 || sparklineData[sparklineData.length-1].price !== h.currentPrice)) {
        sparklineData.push({ i: sparklineData.length, price: h.currentPrice });
    }

    const isUp = sparklineData.length > 1 ? sparklineData[sparklineData.length - 1].price >= sparklineData[0].price : true;
    const strokeColor = isUp ? '#10b981' : '#ef4444';

    if (sparklineData.length <= 1) return <div className="text-[10px] text-slate-300 italic">No Data</div>;

    return (
      <ResponsiveContainer width="100%" height="100%">
        <LineChart data={sparklineData}>
          <Line type="monotone" dataKey="price" stroke={strokeColor} strokeWidth={2} dot={false} isAnimationActive={false} />
          <YAxis domain={['dataMin', 'dataMax']} hide />
        </LineChart>
      </ResponsiveContainer>
    );
  };

  const renderCard = (h: Holding) => (
    <div key={h.symbol} className={`glass-card rounded-2xl p-5 hover:border-blue-300 dark:hover:border-blue-700 transition-all duration-300 group relative ${h.shares === 0 ? 'opacity-60 grayscale hover:grayscale-0 hover:opacity-100' : ''}`}>
       {/* Card Header */}
       <div className="flex justify-between items-start mb-2">
         <div className="flex items-start space-x-3">
            <div className="w-10 h-10 rounded-lg bg-slate-100 dark:bg-slate-800 flex items-center justify-center font-bold text-slate-700 dark:text-slate-300 text-sm border border-slate-200 dark:border-slate-700 shrink-0">
               {h.symbol.substring(0, 2)}
            </div>
            <div className="overflow-hidden">
               <h3 className="font-bold text-slate-900 dark:text-white leading-tight truncate">{h.symbol}</h3>
               <p className="text-xs text-slate-500 dark:text-slate-400 truncate max-w-[100px]">{h.name}</p>
            </div>
         </div>
         <div className="flex flex-col items-end gap-1">
            <span className="px-2.5 py-1 text-[10px] font-bold uppercase tracking-wide bg-slate-100 dark:bg-slate-800 text-slate-500 dark:text-slate-400 rounded-md border border-slate-200 dark:border-slate-700">
            {h.assetClass}
            </span>
            {h.shares === 0 && <span className="text-[10px] font-bold text-slate-400">SOLD</span>}
         </div>
       </div>

       {/* Sparkline */}
       <div className="h-10 w-full mb-3 -ml-1 opacity-80 group-hover:opacity-100 transition-opacity">
          {renderSparkline(h)}
       </div>

       {/* Stats */}
       <div className="space-y-3">
          <div className="flex justify-between items-end">
             <span className="text-xs text-slate-500">Market Value</span>
             <span className="text-lg font-display font-bold text-slate-900 dark:text-white">
               {formatCurrency(h.marketValue)}
             </span>
          </div>
          <div className="grid grid-cols-2 gap-y-3 gap-x-2 py-3 border-t border-slate-100 dark:border-slate-700/50">
             <div>
               <p className="text-[10px] uppercase text-slate-400 font-semibold mb-0.5">Quantity</p>
               <p className="text-sm font-medium text-slate-700 dark:text-slate-300">{formatNumber(h.shares, 4)}</p>
             </div>
             <div className="text-right">
               <p className="text-[10px] uppercase text-slate-400 font-semibold mb-0.5">P/L</p>
               <p className={`text-sm font-bold ${h.unrealizedPL >= 0 ? 'text-emerald-500' : 'text-rose-500'}`}>
                  {h.unrealizedPL >= 0 ? '+' : ''}{formatCurrency(h.unrealizedPL)}
               </p>
             </div>
          </div>
       </div>

       {/* Price Edit */}
       <div className="flex items-center justify-between pt-3 border-t border-slate-100 dark:border-slate-700/50 mt-1">
           <div className="flex flex-col">
              <span className="text-[10px] text-slate-400 uppercase font-semibold">Price</span>
              {editingPrice === h.symbol ? (
                <input 
                  type="number" 
                  value={tempPrice} 
                  onChange={(e) => setTempPrice(e.target.value)}
                  className="w-20 px-2 py-0.5 text-sm border border-blue-500 rounded bg-white dark:bg-slate-900 dark:text-white focus:outline-none"
                  autoFocus
                  onBlur={() => handleSavePrice(h.symbol)}
                  onKeyDown={(e) => e.key === 'Enter' && handleSavePrice(h.symbol)}
                />
              ) : (
                <button 
                  className="group/price flex items-center space-x-1.5 mt-0.5 hover:text-blue-600 transition-colors text-left"
                  onClick={() => handleEditClick(h.symbol, h.currentPrice)}
                >
                  <span className="text-sm font-bold text-slate-700 dark:text-slate-200">{formatCurrency(h.currentPrice)}</span>
                  <RefreshCw size={12} className="text-slate-300 group-hover/price:text-blue-500 transition-colors" />
                </button>
              )}
           </div>
           <div className="flex flex-col items-end">
              <span className="text-[10px] text-slate-400 uppercase font-semibold">Avg Cost</span>
              <span className="text-sm font-medium text-slate-600 dark:text-slate-400">{formatCurrency(h.avgCost)}</span>
           </div>
       </div>
    </div>
  );

  const renderTableRows = (list: Holding[]) => (
    <div className="bg-white dark:bg-slate-800 rounded-2xl shadow-sm border border-slate-200 dark:border-slate-700 overflow-hidden">
      <div className="overflow-x-auto">
        <table className="w-full text-left text-sm">
          <thead className="bg-slate-50 dark:bg-slate-900/50 text-slate-500 dark:text-slate-400 border-b border-slate-200 dark:border-slate-700">
             <tr>
               <th className="px-6 py-4 font-semibold">Asset</th>
               <th className="px-6 py-4 font-semibold text-right">Price</th>
               <th className="px-6 py-4 font-semibold text-right">Shares</th>
               <th className="px-6 py-4 font-semibold text-right">Avg Cost</th>
               <th className="px-6 py-4 font-semibold text-right">Market Value</th>
               <th className="px-6 py-4 font-semibold text-right">Unrealized P/L</th>
               <th className="px-6 py-4 font-semibold text-right">Return</th>
             </tr>
          </thead>
          <tbody className="divide-y divide-slate-100 dark:divide-slate-800">
             {list.map(h => (
               <tr key={h.symbol} className={`hover:bg-slate-50 dark:hover:bg-slate-800/50 transition-colors ${h.shares === 0 ? 'opacity-50 grayscale hover:opacity-100 hover:grayscale-0' : ''}`}>
                  <td className="px-6 py-4">
                     <div className="flex items-center space-x-3">
                        <div className="w-8 h-8 rounded-lg bg-slate-100 dark:bg-slate-800 flex items-center justify-center text-xs font-bold text-slate-600 dark:text-slate-400">
                           {h.symbol.substring(0, 2)}
                        </div>
                        <div>
                           <div className="flex items-center gap-2">
                             <div className="font-bold text-slate-900 dark:text-white">{h.symbol}</div>
                             {h.shares === 0 && <span className="text-[10px] font-bold px-1.5 py-0.5 rounded bg-slate-100 dark:bg-slate-700 text-slate-500">SOLD</span>}
                           </div>
                           <div className="text-xs text-slate-500 truncate max-w-[120px]">{h.name}</div>
                        </div>
                     </div>
                  </td>
                  <td className="px-6 py-4 text-right">
                      {editingPrice === h.symbol ? (
                        <input 
                          type="number" 
                          value={tempPrice} 
                          onChange={(e) => setTempPrice(e.target.value)}
                          className="w-24 px-2 py-1 text-sm border border-blue-500 rounded bg-white dark:bg-slate-900 dark:text-white focus:outline-none text-right"
                          autoFocus
                          onBlur={() => handleSavePrice(h.symbol)}
                          onKeyDown={(e) => e.key === 'Enter' && handleSavePrice(h.symbol)}
                        />
                      ) : (
                        <button 
                          onClick={() => handleEditClick(h.symbol, h.currentPrice)}
                          className="font-medium text-slate-700 dark:text-slate-200 hover:text-blue-500 dark:hover:text-blue-400 transition-colors group flex items-center justify-end ml-auto"
                        >
                          {formatCurrency(h.currentPrice)}
                          <RefreshCw size={10} className="ml-1.5 opacity-0 group-hover:opacity-100" />
                        </button>
                      )}
                  </td>
                  <td className="px-6 py-4 text-right text-slate-600 dark:text-slate-300 font-mono">
                     {formatNumber(h.shares, 4)}
                  </td>
                  <td className="px-6 py-4 text-right text-slate-600 dark:text-slate-300">
                     {formatCurrency(h.avgCost)}
                  </td>
                  <td className="px-6 py-4 text-right font-bold text-slate-900 dark:text-white">
                     {formatCurrency(h.marketValue)}
                  </td>
                  <td className="px-6 py-4 text-right font-medium">
                     <div className={h.unrealizedPL >= 0 ? 'text-emerald-500' : 'text-rose-500'}>
                        {h.unrealizedPL >= 0 ? '+' : ''}{formatCurrency(h.unrealizedPL)}
                     </div>
                  </td>
                  <td className="px-6 py-4 text-right">
                     <span className={`inline-flex items-center px-2 py-0.5 rounded text-xs font-bold ${
                       h.unrealizedPLPercent >= 0 ? 'bg-emerald-50 text-emerald-700 dark:bg-emerald-900/20 dark:text-emerald-400' : 'bg-rose-50 text-rose-700 dark:bg-rose-900/20 dark:text-rose-400'
                     }`}>
                        {h.unrealizedPLPercent >= 0 ? <ArrowUpRight size={12} className="mr-0.5"/> : <ArrowDownRight size={12} className="mr-0.5"/>}
                        {Math.abs(h.unrealizedPLPercent).toFixed(2)}%
                     </span>
                  </td>
               </tr>
             ))}
          </tbody>
        </table>
      </div>
    </div>
  );

  return (
    <div className="space-y-6 animate-fade-in">

      {/* 1. Header & Controls */}
      <div className="flex flex-col gap-6">
        <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
           <div>
             <h2 className="text-2xl font-display font-bold text-slate-900 dark:text-white">Assets</h2>
             <p className="text-slate-500 dark:text-slate-400 text-sm">Manage your portfolio and track performance</p>
           </div>

           <div className="flex items-center gap-2 bg-white dark:bg-slate-800 p-1.5 rounded-xl border border-slate-200 dark:border-slate-700 shadow-sm">
              <button 
                onClick={() => setActiveView('holdings')}
                className={`flex items-center space-x-2 px-4 py-2 rounded-lg text-sm font-bold transition-all ${
                  activeView === 'holdings' 
                  ? 'bg-slate-100 dark:bg-slate-700 text-slate-900 dark:text-white' 
                  : 'text-slate-500 hover:text-slate-700 dark:text-slate-400 dark:hover:text-slate-200'
                }`}
              >
                <Briefcase size={16} />
                <span>Holdings</span>
              </button>
              <button 
                onClick={() => setActiveView('allocation')}
                className={`flex items-center space-x-2 px-4 py-2 rounded-lg text-sm font-bold transition-all ${
                  activeView === 'allocation' 
                  ? 'bg-slate-100 dark:bg-slate-700 text-slate-900 dark:text-white' 
                  : 'text-slate-500 hover:text-slate-700 dark:text-slate-400 dark:hover:text-slate-200'
                }`}
              >
                <PieChart size={16} />
                <span>Allocation</span>
              </button>
           </div>
        </div>

        {/* Portfolio Summary Cards */}
        <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
             {/* Market Value */}
             <div className="glass-card p-4 rounded-xl border border-slate-200 dark:border-slate-700 flex flex-col justify-center">
                  <div className="flex items-center space-x-2 mb-1.5">
                     <div className="p-1.5 rounded-lg bg-blue-50 dark:bg-blue-900/30 text-blue-600 dark:text-blue-400">
                        <Wallet size={14} />
                     </div>
                     <p className="text-xs text-slate-500 dark:text-slate-400 uppercase font-bold tracking-wider">Net Asset Value</p>
                  </div>
                  <h3 className="text-2xl font-display font-bold text-slate-900 dark:text-white">
                      {formatCurrency(totalMarketValue)}
                  </h3>
             </div>

             {/* Cost Basis */}
             <div className="glass-card p-4 rounded-xl border border-slate-200 dark:border-slate-700 flex flex-col justify-center">
                  <p className="text-xs text-slate-500 dark:text-slate-400 uppercase font-bold tracking-wider mb-1.5 ml-1">Total Cost Basis</p>
                  <h3 className="text-2xl font-display font-bold text-slate-900 dark:text-white">
                      {formatCurrency(totalCost)}
                  </h3>
             </div>

             {/* Total P/L */}
             <div className="glass-card p-4 rounded-xl border border-slate-200 dark:border-slate-700 flex flex-col justify-center">
                  <div className="flex justify-between items-start mb-1">
                      <p className="text-xs text-slate-500 dark:text-slate-400 uppercase font-bold tracking-wider">Total Unrealized P/L</p>
                      <span className={`flex items-center text-xs font-bold px-1.5 py-0.5 rounded ${totalReturnPercent >= 0 ? 'bg-emerald-100 text-emerald-700 dark:bg-emerald-900/30 dark:text-emerald-400' : 'bg-rose-100 text-rose-700 dark:bg-rose-900/30 dark:text-rose-400'}`}>
                         {totalReturnPercent >= 0 ? <ArrowUpRight size={12} className="mr-0.5"/> : <ArrowDownRight size={12} className="mr-0.5"/>}
                         {Math.abs(totalReturnPercent).toFixed(2)}%
                      </span>
                  </div>
                  <h3 className={`text-2xl font-display font-bold ${totalUnrealizedPL >= 0 ? 'text-emerald-600 dark:text-emerald-400' : 'text-rose-600 dark:text-rose-400'}`}>
                      {totalUnrealizedPL >= 0 ? '+' : ''}{formatCurrency(totalUnrealizedPL)}
                  </h3>
             </div>
        </div>

        {/* View Options Toolbar (Only for Holdings Tab) */}
        {activeView === 'holdings' && (
           <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
              <div className="flex items-center space-x-2 w-full sm:w-auto overflow-x-auto">
                 <button 
                   onClick={() => setGroupByCategory(!groupByCategory)}
                   className={`flex items-center space-x-2 px-3 py-1.5 rounded-lg text-xs font-medium border transition-all whitespace-nowrap ${
                     groupByCategory
                     ? 'bg-blue-50 border-blue-200 text-blue-600 dark:bg-blue-900/20 dark:border-blue-800 dark:text-blue-400'
                     : 'bg-white border-slate-200 text-slate-600 dark:bg-slate-800 dark:border-slate-700 dark:text-slate-400 hover:bg-slate-50 dark:hover:bg-slate-700'
                   }`}
                 >
                    <Layers size={14} />
                    <span>Group by Category</span>
                 </button>

                 <button 
                   onClick={() => setHideClosed(!hideClosed)}
                   className={`flex items-center space-x-2 px-3 py-1.5 rounded-lg text-xs font-medium border transition-all whitespace-nowrap ${
                     hideClosed
                     ? 'bg-blue-50 border-blue-200 text-blue-600 dark:bg-blue-900/20 dark:border-blue-800 dark:text-blue-400'
                     : 'bg-white border-slate-200 text-slate-600 dark:bg-slate-800 dark:border-slate-700 dark:text-slate-400 hover:bg-slate-50 dark:hover:bg-slate-700'
                   }`}
                 >
                    {hideClosed ? <EyeOff size={14} /> : <Eye size={14} />}
                    <span>{hideClosed ? 'Showing Active Only' : 'Show All'}</span>
                 </button>
              </div>

              <div className="flex items-center bg-white dark:bg-slate-800 rounded-lg border border-slate-200 dark:border-slate-700 p-1 self-end sm:self-auto">
                 <button 
                   onClick={() => setViewMode('list')}
                   className={`p-1.5 rounded-md transition-all ${viewMode === 'list' ? 'bg-slate-100 dark:bg-slate-700 text-slate-900 dark:text-white shadow-sm' : 'text-slate-400 hover:text-slate-600'}`}
                   title="List View"
                 >
                    <List size={16} />
                 </button>
                 <button 
                   onClick={() => setViewMode('grid')}
                   className={`p-1.5 rounded-md transition-all ${viewMode === 'grid' ? 'bg-slate-100 dark:bg-slate-700 text-slate-900 dark:text-white shadow-sm' : 'text-slate-400 hover:text-slate-600'}`}
                   title="Grid View"
                 >
                    <LayoutGrid size={16} />
                 </button>
              </div>
           </div>
        )}
      </div>

      {/* 2. Content Area */}

      {/* ALLOCATION VIEW */}
      {activeView === 'allocation' && (
         <div className="animate-slide-up">
            <div className="bg-white dark:bg-slate-800 rounded-2xl shadow-sm border border-slate-200 dark:border-slate-700 overflow-hidden">
               <div className="overflow-x-auto">
                 <table className="w-full text-left text-sm">
                   <thead className="bg-slate-50 dark:bg-slate-900/50 text-slate-500 dark:text-slate-400 border-b border-slate-200 dark:border-slate-700">
                     <tr>
                       <th className="px-6 py-4 font-semibold">Asset Class</th>
                       <th className="px-6 py-4 font-semibold text-right">Holdings</th>
                       <th className="px-6 py-4 font-semibold text-right">Total Cost</th>
                       <th className="px-6 py-4 font-semibold text-right">Market Value</th>
                       <th className="px-6 py-4 font-semibold">Allocation</th>
                       <th className="px-6 py-4 font-semibold text-right">Unrealized P/L</th>
                     </tr>
                   </thead>
                   <tbody className="divide-y divide-slate-100 dark:divide-slate-800">
                     {allocationStats.sort((a,b) => b.marketValue - a.marketValue).map(stat => (
                       <tr key={stat.assetClass} className="hover:bg-slate-50 dark:hover:bg-slate-800/50">
                          <td className="px-6 py-4">
                             <div className="flex items-center space-x-3">
                                <div className="p-2 rounded-lg bg-slate-100 dark:bg-slate-800 text-slate-600 dark:text-slate-400">
                                   <PieChart size={18} />
                                </div>
                                <span className="font-bold text-slate-900 dark:text-white">{stat.assetClass}</span>
                             </div>
                          </td>
                          <td className="px-6 py-4 text-right text-slate-600 dark:text-slate-400">
                             {stat.count}
                          </td>
                          <td className="px-6 py-4 text-right text-slate-600 dark:text-slate-400">
                             {formatCurrency(stat.totalCost)}
                          </td>
                          <td className="px-6 py-4 text-right font-bold text-slate-900 dark:text-white">
                             {formatCurrency(stat.marketValue)}
                          </td>
                          <td className="px-6 py-4 align-middle min-w-[140px]">
                             <div className="w-full bg-slate-100 dark:bg-slate-700 rounded-full h-2.5 overflow-hidden">
                                <div className="bg-blue-500 h-full rounded-full" style={{ width: `${stat.weight}%` }}></div>
                             </div>
                             <div className="text-xs text-slate-500 mt-1 text-right">{stat.weight.toFixed(1)}%</div>
                          </td>
                          <td className="px-6 py-4 text-right font-medium">
                              <div className={stat.unrealizedPL >= 0 ? 'text-emerald-500' : 'text-rose-500'}>
                                 {stat.unrealizedPL >= 0 ? '+' : ''}{formatCurrency(stat.unrealizedPL)}
                              </div>
                              <div className={`text-xs ${stat.totalCost > 0 ? (stat.unrealizedPL >= 0 ? 'text-emerald-600/70' : 'text-rose-600/70') : 'text-slate-400'}`}>
                                 {stat.totalCost > 0 ? ((stat.unrealizedPL / stat.totalCost) * 100).toFixed(2) + '%' : '0.00%'}
                              </div>
                          </td>
                       </tr>
                     ))}
                   </tbody>
                 </table>
               </div>
            </div>
         </div>
      )}

      {/* HOLDINGS VIEW */}
      {activeView === 'holdings' && (
         <div className="space-y-8 animate-slide-up">
            {groupByCategory ? (
               // GROUPED VIEW
               Object.keys(groupedHoldings).map((assetClass) => {
                  const items = groupedHoldings[assetClass as AssetClass];
                  if (!items || items.length === 0) return null;

                  return (
                     <div key={assetClass} className="space-y-3">
                        <div className="flex items-center space-x-2 px-1">
                           <span className="bg-slate-200 dark:bg-slate-700 text-slate-600 dark:text-slate-300 px-2 py-0.5 rounded text-xs font-bold uppercase tracking-wide">
                              {assetClass}
                           </span>
                           <div className="h-px bg-slate-200 dark:bg-slate-800 flex-1"></div>
                           <span className="text-xs text-slate-400 font-medium">{items.length} items</span>
                        </div>

                        {viewMode === 'grid' ? (
                           <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">
                              {items.map(h => renderCard(h))}
                           </div>
                        ) : (
                           renderTableRows(items)
                        )}
                     </div>
                  );
               })
            ) : (
               // UNGROUPED VIEW
               viewMode === 'grid' ? (
                  <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">
                     {displayHoldings.map(h => renderCard(h))}
                  </div>
               ) : (
                  renderTableRows(displayHoldings)
               )
            )}

            {displayHoldings.length === 0 && (
               <div className="py-20 flex flex-col items-center justify-center text-center p-8 rounded-3xl border-2 border-dashed border-slate-200 dark:border-slate-700 bg-slate-50/50 dark:bg-slate-800/50">
                  <div className="w-16 h-16 bg-slate-100 dark:bg-slate-800 rounded-full flex items-center justify-center mb-4">
                     <Briefcase size={32} className="text-slate-400" />
                  </div>
                  <h3 className="text-lg font-bold text-slate-900 dark:text-white">No Assets Found</h3>
                  <p className="text-slate-500 dark:text-slate-400 max-w-md mt-2">
                     {hideClosed 
                        ? "No active holdings found. Try showing all holdings to see sold positions." 
                        : "Your portfolio is currently empty. Start by adding your first buy transaction."}
                  </p>
               </div>
            )}
         </div>
      )}
    </div>
  );
};

export default Holdings;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import Layout from './components/Layout';
import Dashboard from './components/Dashboard';
import Holdings from './components/Holdings';
import Reports from './components/Reports';
import History from './components/History';
import GoalModal from './components/GoalModal';
import { Transaction, TransactionType, AssetClass, Holding, Portfolio, FinancialGoal } from './types';
import { calculateHoldings, calculatePortfolioHistory, generateId, formatCurrency, formatNumber } from './utils';
import { X, Save, TrendingUp, TrendingDown, DollarSign, Wallet, Calendar, GitFork, AlertCircle, ArrowRight, Trash2, Zap, Calculator, Search, Clock } from 'lucide-react';
import { Spinner } from './components/LoadingSkeletons';

const POPULAR_SYMBOLS = [
  'AAPL', 'MSFT', 'GOOGL', 'AMZN', 'NVDA', 'TSLA', 'META', 'BRK.B', 'V', 'JNJ', 'WMT', 'JPM', // Tech/Blue Chip
  'VOO', 'VTI', 'QQQ', 'IVV', 'SCHD', 'JEPI', 'VUG', 'VTV', // ETFs
  'BTC', 'ETH', 'SOL', 'USDT', 'BNB', 'XRP', 'ADA' // Crypto
];

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState('dashboard');
  const [isAddModalOpen, setIsAddModalOpen] = useState(false);
  const [editingTransaction, setEditingTransaction] = useState<Transaction | null>(null);

  // Goal Modal State
  const [isGoalModalOpen, setIsGoalModalOpen] = useState(false);

  // --- CONFIRMATION MODAL STATE ---
  const [confirmConfig, setConfirmConfig] = useState<{
    isOpen: boolean;
    title: string;
    message: string;
    onConfirm: () => void;
  }>({
    isOpen: false,
    title: '',
    message: '',
    onConfirm: () => {},
  });

  // --- PORTFOLIO MANAGEMENT STATE ---
  const [portfolios, setPortfolios] = useState<Portfolio[]>(() => {
    const saved = localStorage.getItem('portfolios');
    if (saved) return JSON.parse(saved);

    // Migration: If no portfolios exist but we have legacy transactions, create a default one
    const legacyTx = localStorage.getItem('transactions');
    if (legacyTx) {
      return [{ id: 'default', name: 'Main Portfolio' }];
    }

    return [{ id: generateId(), name: 'My First Portfolio' }];
  });

  const [activePortfolioId, setActivePortfolioId] = useState<string>(() => {
    const saved = localStorage.getItem('activePortfolioId');
    const portfolios = JSON.parse(localStorage.getItem('portfolios') || '[]');
    if (saved && portfolios.some((p: Portfolio) => p.id === saved)) return saved;
    return portfolios.length > 0 ? portfolios[0].id : 'default';
  });

  // --- DATA STATE (Per Portfolio) - Synchronous Initialization ---

  const [transactions, setTransactions] = useState<Transaction[]>(() => {
    const key = `transactions_${activePortfolioId}`;
    const saved = localStorage.getItem(key);
    if (saved) return JSON.parse(saved);

    // Legacy fallback
    if (activePortfolioId === 'default') {
      const legacy = localStorage.getItem('transactions');
      if (legacy) return JSON.parse(legacy);
    }
    return [];
  });

  const [prices, setPrices] = useState<Record<string, number>>(() => {
    const key = `prices_${activePortfolioId}`;
    const saved = localStorage.getItem(key);
    if (saved) return JSON.parse(saved);

    // Legacy fallback
    if (activePortfolioId === 'default') {
      const legacy = localStorage.getItem('prices');
      if (legacy) return JSON.parse(legacy);
    }
    return {};
  });

  const [goals, setGoals] = useState<FinancialGoal[]>(() => {
    const key = `goals_${activePortfolioId}`;
    const saved = localStorage.getItem(key);
    if (saved) return JSON.parse(saved);

    // Legacy fallback logic
    let legacyGoal = 100000;
    const legacyKey = `financialGoal_${activePortfolioId}`;
    const savedLegacy = localStorage.getItem(legacyKey);

    if (savedLegacy) {
      legacyGoal = parseFloat(savedLegacy);
    } else if (activePortfolioId === 'default') {
      const oldGlobal = localStorage.getItem('financialGoal');
      if (oldGlobal) legacyGoal = parseFloat(oldGlobal);
    }

    return [{
      id: generateId(),
      targetAmount: legacyGoal,
      startDate: new Date().toISOString(),
      isAchieved: false,
      notes: 'Initial Goal'
    }];
  });

  const [isDataLoaded, setIsDataLoaded] = useState(true); // Started true because we loaded synchronously
  const [isLoading, setIsLoading] = useState(false); // Started false, ready to render
  const isFirstMount = useRef(true);

  // --- PERSISTENCE: Portfolios List ---
  useEffect(() => {
    localStorage.setItem('portfolios', JSON.stringify(portfolios));
  }, [portfolios]);

  useEffect(() => {
    localStorage.setItem('activePortfolioId', activePortfolioId);
  }, [activePortfolioId]);

  // --- PERSISTENCE: Load Data on Portfolio Switch ONLY ---
  useEffect(() => {
    // Skip the first run because we already initialized state synchronously
    if (isFirstMount.current) {
      isFirstMount.current = false;
      return;
    }

    setIsLoading(true);
    setIsDataLoaded(false);

    const loadData = () => {
        const txKey = `transactions_${activePortfolioId}`;
        const pricesKey = `prices_${activePortfolioId}`;
        const goalsKey = `goals_${activePortfolioId}`;
        const legacyGoalKey = `financialGoal_${activePortfolioId}`;

        // Load Transactions
        const savedTx = localStorage.getItem(txKey);
        if (savedTx) {
          setTransactions(JSON.parse(savedTx));
        } else if (activePortfolioId === 'default' && localStorage.getItem('transactions')) {
          setTransactions(JSON.parse(localStorage.getItem('transactions')!));
        } else {
          setTransactions([]);
        }

        // Load Prices
        const savedPrices = localStorage.getItem(pricesKey);
        if (savedPrices) {
          setPrices(JSON.parse(savedPrices));
        } else if (activePortfolioId === 'default' && localStorage.getItem('prices')) {
          setPrices(JSON.parse(localStorage.getItem('prices')!));
        } else {
          setPrices({});
        }

        // Load Goals
        const savedGoals = localStorage.getItem(goalsKey);
        if (savedGoals) {
           setGoals(JSON.parse(savedGoals));
        } else {
           let legacyGoal = 100000;
           const savedLegacy = localStorage.getItem(legacyGoalKey);
           if (savedLegacy) {
             legacyGoal = parseFloat(savedLegacy);
           } else if (activePortfolioId === 'default' && localStorage.getItem('financialGoal')) {
             legacyGoal = parseFloat(localStorage.getItem('financialGoal')!);
           }

           setGoals([{
             id: generateId(),
             targetAmount: legacyGoal,
             startDate: new Date().toISOString(),
             isAchieved: false,
             notes: 'Initial Goal'
           }]);
        }

        setIsDataLoaded(true);
        setTimeout(() => setIsLoading(false), 500); // Small delay for UX transition
    };

    // Use requestAnimationFrame to ensure we don't block main thread if data is huge
    requestAnimationFrame(loadData);

  }, [activePortfolioId]);

  // --- PERSISTENCE: Save Data on Change ---
  useEffect(() => {
    if (!isDataLoaded) return;
    localStorage.setItem(`transactions_${activePortfolioId}`, JSON.stringify(transactions));
  }, [transactions, activePortfolioId, isDataLoaded]);

  useEffect(() => {
    if (!isDataLoaded) return;
    localStorage.setItem(`prices_${activePortfolioId}`, JSON.stringify(prices));
  }, [prices, activePortfolioId, isDataLoaded]);

  useEffect(() => {
    if (!isDataLoaded) return;
    localStorage.setItem(`goals_${activePortfolioId}`, JSON.stringify(goals));
  }, [goals, activePortfolioId, isDataLoaded]);


  // --- CALCULATIONS ---
  const holdings = useMemo(() => calculateHoldings(transactions, prices), [transactions, prices]);
  const chartData = useMemo(() => calculatePortfolioHistory(transactions, prices), [transactions, prices]);

  const investedAmount = transactions.reduce((sum, t) => {
    if (t.type === TransactionType.DEPOSIT) return sum + (t.price || 0);
    if (t.type === TransactionType.WITHDRAW) return sum - (t.price || 0);
    return sum;
  }, 0);

  const cashBalance = useMemo(() => {
    let balance = 0;
    transactions.forEach(t => {
      if (t.type === TransactionType.DEPOSIT) balance += (t.price || 0);
      if (t.type === TransactionType.WITHDRAW) balance -= (t.price || 0);
      if (t.type === TransactionType.BUY) balance -= (t.price! * t.shares!) + (t.fee || 0);
      if (t.type === TransactionType.SELL) balance += (t.price! * t.shares!) - (t.fee || 0);
      if (t.type === TransactionType.DIVIDEND) balance += (t.price || 0);
    });
    return balance;
  }, [transactions]);

  const portfolioValue = holdings.reduce((sum, h) => sum + h.marketValue, 0);
  const totalNetWorth = portfolioValue + cashBalance;

  // Active Goal Logic
  const activeGoal = useMemo(() => {
    return goals.find(g => !g.endDate) || { targetAmount: 100000 } as FinancialGoal;
  }, [goals]);

  // --- HANDLERS ---
  const handleOpenAddModal = () => {
    setEditingTransaction(null);
    setIsAddModalOpen(true);
  };

  const handleOpenEditModal = (tx: Transaction) => {
    setEditingTransaction(tx);
    setIsAddModalOpen(true);
  };

  const handleSaveTransaction = (tx: Transaction) => {
    // Optimistic Update
    return new Promise<void>((resolve) => {
      if (editingTransaction) {
        setTransactions(prev => prev.map(t => t.id === tx.id ? tx : t));
      } else {
        setTransactions(prev => [...prev, tx]);
      }

      if ((tx.type === TransactionType.BUY || tx.type === TransactionType.SELL) && tx.symbol && tx.price) {
          setPrices(prev => ({...prev, [tx.symbol!]: tx.price!}));
      }

      setIsAddModalOpen(false);
      setEditingTransaction(null);
      resolve();
    });
  };

  const handleUpdatePrice = (symbol: string, newPrice: number) => {
    setPrices(prev => ({ ...prev, [symbol]: newPrice }));
  };

  const handleDeleteTransaction = (id: string) => {
    setTransactions(prev => prev.filter(t => t.id !== id));
    if (editingTransaction && editingTransaction.id === id) {
       setIsAddModalOpen(false);
       setEditingTransaction(null);
    }
  };

  const handleRequestDelete = (id: string) => {
      setConfirmConfig({
          isOpen: true,
          title: 'Delete Transaction',
          message: 'Are you sure you want to delete this transaction? This action cannot be undone.',
          onConfirm: () => {
              handleDeleteTransaction(id);
              setConfirmConfig(prev => ({ ...prev, isOpen: false }));
          }
      });
  };

  const handleImportTransactions = (importedTxs: Transaction[]) => {
      // Merge logic: Update if exists, Add if not
      setTransactions(prev => {
          const currentMap = new Map(prev.map(t => [t.id, t]));
          importedTxs.forEach(t => {
              currentMap.set(t.id, t);
          });
          return Array.from(currentMap.values());
      });
      alert(`Imported ${importedTxs.length} transactions successfully.`);
  };

  // Portfolio Management Handlers
  const handleCreatePortfolio = (name: string) => {
    const newId = generateId();
    const newPortfolio = { id: newId, name };
    setPortfolios([...portfolios, newPortfolio]);
    setActivePortfolioId(newId);
  };

  const handleRenamePortfolio = (id: string, newName: string) => {
    setPortfolios(prev => prev.map(p => p.id === id ? { ...p, name: newName } : p));
  };

  const handleDeletePortfolio = (id: string) => {
    if (portfolios.length <= 1) {
      alert("You must have at least one portfolio.");
      return;
    }
    setConfirmConfig({
        isOpen: true,
        title: 'Delete Portfolio',
        message: 'Are you sure you want to delete this entire portfolio? All transactions within it will be permanently lost.',
        onConfirm: () => {
             localStorage.removeItem(`transactions_${id}`);
             localStorage.removeItem(`prices_${id}`);
             localStorage.removeItem(`goals_${id}`);
             localStorage.removeItem(`financialGoal_${id}`);

             const newPortfolios = portfolios.filter(p => p.id !== id);
             setPortfolios(newPortfolios);

             if (activePortfolioId === id) {
               setActivePortfolioId(newPortfolios[0].id);
             }
             setConfirmConfig(prev => ({ ...prev, isOpen: false }));
        }
    });
  };

  // Goals Handler
  const handleSetNewGoal = (targetAmount: number, notes: string) => {
    const now = new Date().toISOString();

    setGoals(prev => {
      const updatedGoals = prev.map(g => {
        // If there's an active goal, end it.
        if (!g.endDate) {
           const achieved = totalNetWorth >= g.targetAmount;
           return { ...g, endDate: now, isAchieved: achieved };
        }
        return g;
      });

      const newGoal: FinancialGoal = {
        id: generateId(),
        targetAmount,
        startDate: now,
        isAchieved: false,
        notes
      };

      return [...updatedGoals, newGoal];
    });
  };

  const handleEditGoal = (updatedGoal: FinancialGoal) => {
      setGoals(prev => prev.map(g => g.id === updatedGoal.id ? updatedGoal : g));
  };

  const handleDeleteGoal = (id: string) => {
      setGoals(prev => prev.filter(g => g.id !== id));
  };

  return (
    <Layout 
      activeTab={activeTab} 
      setActiveTab={setActiveTab} 
      onOpenAddModal={handleOpenAddModal}
      portfolios={portfolios}
      activePortfolioId={activePortfolioId}
      onSwitchPortfolio={setActivePortfolioId}
      onCreatePortfolio={handleCreatePortfolio}
      onRenamePortfolio={handleRenamePortfolio}
      onDeletePortfolio={handleDeletePortfolio}
    >
      <div key={activePortfolioId} className="h-full">
        {activeTab === 'dashboard' && (
          <Dashboard 
            isLoading={isLoading}
            holdings={holdings} 
            transactions={transactions} 
            financialGoal={activeGoal.targetAmount}
            onOpenGoalModal={() => setIsGoalModalOpen(true)}
            investedAmount={investedAmount}
            cashBalance={cashBalance}
            portfolioValue={portfolioValue}
            chartData={chartData}
          />
        )}
        {activeTab === 'holdings' && (
          <Holdings 
            isLoading={isLoading}
            holdings={holdings} 
            transactions={transactions} 
            onUpdatePrice={handleUpdatePrice} 
          />
        )}
        {activeTab === 'history' && (
          <History 
            isLoading={isLoading}
            transactions={transactions} 
            onDelete={handleRequestDelete}
            onEdit={handleOpenEditModal}
            onAdd={handleOpenAddModal}
            onImport={handleImportTransactions}
          />
        )}
        {activeTab === 'reports' && (
           <Reports 
             isLoading={isLoading}
             transactions={transactions} 
             currentPortfolioValue={portfolioValue + cashBalance} 
             chartData={chartData} 
           />
        )}
      </div>

      {isAddModalOpen && (
        <div className="fixed inset-0 z-50 flex items-end sm:items-center justify-center sm:p-4">
          <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-sm animate-fade-in" onClick={() => setIsAddModalOpen(false)}></div>
          <div className="relative bg-white dark:bg-slate-900 w-full max-w-lg 
                          rounded-t-3xl sm:rounded-3xl border border-slate-200 dark:border-slate-800 
                          shadow-2xl overflow-hidden animate-slide-up flex flex-col
                          max-h-[90dvh] sm:max-h-[85vh]">
            <AddTransactionForm 
              onClose={() => setIsAddModalOpen(false)} 
              onSave={handleSaveTransaction} 
              onDelete={handleRequestDelete}
              cashBalance={cashBalance}
              holdings={holdings}
              prices={prices}
              transactions={transactions}
              initialData={editingTransaction}
            />
          </div>
        </div>
      )}

      <GoalModal 
        isOpen={isGoalModalOpen}
        onClose={() => setIsGoalModalOpen(false)}
        goals={goals}
        currentNetWorth={totalNetWorth}
        onSetGoal={handleSetNewGoal}
        onEditGoal={handleEditGoal}
        onDeleteGoal={handleDeleteGoal}
      />

      {confirmConfig.isOpen && (
        <div className="fixed inset-0 z-[70] flex items-center justify-center p-4 animate-fade-in">
          <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-sm" onClick={() => setConfirmConfig(prev => ({ ...prev, isOpen: false }))}></div>
          <div className="relative bg-white dark:bg-slate-900 rounded-2xl shadow-2xl w-full max-w-sm overflow-hidden animate-zoom-in border border-slate-200 dark:border-slate-700">
            <div className="p-6">
              <div className="w-12 h-12 rounded-full bg-rose-100 dark:bg-rose-900/30 flex items-center justify-center text-rose-600 dark:text-rose-400 mb-4 mx-auto">
                 <Trash2 size={24} />
              </div>
              <h3 className="text-lg font-bold font-display text-slate-900 dark:text-white mb-2 text-center">{confirmConfig.title}</h3>
              <p className="text-sm text-slate-500 dark:text-slate-400 mb-6 text-center">{confirmConfig.message}</p>
              <div className="flex space-x-3">
                <button 
                  onClick={() => setConfirmConfig(prev => ({ ...prev, isOpen: false }))} 
                  className="flex-1 py-3 rounded-xl font-bold text-slate-600 dark:text-slate-400 hover:bg-slate-100 dark:hover:bg-slate-800 transition-colors"
                >
                  Cancel
                </button>
                <button 
                  onClick={confirmConfig.onConfirm} 
                  className="flex-1 py-3 rounded-xl font-bold bg-rose-600 text-white hover:bg-rose-700 transition-colors shadow-lg shadow-rose-600/20"
                >
                  Delete
                </button>
              </div>
            </div>
          </div>
        </div>
      )}
    </Layout>
  );
};

interface AddTransactionFormProps {
  onClose: () => void;
  onSave: (t: Transaction) => Promise<void>;
  onDelete?: (id: string) => void;
  cashBalance: number;
  holdings: Holding[];
  prices: Record<string, number>;
  transactions: Transaction[];
  initialData: Transaction | null;
}

const AddTransactionForm: React.FC<AddTransactionFormProps> = ({ onClose, onSave, onDelete, cashBalance, holdings, prices, transactions, initialData }) => {
  const [type, setType] = useState<TransactionType>(TransactionType.BUY);
  const [date, setDate] = useState(new Date().toISOString().split('T')[0]);
  const [symbol, setSymbol] = useState('');

  // Advanced Input State
  const [shares, setShares] = useState('');
  const [price, setPrice] = useState(''); // Price per share
  const [totalAmount, setTotalAmount] = useState(''); // Total transaction value

  const [fee, setFee] = useState('');
  const [assetClass, setAssetClass] = useState<AssetClass>(AssetClass.STOCK);
  const [exchangeRate, setExchangeRate] = useState(''); 
  const [notes, setNotes] = useState('');
  const [error, setError] = useState<string | null>(null);
  const [isSaving, setIsSaving] = useState(false);

  // Auto-Calc Lock (prevent circular updates)
  const [activeInput, setActiveInput] = useState<'shares' | 'price' | 'total' | null>(null);

  // Autocomplete State
  const [showSuggestions, setShowSuggestions] = useState(false);
  const wrapperRef = useRef<HTMLDivElement>(null);

  // Close suggestions on outside click
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (wrapperRef.current && !wrapperRef.current.contains(event.target as Node)) {
        setShowSuggestions(false);
      }
    };
    document.addEventListener("mousedown", handleClickOutside);
    return () => document.removeEventListener("mousedown", handleClickOutside);
  }, []);

  // Helper to block negative inputs
  const blockInvalidChar = (e: React.KeyboardEvent<HTMLInputElement>) => {
    if (['-', '+', 'e', 'E'].includes(e.key)) {
      e.preventDefault();
    }
  };

  useEffect(() => {
    if (initialData) {
      setType(initialData.type);
      setDate(initialData.date);
      setSymbol(initialData.symbol || '');
      setShares(initialData.shares?.toString() || '');
      setPrice(initialData.price?.toString() || '');
      setFee(initialData.fee?.toString() || '');
      setAssetClass(initialData.assetClass || AssetClass.STOCK);
      setExchangeRate(initialData.exchangeRate?.toString() || '');
      setNotes(initialData.notes || '');

      // Init Total Amount
      if (initialData.shares && initialData.price && (initialData.type === TransactionType.BUY || initialData.type === TransactionType.SELL)) {
         setTotalAmount((initialData.shares * initialData.price).toFixed(2));
      } else if (initialData.price) {
         setTotalAmount(initialData.price.toString());
      }
    }
  }, [initialData]);

  // --- SMART AUTO-FILL ---
  // When symbol changes, try to fetch last price and asset class
  useEffect(() => {
    if (!initialData && symbol && !price && !activeInput) {
       const upperSymbol = symbol.toUpperCase();

       // 1. Try to find in current holdings first (most accurate for asset class)
       const holding = holdings.find(h => h.symbol === upperSymbol);
       if (holding) {
          setAssetClass(holding.assetClass);
          if (holding.currentPrice > 0) {
             setPrice(holding.currentPrice.toString());
          }
       } else {
          // 2. Try to find in known prices history
          const knownPrice = prices[upperSymbol];
          if (knownPrice) {
             setPrice(knownPrice.toString());
          }
       }
    }
  }, [symbol, initialData, holdings, prices, activeInput, price]);


  // --- AUTO CALCULATION LOGIC ---
  useEffect(() => {
    const s = parseFloat(shares) || 0;
    const p = parseFloat(price) || 0;
    const t = parseFloat(totalAmount) || 0;

    // 1. If User edits Shares or Price -> Update Total
    if (activeInput === 'shares' || activeInput === 'price') {
       if (s > 0 && p > 0) {
         setTotalAmount((s * p).toFixed(2));
       } else if (s === 0 || p === 0) {
          // Don't clear total immediately if one is missing, acts weird
       }
    }

    // 2. If User edits Total -> Update Shares (if Price exists)
    if (activeInput === 'total') {
       if (t > 0 && p > 0) {
          setShares((t / p).toFixed(4)); // 4 decimals for shares
       }
    }
  }, [shares, price, totalAmount, activeInput]);

  const needsSymbol = [TransactionType.BUY, TransactionType.SELL, TransactionType.DIVIDEND, TransactionType.SPLIT].includes(type);
  const needsShares = [TransactionType.BUY, TransactionType.SELL, TransactionType.SPLIT].includes(type);
  const needsPrice = type !== TransactionType.SPLIT;
  const isFunding = type === TransactionType.DEPOSIT || type === TransactionType.WITHDRAW;

  // Validation Vars
  const numShares = parseFloat(shares) || 0;
  const numPrice = parseFloat(price) || 0;
  const numFee = parseFloat(fee) || 0;

  // Derived Total (re-calculate for validation integrity)
  const calcTotal = (type === TransactionType.SPLIT) ? 0 : (needsShares ? numShares * numPrice : numPrice);

  let netAmount = 0;
  if (type === TransactionType.BUY) netAmount = -(calcTotal + numFee);
  else if (type === TransactionType.SELL) netAmount = (calcTotal - numFee);
  else if (type === TransactionType.DIVIDEND) netAmount = calcTotal;
  else if (type === TransactionType.DEPOSIT) netAmount = calcTotal;
  else if (type === TransactionType.WITHDRAW) netAmount = -calcTotal;

  // --- VALIDATION EFFECTS ---
  useEffect(() => {
    setError(null);
    if (needsShares && numShares < 0) { setError("Shares cannot be negative."); return; }
    if (needsPrice && numPrice < 0) { setError("Price cannot be negative."); return; }
    if (numFee < 0) { setError("Fee cannot be negative."); return; }

    // Duplicate Check
    const isDuplicate = transactions.some(t => {
      if (initialData && t.id === initialData.id) return false;
      return (
        t.date === date && t.type === type && (t.symbol || '') === (symbol.toUpperCase() || '') &&
        (t.shares || 0) === numShares && (t.price || 0) === numPrice
      );
    });
    if (isDuplicate) { setError("Duplicate transaction detected."); return; }

    // Sell Validation
    if (type === TransactionType.SELL && symbol) {
      const holding = holdings.find(h => h.symbol === symbol.toUpperCase());
      let available = holding ? holding.shares : 0;
      if (initialData && initialData.type === TransactionType.SELL && initialData.symbol === symbol.toUpperCase()) {
         available += (initialData.shares || 0);
      }
      if (numShares > available + 0.00001) {
         setError(`Insufficient shares. Owned: ${formatNumber(available, 4)}`);
         return;
      }
    }

    // Cash Validation
    if (type === TransactionType.BUY || type === TransactionType.WITHDRAW) {
       let available = cashBalance;
       if (initialData) {
         // Logic to reverse old tx impact on cash (simplified)
         if (initialData.type === TransactionType.BUY) available += ((initialData.shares||0)*(initialData.price||0)) + (initialData.fee||0);
         else if (initialData.type === TransactionType.WITHDRAW) available += (initialData.price||0);
         else if (initialData.type === TransactionType.DEPOSIT) available -= (initialData.price||0);
         else if (initialData.type === TransactionType.SELL) available -= ((initialData.shares||0)*(initialData.price||0)) - (initialData.fee||0);
         else if (initialData.type === TransactionType.DIVIDEND) available -= (initialData.price||0);
       }
       if (Math.abs(netAmount) > available + 0.01) {
         setError(`Insufficient funds. Available: ${formatCurrency(available)}`);
         return;
       }
    }
  }, [type, calcTotal, cashBalance, numShares, numPrice, numFee, initialData, transactions, date, symbol, holdings, netAmount]);

  let projectedCash = cashBalance;
  if (initialData) {
     let oldImpact = 0;
     // Simplified reversal logic
     if (initialData.type === TransactionType.BUY) oldImpact = -(((initialData.shares||0)*(initialData.price||0)) + (initialData.fee||0));
     else if (initialData.type === TransactionType.SELL) oldImpact = ((initialData.shares||0)*(initialData.price||0)) - (initialData.fee||0);
     else if (initialData.type === TransactionType.DEPOSIT) oldImpact = (initialData.price||0);
     else if (initialData.type === TransactionType.WITHDRAW) oldImpact = -(initialData.price||0);
     else if (initialData.type === TransactionType.DIVIDEND) oldImpact = (initialData.price||0);
     projectedCash = (cashBalance - oldImpact) + netAmount;
  } else {
     projectedCash = cashBalance + netAmount;
  }

  const handleQuickAdd = (h: Holding) => {
    setSymbol(h.symbol);
    setAssetClass(h.assetClass);
    if(h.currentPrice) setPrice(h.currentPrice.toString());
  };

  // Date Shortcuts
  const setDateToday = () => setDate(new Date().toISOString().split('T')[0]);
  const setDateYesterday = () => {
    const d = new Date();
    d.setDate(d.getDate() - 1);
    setDate(d.toISOString().split('T')[0]);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (error) return;
    // needsPrice is defined as type !== SPLIT. isFunding is included in that set.
    if (needsPrice && calcTotal === 0) {
      setError("Value must be > 0");
      return;
    }
    if (needsSymbol && !symbol) {
      setError("Symbol required");
      return;
    }

    setIsSaving(true);
    await onSave({
      id: initialData ? initialData.id : generateId(),
      date, type,
      symbol: (needsSymbol) ? symbol.toUpperCase() : undefined,
      shares: needsShares ? parseFloat(shares) : undefined,
      price: type === TransactionType.SPLIT ? 0 : parseFloat(price),
      fee: (fee && (type === TransactionType.BUY || type === TransactionType.SELL)) ? parseFloat(fee) : undefined,
      assetClass: (!needsSymbol) ? AssetClass.CASH : assetClass,
      exchangeRate: exchangeRate ? parseFloat(exchangeRate) : 1, 
      notes: notes ? notes : undefined
    });
    setIsSaving(false);
  };

  // Top Holdings for Quick Add
  const quickHoldings = useMemo(() => {
     return [...holdings].sort((a,b) => b.marketValue - a.marketValue).slice(0, 4);
  }, [holdings]);

  // Autocomplete Suggestions
  const suggestions = useMemo(() => {
    if (!symbol || symbol.length < 1) return [];

    const inputUpper = symbol.toUpperCase();

    // Combine existing holdings symbols with popular list (Set for uniqueness)
    const holdingSymbols = holdings.map(h => h.symbol);
    const combined = Array.from(new Set([...holdingSymbols, ...POPULAR_SYMBOLS]));

    return combined
        .filter(s => s.includes(inputUpper))
        .sort((a, b) => {
           // Prioritize startsWith matches
           const aStarts = a.startsWith(inputUpper);
           const bStarts = b.startsWith(inputUpper);
           if (aStarts && !bStarts) return -1;
           if (!aStarts && bStarts) return 1;
           return a.localeCompare(b);
        })
        .slice(0, 6); // Limit to top 6
  }, [symbol, holdings]);

  const selectSuggestion = (s: string) => {
    setSymbol(s);
    setShowSuggestions(false);
  };

  // Dynamic Header Color based on Type
  const getHeaderColor = () => {
    switch (type) {
      case TransactionType.BUY: return 'bg-blue-50 dark:bg-blue-900/20 border-blue-100 dark:border-blue-800';
      case TransactionType.DEPOSIT: return 'bg-blue-50 dark:bg-blue-900/20 border-blue-100 dark:border-blue-800';
      case TransactionType.SELL: return 'bg-rose-50 dark:bg-rose-900/20 border-rose-100 dark:border-rose-800';
      case TransactionType.WITHDRAW: return 'bg-orange-50 dark:bg-orange-900/20 border-orange-100 dark:border-orange-800';
      case TransactionType.DIVIDEND: return 'bg-emerald-50 dark:bg-emerald-900/20 border-emerald-100 dark:border-emerald-800';
      default: return 'bg-slate-50/50 dark:bg-slate-900/50 border-slate-100 dark:border-slate-800';
    }
  };

  return (
    <>
      <div className={`shrink-0 flex justify-between items-center p-4 border-b transition-colors duration-300 ${getHeaderColor()}`}>
        <div>
          <h3 className="text-lg font-display font-bold text-slate-900 dark:text-white">
            {initialData ? 'Edit Transaction' : 'New Transaction'}
          </h3>
          <p className="text-xs text-slate-500">{initialData ? 'Update details' : 'Record your investment activity'}</p>
        </div>
        <button onClick={onClose} className="p-2 rounded-full hover:bg-slate-200 dark:hover:bg-slate-800 text-slate-400 hover:text-slate-600 dark:hover:text-slate-200 transition-colors">
          <X size={20} />
        </button>
      </div>

      <form onSubmit={handleSubmit} className="flex-1 overflow-y-auto min-h-0 p-4 space-y-5 custom-scrollbar">

        {/* Type Selector */}
        <div>
           <div className="grid grid-cols-3 sm:grid-cols-6 gap-2">
              {[
                { id: TransactionType.BUY, icon: <TrendingUp size={14} />, label: 'Buy', color: 'blue' },
                { id: TransactionType.SELL, icon: <TrendingDown size={14} />, label: 'Sell', color: 'rose' },
                { id: TransactionType.DIVIDEND, icon: <DollarSign size={14} />, label: 'Div', color: 'emerald' },
                { id: TransactionType.SPLIT, icon: <GitFork size={14} />, label: 'Split', color: 'purple' },
                { id: TransactionType.DEPOSIT, icon: <Wallet size={14} />, label: 'In', color: 'indigo' },
                { id: TransactionType.WITHDRAW, icon: <Wallet size={14} />, label: 'Out', color: 'orange' },
              ].map((t) => (
                <button
                  key={t.id}
                  type="button"
                  onClick={() => setType(t.id)}
                  className={`flex flex-col items-center justify-center p-2 rounded-lg border transition-all duration-200 ${
                    type === t.id
                      ? `bg-${t.color}-50 border-${t.color}-500 text-${t.color}-700 dark:bg-${t.color}-900/30 dark:border-${t.color}-500 dark:text-${t.color}-300 ring-1 ring-${t.color}-500 shadow-sm`
                      : 'bg-white dark:bg-slate-800 border-slate-200 dark:border-slate-700 text-slate-500 hover:border-slate-300 dark:hover:border-slate-600'
                  }`}
                >
                  <div className="mb-0.5">{t.icon}</div>
                  <span className="text-[10px] font-bold">{t.label}</span>
                </button>
              ))}
           </div>
        </div>

        {/* Date with Shortcuts */}
        <div>
           <div className="flex items-center gap-2 mb-1.5">
             <label className="text-[10px] font-bold text-slate-500 uppercase tracking-wider">Date</label>
             <div className="flex gap-1 ml-auto">
                <button type="button" onClick={setDateYesterday} className="text-[10px] px-2 py-0.5 bg-slate-100 dark:bg-slate-800 rounded hover:bg-slate-200 dark:hover:bg-slate-700 text-slate-600 dark:text-slate-400">Yesterday</button>
                <button type="button" onClick={setDateToday} className="text-[10px] px-2 py-0.5 bg-blue-50 dark:bg-blue-900/20 rounded hover:bg-blue-100 dark:hover:bg-blue-900/40 text-blue-600 dark:text-blue-400 font-medium">Today</button>
             </div>
           </div>
           <div className="relative">
             <Calendar className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={16} />
             <input 
              type="date" 
              required
              value={date}
              onChange={(e) => setDate(e.target.value)}
              className="w-full pl-9 pr-3 py-2.5 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl text-slate-900 dark:text-white focus:ring-2 focus:ring-blue-500 outline-none transition-all font-medium text-sm"
            />
           </div>
        </div>

        {needsSymbol && (
          <div className="space-y-2" ref={wrapperRef}>
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
              <div className="col-span-1 relative">
                 <label className="block text-[10px] font-bold text-slate-500 uppercase tracking-wider mb-1.5">Symbol</label>
                 <div className="relative">
                   <input 
                    type="text" 
                    required
                    placeholder="AAPL"
                    value={symbol}
                    onChange={(e) => {
                      setSymbol(e.target.value);
                      setShowSuggestions(true);
                    }}
                    onFocus={() => setShowSuggestions(true)}
                    className="w-full px-3 py-2.5 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl text-slate-900 dark:text-white focus:ring-2 focus:ring-blue-500 outline-none uppercase font-bold tracking-wide text-sm"
                   />
                   {/* Autocomplete Dropdown */}
                   {showSuggestions && suggestions.length > 0 && (
                      <ul className="absolute z-50 left-0 right-0 mt-1 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl shadow-xl overflow-hidden animate-slide-up">
                        {suggestions.map((s, idx) => (
                           <li 
                             key={s}
                             onMouseDown={(e) => {
                               // Use onMouseDown to prevent blur from firing before click
                               e.preventDefault(); 
                               selectSuggestion(s);
                             }}
                             className={`px-4 py-2 hover:bg-slate-50 dark:hover:bg-slate-700 cursor-pointer text-sm font-bold text-slate-700 dark:text-slate-200 flex items-center justify-between ${idx !== suggestions.length -1 ? 'border-b border-slate-100 dark:border-slate-700/50' : ''}`}
                           >
                             <span>{s}</span>
                             {holdings.some(h => h.symbol === s) && (
                                <span className="text-[10px] font-normal text-slate-400 bg-slate-100 dark:bg-slate-900 px-1.5 py-0.5 rounded">Owned</span>
                             )}
                           </li>
                        ))}
                      </ul>
                   )}
                 </div>
              </div>
               <div className="col-span-1">
                <label className="block text-[10px] font-bold text-slate-500 uppercase tracking-wider mb-1.5">Class</label>
                <select 
                  value={assetClass} 
                  onChange={(e) => setAssetClass(e.target.value as AssetClass)}
                  className="w-full px-3 py-2.5 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl text-slate-900 dark:text-white focus:ring-2 focus:ring-blue-500 outline-none appearance-none text-sm"
                >
                  {Object.values(AssetClass).filter(a => a !== AssetClass.CASH).map(a => <option key={a} value={a}>{a}</option>)}
                </select>
              </div>
            </div>
            {/* Quick Add Chips */}
            {!initialData && quickHoldings.length > 0 && (
               <div className="flex items-center space-x-2 overflow-x-auto pb-1 no-scrollbar">
                  <Zap size={12} className="text-amber-500 shrink-0" />
                  {quickHoldings.map(h => (
                     <button
                       key={h.symbol}
                       type="button"
                       onClick={() => handleQuickAdd(h)}
                       className="px-2 py-1 bg-slate-100 dark:bg-slate-800 hover:bg-blue-50 dark:hover:bg-blue-900/30 text-xs font-medium text-slate-600 dark:text-slate-300 rounded-md transition-colors border border-transparent hover:border-blue-200 dark:hover:border-blue-800 whitespace-nowrap"
                     >
                       {h.symbol}
                     </button>
                  ))}
               </div>
            )}
          </div>
        )}

        <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
           {needsShares && (
            <div className={type === TransactionType.SPLIT ? "col-span-1 sm:col-span-2" : "col-span-1"}>
              <label className="block text-[10px] font-bold text-slate-500 uppercase tracking-wider mb-1.5">
                {type === TransactionType.SPLIT ? "Split Ratio (e.g. 2 for 2:1)" : "Shares"}
              </label>
              <input 
                type="number" 
                step="any"
                min="0"
                required
                onKeyDown={blockInvalidChar}
                placeholder={type === TransactionType.SPLIT ? "2" : "0.00"}
                value={shares}
                onFocus={() => setActiveInput('shares')}
                onChange={(e) => setShares(e.target.value)}
                className="w-full px-3 py-2.5 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl text-slate-900 dark:text-white focus:ring-2 focus:ring-blue-500 outline-none font-mono text-sm"
              />
            </div>
           )}
           {needsPrice && (
             <div className={!needsShares ? "col-span-1 sm:col-span-2" : ""}>
               <label className="block text-[10px] font-bold text-slate-500 uppercase tracking-wider mb-1.5">
                 {needsShares ? "Price / Share" : "Amount ($)"}
               </label>
                <div className="relative">
                  <input 
                    type="number" 
                    step="any"
                    min="0"
                    required
                    onKeyDown={blockInvalidChar}
                    placeholder="0.00"
                    value={price}
                    onFocus={() => setActiveInput('price')}
                    onChange={(e) => setPrice(e.target.value)}
                    className="w-full px-3 py-2.5 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl text-slate-900 dark:text-white focus:ring-2 focus:ring-blue-500 outline-none font-mono text-sm"
                  />
                </div>
             </div>
           )}
        </div>

        {/* Total Amount Calculator Field */}
        {needsShares && needsPrice && (
           <div className="bg-blue-50/50 dark:bg-slate-800/50 p-3 rounded-xl border border-blue-100 dark:border-slate-700/50 flex flex-col sm:flex-row items-start sm:items-center justify-between gap-2">
              <div className="flex items-center space-x-2 text-slate-500 w-full sm:w-auto">
                 <Calculator size={14} />
                 <span className="text-xs font-bold uppercase">Total Amount</span>
              </div>
              <div className="flex items-center space-x-2 w-full sm:w-1/2">
                 <span className="text-slate-400">$</span>
                 <input 
                   type="number"
                   step="any"
                   min="0"
                   onKeyDown={blockInvalidChar}
                   value={totalAmount}
                   onFocus={() => setActiveInput('total')}
                   onChange={(e) => setTotalAmount(e.target.value)}
                   placeholder="0.00"
                   className="w-full bg-transparent border-b border-slate-300 dark:border-slate-600 focus:border-blue-500 outline-none text-right font-mono font-bold text-slate-900 dark:text-white"
                 />
              </div>
           </div>
        )}

        {(type === TransactionType.BUY || type === TransactionType.SELL) && (
           <div>
              <label className="block text-[10px] font-bold text-slate-500 uppercase tracking-wider mb-1.5">
                Fee (Optional)
              </label>
              <input 
                type="number" 
                step="any"
                min="0"
                onKeyDown={blockInvalidChar}
                placeholder="0.00"
                value={fee}
                onChange={(e) => setFee(e.target.value)}
                className="w-full px-3 py-2.5 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl text-slate-900 dark:text-white focus:ring-2 focus:ring-blue-500 outline-none font-mono text-sm"
              />
           </div>
        )}

        {isFunding && (
           <div className="bg-blue-50 dark:bg-slate-800/50 p-3 rounded-xl border border-blue-100 dark:border-slate-700">
             <label className="block text-[10px] font-bold text-slate-500 uppercase tracking-wider mb-1.5">
               Exchange Rate (Optional)
             </label>
              <div className="flex items-center space-x-2">
                <input 
                  type="number" 
                  step="any"
                  min="0"
                  onKeyDown={blockInvalidChar}
                  placeholder="1.00"
                  value={exchangeRate}
                  onChange={(e) => setExchangeRate(e.target.value)}
                  className="flex-1 px-3 py-2 bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-600 rounded-lg text-slate-900 dark:text-white focus:ring-2 focus:ring-blue-500 outline-none font-mono text-right text-sm"
                />
                <span className="text-xs font-medium text-slate-500">Local / USD</span>
              </div>
           </div>
        )}

        <div>
           <label className="block text-[10px] font-bold text-slate-500 uppercase tracking-wider mb-1.5">Notes (Optional)</label>
           <textarea
             rows={2}
             placeholder="Add a memo..."
             value={notes}
             onChange={(e) => setNotes(e.target.value)}
             className="w-full px-3 py-2.5 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl text-slate-900 dark:text-white focus:ring-2 focus:ring-blue-500 outline-none resize-none font-medium text-sm"
           />
        </div>
      </form>

      <div className="shrink-0 bg-white dark:bg-slate-900 border-t border-slate-100 dark:border-slate-800 p-4 shadow-[0_-4px_6px_-1px_rgba(0,0,0,0.05)] z-10">
         <div className="flex flex-col space-y-3 mb-4">
               {/* Main Details */}
               <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-3">
                   <div className="w-full sm:w-auto flex justify-between sm:block">
                      <p className="text-xs text-slate-500 dark:text-slate-400 font-medium uppercase tracking-wider mb-0.5">Net Amount</p>
                      <div className="flex items-baseline space-x-2">
                         <span className={`text-2xl font-bold font-display ${
                             netAmount > 0 ? 'text-emerald-600 dark:text-emerald-400' : 
                             netAmount < 0 ? 'text-slate-900 dark:text-white' : 'text-slate-500'
                         }`}>
                            {netAmount > 0 ? '+' : ''}{formatCurrency(netAmount)}
                         </span>
                      </div>
                   </div>
                   <div className="text-left sm:text-right w-full sm:w-auto flex flex-row sm:flex-col justify-between sm:justify-start items-center sm:items-end">
                      <p className="text-xs text-slate-500 dark:text-slate-400 font-medium uppercase tracking-wider mb-0.5">Cash Balance</p>
                      <div className="flex items-center justify-end space-x-2 text-sm">
                         <span className="text-slate-400 line-through decoration-slate-300 dark:decoration-slate-600">{formatCurrency(cashBalance)}</span>
                         <ArrowRight size={14} className="text-slate-300" />
                         <span className={`font-bold ${projectedCash < 0 ? 'text-rose-500' : 'text-slate-700 dark:text-slate-300'}`}>
                            {formatCurrency(projectedCash)}
                         </span>
                      </div>
                   </div>
               </div>
         </div>

         {error && (
           <div className="bg-rose-50 dark:bg-rose-900/20 border border-rose-200 dark:border-rose-800 rounded-xl p-3 mb-4 flex items-start space-x-3 text-rose-600 dark:text-rose-400 animate-slide-up">
               <AlertCircle size={18} className="shrink-0 mt-0.5" />
               <div className="text-sm font-semibold">{error}</div>
           </div>
         )}

          <div className="flex gap-3">
            {initialData && onDelete && (
               <button
                 type="button"
                 onClick={() => onDelete(initialData.id)}
                 className="px-4 py-3 rounded-xl font-bold bg-rose-50 text-rose-500 hover:bg-rose-100 dark:bg-rose-900/20 dark:text-rose-400 transition-colors"
               >
                 <Trash2 size={20} />
               </button>
            )}

            <button 
              onClick={handleSubmit}
              disabled={!!error || isSaving}
              className={`flex-1 font-bold py-3 rounded-xl shadow-lg transition-all flex items-center justify-center space-x-2 text-base ${
                error || isSaving
                  ? 'bg-slate-300 dark:bg-slate-700 text-slate-500 cursor-not-allowed' 
                  : 'bg-slate-900 dark:bg-blue-600 hover:opacity-90 text-white shadow-slate-900/20 dark:shadow-blue-600/20 active:scale-95'
              }`}
            >
              {isSaving ? (
                <Spinner className="text-white" />
              ) : (
                <>
                  <Save size={18} />
                  <span>{initialData ? 'Update Transaction' : 'Save Transaction'}</span>
                </>
              )}
            </button>
          </div>
      </div>
    </>
  );
};

export default App;

import React, { useMemo, useState } from 'react';
import { Holding, Transaction, ChartDataPoint, AssetClass } from '../types';
import { formatCurrency, formatNumber } from '../utils';
import { 
  AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, 
  PieChart, Pie, Cell, Brush
} from 'recharts';
import { ArrowUpRight, ArrowDownRight, TrendingUp, Wallet, Target, Activity, ChevronLeft, PieChart as PieChartIcon, ZoomIn, Star } from 'lucide-react';
import { DashboardSkeleton } from './LoadingSkeletons';

interface DashboardProps {
  holdings: Holding[];
  transactions: Transaction[];
  financialGoal: number;
  setFinancialGoal?: (val: number) => void; // Optional/Deprecated
  onOpenGoalModal: () => void;
  investedAmount: number;
  cashBalance: number;
  portfolioValue: number;
  chartData: ChartDataPoint[];
  isLoading?: boolean;
}

const COLORS = ['#3b82f6', '#10b981', '#f59e0b', '#ef4444', '#8b5cf6', '#ec4899', '#6366f1', '#14b8a6'];

const Dashboard: React.FC<DashboardProps> = ({ 
  holdings, transactions, financialGoal, onOpenGoalModal, investedAmount, portfolioValue, cashBalance, chartData, isLoading 
}) => {
  const [selectedCategory, setSelectedCategory] = useState<string | null>(null);

  const totalNetWorth = portfolioValue + cashBalance;
  const totalUnrealizedPL = holdings.reduce((sum, h) => sum + h.unrealizedPL, 0);
  const totalPLPercent = investedAmount > 0 ? (totalUnrealizedPL / investedAmount) * 100 : 0;

  // Find Top Performer
  const topPerformer = useMemo(() => {
     if (holdings.length === 0) return null;
     const winners = [...holdings].sort((a,b) => b.unrealizedPL - a.unrealizedPL);
     return winners[0].unrealizedPL > 0 ? winners[0] : null;
  }, [holdings]);

  // 1. Prepare Main Allocation Data (By Category)
  const categoryData = useMemo(() => {
    return holdings
      .filter(h => h.marketValue > 0)
      .map(h => ({ name: h.assetClass, value: h.marketValue }))
      .reduce((acc: any[], curr) => {
        const existing = acc.find(item => item.name === curr.name);
        if (existing) {
          existing.value += curr.value;
        } else {
          acc.push({ ...curr });
        }
        return acc;
      }, [])
      .sort((a, b) => b.value - a.value);
  }, [holdings]);

  // 2. Prepare Drill-down Data (Assets within selected Category)
  const assetData = useMemo(() => {
    if (!selectedCategory) return [];
    return holdings
      .filter(h => h.assetClass === selectedCategory && h.marketValue > 0)
      .map(h => ({ name: h.symbol, value: h.marketValue, fullName: h.name }))
      .sort((a, b) => b.value - a.value);
  }, [holdings, selectedCategory]);

  // Determine which data to show
  const activeChartData = selectedCategory ? assetData : categoryData;

  // Determine the denominator for percentage calculation
  // If viewing main: Denom is Portfolio Value.
  // If viewing category: Denom is Total Value of that Category.
  const activeTotalValue = selectedCategory 
    ? assetData.reduce((sum, item) => sum + item.value, 0)
    : portfolioValue;

  // --- CAGR / PERFORMANCE CALCULATION ---
  const performanceMetric = useMemo(() => {
    if (investedAmount <= 0 || transactions.length === 0) {
      return { label: 'Total Return', value: 0 };
    }

    // Find first transaction date
    let minDate = new Date().getTime();
    let hasTx = false;

    transactions.forEach(t => {
       const txDate = new Date(t.date).getTime();
       if (txDate < minDate) {
         minDate = txDate;
         hasTx = true;
       }
    });

    if (!hasTx) return { label: 'Total Return', value: 0 };

    const now = new Date().getTime();
    const daysElapsed = (now - minDate) / (1000 * 60 * 60 * 24);
    const years = daysElapsed / 365.25;

    // If invested less than 1 year, show Absolute Return instead of CAGR to avoid crazy annualized numbers
    if (years < 1) {
       const absReturn = ((totalNetWorth - investedAmount) / investedAmount) * 100;
       return { label: 'Total Return (Abs)', value: absReturn };
    } else {
       // CAGR Formula: (End Value / Start Value)^(1/n) - 1
       // We use InvestedAmount as the proxy for Start Value (Principal)
       if (totalNetWorth <= 0) return { label: 'Annual Growth (CAGR)', value: -100 };

       const cagr = (Math.pow(totalNetWorth / investedAmount, 1 / years) - 1) * 100;
       return { label: 'Annual Growth (CAGR)', value: cagr };
    }
  }, [transactions, investedAmount, totalNetWorth]);

  if (isLoading) {
    return <DashboardSkeleton />;
  }

  return (
