        <div className="relative overflow-hidden rounded-2xl p-6 group animate-slide-up bg-slate-900 text-white shadow-xl shadow-slate-900/20" style={{ animationDelay: '0ms' }}>
          {/* Subtle gradient background */}
          <div className="absolute inset-0 bg-gradient-to-br from-slate-800 to-slate-950 opacity-100"></div>
          <div className="absolute top-0 right-0 w-32 h-32 bg-blue-500 rounded-full blur-[60px] opacity-20 group-hover:opacity-30 transition-opacity"></div>

          <div className="relative z-10 flex flex-col justify-between h-full">
            <div className="flex justify-between items-start">
               <div>
                  <p className="text-sm font-medium text-slate-300">Net Worth</p>
                  <h3 className="text-3xl font-display font-bold tracking-tight mt-1">
                    {formatCurrency(totalNetWorth)}
