  const [confirmConfig, setConfirmConfig] = useState<{
    isOpen: boolean;
    title: string;
    message: string;
    onConfirm: () => void;
  }>({
    isOpen: false,
    title: '',
    message: '',
    onConfirm: () => {},
  });

  // --- PORTFOLIO MANAGEMENT STATE ---
  const [portfolios, setPortfolios] = useState<Portfolio[]>(() => {
    const saved = localStorage.getItem('portfolios');
    if (saved) return JSON.parse(saved);

    // Migration: If no portfolios exist but we have legacy transactions, create a default one
    const legacyTx = localStorage.getItem('transactions');
    if (legacyTx) {
      return [{ id: 'default', name: 'Main Portfolio' }];
    }

    return [{ id: generateId(), name: 'My First Portfolio' }];
  });

  const [activePortfolioId, setActivePortfolioId] = useState<string>(() => {
    const saved = localStorage.getItem('activePortfolioId');
    const portfolios = JSON.parse(localStorage.getItem('portfolios') || '[]');
    if (saved && portfolios.some((p: Portfolio) => p.id === saved)) return saved;
    return portfolios.length > 0 ? portfolios[0].id : 'default';
  });

  // --- DATA STATE (Per Portfolio) - Synchronous Initialization ---

  const [transactions, setTransactions] = useState<Transaction[]>(() => {
    const key = `transactions_${activePortfolioId}`;
    const saved = localStorage.getItem(key);
    if (saved) return JSON.parse(saved);

    // Legacy fallback
    if (activePortfolioId === 'default') {
      const legacy = localStorage.getItem('transactions');
      if (legacy) return JSON.parse(legacy);
    }
    return [];
  });

  const [prices, setPrices] = useState<Record<string, number>>(() => {
    const key = `prices_${activePortfolioId}`;
    const saved = localStorage.getItem(key);
    if (saved) return JSON.parse(saved);

    // Legacy fallback
    if (activePortfolioId === 'default') {
      const legacy = localStorage.getItem('prices');
      if (legacy) return JSON.parse(legacy);
    }
    return {};
  });

  const [goals, setGoals] = useState<FinancialGoal[]>(() => {
    const key = `goals_${activePortfolioId}`;
    const saved = localStorage.getItem(key);
    if (saved) return JSON.parse(saved);

    // Legacy fallback logic
    let legacyGoal = 100000;
    const legacyKey = `financialGoal_${activePortfolioId}`;
    const savedLegacy = localStorage.getItem(legacyKey);

    if (savedLegacy) {
      legacyGoal = parseFloat(savedLegacy);
    } else if (activePortfolioId === 'default') {
      const oldGlobal = localStorage.getItem('financialGoal');
      if (oldGlobal) legacyGoal = parseFloat(oldGlobal);
    }

    return [{
      id: generateId(),
      targetAmount: legacyGoal,
      startDate: new Date().toISOString(),
      isAchieved: false,
      notes: 'Initial Goal'
    }];
  });

  const [isDataLoaded, setIsDataLoaded] = useState(true); // Started true because we loaded synchronously
  const [isLoading, setIsLoading] = useState(false); // Started false, ready to render
  const isFirstMount = useRef(true);

  // --- PERSISTENCE: Portfolios List ---
  useEffect(() => {
    localStorage.setItem('portfolios', JSON.stringify(portfolios));
  }, [portfolios]);

  useEffect(() => {
    localStorage.setItem('activePortfolioId', activePortfolioId);
  }, [activePortfolioId]);

  // --- PERSISTENCE: Load Data on Portfolio Switch ONLY ---
  useEffect(() => {
    // Skip the first run because we already initialized state synchronously
    if (isFirstMount.current) {
      isFirstMount.current = false;
      return;
    }

    setIsLoading(true);
    setIsDataLoaded(false);

    const loadData = () => {
        const txKey = `transactions_${activePortfolioId}`;
        const pricesKey = `prices_${activePortfolioId}`;
        const goalsKey = `goals_${activePortfolioId}`;
        const legacyGoalKey = `financialGoal_${activePortfolioId}`;

        // Load Transactions
        const savedTx = localStorage.getItem(txKey);
        if (savedTx) {
          setTransactions(JSON.parse(savedTx));
        } else if (activePortfolioId === 'default' && localStorage.getItem('transactions')) {
          setTransactions(JSON.parse(localStorage.getItem('transactions')!));
        } else {
          setTransactions([]);
        }

        // Load Prices
        const savedPrices = localStorage.getItem(pricesKey);
        if (savedPrices) {
          setPrices(JSON.parse(savedPrices));
        } else if (activePortfolioId === 'default' && localStorage.getItem('prices')) {
          setPrices(JSON.parse(localStorage.getItem('prices')!));
        } else {
          setPrices({});
        }

        // Load Goals
        const savedGoals = localStorage.getItem(goalsKey);
        if (savedGoals) {
           setGoals(JSON.parse(savedGoals));
        } else {
           let legacyGoal = 100000;
           const savedLegacy = localStorage.getItem(legacyGoalKey);
           if (savedLegacy) {
             legacyGoal = parseFloat(savedLegacy);
           } else if (activePortfolioId === 'default' && localStorage.getItem('financialGoal')) {
             legacyGoal = parseFloat(localStorage.getItem('financialGoal')!);
           }

           setGoals([{
             id: generateId(),
             targetAmount: legacyGoal,
             startDate: new Date().toISOString(),
             isAchieved: false,
             notes: 'Initial Goal'
           }]);
        }

        setIsDataLoaded(true);
        setTimeout(() => setIsLoading(false), 500); // Small delay for UX transition
    };

    // Use requestAnimationFrame to ensure we don't block main thread if data is huge
    requestAnimationFrame(loadData);

  }, [activePortfolioId]);

  // --- PERSISTENCE: Save Data on Change ---
  useEffect(() => {
    if (!isDataLoaded) return;
    localStorage.setItem(`transactions_${activePortfolioId}`, JSON.stringify(transactions));
  }, [transactions, activePortfolioId, isDataLoaded]);

  useEffect(() => {
    if (!isDataLoaded) return;
    localStorage.setItem(`prices_${activePortfolioId}`, JSON.stringify(prices));
  }, [prices, activePortfolioId, isDataLoaded]);

  useEffect(() => {
    if (!isDataLoaded) return;
    localStorage.setItem(`goals_${activePortfolioId}`, JSON.stringify(goals));
  }, [goals, activePortfolioId, isDataLoaded]);


  // --- CALCULATIONS ---
  const holdings = useMemo(() => calculateHoldings(transactions, prices), [transactions, prices]);
  const chartData = useMemo(() => calculatePortfolioHistory(transactions, prices), [transactions, prices]);

  const investedAmount = transactions.reduce((sum, t) => {
    if (t.type === TransactionType.DEPOSIT) return sum + (t.price || 0);
    if (t.type === TransactionType.WITHDRAW) return sum - (t.price || 0);
    return sum;
  }, 0);

  const cashBalance = useMemo(() => {
    let balance = 0;
    transactions.forEach(t => {
      if (t.type === TransactionType.DEPOSIT) balance += (t.price || 0);
      if (t.type === TransactionType.WITHDRAW) balance -= (t.price || 0);
      if (t.type === TransactionType.BUY) balance -= (t.price! * t.shares!) + (t.fee || 0);
      if (t.type === TransactionType.SELL) balance += (t.price! * t.shares!) - (t.fee || 0);
      if (t.type === TransactionType.DIVIDEND) balance += (t.price || 0);
    });
    return balance;
  }, [transactions]);

  const portfolioValue = holdings.reduce((sum, h) => sum + h.marketValue, 0);
  const totalNetWorth = portfolioValue + cashBalance;

  // Active Goal Logic
  const activeGoal = useMemo(() => {
    return goals.find(g => !g.endDate) || { targetAmount: 100000 } as FinancialGoal;
  }, [goals]);

  // --- HANDLERS ---
  const handleOpenAddModal = () => {
    setEditingTransaction(null);
    setIsAddModalOpen(true);
  };

  const handleOpenEditModal = (tx: Transaction) => {
    setEditingTransaction(tx);
    setIsAddModalOpen(true);
  };

  const handleSaveTransaction = (tx: Transaction) => {
    // Optimistic Update
    return new Promise<void>((resolve) => {
      if (editingTransaction) {
        setTransactions(prev => prev.map(t => t.id === tx.id ? tx : t));
      } else {
        setTransactions(prev => [...prev, tx]);
      }

      if ((tx.type === TransactionType.BUY || tx.type === TransactionType.SELL) && tx.symbol && tx.price) {
          setPrices(prev => ({...prev, [tx.symbol!]: tx.price!}));
      }

      setIsAddModalOpen(false);
      setEditingTransaction(null);
      resolve();
    });
  };

  const handleUpdatePrice = (symbol: string, newPrice: number) => {
    setPrices(prev => ({ ...prev, [symbol]: newPrice }));
  };

  const handleDeleteTransaction = (id: string) => {
    setTransactions(prev => prev.filter(t => t.id !== id));
    if (editingTransaction && editingTransaction.id === id) {
       setIsAddModalOpen(false);
       setEditingTransaction(null);
    }
  };

  const handleRequestDelete = (id: string) => {
      setConfirmConfig({
          isOpen: true,
          title: 'Delete Transaction',
          message: 'Are you sure you want to delete this transaction? This action cannot be undone.',
          onConfirm: () => {
              handleDeleteTransaction(id);
              setConfirmConfig(prev => ({ ...prev, isOpen: false }));
          }
      });
  };

  const handleImportTransactions = (importedTxs: Transaction[]) => {
      // Merge logic: Update if exists, Add if not
      setTransactions(prev => {
          const currentMap = new Map(prev.map(t => [t.id, t]));
          importedTxs.forEach(t => {
              currentMap.set(t.id, t);
          });
          return Array.from(currentMap.values());
      });
      alert(`Imported ${importedTxs.length} transactions successfully.`);
  };

  // Portfolio Management Handlers
  const handleCreatePortfolio = (name: string) => {
    const newId = generateId();
    const newPortfolio = { id: newId, name };
    setPortfolios([...portfolios, newPortfolio]);
    setActivePortfolioId(newId);
  };

  const handleRenamePortfolio = (id: string, newName: string) => {
    setPortfolios(prev => prev.map(p => p.id === id ? { ...p, name: newName } : p));
  };

  const handleDeletePortfolio = (id: string) => {
    if (portfolios.length <= 1) {
      alert("You must have at least one portfolio.");
      return;
    }
    setConfirmConfig({
        isOpen: true,
        title: 'Delete Portfolio',
        message: 'Are you sure you want to delete this entire portfolio? All transactions within it will be permanently lost.',
        onConfirm: () => {
             localStorage.removeItem(`transactions_${id}`);
             localStorage.removeItem(`prices_${id}`);
             localStorage.removeItem(`goals_${id}`);
             localStorage.removeItem(`financialGoal_${id}`);

             const newPortfolios = portfolios.filter(p => p.id !== id);
             setPortfolios(newPortfolios);

             if (activePortfolioId === id) {
               setActivePortfolioId(newPortfolios[0].id);
             }
             setConfirmConfig(prev => ({ ...prev, isOpen: false }));
        }
    });
  };

  // Goals Handler
  const handleSetNewGoal = (targetAmount: number, notes: string) => {
    const now = new Date().toISOString();

    setGoals(prev => {
      const updatedGoals = prev.map(g => {
        // If there's an active goal, end it.
        if (!g.endDate) {
           const achieved = totalNetWorth >= g.targetAmount;
           return { ...g, endDate: now, isAchieved: achieved };
        }
        return g;
      });

      const newGoal: FinancialGoal = {
        id: generateId(),
        targetAmount,
        startDate: now,
        isAchieved: false,
        notes
      };

      return [...updatedGoals, newGoal];
    });
  };

  const handleEditGoal = (updatedGoal: FinancialGoal) => {
      setGoals(prev => prev.map(g => g.id === updatedGoal.id ? updatedGoal : g));
  };

  const handleDeleteGoal = (id: string) => {
      setGoals(prev => prev.filter(g => g.id !== id));
  };

  return (
    <Layout 
      activeTab={activeTab} 
      setActiveTab={setActiveTab} 
      onOpenAddModal={handleOpenAddModal}
      portfolios={portfolios}
      activePortfolioId={activePortfolioId}
      onSwitchPortfolio={setActivePortfolioId}
      onCreatePortfolio={handleCreatePortfolio}
      onRenamePortfolio={handleRenamePortfolio}
      onDeletePortfolio={handleDeletePortfolio}
    >
      <div key={activePortfolioId} className="h-full">
        {activeTab === 'dashboard' && (
          <Dashboard 
            isLoading={isLoading}
            holdings={holdings} 
            transactions={transactions} 
            financialGoal={activeGoal.targetAmount}
            onOpenGoalModal={() => setIsGoalModalOpen(true)}
            investedAmount={investedAmount}
            cashBalance={cashBalance}
            portfolioValue={portfolioValue}
            chartData={chartData}
          />
        )}
        {activeTab === 'holdings' && (
          <Holdings 
            isLoading={isLoading}
            holdings={holdings} 
            transactions={transactions} 
            onUpdatePrice={handleUpdatePrice} 
          />
        )}
        {activeTab === 'history' && (
          <History 
            isLoading={isLoading}
            transactions={transactions} 
            onDelete={handleRequestDelete}
            onEdit={handleOpenEditModal}
            onAdd={handleOpenAddModal}
            onImport={handleImportTransactions}
          />
        )}
        {activeTab === 'reports' && (
           <Reports 
             isLoading={isLoading}
             transactions={transactions} 
             currentPortfolioValue={portfolioValue + cashBalance} 
             chartData={chartData} 
           />
        )}
      </div>

      {isAddModalOpen && (
        <div className="fixed inset-0 z-50 flex items-end sm:items-center justify-center sm:p-4">
          <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-sm animate-fade-in" onClick={() => setIsAddModalOpen(false)}></div>
          <div className="relative bg-white dark:bg-slate-900 w-full max-w-lg 
                          rounded-t-3xl sm:rounded-3xl border border-slate-200 dark:border-slate-800 
                          shadow-2xl overflow-hidden animate-slide-up flex flex-col
                          max-h-[90dvh] sm:max-h-[85vh]">
            <AddTransactionForm 
              onClose={() => setIsAddModalOpen(false)} 
              onSave={handleSaveTransaction} 
              onDelete={handleRequestDelete}
              cashBalance={cashBalance}
              holdings={holdings}
              prices={prices}
              transactions={transactions}
              initialData={editingTransaction}
            />
          </div>
        </div>
      )}

      <GoalModal 
        isOpen={isGoalModalOpen}
        onClose={() => setIsGoalModalOpen(false)}
        goals={goals}
        currentNetWorth={totalNetWorth}
        onSetGoal={handleSetNewGoal}
        onEditGoal={handleEditGoal}
        onDeleteGoal={handleDeleteGoal}
      />

      {confirmConfig.isOpen && (
        <div className="fixed inset-0 z-[70] flex items-center justify-center p-4 animate-fade-in">
          <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-sm" onClick={() => setConfirmConfig(prev => ({ ...prev, isOpen: false }))}></div>
          <div className="relative bg-white dark:bg-slate-900 rounded-2xl shadow-2xl w-full max-w-sm overflow-hidden animate-zoom-in border border-slate-200 dark:border-slate-700">
            <div className="p-6">
              <div className="w-12 h-12 rounded-full bg-rose-100 dark:bg-rose-900/30 flex items-center justify-center text-rose-600 dark:text-rose-400 mb-4 mx-auto">
                 <Trash2 size={24} />
              </div>
              <h3 className="text-lg font-bold font-display text-slate-900 dark:text-white mb-2 text-center">{confirmConfig.title}</h3>
              <p className="text-sm text-slate-500 dark:text-slate-400 mb-6 text-center">{confirmConfig.message}</p>
              <div className="flex space-x-3">
                <button 
                  onClick={() => setConfirmConfig(prev => ({ ...prev, isOpen: false }))} 
                  className="flex-1 py-3 rounded-xl font-bold text-slate-600 dark:text-slate-400 hover:bg-slate-100 dark:hover:bg-slate-800 transition-colors"
                >
                  Cancel
                </button>
                <button 
                  onClick={confirmConfig.onConfirm} 
                  className="flex-1 py-3 rounded-xl font-bold bg-rose-600 text-white hover:bg-rose-700 transition-colors shadow-lg shadow-rose-600/20"
                >
                  Delete
                </button>
              </div>
            </div>
          </div>
        </div>
      )}
    </Layout>
  );
};

interface AddTransactionFormProps {
  onClose: () => void;
  onSave: (t: Transaction) => Promise<void>;
  onDelete?: (id: string) => void;
  cashBalance: number;
  holdings: Holding[];
  prices: Record<string, number>;
  transactions: Transaction[];
  initialData: Transaction | null;
}

const AddTransactionForm: React.FC<AddTransactionFormProps> = ({ onClose, onSave, onDelete, cashBalance, holdings, prices, transactions, initialData }) => {
  const [type, setType] = useState<TransactionType>(TransactionType.BUY);
  const [date, setDate] = useState(new Date().toISOString().split('T')[0]);
  const [symbol, setSymbol] = useState('');

  // Advanced Input State
  const [shares, setShares] = useState('');
  const [price, setPrice] = useState(''); // Price per share
  const [totalAmount, setTotalAmount] = useState(''); // Total transaction value

  const [fee, setFee] = useState('');
  const [assetClass, setAssetClass] = useState<AssetClass>(AssetClass.STOCK);
  const [exchangeRate, setExchangeRate] = useState(''); 
  const [notes, setNotes] = useState('');
  const [error, setError] = useState<string | null>(null);
  const [isSaving, setIsSaving] = useState(false);

  // Auto-Calc Lock (prevent circular updates)
  const [activeInput, setActiveInput] = useState<'shares' | 'price' | 'total' | null>(null);

  // Autocomplete State
  const [showSuggestions, setShowSuggestions] = useState(false);
  const wrapperRef = useRef<HTMLDivElement>(null);

  // Close suggestions on outside click
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (wrapperRef.current && !wrapperRef.current.contains(event.target as Node)) {
        setShowSuggestions(false);
      }
    };
    document.addEventListener("mousedown", handleClickOutside);
    return () => document.removeEventListener("mousedown", handleClickOutside);
  }, []);

  // Helper to block negative inputs
  const blockInvalidChar = (e: React.KeyboardEvent<HTMLInputElement>) => {
    if (['-', '+', 'e', 'E'].includes(e.key)) {
      e.preventDefault();
    }
  };

  useEffect(() => {
    if (initialData) {
      setType(initialData.type);
      setDate(initialData.date);
      setSymbol(initialData.symbol || '');
      setShares(initialData.shares?.toString() || '');
      setPrice(initialData.price?.toString() || '');
      setFee(initialData.fee?.toString() || '');
      setAssetClass(initialData.assetClass || AssetClass.STOCK);
      setExchangeRate(initialData.exchangeRate?.toString() || '');
      setNotes(initialData.notes || '');

      // Init Total Amount
      if (initialData.shares && initialData.price && (initialData.type === TransactionType.BUY || initialData.type === TransactionType.SELL)) {
         setTotalAmount((initialData.shares * initialData.price).toFixed(2));
      } else if (initialData.price) {
         setTotalAmount(initialData.price.toString());
      }
    }
  }, [initialData]);

  // --- SMART AUTO-FILL ---
  // When symbol changes, try to fetch last price and asset class
  useEffect(() => {
    if (!initialData && symbol && !price && !activeInput) {
       const upperSymbol = symbol.toUpperCase();

       // 1. Try to find in current holdings first (most accurate for asset class)
       const holding = holdings.find(h => h.symbol === upperSymbol);
       if (holding) {
          setAssetClass(holding.assetClass);
          if (holding.currentPrice > 0) {
             setPrice(holding.currentPrice.toString());
          }
       } else {
          // 2. Try to find in known prices history
          const knownPrice = prices[upperSymbol];
          if (knownPrice) {
             setPrice(knownPrice.toString());
          }
       }
    }
  }, [symbol, initialData, holdings, prices, activeInput, price]);


  // --- AUTO CALCULATION LOGIC ---
  useEffect(() => {
    const s = parseFloat(shares) || 0;
    const p = parseFloat(price) || 0;
    const t = parseFloat(totalAmount) || 0;

    // 1. If User edits Shares or Price -> Update Total
    if (activeInput === 'shares' || activeInput === 'price') {
       if (s > 0 && p > 0) {
         setTotalAmount((s * p).toFixed(2));
       } else if (s === 0 || p === 0) {
          // Don't clear total immediately if one is missing, acts weird
       }
    }

    // 2. If User edits Total -> Update Shares (if Price exists)
    if (activeInput === 'total') {
       if (t > 0 && p > 0) {
          setShares((t / p).toFixed(4)); // 4 decimals for shares
       }
    }
  }, [shares, price, totalAmount, activeInput]);

  const needsSymbol = [TransactionType.BUY, TransactionType.SELL, TransactionType.DIVIDEND, TransactionType.SPLIT].includes(type);
  const needsShares = [TransactionType.BUY, TransactionType.SELL, TransactionType.SPLIT].includes(type);
  const needsPrice = type !== TransactionType.SPLIT;
  const isFunding = type === TransactionType.DEPOSIT || type === TransactionType.WITHDRAW;

  // Validation Vars
  const numShares = parseFloat(shares) || 0;
  const numPrice = parseFloat(price) || 0;
  const numFee = parseFloat(fee) || 0;

  // Derived Total (re-calculate for validation integrity)
  const calcTotal = (type === TransactionType.SPLIT) ? 0 : (needsShares ? numShares * numPrice : numPrice);

  let netAmount = 0;
  if (type === TransactionType.BUY) netAmount = -(calcTotal + numFee);
  else if (type === TransactionType.SELL) netAmount = (calcTotal - numFee);
  else if (type === TransactionType.DIVIDEND) netAmount = calcTotal;
  else if (type === TransactionType.DEPOSIT) netAmount = calcTotal;
  else if (type === TransactionType.WITHDRAW) netAmount = -calcTotal;

  // --- VALIDATION EFFECTS ---
  useEffect(() => {
    setError(null);
    if (needsShares && numShares < 0) { setError("Shares cannot be negative."); return; }
    if (needsPrice && numPrice < 0) { setError("Price cannot be negative."); return; }
    if (numFee < 0) { setError("Fee cannot be negative."); return; }

    // Duplicate Check
    const isDuplicate = transactions.some(t => {
      if (initialData && t.id === initialData.id) return false;
      return (
        t.date === date && t.type === type && (t.symbol || '') === (symbol.toUpperCase() || '') &&
        (t.shares || 0) === numShares && (t.price || 0) === numPrice
      );
    });
    if (isDuplicate) { setError("Duplicate transaction detected."); return; }

    // Sell Validation
    if (type === TransactionType.SELL && symbol) {
      const holding = holdings.find(h => h.symbol === symbol.toUpperCase());
      let available = holding ? holding.shares : 0;
      if (initialData && initialData.type === TransactionType.SELL && initialData.symbol === symbol.toUpperCase()) {
         available += (initialData.shares || 0);
      }
      if (numShares > available + 0.00001) {
         setError(`Insufficient shares. Owned: ${formatNumber(available, 4)}`);
         return;
      }
    }

    // Cash Validation
    if (type === TransactionType.BUY || type === TransactionType.WITHDRAW) {
       let available = cashBalance;
       if (initialData) {
         // Logic to reverse old tx impact on cash (simplified)
         if (initialData.type === TransactionType.BUY) available += ((initialData.shares||0)*(initialData.price||0)) + (initialData.fee||0);
         else if (initialData.type === TransactionType.WITHDRAW) available += (initialData.price||0);
         else if (initialData.type === TransactionType.DEPOSIT) available -= (initialData.price||0);
         else if (initialData.type === TransactionType.SELL) available -= ((initialData.shares||0)*(initialData.price||0)) - (initialData.fee||0);
         else if (initialData.type === TransactionType.DIVIDEND) available -= (initialData.price||0);
       }
       if (Math.abs(netAmount) > available + 0.01) {
         setError(`Insufficient funds. Available: ${formatCurrency(available)}`);
         return;
       }
    }
  }, [type, calcTotal, cashBalance, numShares, numPrice, numFee, initialData, transactions, date, symbol, holdings, netAmount]);

  let projectedCash = cashBalance;
  if (initialData) {
     let oldImpact = 0;
     // Simplified reversal logic
     if (initialData.type === TransactionType.BUY) oldImpact = -(((initialData.shares||0)*(initialData.price||0)) + (initialData.fee||0));
     else if (initialData.type === TransactionType.SELL) oldImpact = ((initialData.shares||0)*(initialData.price||0)) - (initialData.fee||0);
     else if (initialData.type === TransactionType.DEPOSIT) oldImpact = (initialData.price||0);
     else if (initialData.type === TransactionType.WITHDRAW) oldImpact = -(initialData.price||0);
     else if (initialData.type === TransactionType.DIVIDEND) oldImpact = (initialData.price||0);
     projectedCash = (cashBalance - oldImpact) + netAmount;
  } else {
     projectedCash = cashBalance + netAmount;
  }

  const handleQuickAdd = (h: Holding) => {
    setSymbol(h.symbol);
    setAssetClass(h.assetClass);
    if(h.currentPrice) setPrice(h.currentPrice.toString());
  };

  // Date Shortcuts
  const setDateToday = () => setDate(new Date().toISOString().split('T')[0]);
  const setDateYesterday = () => {
    const d = new Date();
    d.setDate(d.getDate() - 1);
    setDate(d.toISOString().split('T')[0]);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (error) return;
    // needsPrice is defined as type !== SPLIT. isFunding is included in that set.
    if (needsPrice && calcTotal === 0) {
      setError("Value must be > 0");
      return;
    }
    if (needsSymbol && !symbol) {
      setError("Symbol required");
      return;
    }

    setIsSaving(true);
    await onSave({
      id: initialData ? initialData.id : generateId(),
      date, type,
      symbol: (needsSymbol) ? symbol.toUpperCase() : undefined,
      shares: needsShares ? parseFloat(shares) : undefined,
      price: type === TransactionType.SPLIT ? 0 : parseFloat(price),
      fee: (fee && (type === TransactionType.BUY || type === TransactionType.SELL)) ? parseFloat(fee) : undefined,
      assetClass: (!needsSymbol) ? AssetClass.CASH : assetClass,
      exchangeRate: exchangeRate ? parseFloat(exchangeRate) : 1, 
      notes: notes ? notes : undefined
    });
    setIsSaving(false);
  };

  // Top Holdings for Quick Add
  const quickHoldings = useMemo(() => {
     return [...holdings].sort((a,b) => b.marketValue - a.marketValue).slice(0, 4);
  }, [holdings]);

  // Autocomplete Suggestions
  const suggestions = useMemo(() => {
    if (!symbol || symbol.length < 1) return [];

    const inputUpper = symbol.toUpperCase();

    // Combine existing holdings symbols with popular list (Set for uniqueness)
    const holdingSymbols = holdings.map(h => h.symbol);
    const combined = Array.from(new Set([...holdingSymbols, ...POPULAR_SYMBOLS]));

    return combined
        .filter(s => s.includes(inputUpper))
        .sort((a, b) => {
           // Prioritize startsWith matches
           const aStarts = a.startsWith(inputUpper);
           const bStarts = b.startsWith(inputUpper);
           if (aStarts && !bStarts) return -1;
           if (!aStarts && bStarts) return 1;
           return a.localeCompare(b);
        })
        .slice(0, 6); // Limit to top 6
  }, [symbol, holdings]);

  const selectSuggestion = (s: string) => {
    setSymbol(s);
    setShowSuggestions(false);
  };

  // Dynamic Header Color based on Type
  const getHeaderColor = () => {
    switch (type) {
      case TransactionType.BUY: return 'bg-blue-50 dark:bg-blue-900/20 border-blue-100 dark:border-blue-800';
      case TransactionType.DEPOSIT: return 'bg-blue-50 dark:bg-blue-900/20 border-blue-100 dark:border-blue-800';
      case TransactionType.SELL: return 'bg-rose-50 dark:bg-rose-900/20 border-rose-100 dark:border-rose-800';
      case TransactionType.WITHDRAW: return 'bg-orange-50 dark:bg-orange-900/20 border-orange-100 dark:border-orange-800';
      case TransactionType.DIVIDEND: return 'bg-emerald-50 dark:bg-emerald-900/20 border-emerald-100 dark:border-emerald-800';
      default: return 'bg-slate-50/50 dark:bg-slate-900/50 border-slate-100 dark:border-slate-800';
    }
  };

  return (
    <>
      <div className={`shrink-0 flex justify-between items-center p-4 border-b transition-colors duration-300 ${getHeaderColor()}`}>
        <div>
          <h3 className="text-lg font-display font-bold text-slate-900 dark:text-white">
            {initialData ? 'Edit Transaction' : 'New Transaction'}
          </h3>
