           />
        </div>
      </form>

      <div className="shrink-0 bg-white dark:bg-slate-900 border-t border-slate-100 dark:border-slate-800 p-4 shadow-[0_-4px_6px_-1px_rgba(0,0,0,0.05)] z-10">
         <div className="flex flex-col space-y-3 mb-4">
               {/* Main Details */}
               <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-3">
                   <div className="w-full sm:w-auto flex justify-between sm:block">
                      <p className="text-xs text-slate-500 dark:text-slate-400 font-medium uppercase tracking-wider mb-0.5">Net Amount</p>
                      <div className="flex items-baseline space-x-2">
                         <span className={`text-2xl font-bold font-display ${
                             netAmount > 0 ? 'text-emerald-600 dark:text-emerald-400' : 
                             netAmount < 0 ? 'text-slate-900 dark:text-white' : 'text-slate-500'
                         }`}>
                            {netAmount > 0 ? '+' : ''}{formatCurrency(netAmount)}
                         </span>
                      </div>
                   </div>
                   <div className="text-left sm:text-right w-full sm:w-auto flex flex-row sm:flex-col justify-between sm:justify-start items-center sm:items-end">
                      <p className="text-xs text-slate-500 dark:text-slate-400 font-medium uppercase tracking-wider mb-0.5">Cash Balance</p>
                      <div className="flex items-center justify-end space-x-2 text-sm">
                         <span className="text-slate-400 line-through decoration-slate-300 dark:decoration-slate-600">{formatCurrency(cashBalance)}</span>
                         <ArrowRight size={14} className="text-slate-300" />
                         <span className={`font-bold ${projectedCash < 0 ? 'text-rose-500' : 'text-slate-700 dark:text-slate-300'}`}>
                            {formatCurrency(projectedCash)}
                         </span>
                      </div>
                   </div>
               </div>
         </div>

         {error && (
           <div className="bg-rose-50 dark:bg-rose-900/20 border border-rose-200 dark:border-rose-800 rounded-xl p-3 mb-4 flex items-start space-x-3 text-rose-600 dark:text-rose-400 animate-slide-up">
               <AlertCircle size={18} className="shrink-0 mt-0.5" />
               <div className="text-sm font-semibold">{error}</div>
           </div>
         )}

          <div className="flex gap-3">
            {initialData && onDelete && (
               <button
                 type="button"
                 onClick={() => onDelete(initialData.id)}
                 className="px-4 py-3 rounded-xl font-bold bg-rose-50 text-rose-500 hover:bg-rose-100 dark:bg-rose-900/20 dark:text-rose-400 transition-colors"
               >
                 <Trash2 size={20} />
               </button>
            )}

            <button 
              onClick={handleSubmit}
              disabled={!!error || isSaving}
              className={`flex-1 font-bold py-3 rounded-xl shadow-lg transition-all flex items-center justify-center space-x-2 text-base ${
                error || isSaving
                  ? 'bg-slate-300 dark:bg-slate-700 text-slate-500 cursor-not-allowed' 
                  : 'bg-slate-900 dark:bg-blue-600 hover:opacity-90 text-white shadow-slate-900/20 dark:shadow-blue-600/20 active:scale-95'
              }`}
            >
              {isSaving ? (
                <Spinner className="text-white" />
              ) : (
                <>
                  <Save size={18} />
                  <span>{initialData ? 'Update Transaction' : 'Save Transaction'}</span>
                </>
              )}
            </button>
          </div>
      </div>
    </>
  );
};

export default App;

import React, { useState, useMemo } from 'react';
import { Transaction, TransactionType, ChartDataPoint } from '../types';
import { getYearlyDividends, getMonthlyDividends, calculateFundingStats, calculateMonthlyActivity, formatCurrency, formatNumber } from '../utils';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, AreaChart, Area, ComposedChart, Line, ReferenceLine, Cell } from 'recharts';
import { DollarSign, TrendingUp, TrendingDown, Calendar, ArrowUpRight, ArrowDownRight, RefreshCcw, Clock, ArrowRight, Minus, ChevronDown, ChevronRight, Wallet, GitFork, BarChart3, PieChart, Landmark } from 'lucide-react';
import { ReportsSkeleton } from './LoadingSkeletons';

interface ReportsProps {
  transactions: Transaction[];
  currentPortfolioValue: number;
  chartData: ChartDataPoint[];
  isLoading?: boolean;
}

const Reports: React.FC<ReportsProps> = ({ transactions, currentPortfolioValue, chartData, isLoading }) => {
  const [activeTab, setActiveTab] = useState<'monthly' | 'dividends' | 'funding' | 'growth'>('monthly');

  if (isLoading) {
    return <ReportsSkeleton />;
  }

  const tabs = [
    { id: 'monthly', label: 'Activity', icon: <BarChart3 size={16} /> },
    { id: 'dividends', label: 'Dividends', icon: <PieChart size={16} /> },
    { id: 'funding', label: 'Funding', icon: <Landmark size={16} /> },
    { id: 'growth', label: 'Growth', icon: <TrendingUp size={16} /> },
  ];

  return (
    <div className="space-y-8 animate-fade-in pb-10">

      {/* 1. Modern Segmented Control Header */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
           <h2 className="text-2xl font-display font-bold text-slate-900 dark:text-white">Portfolio Reports</h2>
           <p className="text-slate-500 dark:text-slate-400 text-sm">Deep dive into your investment performance</p>
        </div>

        <div className="bg-white dark:bg-slate-800 p-1.5 rounded-xl border border-slate-200 dark:border-slate-700 shadow-sm flex overflow-x-auto no-scrollbar">
          {tabs.map((tab) => (
            <button
              key={tab.id}
              onClick={() => setActiveTab(tab.id as any)}
              className={`flex items-center space-x-2 px-4 py-2 rounded-lg text-sm font-bold transition-all whitespace-nowrap ${
                activeTab === tab.id
                  ? 'bg-slate-900 text-white dark:bg-blue-600 shadow-md'
                  : 'text-slate-500 hover:text-slate-900 dark:text-slate-400 dark:hover:text-white hover:bg-slate-50 dark:hover:bg-slate-700'
              }`}
            >
              {tab.icon}
              <span>{tab.label}</span>
            </button>
          ))}
        </div>
      </div>

      {/* 2. Content Views */}
      <div className="min-h-[400px]">
         {activeTab === 'monthly' && <MonthlyActivityView transactions={transactions} />}
         {activeTab === 'dividends' && <DividendsView transactions={transactions} />}
         {activeTab === 'funding' && <FundingView transactions={transactions} currentPortfolioValue={currentPortfolioValue} />}
         {activeTab === 'growth' && <GrowthView transactions={transactions} currentPortfolioValue={currentPortfolioValue} chartData={chartData} />}
      </div>
    </div>
  );
};

// --- SUB-VIEWS ---

const MonthlyActivityView: React.FC<{ transactions: Transaction[] }> = ({ transactions }) => {
  const [range, setRange] = useState<number>(6); // Default 6 months
  const [expandedMonth, setExpandedMonth] = useState<string | null>(null);

  const monthlyData = useMemo(() => calculateMonthlyActivity(transactions), [transactions]);
  // Reverse for Chart (Oldest to Newest), Slice for display
  const chartData = [...monthlyData].reverse().slice(-range); 
  const displayData = range === 999 ? monthlyData : monthlyData.slice(0, range);

  // Stats
  const current = monthlyData[0] || { buyVolume: 0, dividendIncome: 0, yearMonth: 'N/A' };

  // Calculate average monthly investment over selected range
  const avgInvestment = displayData.reduce((sum, m) => sum + m.buyVolume, 0) / (displayData.length || 1);

  const toggleMonth = (ym: string) => {
    if (expandedMonth === ym) setExpandedMonth(null);
    else setExpandedMonth(ym);
  };

  const renderTransactionDetails = (yearMonth: string) => {
    const monthTxs = transactions.filter(t => t.date.startsWith(yearMonth))
                                 .sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());

    if (monthTxs.length === 0) return <div className="p-4 text-center text-sm text-slate-400 italic">No transactions found.</div>;

    return (
      <div className="bg-slate-50 dark:bg-slate-900/40 p-3 -mx-6 mt-4 border-t border-b border-slate-100 dark:border-slate-700 shadow-inner">
         <h4 className="text-[10px] font-bold uppercase text-slate-400 mb-2 px-1 tracking-wider">Transaction Log</h4>
         <div className="space-y-2">
            {monthTxs.map(tx => {
               const totalVal = (tx.type === TransactionType.BUY || tx.type === TransactionType.SELL) 
                                ? (tx.price || 0) * (tx.shares || 0) 
                                : (tx.price || 0);

               return (
                 <div key={tx.id} className="flex items-center justify-between p-2.5 bg-white dark:bg-slate-800 rounded-lg border border-slate-200 dark:border-slate-700 shadow-sm">
                    <div className="flex items-center gap-3">
                       <div className={`w-8 h-8 rounded-lg flex items-center justify-center shrink-0 ${
                          tx.type === TransactionType.BUY ? 'bg-blue-100 text-blue-600 dark:bg-blue-900/30 dark:text-blue-400' :
                          tx.type === TransactionType.SELL ? 'bg-rose-100 text-rose-600 dark:bg-rose-900/30 dark:text-rose-400' :
                          tx.type === TransactionType.DIVIDEND ? 'bg-emerald-100 text-emerald-600 dark:bg-emerald-900/30 dark:text-emerald-400' :
                          'bg-slate-100 text-slate-600 dark:bg-slate-800 dark:text-slate-400'
                       }`}>
                          {tx.type === TransactionType.BUY ? <TrendingUp size={14} /> :
                           tx.type === TransactionType.SELL ? <TrendingDown size={14} /> :
                           tx.type === TransactionType.DIVIDEND ? <DollarSign size={14} /> :
                           <Wallet size={14} />}
                       </div>
                       <div>
                          <div className="flex items-center gap-2">
                             <span className="font-bold text-sm text-slate-900 dark:text-white">{tx.symbol || (tx.type === 'DEPOSIT' || tx.type === 'WITHDRAW' ? 'Cash' : 'N/A')}</span>
                             <span className="text-[10px] font-medium text-slate-400 bg-slate-100 dark:bg-slate-700/50 px-1.5 rounded">{tx.type}</span>
                          </div>
                          <div className="text-xs text-slate-400">{new Date(tx.date).toLocaleDateString()}</div>
                       </div>
                    </div>
                    <div className="text-right">
                       <div className="font-mono text-sm font-medium text-slate-900 dark:text-white">
                          {tx.type === TransactionType.SPLIT ? '-' : formatCurrency(totalVal)}
                       </div>
                    </div>
                 </div>
               );
            })}
         </div>
      </div>
    );
  };

  return (
    <div className="space-y-6 animate-slide-up">
      {/* 1. Hero Metrics */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
          <div className="glass-card p-5 rounded-2xl border border-slate-200 dark:border-slate-700 relative overflow-hidden">
              <div className="absolute right-0 top-0 p-4 opacity-10"><Calendar size={60} /></div>
              <p className="text-xs font-bold text-slate-500 uppercase tracking-wider">This Month Invested</p>
              <h3 className="text-2xl font-bold text-slate-900 dark:text-white mt-1">{formatCurrency(current.buyVolume)}</h3>
          </div>

          <div className="glass-card p-5 rounded-2xl border border-slate-200 dark:border-slate-700 relative overflow-hidden">
              <div className="absolute right-0 top-0 p-4 opacity-10"><Wallet size={60} /></div>
              <p className="text-xs font-bold text-slate-500 uppercase tracking-wider">Avg. Monthly Invest</p>
              <h3 className="text-2xl font-bold text-blue-600 dark:text-blue-400 mt-1">{formatCurrency(avgInvestment)}</h3>
              <p className="text-[10px] text-slate-400 mt-1">Based on last {range === 999 ? 'all' : range} months</p>
          </div>

          <div className="glass-card p-5 rounded-2xl border border-slate-200 dark:border-slate-700 relative overflow-hidden flex flex-col justify-center items-end text-right">
             <div className="flex items-center gap-2 mb-2">
