import { ReportsSkeleton } from './LoadingSkeletons';

interface ReportsProps {
  transactions: Transaction[];
  currentPortfolioValue: number;
  chartData: ChartDataPoint[];
  isLoading?: boolean;
}

const Reports: React.FC<ReportsProps> = ({ transactions, currentPortfolioValue, chartData, isLoading }) => {
  const [activeTab, setActiveTab] = useState<'monthly' | 'dividends' | 'funding' | 'growth'>('monthly');

  if (isLoading) {
    return <ReportsSkeleton />;
  }

  const tabs = [
    { id: 'monthly', label: 'Monthly', icon: <Calendar size={16} /> },
    { id: 'dividends', label: 'Dividends', icon: <PieChart size={16} /> },
    { id: 'funding', label: 'Funding', icon: <Landmark size={16} /> },
    { id: 'growth', label: 'Growth', icon: <TrendingUp size={16} /> },
  ];

  return (
    <div className="space-y-8 animate-fade-in pb-10">

      {/* 1. Modern Segmented Control Header */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
           <h2 className="text-2xl font-display font-bold text-slate-900 dark:text-white">Portfolio Reports</h2>
           <p className="text-slate-500 dark:text-slate-400 text-sm">Deep dive into your investment performance</p>
        </div>

        <div className="bg-white dark:bg-slate-800 p-1.5 rounded-xl border border-slate-200 dark:border-slate-700 shadow-sm flex overflow-x-auto no-scrollbar">
          {tabs.map((tab) => (
            <button
              key={tab.id}
              onClick={() => setActiveTab(tab.id as any)}
              className={`flex items-center space-x-2 px-4 py-2 rounded-lg text-sm font-bold transition-all whitespace-nowrap ${
                activeTab === tab.id
                  ? 'bg-slate-900 text-white dark:bg-blue-600 shadow-md'
                  : 'text-slate-500 hover:text-slate-900 dark:text-slate-400 dark:hover:text-white hover:bg-slate-50 dark:hover:bg-slate-700'
              }`}
            >
              {tab.icon}
              <span>{tab.label}</span>
            </button>
          ))}
        </div>
      </div>

      {/* 2. Content Views */}
      <div className="min-h-[400px]">
         {activeTab === 'monthly' && <MonthlyActivityView transactions={transactions} />}
         {activeTab === 'dividends' && <DividendsView transactions={transactions} />}
         {activeTab === 'funding' && <FundingView transactions={transactions} currentPortfolioValue={currentPortfolioValue} />}
         {activeTab === 'growth' && <GrowthView transactions={transactions} currentPortfolioValue={currentPortfolioValue} chartData={chartData} />}
      </div>
    </div>
  );
};

