          </div>

          <div className="glass-card p-5 rounded-2xl border border-slate-200 dark:border-slate-700 relative overflow-hidden">
              <div className="absolute right-0 top-0 p-4 opacity-10"><Wallet size={60} /></div>
              <p className="text-xs font-bold text-slate-500 uppercase tracking-wider">Avg. Monthly Invest</p>
              <h3 className="text-2xl font-bold text-blue-600 dark:text-blue-400 mt-1">{formatCurrency(avgInvestment)}</h3>
              <p className="text-[10px] text-slate-400 mt-1">Based on last {range === 999 ? 'all' : range} months</p>
          </div>

          <div className="glass-card p-5 rounded-2xl border border-slate-200 dark:border-slate-700 relative overflow-hidden flex flex-col justify-center items-end text-right">
             <div className="flex items-center gap-2 mb-2">
                 <span className="text-xs font-bold text-slate-500">View Range:</span>
                 <div className="flex bg-slate-100 dark:bg-slate-700/50 p-1 rounded-lg">
                    {[6, 12, 999].map((val) => (
                      <button 
                        key={val}
                        onClick={() => setRange(val)}
                        className={`text-[10px] px-2 py-1 rounded font-bold transition-all ${range === val ? 'bg-white dark:bg-slate-600 shadow-sm text-slate-900 dark:text-white' : 'text-slate-400 hover:text-slate-600'}`}
