                 // Dividends (In) + Sold (In) - Bought (Out)
                 const netFlow = data.dividendIncome + data.sellVolume - data.buyVolume;
                 const isExpanded = expandedMonth === data.yearMonth;

                 return (
                   <React.Fragment key={data.yearMonth}>
                    <tr 
                      className={`hover:bg-slate-50 dark:hover:bg-slate-700/30 cursor-pointer transition-all ${isExpanded ? 'bg-slate-50 dark:bg-slate-800' : ''}`}
