  const [expandedMonth, setExpandedMonth] = useState<string | null>(null);

  // Data Calculation
  const monthlyData = useMemo(() => calculateMonthlyActivity(transactions), [transactions]);

  // Prepare data for display (Chart needs Oldest -> Newest)
  const displayData = range === 999 ? monthlyData : monthlyData.slice(0, range);
  const chartData = useMemo(() => {
     return [...displayData].reverse().map(d => ({
        ...d,
        netInvested: d.buyVolume - d.sellVolume // Net Accumulation
     }));
  }, [displayData]);

  // Insights Calculation
  const currentMonth = monthlyData[0] || { buyVolume: 0, sellVolume: 0, dividendIncome: 0, yearMonth: 'N/A' };
  const prevMonth = monthlyData[1] || { buyVolume: 0, sellVolume: 0, dividendIncome: 0 };

  // Calculate Average Investment (excluding 0 months to be fair)
  const activeMonths = monthlyData.filter(m => m.buyVolume > 0);
  const avgInvestment = activeMonths.length > 0 
    ? activeMonths.reduce((sum, m) => sum + (m.buyVolume - m.sellVolume), 0) / activeMonths.length 
    : 0;

  // Auto-expand latest month on mount if data exists
  useEffect(() => {
    if (monthlyData.length > 0 && !expandedMonth) {
      setExpandedMonth(monthlyData[0].yearMonth);
    }
  }, [monthlyData]);

  const toggleMonth = (ym: string) => {
    setExpandedMonth(expandedMonth === ym ? null : ym);
  };

  const calculateTrend = (current: number, previous: number) => {
     if (previous === 0) return current > 0 ? 100 : 0;
     return ((current - previous) / previous) * 100;
  };

  const buyTrend = calculateTrend(currentMonth.buyVolume, prevMonth.buyVolume);
  const divTrend = calculateTrend(currentMonth.dividendIncome, prevMonth.dividendIncome);

  // Render detail rows
  const renderTransactionDetails = (yearMonth: string) => {
    const monthTxs = transactions.filter(t => t.date.startsWith(yearMonth))
                                 .sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());

    if (monthTxs.length === 0) return <div className="p-4 text-center text-sm text-slate-400 italic">No transactions found.</div>;

    return (
      <div className="bg-slate-50 dark:bg-slate-900/40 p-3 rounded-xl border border-slate-200 dark:border-slate-700 shadow-inner mt-3">
         <div className="flex justify-between items-center mb-2 px-1">
            <h4 className="text-[10px] font-bold uppercase text-slate-400 tracking-wider">Transaction Log</h4>
            <span className="text-[10px] text-slate-400">{monthTxs.length} records</span>
         </div>
         <div className="space-y-2">
            {monthTxs.map(tx => {
               const totalVal = (tx.type === TransactionType.BUY || tx.type === TransactionType.SELL) 
                                ? (tx.price || 0) * (tx.shares || 0) 
                                : (tx.price || 0);

               return (
                 <div key={tx.id} className="flex items-center justify-between p-2.5 bg-white dark:bg-slate-800 rounded-lg border border-slate-200 dark:border-slate-700 shadow-sm">
                    <div className="flex items-center gap-3">
                       <div className={`w-8 h-8 rounded-lg flex items-center justify-center shrink-0 ${
                          tx.type === TransactionType.BUY ? 'bg-blue-100 text-blue-600 dark:bg-blue-900/30 dark:text-blue-400' :
                          tx.type === TransactionType.SELL ? 'bg-rose-100 text-rose-600 dark:bg-rose-900/30 dark:text-rose-400' :
                          tx.type === TransactionType.DIVIDEND ? 'bg-emerald-100 text-emerald-600 dark:bg-emerald-900/30 dark:text-emerald-400' :
                          'bg-slate-100 text-slate-600 dark:bg-slate-800 dark:text-slate-400'
                       }`}>
                          {tx.type === TransactionType.BUY ? <TrendingUp size={14} /> :
                           tx.type === TransactionType.SELL ? <TrendingDown size={14} /> :
                           tx.type === TransactionType.DIVIDEND ? <DollarSign size={14} /> :
                           <Wallet size={14} />}
                       </div>
                       <div>
                          <div className="flex items-center gap-2">
                             <span className="font-bold text-sm text-slate-900 dark:text-white">{tx.symbol || (tx.type === 'DEPOSIT' || tx.type === 'WITHDRAW' ? 'Cash' : 'N/A')}</span>
                             <span className={`text-[10px] font-bold px-1.5 rounded uppercase ${
                                 tx.type === TransactionType.BUY ? 'bg-blue-50 text-blue-600 dark:bg-blue-900/20' : 
                                 tx.type === TransactionType.SELL ? 'bg-rose-50 text-rose-600 dark:bg-rose-900/20' : 
                                 'bg-slate-100 text-slate-500 dark:bg-slate-700'
                             }`}>{tx.type}</span>
                          </div>
                          <div className="text-xs text-slate-400">{new Date(tx.date).toLocaleDateString()}</div>
                       </div>
                    </div>
                    <div className="text-right">
                       <div className="font-mono text-sm font-medium text-slate-900 dark:text-white">
                          {tx.type === TransactionType.SPLIT ? '-' : formatCurrency(totalVal)}
                       </div>
                    </div>
                 </div>
               );
            })}
         </div>
      </div>
    );
  };

  return (
    <div className="space-y-6 animate-slide-up">
      {/* 1. Meaningful Hero Metrics */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
          {/* Card 1: Activity Context */}
          <div className="glass-card p-5 rounded-2xl border border-slate-200 dark:border-slate-700 relative overflow-hidden flex flex-col justify-between h-full">
              <div className="absolute right-0 top-0 p-4 opacity-5"><TrendingUp size={80} /></div>
              <div>
                  <p className="text-xs font-bold text-slate-500 uppercase tracking-wider">Invested This Month</p>
                  <div className="flex items-baseline gap-2 mt-1">
                     <h3 className="text-2xl font-bold text-slate-900 dark:text-white">{formatCurrency(currentMonth.buyVolume)}</h3>
                  </div>
              </div>
              <div className="mt-4 flex items-center gap-2">
                 <span className={`flex items-center text-xs font-bold px-1.5 py-0.5 rounded ${buyTrend >= 0 ? 'bg-blue-50 text-blue-600 dark:bg-blue-900/20 dark:text-blue-400' : 'bg-slate-100 text-slate-500 dark:bg-slate-800'}`}>
                    {buyTrend >= 0 ? <ArrowUpRight size={12} className="mr-1"/> : <ArrowDownRight size={12} className="mr-1"/>}
                    {Math.abs(buyTrend).toFixed(0)}%
                 </span>
                 <span className="text-xs text-slate-400">vs last month</span>
              </div>
          </div>

          {/* Card 2: Passive Income */}
          <div className="glass-card p-5 rounded-2xl border border-slate-200 dark:border-slate-700 relative overflow-hidden flex flex-col justify-between h-full">
              <div className="absolute right-0 top-0 p-4 opacity-5"><DollarSign size={80} /></div>
              <div>
                  <p className="text-xs font-bold text-slate-500 uppercase tracking-wider">Passive Income (Mo)</p>
                  <div className="flex items-baseline gap-2 mt-1">
                     <h3 className="text-2xl font-bold text-emerald-600 dark:text-emerald-400">{formatCurrency(currentMonth.dividendIncome)}</h3>
                  </div>
              </div>
              <div className="mt-4 flex items-center gap-2">
                  {currentMonth.dividendIncome > 0 ? (
                    <>
                        <span className={`flex items-center text-xs font-bold px-1.5 py-0.5 rounded ${divTrend >= 0 ? 'bg-emerald-50 text-emerald-600 dark:bg-emerald-900/20 dark:text-emerald-400' : 'bg-rose-50 text-rose-600'}`}>
                            {divTrend >= 0 ? <ArrowUpRight size={12} className="mr-1"/> : <ArrowDownRight size={12} className="mr-1"/>}
                            {Math.abs(divTrend).toFixed(0)}%
                        </span>
                        <span className="text-xs text-slate-400">vs last month</span>
                    </>
                  ) : (
                    <span className="text-xs text-slate-400 italic">No dividends yet this month</span>
                  )}
              </div>
          </div>

          {/* Card 3: Consistency Context */}
          <div className="glass-card p-5 rounded-2xl border border-slate-200 dark:border-slate-700 relative overflow-hidden flex flex-col justify-between h-full">
             <div>
                <div className="flex justify-between items-start">
                    <p className="text-xs font-bold text-slate-500 uppercase tracking-wider">Average Consistency</p>
                    <Target size={16} className="text-slate-300"/>
                </div>
                <h3 className="text-2xl font-bold text-slate-700 dark:text-slate-300 mt-1">{formatCurrency(avgInvestment)}</h3>
                <p className="text-[10px] text-slate-400 mt-1">Avg. Net Invested (Buy - Sell)</p>
             </div>

             <div className="mt-4">
                 <div className="flex justify-between items-center text-xs mb-1">
                    <span className="text-slate-400">Range Control</span>
                    <span className="font-bold text-slate-600 dark:text-slate-300">{range === 999 ? 'Max' : `${range} Months`}</span>
                 </div>
                 <div className="flex bg-slate-100 dark:bg-slate-700/50 p-1 rounded-lg">
                    {[6, 12, 999].map((val) => (
                      <button 
                        key={val}
                        onClick={() => setRange(val)}
                        className={`flex-1 text-[10px] py-1 rounded font-bold transition-all ${range === val ? 'bg-white dark:bg-slate-600 shadow-sm text-slate-900 dark:text-white' : 'text-slate-400 hover:text-slate-600'}`}
                      >
                        {val === 999 ? 'ALL' : `${val}M`}
                      </button>
                    ))}
                 </div>
             </div>
          </div>
      </div>

      {/* 2. Effective Visual Chart: Net Accumulation */}
      <div className="glass-card p-6 rounded-2xl border border-slate-200 dark:border-slate-700">
        <div className="flex flex-col sm:flex-row justify-between sm:items-center mb-6 gap-2">
            <div>
                <h3 className="text-lg font-bold text-slate-900 dark:text-white">Net Accumulation Strategy</h3>
                <p className="text-xs text-slate-500 dark:text-slate-400">
                    Are you accumulating assets (Green) or cashing out (Red)? Dotted line is your average.
                </p>
            </div>
            <div className="flex items-center gap-3 text-xs font-medium">
                <div className="flex items-center"><div className="w-2 h-2 bg-emerald-500 rounded mr-1.5"></div> Net Buy</div>
                <div className="flex items-center"><div className="w-2 h-2 bg-rose-400 rounded mr-1.5"></div> Net Sell</div>
                <div className="flex items-center"><div className="w-2 h-2 bg-blue-400 rounded-full mr-1.5"></div> Dividends</div>
            </div>
        </div>

        <div className="h-[280px] w-full">
           <ResponsiveContainer width="100%" height="100%">
              <ComposedChart data={chartData} margin={{ top: 10, right: 10, left: 0, bottom: 0 }}>
                 <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#e2e8f0" opacity={0.3} />
                 <XAxis dataKey="yearMonth" axisLine={false} tickLine={false} tick={{fill: '#94a3b8', fontSize: 11}} dy={10} minTickGap={30} />
                 <YAxis axisLine={false} tickLine={false} tick={{fill: '#94a3b8', fontSize: 11}} tickFormatter={(val) => `${(val/1000).toFixed(0)}k`} />
                 <Tooltip 
                    cursor={{fill: 'rgba(255,255,255,0.05)'}}
                    contentStyle={{ backgroundColor: '#0f172a', border: 'none', borderRadius: '12px', color: '#fff', boxShadow: '0 10px 15px -3px rgba(0,0,0,0.1)' }}
                    itemStyle={{ fontSize: '12px', padding: '2px 0' }}
                    labelStyle={{ color: '#94a3b8', marginBottom: '8px' }}
                    formatter={(val: number, name: string) => [
                        formatCurrency(Math.abs(val)), 
                        name === 'netInvested' ? (val >= 0 ? 'Net Added' : 'Net Sold') : 'Dividends'
                    ]}
                 />
                 <ReferenceLine y={avgInvestment} stroke="#94a3b8" strokeDasharray="3 3" opacity={0.5} label={{ value: 'AVG', position: 'right', fill: '#94a3b8', fontSize: 10 }} />
                 <ReferenceLine y={0} stroke="#e2e8f0" opacity={0.2} />

                 <Bar dataKey="netInvested" name="netInvested" radius={[2, 2, 2, 2]} maxBarSize={40}>
                    {chartData.map((entry, index) => (
                        <Cell key={`cell-${index}`} fill={entry.netInvested >= 0 ? '#10b981' : '#f43f5e'} opacity={entry.netInvested >= 0 ? 0.8 : 0.8} />
                    ))}
                 </Bar>
                 <Line type="monotone" dataKey="dividendIncome" name="Dividends" stroke="#60a5fa" strokeWidth={3} dot={{r: 3, fill: '#60a5fa', strokeWidth: 0}} />
              </ComposedChart>
           </ResponsiveContainer>
        </div>
      </div>

      {/* 3. Redesigned Responsive List */}
      <div className="bg-white dark:bg-slate-800 rounded-2xl shadow-sm border border-slate-200 dark:border-slate-700 overflow-hidden">
        <div className="p-4 border-b border-slate-100 dark:border-slate-700 bg-slate-50/50 dark:bg-slate-800/50 flex justify-between items-center">
           <h3 className="font-bold text-slate-900 dark:text-white">Monthly Breakdown</h3>
           <div className="flex gap-3 text-[10px] text-slate-400 uppercase font-semibold">
              <div className="flex items-center"><div className="w-2 h-2 rounded-full bg-blue-500 mr-1.5"></div>Buy</div>
              <div className="flex items-center"><div className="w-2 h-2 rounded-full bg-rose-500 mr-1.5"></div>Sell</div>
           </div>
        </div>

        {/* Desktop Header (Hidden on Mobile) */}
        <div className="hidden md:grid grid-cols-12 gap-4 px-6 py-3 bg-slate-50 dark:bg-slate-900/50 text-slate-500 dark:text-slate-400 text-sm font-semibold border-b border-slate-100 dark:border-slate-700">
           <div className="col-span-3">Month</div>
           <div className="col-span-3 text-right">Buy Volume</div>
           <div className="col-span-3 text-right">Sell Volume</div>
           <div className="col-span-2 text-right">Net Flow</div>
           <div className="col-span-1"></div>
        </div>

        <div className="divide-y divide-slate-100 dark:divide-slate-700">
           {displayData.map((data) => {
              const netFlow = data.buyVolume - data.sellVolume;
              const isExpanded = expandedMonth === data.yearMonth;

              return (
                 <div key={data.yearMonth} className={`group transition-all ${isExpanded ? 'bg-slate-50/80 dark:bg-slate-800/80' : 'hover:bg-slate-50 dark:hover:bg-slate-800/30'}`}>

                    {/* Main Row Content */}
                    <div 
                       className="cursor-pointer"
                       onClick={() => toggleMonth(data.yearMonth)}
                    >
                       {/* Mobile Layout (Card Style) */}
                       <div className="md:hidden p-4 space-y-3">
                           <div className="flex justify-between items-center">
                              <div className="font-bold text-slate-800 dark:text-slate-200 text-base">{data.yearMonth}</div>
                              {data.dividendIncome > 0 && (
                                  <div className="text-[10px] font-bold text-emerald-600 dark:text-emerald-400 bg-emerald-50 dark:bg-emerald-900/20 px-2 py-0.5 rounded-full flex items-center">
                                     <DollarSign size={10} className="mr-0.5" /> {formatCurrency(data.dividendIncome)}
                                  </div>
                              )}
                           </div>

                           {/* Stats Grid */}
                           <div className="grid grid-cols-2 gap-3">
                              <div className="bg-blue-50 dark:bg-blue-900/10 p-2 rounded-lg border border-blue-100 dark:border-blue-900/30">
                                 <div className="text-[10px] text-blue-500 dark:text-blue-400 uppercase font-bold mb-0.5">Buy Volume</div>
                                 <div className={`text-sm font-mono font-medium ${data.buyVolume > 0 ? 'text-blue-700 dark:text-blue-300' : 'text-slate-400'}`}>
                                    {data.buyVolume > 0 ? formatCurrency(data.buyVolume) : '-'}
                                 </div>
                              </div>
                              <div className="bg-rose-50 dark:bg-rose-900/10 p-2 rounded-lg border border-rose-100 dark:border-rose-900/30">
                                 <div className="text-[10px] text-rose-500 dark:text-rose-400 uppercase font-bold mb-0.5">Sell Volume</div>
                                 <div className={`text-sm font-mono font-medium ${data.sellVolume > 0 ? 'text-rose-700 dark:text-rose-300' : 'text-slate-400'}`}>
                                    {data.sellVolume > 0 ? formatCurrency(data.sellVolume) : '-'}
                                 </div>
                              </div>
                           </div>

                           <div className="flex justify-between items-center pt-1 border-t border-slate-100 dark:border-slate-700/50">
                              <span className="text-xs text-slate-400">Net Flow</span>
                              <div className={`font-mono font-bold text-sm ${netFlow > 0 ? 'text-emerald-500' : netFlow < 0 ? 'text-rose-500' : 'text-slate-400'}`}>
                                  {netFlow > 0 ? '+' : ''}{formatCurrency(netFlow)}
                              </div>
                           </div>

                           <div className="flex justify-center text-slate-300 pt-1">
                              {isExpanded ? <ChevronDown size={16} /> : <ChevronRight size={16} />}
                           </div>
                       </div>

                       {/* Desktop Layout (Table Style) */}
                       <div className="hidden md:grid grid-cols-12 gap-4 items-center px-6 py-4">
                          <div className="col-span-3 flex items-center space-x-3">
                             <div className="font-bold text-slate-700 dark:text-slate-200">{data.yearMonth}</div>
                             {data.dividendIncome > 0 && (
                                <div className="text-[10px] text-emerald-600 dark:text-emerald-400 font-bold items-center bg-emerald-50 dark:bg-emerald-900/20 px-1.5 py-0.5 rounded-full flex">
                                   <DollarSign size={10} className="mr-0.5" /> {formatCurrency(data.dividendIncome)}
                                </div>
                             )}
                          </div>

                          <div className="col-span-3 text-right">
                             <span className={`font-mono text-sm font-medium ${data.buyVolume > 0 ? 'text-blue-600 dark:text-blue-400' : 'text-slate-300'}`}>
                                {data.buyVolume > 0 ? formatCurrency(data.buyVolume) : '-'}
                             </span>
                          </div>

                          <div className="col-span-3 text-right">
                             <span className={`font-mono text-sm font-medium ${data.sellVolume > 0 ? 'text-rose-500 dark:text-rose-400' : 'text-slate-300'}`}>
                                {data.sellVolume > 0 ? formatCurrency(data.sellVolume) : '-'}
                             </span>
                          </div>

                          <div className="col-span-2 text-right">
                             <span className={`font-mono font-bold text-sm ${netFlow > 0 ? 'text-emerald-500' : netFlow < 0 ? 'text-rose-500' : 'text-slate-300'}`}>
                                {netFlow > 0 ? '+' : ''}{formatCurrency(netFlow)}
                             </span>
                          </div>

                          <div className="col-span-1 flex justify-end text-slate-400">
                             {isExpanded ? <ChevronDown size={16} /> : <ChevronRight size={16} />}
                          </div>
                       </div>
                    </div>

                    {/* Expanded Detail View */}
                    {isExpanded && (
                       <div className="px-4 pb-4 md:px-6 md:pb-6 animate-fade-in">
                          {renderTransactionDetails(data.yearMonth)}
                       </div>
                    )}
                 </div>
              );
           })}
           {displayData.length === 0 && (
              <div className="p-8 text-center text-slate-400">
                 No transaction data available yet.
              </div>
           )}
        </div>
      </div>
    </div>
  );
};

