             >
                {t}
             </button>
           ))}
        </div>

        {/* 2. BIG INPUTS SECTION */}
        <div className="space-y-4">
             {needsSymbol && (
                <div className="relative z-20" ref={wrapperRef}>
                    <label className="text-[10px] font-bold text-slate-400 uppercase tracking-wider mb-1 block">Asset Symbol</label>
                    <div className="relative">
                        <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
                        <input 
                           type="text" placeholder="e.g. AAPL" value={symbol} 
                           onChange={e => { setSymbol(e.target.value); setShowSuggestions(true); }}
                           onFocus={() => setShowSuggestions(true)}
                           className="w-full pl-12 pr-4 py-4 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-2xl text-lg font-bold uppercase tracking-wide focus:ring-2 focus:ring-blue-500 outline-none shadow-sm"
                        />
                         {showSuggestions && suggestions.length > 0 && (
                            <div className="absolute top-full left-0 right-0 mt-2 bg-white dark:bg-slate-800 rounded-xl shadow-xl border border-slate-100 dark:border-slate-700 overflow-hidden z-50">
                                {suggestions.map(s => (
                                    <div key={s} onMouseDown={(e) => { e.preventDefault(); setSymbol(s); setShowSuggestions(false); }} className="px-4 py-3 hover:bg-slate-50 dark:hover:bg-slate-700 cursor-pointer font-bold text-slate-700 dark:text-slate-300">{s}</div>
                                ))}
                            </div>
                        )}
                    </div>
                </div>
             )}

             {/* The Big Money Input */}
             {(needsPrice || isFunding) && (
                <div>
                   <label className="text-[10px] font-bold text-slate-400 uppercase tracking-wider mb-1 block">
                       {needsShares ? 'Total Amount' : 'Amount'}
                   </label>
                   <div className="relative">
                       <span className={`absolute left-4 top-1/2 -translate-y-1/2 text-2xl font-bold ${type === TransactionType.SELL || type === TransactionType.WITHDRAW ? 'text-rose-500' : 'text-blue-500'}`}>$</span>
                       <input 
                          type="number" step="any" min="0" placeholder="0.00"
                          value={totalAmount}
                          onFocus={() => setActiveInput('total')}
                          onChange={e => setTotalAmount(e.target.value)}
                          className="w-full pl-10 pr-4 py-4 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-2xl text-3xl font-bold text-slate-900 dark:text-white focus:ring-2 focus:ring-blue-500 outline-none shadow-sm"
                       />
                   </div>
                </div>
             )}
        </div>

        {/* 3. DETAILS GRID */}
        <div className="grid grid-cols-2 gap-4">
            <div>
               <label className="text-[10px] font-bold text-slate-400 uppercase tracking-wider mb-1 block">Date</label>
               <input type="date" value={date} onChange={e => setDate(e.target.value)} className="w-full px-4 py-3 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl font-medium text-sm focus:ring-2 focus:ring-blue-500 outline-none" />
            </div>

            {needsShares && (
                <div>
                    <label className="text-[10px] font-bold text-slate-400 uppercase tracking-wider mb-1 block">Shares / Qty</label>
                    <input 
                        type="number" step="any" placeholder="0" value={shares}
                        onFocus={() => setActiveInput('shares')}
                        onChange={e => setShares(e.target.value)}
                        className="w-full px-4 py-3 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl font-medium text-sm focus:ring-2 focus:ring-blue-500 outline-none"
                    />
                </div>
            )}

            {needsPrice && needsShares && (
                <div>
                   <label className="text-[10px] font-bold text-slate-400 uppercase tracking-wider mb-1 block">Price / Share</label>
                   <input 
                      type="number" step="any" placeholder="0.00" value={price}
                      onFocus={() => setActiveInput('price')}
                      onChange={e => setPrice(e.target.value)}
                      className="w-full px-4 py-3 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl font-medium text-sm focus:ring-2 focus:ring-blue-500 outline-none"
                   />
                </div>
            )}

             {needsSymbol && (
                <div>
                    <label className="text-[10px] font-bold text-slate-400 uppercase tracking-wider mb-1 block">Asset Class</label>
                    <select value={assetClass} onChange={e => setAssetClass(e.target.value as AssetClass)} className="w-full px-4 py-3 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl font-medium text-sm outline-none">
                        {Object.values(AssetClass).filter(a => a !== AssetClass.CASH).map(a => <option key={a} value={a}>{a}</option>)}
                    </select>
                </div>
             )}
        </div>

        {/* 4. EXPANDABLE OPTIONAL FIELDS */}
        <details className="group">
            <summary className="flex items-center text-xs font-bold text-slate-400 uppercase tracking-wider cursor-pointer list-none mb-3">
               <PlusCircle size={14} className="mr-1 group-open:hidden" />
               <MinusCircle size={14} className="mr-1 hidden group-open:block" />
               Optional Details (Fee, FX, Notes)
            </summary>
            <div className="space-y-4 pt-2 animate-fade-in">
                 {(type === TransactionType.BUY || type === TransactionType.SELL) && (
                     <div>
                        <label className="text-[10px] font-bold text-slate-400 uppercase tracking-wider mb-1 block">Transaction Fee</label>
                        <input type="number" placeholder="0.00" value={fee} onChange={e => setFee(e.target.value)} className="w-full px-4 py-3 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl text-sm" />
                     </div>
                 )}
                 {isFunding && (
                     <div>
                        <label className="text-[10px] font-bold text-slate-400 uppercase tracking-wider mb-1 block">Exchange Rate (Local/USD)</label>
                        <input type="number" placeholder="1.0" value={exchangeRate} onChange={e => setExchangeRate(e.target.value)} className="w-full px-4 py-3 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl text-sm" />
                     </div>
                 )}
                 <div>
                    <label className="text-[10px] font-bold text-slate-400 uppercase tracking-wider mb-1 block">Notes</label>
                    <textarea rows={2} placeholder="Add a memo..." value={notes} onChange={e => setNotes(e.target.value)} className="w-full px-4 py-3 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl text-sm" />
                 </div>
            </div>
        </details>
      </form>

      {/* 5. FOOTER ACTIONS */}
      <div className="p-5 border-t border-slate-100 dark:border-slate-800 bg-white dark:bg-slate-900 z-10">
         {error && (
            <div className="bg-rose-50 text-rose-600 px-4 py-3 rounded-xl text-sm font-bold flex items-center mb-4">
                <AlertCircle size={16} className="mr-2" /> {error}
            </div>
         )}
         <div className="flex gap-3">
             {initialData && onDelete && (
                 <button type="button" onClick={() => onDelete(initialData.id)} className="p-4 rounded-xl bg-rose-50 text-rose-500 hover:bg-rose-100 transition-colors"><Trash2 size={20} /></button>
             )}
             <button 
                onClick={handleSubmit} disabled={isSaving}
                className={`flex-1 py-4 rounded-xl font-bold text-lg text-white shadow-xl transition-all active:scale-95 flex items-center justify-center ${isSaving ? 'bg-slate-400 cursor-not-allowed' : `bg-${themeColor}-600 hover:bg-${themeColor}-700 shadow-${themeColor}-500/30`}`}
             >
                {isSaving ? <Spinner className="text-white" /> : (initialData ? 'Update' : 'Save Transaction')}
             </button>
         </div>
      </div>
    </>
  );
};

export default App;

import React, { useState, useMemo, useRef } from 'react';
import { Transaction, TransactionType, AssetClass } from '../types';
import { Search, Calendar, Filter, Trash2, ArrowUpDown, XCircle, Edit2, Plus, Download, Upload, TrendingUp, TrendingDown, RefreshCcw, DollarSign, Wallet } from 'lucide-react';
import { formatCurrency, formatNumber, transactionsToCSV, csvToTransactions } from '../utils';
import { HistorySkeleton } from './LoadingSkeletons';

interface HistoryProps {
  transactions: Transaction[];
  onDelete: (id: string) => void;
  onEdit: (tx: Transaction) => void;
  onAdd: () => void;
  onImport: (txs: Transaction[]) => void;
  isLoading?: boolean;
}

const History: React.FC<HistoryProps> = ({ transactions, onDelete, onEdit, onAdd, onImport, isLoading }) => {
  // Filters State
  const [searchTerm, setSearchTerm] = useState('');
  const [typeFilter, setTypeFilter] = useState<TransactionType | 'ALL'>('ALL');
  const [assetClassFilter, setAssetClassFilter] = useState<AssetClass | 'ALL'>('ALL');
  const [startDate, setStartDate] = useState('');
  const [endDate, setEndDate] = useState('');
  const [sortOrder, setSortOrder] = useState<'desc' | 'asc'>('desc');
  const [showFilters, setShowFilters] = useState(false);

  const fileInputRef = useRef<HTMLInputElement>(null);

  // Logic
  const filteredTransactions = useMemo(() => {
    return transactions.filter(tx => {
      // 1. Search (Symbol, Notes)
      const searchLower = searchTerm.toLowerCase();
      const matchesSearch = 
        (tx.symbol?.toLowerCase().includes(searchLower) ?? false) ||
        (tx.notes?.toLowerCase().includes(searchLower) ?? false) ||
        (tx.type.toLowerCase().includes(searchLower));

      // 2. Type Filter
      const matchesType = typeFilter === 'ALL' || tx.type === typeFilter;

      // 3. Asset Class Filter
      const matchesAsset = assetClassFilter === 'ALL' || tx.assetClass === assetClassFilter;

      // 4. Date Range
      const txDate = new Date(tx.date).getTime();
      const start = startDate ? new Date(startDate).getTime() : -Infinity;
      const end = endDate ? new Date(endDate).getTime() : Infinity;
      const matchesDate = txDate >= start && txDate <= end;

      return matchesSearch && matchesType && matchesAsset && matchesDate;
    }).sort((a, b) => {
      const dateA = new Date(a.date).getTime();
      const dateB = new Date(b.date).getTime();
      return sortOrder === 'desc' ? dateB - dateA : dateA - dateB;
    });
  }, [transactions, searchTerm, typeFilter, assetClassFilter, startDate, endDate, sortOrder]);

  const resetFilters = () => {
    setSearchTerm('');
    setTypeFilter('ALL');
    setAssetClassFilter('ALL');
    setStartDate('');
    setEndDate('');
  };

  const handleImportClick = () => fileInputRef.current?.click();

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (evt) => {
      const content = evt.target?.result as string;
      if (content) {
        const imported = csvToTransactions(content);
        if (imported.length > 0) onImport(imported);
        else alert("No valid transactions found.");
      }
    };
    reader.readAsText(file);
    e.target.value = '';
  };

  const handleExport = () => {
    const csv = transactionsToCSV(transactions);
    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.setAttribute('download', `portfolio_backup_${new Date().toISOString().split('T')[0]}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  if (isLoading) return <HistorySkeleton />;

  const hasActiveFilters = searchTerm || typeFilter !== 'ALL' || assetClassFilter !== 'ALL' || startDate || endDate;

  // Helper for Icons
  const getIconForType = (type: TransactionType) => {
      switch(type) {
          case TransactionType.BUY: return <TrendingUp size={16} />;
          case TransactionType.SELL: return <TrendingDown size={16} />;
          case TransactionType.DEPOSIT: return <Wallet size={16} />;
          case TransactionType.WITHDRAW: return <Wallet size={16} />;
          case TransactionType.DIVIDEND: return <DollarSign size={16} />;
          default: return <RefreshCcw size={16} />;
      }
  };

  const getColorForType = (type: TransactionType) => {
      switch(type) {
          case TransactionType.BUY: return 'bg-blue-100 text-blue-600 dark:bg-blue-900/30 dark:text-blue-400';
          case TransactionType.SELL: return 'bg-rose-100 text-rose-600 dark:bg-rose-900/30 dark:text-rose-400';
          case TransactionType.DEPOSIT: return 'bg-indigo-100 text-indigo-600 dark:bg-indigo-900/30 dark:text-indigo-400';
          case TransactionType.WITHDRAW: return 'bg-orange-100 text-orange-600 dark:bg-orange-900/30 dark:text-orange-400';
          case TransactionType.DIVIDEND: return 'bg-emerald-100 text-emerald-600 dark:bg-emerald-900/30 dark:text-emerald-400';
          default: return 'bg-slate-100 text-slate-600 dark:bg-slate-800 dark:text-slate-400';
      }
  }

  return (
    <div className="space-y-6 animate-fade-in pb-12">
      <input type="file" accept=".csv" ref={fileInputRef} onChange={handleFileChange} className="hidden" />

      {/* Header Area */}
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
           <div>
              <h2 className="text-2xl font-display font-bold text-slate-900 dark:text-white">Activity</h2>
              <p className="text-slate-500 text-sm">{filteredTransactions.length} transactions</p>
           </div>

           <div className="flex items-center gap-2">
             <div className="relative flex-1 md:w-64">
               <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={16} />
               <input 
                 type="text" placeholder="Search..." 
                 value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)}
                 className="w-full pl-9 pr-4 py-2 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl text-sm outline-none focus:ring-2 focus:ring-blue-500"
               />
             </div>
             <button onClick={() => setShowFilters(!showFilters)} className={`p-2 rounded-xl border ${showFilters || hasActiveFilters ? 'bg-blue-50 border-blue-200 text-blue-600' : 'bg-white border-slate-200 text-slate-500'} transition-colors`}>
                <Filter size={20} />
             </button>
             <button onClick={onAdd} className="hidden md:flex items-center space-x-2 bg-slate-900 text-white px-4 py-2 rounded-xl font-bold text-sm hover:opacity-90">
                 <Plus size={16} /> <span>New</span>
             </button>
             {/* Mobile Add */}
             <button onClick={onAdd} className="md:hidden p-2 bg-slate-900 text-white rounded-xl shadow-lg">
                 <Plus size={20} />
             </button>
           </div>
      </div>

      {/* Collapsible Filters */}
      {showFilters && (
        <div className="bg-white dark:bg-slate-800 p-4 rounded-xl border border-slate-200 dark:border-slate-700 shadow-sm grid grid-cols-2 md:grid-cols-4 gap-3 animate-slide-up">
           <select value={typeFilter} onChange={(e) => setTypeFilter(e.target.value as any)} className="bg-slate-50 dark:bg-slate-900 border border-slate-200 dark:border-slate-700 rounded-lg px-3 py-2 text-sm outline-none"><option value="ALL">All Types</option>{Object.values(TransactionType).map(t => <option key={t} value={t}>{t}</option>)}</select>
           <select value={assetClassFilter} onChange={(e) => setAssetClassFilter(e.target.value as any)} className="bg-slate-50 dark:bg-slate-900 border border-slate-200 dark:border-slate-700 rounded-lg px-3 py-2 text-sm outline-none"><option value="ALL">All Assets</option>{Object.values(AssetClass).map(a => <option key={a} value={a}>{a}</option>)}</select>
           <input type="date" value={startDate} onChange={(e) => setStartDate(e.target.value)} className="bg-slate-50 dark:bg-slate-900 border border-slate-200 dark:border-slate-700 rounded-lg px-3 py-2 text-sm outline-none" />
           <div className="flex gap-2">
              <input type="date" value={endDate} onChange={(e) => setEndDate(e.target.value)} className="flex-1 bg-slate-50 dark:bg-slate-900 border border-slate-200 dark:border-slate-700 rounded-lg px-3 py-2 text-sm outline-none" />
              {hasActiveFilters && <button onClick={resetFilters} className="text-rose-500 p-2"><XCircle size={20} /></button>}
           </div>
           <div className="col-span-2 md:col-span-4 flex justify-end gap-2 pt-2 border-t border-slate-100 dark:border-slate-700">
              <button onClick={handleImportClick} className="text-xs font-bold text-blue-600 flex items-center"><Upload size={12} className="mr-1"/> Import CSV</button>
              <button onClick={handleExport} className="text-xs font-bold text-blue-600 flex items-center ml-4"><Download size={12} className="mr-1"/> Export CSV</button>
           </div>
        </div>
      )}

      {/* Modern List View */}
      <div className="bg-white dark:bg-slate-800 rounded-2xl shadow-sm border border-slate-200 dark:border-slate-700 overflow-hidden min-h-[400px]">
         <div className="divide-y divide-slate-100 dark:divide-slate-800">
            {filteredTransactions.map(tx => {
               const isPositive = tx.type === 'SELL' || tx.type === 'DIVIDEND' || tx.type === 'DEPOSIT';
               const amount = (tx.type === 'BUY' || tx.type === 'SELL') ? (tx.price! * tx.shares!) : tx.price!;

               return (
                 <div 
                   key={tx.id} 
                   onClick={() => onEdit(tx)}
                   className="p-4 hover:bg-slate-50 dark:hover:bg-slate-700/30 transition-colors cursor-pointer flex items-center justify-between group"
                 >
                    <div className="flex items-center space-x-4">
                       {/* Icon Box */}
                       <div className={`w-10 h-10 rounded-xl flex items-center justify-center shrink-0 ${getColorForType(tx.type)}`}>
                          {getIconForType(tx.type)}
                       </div>

                       <div>
                          <div className="font-bold text-slate-900 dark:text-white text-sm">
                             {tx.symbol || (tx.type === 'DEPOSIT' || tx.type === 'WITHDRAW' ? 'Cash Transfer' : tx.type)}
                          </div>
                          <div className="text-xs text-slate-500 dark:text-slate-400 flex items-center mt-0.5">
                             <span>{new Date(tx.date).toLocaleDateString()}</span>
                             <span className="mx-1.5">•</span>
                             <span className="uppercase">{tx.type}</span>
                          </div>
                       </div>
                    </div>

                    <div className="text-right">
                       <div className={`font-mono font-bold text-sm ${isPositive ? 'text-emerald-600 dark:text-emerald-400' : 'text-slate-900 dark:text-white'}`}>
                          {isPositive ? '+' : ''}{tx.type === 'SPLIT' ? '-' : formatCurrency(amount)}
                       </div>
                       {tx.shares && tx.shares > 0 && (
                          <div className="text-xs text-slate-400 mt-0.5">
                             {formatNumber(tx.shares)} {tx.type === 'SPLIT' ? 'ratio' : 'shares'}
                          </div>
                       )}
                    </div>
                 </div>
               );
            })}

            {filteredTransactions.length === 0 && (
                <div className="p-12 text-center text-slate-400">
                   <p>No transactions found.</p>
                </div>
            )}
         </div>
      </div>
    </div>
  );
};

export default History;

import React, { useMemo, useState } from 'react';
import { Holding, Transaction, ChartDataPoint, AssetClass } from '../types';
import { formatCurrency, formatNumber } from '../utils';
import { 
  AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, 
  PieChart, Pie, Cell, Brush
} from 'recharts';
import { ArrowUpRight, ArrowDownRight, TrendingUp, Wallet, Target, Activity, ChevronLeft, PieChart as PieChartIcon, ZoomIn, Star, ShieldCheck, Banknote } from 'lucide-react';
import { DashboardSkeleton } from './LoadingSkeletons';

interface DashboardProps {
  holdings: Holding[];
  transactions: Transaction[];
  financialGoal: number;
  setFinancialGoal?: (val: number) => void; // Optional/Deprecated
  onOpenGoalModal: () => void;
  investedAmount: number;
  cashBalance: number;
  portfolioValue: number;
  chartData: ChartDataPoint[];
  isLoading?: boolean;
}

const COLORS = ['#3b82f6', '#10b981', '#f59e0b', '#ef4444', '#8b5cf6', '#ec4899', '#6366f1', '#14b8a6'];

const Dashboard: React.FC<DashboardProps> = ({ 
  holdings, transactions, financialGoal, onOpenGoalModal, investedAmount, portfolioValue, cashBalance, chartData, isLoading 
}) => {
  const [selectedCategory, setSelectedCategory] = useState<string | null>(null);

  const totalNetWorth = portfolioValue + cashBalance;
  const totalUnrealizedPL = holdings.reduce((sum, h) => sum + h.unrealizedPL, 0);
  const totalPLPercent = investedAmount > 0 ? (totalUnrealizedPL / investedAmount) * 100 : 0;

  // 1. Prepare Main Allocation Data (By Category)
  const categoryData = useMemo(() => {
    return holdings
      .filter(h => h.marketValue > 0)
      .map(h => ({ name: h.assetClass, value: h.marketValue }))
      .reduce((acc: any[], curr) => {
        const existing = acc.find(item => item.name === curr.name);
        if (existing) {
          existing.value += curr.value;
        } else {
          acc.push({ ...curr });
        }
        return acc;
      }, [])
      .sort((a, b) => b.value - a.value);
  }, [holdings]);

  // 2. Prepare Drill-down Data (Assets within selected Category)
  const assetData = useMemo(() => {
    if (!selectedCategory) return [];
    return holdings
      .filter(h => h.assetClass === selectedCategory && h.marketValue > 0)
      .map(h => ({ name: h.symbol, value: h.marketValue, fullName: h.name }))
      .sort((a, b) => b.value - a.value);
  }, [holdings, selectedCategory]);

  // Determine which data to show
  const activeChartData = selectedCategory ? assetData : categoryData;
  const activeTotalValue = selectedCategory 
    ? assetData.reduce((sum, item) => sum + item.value, 0)
    : portfolioValue;

  if (isLoading) {
    return <DashboardSkeleton />;
  }

  return (
    <div className="space-y-6 animate-fade-in pb-10">

      {/* 1. PRIMARY METRICS (Bento Grid Layout) */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-4 md:gap-6">

        {/* BIG CARD: Total Balance */}
        <div className="md:col-span-2 relative overflow-hidden rounded-3xl p-6 sm:p-8 bg-slate-900 text-white shadow-xl shadow-slate-900/10 group">
          <div className="absolute inset-0 bg-gradient-to-br from-slate-800 to-slate-950"></div>
          {/* Abstract blobs */}
          <div className="absolute top-0 right-0 w-64 h-64 bg-blue-600/20 rounded-full blur-[80px] -translate-y-1/2 translate-x-1/2"></div>
          <div className="absolute bottom-0 left-0 w-40 h-40 bg-purple-600/20 rounded-full blur-[60px] translate-y-1/2 -translate-x-1/2"></div>

          <div className="relative z-10 flex flex-col justify-between h-full space-y-6">
            <div className="flex justify-between items-start">
               <div>
                  <p className="text-slate-400 font-medium mb-1">Total Balance</p>
                  <h2 className="text-4xl sm:text-5xl font-display font-bold tracking-tight">
                    {formatCurrency(totalNetWorth)}
                  </h2>
               </div>
               <div className="p-3 bg-white/5 rounded-2xl backdrop-blur-md border border-white/10">
                 <ShieldCheck className="text-emerald-400" size={24} />
               </div>
            </div>

            <div className="grid grid-cols-2 gap-8 border-t border-white/10 pt-6">
               <div>
                 <p className="text-xs text-slate-400 font-bold uppercase tracking-wider mb-1 flex items-center">
                    <Banknote size={14} className="mr-1.5" /> Cash Available
                 </p>
                 <p className="text-xl font-bold font-mono">{formatCurrency(cashBalance)}</p>
               </div>
               <div>
                 <p className="text-xs text-slate-400 font-bold uppercase tracking-wider mb-1 flex items-center">
                    <TrendingUp size={14} className="mr-1.5" /> Invested Assets
                 </p>
                 <p className="text-xl font-bold font-mono">{formatCurrency(portfolioValue)}</p>
               </div>
            </div>
          </div>
        </div>

        {/* SIDE COLUMN: Performance & Goals */}
        <div className="space-y-4 md:space-y-6 flex flex-col">

            {/* P/L Card */}
            <div className="flex-1 bg-white dark:bg-slate-800 rounded-3xl p-6 border border-slate-100 dark:border-slate-700 shadow-sm flex flex-col justify-center">
                <p className="text-sm text-slate-500 dark:text-slate-400 font-medium mb-1">Unrealized P/L</p>
                <div className="flex items-baseline space-x-2">
                    <h3 className={`text-2xl sm:text-3xl font-bold ${totalUnrealizedPL >= 0 ? 'text-emerald-600 dark:text-emerald-400' : 'text-rose-600 dark:text-rose-400'}`}>
                        {totalUnrealizedPL >= 0 ? '+' : ''}{formatCurrency(totalUnrealizedPL)}
                    </h3>
                </div>
                <div className={`mt-2 inline-flex items-center px-2.5 py-1 rounded-lg text-xs font-bold w-fit ${totalPLPercent >= 0 ? 'bg-emerald-50 text-emerald-700 dark:bg-emerald-900/30 dark:text-emerald-400' : 'bg-rose-50 text-rose-700 dark:bg-rose-900/30 dark:text-rose-400'}`}>
                    {totalPLPercent >= 0 ? <ArrowUpRight size={14} className="mr-1"/> : <ArrowDownRight size={14} className="mr-1"/>}
                    {Math.abs(totalPLPercent).toFixed(2)}% All Time
                </div>
            </div>

            {/* Goal Progress (Compact) */}
            <div className="flex-1 bg-blue-50 dark:bg-slate-800/50 rounded-3xl p-6 border border-blue-100 dark:border-slate-700 relative overflow-hidden group cursor-pointer hover:border-blue-300 transition-colors" onClick={onOpenGoalModal}>
                <div className="absolute right-0 top-0 p-4 opacity-5 group-hover:opacity-10 transition-opacity transform group-hover:scale-110 duration-500">
                    <Target size={80} />
                </div>
                <div className="relative z-10">
                    <div className="flex justify-between items-center mb-2">
                        <p className="text-sm font-bold text-slate-500 dark:text-slate-400 uppercase tracking-wider">Goal Target</p>
                        <p className="text-xs font-bold text-blue-600 dark:text-blue-400">{((totalNetWorth / financialGoal) * 100).toFixed(0)}%</p>
                    </div>
                    <p className="text-xl font-bold text-slate-900 dark:text-white mb-3">
                        {formatCurrency(financialGoal)}
                    </p>
                    <div className="w-full bg-slate-200 dark:bg-slate-700 h-1.5 rounded-full overflow-hidden">
                        <div className="bg-blue-500 h-full rounded-full transition-all duration-1000" style={{ width: `${Math.min((totalNetWorth / financialGoal) * 100, 100)}%` }}></div>
                    </div>
                </div>
            </div>
        </div>
      </div>

      {/* 2. CHART SECTION */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">

        {/* Wealth Chart */}
        <div className="lg:col-span-2 bg-white dark:bg-slate-800 rounded-3xl p-6 border border-slate-100 dark:border-slate-700 shadow-sm">
           <div className="flex items-center justify-between mb-6">
             <div>
                <h3 className="text-lg font-bold text-slate-900 dark:text-white">Performance History</h3>
                <p className="text-xs text-slate-500">Net Invested vs. Market Value</p>
             </div>
             <div className="hidden sm:flex items-center space-x-4 text-xs font-bold">
                  <div className="flex items-center text-blue-500"><div className="w-2.5 h-2.5 bg-blue-500 rounded-full mr-2"></div> Value</div>
                  <div className="flex items-center text-slate-400"><div className="w-2.5 h-2.5 bg-slate-300 rounded-full mr-2"></div> Cost</div>
              </div>
           </div>

           <div className="h-[300px] w-full">
            {chartData.length > 0 ? (
              <ResponsiveContainer width="100%" height="100%">
              <AreaChart data={chartData} margin={{ top: 10, right: 10, left: 0, bottom: 0 }}>
                <defs>
                  <linearGradient id="colorValue" x1="0" y1="0" x2="0" y2="1">
                    <stop offset="5%" stopColor="#3b82f6" stopOpacity={0.2}/>
                    <stop offset="95%" stopColor="#3b82f6" stopOpacity={0}/>
                  </linearGradient>
                </defs>
                <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" opacity={0.4} vertical={false} />
                <XAxis 
                  dataKey="date" 
                  axisLine={false} 
                  tickLine={false} 
                  tick={{fill: '#94a3b8', fontSize: 11}} 
                  dy={15} 
                  minTickGap={40} 
                />
                <YAxis 
                  axisLine={false} 
                  tickLine={false} 
                  tick={{fill: '#94a3b8', fontSize: 11}} 
                  tickFormatter={(val) => val >= 1000 ? (val/1000).toFixed(0) + 'k' : val}
                />
                <Tooltip 
                  contentStyle={{ 
                    backgroundColor: '#0f172a', 
                    border: 'none', 
                    borderRadius: '12px', 
                    color: '#fff',
                  }}
                  itemStyle={{ color: '#fff', fontSize: '12px' }}
                  labelStyle={{ color: '#94a3b8', fontSize: '11px', marginBottom: '8px', textTransform: 'uppercase' }}
                  formatter={(value: number, name: string) => [
                    formatCurrency(value), 
                    name === 'value' ? 'Market Value' : 'Net Invested'
                  ]}
                />
                <Area 
                  type="monotone" 
                  dataKey="value" 
                  stroke="#3b82f6" 
                  strokeWidth={3} 
                  fillOpacity={1} 
                  fill="url(#colorValue)" 
                />
                <Area 
                  type="monotone" 
                  dataKey="invested" 
                  stroke="#cbd5e1" 
                  strokeDasharray="4 4" 
                  strokeWidth={2} 
                  fill="transparent" 
                />
              </AreaChart>
            </ResponsiveContainer>
            ) : (
              <div className="flex h-full flex-col items-center justify-center text-slate-400 bg-slate-50 dark:bg-slate-900/50 rounded-2xl border-2 border-dashed border-slate-200 dark:border-slate-700">
                <Activity className="mb-2 opacity-50" size={32} />
                <p>No data to display yet.</p>
              </div>
            )}
          </div>
        </div>

        {/* Allocation Donut */}
        <div className="bg-white dark:bg-slate-800 rounded-3xl p-6 border border-slate-100 dark:border-slate-700 shadow-sm flex flex-col relative">
           <div className="flex items-center justify-between mb-4">
               <div>
                  <h3 className="text-lg font-bold text-slate-900 dark:text-white">Allocation</h3>
                  <p className="text-xs text-slate-500">{selectedCategory ? selectedCategory : 'By Asset Class'}</p>
               </div>
               {selectedCategory && (
                  <button onClick={() => setSelectedCategory(null)} className="p-1.5 bg-slate-100 dark:bg-slate-700 rounded-full text-slate-500">
                     <ChevronLeft size={16} />
                  </button>
               )}
           </div>

           <div className="flex-1 flex flex-col justify-center items-center relative min-h-[220px]">
              {activeChartData.length > 0 ? (
                 <ResponsiveContainer width="100%" height="100%">
                  <PieChart>
                    <Pie
                      data={activeChartData}
                      cx="50%"
                      cy="50%"
                      innerRadius={65}
                      outerRadius={85}
                      paddingAngle={4}
                      dataKey="value"
                      cornerRadius={6}
                      onClick={(data) => {
                         const clickedName = data.name || data.payload?.name;
                         if (!selectedCategory && clickedName) setSelectedCategory(clickedName);
                      }}
                      className={!selectedCategory ? 'cursor-pointer' : ''}
                    >
                      {activeChartData.map((entry, index) => (
                        <Cell 
                          key={`cell-${index}`} 
                          fill={COLORS[index % COLORS.length]} 
                          strokeWidth={0} 
                        />
                      ))}
                    </Pie>
                    <Tooltip 
                       contentStyle={{ backgroundColor: '#0f172a', borderRadius: '8px', border: 'none', color: '#fff' }}
                       formatter={(value: number) => formatCurrency(value)} 
                    />
                  </PieChart>
                </ResponsiveContainer>
              ) : (
                 <div className="text-slate-300 flex flex-col items-center">
                    <PieChartIcon size={40} className="mb-2" />
                    <span className="text-sm">No assets</span>
                 </div>
              )}

              {/* Center Label */}
              {activeChartData.length > 0 && (
                 <div className="absolute inset-0 flex flex-col items-center justify-center pointer-events-none">
                    <span className="text-[10px] text-slate-400 font-bold uppercase tracking-wider">Total</span>
                    <span className="text-sm font-bold text-slate-900 dark:text-white">{formatCurrency(activeTotalValue).split('.')[0]}</span>
                 </div>
              )}
           </div>

           {/* Legend List */}
           <div className="mt-4 space-y-2 max-h-[140px] overflow-y-auto custom-scrollbar">
             {activeChartData.map((entry, idx) => (
                <div key={idx} className="flex items-center justify-between text-sm p-1.5 hover:bg-slate-50 dark:hover:bg-slate-700/50 rounded-lg cursor-pointer transition-colors" onClick={() => !selectedCategory && setSelectedCategory(entry.name)}>
                   <div className="flex items-center">
                      <div className="w-2.5 h-2.5 rounded-full mr-2.5" style={{ backgroundColor: COLORS[idx % COLORS.length] }}></div>
                      <span className="text-slate-600 dark:text-slate-300 font-medium truncate max-w-[100px]">{entry.name}</span>
                   </div>
                   <div className="font-bold text-slate-900 dark:text-white">
                      {((entry.value / activeTotalValue) * 100).toFixed(0)}%
                   </div>
                </div>
             ))}
           </div>
        </div>

      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import Layout from './components/Layout';
import Dashboard from './components/Dashboard';
import Holdings from './components/Holdings';
import Reports from './components/Reports';
import History from './components/History';
import GoalModal from './components/GoalModal';
import { Transaction, TransactionType, AssetClass, Holding, Portfolio, FinancialGoal } from './types';
import { calculateHoldings, calculatePortfolioHistory, generateId, formatCurrency, formatNumber } from './utils';
import { X, Save, TrendingUp, TrendingDown, DollarSign, Wallet, Calendar, GitFork, AlertCircle, ArrowRight, Trash2, Zap, Calculator, Search, Clock, PlusCircle, MinusCircle, RefreshCcw, Split } from 'lucide-react';
import { Spinner } from './components/LoadingSkeletons';

const POPULAR_SYMBOLS = [
  'AAPL', 'MSFT', 'GOOGL', 'AMZN', 'NVDA', 'TSLA', 'META', 'BRK.B', 'V', 'JNJ', 'WMT', 'JPM', // Tech/Blue Chip
  'VOO', 'VTI', 'QQQ', 'IVV', 'SCHD', 'JEPI', 'VUG', 'VTV', // ETFs
  'BTC', 'ETH', 'SOL', 'USDT', 'BNB', 'XRP', 'ADA' // Crypto
];

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState('dashboard');
  const [isAddModalOpen, setIsAddModalOpen] = useState(false);
  const [editingTransaction, setEditingTransaction] = useState<Transaction | null>(null);

  // Goal Modal State
  const [isGoalModalOpen, setIsGoalModalOpen] = useState(false);

  // --- CONFIRMATION MODAL STATE ---
  const [confirmConfig, setConfirmConfig] = useState<{
    isOpen: boolean;
    title: string;
    message: string;
    onConfirm: () => void;
  }>({
    isOpen: false,
    title: '',
    message: '',
    onConfirm: () => {},
  });

  // --- PORTFOLIO MANAGEMENT STATE ---
  const [portfolios, setPortfolios] = useState<Portfolio[]>(() => {
    const saved = localStorage.getItem('portfolios');
    if (saved) return JSON.parse(saved);
    const legacyTx = localStorage.getItem('transactions');
    if (legacyTx) return [{ id: 'default', name: 'Main Portfolio' }];
    return [{ id: generateId(), name: 'My First Portfolio' }];
  });

  const [activePortfolioId, setActivePortfolioId] = useState<string>(() => {
    const saved = localStorage.getItem('activePortfolioId');
    const portfolios = JSON.parse(localStorage.getItem('portfolios') || '[]');
    if (saved && portfolios.some((p: Portfolio) => p.id === saved)) return saved;
    return portfolios.length > 0 ? portfolios[0].id : 'default';
  });

  // --- DATA STATE (Per Portfolio) - Synchronous Initialization ---
  const [transactions, setTransactions] = useState<Transaction[]>(() => {
    const key = `transactions_${activePortfolioId}`;
    const saved = localStorage.getItem(key);
    if (saved) return JSON.parse(saved);
    if (activePortfolioId === 'default') {
      const legacy = localStorage.getItem('transactions');
      if (legacy) return JSON.parse(legacy);
    }
    return [];
  });

  const [prices, setPrices] = useState<Record<string, number>>(() => {
    const key = `prices_${activePortfolioId}`;
    const saved = localStorage.getItem(key);
    if (saved) return JSON.parse(saved);
    if (activePortfolioId === 'default') {
      const legacy = localStorage.getItem('prices');
      if (legacy) return JSON.parse(legacy);
    }
    return {};
  });

  const [goals, setGoals] = useState<FinancialGoal[]>(() => {
    const key = `goals_${activePortfolioId}`;
    const saved = localStorage.getItem(key);
    if (saved) return JSON.parse(saved);

    let legacyGoal = 100000;
    const legacyKey = `financialGoal_${activePortfolioId}`;
    const savedLegacy = localStorage.getItem(legacyKey);
    if (savedLegacy) legacyGoal = parseFloat(savedLegacy);
    else if (activePortfolioId === 'default' && localStorage.getItem('financialGoal')) legacyGoal = parseFloat(localStorage.getItem('financialGoal')!);

    return [{ id: generateId(), targetAmount: legacyGoal, startDate: new Date().toISOString(), isAchieved: false, notes: 'Initial Goal' }];
  });

  const [isDataLoaded, setIsDataLoaded] = useState(true);
  const [isLoading, setIsLoading] = useState(false);
  const isFirstMount = useRef(true);

  // --- PERSISTENCE ---
  useEffect(() => { localStorage.setItem('portfolios', JSON.stringify(portfolios)); }, [portfolios]);
  useEffect(() => { localStorage.setItem('activePortfolioId', activePortfolioId); }, [activePortfolioId]);

  useEffect(() => {
    if (isFirstMount.current) { isFirstMount.current = false; return; }
    setIsLoading(true);
    setIsDataLoaded(false);
    const loadData = () => {
        const txKey = `transactions_${activePortfolioId}`;
        const pricesKey = `prices_${activePortfolioId}`;
        const goalsKey = `goals_${activePortfolioId}`;

        const savedTx = localStorage.getItem(txKey);
        setTransactions(savedTx ? JSON.parse(savedTx) : []);

        const savedPrices = localStorage.getItem(pricesKey);
        setPrices(savedPrices ? JSON.parse(savedPrices) : {});

        const savedGoals = localStorage.getItem(goalsKey);
        setGoals(savedGoals ? JSON.parse(savedGoals) : []); 

        setIsDataLoaded(true);
        setTimeout(() => setIsLoading(false), 500);
    };
    requestAnimationFrame(loadData);
  }, [activePortfolioId]);

  useEffect(() => { if (isDataLoaded) localStorage.setItem(`transactions_${activePortfolioId}`, JSON.stringify(transactions)); }, [transactions, activePortfolioId, isDataLoaded]);
  useEffect(() => { if (isDataLoaded) localStorage.setItem(`prices_${activePortfolioId}`, JSON.stringify(prices)); }, [prices, activePortfolioId, isDataLoaded]);
  useEffect(() => { if (isDataLoaded) localStorage.setItem(`goals_${activePortfolioId}`, JSON.stringify(goals)); }, [goals, activePortfolioId, isDataLoaded]);

  // --- CALCULATIONS ---
  const holdings = useMemo(() => calculateHoldings(transactions, prices), [transactions, prices]);
  const chartData = useMemo(() => calculatePortfolioHistory(transactions, prices), [transactions, prices]);
  const investedAmount = transactions.reduce((sum, t) => {
    if (t.type === TransactionType.DEPOSIT) return sum + (t.price || 0);
    if (t.type === TransactionType.WITHDRAW) return sum - (t.price || 0);
    return sum;
  }, 0);
  const cashBalance = useMemo(() => {
    let balance = 0;
    transactions.forEach(t => {
      if (t.type === TransactionType.DEPOSIT) balance += (t.price || 0);
      if (t.type === TransactionType.WITHDRAW) balance -= (t.price || 0);
      if (t.type === TransactionType.BUY) balance -= (t.price! * t.shares!) + (t.fee || 0);
      if (t.type === TransactionType.SELL) balance += (t.price! * t.shares!) - (t.fee || 0);
      if (t.type === TransactionType.DIVIDEND) balance += (t.price || 0);
    });
    return balance;
  }, [transactions]);
  const portfolioValue = holdings.reduce((sum, h) => sum + h.marketValue, 0);
  const totalNetWorth = portfolioValue + cashBalance;
  const activeGoal = useMemo(() => goals.find(g => !g.endDate) || { targetAmount: 100000 } as FinancialGoal, [goals]);

  // --- HANDLERS ---
  const handleOpenAddModal = () => { setEditingTransaction(null); setIsAddModalOpen(true); };
  const handleOpenEditModal = (tx: Transaction) => { setEditingTransaction(tx); setIsAddModalOpen(true); };
  const handleSaveTransaction = (tx: Transaction) => {
    return new Promise<void>((resolve) => {
      if (editingTransaction) setTransactions(prev => prev.map(t => t.id === tx.id ? tx : t));
      else setTransactions(prev => [...prev, tx]);
      if ((tx.type === TransactionType.BUY || tx.type === TransactionType.SELL) && tx.symbol && tx.price) setPrices(prev => ({...prev, [tx.symbol!]: tx.price!}));
      setIsAddModalOpen(false); setEditingTransaction(null); resolve();
    });
  };
  const handleUpdatePrice = (symbol: string, newPrice: number) => setPrices(prev => ({ ...prev, [symbol]: newPrice }));
  const handleDeleteTransaction = (id: string) => {
    setTransactions(prev => prev.filter(t => t.id !== id));
    if (editingTransaction && editingTransaction.id === id) { setIsAddModalOpen(false); setEditingTransaction(null); }
  };
  const handleRequestDelete = (id: string) => {
      setConfirmConfig({ isOpen: true, title: 'Delete Transaction', message: 'Permanently remove this record?', onConfirm: () => { handleDeleteTransaction(id); setConfirmConfig(prev => ({ ...prev, isOpen: false })); } });
  };
  const handleImportTransactions = (importedTxs: Transaction[]) => {
      setTransactions(prev => {
          const currentMap = new Map(prev.map(t => [t.id, t]));
          importedTxs.forEach(t => { currentMap.set(t.id, t); });
          return Array.from(currentMap.values());
      });
  };

  // Portfolios
  const handleCreatePortfolio = (name: string) => { const newId = generateId(); setPortfolios([...portfolios, { id: newId, name }]); setActivePortfolioId(newId); };
  const handleRenamePortfolio = (id: string, newName: string) => { setPortfolios(prev => prev.map(p => p.id === id ? { ...p, name: newName } : p)); };
  const handleDeletePortfolio = (id: string) => {
    if (portfolios.length <= 1) { alert("Cannot delete last portfolio"); return; }
    setConfirmConfig({
        isOpen: true, title: 'Delete Portfolio', message: 'Delete entire portfolio and all data?', 
        onConfirm: () => {
             localStorage.removeItem(`transactions_${id}`); localStorage.removeItem(`prices_${id}`); localStorage.removeItem(`goals_${id}`);
             const newPortfolios = portfolios.filter(p => p.id !== id); setPortfolios(newPortfolios);
             if (activePortfolioId === id) setActivePortfolioId(newPortfolios[0].id);
             setConfirmConfig(prev => ({ ...prev, isOpen: false }));
        }
    });
  };

  // Goals
  const handleSetNewGoal = (targetAmount: number, notes: string) => {
    const now = new Date().toISOString();
    setGoals(prev => [...prev.map(g => !g.endDate ? { ...g, endDate: now, isAchieved: totalNetWorth >= g.targetAmount } : g), { id: generateId(), targetAmount, startDate: now, isAchieved: false, notes }]);
  };
  const handleEditGoal = (updatedGoal: FinancialGoal) => setGoals(prev => prev.map(g => g.id === updatedGoal.id ? updatedGoal : g));
  const handleDeleteGoal = (id: string) => setGoals(prev => prev.filter(g => g.id !== id));

  return (
    <Layout 
      activeTab={activeTab} setActiveTab={setActiveTab} onOpenAddModal={handleOpenAddModal}
      portfolios={portfolios} activePortfolioId={activePortfolioId} onSwitchPortfolio={setActivePortfolioId}
      onCreatePortfolio={handleCreatePortfolio} onRenamePortfolio={handleRenamePortfolio} onDeletePortfolio={handleDeletePortfolio}
    >
      <div key={activePortfolioId} className="h-full">
        {activeTab === 'dashboard' && <Dashboard isLoading={isLoading} holdings={holdings} transactions={transactions} financialGoal={activeGoal.targetAmount} onOpenGoalModal={() => setIsGoalModalOpen(true)} investedAmount={investedAmount} cashBalance={cashBalance} portfolioValue={portfolioValue} chartData={chartData} />}
        {activeTab === 'holdings' && <Holdings isLoading={isLoading} holdings={holdings} transactions={transactions} onUpdatePrice={handleUpdatePrice} />}
        {activeTab === 'history' && <History isLoading={isLoading} transactions={transactions} onDelete={handleRequestDelete} onEdit={handleOpenEditModal} onAdd={handleOpenAddModal} onImport={handleImportTransactions} />}
        {activeTab === 'reports' && <Reports isLoading={isLoading} transactions={transactions} currentPortfolioValue={portfolioValue + cashBalance} chartData={chartData} />}
      </div>

      {isAddModalOpen && (
        <div className="fixed inset-0 z-50 flex items-end sm:items-center justify-center sm:p-4">
          <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-sm animate-fade-in" onClick={() => setIsAddModalOpen(false)}></div>
          <div className="relative bg-white dark:bg-slate-900 w-full max-w-lg rounded-t-3xl sm:rounded-3xl shadow-2xl overflow-hidden animate-slide-up flex flex-col max-h-[95dvh] sm:max-h-[90vh]">
            <AddTransactionForm onClose={() => setIsAddModalOpen(false)} onSave={handleSaveTransaction} onDelete={handleRequestDelete} cashBalance={cashBalance} holdings={holdings} prices={prices} transactions={transactions} initialData={editingTransaction} />
          </div>
        </div>
      )}

      <GoalModal isOpen={isGoalModalOpen} onClose={() => setIsGoalModalOpen(false)} goals={goals} currentNetWorth={totalNetWorth} onSetGoal={handleSetNewGoal} onEditGoal={handleEditGoal} onDeleteGoal={handleDeleteGoal} />

      {confirmConfig.isOpen && (
        <div className="fixed inset-0 z-[70] flex items-center justify-center p-4 animate-fade-in">
          <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-sm" onClick={() => setConfirmConfig(prev => ({ ...prev, isOpen: false }))}></div>
          <div className="relative bg-white dark:bg-slate-900 rounded-2xl shadow-2xl w-full max-w-sm overflow-hidden animate-zoom-in p-6 text-center">
              <Trash2 size={40} className="mx-auto text-rose-500 mb-4" />
              <h3 className="text-lg font-bold text-slate-900 dark:text-white mb-2">{confirmConfig.title}</h3>
              <p className="text-sm text-slate-500 dark:text-slate-400 mb-6">{confirmConfig.message}</p>
              <div className="flex space-x-3">
                <button onClick={() => setConfirmConfig(prev => ({ ...prev, isOpen: false }))} className="flex-1 py-3 rounded-xl font-bold bg-slate-100 dark:bg-slate-800 text-slate-600 dark:text-slate-400">Cancel</button>
                <button onClick={confirmConfig.onConfirm} className="flex-1 py-3 rounded-xl font-bold bg-rose-600 text-white shadow-lg shadow-rose-600/20">Delete</button>
              </div>
          </div>
        </div>
      )}
    </Layout>
  );
};

interface AddTransactionFormProps {
  onClose: () => void;
  onSave: (t: Transaction) => Promise<void>;
  onDelete?: (id: string) => void;
  cashBalance: number;
  holdings: Holding[];
  prices: Record<string, number>;
  transactions: Transaction[];
  initialData: Transaction | null;
}

const AddTransactionForm: React.FC<AddTransactionFormProps> = ({ onClose, onSave, onDelete, cashBalance, holdings, prices, transactions, initialData }) => {
  const [type, setType] = useState<TransactionType>(TransactionType.BUY);
  const [date, setDate] = useState(new Date().toISOString().split('T')[0]);
  const [symbol, setSymbol] = useState('');
  const [shares, setShares] = useState('');
  const [price, setPrice] = useState(''); // Price per share
  const [totalAmount, setTotalAmount] = useState(''); // Total transaction value
  const [fee, setFee] = useState('');
  const [assetClass, setAssetClass] = useState<AssetClass>(AssetClass.STOCK);
  const [exchangeRate, setExchangeRate] = useState(''); 
  const [notes, setNotes] = useState('');
  const [error, setError] = useState<string | null>(null);
  const [isSaving, setIsSaving] = useState(false);
  const [activeInput, setActiveInput] = useState<'shares' | 'price' | 'total' | null>(null);
  const [showSuggestions, setShowSuggestions] = useState(false);
  const wrapperRef = useRef<HTMLDivElement>(null);

  // Helper: Get color based on type
  const getTypeColor = (t: TransactionType) => {
    switch (t) {
        case TransactionType.BUY: return 'blue';
        case TransactionType.DEPOSIT: return 'blue';
        case TransactionType.SELL: return 'rose';
        case TransactionType.WITHDRAW: return 'rose';
        case TransactionType.DIVIDEND: return 'emerald';
        case TransactionType.SPLIT: return 'purple';
        default: return 'slate';
    }
  }

  const themeColor = getTypeColor(type);

  // Validation logic helpers
  const needsSymbol = [TransactionType.BUY, TransactionType.SELL, TransactionType.DIVIDEND, TransactionType.SPLIT].includes(type);
  const needsShares = [TransactionType.BUY, TransactionType.SELL, TransactionType.SPLIT].includes(type);
  const needsPrice = type !== TransactionType.SPLIT;
  const isFunding = type === TransactionType.DEPOSIT || type === TransactionType.WITHDRAW;

  // Effects (Initialization, Auto-fill, Calculation)
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => { if (wrapperRef.current && !wrapperRef.current.contains(event.target as Node)) setShowSuggestions(false); };
    document.addEventListener("mousedown", handleClickOutside); return () => document.removeEventListener("mousedown", handleClickOutside);
  }, []);

  useEffect(() => {
    if (initialData) {
      setType(initialData.type); setDate(initialData.date); setSymbol(initialData.symbol || '');
      setShares(initialData.shares?.toString() || ''); setPrice(initialData.price?.toString() || '');
      setFee(initialData.fee?.toString() || ''); setAssetClass(initialData.assetClass || AssetClass.STOCK);
      setExchangeRate(initialData.exchangeRate?.toString() || ''); setNotes(initialData.notes || '');
      if (initialData.shares && initialData.price && (initialData.type === TransactionType.BUY || initialData.type === TransactionType.SELL)) {
         setTotalAmount((initialData.shares * initialData.price).toFixed(2));
      } else if (initialData.price) setTotalAmount(initialData.price.toString());
    }
  }, [initialData]);

  useEffect(() => {
    if (!initialData && symbol && !price && !activeInput) {
       const h = holdings.find(h => h.symbol === symbol.toUpperCase());
       if (h) { setAssetClass(h.assetClass); if (h.currentPrice > 0) setPrice(h.currentPrice.toString()); }
       else { const kp = prices[symbol.toUpperCase()]; if (kp) setPrice(kp.toString()); }
    }
  }, [symbol]);

  useEffect(() => {
    const s = parseFloat(shares) || 0; const p = parseFloat(price) || 0; const t = parseFloat(totalAmount) || 0;
    if ((activeInput === 'shares' || activeInput === 'price') && s > 0 && p > 0) setTotalAmount((s * p).toFixed(2));
    if (activeInput === 'total' && t > 0 && p > 0) setShares((t / p).toFixed(4));
  }, [shares, price, totalAmount, activeInput]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (needsSymbol && !symbol) return setError("Symbol required");
    setIsSaving(true);
    await onSave({
      id: initialData ? initialData.id : generateId(),
      date, type, symbol: needsSymbol ? symbol.toUpperCase() : undefined,
      shares: needsShares ? parseFloat(shares) : undefined,
      price: type === TransactionType.SPLIT ? 0 : parseFloat(price),
      fee: (fee && (type === TransactionType.BUY || type === TransactionType.SELL)) ? parseFloat(fee) : undefined,
      assetClass: !needsSymbol ? AssetClass.CASH : assetClass,
      exchangeRate: exchangeRate ? parseFloat(exchangeRate) : 1, notes: notes || undefined
    });
    setIsSaving(false);
  };

  const suggestions = useMemo(() => {
    if (!symbol) return [];
    const inputUpper = symbol.toUpperCase();
    return Array.from(new Set([...holdings.map(h => h.symbol), ...POPULAR_SYMBOLS])).filter(s => s.includes(inputUpper)).slice(0, 5);
  }, [symbol, holdings]);

  return (
    <>
      <div className="shrink-0 p-5 border-b border-slate-100 dark:border-slate-800 flex justify-between items-center bg-white dark:bg-slate-900">
          <h3 className="text-xl font-display font-bold text-slate-900 dark:text-white">{initialData ? 'Edit Details' : 'New Transaction'}</h3>
          <button onClick={onClose} className="bg-slate-100 dark:bg-slate-800 p-2 rounded-full text-slate-500 hover:text-slate-800 dark:hover:text-white transition-colors"><X size={20} /></button>
      </div>

      <form onSubmit={handleSubmit} className="flex-1 overflow-y-auto min-h-0 p-5 space-y-6 custom-scrollbar bg-slate-50/50 dark:bg-slate-900/50">

        {/* 1. Transaction Type Selector (Segmented) */}
        <div className="bg-slate-200 dark:bg-slate-800 p-1 rounded-xl flex overflow-x-auto no-scrollbar">
           {[TransactionType.BUY, TransactionType.SELL, TransactionType.DEPOSIT, TransactionType.WITHDRAW, TransactionType.DIVIDEND, TransactionType.SPLIT].map(t => (
             <button
                key={t} type="button" onClick={() => setType(t)}
                className={`flex-1 min-w-[60px] py-2 px-3 rounded-lg text-xs font-bold transition-all whitespace-nowrap ${type === t ? 'bg-white dark:bg-slate-700 text-slate-900 dark:text-white shadow-sm scale-100' : 'text-slate-500 dark:text-slate-400 hover:text-slate-700'}`}
             >
                {t}
             </button>
           ))}
        </div>

        {/* 2. BIG INPUTS SECTION */}
        <div className="space-y-4">
             {needsSymbol && (
                <div className="relative z-20" ref={wrapperRef}>
                    <label className="text-[10px] font-bold text-slate-400 uppercase tracking-wider mb-1 block">Asset Symbol</label>
                    <div className="relative">
                        <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
                        <input 
                           type="text" placeholder="e.g. AAPL" value={symbol} 
                           onChange={e => { setSymbol(e.target.value); setShowSuggestions(true); }}
                           onFocus={() => setShowSuggestions(true)}
                           className="w-full pl-12 pr-4 py-4 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-2xl text-lg font-bold uppercase tracking-wide focus:ring-2 focus:ring-blue-500 outline-none shadow-sm"
                        />
                         {showSuggestions && suggestions.length > 0 && (
                            <div className="absolute top-full left-0 right-0 mt-2 bg-white dark:bg-slate-800 rounded-xl shadow-xl border border-slate-100 dark:border-slate-700 overflow-hidden z-50">
                                {suggestions.map(s => (
                                    <div key={s} onMouseDown={(e) => { e.preventDefault(); setSymbol(s); setShowSuggestions(false); }} className="px-4 py-3 hover:bg-slate-50 dark:hover:bg-slate-700 cursor-pointer font-bold text-slate-700 dark:text-slate-300">{s}</div>
                                ))}
                            </div>
                        )}
                    </div>
                </div>
             )}

             {/* The Big Money Input */}
             {(needsPrice || isFunding) && (
                <div>
                   <label className="text-[10px] font-bold text-slate-400 uppercase tracking-wider mb-1 block">
                       {needsShares ? 'Total Amount' : 'Amount'}
                   </label>
                   <div className="relative">
                       <span className={`absolute left-4 top-1/2 -translate-y-1/2 text-2xl font-bold ${type === TransactionType.SELL || type === TransactionType.WITHDRAW ? 'text-rose-500' : 'text-blue-500'}`}>$</span>
                       <input 
                          type="number" step="any" min="0" placeholder="0.00"
                          value={totalAmount}
                          onFocus={() => setActiveInput('total')}
                          onChange={e => setTotalAmount(e.target.value)}
                          className="w-full pl-10 pr-4 py-4 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-2xl text-3xl font-bold text-slate-900 dark:text-white focus:ring-2 focus:ring-blue-500 outline-none shadow-sm"
                       />
                   </div>
                </div>
             )}
        </div>

        {/* 3. DETAILS GRID */}
        <div className="grid grid-cols-2 gap-4">
            <div>
               <label className="text-[10px] font-bold text-slate-400 uppercase tracking-wider mb-1 block">Date</label>
               <input type="date" value={date} onChange={e => setDate(e.target.value)} className="w-full px-4 py-3 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl font-medium text-sm focus:ring-2 focus:ring-blue-500 outline-none" />
            </div>

            {needsShares && (
                <div>
                    <label className="text-[10px] font-bold text-slate-400 uppercase tracking-wider mb-1 block">
                        {type === TransactionType.SPLIT ? 'Split Ratio (e.g. 2)' : 'Shares / Qty'}
                    </label>
                    <input 
                        type="number" step="any" 
                        placeholder={type === TransactionType.SPLIT ? "2.0" : "0"} 
                        value={shares}
                        onFocus={() => setActiveInput('shares')}
                        onChange={e => setShares(e.target.value)}
                        className="w-full px-4 py-3 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl font-medium text-sm focus:ring-2 focus:ring-blue-500 outline-none"
                    />
                </div>
            )}

            {needsPrice && needsShares && (
                <div>
                   <label className="text-[10px] font-bold text-slate-400 uppercase tracking-wider mb-1 block">Price / Share</label>
                   <input 
                      type="number" step="any" placeholder="0.00" value={price}
                      onFocus={() => setActiveInput('price')}
                      onChange={e => setPrice(e.target.value)}
                      className="w-full px-4 py-3 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl font-medium text-sm focus:ring-2 focus:ring-blue-500 outline-none"
                   />
                </div>
            )}

             {needsSymbol && (
                <div>
                    <label className="text-[10px] font-bold text-slate-400 uppercase tracking-wider mb-1 block">Asset Class</label>
                    <select value={assetClass} onChange={e => setAssetClass(e.target.value as AssetClass)} className="w-full px-4 py-3 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl font-medium text-sm outline-none">
                        {Object.values(AssetClass).filter(a => a !== AssetClass.CASH).map(a => <option key={a} value={a}>{a}</option>)}
                    </select>
                </div>
             )}
        </div>

        {/* 4. EXPANDABLE OPTIONAL FIELDS */}
        <details className="group">
            <summary className="flex items-center text-xs font-bold text-slate-400 uppercase tracking-wider cursor-pointer list-none mb-3">
               <PlusCircle size={14} className="mr-1 group-open:hidden" />
               <MinusCircle size={14} className="mr-1 hidden group-open:block" />
               Optional Details (Fee, FX, Notes)
            </summary>
            <div className="space-y-4 pt-2 animate-fade-in">
                 {(type === TransactionType.BUY || type === TransactionType.SELL) && (
                     <div>
                        <label className="text-[10px] font-bold text-slate-400 uppercase tracking-wider mb-1 block">Transaction Fee</label>
                        <input type="number" placeholder="0.00" value={fee} onChange={e => setFee(e.target.value)} className="w-full px-4 py-3 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl text-sm" />
                     </div>
                 )}
                 {isFunding && (
                     <div>
                        <label className="text-[10px] font-bold text-slate-400 uppercase tracking-wider mb-1 block">Exchange Rate (Local/USD)</label>
                        <input type="number" placeholder="1.0" value={exchangeRate} onChange={e => setExchangeRate(e.target.value)} className="w-full px-4 py-3 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl text-sm" />
                     </div>
                 )}
                 <div>
                    <label className="text-[10px] font-bold text-slate-400 uppercase tracking-wider mb-1 block">Notes</label>
                    <textarea rows={2} placeholder="Add a memo..." value={notes} onChange={e => setNotes(e.target.value)} className="w-full px-4 py-3 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl text-sm" />
                 </div>
            </div>
        </details>
      </form>

      {/* 5. FOOTER ACTIONS */}
      <div className="p-5 border-t border-slate-100 dark:border-slate-800 bg-white dark:bg-slate-900 z-10">
         {error && (
            <div className="bg-rose-50 text-rose-600 px-4 py-3 rounded-xl text-sm font-bold flex items-center mb-4">
                <AlertCircle size={16} className="mr-2" /> {error}
            </div>
         )}
         <div className="flex gap-3">
             {initialData && onDelete && (
                 <button type="button" onClick={() => onDelete(initialData.id)} className="p-4 rounded-xl bg-rose-50 text-rose-500 hover:bg-rose-100 transition-colors"><Trash2 size={20} /></button>
             )}
             <button 
                onClick={handleSubmit} disabled={isSaving}
                className={`flex-1 py-4 rounded-xl font-bold text-lg text-white shadow-xl transition-all active:scale-95 flex items-center justify-center ${isSaving ? 'bg-slate-400 cursor-not-allowed' : `bg-${themeColor}-600 hover:bg-${themeColor}-700 shadow-${themeColor}-500/30`}`}
             >
                {isSaving ? <Spinner className="text-white" /> : (initialData ? 'Update' : 'Save Transaction')}
             </button>
         </div>
      </div>
    </>
  );
};

export default App;

import React, { useState, useMemo, useRef } from 'react';
import { Transaction, TransactionType, AssetClass } from '../types';
import { Search, Calendar, Filter, Trash2, ArrowUpDown, XCircle, Edit2, Plus, Download, Upload, TrendingUp, TrendingDown, RefreshCcw, DollarSign, Wallet, Split } from 'lucide-react';
import { formatCurrency, formatNumber, transactionsToCSV, csvToTransactions } from '../utils';
import { HistorySkeleton } from './LoadingSkeletons';

interface HistoryProps {
  transactions: Transaction[];
  onDelete: (id: string) => void;
  onEdit: (tx: Transaction) => void;
  onAdd: () => void;
  onImport: (txs: Transaction[]) => void;
  isLoading?: boolean;
}

const History: React.FC<HistoryProps> = ({ transactions, onDelete, onEdit, onAdd, onImport, isLoading }) => {
  // Filters State
  const [searchTerm, setSearchTerm] = useState('');
  const [typeFilter, setTypeFilter] = useState<TransactionType | 'ALL'>('ALL');
  const [assetClassFilter, setAssetClassFilter] = useState<AssetClass | 'ALL'>('ALL');
  const [startDate, setStartDate] = useState('');
  const [endDate, setEndDate] = useState('');
  const [sortOrder, setSortOrder] = useState<'desc' | 'asc'>('desc');
  const [showFilters, setShowFilters] = useState(false);

  const fileInputRef = useRef<HTMLInputElement>(null);

  // Logic
  const filteredTransactions = useMemo(() => {
    return transactions.filter(tx => {
      // 1. Search (Symbol, Notes)
      const searchLower = searchTerm.toLowerCase();
      const matchesSearch = 
        (tx.symbol?.toLowerCase().includes(searchLower) ?? false) ||
        (tx.notes?.toLowerCase().includes(searchLower) ?? false) ||
        (tx.type.toLowerCase().includes(searchLower));

      // 2. Type Filter
      const matchesType = typeFilter === 'ALL' || tx.type === typeFilter;

      // 3. Asset Class Filter
      const matchesAsset = assetClassFilter === 'ALL' || tx.assetClass === assetClassFilter;

      // 4. Date Range
      const txDate = new Date(tx.date).getTime();
      const start = startDate ? new Date(startDate).getTime() : -Infinity;
      const end = endDate ? new Date(endDate).getTime() : Infinity;
      const matchesDate = txDate >= start && txDate <= end;

      return matchesSearch && matchesType && matchesAsset && matchesDate;
    }).sort((a, b) => {
      const dateA = new Date(a.date).getTime();
      const dateB = new Date(b.date).getTime();
      return sortOrder === 'desc' ? dateB - dateA : dateA - dateB;
    });
  }, [transactions, searchTerm, typeFilter, assetClassFilter, startDate, endDate, sortOrder]);

  const resetFilters = () => {
    setSearchTerm('');
    setTypeFilter('ALL');
    setAssetClassFilter('ALL');
    setStartDate('');
    setEndDate('');
  };

  const handleImportClick = () => fileInputRef.current?.click();

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (evt) => {
      const content = evt.target?.result as string;
      if (content) {
        const imported = csvToTransactions(content);
        if (imported.length > 0) onImport(imported);
        else alert("No valid transactions found.");
      }
    };
    reader.readAsText(file);
    e.target.value = '';
  };

  const handleExport = () => {
    const csv = transactionsToCSV(transactions);
    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.setAttribute('download', `portfolio_backup_${new Date().toISOString().split('T')[0]}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  if (isLoading) return <HistorySkeleton />;

  const hasActiveFilters = searchTerm || typeFilter !== 'ALL' || assetClassFilter !== 'ALL' || startDate || endDate;

  // Helper for Icons
  const getIconForType = (type: TransactionType) => {
      switch(type) {
          case TransactionType.BUY: return <TrendingUp size={16} />;
          case TransactionType.SELL: return <TrendingDown size={16} />;
          case TransactionType.DEPOSIT: return <Wallet size={16} />;
          case TransactionType.WITHDRAW: return <Wallet size={16} />;
          case TransactionType.DIVIDEND: return <DollarSign size={16} />;
          case TransactionType.SPLIT: return <Split size={16} />;
          default: return <RefreshCcw size={16} />;
      }
  };

  const getColorForType = (type: TransactionType) => {
      switch(type) {
          case TransactionType.BUY: return 'bg-blue-100 text-blue-600 dark:bg-blue-900/30 dark:text-blue-400';
          case TransactionType.SELL: return 'bg-rose-100 text-rose-600 dark:bg-rose-900/30 dark:text-rose-400';
          case TransactionType.DEPOSIT: return 'bg-indigo-100 text-indigo-600 dark:bg-indigo-900/30 dark:text-indigo-400';
          case TransactionType.WITHDRAW: return 'bg-orange-100 text-orange-600 dark:bg-orange-900/30 dark:text-orange-400';
          case TransactionType.DIVIDEND: return 'bg-emerald-100 text-emerald-600 dark:bg-emerald-900/30 dark:text-emerald-400';
          case TransactionType.SPLIT: return 'bg-purple-100 text-purple-600 dark:bg-purple-900/30 dark:text-purple-400';
          default: return 'bg-slate-100 text-slate-600 dark:bg-slate-800 dark:text-slate-400';
      }
  }

  return (
    <div className="space-y-6 animate-fade-in pb-12">
      <input type="file" accept=".csv" ref={fileInputRef} onChange={handleFileChange} className="hidden" />

      {/* Header Area */}
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
           <div>
              <h2 className="text-2xl font-display font-bold text-slate-900 dark:text-white">Activity</h2>
              <p className="text-slate-500 text-sm">{filteredTransactions.length} transactions</p>
           </div>

           <div className="flex items-center gap-2">
             <div className="relative flex-1 md:w-64">
               <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={16} />
               <input 
                 type="text" placeholder="Search..." 
                 value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)}
                 className="w-full pl-9 pr-4 py-2 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl text-sm outline-none focus:ring-2 focus:ring-blue-500"
               />
             </div>
             <button onClick={() => setShowFilters(!showFilters)} className={`p-2 rounded-xl border ${showFilters || hasActiveFilters ? 'bg-blue-50 border-blue-200 text-blue-600' : 'bg-white border-slate-200 text-slate-500'} transition-colors`}>
                <Filter size={20} />
             </button>
             <button onClick={onAdd} className="hidden md:flex items-center space-x-2 bg-slate-900 text-white px-4 py-2 rounded-xl font-bold text-sm hover:opacity-90">
                 <Plus size={16} /> <span>New</span>
             </button>
             {/* Mobile Add */}
             <button onClick={onAdd} className="md:hidden p-2 bg-slate-900 text-white rounded-xl shadow-lg">
                 <Plus size={20} />
             </button>
           </div>
      </div>

      {/* Collapsible Filters */}
      {showFilters && (
        <div className="bg-white dark:bg-slate-800 p-4 rounded-xl border border-slate-200 dark:border-slate-700 shadow-sm grid grid-cols-2 md:grid-cols-4 gap-3 animate-slide-up">
           <select value={typeFilter} onChange={(e) => setTypeFilter(e.target.value as any)} className="bg-slate-50 dark:bg-slate-900 border border-slate-200 dark:border-slate-700 rounded-lg px-3 py-2 text-sm outline-none"><option value="ALL">All Types</option>{Object.values(TransactionType).map(t => <option key={t} value={t}>{t}</option>)}</select>
           <select value={assetClassFilter} onChange={(e) => setAssetClassFilter(e.target.value as any)} className="bg-slate-50 dark:bg-slate-900 border border-slate-200 dark:border-slate-700 rounded-lg px-3 py-2 text-sm outline-none"><option value="ALL">All Assets</option>{Object.values(AssetClass).map(a => <option key={a} value={a}>{a}</option>)}</select>
           <input type="date" value={startDate} onChange={(e) => setStartDate(e.target.value)} className="bg-slate-50 dark:bg-slate-900 border border-slate-200 dark:border-slate-700 rounded-lg px-3 py-2 text-sm outline-none" />
           <div className="flex gap-2">
              <input type="date" value={endDate} onChange={(e) => setEndDate(e.target.value)} className="flex-1 bg-slate-50 dark:bg-slate-900 border border-slate-200 dark:border-slate-700 rounded-lg px-3 py-2 text-sm outline-none" />
              {hasActiveFilters && <button onClick={resetFilters} className="text-rose-500 p-2"><XCircle size={20} /></button>}
           </div>
           <div className="col-span-2 md:col-span-4 flex justify-end gap-2 pt-2 border-t border-slate-100 dark:border-slate-700">
              <button onClick={handleImportClick} className="text-xs font-bold text-blue-600 flex items-center"><Upload size={12} className="mr-1"/> Import CSV</button>
              <button onClick={handleExport} className="text-xs font-bold text-blue-600 flex items-center ml-4"><Download size={12} className="mr-1"/> Export CSV</button>
           </div>
        </div>
      )}

      {/* Modern List View */}
      <div className="bg-white dark:bg-slate-800 rounded-2xl shadow-sm border border-slate-200 dark:border-slate-700 overflow-hidden min-h-[400px]">
         <div className="divide-y divide-slate-100 dark:divide-slate-800">
            {filteredTransactions.map(tx => {
               const isPositive = tx.type === 'SELL' || tx.type === 'DIVIDEND' || tx.type === 'DEPOSIT';
               const amount = (tx.type === 'BUY' || tx.type === 'SELL') ? (tx.price! * tx.shares!) : tx.price!;

               return (
                 <div 
                   key={tx.id} 
                   onClick={() => onEdit(tx)}
                   className="p-4 hover:bg-slate-50 dark:hover:bg-slate-700/30 transition-colors cursor-pointer flex items-center justify-between group"
                 >
                    <div className="flex items-center space-x-4">
                       {/* Icon Box */}
                       <div className={`w-10 h-10 rounded-xl flex items-center justify-center shrink-0 ${getColorForType(tx.type)}`}>
                          {getIconForType(tx.type)}
                       </div>

                       <div>
                          <div className="font-bold text-slate-900 dark:text-white text-sm">
                             {tx.symbol || (tx.type === 'DEPOSIT' || tx.type === 'WITHDRAW' ? 'Cash Transfer' : tx.type)}
                          </div>
                          <div className="text-xs text-slate-500 dark:text-slate-400 flex items-center mt-0.5">
                             <span>{new Date(tx.date).toLocaleDateString()}</span>
                             <span className="mx-1.5">•</span>
                             <span className="uppercase">{tx.type}</span>
                          </div>
                       </div>
                    </div>

                    <div className="text-right">
                       <div className={`font-mono font-bold text-sm ${isPositive ? 'text-emerald-600 dark:text-emerald-400' : 'text-slate-900 dark:text-white'}`}>
                          {isPositive ? '+' : ''}{tx.type === 'SPLIT' ? '-' : formatCurrency(amount)}
                       </div>
                       {tx.shares && tx.shares > 0 && (
                          <div className="text-xs text-slate-400 mt-0.5">
                             {formatNumber(tx.shares)} {tx.type === 'SPLIT' ? 'ratio' : 'shares'}
                          </div>
                       )}
                    </div>
                 </div>
               );
            })}

            {filteredTransactions.length === 0 && (
                <div className="p-12 text-center text-slate-400">
                   <p>No transactions found.</p>
                </div>
            )}
         </div>
      </div>
    </div>
  );
};

export default History;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import Layout from './components/Layout';
import Dashboard from './components/Dashboard';
import Holdings from './components/Holdings';
import Reports from './components/Reports';
import History from './components/History';
import GoalModal from './components/GoalModal';
import { Transaction, TransactionType, AssetClass, Holding, Portfolio, FinancialGoal } from './types';
import { calculateHoldings, calculatePortfolioHistory, generateId, formatCurrency, formatNumber } from './utils';
import { X, Save, TrendingUp, TrendingDown, DollarSign, Wallet, Calendar, GitFork, AlertCircle, ArrowRight, Trash2, Zap, Calculator, Search, Clock, PlusCircle, MinusCircle, RefreshCcw, Split, Hash } from 'lucide-react';
import { Spinner } from './components/LoadingSkeletons';

const POPULAR_SYMBOLS = [
  'AAPL', 'MSFT', 'GOOGL', 'AMZN', 'NVDA', 'TSLA', 'META', 'BRK.B', 'V', 'JNJ', 'WMT', 'JPM', // Tech/Blue Chip
  'VOO', 'VTI', 'QQQ', 'IVV', 'SCHD', 'JEPI', 'VUG', 'VTV', // ETFs
  'BTC', 'ETH', 'SOL', 'USDT', 'BNB', 'XRP', 'ADA' // Crypto
];

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState('dashboard');
  const [isAddModalOpen, setIsAddModalOpen] = useState(false);
  const [editingTransaction, setEditingTransaction] = useState<Transaction | null>(null);

  // Goal Modal State
  const [isGoalModalOpen, setIsGoalModalOpen] = useState(false);

  // --- CONFIRMATION MODAL STATE ---
  const [confirmConfig, setConfirmConfig] = useState<{
    isOpen: boolean;
    title: string;
    message: string;
    onConfirm: () => void;
  }>({
    isOpen: false,
    title: '',
    message: '',
    onConfirm: () => {},
  });

  // --- PORTFOLIO MANAGEMENT STATE ---
  const [portfolios, setPortfolios] = useState<Portfolio[]>(() => {
    const saved = localStorage.getItem('portfolios');
    if (saved) return JSON.parse(saved);
    const legacyTx = localStorage.getItem('transactions');
    if (legacyTx) return [{ id: 'default', name: 'Main Portfolio' }];
    return [{ id: generateId(), name: 'My First Portfolio' }];
  });

  const [activePortfolioId, setActivePortfolioId] = useState<string>(() => {
    const saved = localStorage.getItem('activePortfolioId');
    const portfolios = JSON.parse(localStorage.getItem('portfolios') || '[]');
    if (saved && portfolios.some((p: Portfolio) => p.id === saved)) return saved;
    return portfolios.length > 0 ? portfolios[0].id : 'default';
  });

  // --- DATA STATE (Per Portfolio) - Synchronous Initialization ---
  const [transactions, setTransactions] = useState<Transaction[]>(() => {
    const key = `transactions_${activePortfolioId}`;
    const saved = localStorage.getItem(key);
    if (saved) return JSON.parse(saved);
    if (activePortfolioId === 'default') {
      const legacy = localStorage.getItem('transactions');
      if (legacy) return JSON.parse(legacy);
    }
    return [];
  });

  const [prices, setPrices] = useState<Record<string, number>>(() => {
    const key = `prices_${activePortfolioId}`;
    const saved = localStorage.getItem(key);
    if (saved) return JSON.parse(saved);
    if (activePortfolioId === 'default') {
      const legacy = localStorage.getItem('prices');
      if (legacy) return JSON.parse(legacy);
    }
    return {};
  });

  const [goals, setGoals] = useState<FinancialGoal[]>(() => {
    const key = `goals_${activePortfolioId}`;
    const saved = localStorage.getItem(key);
    if (saved) return JSON.parse(saved);

    let legacyGoal = 100000;
    const legacyKey = `financialGoal_${activePortfolioId}`;
    const savedLegacy = localStorage.getItem(legacyKey);
    if (savedLegacy) legacyGoal = parseFloat(savedLegacy);
    else if (activePortfolioId === 'default' && localStorage.getItem('financialGoal')) legacyGoal = parseFloat(localStorage.getItem('financialGoal')!);

    return [{ id: generateId(), targetAmount: legacyGoal, startDate: new Date().toISOString(), isAchieved: false, notes: 'Initial Goal' }];
  });

  const [isDataLoaded, setIsDataLoaded] = useState(true);
  const [isLoading, setIsLoading] = useState(false);
  const isFirstMount = useRef(true);

  // --- PERSISTENCE ---
  useEffect(() => { localStorage.setItem('portfolios', JSON.stringify(portfolios)); }, [portfolios]);
  useEffect(() => { localStorage.setItem('activePortfolioId', activePortfolioId); }, [activePortfolioId]);

  useEffect(() => {
    if (isFirstMount.current) { isFirstMount.current = false; return; }
    setIsLoading(true);
    setIsDataLoaded(false);
    const loadData = () => {
        const txKey = `transactions_${activePortfolioId}`;
        const pricesKey = `prices_${activePortfolioId}`;
        const goalsKey = `goals_${activePortfolioId}`;

        const savedTx = localStorage.getItem(txKey);
        setTransactions(savedTx ? JSON.parse(savedTx) : []);

        const savedPrices = localStorage.getItem(pricesKey);
        setPrices(savedPrices ? JSON.parse(savedPrices) : {});

        const savedGoals = localStorage.getItem(goalsKey);
        setGoals(savedGoals ? JSON.parse(savedGoals) : []); 

        setIsDataLoaded(true);
        setTimeout(() => setIsLoading(false), 500);
    };
    requestAnimationFrame(loadData);
  }, [activePortfolioId]);

  useEffect(() => { if (isDataLoaded) localStorage.setItem(`transactions_${activePortfolioId}`, JSON.stringify(transactions)); }, [transactions, activePortfolioId, isDataLoaded]);
  useEffect(() => { if (isDataLoaded) localStorage.setItem(`prices_${activePortfolioId}`, JSON.stringify(prices)); }, [prices, activePortfolioId, isDataLoaded]);
  useEffect(() => { if (isDataLoaded) localStorage.setItem(`goals_${activePortfolioId}`, JSON.stringify(goals)); }, [goals, activePortfolioId, isDataLoaded]);

  // --- CALCULATIONS ---
  const holdings = useMemo(() => calculateHoldings(transactions, prices), [transactions, prices]);
  const chartData = useMemo(() => calculatePortfolioHistory(transactions, prices), [transactions, prices]);
  const investedAmount = transactions.reduce((sum, t) => {
    if (t.type === TransactionType.DEPOSIT) return sum + (t.price || 0);
    if (t.type === TransactionType.WITHDRAW) return sum - (t.price || 0);
    return sum;
  }, 0);
  const cashBalance = useMemo(() => {
    let balance = 0;
    transactions.forEach(t => {
      if (t.type === TransactionType.DEPOSIT) balance += (t.price || 0);
      if (t.type === TransactionType.WITHDRAW) balance -= (t.price || 0);
      if (t.type === TransactionType.BUY) balance -= (t.price! * t.shares!) + (t.fee || 0);
      if (t.type === TransactionType.SELL) balance += (t.price! * t.shares!) - (t.fee || 0);
      if (t.type === TransactionType.DIVIDEND) balance += (t.price || 0);
    });
    return balance;
  }, [transactions]);
  const portfolioValue = holdings.reduce((sum, h) => sum + h.marketValue, 0);
  const totalNetWorth = portfolioValue + cashBalance;
  const activeGoal = useMemo(() => goals.find(g => !g.endDate) || { targetAmount: 100000 } as FinancialGoal, [goals]);

  // --- HANDLERS ---
  const handleOpenAddModal = () => { setEditingTransaction(null); setIsAddModalOpen(true); };
  const handleOpenEditModal = (tx: Transaction) => { setEditingTransaction(tx); setIsAddModalOpen(true); };
  const handleSaveTransaction = (tx: Transaction) => {
    return new Promise<void>((resolve) => {
      if (editingTransaction) setTransactions(prev => prev.map(t => t.id === tx.id ? tx : t));
      else setTransactions(prev => [...prev, tx]);
      if ((tx.type === TransactionType.BUY || tx.type === TransactionType.SELL) && tx.symbol && tx.price) setPrices(prev => ({...prev, [tx.symbol!]: tx.price!}));
      setIsAddModalOpen(false); setEditingTransaction(null); resolve();
    });
  };
  const handleUpdatePrice = (symbol: string, newPrice: number) => setPrices(prev => ({ ...prev, [symbol]: newPrice }));
  const handleDeleteTransaction = (id: string) => {
    setTransactions(prev => prev.filter(t => t.id !== id));
    if (editingTransaction && editingTransaction.id === id) { setIsAddModalOpen(false); setEditingTransaction(null); }
  };
  const handleRequestDelete = (id: string) => {
      setConfirmConfig({ isOpen: true, title: 'Delete Transaction', message: 'Permanently remove this record?', onConfirm: () => { handleDeleteTransaction(id); setConfirmConfig(prev => ({ ...prev, isOpen: false })); } });
  };
  const handleImportTransactions = (importedTxs: Transaction[]) => {
      setTransactions(prev => {
          const currentMap = new Map(prev.map(t => [t.id, t]));
          importedTxs.forEach(t => { currentMap.set(t.id, t); });
          return Array.from(currentMap.values());
      });
  };

  // Portfolios
  const handleCreatePortfolio = (name: string) => { const newId = generateId(); setPortfolios([...portfolios, { id: newId, name }]); setActivePortfolioId(newId); };
  const handleRenamePortfolio = (id: string, newName: string) => { setPortfolios(prev => prev.map(p => p.id === id ? { ...p, name: newName } : p)); };
  const handleDeletePortfolio = (id: string) => {
    if (portfolios.length <= 1) { alert("Cannot delete last portfolio"); return; }
    setConfirmConfig({
        isOpen: true, title: 'Delete Portfolio', message: 'Delete entire portfolio and all data?', 
        onConfirm: () => {
             localStorage.removeItem(`transactions_${id}`); localStorage.removeItem(`prices_${id}`); localStorage.removeItem(`goals_${id}`);
             const newPortfolios = portfolios.filter(p => p.id !== id); setPortfolios(newPortfolios);
             if (activePortfolioId === id) setActivePortfolioId(newPortfolios[0].id);
             setConfirmConfig(prev => ({ ...prev, isOpen: false }));
        }
    });
  };

  // Goals
  const handleSetNewGoal = (targetAmount: number, notes: string) => {
    const now = new Date().toISOString();
    setGoals(prev => [...prev.map(g => !g.endDate ? { ...g, endDate: now, isAchieved: totalNetWorth >= g.targetAmount } : g), { id: generateId(), targetAmount, startDate: now, isAchieved: false, notes }]);
  };
  const handleEditGoal = (updatedGoal: FinancialGoal) => setGoals(prev => prev.map(g => g.id === updatedGoal.id ? updatedGoal : g));
  const handleDeleteGoal = (id: string) => setGoals(prev => prev.filter(g => g.id !== id));

  return (
    <Layout 
      activeTab={activeTab} setActiveTab={setActiveTab} onOpenAddModal={handleOpenAddModal}
      portfolios={portfolios} activePortfolioId={activePortfolioId} onSwitchPortfolio={setActivePortfolioId}
      onCreatePortfolio={handleCreatePortfolio} onRenamePortfolio={handleRenamePortfolio} onDeletePortfolio={handleDeletePortfolio}
    >
      <div key={activePortfolioId} className="h-full">
        {activeTab === 'dashboard' && <Dashboard isLoading={isLoading} holdings={holdings} transactions={transactions} financialGoal={activeGoal.targetAmount} onOpenGoalModal={() => setIsGoalModalOpen(true)} investedAmount={investedAmount} cashBalance={cashBalance} portfolioValue={portfolioValue} chartData={chartData} />}
        {activeTab === 'holdings' && <Holdings isLoading={isLoading} holdings={holdings} transactions={transactions} onUpdatePrice={handleUpdatePrice} />}
        {activeTab === 'history' && <History isLoading={isLoading} transactions={transactions} onDelete={handleRequestDelete} onEdit={handleOpenEditModal} onAdd={handleOpenAddModal} onImport={handleImportTransactions} />}
        {activeTab === 'reports' && <Reports isLoading={isLoading} transactions={transactions} currentPortfolioValue={portfolioValue + cashBalance} chartData={chartData} />}
      </div>

      {isAddModalOpen && (
        <div className="fixed inset-0 z-50 flex items-end sm:items-center justify-center sm:p-4">
          <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-sm animate-fade-in" onClick={() => setIsAddModalOpen(false)}></div>
          <div className="relative bg-white dark:bg-slate-900 w-full max-w-lg rounded-t-3xl sm:rounded-3xl shadow-2xl overflow-hidden animate-slide-up flex flex-col max-h-[95dvh] sm:max-h-[85vh]">
            <AddTransactionForm onClose={() => setIsAddModalOpen(false)} onSave={handleSaveTransaction} onDelete={handleRequestDelete} cashBalance={cashBalance} holdings={holdings} prices={prices} transactions={transactions} initialData={editingTransaction} />
          </div>
        </div>
      )}

      <GoalModal isOpen={isGoalModalOpen} onClose={() => setIsGoalModalOpen(false)} goals={goals} currentNetWorth={totalNetWorth} onSetGoal={handleSetNewGoal} onEditGoal={handleEditGoal} onDeleteGoal={handleDeleteGoal} />

      {confirmConfig.isOpen && (
        <div className="fixed inset-0 z-[70] flex items-center justify-center p-4 animate-fade-in">
          <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-sm" onClick={() => setConfirmConfig(prev => ({ ...prev, isOpen: false }))}></div>
          <div className="relative bg-white dark:bg-slate-900 rounded-2xl shadow-2xl w-full max-w-sm overflow-hidden animate-zoom-in p-6 text-center">
              <Trash2 size={40} className="mx-auto text-rose-500 mb-4" />
              <h3 className="text-lg font-bold text-slate-900 dark:text-white mb-2">{confirmConfig.title}</h3>
              <p className="text-sm text-slate-500 dark:text-slate-400 mb-6">{confirmConfig.message}</p>
              <div className="flex space-x-3">
                <button onClick={() => setConfirmConfig(prev => ({ ...prev, isOpen: false }))} className="flex-1 py-3 rounded-xl font-bold bg-slate-100 dark:bg-slate-800 text-slate-600 dark:text-slate-400">Cancel</button>
                <button onClick={confirmConfig.onConfirm} className="flex-1 py-3 rounded-xl font-bold bg-rose-600 text-white shadow-lg shadow-rose-600/20">Delete</button>
              </div>
          </div>
        </div>
      )}
    </Layout>
  );
};

interface AddTransactionFormProps {
  onClose: () => void;
  onSave: (t: Transaction) => Promise<void>;
  onDelete?: (id: string) => void;
  cashBalance: number;
  holdings: Holding[];
  prices: Record<string, number>;
  transactions: Transaction[];
  initialData: Transaction | null;
}

const AddTransactionForm: React.FC<AddTransactionFormProps> = ({ onClose, onSave, onDelete, cashBalance, holdings, prices, transactions, initialData }) => {
  const [type, setType] = useState<TransactionType>(TransactionType.BUY);
  const [date, setDate] = useState(new Date().toISOString().split('T')[0]);
  const [symbol, setSymbol] = useState('');
  const [shares, setShares] = useState('');
  const [price, setPrice] = useState(''); // Price per share
  const [totalAmount, setTotalAmount] = useState(''); // Total transaction value
  const [fee, setFee] = useState('');
  const [assetClass, setAssetClass] = useState<AssetClass>(AssetClass.STOCK);
  const [exchangeRate, setExchangeRate] = useState(''); 
  const [notes, setNotes] = useState('');
  const [error, setError] = useState<string | null>(null);
  const [isSaving, setIsSaving] = useState(false);
  const [activeInput, setActiveInput] = useState<'shares' | 'price' | 'total' | null>(null);
  const [showSuggestions, setShowSuggestions] = useState(false);
  const wrapperRef = useRef<HTMLDivElement>(null);

  // Helper: Get color based on type
  const getTypeColor = (t: TransactionType) => {
    switch (t) {
        case TransactionType.BUY: return 'blue';
        case TransactionType.DEPOSIT: return 'emerald';
        case TransactionType.SELL: return 'rose';
        case TransactionType.WITHDRAW: return 'rose';
        case TransactionType.DIVIDEND: return 'emerald';
        case TransactionType.SPLIT: return 'purple';
        default: return 'slate';
    }
  }

  const themeColor = getTypeColor(type);

  // Validation logic helpers
  const needsSymbol = [TransactionType.BUY, TransactionType.SELL, TransactionType.DIVIDEND, TransactionType.SPLIT].includes(type);
  const needsShares = [TransactionType.BUY, TransactionType.SELL, TransactionType.SPLIT].includes(type);
  const needsPrice = type !== TransactionType.SPLIT;
  const isFunding = type === TransactionType.DEPOSIT || type === TransactionType.WITHDRAW;

  // Effects (Initialization, Auto-fill, Calculation)
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => { if (wrapperRef.current && !wrapperRef.current.contains(event.target as Node)) setShowSuggestions(false); };
    document.addEventListener("mousedown", handleClickOutside); return () => document.removeEventListener("mousedown", handleClickOutside);
  }, []);

  useEffect(() => {
    if (initialData) {
      setType(initialData.type); setDate(initialData.date); setSymbol(initialData.symbol || '');
      setShares(initialData.shares?.toString() || ''); setPrice(initialData.price?.toString() || '');
      setFee(initialData.fee?.toString() || ''); setAssetClass(initialData.assetClass || AssetClass.STOCK);
      setExchangeRate(initialData.exchangeRate?.toString() || ''); setNotes(initialData.notes || '');
      if (initialData.shares && initialData.price && (initialData.type === TransactionType.BUY || initialData.type === TransactionType.SELL)) {
         setTotalAmount((initialData.shares * initialData.price).toFixed(2));
      } else if (initialData.price) setTotalAmount(initialData.price.toString());
    }
  }, [initialData]);

  useEffect(() => {
    if (!initialData && symbol && !price && !activeInput) {
       const h = holdings.find(h => h.symbol === symbol.toUpperCase());
       if (h) { setAssetClass(h.assetClass); if (h.currentPrice > 0) setPrice(h.currentPrice.toString()); }
       else { const kp = prices[symbol.toUpperCase()]; if (kp) setPrice(kp.toString()); }
    }
  }, [symbol]);

  useEffect(() => {
    const s = parseFloat(shares) || 0; const p = parseFloat(price) || 0; const t = parseFloat(totalAmount) || 0;
    if ((activeInput === 'shares' || activeInput === 'price') && s > 0 && p > 0) setTotalAmount((s * p).toFixed(2));
    if (activeInput === 'total' && t > 0 && p > 0) setShares((t / p).toFixed(4));
  }, [shares, price, totalAmount, activeInput]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (needsSymbol && !symbol) return setError("Symbol required");
    setIsSaving(true);
    await onSave({
      id: initialData ? initialData.id : generateId(),
      date, type, symbol: needsSymbol ? symbol.toUpperCase() : undefined,
      shares: needsShares ? parseFloat(shares) : undefined,
      price: type === TransactionType.SPLIT ? 0 : parseFloat(price),
      fee: (fee && (type === TransactionType.BUY || type === TransactionType.SELL)) ? parseFloat(fee) : undefined,
      assetClass: !needsSymbol ? AssetClass.CASH : assetClass,
      exchangeRate: exchangeRate ? parseFloat(exchangeRate) : 1, notes: notes || undefined
    });
    setIsSaving(false);
  };

  const suggestions = useMemo(() => {
    if (!symbol) return [];
    const inputUpper = symbol.toUpperCase();
    return Array.from(new Set([...holdings.map(h => h.symbol), ...POPULAR_SYMBOLS])).filter(s => s.includes(inputUpper)).slice(0, 5);
  }, [symbol, holdings]);

  return (
    <>
      <div className="shrink-0 px-6 py-5 border-b border-slate-100 dark:border-slate-800 flex justify-between items-center bg-white dark:bg-slate-900">
          <h3 className="text-xl font-display font-bold text-slate-900 dark:text-white">{initialData ? 'Edit Transaction' : 'New Transaction'}</h3>
          <button onClick={onClose} className="bg-slate-100 dark:bg-slate-800 p-2 rounded-full text-slate-500 hover:text-slate-800 dark:hover:text-white transition-colors"><X size={20} /></button>
      </div>

      <form onSubmit={handleSubmit} className="flex-1 overflow-y-auto min-h-0 p-6 space-y-8 custom-scrollbar bg-white dark:bg-slate-900">

        {/* 1. Transaction Type Selector (Modern Pills) */}
        <div>
           <label className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-3 block">Transaction Type</label>
           <div className="flex flex-wrap gap-2">
              {[TransactionType.BUY, TransactionType.SELL, TransactionType.DEPOSIT, TransactionType.WITHDRAW, TransactionType.DIVIDEND, TransactionType.SPLIT].map(t => {
                 const isActive = type === t;
                 // Determine pill color
                 let activeClass = 'bg-slate-800 text-white dark:bg-white dark:text-slate-900'; // Default black/white
                 if (isActive) {
                    if (t === 'BUY') activeClass = 'bg-blue-600 text-white shadow-lg shadow-blue-500/20';
                    if (t === 'SELL' || t === 'WITHDRAW') activeClass = 'bg-rose-600 text-white shadow-lg shadow-rose-500/20';
                    if (t === 'DEPOSIT' || t === 'DIVIDEND') activeClass = 'bg-emerald-600 text-white shadow-lg shadow-emerald-500/20';
                    if (t === 'SPLIT') activeClass = 'bg-purple-600 text-white shadow-lg shadow-purple-500/20';
                 }

                 return (
                   <button
                      key={t} type="button" onClick={() => setType(t)}
                      className={`flex-1 min-w-[80px] py-2.5 px-4 rounded-xl text-xs font-bold transition-all border ${
                         isActive 
                         ? `border-transparent ${activeClass} transform scale-105` 
                         : 'bg-white dark:bg-slate-800 border-slate-200 dark:border-slate-700 text-slate-500 dark:text-slate-400 hover:border-slate-300 dark:hover:border-slate-600'
                      }`}
                   >
                      {t}
                   </button>
                 )
              })}
           </div>
        </div>

        {/* 2. MAIN HERO INPUTS */}
        <div className="space-y-6">
             {needsSymbol && (
                <div className="relative z-20" ref={wrapperRef}>
                    <label className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-2 block">Asset Symbol</label>
                    <div className="relative group">
                        <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400 group-focus-within:text-blue-500 transition-colors" size={20} />
                        <input 
                           type="text" placeholder="e.g. AAPL" value={symbol} 
                           onChange={e => { setSymbol(e.target.value); setShowSuggestions(true); }}
                           onFocus={() => setShowSuggestions(true)}
                           className="w-full pl-12 pr-4 py-4 bg-slate-50 dark:bg-slate-800/50 border border-slate-200 dark:border-slate-700 rounded-2xl text-2xl font-bold uppercase tracking-wide focus:ring-2 focus:ring-blue-500 focus:bg-white dark:focus:bg-slate-800 outline-none transition-all"
                        />
                         {showSuggestions && suggestions.length > 0 && (
                            <div className="absolute top-full left-0 right-0 mt-2 bg-white dark:bg-slate-800 rounded-xl shadow-xl border border-slate-100 dark:border-slate-700 overflow-hidden z-50 animate-fade-in">
                                {suggestions.map(s => (
                                    <div key={s} onMouseDown={(e) => { e.preventDefault(); setSymbol(s); setShowSuggestions(false); }} className="px-5 py-3 hover:bg-slate-50 dark:hover:bg-slate-700 cursor-pointer font-bold text-slate-700 dark:text-slate-300 flex justify-between">
                                       <span>{s}</span>
                                       <span className="text-xs text-slate-400 font-normal">Select</span>
                                    </div>
                                ))}
                            </div>
                        )}
                    </div>
                </div>
             )}

             {/* The Big Money Input */}
             {(needsPrice || isFunding) && (
                <div>
                   <label className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-2 block">
                       {needsShares ? 'Total Amount' : 'Amount'}
                   </label>
                   <div className="relative group">
                       <span className={`absolute left-5 top-1/2 -translate-y-1/2 text-3xl font-bold ${type === TransactionType.SELL || type === TransactionType.WITHDRAW ? 'text-rose-500' : 'text-blue-500'}`}>$</span>
                       <input 
                          type="number" step="any" min="0" placeholder="0.00"
                          value={totalAmount}
                          onFocus={() => setActiveInput('total')}
                          onChange={e => setTotalAmount(e.target.value)}
                          className="w-full pl-12 pr-4 py-5 bg-slate-50 dark:bg-slate-800/50 border border-slate-200 dark:border-slate-700 rounded-2xl text-4xl font-display font-bold text-slate-900 dark:text-white focus:ring-2 focus:ring-blue-500 focus:bg-white dark:focus:bg-slate-800 outline-none transition-all"
                       />
                   </div>
                </div>
             )}
        </div>

        <div className="h-px bg-slate-100 dark:bg-slate-800"></div>

        {/* 3. DETAILS GRID */}
        <div className="grid grid-cols-1 sm:grid-cols-2 gap-6">
            <div>
               <label className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-2 block">Date</label>
               <div className="relative">
                  <Calendar className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={16} />
                  <input type="date" value={date} onChange={e => setDate(e.target.value)} className="w-full pl-10 pr-4 py-3 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl font-medium text-sm focus:ring-2 focus:ring-blue-500 outline-none" />
               </div>
            </div>

             {needsSymbol && (
                <div>
                    <label className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-2 block">Asset Class</label>
                    <select value={assetClass} onChange={e => setAssetClass(e.target.value as AssetClass)} className="w-full px-4 py-3 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl font-medium text-sm outline-none focus:ring-2 focus:ring-blue-500">
                        {Object.values(AssetClass).filter(a => a !== AssetClass.CASH).map(a => <option key={a} value={a}>{a}</option>)}
                    </select>
                </div>
             )}

            {needsShares && (
                <div>
                    <label className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-2 block">
                        {type === TransactionType.SPLIT ? 'Split Ratio (e.g. 2)' : 'Quantity / Shares'}
                    </label>
                    <div className="relative">
                      {type === TransactionType.SPLIT ? <Split className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={16} /> : <Hash className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={16} />}
                      <input 
                          type="number" step="any" 
                          placeholder={type === TransactionType.SPLIT ? "2.0 (for 2:1)" : "0"} 
                          value={shares}
                          onFocus={() => setActiveInput('shares')}
                          onChange={e => setShares(e.target.value)}
                          className="w-full pl-10 pr-4 py-3 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl font-medium text-sm focus:ring-2 focus:ring-blue-500 outline-none"
                      />
                    </div>
                </div>
            )}

            {needsPrice && needsShares && (
                <div>
                   <label className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-2 block">Price per Share</label>
                   <div className="relative">
                      <DollarSign className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={16} />
                      <input 
                          type="number" step="any" placeholder="0.00" value={price}
                          onFocus={() => setActiveInput('price')}
                          onChange={e => setPrice(e.target.value)}
                          className="w-full pl-10 pr-4 py-3 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl font-medium text-sm focus:ring-2 focus:ring-blue-500 outline-none"
                      />
                   </div>
                </div>
            )}
        </div>

        {/* 4. EXPANDABLE OPTIONAL FIELDS */}
        <details className="group bg-slate-50 dark:bg-slate-800/30 rounded-xl overflow-hidden">
            <summary className="flex items-center justify-between p-4 cursor-pointer list-none select-none">
               <span className="text-xs font-bold text-slate-500 uppercase tracking-wider">Advanced (Fee, FX, Notes)</span>
               <div className="bg-white dark:bg-slate-700 rounded-full p-1 text-slate-400 group-open:rotate-180 transition-transform">
                  <ChevronDownIcon />
               </div>
            </summary>
            <div className="p-4 pt-0 space-y-4 animate-slide-up border-t border-slate-100 dark:border-slate-800/50 mt-2">
                 {(type === TransactionType.BUY || type === TransactionType.SELL) && (
                     <div>
                        <label className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-2 block">Transaction Fee</label>
                        <input type="number" placeholder="0.00" value={fee} onChange={e => setFee(e.target.value)} className="w-full px-4 py-3 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl text-sm outline-none" />
                     </div>
                 )}
                 {isFunding && (
                     <div>
                        <label className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-2 block">Exchange Rate (Local/USD)</label>
                        <input type="number" placeholder="1.0" value={exchangeRate} onChange={e => setExchangeRate(e.target.value)} className="w-full px-4 py-3 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl text-sm outline-none" />
                     </div>
                 )}
                 <div>
                    <label className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-2 block">Notes</label>
                    <textarea rows={2} placeholder="Add a memo..." value={notes} onChange={e => setNotes(e.target.value)} className="w-full px-4 py-3 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl text-sm outline-none resize-none" />
                 </div>
            </div>
        </details>
      </form>

      {/* 5. FOOTER ACTIONS */}
      <div className="px-6 py-5 border-t border-slate-100 dark:border-slate-800 bg-white dark:bg-slate-900 z-10">
         {error && (
            <div className="bg-rose-50 text-rose-600 px-4 py-3 rounded-xl text-sm font-bold flex items-center mb-4 animate-fade-in">
                <AlertCircle size={16} className="mr-2" /> {error}
            </div>
         )}
         <div className="flex gap-4">
             {initialData && onDelete && (
                 <button type="button" onClick={() => onDelete(initialData.id)} className="p-4 rounded-xl bg-rose-50 text-rose-500 hover:bg-rose-100 dark:bg-rose-900/10 dark:hover:bg-rose-900/20 transition-colors"><Trash2 size={20} /></button>
             )}
             <button 
                onClick={handleSubmit} disabled={isSaving}
                className={`flex-1 py-4 rounded-xl font-bold text-lg text-white shadow-xl transition-all active:scale-95 flex items-center justify-center space-x-2 ${isSaving ? 'bg-slate-400 cursor-not-allowed' : `bg-${themeColor}-600 hover:bg-${themeColor}-700 shadow-${themeColor}-500/30`}`}
             >
                {isSaving ? <Spinner className="text-white" /> : (
                  <>
                    <Save size={20} />
                    <span>{initialData ? 'Update Transaction' : 'Save Transaction'}</span>
                  </>
                )}
             </button>
         </div>
      </div>
    </>
  );
};

