         {activeTab === 'dividends' && <DividendsView transactions={transactions} />}
         {activeTab === 'funding' && <FundingView transactions={transactions} currentPortfolioValue={currentPortfolioValue} />}
         {activeTab === 'growth' && <GrowthView transactions={transactions} currentPortfolioValue={currentPortfolioValue} chartData={chartData} />}
      </div>
    </div>
  );
};

// --- SUB-VIEWS ---

const MonthlyActivityView: React.FC<{ transactions: Transaction[] }> = ({ transactions }) => {
  const [range, setRange] = useState<number>(12); // Default 12 months for better trend view
  const [expandedMonth, setExpandedMonth] = useState<string | null>(null);

  // Data Calculation
  const monthlyData = useMemo(() => calculateMonthlyActivity(transactions), [transactions]);

  // Prepare data for display (Chart needs Oldest -> Newest)
  const displayData = range === 999 ? monthlyData : monthlyData.slice(0, range);
  const chartData = useMemo(() => {
     return [...displayData].reverse().map(d => ({
        ...d,
        netInvested: d.buyVolume - d.sellVolume // Net Accumulation
     }));
  }, [displayData]);

  // Insights Calculation
  const currentMonth = monthlyData[0] || { buyVolume: 0, sellVolume: 0, dividendIncome: 0, yearMonth: 'N/A' };
  const prevMonth = monthlyData[1] || { buyVolume: 0, sellVolume: 0, dividendIncome: 0 };

  // Calculate Average Investment (excluding 0 months to be fair)
  const activeMonths = monthlyData.filter(m => m.buyVolume > 0);
  const avgInvestment = activeMonths.length > 0 
    ? activeMonths.reduce((sum, m) => sum + (m.buyVolume - m.sellVolume), 0) / activeMonths.length 
    : 0;

  // Auto-expand latest month on mount if data exists
  useEffect(() => {
    if (monthlyData.length > 0 && !expandedMonth) {
      setExpandedMonth(monthlyData[0].yearMonth);
    }
  }, [monthlyData]);

  const toggleMonth = (ym: string) => {
    setExpandedMonth(expandedMonth === ym ? null : ym);
  };

  const calculateTrend = (current: number, previous: number) => {
     if (previous === 0) return current > 0 ? 100 : 0;
     return ((current - previous) / previous) * 100;
  };

  const buyTrend = calculateTrend(currentMonth.buyVolume, prevMonth.buyVolume);
  const divTrend = calculateTrend(currentMonth.dividendIncome, prevMonth.dividendIncome);

  // Render detail rows
  const renderTransactionDetails = (yearMonth: string) => {
    const monthTxs = transactions.filter(t => t.date.startsWith(yearMonth))
                                 .sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());

    if (monthTxs.length === 0) return <div className="p-4 text-center text-sm text-slate-400 italic">No transactions found.</div>;

    return (
      <div className="bg-slate-50 dark:bg-slate-900/40 p-3 rounded-xl border border-slate-200 dark:border-slate-700 shadow-inner mt-3">
         <div className="flex justify-between items-center mb-2 px-1">
            <h4 className="text-[10px] font-bold uppercase text-slate-400 tracking-wider">Transaction Log</h4>
            <span className="text-[10px] text-slate-400">{monthTxs.length} records</span>
         </div>
         <div className="space-y-2">
            {monthTxs.map(tx => {
               const totalVal = (tx.type === TransactionType.BUY || tx.type === TransactionType.SELL) 
                                ? (tx.price || 0) * (tx.shares || 0) 
                                : (tx.price || 0);

               return (
                 <div key={tx.id} className="flex items-center justify-between p-2.5 bg-white dark:bg-slate-800 rounded-lg border border-slate-200 dark:border-slate-700 shadow-sm">
                    <div className="flex items-center gap-3">
                       <div className={`w-8 h-8 rounded-lg flex items-center justify-center shrink-0 ${
                          tx.type === TransactionType.BUY ? 'bg-blue-100 text-blue-600 dark:bg-blue-900/30 dark:text-blue-400' :
                          tx.type === TransactionType.SELL ? 'bg-rose-100 text-rose-600 dark:bg-rose-900/30 dark:text-rose-400' :
                          tx.type === TransactionType.DIVIDEND ? 'bg-emerald-100 text-emerald-600 dark:bg-emerald-900/30 dark:text-emerald-400' :
                          'bg-slate-100 text-slate-600 dark:bg-slate-800 dark:text-slate-400'
                       }`}>
                          {tx.type === TransactionType.BUY ? <TrendingUp size={14} /> :
                           tx.type === TransactionType.SELL ? <TrendingDown size={14} /> :
                           tx.type === TransactionType.DIVIDEND ? <DollarSign size={14} /> :
                           <Wallet size={14} />}
                       </div>
                       <div>
