          <div>
            <p className="text-xs font-bold text-slate-400 uppercase tracking-wider">FX Gain/Loss on Principal</p>
            <div className="mt-2 flex items-baseline space-x-2">
               <h3 className={`text-3xl font-display font-bold ${fxGainOnPrincipal >= 0 ? 'text-emerald-500' : 'text-rose-500'}`}>
                 {fxGainOnPrincipal >= 0 ? '+' : ''}{formatNumber(fxGainOnPrincipal, 0)} 
               </h3>
               <span className="text-sm font-bold text-slate-400">THB</span>
