const GrowthView: React.FC<{ transactions: Transaction[], currentPortfolioValue: number, chartData: ChartDataPoint[] }> = ({ transactions, currentPortfolioValue, chartData }) => {
   const { netFundingUSD } = useMemo(() => calculateFundingStats(transactions), [transactions]);
   const gap = currentPortfolioValue - netFundingUSD;
   const gapPercent = netFundingUSD > 0 ? (gap / netFundingUSD) * 100 : 0;

   // Estimate Time in Market
   const firstTxDate = useMemo(() => {
       if(transactions.length === 0) return null;
       const sorted = [...transactions].sort((a, b) => new Date(a.date).getTime() - new Date(b.date).getTime());
       return new Date(sorted[0].date);
   }, [transactions]);

   const daysInMarket = useMemo(() => {
       if(!firstTxDate) return 0;
       const diffTime = Math.abs(new Date().getTime() - firstTxDate.getTime());
       return Math.ceil(diffTime / (1000 * 60 * 60 * 24)); 
   }, [firstTxDate]);

   const yearsInMarket = useMemo(() => {
       if (daysInMarket === 0) return 0;
       return (daysInMarket / 365.25).toFixed(1);
   }, [daysInMarket]);

   return (
      <div className="space-y-6 animate-slide-up">

         <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
             {/* Gap Card */}
             <div className="glass-card p-6 rounded-2xl border border-slate-200 dark:border-slate-700 flex flex-col justify-between">
                <div>
                  <p className="text-xs font-bold text-slate-400 uppercase tracking-wider">Total Value Gap (Spread)</p>
                  <h3 className={`text-4xl font-display font-bold mt-2 ${gap >= 0 ? 'text-emerald-500' : 'text-rose-500'}`}>
                     {gap >= 0 ? '+' : ''}{formatCurrency(gap)}
                  </h3>
                  <div className="mt-2 inline-flex items-center px-2 py-1 rounded bg-slate-100 dark:bg-slate-700/50">
                     <span className={`text-xs font-bold ${gap >= 0 ? 'text-emerald-600 dark:text-emerald-400' : 'text-rose-600 dark:text-rose-400'}`}>
                        {gapPercent.toFixed(2)}% All Time Return
                     </span>
                  </div>
                </div>
                <div className="mt-6 text-xs text-slate-400">
                   Difference between Current Market Value and Net Invested Capital.
                </div>
             </div>

             {/* Time Card */}
             <div className="glass-card p-6 rounded-2xl border border-slate-200 dark:border-slate-700 relative overflow-hidden">
                <div className="absolute top-0 right-0 p-6 opacity-5">
                   <Clock size={100} />
                </div>
                <div className="relative z-10">
                   <p className="text-xs font-bold text-slate-400 uppercase tracking-wider">Time in Market</p>
                   <h3 className="text-4xl font-display font-bold text-slate-900 dark:text-white mt-2">
                      {daysInMarket} <span className="text-xl font-normal text-slate-400">Days</span>
                   </h3>
                   <div className="mt-2 text-sm font-medium text-slate-600 dark:text-slate-300">
                       ≈ {yearsInMarket} Years Compounding
                   </div>
                   <p className="text-xs text-slate-400 mt-6">
                      Since first transaction on <span className="font-bold">{firstTxDate?.toLocaleDateString() || '-'}</span>
                   </p>
                </div>
             </div>
         </div>

         {/* Full Wealth Growth Chart */}
         <div className="glass-card p-6 rounded-2xl border border-slate-200 dark:border-slate-700">
          <div className="flex justify-between items-center mb-6">
              <h3 className="font-bold text-slate-900 dark:text-white">Wealth Growth Curve</h3>
              <div className="flex items-center space-x-4 text-xs font-bold">
                  <div className="flex items-center text-blue-500"><div className="w-3 h-3 bg-blue-500 rounded-full mr-2"></div> Market Value</div>
                  <div className="flex items-center text-slate-400"><div className="w-3 h-3 bg-slate-400 rounded-full mr-2 opacity-50"></div> Cost Basis</div>
              </div>
          </div>
          <div className="h-[400px] w-full">
            {chartData.length > 0 ? (
              <ResponsiveContainer width="100%" height="100%">
              <AreaChart data={chartData}>
                <defs>
                  <linearGradient id="colorValueGrowth" x1="0" y1="0" x2="0" y2="1">
                    <stop offset="5%" stopColor="#3b82f6" stopOpacity={0.3}/>
                    <stop offset="95%" stopColor="#3b82f6" stopOpacity={0}/>
                  </linearGradient>
                </defs>
                <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" opacity={0.3} vertical={false} />
                <XAxis dataKey="date" axisLine={false} tickLine={false} tick={{fill: '#94a3b8', fontSize: 11}} dy={10} minTickGap={50} />
                <YAxis axisLine={false} tickLine={false} tick={{fill: '#94a3b8', fontSize: 11}} tickFormatter={(val) => `${val >= 1000 ? (val/1000).toFixed(0) + 'k' : val}`} />
                <Tooltip 
                  contentStyle={{ backgroundColor: '#0f172a', border: 'none', borderRadius: '8px', color: '#fff' }}
                  itemStyle={{ color: '#fff' }}
                  formatter={(value: number) => formatCurrency(value)}
                  labelFormatter={(label) => `Date: ${label}`}
                />
                <Area type="monotone" dataKey="value" stroke="#3b82f6" strokeWidth={3} fillOpacity={1} fill="url(#colorValueGrowth)" name="Market Value" />
                <Area type="monotone" dataKey="invested" stroke="#94a3b8" strokeDasharray="5 5" strokeWidth={2} fill="transparent" name="Net Invested" />
              </AreaChart>
            </ResponsiveContainer>
            ) : (
              <div className="flex h-full items-center justify-center text-slate-400 italic">
                No transaction data available for chart.
              </div>
            )}
          </div>
        </div>
      </div>
   );
};

export default Reports;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import Layout from './components/Layout';
import Dashboard from './components/Dashboard';
import Holdings from './components/Holdings';
import Reports from './components/Reports';
import History from './components/History';
import GoalModal from './components/GoalModal';
import { Transaction, TransactionType, AssetClass, Holding, Portfolio, FinancialGoal } from './types';
import { calculateHoldings, calculatePortfolioHistory, generateId, formatCurrency, formatNumber } from './utils';
import { X, Save, TrendingUp, TrendingDown, DollarSign, Wallet, Calendar, GitFork, AlertCircle, ArrowRight, Trash2, Zap, Calculator, Search, Clock, PlusCircle, MinusCircle, RefreshCcw, Split, Hash, ChevronDown, ArrowRightCircle, Globe } from 'lucide-react';
import { Spinner } from './components/LoadingSkeletons';

const POPULAR_SYMBOLS = [
  'AAPL', 'MSFT', 'GOOGL', 'AMZN', 'NVDA', 'TSLA', 'META', 'BRK.B', 'V', 'JNJ', 'WMT', 'JPM', // Tech/Blue Chip
  'VOO', 'VTI', 'QQQ', 'IVV', 'SCHD', 'JEPI', 'VUG', 'VTV', // ETFs
  'BTC', 'ETH', 'SOL', 'USDT', 'BNB', 'XRP', 'ADA' // Crypto
];

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState('dashboard');
  const [isAddModalOpen, setIsAddModalOpen] = useState(false);
  const [editingTransaction, setEditingTransaction] = useState<Transaction | null>(null);

  // Goal Modal State
  const [isGoalModalOpen, setIsGoalModalOpen] = useState(false);

  // --- CONFIRMATION MODAL STATE ---
  const [confirmConfig, setConfirmConfig] = useState<{
    isOpen: boolean;
    title: string;
    message: string;
    onConfirm: () => void;
  }>({
    isOpen: false,
    title: '',
    message: '',
    onConfirm: () => {},
  });

  // --- PORTFOLIO MANAGEMENT STATE ---
  const [portfolios, setPortfolios] = useState<Portfolio[]>(() => {
    const saved = localStorage.getItem('portfolios');
    if (saved) return JSON.parse(saved);
    const legacyTx = localStorage.getItem('transactions');
    if (legacyTx) return [{ id: 'default', name: 'Main Portfolio' }];
    return [{ id: generateId(), name: 'My First Portfolio' }];
  });

  const [activePortfolioId, setActivePortfolioId] = useState<string>(() => {
    const saved = localStorage.getItem('activePortfolioId');
    const portfolios = JSON.parse(localStorage.getItem('portfolios') || '[]');
    if (saved && portfolios.some((p: Portfolio) => p.id === saved)) return saved;
    return portfolios.length > 0 ? portfolios[0].id : 'default';
  });

  // --- DATA STATE (Per Portfolio) - Synchronous Initialization ---
  const [transactions, setTransactions] = useState<Transaction[]>(() => {
    const key = `transactions_${activePortfolioId}`;
    const saved = localStorage.getItem(key);
    if (saved) return JSON.parse(saved);
    if (activePortfolioId === 'default') {
      const legacy = localStorage.getItem('transactions');
      if (legacy) return JSON.parse(legacy);
    }
    return [];
  });

  const [prices, setPrices] = useState<Record<string, number>>(() => {
    const key = `prices_${activePortfolioId}`;
    const saved = localStorage.getItem(key);
    if (saved) return JSON.parse(saved);
    if (activePortfolioId === 'default') {
      const legacy = localStorage.getItem('prices');
      if (legacy) return JSON.parse(legacy);
    }
    return {};
  });

  const [goals, setGoals] = useState<FinancialGoal[]>(() => {
    const key = `goals_${activePortfolioId}`;
    const saved = localStorage.getItem(key);
    if (saved) return JSON.parse(saved);

    let legacyGoal = 100000;
    const legacyKey = `financialGoal_${activePortfolioId}`;
    const savedLegacy = localStorage.getItem(legacyKey);
    if (savedLegacy) legacyGoal = parseFloat(savedLegacy);
    else if (activePortfolioId === 'default' && localStorage.getItem('financialGoal')) legacyGoal = parseFloat(localStorage.getItem('financialGoal')!);

    return [{ id: generateId(), targetAmount: legacyGoal, startDate: new Date().toISOString(), isAchieved: false, notes: 'Initial Goal' }];
  });

  const [isDataLoaded, setIsDataLoaded] = useState(true);
  const [isLoading, setIsLoading] = useState(false);
  const isFirstMount = useRef(true);

  // --- PERSISTENCE ---
  useEffect(() => { localStorage.setItem('portfolios', JSON.stringify(portfolios)); }, [portfolios]);
  useEffect(() => { localStorage.setItem('activePortfolioId', activePortfolioId); }, [activePortfolioId]);

  useEffect(() => {
    if (isFirstMount.current) { isFirstMount.current = false; return; }
    setIsLoading(true);
    setIsDataLoaded(false);
    const loadData = () => {
        const txKey = `transactions_${activePortfolioId}`;
        const pricesKey = `prices_${activePortfolioId}`;
        const goalsKey = `goals_${activePortfolioId}`;

        const savedTx = localStorage.getItem(txKey);
        setTransactions(savedTx ? JSON.parse(savedTx) : []);

        const savedPrices = localStorage.getItem(pricesKey);
        setPrices(savedPrices ? JSON.parse(savedPrices) : {});

        const savedGoals = localStorage.getItem(goalsKey);
        setGoals(savedGoals ? JSON.parse(savedGoals) : []); 

        setIsDataLoaded(true);
        setTimeout(() => setIsLoading(false), 500);
    };
    requestAnimationFrame(loadData);
  }, [activePortfolioId]);

  useEffect(() => { if (isDataLoaded) localStorage.setItem(`transactions_${activePortfolioId}`, JSON.stringify(transactions)); }, [transactions, activePortfolioId, isDataLoaded]);
  useEffect(() => { if (isDataLoaded) localStorage.setItem(`prices_${activePortfolioId}`, JSON.stringify(prices)); }, [prices, activePortfolioId, isDataLoaded]);
  useEffect(() => { if (isDataLoaded) localStorage.setItem(`goals_${activePortfolioId}`, JSON.stringify(goals)); }, [goals, activePortfolioId, isDataLoaded]);

  // --- CALCULATIONS ---
  const holdings = useMemo(() => calculateHoldings(transactions, prices), [transactions, prices]);
  const chartData = useMemo(() => calculatePortfolioHistory(transactions, prices), [transactions, prices]);
  const investedAmount = transactions.reduce((sum, t) => {
    if (t.type === TransactionType.DEPOSIT) return sum + (t.price || 0);
    if (t.type === TransactionType.WITHDRAW) return sum - (t.price || 0);
    return sum;
  }, 0);
  const cashBalance = useMemo(() => {
    let balance = 0;
    transactions.forEach(t => {
      if (t.type === TransactionType.DEPOSIT) balance += (t.price || 0);
      if (t.type === TransactionType.WITHDRAW) balance -= (t.price || 0);
      if (t.type === TransactionType.BUY) balance -= (t.price! * t.shares!) + (t.fee || 0);
      if (t.type === TransactionType.SELL) balance += (t.price! * t.shares!) - (t.fee || 0);
      if (t.type === TransactionType.DIVIDEND) balance += (t.price || 0);
    });
    return balance;
  }, [transactions]);
  const portfolioValue = holdings.reduce((sum, h) => sum + h.marketValue, 0);
  const totalNetWorth = portfolioValue + cashBalance;
  const activeGoal = useMemo(() => goals.find(g => !g.endDate) || { targetAmount: 100000 } as FinancialGoal, [goals]);

  // --- HANDLERS ---
  const handleOpenAddModal = () => { setEditingTransaction(null); setIsAddModalOpen(true); };
  const handleOpenEditModal = (tx: Transaction) => { setEditingTransaction(tx); setIsAddModalOpen(true); };
  const handleSaveTransaction = (tx: Transaction) => {
    return new Promise<void>((resolve) => {
      if (editingTransaction) setTransactions(prev => prev.map(t => t.id === tx.id ? tx : t));
      else setTransactions(prev => [...prev, tx]);
      if ((tx.type === TransactionType.BUY || tx.type === TransactionType.SELL) && tx.symbol && tx.price) setPrices(prev => ({...prev, [tx.symbol!]: tx.price!}));
      setIsAddModalOpen(false); setEditingTransaction(null); resolve();
    });
  };
  const handleUpdatePrice = (symbol: string, newPrice: number) => setPrices(prev => ({ ...prev, [symbol]: newPrice }));
  const handleDeleteTransaction = (id: string) => {
    setTransactions(prev => prev.filter(t => t.id !== id));
    if (editingTransaction && editingTransaction.id === id) { setIsAddModalOpen(false); setEditingTransaction(null); }
  };
  const handleRequestDelete = (id: string) => {
      setConfirmConfig({ isOpen: true, title: 'Delete Transaction', message: 'Permanently remove this record?', onConfirm: () => { handleDeleteTransaction(id); setConfirmConfig(prev => ({ ...prev, isOpen: false })); } });
  };
  const handleImportTransactions = (importedTxs: Transaction[]) => {
      setTransactions(prev => {
          const currentMap = new Map(prev.map(t => [t.id, t]));
          importedTxs.forEach(t => { currentMap.set(t.id, t); });
          return Array.from(currentMap.values());
      });
  };

  // Portfolios
  const handleCreatePortfolio = (name: string) => { const newId = generateId(); setPortfolios([...portfolios, { id: newId, name }]); setActivePortfolioId(newId); };
  const handleRenamePortfolio = (id: string, newName: string) => { setPortfolios(prev => prev.map(p => p.id === id ? { ...p, name: newName } : p)); };
  const handleDeletePortfolio = (id: string) => {
    if (portfolios.length <= 1) { alert("Cannot delete last portfolio"); return; }
    setConfirmConfig({
        isOpen: true, title: 'Delete Portfolio', message: 'Delete entire portfolio and all data?', 
        onConfirm: () => {
             localStorage.removeItem(`transactions_${id}`); localStorage.removeItem(`prices_${id}`); localStorage.removeItem(`goals_${id}`);
             const newPortfolios = portfolios.filter(p => p.id !== id); setPortfolios(newPortfolios);
             if (activePortfolioId === id) setActivePortfolioId(newPortfolios[0].id);
             setConfirmConfig(prev => ({ ...prev, isOpen: false }));
        }
    });
  };

  // Goals
  const handleSetNewGoal = (targetAmount: number, notes: string) => {
    const now = new Date().toISOString();
    setGoals(prev => [...prev.map(g => !g.endDate ? { ...g, endDate: now, isAchieved: totalNetWorth >= g.targetAmount } : g), { id: generateId(), targetAmount, startDate: now, isAchieved: false, notes }]);
  };
  const handleEditGoal = (updatedGoal: FinancialGoal) => setGoals(prev => prev.map(g => g.id === updatedGoal.id ? updatedGoal : g));
  const handleDeleteGoal = (id: string) => setGoals(prev => prev.filter(g => g.id !== id));

  return (
    <Layout 
      activeTab={activeTab} setActiveTab={setActiveTab} onOpenAddModal={handleOpenAddModal}
      portfolios={portfolios} activePortfolioId={activePortfolioId} onSwitchPortfolio={setActivePortfolioId}
      onCreatePortfolio={handleCreatePortfolio} onRenamePortfolio={handleRenamePortfolio} onDeletePortfolio={handleDeletePortfolio}
    >
      <div key={activePortfolioId} className="h-full">
        {activeTab === 'dashboard' && <Dashboard isLoading={isLoading} holdings={holdings} transactions={transactions} financialGoal={activeGoal.targetAmount} onOpenGoalModal={() => setIsGoalModalOpen(true)} investedAmount={investedAmount} cashBalance={cashBalance} portfolioValue={portfolioValue} chartData={chartData} />}
        {activeTab === 'holdings' && <Holdings isLoading={isLoading} holdings={holdings} transactions={transactions} onUpdatePrice={handleUpdatePrice} />}
        {activeTab === 'history' && <History isLoading={isLoading} transactions={transactions} onDelete={handleRequestDelete} onEdit={handleOpenEditModal} onAdd={handleOpenAddModal} onImport={handleImportTransactions} />}
        {activeTab === 'reports' && <Reports isLoading={isLoading} transactions={transactions} currentPortfolioValue={portfolioValue + cashBalance} chartData={chartData} />}
      </div>

      {isAddModalOpen && (
        <div className="fixed inset-0 z-50 flex items-end sm:items-center justify-center sm:p-4">
          <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-sm animate-fade-in" onClick={() => setIsAddModalOpen(false)}></div>
          <div className="relative bg-white dark:bg-slate-900 w-full max-w-lg rounded-t-3xl sm:rounded-3xl shadow-2xl overflow-hidden animate-slide-up flex flex-col max-h-[90dvh]">
            <AddTransactionForm onClose={() => setIsAddModalOpen(false)} onSave={handleSaveTransaction} onDelete={handleRequestDelete} cashBalance={cashBalance} holdings={holdings} prices={prices} transactions={transactions} initialData={editingTransaction} />
          </div>
        </div>
      )}

      <GoalModal isOpen={isGoalModalOpen} onClose={() => setIsGoalModalOpen(false)} goals={goals} currentNetWorth={totalNetWorth} onSetGoal={handleSetNewGoal} onEditGoal={handleEditGoal} onDeleteGoal={handleDeleteGoal} />

      {confirmConfig.isOpen && (
        <div className="fixed inset-0 z-[70] flex items-center justify-center p-4 animate-fade-in">
          <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-sm" onClick={() => setConfirmConfig(prev => ({ ...prev, isOpen: false }))}></div>
          <div className="relative bg-white dark:bg-slate-900 rounded-2xl shadow-2xl w-full max-w-sm overflow-hidden animate-zoom-in p-6 text-center">
              <Trash2 size={40} className="mx-auto text-rose-500 mb-4" />
              <h3 className="text-lg font-bold text-slate-900 dark:text-white mb-2">{confirmConfig.title}</h3>
              <p className="text-sm text-slate-500 dark:text-slate-400 mb-6">{confirmConfig.message}</p>
              <div className="flex space-x-3">
                <button onClick={() => setConfirmConfig(prev => ({ ...prev, isOpen: false }))} className="flex-1 py-3 rounded-xl font-bold bg-slate-100 dark:bg-slate-800 text-slate-600 dark:text-slate-400">Cancel</button>
                <button onClick={confirmConfig.onConfirm} className="flex-1 py-3 rounded-xl font-bold bg-rose-600 text-white shadow-lg shadow-rose-600/20">Delete</button>
              </div>
          </div>
        </div>
      )}
    </Layout>
  );
};

interface AddTransactionFormProps {
  onClose: () => void;
  onSave: (t: Transaction) => Promise<void>;
  onDelete?: (id: string) => void;
  cashBalance: number;
  holdings: Holding[];
  prices: Record<string, number>;
  transactions: Transaction[];
  initialData: Transaction | null;
}

const AddTransactionForm: React.FC<AddTransactionFormProps> = ({ onClose, onSave, onDelete, cashBalance, holdings, prices, transactions, initialData }) => {
  const [type, setType] = useState<TransactionType>(TransactionType.BUY);
  const [date, setDate] = useState(new Date().toISOString().split('T')[0]);
  const [symbol, setSymbol] = useState('');
  const [shares, setShares] = useState('');
  const [price, setPrice] = useState(''); // Price per share
  const [totalAmount, setTotalAmount] = useState(''); // Total transaction value
  const [fee, setFee] = useState('');
  const [assetClass, setAssetClass] = useState<AssetClass>(AssetClass.STOCK);
  const [exchangeRate, setExchangeRate] = useState(''); 
  const [notes, setNotes] = useState('');
  const [error, setError] = useState<string | null>(null);
  const [isSaving, setIsSaving] = useState(false);
  const [activeInput, setActiveInput] = useState<'shares' | 'price' | 'total' | null>(null);
  const [showSuggestions, setShowSuggestions] = useState(false);
  const wrapperRef = useRef<HTMLDivElement>(null);

  // Helper: Get color based on type
  const getTypeColor = (t: TransactionType) => {
    switch (t) {
        case TransactionType.BUY: return 'blue';
        case TransactionType.DEPOSIT: return 'emerald';
        case TransactionType.SELL: return 'rose';
        case TransactionType.WITHDRAW: return 'rose';
        case TransactionType.DIVIDEND: return 'emerald';
        case TransactionType.SPLIT: return 'purple';
        default: return 'slate';
    }
  }

  const themeColor = getTypeColor(type);

  // Validation logic helpers
  const needsSymbol = [TransactionType.BUY, TransactionType.SELL, TransactionType.DIVIDEND, TransactionType.SPLIT].includes(type);
  const needsShares = [TransactionType.BUY, TransactionType.SELL, TransactionType.SPLIT].includes(type);
  const needsPrice = type !== TransactionType.SPLIT;

  // FX Rate is relevant for: Deposits, Withdrawals, and Dividends (Foreign income)
  const hasExchangeRate = type === TransactionType.DEPOSIT || type === TransactionType.WITHDRAW || type === TransactionType.DIVIDEND;
  const isFunding = type === TransactionType.DEPOSIT || type === TransactionType.WITHDRAW;

  // Effects (Initialization, Auto-fill, Calculation)
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => { if (wrapperRef.current && !wrapperRef.current.contains(event.target as Node)) setShowSuggestions(false); };
    document.addEventListener("mousedown", handleClickOutside); return () => document.removeEventListener("mousedown", handleClickOutside);
  }, []);

  useEffect(() => {
    if (initialData) {
      setType(initialData.type); setDate(initialData.date); setSymbol(initialData.symbol || '');
      setShares(initialData.shares?.toString() || ''); setPrice(initialData.price?.toString() || '');
      setFee(initialData.fee?.toString() || ''); setAssetClass(initialData.assetClass || AssetClass.STOCK);
      setExchangeRate(initialData.exchangeRate?.toString() || ''); setNotes(initialData.notes || '');
      if (initialData.shares && initialData.price && (initialData.type === TransactionType.BUY || initialData.type === TransactionType.SELL)) {
         setTotalAmount((initialData.shares * initialData.price).toFixed(2));
      } else if (initialData.price) setTotalAmount(initialData.price.toString());
    }
  }, [initialData]);

  useEffect(() => {
    if (!initialData && symbol && !price && !activeInput) {
       const h = holdings.find(h => h.symbol === symbol.toUpperCase());
       if (h) { setAssetClass(h.assetClass); if (h.currentPrice > 0) setPrice(h.currentPrice.toString()); }
       else { const kp = prices[symbol.toUpperCase()]; if (kp) setPrice(kp.toString()); }
    }
  }, [symbol]);

  useEffect(() => {
    const s = parseFloat(shares) || 0; const p = parseFloat(price) || 0; const t = parseFloat(totalAmount) || 0;
    if ((activeInput === 'shares' || activeInput === 'price') && s > 0 && p > 0) setTotalAmount((s * p).toFixed(2));
    if (activeInput === 'total' && t > 0 && p > 0) setShares((t / p).toFixed(4));
  }, [shares, price, totalAmount, activeInput]);

  // IMPACT CALCULATIONS FOR SUMMARY
  const currentCashImpact = useMemo(() => {
     const qty = parseFloat(shares) || 0;
     const unitPrice = parseFloat(price) || 0;
     const feeVal = parseFloat(fee) || 0;
     const amt = parseFloat(totalAmount) || 0;

     if (type === TransactionType.BUY) return -((qty * unitPrice) + feeVal);
     if (type === TransactionType.SELL) return ((qty * unitPrice) - feeVal);
     if (type === TransactionType.DEPOSIT) return amt;
     if (type === TransactionType.WITHDRAW) return -amt;
     if (type === TransactionType.DIVIDEND) return amt;
     return 0;
  }, [type, shares, price, fee, totalAmount]);

  const originalCashImpact = useMemo(() => {
    if (!initialData) return 0;
    const qty = initialData.shares || 0;
    const unitPrice = initialData.price || 0;
    const feeVal = initialData.fee || 0;

    if (initialData.type === TransactionType.BUY) return -((qty * unitPrice) + feeVal);
    if (initialData.type === TransactionType.SELL) return ((qty * unitPrice) - feeVal);
    if (initialData.type === TransactionType.DEPOSIT) return unitPrice; // price holds amount for funding
    if (initialData.type === TransactionType.WITHDRAW) return -unitPrice;
    if (initialData.type === TransactionType.DIVIDEND) return unitPrice;
    return 0;
  }, [initialData]);

  const projectedCashBalance = cashBalance - originalCashImpact + currentCashImpact;

  // Validation
  const validate = () => {
    if (needsSymbol && !symbol) return "Asset Symbol is required.";
    if (!needsSymbol && !totalAmount) return "Amount is required.";

    // Sell Check
    if (type === TransactionType.SELL) {
        const holding = holdings.find(h => h.symbol === symbol.toUpperCase());
        const currentShares = holding ? holding.shares : 0;
        const originalShares = (initialData && initialData.type === TransactionType.SELL && initialData.symbol === symbol) ? (initialData.shares || 0) : 0;
        const available = currentShares + originalShares;

        if ((parseFloat(shares) || 0) > available) {
            return `Insufficient shares. Owned: ${formatNumber(available)}. Selling: ${shares}.`;
        }
    }

    // Strict Negative Cash Warning is handled in UI as a warning, but we might want to block excessive withdrawals
    if (type === TransactionType.WITHDRAW && projectedCashBalance < 0) {
        return "Insufficient funds for withdrawal.";
    }

    return null;
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    const errMsg = validate();
    if (errMsg) return setError(errMsg);
    setError(null);

    setIsSaving(true);
    await onSave({
      id: initialData ? initialData.id : generateId(),
      date, type, symbol: needsSymbol ? symbol.toUpperCase() : undefined,
      shares: needsShares ? parseFloat(shares) : undefined,
      // For types that don't need shares (Deposit, Withdraw, Dividend), use the total amount as price
      price: type === TransactionType.SPLIT ? 0 : (needsShares ? parseFloat(price) : parseFloat(totalAmount)),
      fee: (fee && (type === TransactionType.BUY || type === TransactionType.SELL)) ? parseFloat(fee) : undefined,
      assetClass: !needsSymbol ? AssetClass.CASH : assetClass,
      exchangeRate: exchangeRate ? parseFloat(exchangeRate) : 1, notes: notes || undefined
    });
    setIsSaving(false);
  };

  const suggestions = useMemo(() => {
    if (!symbol) return [];
    const inputUpper = symbol.toUpperCase();
    return Array.from(new Set([...holdings.map(h => h.symbol), ...POPULAR_SYMBOLS])).filter(s => s.includes(inputUpper)).slice(0, 5);
  }, [symbol, holdings]);

  // Calculate Summary Text
  const summary = useMemo(() => {
     const qty = parseFloat(shares) || 0;
     const unitPrice = parseFloat(price) || 0;
     const subTotal = parseFloat(totalAmount) || (qty * unitPrice);

     if (type === TransactionType.BUY) {
         return { label: 'Total Cost', description: `Buying ${qty > 0 ? formatNumber(qty, 4) : '...'} shares of ${symbol || '...'}` };
     } else if (type === TransactionType.SELL) {
         return { label: 'Net Proceeds', description: `Selling ${qty > 0 ? formatNumber(qty, 4) : '...'} shares of ${symbol || '...'}` };
     } else if (type === TransactionType.DEPOSIT) {
         return { label: 'Amount Added', description: 'Adding cash to portfolio' };
     } else if (type === TransactionType.WITHDRAW) {
         return { label: 'Amount Removed', description: 'Removing cash from portfolio' };
     } else if (type === TransactionType.DIVIDEND) {
         return { label: 'Dividend Income', description: `Dividend payout from ${symbol || '...'}` };
     } else if (type === TransactionType.SPLIT) {
         return { label: 'New Share Count', description: `Splitting ${symbol || '...'} by ${qty}:1` };
     }
     return null;
  }, [type, shares, price, totalAmount, symbol]);

  const calculatedLocalValue = useMemo(() => {
      const amt = parseFloat(totalAmount);
      const rate = parseFloat(exchangeRate);
      if (amt && rate) return amt * rate;
      return null;
  }, [totalAmount, exchangeRate]);

  return (
    <>
      <div className="shrink-0 px-6 py-4 border-b border-slate-100 dark:border-slate-800 flex justify-between items-center bg-white dark:bg-slate-900">
          <h3 className="text-lg font-display font-bold text-slate-900 dark:text-white">{initialData ? 'Edit Transaction' : 'New Transaction'}</h3>
          <button onClick={onClose} className="bg-slate-100 dark:bg-slate-800 p-2 rounded-full text-slate-500 hover:text-slate-800 dark:hover:text-white transition-colors"><X size={20} /></button>
      </div>

      <form onSubmit={handleSubmit} className="flex-1 overflow-y-auto min-h-0 p-5 space-y-5 custom-scrollbar bg-white dark:bg-slate-900">

        {/* 1. Transaction Type Selector (Compact) */}
        <div>
           <label className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-2 block">Transaction Type</label>
           <div className="grid grid-cols-3 sm:grid-cols-6 gap-2">
              {[TransactionType.BUY, TransactionType.SELL, TransactionType.DEPOSIT, TransactionType.WITHDRAW, TransactionType.DIVIDEND, TransactionType.SPLIT].map(t => {
                 const isActive = type === t;
                 // Determine pill color
                 let activeClass = 'bg-slate-800 text-white dark:bg-white dark:text-slate-900'; // Default black/white
                 if (isActive) {
                    if (t === 'BUY') activeClass = 'bg-blue-600 text-white shadow-sm shadow-blue-500/20';
                    if (t === 'SELL' || t === 'WITHDRAW') activeClass = 'bg-rose-600 text-white shadow-sm shadow-rose-500/20';
                    if (t === 'DEPOSIT' || t === 'DIVIDEND') activeClass = 'bg-emerald-600 text-white shadow-sm shadow-emerald-500/20';
                    if (t === 'SPLIT') activeClass = 'bg-purple-600 text-white shadow-sm shadow-purple-500/20';
                 }

                 return (
                   <button
                      key={t} type="button" onClick={() => setType(t)}
                      className={`flex-1 py-2 px-3 rounded-lg text-xs font-bold transition-all border ${
                         isActive 
                         ? `border-transparent ${activeClass}` 
                         : 'bg-white dark:bg-slate-800 border-slate-200 dark:border-slate-700 text-slate-500 dark:text-slate-400 hover:border-slate-300 dark:hover:border-slate-600'
                      }`}
                   >
                      {t}
                   </button>
                 )
              })}
           </div>
        </div>

        {/* 2. MAIN HERO INPUTS (Compact) */}
        <div className="space-y-4">
             {needsSymbol && (
                <div className="relative z-20" ref={wrapperRef}>
                    <label className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-1 block">Asset Symbol</label>
                    <div className="relative group">
                        <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400 group-focus-within:text-blue-500 transition-colors" size={18} />
                        <input 
                           type="text" placeholder="e.g. AAPL" value={symbol} 
                           onChange={e => { setSymbol(e.target.value); setShowSuggestions(true); }}
                           onFocus={() => setShowSuggestions(true)}
                           className="w-full pl-10 pr-4 py-3 bg-slate-50 dark:bg-slate-800/50 border border-slate-200 dark:border-slate-700 rounded-xl text-xl font-bold uppercase tracking-wide focus:ring-2 focus:ring-blue-500 focus:bg-white dark:focus:bg-slate-800 outline-none transition-all"
                        />
                         {showSuggestions && suggestions.length > 0 && (
                            <div className="absolute top-full left-0 right-0 mt-2 bg-white dark:bg-slate-800 rounded-xl shadow-xl border border-slate-100 dark:border-slate-700 overflow-hidden z-50 animate-fade-in">
                                {suggestions.map(s => (
                                    <div key={s} onMouseDown={(e) => { e.preventDefault(); setSymbol(s); setShowSuggestions(false); }} className="px-4 py-2 hover:bg-slate-50 dark:hover:bg-slate-700 cursor-pointer font-bold text-slate-700 dark:text-slate-300 flex justify-between text-sm">
                                       <span>{s}</span>
                                       <span className="text-xs text-slate-400 font-normal">Select</span>
                                    </div>
                                ))}
                            </div>
                        )}
                    </div>
                </div>
             )}

             {/* The Big Money Input */}
             {(needsPrice || isFunding) && (
                <div>
                   <label className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-1 block">
                       {needsShares ? 'Total Amount (USD)' : 'Amount (USD)'}
                   </label>
                   <div className="relative group">
                       <span className={`absolute left-4 top-1/2 -translate-y-1/2 text-2xl font-bold ${type === TransactionType.SELL || type === TransactionType.WITHDRAW ? 'text-rose-500' : 'text-blue-500'}`}>$</span>
                       <input 
                          type="number" step="any" min="0" placeholder="0.00"
                          value={totalAmount}
                          onFocus={() => setActiveInput('total')}
                          onChange={e => setTotalAmount(e.target.value)}
                          className="w-full pl-10 pr-4 py-3 bg-slate-50 dark:bg-slate-800/50 border border-slate-200 dark:border-slate-700 rounded-xl text-3xl font-display font-bold text-slate-900 dark:text-white focus:ring-2 focus:ring-blue-500 focus:bg-white dark:focus:bg-slate-800 outline-none transition-all"
                       />
                   </div>
                </div>
             )}
        </div>

        <div className="h-px bg-slate-100 dark:bg-slate-800"></div>

        {/* 3. DETAILS GRID (Compact Gap) */}
        <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
            <div>
               <label className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-1 block">Date</label>
               <div className="relative">
                  <Calendar className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={16} />
                  <input type="date" value={date} onChange={e => setDate(e.target.value)} className="w-full pl-10 pr-4 py-2.5 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl font-medium text-sm focus:ring-2 focus:ring-blue-500 outline-none" />
               </div>
            </div>

             {needsSymbol && (
                <div>
                    <label className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-1 block">Asset Class</label>
                    <select value={assetClass} onChange={e => setAssetClass(e.target.value as AssetClass)} className="w-full px-4 py-2.5 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl font-medium text-sm outline-none focus:ring-2 focus:ring-blue-500">
                        {Object.values(AssetClass).filter(a => a !== AssetClass.CASH).map(a => <option key={a} value={a}>{a}</option>)}
                    </select>
                </div>
             )}

             {hasExchangeRate && (
                <div>
                   <label className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-1 block">Exchange Rate</label>
                   <div className="relative">
                       <RefreshCcw className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={16} />
                       <input 
                         type="number" 
                         step="any"
                         min="0"
                         placeholder="1.0 (Local/USD)" 
                         value={exchangeRate} 
                         onChange={e => setExchangeRate(e.target.value)} 
                         className="w-full pl-10 pr-4 py-2.5 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl font-medium text-sm outline-none focus:ring-2 focus:ring-blue-500" 
                       />
                   </div>
                   {calculatedLocalValue !== null && (
                      <p className="text-[10px] text-slate-400 mt-1 pl-1 flex items-center">
                        <Globe size={10} className="mr-1" />
                        <span>≈ {formatNumber(calculatedLocalValue)} Local Currency</span>
                      </p>
                   )}
                </div>
             )}

            {needsShares && (
                <div>
                    <label className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-1 block">
                        {type === TransactionType.SPLIT ? 'Split Ratio' : 'Quantity / Shares'}
                    </label>
                    <div className="relative">
                      {type === TransactionType.SPLIT ? <Split className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={16} /> : <Hash className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={16} />}
                      <input 
                          type="number" step="any" 
                          placeholder={type === TransactionType.SPLIT ? "2.0 (for 2:1)" : "0"} 
                          value={shares}
                          onFocus={() => setActiveInput('shares')}
                          onChange={e => setShares(e.target.value)}
                          className="w-full pl-10 pr-4 py-2.5 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl font-medium text-sm focus:ring-2 focus:ring-blue-500 outline-none"
                      />
                    </div>
                </div>
            )}

            {needsPrice && needsShares && (
                <div>
                   <label className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-1 block">Price per Share</label>
                   <div className="relative">
                      <DollarSign className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={16} />
                      <input 
                          type="number" step="any" placeholder="0.00" value={price}
                          onFocus={() => setActiveInput('price')}
                          onChange={e => setPrice(e.target.value)}
                          className="w-full pl-10 pr-4 py-2.5 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl font-medium text-sm focus:ring-2 focus:ring-blue-500 outline-none"
                      />
                   </div>
                </div>
            )}

            {(type === TransactionType.BUY || type === TransactionType.SELL) && (
                <div>
                   <label className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-1 block">Transaction Fee</label>
                   <div className="relative">
                       <input 
                         type="number" step="any" placeholder="0.00" value={fee} onChange={e => setFee(e.target.value)} 
                         className="w-full px-4 py-2.5 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl text-sm outline-none focus:ring-2 focus:ring-blue-500" 
                       />
                   </div>
                </div>
            )}
        </div>

        {/* 4. EXPANDABLE OPTIONAL FIELDS */}
        <details className="group bg-slate-50 dark:bg-slate-800/30 rounded-xl overflow-hidden">
            <summary className="flex items-center justify-between p-3 cursor-pointer list-none select-none">
               <span className="text-xs font-bold text-slate-500 uppercase tracking-wider">Advanced (Notes)</span>
               <div className="bg-white dark:bg-slate-700 rounded-full p-1 text-slate-400 group-open:rotate-180 transition-transform">
                  <ChevronDownIcon />
               </div>
            </summary>
            <div className="p-3 pt-0 space-y-3 animate-slide-up border-t border-slate-100 dark:border-slate-800/50 mt-2">
                 <div>
                    <label className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-1 block">Notes</label>
                    <textarea rows={2} placeholder="Add a memo..." value={notes} onChange={e => setNotes(e.target.value)} className="w-full px-4 py-2 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl text-sm outline-none resize-none" />
                 </div>
            </div>
        </details>

        {/* 5. TRANSACTION SUMMARY CARD (ENHANCED) */}
        {summary && (
           <div className="space-y-3">
               <div className="bg-blue-50 dark:bg-slate-800/50 rounded-xl p-4 border border-blue-100 dark:border-slate-700">
                   <div className="flex justify-between items-end mb-1">
                       <div>
                           <p className="text-xs font-bold text-slate-500 dark:text-slate-400 uppercase tracking-wider">{summary.label}</p>
                           <p className="text-[10px] text-slate-400 mt-0.5 italic">{summary.description}</p>
                       </div>
                       <div className="text-right">
                           <span className="text-xl font-bold font-display text-slate-900 dark:text-white">
                               {type === TransactionType.SPLIT ? formatNumber(Math.abs(currentCashImpact), 2) : formatCurrency(Math.abs(currentCashImpact))}
                           </span>
                       </div>
                   </div>

                   {/* Projected Cash Balance */}
                   <div className="mt-3 pt-2 border-t border-blue-100 dark:border-slate-700/50 flex justify-between items-center">
                       <span className="text-[10px] font-bold text-slate-500 dark:text-slate-400 uppercase">Projected Cash</span>
                       <div className="flex items-center space-x-2">
                           <span className={`text-xs font-mono font-medium ${cashBalance < 0 ? 'text-rose-500' : 'text-slate-400'} line-through decoration-slate-400/50`}>
                               {formatCurrency(cashBalance)}
                           </span>
                           <ArrowRightCircle size={12} className="text-slate-400" />
                           <span className={`text-xs font-mono font-bold ${projectedCashBalance < 0 ? 'text-rose-600 dark:text-rose-400' : 'text-slate-900 dark:text-white'}`}>
                               {formatCurrency(projectedCashBalance)}
                           </span>
                       </div>
                   </div>
                   {projectedCashBalance < 0 && (
                      <div className="mt-1 text-[10px] text-rose-500 font-bold flex items-center">
                          <AlertCircle size={10} className="mr-1" />
                          Warning: Negative cash balance
                      </div>
                   )}
               </div>
           </div>
        )}

      </form>

      {/* 6. FOOTER ACTIONS */}
      <div className="px-6 py-4 border-t border-slate-100 dark:border-slate-800 bg-white dark:bg-slate-900 z-10">
         {error && (
            <div className="bg-rose-50 text-rose-600 px-4 py-2 rounded-xl text-sm font-bold flex items-center mb-3 animate-fade-in">
                <AlertCircle size={16} className="mr-2" /> {error}
            </div>
         )}
         <div className="flex gap-3">
             {initialData && onDelete && (
                 <button type="button" onClick={() => onDelete(initialData.id)} className="p-3 rounded-xl bg-rose-50 text-rose-500 hover:bg-rose-100 dark:bg-rose-900/10 dark:hover:bg-rose-900/20 transition-colors"><Trash2 size={20} /></button>
             )}
             <button 
                onClick={handleSubmit} disabled={isSaving}
                className={`flex-1 py-3 rounded-xl font-bold text-base text-white shadow-xl transition-all active:scale-95 flex items-center justify-center space-x-2 ${isSaving ? 'bg-slate-400 cursor-not-allowed' : `bg-${themeColor}-600 hover:bg-${themeColor}-700 shadow-${themeColor}-500/30`}`}
             >
                {isSaving ? <Spinner className="text-white" /> : (
                  <>
                    <Save size={18} />
                    <span>{initialData ? 'Update' : 'Save'}</span>
                  </>
                )}
             </button>
         </div>
      </div>
    </>
  );
};

// Mini icon component for local usage
const ChevronDownIcon = () => (
  <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="m6 9 6 6 6-6"/></svg>
);

export default App;

export enum TransactionType {
  BUY = 'BUY',
  SELL = 'SELL',
  DEPOSIT = 'DEPOSIT',
  WITHDRAW = 'WITHDRAW',
  DIVIDEND = 'DIVIDEND',
  SPLIT = 'SPLIT'
}

export enum AssetClass {
  STOCK = 'Stock',
  CRYPTO = 'Crypto',
  FUND = 'Fund',
  ETF = 'ETF',
  BOND = 'Bond',
  REAL_ESTATE = 'Real Estate',
  GOLD = 'Gold',
  CASH = 'Cash'
}

export interface Portfolio {
  id: string;
  name: string;
}

export interface Transaction {
  id: string;
  date: string;
  type: TransactionType;
  symbol?: string; // e.g., AAPL, BTC
  name?: string; // e.g., Apple Inc.
  assetClass?: AssetClass;
  sector?: string; // e.g., Tech, Finance
  shares?: number; // For SPLIT, this stores the Ratio (e.g. 2 for 2:1)
  price?: number; // Price per share or Amount for Deposit/Withdraw
  fee?: number;
  exchangeRate?: number; // 1 for local currency
  notes?: string;
}

export interface Holding {
  symbol: string;
  name: string;
  assetClass: AssetClass;
  sector: string;
  shares: number;
  avgCost: number;
  totalCost: number;
  currentPrice: number;
  marketValue: number;
  unrealizedPL: number;
  unrealizedPLPercent: number;
  realizedPL: number;
  totalDividends: number;
  totalReturn: number;
}

export interface MonthlyReturn {
  yearMonth: string; // YYYY-MM
  value: number; // Percentage
}

export interface FinancialGoal {
  id: string;
  targetAmount: number;
  startDate: string; // ISO Date
  endDate?: string; // ISO Date (if completed/changed)
  isAchieved: boolean;
  notes?: string;
}

export interface PortfolioState {
  transactions: Transaction[];
  prices: Record<string, number>; // symbol -> current price
  financialGoal: number; // Deprecated in favor of goals list, kept for legacy type safety if needed
  goals: FinancialGoal[];
  monthlyReturns: Record<string, number>; // YYYY-MM -> %
}

export interface ChartDataPoint {
  date: string;
  invested: number;
  value: number;
}

import React, { useState, useEffect, useMemo, useRef } from 'react';
import Layout from './components/Layout';
import Dashboard from './components/Dashboard';
import Holdings from './components/Holdings';
import Reports from './components/Reports';
import History from './components/History';
import GoalModal from './components/GoalModal';
import { Transaction, TransactionType, AssetClass, Holding, Portfolio, FinancialGoal } from './types';
import { calculateHoldings, calculatePortfolioHistory, generateId, formatCurrency, formatNumber } from './utils';
import { X, Save, TrendingUp, TrendingDown, DollarSign, Wallet, Calendar, GitFork, AlertCircle, ArrowRight, Trash2, Zap, Calculator, Search, Clock, PlusCircle, MinusCircle, RefreshCcw, Split, Hash, ChevronDown, ArrowRightCircle, Globe, CheckCircle2, FileText, Banknote, Percent } from 'lucide-react';
import { Spinner } from './components/LoadingSkeletons';

const POPULAR_SYMBOLS = [
  'AAPL', 'MSFT', 'GOOGL', 'AMZN', 'NVDA', 'TSLA', 'META', 'BRK.B', 'V', 'JNJ', 'WMT', 'JPM', // Tech/Blue Chip
  'VOO', 'VTI', 'QQQ', 'IVV', 'SCHD', 'JEPI', 'VUG', 'VTV', // ETFs
  'BTC', 'ETH', 'SOL', 'USDT', 'BNB', 'XRP', 'ADA' // Crypto
];

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState('dashboard');
  const [isAddModalOpen, setIsAddModalOpen] = useState(false);
  const [editingTransaction, setEditingTransaction] = useState<Transaction | null>(null);

  // Persistence for better UX
  const [lastTxDate, setLastTxDate] = useState<string>(() => localStorage.getItem('lastTxDate') || new Date().toISOString().split('T')[0]);

  // Goal Modal State
  const [isGoalModalOpen, setIsGoalModalOpen] = useState(false);

  // --- CONFIRMATION MODAL STATE ---
  const [confirmConfig, setConfirmConfig] = useState<{
    isOpen: boolean;
    title: string;
    message: string;
    onConfirm: () => void;
  }>({
    isOpen: false,
    title: '',
    message: '',
    onConfirm: () => {},
  });

  // --- PORTFOLIO MANAGEMENT STATE ---
  const [portfolios, setPortfolios] = useState<Portfolio[]>(() => {
    const saved = localStorage.getItem('portfolios');
    if (saved) return JSON.parse(saved);
    const legacyTx = localStorage.getItem('transactions');
    if (legacyTx) return [{ id: 'default', name: 'Main Portfolio' }];
    return [{ id: generateId(), name: 'My First Portfolio' }];
  });

  const [activePortfolioId, setActivePortfolioId] = useState<string>(() => {
    const saved = localStorage.getItem('activePortfolioId');
    const portfolios = JSON.parse(localStorage.getItem('portfolios') || '[]');
    if (saved && portfolios.some((p: Portfolio) => p.id === saved)) return saved;
    return portfolios.length > 0 ? portfolios[0].id : 'default';
  });

  // --- DATA STATE (Per Portfolio) - Synchronous Initialization ---
  const [transactions, setTransactions] = useState<Transaction[]>(() => {
    const key = `transactions_${activePortfolioId}`;
    const saved = localStorage.getItem(key);
    if (saved) return JSON.parse(saved);
    if (activePortfolioId === 'default') {
      const legacy = localStorage.getItem('transactions');
      if (legacy) return JSON.parse(legacy);
    }
    return [];
  });

  const [prices, setPrices] = useState<Record<string, number>>(() => {
    const key = `prices_${activePortfolioId}`;
    const saved = localStorage.getItem(key);
    if (saved) return JSON.parse(saved);
    if (activePortfolioId === 'default') {
      const legacy = localStorage.getItem('prices');
      if (legacy) return JSON.parse(legacy);
    }
    return {};
  });

  const [goals, setGoals] = useState<FinancialGoal[]>(() => {
    const key = `goals_${activePortfolioId}`;
    const saved = localStorage.getItem(key);
    if (saved) return JSON.parse(saved);

    let legacyGoal = 100000;
    const legacyKey = `financialGoal_${activePortfolioId}`;
    const savedLegacy = localStorage.getItem(legacyKey);
    if (savedLegacy) legacyGoal = parseFloat(savedLegacy);
    else if (activePortfolioId === 'default' && localStorage.getItem('financialGoal')) legacyGoal = parseFloat(localStorage.getItem('financialGoal')!);

    return [{ id: generateId(), targetAmount: legacyGoal, startDate: new Date().toISOString(), isAchieved: false, notes: 'Initial Goal' }];
  });

  const [isDataLoaded, setIsDataLoaded] = useState(true);
  const [isLoading, setIsLoading] = useState(false);
  const isFirstMount = useRef(true);

  // --- PERSISTENCE ---
  useEffect(() => { localStorage.setItem('portfolios', JSON.stringify(portfolios)); }, [portfolios]);
  useEffect(() => { localStorage.setItem('activePortfolioId', activePortfolioId); }, [activePortfolioId]);

  useEffect(() => {
    if (isFirstMount.current) { isFirstMount.current = false; return; }
    setIsLoading(true);
    setIsDataLoaded(false);
    const loadData = () => {
        const txKey = `transactions_${activePortfolioId}`;
        const pricesKey = `prices_${activePortfolioId}`;
        const goalsKey = `goals_${activePortfolioId}`;

        const savedTx = localStorage.getItem(txKey);
        setTransactions(savedTx ? JSON.parse(savedTx) : []);

        const savedPrices = localStorage.getItem(pricesKey);
        setPrices(savedPrices ? JSON.parse(savedPrices) : {});

        const savedGoals = localStorage.getItem(goalsKey);
        setGoals(savedGoals ? JSON.parse(savedGoals) : []); 

        setIsDataLoaded(true);
        setTimeout(() => setIsLoading(false), 500);
    };
    requestAnimationFrame(loadData);
  }, [activePortfolioId]);

  useEffect(() => { if (isDataLoaded) localStorage.setItem(`transactions_${activePortfolioId}`, JSON.stringify(transactions)); }, [transactions, activePortfolioId, isDataLoaded]);
  useEffect(() => { if (isDataLoaded) localStorage.setItem(`prices_${activePortfolioId}`, JSON.stringify(prices)); }, [prices, activePortfolioId, isDataLoaded]);
  useEffect(() => { if (isDataLoaded) localStorage.setItem(`goals_${activePortfolioId}`, JSON.stringify(goals)); }, [goals, activePortfolioId, isDataLoaded]);

  // --- CALCULATIONS ---
  const holdings = useMemo(() => calculateHoldings(transactions, prices), [transactions, prices]);
  const chartData = useMemo(() => calculatePortfolioHistory(transactions, prices), [transactions, prices]);
  const investedAmount = transactions.reduce((sum, t) => {
    if (t.type === TransactionType.DEPOSIT) return sum + (t.price || 0);
    if (t.type === TransactionType.WITHDRAW) return sum - (t.price || 0);
    return sum;
  }, 0);
  const cashBalance = useMemo(() => {
    let balance = 0;
    transactions.forEach(t => {
      if (t.type === TransactionType.DEPOSIT) balance += (t.price || 0);
      if (t.type === TransactionType.WITHDRAW) balance -= (t.price || 0);
      if (t.type === TransactionType.BUY) balance -= (t.price! * t.shares!) + (t.fee || 0);
      if (t.type === TransactionType.SELL) balance += (t.price! * t.shares!) - (t.fee || 0);
      if (t.type === TransactionType.DIVIDEND) balance += (t.price || 0);
    });
    return balance;
  }, [transactions]);
  const portfolioValue = holdings.reduce((sum, h) => sum + h.marketValue, 0);
  const totalNetWorth = portfolioValue + cashBalance;
  const activeGoal = useMemo(() => goals.find(g => !g.endDate) || { targetAmount: 100000 } as FinancialGoal, [goals]);

  // --- HANDLERS ---
  const handleOpenAddModal = () => { setEditingTransaction(null); setIsAddModalOpen(true); };
  const handleOpenEditModal = (tx: Transaction) => { setEditingTransaction(tx); setIsAddModalOpen(true); };

  const handleSaveTransaction = (tx: Transaction) => {
    return new Promise<void>((resolve) => {
      if (editingTransaction) setTransactions(prev => prev.map(t => t.id === tx.id ? tx : t));
      else setTransactions(prev => [...prev, tx]);

      // Update price reference
      if ((tx.type === TransactionType.BUY || tx.type === TransactionType.SELL) && tx.symbol && tx.price) {
        setPrices(prev => ({...prev, [tx.symbol!]: tx.price!}));
      }

      // Update Last Used Date Persistence
      setLastTxDate(tx.date);
      localStorage.setItem('lastTxDate', tx.date);

      setIsAddModalOpen(false); 
      setEditingTransaction(null); 
      resolve();
    });
  };

  const handleUpdatePrice = (symbol: string, newPrice: number) => setPrices(prev => ({ ...prev, [symbol]: newPrice }));
  const handleDeleteTransaction = (id: string) => {
    setTransactions(prev => prev.filter(t => t.id !== id));
    if (editingTransaction && editingTransaction.id === id) { setIsAddModalOpen(false); setEditingTransaction(null); }
  };
  const handleRequestDelete = (id: string) => {
      setConfirmConfig({ isOpen: true, title: 'Delete Transaction', message: 'Permanently remove this record?', onConfirm: () => { handleDeleteTransaction(id); setConfirmConfig(prev => ({ ...prev, isOpen: false })); } });
  };
  const handleImportTransactions = (importedTxs: Transaction[]) => {
      setTransactions(prev => {
          const currentMap = new Map(prev.map(t => [t.id, t]));
          importedTxs.forEach(t => { currentMap.set(t.id, t); });
          return Array.from(currentMap.values());
      });
  };

  // Portfolios
  const handleCreatePortfolio = (name: string) => { const newId = generateId(); setPortfolios([...portfolios, { id: newId, name }]); setActivePortfolioId(newId); };
  const handleRenamePortfolio = (id: string, newName: string) => { setPortfolios(prev => prev.map(p => p.id === id ? { ...p, name: newName } : p)); };
  const handleDeletePortfolio = (id: string) => {
    if (portfolios.length <= 1) { alert("Cannot delete last portfolio"); return; }
    setConfirmConfig({
        isOpen: true, title: 'Delete Portfolio', message: 'Delete entire portfolio and all data?', 
        onConfirm: () => {
             localStorage.removeItem(`transactions_${id}`); localStorage.removeItem(`prices_${id}`); localStorage.removeItem(`goals_${id}`);
             const newPortfolios = portfolios.filter(p => p.id !== id); setPortfolios(newPortfolios);
             if (activePortfolioId === id) setActivePortfolioId(newPortfolios[0].id);
             setConfirmConfig(prev => ({ ...prev, isOpen: false }));
        }
    });
  };

  // Goals
  const handleSetNewGoal = (targetAmount: number, notes: string) => {
    const now = new Date().toISOString();
    setGoals(prev => [...prev.map(g => !g.endDate ? { ...g, endDate: now, isAchieved: totalNetWorth >= g.targetAmount } : g), { id: generateId(), targetAmount, startDate: now, isAchieved: false, notes }]);
  };
  const handleEditGoal = (updatedGoal: FinancialGoal) => setGoals(prev => prev.map(g => g.id === updatedGoal.id ? updatedGoal : g));
  const handleDeleteGoal = (id: string) => setGoals(prev => prev.filter(g => g.id !== id));

  return (
    <Layout 
      activeTab={activeTab} setActiveTab={setActiveTab} onOpenAddModal={handleOpenAddModal}
      portfolios={portfolios} activePortfolioId={activePortfolioId} onSwitchPortfolio={setActivePortfolioId}
      onCreatePortfolio={handleCreatePortfolio} onRenamePortfolio={handleRenamePortfolio} onDeletePortfolio={handleDeletePortfolio}
    >
      <div key={activePortfolioId} className="h-full">
        {activeTab === 'dashboard' && <Dashboard isLoading={isLoading} holdings={holdings} transactions={transactions} financialGoal={activeGoal.targetAmount} onOpenGoalModal={() => setIsGoalModalOpen(true)} investedAmount={investedAmount} cashBalance={cashBalance} portfolioValue={portfolioValue} chartData={chartData} />}
        {activeTab === 'holdings' && <Holdings isLoading={isLoading} holdings={holdings} transactions={transactions} onUpdatePrice={handleUpdatePrice} />}
        {activeTab === 'history' && <History isLoading={isLoading} transactions={transactions} onDelete={handleRequestDelete} onEdit={handleOpenEditModal} onAdd={handleOpenAddModal} onImport={handleImportTransactions} />}
        {activeTab === 'reports' && <Reports isLoading={isLoading} transactions={transactions} currentPortfolioValue={portfolioValue + cashBalance} chartData={chartData} />}
      </div>

      {isAddModalOpen && (
        <div className="fixed inset-0 z-50 flex items-end sm:items-center justify-center sm:p-4">
          <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-sm animate-fade-in" onClick={() => setIsAddModalOpen(false)}></div>
          <div className="relative bg-white dark:bg-slate-900 w-full max-w-2xl rounded-t-3xl sm:rounded-3xl shadow-2xl overflow-hidden animate-slide-up flex flex-col max-h-[90dvh]">
            <AddTransactionForm 
              onClose={() => setIsAddModalOpen(false)} 
              onSave={handleSaveTransaction} 
              onDelete={handleRequestDelete} 
              cashBalance={cashBalance} 
              holdings={holdings} 
              prices={prices} 
              transactions={transactions} 
              initialData={editingTransaction}
              defaultDate={lastTxDate}
            />
          </div>
        </div>
      )}

      <GoalModal isOpen={isGoalModalOpen} onClose={() => setIsGoalModalOpen(false)} goals={goals} currentNetWorth={totalNetWorth} onSetGoal={handleSetNewGoal} onEditGoal={handleEditGoal} onDeleteGoal={handleDeleteGoal} />

      {confirmConfig.isOpen && (
        <div className="fixed inset-0 z-[70] flex items-center justify-center p-4 animate-fade-in">
          <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-sm" onClick={() => setConfirmConfig(prev => ({ ...prev, isOpen: false }))}></div>
          <div className="relative bg-white dark:bg-slate-900 rounded-2xl shadow-2xl w-full max-w-sm overflow-hidden animate-zoom-in p-6 text-center">
              <Trash2 size={40} className="mx-auto text-rose-500 mb-4" />
              <h3 className="text-lg font-bold text-slate-900 dark:text-white mb-2">{confirmConfig.title}</h3>
              <p className="text-sm text-slate-500 dark:text-slate-400 mb-6">{confirmConfig.message}</p>
              <div className="flex space-x-3">
                <button onClick={() => setConfirmConfig(prev => ({ ...prev, isOpen: false }))} className="flex-1 py-3 rounded-xl font-bold bg-slate-100 dark:bg-slate-800 text-slate-600 dark:text-slate-400">Cancel</button>
                <button onClick={confirmConfig.onConfirm} className="flex-1 py-3 rounded-xl font-bold bg-rose-600 text-white shadow-lg shadow-rose-600/20">Delete</button>
              </div>
          </div>
        </div>
      )}
    </Layout>
  );
};

interface AddTransactionFormProps {
  onClose: () => void;
  onSave: (t: Transaction) => Promise<void>;
  onDelete?: (id: string) => void;
  cashBalance: number;
  holdings: Holding[];
  prices: Record<string, number>;
  transactions: Transaction[];
  initialData: Transaction | null;
  defaultDate: string;
}

const AddTransactionForm: React.FC<AddTransactionFormProps> = ({ onClose, onSave, onDelete, cashBalance, holdings, prices, transactions, initialData, defaultDate }) => {
  const [step, setStep] = useState<'input' | 'review'>('input');

  const [type, setType] = useState<TransactionType>(TransactionType.BUY);
  const [date, setDate] = useState(defaultDate);
  const [symbol, setSymbol] = useState('');
  const [shares, setShares] = useState('');
  const [price, setPrice] = useState(''); // Price per share
  const [totalAmount, setTotalAmount] = useState(''); // Total transaction value
  const [fee, setFee] = useState('');
  const [assetClass, setAssetClass] = useState<AssetClass>(AssetClass.STOCK);
  const [exchangeRate, setExchangeRate] = useState(''); 
  const [notes, setNotes] = useState('');
  const [error, setError] = useState<string | null>(null);
  const [isSaving, setIsSaving] = useState(false);

  // Track which input is driving the calculation
  const [activeInput, setActiveInput] = useState<'shares' | 'price' | 'total' | null>(null);
  const [showSuggestions, setShowSuggestions] = useState(false);
  const wrapperRef = useRef<HTMLDivElement>(null);

  // Validation logic helpers
  const needsSymbol = [TransactionType.BUY, TransactionType.SELL, TransactionType.DIVIDEND, TransactionType.SPLIT].includes(type);
  const needsShares = [TransactionType.BUY, TransactionType.SELL, TransactionType.SPLIT].includes(type);
  const needsPrice = type !== TransactionType.SPLIT;

  // FX Rate is relevant for: Deposits, Withdrawals, and Dividends (Foreign income)
  const hasExchangeRate = type === TransactionType.DEPOSIT || type === TransactionType.WITHDRAW || type === TransactionType.DIVIDEND;
  const isFunding = type === TransactionType.DEPOSIT || type === TransactionType.WITHDRAW;

  // Effects (Initialization, Auto-fill, Calculation)
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => { if (wrapperRef.current && !wrapperRef.current.contains(event.target as Node)) setShowSuggestions(false); };
    document.addEventListener("mousedown", handleClickOutside); return () => document.removeEventListener("mousedown", handleClickOutside);
  }, []);

  useEffect(() => {
    if (initialData) {
      setType(initialData.type); setDate(initialData.date); setSymbol(initialData.symbol || '');
      setShares(initialData.shares?.toString() || ''); setPrice(initialData.price?.toString() || '');
      setFee(initialData.fee?.toString() || ''); setAssetClass(initialData.assetClass || AssetClass.STOCK);
      setExchangeRate(initialData.exchangeRate?.toString() || ''); setNotes(initialData.notes || '');
      if (initialData.shares && initialData.price && (initialData.type === TransactionType.BUY || initialData.type === TransactionType.SELL)) {
         setTotalAmount((initialData.shares * initialData.price).toFixed(2));
      } else if (initialData.price) setTotalAmount(initialData.price.toString());
    }
  }, [initialData]);

  // Auto-fill price from holdings or market data
  useEffect(() => {
    if (!initialData && symbol && !price && !activeInput) {
       const h = holdings.find(h => h.symbol === symbol.toUpperCase());
       if (h) { setAssetClass(h.assetClass); if (h.currentPrice > 0) setPrice(h.currentPrice.toString()); }
       else { const kp = prices[symbol.toUpperCase()]; if (kp) setPrice(kp.toString()); }
    }
  }, [symbol]);

  // Bi-directional Calculation
  useEffect(() => {
    const s = parseFloat(shares) || 0; 
    const p = parseFloat(price) || 0; 
    const t = parseFloat(totalAmount) || 0;

    // Only auto-calc if user is actively typing in one field to update the other
    if ((activeInput === 'shares' || activeInput === 'price') && s > 0 && p > 0) {
        setTotalAmount((s * p).toFixed(2));
    }
    if (activeInput === 'total' && t > 0 && p > 0) {
        setShares((t / p).toFixed(4));
    }
  }, [shares, price, totalAmount, activeInput]);

  // Max Button Handlers
  const handleMax = () => {
    const p = parseFloat(price);

    if (type === TransactionType.BUY) {
        if (p > 0) {
            // Max buyable with current cash (minus fee estimation if we wanted to be complex, but simple is better)
            const maxAmt = Math.max(0, cashBalance);
            setTotalAmount(maxAmt.toFixed(2));
            setShares((maxAmt / p).toFixed(4));
            setActiveInput('total');
        } else {
            setTotalAmount(cashBalance.toFixed(2));
            setActiveInput('total');
        }
    } else if (type === TransactionType.SELL) {
        const holding = holdings.find(h => h.symbol === symbol.toUpperCase());
        if (holding) {
            setShares(holding.shares.toString());
            if (p > 0) setTotalAmount((holding.shares * p).toFixed(2));
            setActiveInput('shares');
        }
    }
  };

  // IMPACT CALCULATIONS FOR SUMMARY
  const currentCashImpact = useMemo(() => {
     const qty = parseFloat(shares) || 0;
     const unitPrice = parseFloat(price) || 0;
     const feeVal = parseFloat(fee) || 0;
     const amt = parseFloat(totalAmount) || 0;

     if (type === TransactionType.BUY) return -((qty * unitPrice) + feeVal);
     if (type === TransactionType.SELL) return ((qty * unitPrice) - feeVal);
     if (type === TransactionType.DEPOSIT) return amt;
     if (type === TransactionType.WITHDRAW) return -amt;
     if (type === TransactionType.DIVIDEND) return amt;
     return 0;
  }, [type, shares, price, fee, totalAmount]);

  const originalCashImpact = useMemo(() => {
    if (!initialData) return 0;
    const qty = initialData.shares || 0;
    const unitPrice = initialData.price || 0;
    const feeVal = initialData.fee || 0;

    if (initialData.type === TransactionType.BUY) return -((qty * unitPrice) + feeVal);
    if (initialData.type === TransactionType.SELL) return ((qty * unitPrice) - feeVal);
    if (initialData.type === TransactionType.DEPOSIT) return unitPrice; 
    if (initialData.type === TransactionType.WITHDRAW) return -unitPrice;
    if (initialData.type === TransactionType.DIVIDEND) return unitPrice;
    return 0;
  }, [initialData]);

  const projectedCashBalance = cashBalance - originalCashImpact + currentCashImpact;

  // Validation
  const validate = () => {
    if (needsSymbol && !symbol) return "Asset Symbol is required.";
    if (!needsSymbol && !totalAmount) return "Amount is required.";

    // Sell Check
    if (type === TransactionType.SELL) {
        const holding = holdings.find(h => h.symbol === symbol.toUpperCase());
        const currentShares = holding ? holding.shares : 0;
        const originalShares = (initialData && initialData.type === TransactionType.SELL && initialData.symbol === symbol) ? (initialData.shares || 0) : 0;
        const available = currentShares + originalShares;

        if ((parseFloat(shares) || 0) > available) {
            return `Insufficient shares. Owned: ${formatNumber(available)}. Selling: ${shares}.`;
        }
    }

    // Strict Negative Cash Warning 
    if ((type === TransactionType.WITHDRAW || type === TransactionType.BUY) && projectedCashBalance < 0) {
        return "Insufficient funds. Transaction exceeds cash balance.";
    }

    return null;
  };

  const handleReview = (e: React.FormEvent) => {
      e.preventDefault();
      const errMsg = validate();
      if (errMsg) return setError(errMsg);
      setError(null);
      setStep('review');
  };

  const handleFinalSubmit = async () => {
    setIsSaving(true);
    await onSave({
      id: initialData ? initialData.id : generateId(),
      date, type, symbol: needsSymbol ? symbol.toUpperCase() : undefined,
      shares: needsShares ? parseFloat(shares) : undefined,
      // For types that don't need shares (Deposit, Withdraw, Dividend), use the total amount as price
      price: type === TransactionType.SPLIT ? 0 : (needsShares ? parseFloat(price) : parseFloat(totalAmount)),
      fee: (fee && (type === TransactionType.BUY || type === TransactionType.SELL)) ? parseFloat(fee) : undefined,
      assetClass: !needsSymbol ? AssetClass.CASH : assetClass,
      exchangeRate: exchangeRate ? parseFloat(exchangeRate) : 1, notes: notes || undefined
    });
    setIsSaving(false);
  };

  const suggestions = useMemo(() => {
    if (!symbol) return [];
    const inputUpper = symbol.toUpperCase();
    return Array.from(new Set([...holdings.map(h => h.symbol), ...POPULAR_SYMBOLS])).filter(s => s.includes(inputUpper)).slice(0, 5);
  }, [symbol, holdings]);

  // Icons and Colors
  const getTypeConfig = (t: TransactionType) => {
    switch (t) {
        case TransactionType.BUY: return { color: 'blue', icon: <TrendingUp size={16} /> };
        case TransactionType.DEPOSIT: return { color: 'emerald', icon: <Wallet size={16} /> };
        case TransactionType.SELL: return { color: 'rose', icon: <TrendingDown size={16} /> };
        case TransactionType.WITHDRAW: return { color: 'orange', icon: <Banknote size={16} /> };
        case TransactionType.DIVIDEND: return { color: 'emerald', icon: <DollarSign size={16} /> };
        case TransactionType.SPLIT: return { color: 'purple', icon: <Split size={16} /> };
        default: return { color: 'slate', icon: <CheckCircle2 size={16} /> };
    }
  }
  const theme = getTypeConfig(type);

  // SUMMARY BAR
  const summaryBox = useMemo(() => {
     const absImpact = Math.abs(currentCashImpact);
     const isPositive = currentCashImpact >= 0;
     const portfolioPercent = (totalNetWorth > 0) ? (absImpact / totalNetWorth) * 100 : 0;

     return (
         <div className="bg-slate-100 dark:bg-slate-800/80 rounded-2xl p-5 border border-slate-200 dark:border-slate-700 mt-4">
             <div className="flex justify-between items-start mb-4">
                 <div>
                    <p className="text-xs font-bold text-slate-500 uppercase tracking-wider">Net Cash Impact</p>
                    <h3 className={`text-2xl font-bold font-display ${isPositive ? 'text-emerald-600' : 'text-rose-600'}`}>
                        {isPositive ? '+' : '-'}{formatCurrency(absImpact)}
                    </h3>
                    <p className="text-[10px] text-slate-400 mt-1 font-medium flex items-center">
                        <Percent size={10} className="mr-1"/>
                        ≈ {portfolioPercent.toFixed(1)}% of Total Portfolio
                    </p>
                 </div>
                 <div className="text-right">
                    <p className="text-xs font-bold text-slate-500 uppercase tracking-wider">Projected Cash</p>
                    <p className="text-xl font-bold font-mono text-slate-800 dark:text-slate-200">{formatCurrency(projectedCashBalance)}</p>
                 </div>
             </div>

             {/* Progress Bar */}
             <div className="relative h-2.5 bg-slate-200 dark:bg-slate-700 rounded-full overflow-hidden">
                 {/* Background: Current Balance */}
                 <div 
                    className="absolute top-0 left-0 h-full bg-slate-400 dark:bg-slate-500 transition-all" 
                    style={{ width: '100%' }} // Simplified visualization, always show full width as base
                 ></div>

                 {/* Overlay: New Balance (if shrinking) */}
                 {projectedCashBalance < cashBalance && (
                    <div 
                        className="absolute top-0 right-0 h-full bg-rose-500 transition-all animate-pulse" 
                        style={{ width: `${((cashBalance - projectedCashBalance)/cashBalance)*100}%` }}
                    ></div>
                 )}
                 {/* Overlay: New Balance (if growing) */}
                 {projectedCashBalance > cashBalance && (
                     <div 
                        className="absolute top-0 left-0 h-full bg-emerald-500 transition-all" 
                         style={{ width: '100%' }} // If growing, it fills and overflows conceptually
                     ></div>
                 )}
             </div>
             <div className="flex justify-between text-[10px] text-slate-400 mt-1.5 font-bold uppercase">
                 <span>Before: {formatCurrency(cashBalance)}</span>
                 <span>After: {formatCurrency(projectedCashBalance)}</span>
             </div>
         </div>
     )
  }, [currentCashImpact, projectedCashBalance, cashBalance, totalNetWorth]);

  // RENDER: REVIEW STEP
  if (step === 'review') {
      return (
          <div className="flex flex-col h-full bg-white dark:bg-slate-900">
             <div className="p-6 text-center border-b border-slate-100 dark:border-slate-800">
                <div className={`w-16 h-16 mx-auto rounded-full bg-${theme.color}-100 dark:bg-${theme.color}-900/30 text-${theme.color}-600 dark:text-${theme.color}-400 flex items-center justify-center mb-4 shadow-lg shadow-${theme.color}-500/20`}>
                   {theme.icon}
                </div>
                <h3 className="text-xl font-display font-bold text-slate-900 dark:text-white">Review Transaction</h3>
                <p className="text-sm text-slate-500">Please confirm details before saving.</p>
             </div>

             <div className="flex-1 overflow-y-auto p-6 space-y-6">
                 {/* Details Card */}
                 <div className="bg-slate-50 dark:bg-slate-800/50 rounded-2xl p-5 border border-slate-200 dark:border-slate-700 space-y-4">
                     <div className="flex justify-between border-b border-slate-200 dark:border-slate-700 pb-2">
                        <span className="text-sm text-slate-500">Date</span>
                        <span className="text-sm font-bold text-slate-900 dark:text-white">{date}</span>
                     </div>
                     <div className="flex justify-between border-b border-slate-200 dark:border-slate-700 pb-2">
                        <span className="text-sm text-slate-500">Type</span>
                        <span className={`text-sm font-bold uppercase text-${theme.color}-600`}>{type}</span>
                     </div>
                     {needsSymbol && (
                         <div className="flex justify-between border-b border-slate-200 dark:border-slate-700 pb-2">
                            <span className="text-sm text-slate-500">Asset</span>
                            <span className="text-sm font-bold text-slate-900 dark:text-white">{symbol} <span className="text-xs text-slate-400 font-normal">({assetClass})</span></span>
                         </div>
                     )}
                     <div className="flex justify-between border-b border-slate-200 dark:border-slate-700 pb-2">
                        <span className="text-sm text-slate-500">Total Amount</span>
                        <span className="text-lg font-bold text-slate-900 dark:text-white">{formatCurrency(parseFloat(totalAmount))}</span>
                     </div>
                     {needsShares && (
                        <div className="flex justify-between pt-1">
                            <span className="text-xs text-slate-400">Details</span>
                            <span className="text-xs text-slate-500">{shares} units @ {formatCurrency(parseFloat(price))}</span>
                        </div>
                     )}
                 </div>

                 {projectedCashBalance < 0 && (
                     <div className="bg-rose-50 text-rose-600 p-4 rounded-xl text-sm font-bold flex items-center">
                         <AlertCircle size={20} className="mr-3 shrink-0" />
                         WARNING: This transaction will result in a negative cash balance.
                     </div>
                 )}
             </div>

             <div className="p-6 border-t border-slate-100 dark:border-slate-800 flex gap-4">
                 <button onClick={() => setStep('input')} className="flex-1 py-3 rounded-xl font-bold bg-slate-100 dark:bg-slate-800 text-slate-600 dark:text-slate-300 hover:bg-slate-200 dark:hover:bg-slate-700 transition-colors">
                    Back to Edit
                 </button>
                 <button onClick={handleFinalSubmit} disabled={isSaving} className={`flex-1 py-3 rounded-xl font-bold text-white shadow-xl flex items-center justify-center space-x-2 bg-${theme.color}-600 hover:bg-${theme.color}-700 transition-all`}>
                    {isSaving ? <Spinner className="text-white" /> : (
                        <>
                            <CheckCircle2 size={18} />
                            <span>Confirm & Save</span>
                        </>
                    )}
                 </button>
             </div>
          </div>
      )
  }

  // RENDER: INPUT STEP
  return (
    <>
      <div className="shrink-0 px-6 py-4 border-b border-slate-100 dark:border-slate-800 flex justify-between items-center bg-white dark:bg-slate-900">
          <h3 className="text-lg font-display font-bold text-slate-900 dark:text-white">{initialData ? 'Edit Transaction' : 'New Transaction'}</h3>
          <button onClick={onClose} className="bg-slate-100 dark:bg-slate-800 p-2 rounded-full text-slate-500 hover:text-slate-800 dark:hover:text-white transition-colors"><X size={20} /></button>
      </div>

      <form onSubmit={handleReview} className="flex-1 overflow-y-auto min-h-0 p-6 custom-scrollbar bg-white dark:bg-slate-900">

        {/* 1. Transaction Type Selector with Icons */}
        <div className="mb-6">
           <label className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-3 block">Transaction Type</label>
           <div className="grid grid-cols-3 sm:grid-cols-6 gap-2">
              {[TransactionType.BUY, TransactionType.SELL, TransactionType.DEPOSIT, TransactionType.WITHDRAW, TransactionType.DIVIDEND, TransactionType.SPLIT].map(t => {
                 const isActive = type === t;
                 const config = getTypeConfig(t);

                 return (
                   <button
                      key={t} type="button" onClick={() => setType(t)}
                      className={`flex flex-col items-center justify-center py-2.5 px-1 rounded-xl text-[10px] sm:text-xs font-bold transition-all border ${
                         isActive 
                         ? `border-transparent bg-${config.color}-600 text-white shadow-md shadow-${config.color}-500/20 transform scale-105` 
                         : 'bg-white dark:bg-slate-800 border-slate-200 dark:border-slate-700 text-slate-500 dark:text-slate-400 hover:border-slate-300 dark:hover:border-slate-600 hover:bg-slate-50'
                      }`}
                   >
                      <div className="mb-1">{config.icon}</div>
                      {t}
                   </button>
                 )
              })}
           </div>
        </div>

        <div className="grid md:grid-cols-2 gap-8">
            {/* LEFT COLUMN: DETAILS */}
            <div className="space-y-5">
                <div className="flex items-center space-x-2 text-slate-800 dark:text-slate-200 border-b border-slate-100 dark:border-slate-800 pb-2">
                    <FileText size={18} />
                    <h4 className="font-bold text-sm uppercase tracking-wide">Transaction Details</h4>
                </div>

                <div>
                   <label className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-1.5 block">Date</label>
                   <div className="relative">
                      <Calendar className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={16} />
                      <input type="date" value={date} onChange={e => setDate(e.target.value)} className="w-full pl-10 pr-4 py-2.5 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl font-medium text-sm focus:ring-2 focus:ring-blue-500 outline-none transition-all" />
                   </div>
                </div>

                {needsSymbol && (
                    <div className="relative z-20" ref={wrapperRef}>
                        <label className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-1.5 block">Asset Symbol</label>
                        <div className="relative group">
                            <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400 group-focus-within:text-blue-500 transition-colors" size={18} />
                            <input 
                               type="text" placeholder="e.g. AAPL" value={symbol} 
                               onChange={e => { setSymbol(e.target.value); setShowSuggestions(true); }}
                               onFocus={() => setShowSuggestions(true)}
                               className="w-full pl-10 pr-4 py-3 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl text-lg font-bold uppercase tracking-wide focus:ring-2 focus:ring-blue-500 focus:bg-white dark:focus:bg-slate-800 outline-none transition-all"
                            />
                             {showSuggestions && suggestions.length > 0 && (
                                <div className="absolute top-full left-0 right-0 mt-2 bg-white dark:bg-slate-800 rounded-xl shadow-xl border border-slate-100 dark:border-slate-700 overflow-hidden z-50 animate-fade-in">
                                    {suggestions.map(s => (
                                        <div key={s} onMouseDown={(e) => { e.preventDefault(); setSymbol(s); setShowSuggestions(false); }} className="px-4 py-2 hover:bg-slate-50 dark:hover:bg-slate-700 cursor-pointer font-bold text-slate-700 dark:text-slate-300 flex justify-between text-sm">
                                           <span>{s}</span>
                                           <span className="text-xs text-slate-400 font-normal">Select</span>
                                        </div>
                                    ))}
                                </div>
                            )}
                        </div>
                    </div>
                 )}

                 {needsSymbol && (
                    <div>
                        <label className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-1.5 block">Asset Class</label>
                        <select value={assetClass} onChange={e => setAssetClass(e.target.value as AssetClass)} className="w-full px-4 py-2.5 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl font-medium text-sm outline-none focus:ring-2 focus:ring-blue-500 transition-all cursor-pointer">
                            {Object.values(AssetClass).filter(a => a !== AssetClass.CASH).map(a => <option key={a} value={a}>{a}</option>)}
                        </select>
                    </div>
                 )}
            </div>

            {/* RIGHT COLUMN: FINANCIALS */}
            <div className="space-y-5">
                <div className="flex items-center space-x-2 text-slate-800 dark:text-slate-200 border-b border-slate-100 dark:border-slate-800 pb-2">
                    <DollarSign size={18} />
                    <h4 className="font-bold text-sm uppercase tracking-wide">Financials</h4>
                </div>

                {/* Amount / Price Fields */}
                {(needsPrice || isFunding) && (
                   <div>
                       <label className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-1.5 flex justify-between">
                           <span>{needsShares ? 'Total Amount' : 'Amount'}</span>
                           {type === TransactionType.BUY && (
                               <button type="button" onClick={handleMax} className="text-blue-500 hover:underline text-[10px]">Use Max Cash</button>
                           )}
                       </label>
                       <div className="relative group">
                           <span className={`absolute left-4 top-1/2 -translate-y-1/2 text-xl font-bold ${type === TransactionType.SELL || type === TransactionType.WITHDRAW ? 'text-rose-500' : 'text-blue-500'}`}>$</span>
                           <input 
                              type="number" step="any" min="0" placeholder="0.00"
                              value={totalAmount}
                              onFocus={() => setActiveInput('total')}
                              onChange={e => setTotalAmount(e.target.value)}
                              className="w-full pl-9 pr-4 py-2.5 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl text-2xl font-display font-bold text-slate-900 dark:text-white focus:ring-2 focus:ring-blue-500 focus:bg-white dark:focus:bg-slate-800 outline-none transition-all"
                           />
                       </div>
                   </div>
                 )}

                 <div className="grid grid-cols-2 gap-4">
                     {needsShares && (
                        <div>
                            <label className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-1.5 flex justify-between">
                                <span>Quantity</span>
                                {type === TransactionType.SELL && (
                                   <button type="button" onClick={handleMax} className="text-rose-500 hover:underline text-[10px]">Sell All</button>
                                )}
                            </label>
                            <input 
                                type="number" step="any" 
                                placeholder="0" 
                                value={shares}
                                onFocus={() => setActiveInput('shares')}
                                onChange={e => setShares(e.target.value)}
                                className="w-full px-3 py-2.5 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl font-medium text-sm focus:ring-2 focus:ring-blue-500 outline-none"
                            />
                        </div>
                     )}

                     {needsPrice && needsShares && (
                        <div>
                           <label className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-1.5 block">Price / Share</label>
                           <input 
                                type="number" step="any" placeholder="0.00" value={price}
                                onFocus={() => setActiveInput('price')}
                                onChange={e => setPrice(e.target.value)}
                                className="w-full px-3 py-2.5 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl font-medium text-sm focus:ring-2 focus:ring-blue-500 outline-none"
                            />
                        </div>
                     )}
                 </div>

                 {(type === TransactionType.BUY || type === TransactionType.SELL) && (
                    <div>
                        <label className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-1.5 block">Fee</label>
                        <input 
                             type="number" step="any" placeholder="0.00" value={fee} onChange={e => setFee(e.target.value)} 
                             className="w-full px-4 py-2 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl text-sm outline-none focus:ring-2 focus:ring-blue-500" 
                        />
                    </div>
                 )}

                 {hasExchangeRate && (
                    <div>
                       <label className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-1 block">Exchange Rate</label>
                       <input 
                         type="number" step="any" min="0" placeholder="1.0" 
                         value={exchangeRate} onChange={e => setExchangeRate(e.target.value)} 
                         className="w-full px-4 py-2 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl font-medium text-sm outline-none focus:ring-2 focus:ring-blue-500" 
                       />
                    </div>
                 )}
            </div>
        </div>

        {/* SUMMARY SECTION */}
        {summaryBox}

        {/* Notes Collapsible */}
        <details className="group mt-4">
            <summary className="flex items-center text-xs font-bold text-slate-400 uppercase tracking-wider cursor-pointer hover:text-blue-500 transition-colors w-fit">
               <span className="mr-2">Add Notes</span>
               <ChevronDown size={14} className="group-open:rotate-180 transition-transform" />
            </summary>
            <div className="mt-2 animate-slide-up">
                 <textarea 
                   rows={2} 
                   placeholder="E.g. Monthly DCA, Rebalancing..." 
                   value={notes} 
                   onChange={e => setNotes(e.target.value)} 
                   className="w-full px-4 py-2 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl text-sm outline-none resize-none transition-all focus:border-blue-400" 
                 />
            </div>
        </details>

      </form>

      {/* 6. FOOTER ACTIONS */}
      <div className="px-6 py-4 border-t border-slate-100 dark:border-slate-800 bg-white dark:bg-slate-900 z-10 flex gap-3">
             {error && (
                <div className="absolute bottom-full left-0 w-full px-6 pb-2">
                    <div className="bg-rose-50 text-rose-600 px-4 py-2 rounded-xl text-sm font-bold flex items-center animate-slide-up shadow-sm border border-rose-100">
                        <AlertCircle size={16} className="mr-2" /> {error}
                    </div>
                </div>
             )}

             {initialData && onDelete && (
                 <button type="button" onClick={() => onDelete(initialData.id)} className="p-3 rounded-xl bg-rose-50 text-rose-500 hover:bg-rose-100 dark:bg-rose-900/10 dark:hover:bg-rose-900/20 transition-colors"><Trash2 size={20} /></button>
             )}
             <button 
                onClick={handleReview} 
                className={`flex-1 py-3 rounded-xl font-bold text-base text-white shadow-xl transition-all active:scale-95 flex items-center justify-center space-x-2 bg-${theme.color}-600 hover:bg-${theme.color}-700 shadow-${theme.color}-500/30`}
             >
                <span>Review & Save</span>
                <ArrowRight size={18} />
             </button>
      </div>
    </>
  );
};

export default App;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import Layout from './components/Layout';
import Dashboard from './components/Dashboard';
import Holdings from './components/Holdings';
import Reports from './components/Reports';
import History from './components/History';
import GoalModal from './components/GoalModal';
import { Transaction, TransactionType, AssetClass, Holding, Portfolio, FinancialGoal } from './types';
import { calculateHoldings, calculatePortfolioHistory, generateId, formatCurrency, formatNumber } from './utils';
import { X, Save, TrendingUp, TrendingDown, DollarSign, Wallet, Calendar, GitFork, AlertCircle, ArrowRight, Trash2, Zap, Calculator, Search, Clock, PlusCircle, MinusCircle, RefreshCcw, Split, Hash, ChevronDown, ArrowRightCircle, Globe, CheckCircle2, FileText, Banknote, Percent } from 'lucide-react';
import { Spinner } from './components/LoadingSkeletons';

const POPULAR_SYMBOLS = [
  'AAPL', 'MSFT', 'GOOGL', 'AMZN', 'NVDA', 'TSLA', 'META', 'BRK.B', 'V', 'JNJ', 'WMT', 'JPM', // Tech/Blue Chip
  'VOO', 'VTI', 'QQQ', 'IVV', 'SCHD', 'JEPI', 'VUG', 'VTV', // ETFs
  'BTC', 'ETH', 'SOL', 'USDT', 'BNB', 'XRP', 'ADA' // Crypto
];

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState('dashboard');
  const [isAddModalOpen, setIsAddModalOpen] = useState(false);
  const [editingTransaction, setEditingTransaction] = useState<Transaction | null>(null);

  // Persistence for better UX
  const [lastTxDate, setLastTxDate] = useState<string>(() => localStorage.getItem('lastTxDate') || new Date().toISOString().split('T')[0]);

  // Goal Modal State
  const [isGoalModalOpen, setIsGoalModalOpen] = useState(false);

  // --- CONFIRMATION MODAL STATE ---
  const [confirmConfig, setConfirmConfig] = useState<{
    isOpen: boolean;
    title: string;
    message: string;
    onConfirm: () => void;
  }>({
    isOpen: false,
    title: '',
    message: '',
    onConfirm: () => {},
  });

  // --- PORTFOLIO MANAGEMENT STATE ---
  const [portfolios, setPortfolios] = useState<Portfolio[]>(() => {
    const saved = localStorage.getItem('portfolios');
    if (saved) return JSON.parse(saved);
    const legacyTx = localStorage.getItem('transactions');
    if (legacyTx) return [{ id: 'default', name: 'Main Portfolio' }];
    return [{ id: generateId(), name: 'My First Portfolio' }];
  });

  const [activePortfolioId, setActivePortfolioId] = useState<string>(() => {
    const saved = localStorage.getItem('activePortfolioId');
    const portfolios = JSON.parse(localStorage.getItem('portfolios') || '[]');
    if (saved && portfolios.some((p: Portfolio) => p.id === saved)) return saved;
    return portfolios.length > 0 ? portfolios[0].id : 'default';
  });

  // --- DATA STATE (Per Portfolio) - Synchronous Initialization ---
  const [transactions, setTransactions] = useState<Transaction[]>(() => {
    const key = `transactions_${activePortfolioId}`;
    const saved = localStorage.getItem(key);
    if (saved) return JSON.parse(saved);
    if (activePortfolioId === 'default') {
      const legacy = localStorage.getItem('transactions');
      if (legacy) return JSON.parse(legacy);
    }
    return [];
  });

  const [prices, setPrices] = useState<Record<string, number>>(() => {
    const key = `prices_${activePortfolioId}`;
    const saved = localStorage.getItem(key);
    if (saved) return JSON.parse(saved);
    if (activePortfolioId === 'default') {
      const legacy = localStorage.getItem('prices');
      if (legacy) return JSON.parse(legacy);
    }
    return {};
  });

  const [goals, setGoals] = useState<FinancialGoal[]>(() => {
    const key = `goals_${activePortfolioId}`;
    const saved = localStorage.getItem(key);
    if (saved) return JSON.parse(saved);

    let legacyGoal = 100000;
    const legacyKey = `financialGoal_${activePortfolioId}`;
    const savedLegacy = localStorage.getItem(legacyKey);
    if (savedLegacy) legacyGoal = parseFloat(savedLegacy);
    else if (activePortfolioId === 'default' && localStorage.getItem('financialGoal')) legacyGoal = parseFloat(localStorage.getItem('financialGoal')!);

    return [{ id: generateId(), targetAmount: legacyGoal, startDate: new Date().toISOString(), isAchieved: false, notes: 'Initial Goal' }];
  });

  const [isDataLoaded, setIsDataLoaded] = useState(true);
  const [isLoading, setIsLoading] = useState(false);
  const isFirstMount = useRef(true);

  // --- PERSISTENCE ---
  useEffect(() => { localStorage.setItem('portfolios', JSON.stringify(portfolios)); }, [portfolios]);
  useEffect(() => { localStorage.setItem('activePortfolioId', activePortfolioId); }, [activePortfolioId]);

  useEffect(() => {
    if (isFirstMount.current) { isFirstMount.current = false; return; }
    setIsLoading(true);
    setIsDataLoaded(false);
    const loadData = () => {
        const txKey = `transactions_${activePortfolioId}`;
        const pricesKey = `prices_${activePortfolioId}`;
        const goalsKey = `goals_${activePortfolioId}`;

        const savedTx = localStorage.getItem(txKey);
        setTransactions(savedTx ? JSON.parse(savedTx) : []);

        const savedPrices = localStorage.getItem(pricesKey);
        setPrices(savedPrices ? JSON.parse(savedPrices) : {});

        const savedGoals = localStorage.getItem(goalsKey);
        setGoals(savedGoals ? JSON.parse(savedGoals) : []); 

        setIsDataLoaded(true);
        setTimeout(() => setIsLoading(false), 500);
    };
    requestAnimationFrame(loadData);
  }, [activePortfolioId]);

  useEffect(() => { if (isDataLoaded) localStorage.setItem(`transactions_${activePortfolioId}`, JSON.stringify(transactions)); }, [transactions, activePortfolioId, isDataLoaded]);
  useEffect(() => { if (isDataLoaded) localStorage.setItem(`prices_${activePortfolioId}`, JSON.stringify(prices)); }, [prices, activePortfolioId, isDataLoaded]);
  useEffect(() => { if (isDataLoaded) localStorage.setItem(`goals_${activePortfolioId}`, JSON.stringify(goals)); }, [goals, activePortfolioId, isDataLoaded]);

  // --- CALCULATIONS ---
  const holdings = useMemo(() => calculateHoldings(transactions, prices), [transactions, prices]);
  const chartData = useMemo(() => calculatePortfolioHistory(transactions, prices), [transactions, prices]);
  const investedAmount = transactions.reduce((sum, t) => {
    if (t.type === TransactionType.DEPOSIT) return sum + (t.price || 0);
    if (t.type === TransactionType.WITHDRAW) return sum - (t.price || 0);
    return sum;
  }, 0);
  const cashBalance = useMemo(() => {
    let balance = 0;
    transactions.forEach(t => {
      if (t.type === TransactionType.DEPOSIT) balance += (t.price || 0);
      if (t.type === TransactionType.WITHDRAW) balance -= (t.price || 0);
      if (t.type === TransactionType.BUY) balance -= (t.price! * t.shares!) + (t.fee || 0);
      if (t.type === TransactionType.SELL) balance += (t.price! * t.shares!) - (t.fee || 0);
      if (t.type === TransactionType.DIVIDEND) balance += (t.price || 0);
    });
    return balance;
  }, [transactions]);
  const portfolioValue = holdings.reduce((sum, h) => sum + h.marketValue, 0);
  const totalNetWorth = portfolioValue + cashBalance;
  const activeGoal = useMemo(() => goals.find(g => !g.endDate) || { targetAmount: 100000 } as FinancialGoal, [goals]);

  // --- HANDLERS ---
  const handleOpenAddModal = () => { setEditingTransaction(null); setIsAddModalOpen(true); };
  const handleOpenEditModal = (tx: Transaction) => { setEditingTransaction(tx); setIsAddModalOpen(true); };

  const handleSaveTransaction = (tx: Transaction) => {
    return new Promise<void>((resolve) => {
      if (editingTransaction) setTransactions(prev => prev.map(t => t.id === tx.id ? tx : t));
      else setTransactions(prev => [...prev, tx]);

      // Update price reference
      if ((tx.type === TransactionType.BUY || tx.type === TransactionType.SELL) && tx.symbol && tx.price) {
        setPrices(prev => ({...prev, [tx.symbol!]: tx.price!}));
      }

      // Update Last Used Date Persistence
      setLastTxDate(tx.date);
      localStorage.setItem('lastTxDate', tx.date);

      setIsAddModalOpen(false); 
      setEditingTransaction(null); 
      resolve();
    });
  };

  const handleUpdatePrice = (symbol: string, newPrice: number) => setPrices(prev => ({ ...prev, [symbol]: newPrice }));
  const handleDeleteTransaction = (id: string) => {
    setTransactions(prev => prev.filter(t => t.id !== id));
    if (editingTransaction && editingTransaction.id === id) { setIsAddModalOpen(false); setEditingTransaction(null); }
  };
  const handleRequestDelete = (id: string) => {
      setConfirmConfig({ isOpen: true, title: 'Delete Transaction', message: 'Permanently remove this record?', onConfirm: () => { handleDeleteTransaction(id); setConfirmConfig(prev => ({ ...prev, isOpen: false })); } });
  };
  const handleImportTransactions = (importedTxs: Transaction[]) => {
      setTransactions(prev => {
          const currentMap = new Map(prev.map(t => [t.id, t]));
          importedTxs.forEach(t => { currentMap.set(t.id, t); });
          return Array.from(currentMap.values());
      });
  };

  // Portfolios
  const handleCreatePortfolio = (name: string) => { const newId = generateId(); setPortfolios([...portfolios, { id: newId, name }]); setActivePortfolioId(newId); };
  const handleRenamePortfolio = (id: string, newName: string) => { setPortfolios(prev => prev.map(p => p.id === id ? { ...p, name: newName } : p)); };
  const handleDeletePortfolio = (id: string) => {
    if (portfolios.length <= 1) { alert("Cannot delete last portfolio"); return; }
    setConfirmConfig({
        isOpen: true, title: 'Delete Portfolio', message: 'Delete entire portfolio and all data?', 
        onConfirm: () => {
             localStorage.removeItem(`transactions_${id}`); localStorage.removeItem(`prices_${id}`); localStorage.removeItem(`goals_${id}`);
             const newPortfolios = portfolios.filter(p => p.id !== id); setPortfolios(newPortfolios);
             if (activePortfolioId === id) setActivePortfolioId(newPortfolios[0].id);
             setConfirmConfig(prev => ({ ...prev, isOpen: false }));
        }
    });
  };

  // Goals
  const handleSetNewGoal = (targetAmount: number, notes: string) => {
    const now = new Date().toISOString();
    setGoals(prev => [...prev.map(g => !g.endDate ? { ...g, endDate: now, isAchieved: totalNetWorth >= g.targetAmount } : g), { id: generateId(), targetAmount, startDate: now, isAchieved: false, notes }]);
  };
  const handleEditGoal = (updatedGoal: FinancialGoal) => setGoals(prev => prev.map(g => g.id === updatedGoal.id ? updatedGoal : g));
  const handleDeleteGoal = (id: string) => setGoals(prev => prev.filter(g => g.id !== id));

  return (
    <Layout 
      activeTab={activeTab} setActiveTab={setActiveTab} onOpenAddModal={handleOpenAddModal}
      portfolios={portfolios} activePortfolioId={activePortfolioId} onSwitchPortfolio={setActivePortfolioId}
      onCreatePortfolio={handleCreatePortfolio} onRenamePortfolio={handleRenamePortfolio} onDeletePortfolio={handleDeletePortfolio}
    >
      <div key={activePortfolioId} className="h-full">
        {activeTab === 'dashboard' && <Dashboard isLoading={isLoading} holdings={holdings} transactions={transactions} financialGoal={activeGoal.targetAmount} onOpenGoalModal={() => setIsGoalModalOpen(true)} investedAmount={investedAmount} cashBalance={cashBalance} portfolioValue={portfolioValue} chartData={chartData} />}
        {activeTab === 'holdings' && <Holdings isLoading={isLoading} holdings={holdings} transactions={transactions} onUpdatePrice={handleUpdatePrice} />}
        {activeTab === 'history' && <History isLoading={isLoading} transactions={transactions} onDelete={handleRequestDelete} onEdit={handleOpenEditModal} onAdd={handleOpenAddModal} onImport={handleImportTransactions} />}
        {activeTab === 'reports' && <Reports isLoading={isLoading} transactions={transactions} currentPortfolioValue={portfolioValue + cashBalance} chartData={chartData} />}
      </div>

      {isAddModalOpen && (
        <div className="fixed inset-0 z-50 flex items-end sm:items-center justify-center sm:p-4">
          <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-sm animate-fade-in" onClick={() => setIsAddModalOpen(false)}></div>
          <div className="relative bg-white dark:bg-slate-900 w-full max-w-2xl rounded-t-3xl sm:rounded-3xl shadow-2xl overflow-hidden animate-slide-up flex flex-col max-h-[90dvh]">
            <AddTransactionForm 
              onClose={() => setIsAddModalOpen(false)} 
              onSave={handleSaveTransaction} 
              onDelete={handleRequestDelete} 
              cashBalance={cashBalance} 
              holdings={holdings} 
              prices={prices} 
              transactions={transactions} 
              initialData={editingTransaction}
              defaultDate={lastTxDate}
            />
          </div>
        </div>
      )}

      <GoalModal isOpen={isGoalModalOpen} onClose={() => setIsGoalModalOpen(false)} goals={goals} currentNetWorth={totalNetWorth} onSetGoal={handleSetNewGoal} onEditGoal={handleEditGoal} onDeleteGoal={handleDeleteGoal} />

      {confirmConfig.isOpen && (
        <div className="fixed inset-0 z-[70] flex items-center justify-center p-4 animate-fade-in">
          <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-sm" onClick={() => setConfirmConfig(prev => ({ ...prev, isOpen: false }))}></div>
          <div className="relative bg-white dark:bg-slate-900 rounded-2xl shadow-2xl w-full max-w-sm overflow-hidden animate-zoom-in p-6 text-center">
              <Trash2 size={40} className="mx-auto text-rose-500 mb-4" />
              <h3 className="text-lg font-bold text-slate-900 dark:text-white mb-2">{confirmConfig.title}</h3>
              <p className="text-sm text-slate-500 dark:text-slate-400 mb-6">{confirmConfig.message}</p>
              <div className="flex space-x-3">
                <button onClick={() => setConfirmConfig(prev => ({ ...prev, isOpen: false }))} className="flex-1 py-3 rounded-xl font-bold bg-slate-100 dark:bg-slate-800 text-slate-600 dark:text-slate-400">Cancel</button>
                <button onClick={confirmConfig.onConfirm} className="flex-1 py-3 rounded-xl font-bold bg-rose-600 text-white shadow-lg shadow-rose-600/20">Delete</button>
              </div>
          </div>
        </div>
      )}
    </Layout>
  );
};

interface AddTransactionFormProps {
  onClose: () => void;
  onSave: (t: Transaction) => Promise<void>;
  onDelete?: (id: string) => void;
  cashBalance: number;
  holdings: Holding[];
  prices: Record<string, number>;
  transactions: Transaction[];
  initialData: Transaction | null;
  defaultDate: string;
}

const AddTransactionForm: React.FC<AddTransactionFormProps> = ({ onClose, onSave, onDelete, cashBalance, holdings, prices, transactions, initialData, defaultDate }) => {
  const [step, setStep] = useState<'input' | 'review'>('input');

  const [type, setType] = useState<TransactionType>(TransactionType.BUY);
  const [date, setDate] = useState(defaultDate);
  const [symbol, setSymbol] = useState('');
  const [shares, setShares] = useState('');
  const [price, setPrice] = useState(''); // Price per share
  const [totalAmount, setTotalAmount] = useState(''); // Total transaction value
  const [fee, setFee] = useState('');
  const [assetClass, setAssetClass] = useState<AssetClass>(AssetClass.STOCK);
  const [exchangeRate, setExchangeRate] = useState(''); 
  const [notes, setNotes] = useState('');
  const [error, setError] = useState<string | null>(null);
  const [isSaving, setIsSaving] = useState(false);

  // Track which input is driving the calculation
  const [activeInput, setActiveInput] = useState<'shares' | 'price' | 'total' | null>(null);
  const [showSuggestions, setShowSuggestions] = useState(false);
  const wrapperRef = useRef<HTMLDivElement>(null);

  // Validation logic helpers
  const needsSymbol = [TransactionType.BUY, TransactionType.SELL, TransactionType.DIVIDEND, TransactionType.SPLIT].includes(type);
  const needsShares = [TransactionType.BUY, TransactionType.SELL, TransactionType.SPLIT].includes(type);
  const needsPrice = type !== TransactionType.SPLIT;

  // FX Rate is relevant for: Deposits, Withdrawals, and Dividends (Foreign income)
  const hasExchangeRate = type === TransactionType.DEPOSIT || type === TransactionType.WITHDRAW || type === TransactionType.DIVIDEND;
  const isFunding = type === TransactionType.DEPOSIT || type === TransactionType.WITHDRAW;

  // Effects (Initialization, Auto-fill, Calculation)
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => { if (wrapperRef.current && !wrapperRef.current.contains(event.target as Node)) setShowSuggestions(false); };
    document.addEventListener("mousedown", handleClickOutside); return () => document.removeEventListener("mousedown", handleClickOutside);
  }, []);

  useEffect(() => {
    if (initialData) {
      setType(initialData.type); setDate(initialData.date); setSymbol(initialData.symbol || '');
      setShares(initialData.shares?.toString() || ''); setPrice(initialData.price?.toString() || '');
      setFee(initialData.fee?.toString() || ''); setAssetClass(initialData.assetClass || AssetClass.STOCK);
      setExchangeRate(initialData.exchangeRate?.toString() || ''); setNotes(initialData.notes || '');
      if (initialData.shares && initialData.price && (initialData.type === TransactionType.BUY || initialData.type === TransactionType.SELL)) {
         setTotalAmount((initialData.shares * initialData.price).toFixed(2));
      } else if (initialData.price) setTotalAmount(initialData.price.toString());
    }
  }, [initialData]);

  // Auto-fill price from holdings or market data
  useEffect(() => {
    if (!initialData && symbol && !price && !activeInput) {
       const h = holdings.find(h => h.symbol === symbol.toUpperCase());
       if (h) { setAssetClass(h.assetClass); if (h.currentPrice > 0) setPrice(h.currentPrice.toString()); }
       else { const kp = prices[symbol.toUpperCase()]; if (kp) setPrice(kp.toString()); }
    }
  }, [symbol]);

  // Bi-directional Calculation
  useEffect(() => {
    const s = parseFloat(shares) || 0; 
    const p = parseFloat(price) || 0; 
    const t = parseFloat(totalAmount) || 0;

    // Only auto-calc if user is actively typing in one field to update the other
    if ((activeInput === 'shares' || activeInput === 'price') && s > 0 && p > 0) {
        setTotalAmount((s * p).toFixed(2));
    }
    if (activeInput === 'total' && t > 0 && p > 0) {
        setShares((t / p).toFixed(4));
    }
  }, [shares, price, totalAmount, activeInput]);

  // Max Button Handlers
  const handleMax = () => {
    const p = parseFloat(price);

    if (type === TransactionType.BUY) {
        if (p > 0) {
            // Max buyable with current cash (minus fee estimation if we wanted to be complex, but simple is better)
            const maxAmt = Math.max(0, cashBalance);
            setTotalAmount(maxAmt.toFixed(2));
            setShares((maxAmt / p).toFixed(4));
            setActiveInput('total');
        } else {
            setTotalAmount(cashBalance.toFixed(2));
            setActiveInput('total');
        }
    } else if (type === TransactionType.SELL) {
        const holding = holdings.find(h => h.symbol === symbol.toUpperCase());
        if (holding) {
            setShares(holding.shares.toString());
            if (p > 0) setTotalAmount((holding.shares * p).toFixed(2));
            setActiveInput('shares');
        }
    }
  };

  // IMPACT CALCULATIONS FOR SUMMARY
  const currentCashImpact = useMemo(() => {
     const qty = parseFloat(shares) || 0;
     const unitPrice = parseFloat(price) || 0;
     const feeVal = parseFloat(fee) || 0;
     const amt = parseFloat(totalAmount) || 0;

     if (type === TransactionType.BUY) return -((qty * unitPrice) + feeVal);
     if (type === TransactionType.SELL) return ((qty * unitPrice) - feeVal);
     if (type === TransactionType.DEPOSIT) return amt;
     if (type === TransactionType.WITHDRAW) return -amt;
     if (type === TransactionType.DIVIDEND) return amt;
     return 0;
  }, [type, shares, price, fee, totalAmount]);

  const originalCashImpact = useMemo(() => {
    if (!initialData) return 0;
    const qty = initialData.shares || 0;
    const unitPrice = initialData.price || 0;
    const feeVal = initialData.fee || 0;

    if (initialData.type === TransactionType.BUY) return -((qty * unitPrice) + feeVal);
    if (initialData.type === TransactionType.SELL) return ((qty * unitPrice) - feeVal);
    if (initialData.type === TransactionType.DEPOSIT) return unitPrice; 
    if (initialData.type === TransactionType.WITHDRAW) return -unitPrice;
    if (initialData.type === TransactionType.DIVIDEND) return unitPrice;
    return 0;
  }, [initialData]);

  const projectedCashBalance = cashBalance - originalCashImpact + currentCashImpact;

  // Calculate totalNetWorth for summary
  const totalNetWorth = useMemo(() => {
     const invested = holdings.reduce((sum, h) => sum + h.marketValue, 0);
     return invested + cashBalance;
  }, [holdings, cashBalance]);

  // Validation
  const validate = () => {
    if (needsSymbol && !symbol) return "Asset Symbol is required.";
    if (!needsSymbol && !totalAmount) return "Amount is required.";

    // Sell Check
    if (type === TransactionType.SELL) {
        const holding = holdings.find(h => h.symbol === symbol.toUpperCase());
        const currentShares = holding ? holding.shares : 0;
        const originalShares = (initialData && initialData.type === TransactionType.SELL && initialData.symbol === symbol) ? (initialData.shares || 0) : 0;
        const available = currentShares + originalShares;

        if ((parseFloat(shares) || 0) > available) {
            return `Insufficient shares. Owned: ${formatNumber(available)}. Selling: ${shares}.`;
        }
    }

    // Strict Negative Cash Warning 
    if ((type === TransactionType.WITHDRAW || type === TransactionType.BUY) && projectedCashBalance < 0) {
        return "Insufficient funds. Transaction exceeds cash balance.";
    }

    return null;
  };

  const handleReview = (e: React.FormEvent) => {
      e.preventDefault();
      const errMsg = validate();
      if (errMsg) return setError(errMsg);
      setError(null);
      setStep('review');
  };

  const handleFinalSubmit = async () => {
    setIsSaving(true);
    await onSave({
      id: initialData ? initialData.id : generateId(),
      date, type, symbol: needsSymbol ? symbol.toUpperCase() : undefined,
      shares: needsShares ? parseFloat(shares) : undefined,
      // For types that don't need shares (Deposit, Withdraw, Dividend), use the total amount as price
      price: type === TransactionType.SPLIT ? 0 : (needsShares ? parseFloat(price) : parseFloat(totalAmount)),
      fee: (fee && (type === TransactionType.BUY || type === TransactionType.SELL)) ? parseFloat(fee) : undefined,
      assetClass: !needsSymbol ? AssetClass.CASH : assetClass,
      exchangeRate: exchangeRate ? parseFloat(exchangeRate) : 1, notes: notes || undefined
    });
    setIsSaving(false);
  };

  const suggestions = useMemo(() => {
    if (!symbol) return [];
    const inputUpper = symbol.toUpperCase();
    return Array.from(new Set([...holdings.map(h => h.symbol), ...POPULAR_SYMBOLS])).filter(s => s.includes(inputUpper)).slice(0, 5);
  }, [symbol, holdings]);

  // Icons and Colors
  const getTypeConfig = (t: TransactionType) => {
    switch (t) {
        case TransactionType.BUY: return { color: 'blue', icon: <TrendingUp size={16} /> };
        case TransactionType.DEPOSIT: return { color: 'emerald', icon: <Wallet size={16} /> };
        case TransactionType.SELL: return { color: 'rose', icon: <TrendingDown size={16} /> };
        case TransactionType.WITHDRAW: return { color: 'orange', icon: <Banknote size={16} /> };
        case TransactionType.DIVIDEND: return { color: 'emerald', icon: <DollarSign size={16} /> };
        case TransactionType.SPLIT: return { color: 'purple', icon: <Split size={16} /> };
        default: return { color: 'slate', icon: <CheckCircle2 size={16} /> };
    }
  }
  const theme = getTypeConfig(type);

  // SUMMARY BAR
  const summaryBox = useMemo(() => {
     const absImpact = Math.abs(currentCashImpact);
     const isPositive = currentCashImpact >= 0;
     const portfolioPercent = (totalNetWorth > 0) ? (absImpact / totalNetWorth) * 100 : 0;

     return (
         <div className="bg-slate-100 dark:bg-slate-800/80 rounded-2xl p-5 border border-slate-200 dark:border-slate-700 mt-4">
             <div className="flex justify-between items-start mb-4">
                 <div>
                    <p className="text-xs font-bold text-slate-500 uppercase tracking-wider">Net Cash Impact</p>
                    <h3 className={`text-2xl font-bold font-display ${isPositive ? 'text-emerald-600' : 'text-rose-600'}`}>
                        {isPositive ? '+' : '-'}{formatCurrency(absImpact)}
                    </h3>
                    <p className="text-[10px] text-slate-400 mt-1 font-medium flex items-center">
                        <Percent size={10} className="mr-1"/>
                        ≈ {portfolioPercent.toFixed(1)}% of Total Portfolio
                    </p>
                 </div>
                 <div className="text-right">
                    <p className="text-xs font-bold text-slate-500 uppercase tracking-wider">Projected Cash</p>
                    <p className="text-xl font-bold font-mono text-slate-800 dark:text-slate-200">{formatCurrency(projectedCashBalance)}</p>
                 </div>
             </div>

             {/* Progress Bar */}
             <div className="relative h-2.5 bg-slate-200 dark:bg-slate-700 rounded-full overflow-hidden">
                 {/* Background: Current Balance */}
                 <div 
                    className="absolute top-0 left-0 h-full bg-slate-400 dark:bg-slate-500 transition-all" 
                    style={{ width: '100%' }} // Simplified visualization, always show full width as base
                 ></div>

                 {/* Overlay: New Balance (if shrinking) */}
                 {projectedCashBalance < cashBalance && (
                    <div 
                        className="absolute top-0 right-0 h-full bg-rose-500 transition-all animate-pulse" 
                        style={{ width: `${((cashBalance - projectedCashBalance)/cashBalance)*100}%` }}
                    ></div>
                 )}
                 {/* Overlay: New Balance (if growing) */}
                 {projectedCashBalance > cashBalance && (
                     <div 
                        className="absolute top-0 left-0 h-full bg-emerald-500 transition-all" 
                         style={{ width: '100%' }} // If growing, it fills and overflows conceptually
                     ></div>
                 )}
             </div>
             <div className="flex justify-between text-[10px] text-slate-400 mt-1.5 font-bold uppercase">
                 <span>Before: {formatCurrency(cashBalance)}</span>
                 <span>After: {formatCurrency(projectedCashBalance)}</span>
             </div>
         </div>
     )
  }, [currentCashImpact, projectedCashBalance, cashBalance, totalNetWorth]);

  // RENDER: REVIEW STEP
  if (step === 'review') {
      return (
          <div className="flex flex-col h-full bg-white dark:bg-slate-900">
             <div className="p-6 text-center border-b border-slate-100 dark:border-slate-800">
                <div className={`w-16 h-16 mx-auto rounded-full bg-${theme.color}-100 dark:bg-${theme.color}-900/30 text-${theme.color}-600 dark:text-${theme.color}-400 flex items-center justify-center mb-4 shadow-lg shadow-${theme.color}-500/20`}>
                   {theme.icon}
                </div>
                <h3 className="text-xl font-display font-bold text-slate-900 dark:text-white">Review Transaction</h3>
                <p className="text-sm text-slate-500">Please confirm details before saving.</p>
             </div>

             <div className="flex-1 overflow-y-auto p-6 space-y-6">
                 {/* Details Card */}
                 <div className="bg-slate-50 dark:bg-slate-800/50 rounded-2xl p-5 border border-slate-200 dark:border-slate-700 space-y-4">
                     <div className="flex justify-between border-b border-slate-200 dark:border-slate-700 pb-2">
                        <span className="text-sm text-slate-500">Date</span>
                        <span className="text-sm font-bold text-slate-900 dark:text-white">{date}</span>
                     </div>
                     <div className="flex justify-between border-b border-slate-200 dark:border-slate-700 pb-2">
                        <span className="text-sm text-slate-500">Type</span>
                        <span className={`text-sm font-bold uppercase text-${theme.color}-600`}>{type}</span>
                     </div>
                     {needsSymbol && (
                         <div className="flex justify-between border-b border-slate-200 dark:border-slate-700 pb-2">
                            <span className="text-sm text-slate-500">Asset</span>
                            <span className="text-sm font-bold text-slate-900 dark:text-white">{symbol} <span className="text-xs text-slate-400 font-normal">({assetClass})</span></span>
                         </div>
                     )}
                     <div className="flex justify-between border-b border-slate-200 dark:border-slate-700 pb-2">
                        <span className="text-sm text-slate-500">Total Amount</span>
                        <span className="text-lg font-bold text-slate-900 dark:text-white">{formatCurrency(parseFloat(totalAmount))}</span>
                     </div>
                     {needsShares && (
                        <div className="flex justify-between pt-1">
                            <span className="text-xs text-slate-400">Details</span>
                            <span className="text-xs text-slate-500">{shares} units @ {formatCurrency(parseFloat(price))}</span>
                        </div>
                     )}
                 </div>

                 {projectedCashBalance < 0 && (
                     <div className="bg-rose-50 text-rose-600 p-4 rounded-xl text-sm font-bold flex items-center">
                         <AlertCircle size={20} className="mr-3 shrink-0" />
                         WARNING: This transaction will result in a negative cash balance.
                     </div>
                 )}
             </div>

             <div className="p-6 border-t border-slate-100 dark:border-slate-800 flex gap-4">
                 <button onClick={() => setStep('input')} className="flex-1 py-3 rounded-xl font-bold bg-slate-100 dark:bg-slate-800 text-slate-600 dark:text-slate-300 hover:bg-slate-200 dark:hover:bg-slate-700 transition-colors">
                    Back to Edit
                 </button>
                 <button onClick={handleFinalSubmit} disabled={isSaving} className={`flex-1 py-3 rounded-xl font-bold text-white shadow-xl flex items-center justify-center space-x-2 bg-${theme.color}-600 hover:bg-${theme.color}-700 transition-all`}>
                    {isSaving ? <Spinner className="text-white" /> : (
                        <>
                            <CheckCircle2 size={18} />
                            <span>Confirm & Save</span>
                        </>
                    )}
                 </button>
             </div>
          </div>
      )
  }

  // RENDER: INPUT STEP
  return (
    <>
      <div className="shrink-0 px-6 py-4 border-b border-slate-100 dark:border-slate-800 flex justify-between items-center bg-white dark:bg-slate-900">
          <h3 className="text-lg font-display font-bold text-slate-900 dark:text-white">{initialData ? 'Edit Transaction' : 'New Transaction'}</h3>
          <button onClick={onClose} className="bg-slate-100 dark:bg-slate-800 p-2 rounded-full text-slate-500 hover:text-slate-800 dark:hover:text-white transition-colors"><X size={20} /></button>
      </div>

      <form onSubmit={handleReview} className="flex-1 overflow-y-auto min-h-0 p-6 custom-scrollbar bg-white dark:bg-slate-900">

        {/* 1. Transaction Type Selector with Icons */}
        <div className="mb-6">
           <label className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-3 block">Transaction Type</label>
           <div className="grid grid-cols-3 sm:grid-cols-6 gap-2">
              {[TransactionType.BUY, TransactionType.SELL, TransactionType.DEPOSIT, TransactionType.WITHDRAW, TransactionType.DIVIDEND, TransactionType.SPLIT].map(t => {
                 const isActive = type === t;
                 const config = getTypeConfig(t);

                 return (
                   <button
                      key={t} type="button" onClick={() => setType(t)}
