  const totalPLPercent = investedAmount > 0 ? (totalUnrealizedPL / investedAmount) * 100 : 0;

  // 1. Prepare Main Allocation Data (By Category)
  const categoryData = useMemo(() => {
    // Aggregate holdings by Asset Class
    const data = holdings
      .filter(h => h.marketValue > 0)
      .map(h => ({ name: h.assetClass, value: h.marketValue }))
      .reduce((acc: any[], curr) => {
        const existing = acc.find(item => item.name === curr.name);
        if (existing) {
          existing.value += curr.value;
        } else {
          acc.push({ ...curr });
        }
        return acc;
      }, []);

    // Add Cash Balance if positive
    if (cashBalance > 0) {
       const cashCategory = data.find(item => item.name === 'Cash');
       if (cashCategory) {
          cashCategory.value += cashBalance;
       } else {
          data.push({ name: 'Cash', value: cashBalance });
       }
