export default Dashboard;

import React, { useState, useMemo, useRef } from 'react';
import { Transaction, TransactionType, AssetClass } from '../types';
import { Search, Filter, Trash2, XCircle, Edit2, Plus, Download, Upload, TrendingUp, TrendingDown, RefreshCcw, DollarSign, Wallet, Split, FileDown, FileUp } from 'lucide-react';
import { formatCurrency, formatNumber, transactionsToCSV, csvToTransactions } from '../utils';
import { HistorySkeleton } from './LoadingSkeletons';

interface HistoryProps {
  transactions: Transaction[];
  onDelete: (id: string) => void;
  onEdit: (tx: Transaction) => void;
  onAdd: () => void;
  onImport: (txs: Transaction[]) => void;
  isLoading?: boolean;
}

const History: React.FC<HistoryProps> = ({ transactions, onDelete, onEdit, onAdd, onImport, isLoading }) => {
  // Filters State
  const [searchTerm, setSearchTerm] = useState('');
  const [typeFilter, setTypeFilter] = useState<TransactionType | 'ALL'>('ALL');
  const [assetClassFilter, setAssetClassFilter] = useState<AssetClass | 'ALL'>('ALL');
  const [startDate, setStartDate] = useState('');
  const [endDate, setEndDate] = useState('');
  const [sortOrder, setSortOrder] = useState<'desc' | 'asc'>('desc');
  const [showFilters, setShowFilters] = useState(false);

  const fileInputRef = useRef<HTMLInputElement>(null);

  // --- LOGIC ---

  const filteredTransactions = useMemo(() => {
    return transactions.filter(tx => {
      // 1. Search (Symbol, Notes)
      const searchLower = searchTerm.toLowerCase();
      const matchesSearch = 
        (tx.symbol?.toLowerCase().includes(searchLower) ?? false) ||
        (tx.notes?.toLowerCase().includes(searchLower) ?? false) ||
        (tx.type.toLowerCase().includes(searchLower));

      // 2. Type Filter
      const matchesType = typeFilter === 'ALL' || tx.type === typeFilter;

      // 3. Asset Class Filter
      const matchesAsset = assetClassFilter === 'ALL' || tx.assetClass === assetClassFilter;

      // 4. Date Range
      const txDate = new Date(tx.date).getTime();
      const start = startDate ? new Date(startDate).getTime() : -Infinity;
      const end = endDate ? new Date(endDate).getTime() : Infinity;
      const matchesDate = txDate >= start && txDate <= end;

      return matchesSearch && matchesType && matchesAsset && matchesDate;
    }).sort((a, b) => {
      const dateA = new Date(a.date).getTime();
      const dateB = new Date(b.date).getTime();
      return sortOrder === 'desc' ? dateB - dateA : dateA - dateB;
    });
  }, [transactions, searchTerm, typeFilter, assetClassFilter, startDate, endDate, sortOrder]);

  // Group transactions by date for display
  const groupedTransactions = useMemo(() => {
    const groups: { title: string, txs: Transaction[] }[] = [];
    let currentKey = "";

    filteredTransactions.forEach(tx => {
       const dateObj = new Date(tx.date);
       const today = new Date();
       const yesterday = new Date();
       yesterday.setDate(yesterday.getDate() - 1);

       let key = dateObj.toLocaleDateString('en-US', { weekday: 'short', month: 'short', day: 'numeric', year: 'numeric' });

       if (dateObj.toDateString() === today.toDateString()) key = "Today";
       else if (dateObj.toDateString() === yesterday.toDateString()) key = "Yesterday";

       if (key !== currentKey) {
           groups.push({ title: key, txs: [] });
           currentKey = key;
       }
       groups[groups.length - 1].txs.push(tx);
    });

    return groups;
  }, [filteredTransactions]);

  // Calculate Summary Stats based on filtered view
  const stats = useMemo(() => {
      let inflow = 0;
      let outflow = 0;

      filteredTransactions.forEach(t => {
          const val = (t.shares && (t.type === 'BUY' || t.type === 'SELL')) ? (t.price || 0) * t.shares : (t.price || 0);

          // Cash Flow perspective
          if (t.type === 'DEPOSIT' || t.type === 'DIVIDEND' || t.type === 'SELL') {
              inflow += val;
          } else if (t.type === 'WITHDRAW' || t.type === 'BUY') {
              outflow += val;
          }
      });

      return { inflow, outflow, net: inflow - outflow, count: filteredTransactions.length };
  }, [filteredTransactions]);

  const resetFilters = () => {
    setSearchTerm('');
    setTypeFilter('ALL');
    setAssetClassFilter('ALL');
    setStartDate('');
    setEndDate('');
  };

  const handleImportClick = () => fileInputRef.current?.click();

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (evt) => {
      const content = evt.target?.result as string;
      if (content) {
        const imported = csvToTransactions(content);
        if (imported.length > 0) onImport(imported);
        else alert("No valid transactions found.");
      }
    };
    reader.readAsText(file);
    e.target.value = '';
  };

  const handleExport = () => {
    const csv = transactionsToCSV(transactions);
    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.setAttribute('download', `portfolio_backup_${new Date().toISOString().split('T')[0]}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  if (isLoading) return <HistorySkeleton />;

  const hasActiveFilters = searchTerm || typeFilter !== 'ALL' || assetClassFilter !== 'ALL' || startDate || endDate;

  // Helper for Icons & Styles
  const getIconForType = (type: TransactionType) => {
      switch(type) {
          case TransactionType.BUY: return <TrendingUp size={16} />;
          case TransactionType.SELL: return <TrendingDown size={16} />;
          case TransactionType.DEPOSIT: return <Wallet size={16} />;
          case TransactionType.WITHDRAW: return <Wallet size={16} />;
          case TransactionType.DIVIDEND: return <DollarSign size={16} />;
          case TransactionType.SPLIT: return <Split size={16} />;
          default: return <RefreshCcw size={16} />;
      }
  };

  const getColorForType = (type: TransactionType) => {
      switch(type) {
          case TransactionType.BUY: return 'bg-emerald-100 text-emerald-600 dark:bg-emerald-900/30 dark:text-emerald-400';
          case TransactionType.SELL: return 'bg-rose-100 text-rose-600 dark:bg-rose-900/30 dark:text-rose-400';
          case TransactionType.DEPOSIT: return 'bg-blue-100 text-blue-600 dark:bg-blue-900/30 dark:text-blue-400';
          case TransactionType.WITHDRAW: return 'bg-orange-100 text-orange-600 dark:bg-orange-900/30 dark:text-orange-400';
          case TransactionType.DIVIDEND: return 'bg-teal-100 text-teal-600 dark:bg-teal-900/30 dark:text-teal-400';
          case TransactionType.SPLIT: return 'bg-purple-100 text-purple-600 dark:bg-purple-900/30 dark:text-purple-400';
          default: return 'bg-slate-100 text-slate-600 dark:bg-slate-800 dark:text-slate-400';
      }
  }

  return (
    <div className="space-y-6 animate-fade-in pb-20">
      <input type="file" accept=".csv" ref={fileInputRef} onChange={handleFileChange} className="hidden" />

      {/* 1. TOP HEADER & SUMMARY */}
      <div className="space-y-6">
          <div className="flex flex-col md:flex-row md:items-end justify-between gap-4">
             <div>
                <h2 className="text-3xl font-display font-bold text-slate-900 dark:text-white">Transaction History</h2>
                <p className="text-slate-500 dark:text-slate-400 mt-1">
                   Track every move in your portfolio.
                </p>
             </div>
             <div className="flex items-center gap-3">
                 <button onClick={handleImportClick} className="hidden md:flex items-center space-x-2 px-3 py-2 rounded-xl text-xs font-bold bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 text-slate-600 dark:text-slate-300 hover:bg-slate-50 dark:hover:bg-slate-700 transition-colors">
                    <FileUp size={14} /> <span>Import</span>
                 </button>
                 <button onClick={handleExport} className="hidden md:flex items-center space-x-2 px-3 py-2 rounded-xl text-xs font-bold bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 text-slate-600 dark:text-slate-300 hover:bg-slate-50 dark:hover:bg-slate-700 transition-colors">
                    <FileDown size={14} /> <span>Export</span>
                 </button>
                 <button onClick={onAdd} className="flex items-center space-x-2 bg-slate-900 dark:bg-white text-white dark:text-slate-900 px-4 py-2 rounded-xl font-bold shadow-lg hover:opacity-90 transition-all active:scale-95">
                     <Plus size={18} /> <span className="hidden sm:inline">Add Transaction</span>
                 </button>
             </div>
          </div>

          {/* SUMMARY CARDS */}
          <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
             <div className="bg-white dark:bg-slate-800 p-4 rounded-2xl border border-slate-200 dark:border-slate-700 shadow-sm">
                <p className="text-[10px] uppercase font-bold text-slate-400 tracking-wider">Filtered Count</p>
                <p className="text-2xl font-display font-bold text-slate-900 dark:text-white mt-1">{stats.count}</p>
             </div>
             <div className="bg-white dark:bg-slate-800 p-4 rounded-2xl border border-slate-200 dark:border-slate-700 shadow-sm">
                <p className="text-[10px] uppercase font-bold text-emerald-500 tracking-wider">Total Inflow</p>
                <p className="text-xl font-mono font-bold text-emerald-600 dark:text-emerald-400 mt-1">+{formatNumber(stats.inflow, 0)}</p>
             </div>
             <div className="bg-white dark:bg-slate-800 p-4 rounded-2xl border border-slate-200 dark:border-slate-700 shadow-sm">
                <p className="text-[10px] uppercase font-bold text-rose-500 tracking-wider">Total Outflow</p>
                <p className="text-xl font-mono font-bold text-rose-600 dark:text-rose-400 mt-1">-{formatNumber(stats.outflow, 0)}</p>
             </div>
             <div className="bg-white dark:bg-slate-800 p-4 rounded-2xl border border-slate-200 dark:border-slate-700 shadow-sm">
                <p className="text-[10px] uppercase font-bold text-blue-500 tracking-wider">Net Cash Flow</p>
                <p className={`text-xl font-mono font-bold mt-1 ${stats.net >= 0 ? 'text-blue-600 dark:text-blue-400' : 'text-slate-500'}`}>
                   {stats.net >= 0 ? '+' : ''}{formatNumber(stats.net, 0)}
                </p>
             </div>
          </div>
      </div>

      {/* 2. SEARCH & FILTER TOOLBAR */}
      <div className="sticky top-[72px] z-20 bg-slate-50/95 dark:bg-[#0b1120]/95 backdrop-blur-sm py-2">
         <div className="flex gap-2">
             <div className="relative flex-1">
               <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={16} />
               <input 
                 type="text" placeholder="Search symbol, notes, type..." 
                 value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)}
                 className="w-full pl-10 pr-4 py-3 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl text-sm font-medium outline-none focus:ring-2 focus:ring-blue-500 transition-all shadow-sm"
               />
             </div>
             <button 
                onClick={() => setShowFilters(!showFilters)} 
                className={`px-4 rounded-xl border font-bold text-sm flex items-center gap-2 transition-all ${
                    showFilters || hasActiveFilters 
                    ? 'bg-slate-800 text-white border-slate-800 dark:bg-white dark:text-slate-900' 
                    : 'bg-white border-slate-200 text-slate-600 dark:bg-slate-800 dark:border-slate-700 dark:text-slate-300 hover:bg-slate-50'
                }`}
             >
                <Filter size={16} />
                <span className="hidden sm:inline">Filters</span>
                {hasActiveFilters && <div className="w-2 h-2 rounded-full bg-blue-500 ml-1 animate-pulse"></div>}
             </button>
         </div>

         {/* EXPANDABLE FILTERS */}
         {showFilters && (
            <div className="mt-2 p-4 bg-white dark:bg-slate-800 rounded-2xl border border-slate-200 dark:border-slate-700 shadow-lg grid grid-cols-2 md:grid-cols-4 gap-4 animate-slide-up">
               <div>
                  <label className="text-[10px] font-bold text-slate-400 uppercase mb-1 block">Type</label>
                  <select value={typeFilter} onChange={(e) => setTypeFilter(e.target.value as any)} className="w-full bg-slate-50 dark:bg-slate-900 border border-slate-200 dark:border-slate-700 rounded-lg px-3 py-2 text-sm outline-none font-medium">
                      <option value="ALL">All Types</option>
                      {Object.values(TransactionType).map(t => <option key={t} value={t}>{t}</option>)}
                  </select>
               </div>
               <div>
                  <label className="text-[10px] font-bold text-slate-400 uppercase mb-1 block">Asset Class</label>
                  <select value={assetClassFilter} onChange={(e) => setAssetClassFilter(e.target.value as any)} className="w-full bg-slate-50 dark:bg-slate-900 border border-slate-200 dark:border-slate-700 rounded-lg px-3 py-2 text-sm outline-none font-medium">
                      <option value="ALL">All Assets</option>
                      {Object.values(AssetClass).map(a => <option key={a} value={a}>{a}</option>)}
                  </select>
               </div>
               <div>
                  <label className="text-[10px] font-bold text-slate-400 uppercase mb-1 block">From Date</label>
                  <input type="date" value={startDate} onChange={(e) => setStartDate(e.target.value)} className="w-full bg-slate-50 dark:bg-slate-900 border border-slate-200 dark:border-slate-700 rounded-lg px-3 py-2 text-sm outline-none font-medium" />
               </div>
               <div>
                   <label className="text-[10px] font-bold text-slate-400 uppercase mb-1 block">To Date</label>
                   <div className="flex gap-2">
                      <input type="date" value={endDate} onChange={(e) => setEndDate(e.target.value)} className="w-full bg-slate-50 dark:bg-slate-900 border border-slate-200 dark:border-slate-700 rounded-lg px-3 py-2 text-sm outline-none font-medium" />
                      {hasActiveFilters && (
                          <button onClick={resetFilters} className="bg-rose-50 text-rose-500 p-2 rounded-lg hover:bg-rose-100 transition-colors" title="Reset Filters">
                              <XCircle size={18} />
                          </button>
                      )}
                   </div>
               </div>

               {/* Mobile Import/Export Actions inside filter menu */}
               <div className="col-span-2 md:hidden flex gap-2 pt-2 border-t border-slate-100 dark:border-slate-700">
                  <button onClick={handleImportClick} className="flex-1 py-2 rounded-lg bg-slate-50 dark:bg-slate-900 text-xs font-bold text-blue-600 flex items-center justify-center border border-slate-200 dark:border-slate-700">
                      <Upload size={14} className="mr-1"/> Import
                  </button>
                  <button onClick={handleExport} className="flex-1 py-2 rounded-lg bg-slate-50 dark:bg-slate-900 text-xs font-bold text-blue-600 flex items-center justify-center border border-slate-200 dark:border-slate-700">
                      <Download size={14} className="mr-1"/> Export
                  </button>
               </div>
            </div>
         )}
      </div>

      {/* 3. TRANSACTION LIST (GROUPED) */}
      <div className="space-y-6">
         {groupedTransactions.map((group) => (
            <div key={group.title} className="animate-slide-up">
                {/* Date Header */}
                <div className="flex items-center space-x-4 mb-3">
                   <h3 className="text-sm font-bold text-slate-500 dark:text-slate-400 uppercase tracking-wider">{group.title}</h3>
                   <div className="h-px bg-slate-200 dark:bg-slate-800 flex-1"></div>
                </div>

                <div className="bg-white dark:bg-slate-800 rounded-2xl shadow-sm border border-slate-200 dark:border-slate-700 overflow-hidden">
                   <div className="divide-y divide-slate-100 dark:divide-slate-800">
                      {group.txs.map(tx => {
                          const isPositive = tx.type === 'SELL' || tx.type === 'DIVIDEND' || tx.type === 'DEPOSIT';
                          const amount = (tx.type === 'BUY' || tx.type === 'SELL') ? (tx.price! * tx.shares!) : tx.price!;

                          return (
                             <div 
                               key={tx.id} 
                               className="group relative hover:bg-slate-50 dark:hover:bg-slate-700/30 transition-colors"
                             >
                                <div className="p-3 sm:p-4 flex items-center justify-between">

                                   {/* LEFT SIDE: Icon + Info */}
                                   <div className="flex items-center space-x-3 sm:space-x-4 min-w-0 flex-1 mr-2">
                                      {/* Icon Box */}
                                      <div className={`w-9 h-9 sm:w-10 sm:h-10 rounded-xl flex items-center justify-center shrink-0 ${getColorForType(tx.type)}`}>
                                         {getIconForType(tx.type)}
                                      </div>

                                      <div className="min-w-0 flex-1">
                                         <div className="flex items-center gap-2">
                                            <span className="font-bold text-slate-900 dark:text-white text-sm truncate">
                                                {tx.symbol || (tx.type === 'DEPOSIT' || tx.type === 'WITHDRAW' ? 'Cash Transfer' : tx.type)}
                                            </span>
                                            {tx.type === 'SPLIT' && <span className="hidden sm:inline-block text-[10px] bg-purple-100 text-purple-600 px-1.5 py-0.5 rounded font-bold">SPLIT</span>}
                                         </div>
                                         <div className="text-xs text-slate-500 dark:text-slate-400 flex items-center mt-0.5 truncate">
                                            <span className="uppercase font-semibold text-[10px] tracking-wide bg-slate-100 dark:bg-slate-700 px-1.5 rounded text-slate-500 dark:text-slate-300 mr-2 shrink-0">{tx.type}</span>
                                            {tx.assetClass !== 'Cash' && <span className="truncate">{tx.assetClass}</span>}
                                         </div>
                                      </div>
                                   </div>

                                   {/* RIGHT SIDE: Financials & Actions */}
                                   <div className="flex items-center gap-4 sm:gap-6 shrink-0">
                                       <div className="text-right">
                                          <div className={`font-mono font-bold text-sm ${isPositive ? 'text-emerald-600 dark:text-emerald-400' : 'text-slate-900 dark:text-white'}`}>
                                             {isPositive ? '+' : ''}{tx.type === 'SPLIT' ? '-' : formatCurrency(amount)}
                                          </div>
                                          {tx.shares && tx.shares > 0 && (
                                             <div className="text-xs text-slate-400 mt-0.5 font-mono">
                                                {formatNumber(tx.shares)} {tx.type === 'SPLIT' ? 'ratio' : 'units'}
                                                {/* Hide price on very small screens if needed, or wrap */}
                                                <span className="hidden xs:inline">
                                                    {tx.price && tx.type !== 'SPLIT' && ` @ ${formatCurrency(tx.price)}`}
                                                </span>
                                             </div>
                                          )}
                                       </div>

                                       {/* Desktop Quick Actions (Visible on Hover) */}
                                       <div className="hidden sm:flex items-center space-x-1 opacity-0 group-hover:opacity-100 transition-opacity">
                                           <button onClick={() => onEdit(tx)} className="p-2 text-slate-400 hover:text-blue-500 hover:bg-blue-50 dark:hover:bg-blue-900/20 rounded-lg transition-colors" title="Edit">
                                              <Edit2 size={16} />
                                           </button>
                                           <button onClick={() => onDelete(tx.id)} className="p-2 text-slate-400 hover:text-rose-500 hover:bg-rose-50 dark:hover:bg-rose-900/20 rounded-lg transition-colors" title="Delete">
                                              <Trash2 size={16} />
                                           </button>
                                       </div>
                                   </div>
                                </div>

                                {/* Mobile Action Overlay */}
                                <div className="absolute inset-0 sm:hidden z-10" onClick={() => onEdit(tx)}></div>
                             </div>
                          );
                      })}
                   </div>
                </div>
            </div>
         ))}

         {filteredTransactions.length === 0 && (
             <div className="py-20 flex flex-col items-center justify-center text-center p-8 rounded-3xl border-2 border-dashed border-slate-200 dark:border-slate-700 bg-slate-50/50 dark:bg-slate-800/50">
                 <div className="w-16 h-16 bg-white dark:bg-slate-800 rounded-full shadow-sm flex items-center justify-center mb-4">
                     <Search size={32} className="text-slate-300" />
                 </div>
                 <h3 className="text-lg font-bold text-slate-900 dark:text-white">No transactions found</h3>
                 <p className="text-slate-500 dark:text-slate-400 mt-1 max-w-xs">
                    Try adjusting your filters or search terms.
                 </p>
                 {hasActiveFilters && (
                    <button onClick={resetFilters} className="mt-4 px-4 py-2 bg-blue-50 text-blue-600 rounded-lg text-sm font-bold hover:bg-blue-100 transition-colors">
                       Clear Filters
                    </button>
                 )}
             </div>
         )}
      </div>
    </div>
  );
};

export default History;

import React, { useState, useMemo } from 'react';
import { Holding, Transaction, AssetClass } from '../types';
import { formatCurrency, formatNumber } from '../utils';
import { RefreshCw, Briefcase, LayoutGrid, List, Layers, ArrowUpRight, ArrowDownRight, Eye, EyeOff } from 'lucide-react';
import { AreaChart, Area, ResponsiveContainer, YAxis } from 'recharts';
import { HoldingsSkeleton } from './LoadingSkeletons';

interface HoldingsProps {
  holdings: Holding[];
  transactions: Transaction[];
  onUpdatePrice: (symbol: string, newPrice: number) => void;
  isLoading?: boolean;
}

const Holdings: React.FC<HoldingsProps> = ({ holdings, transactions, onUpdatePrice, isLoading }) => {
  const [viewMode, setViewMode] = useState<'list' | 'grid'>('list');
  const [groupByCategory, setGroupByCategory] = useState(false);
  // Default to TRUE to show only active assets first
  const [hideClosed, setHideClosed] = useState(true);

  // Price Editing State
  const [editingPrice, setEditingPrice] = useState<string | null>(null);
  const [tempPrice, setTempPrice] = useState<string>('');

  const handleEditClick = (symbol: string, currentPrice: number) => {
    setEditingPrice(symbol);
    setTempPrice(currentPrice.toString());
  };

  const handleSavePrice = (symbol: string) => {
    const price = parseFloat(tempPrice);
    if (!isNaN(price) && price >= 0) {
      onUpdatePrice(symbol, price);
    }
    setEditingPrice(null);
  };

  // --- DATA PROCESSING ---

  // 0. Filter Holdings based on Visibility Toggle
  const displayHoldings = useMemo(() => {
    return hideClosed 
      ? holdings.filter(h => h.shares > 0.000001) 
      : holdings;
  }, [holdings, hideClosed]);

  // 1. Group Holdings by Asset Class
  const groupedHoldings = useMemo(() => {
    const groups: Partial<Record<AssetClass, Holding[]>> = {};
    displayHoldings.forEach(h => {
      if (!groups[h.assetClass]) groups[h.assetClass] = [];
      groups[h.assetClass]?.push(h);
    });
    return groups;
  }, [displayHoldings]);

  // 2. Global Stats
  const { totalMarketValue, totalReturnPercent } = useMemo(() => {
    const mv = displayHoldings.reduce((sum, h) => sum + h.marketValue, 0);
    const cost = displayHoldings.reduce((sum, h) => sum + h.totalCost, 0);
    const pl = mv - cost;
    const pct = cost > 0 ? (pl / cost) * 100 : 0;
    return { totalMarketValue: mv, totalCost: cost, totalUnrealizedPL: pl, totalReturnPercent: pct };
  }, [displayHoldings]);

  // 3. Composition Data for "DNA Bar"
  const compositionData = useMemo(() => {
     if (totalMarketValue === 0) return [];
     return Object.keys(groupedHoldings).map(key => {
        const groupVal = groupedHoldings[key as AssetClass]!.reduce((sum, h) => sum + h.marketValue, 0);
        return {
           type: key,
           percent: (groupVal / totalMarketValue) * 100,
           color: key === 'Stock' ? 'bg-blue-500' : key === 'Crypto' ? 'bg-purple-500' : key === 'Cash' ? 'bg-emerald-500' : 'bg-orange-500'
        };
     }).sort((a,b) => b.percent - a.percent);
  }, [groupedHoldings, totalMarketValue]);


  if (isLoading) {
    return <HoldingsSkeleton />;
  }

  // --- RENDER HELPERS ---

  const renderCompositionBar = () => (
     <div className="w-full h-3 rounded-full overflow-hidden flex bg-slate-200 dark:bg-slate-700">
        {compositionData.map((seg) => (
           <div 
             key={seg.type} 
             className={`h-full ${seg.color} first:rounded-l-full last:rounded-r-full relative group`} 
             style={{ width: `${seg.percent}%` }}
           >
              <div className="absolute bottom-full mb-2 left-1/2 -translate-x-1/2 hidden group-hover:block bg-slate-900 text-white text-[10px] px-2 py-1 rounded whitespace-nowrap z-10">
                 {seg.type}: {seg.percent.toFixed(1)}%
              </div>
           </div>
        ))}
     </div>
  );

  const renderSparkline = (h: Holding, height = 40) => {
    const sparklineData = transactions
      .filter(t => t.symbol === h.symbol && (t.type === 'BUY' || t.type === 'SELL') && (t.price || 0) > 0)
      .sort((a, b) => new Date(a.date).getTime() - new Date(b.date).getTime())
      .map((t, i) => ({ i, price: t.price! }));

    if (h.currentPrice > 0) {
        sparklineData.push({ i: sparklineData.length, price: h.currentPrice });
    }

    const isUp = h.unrealizedPL >= 0;
    const color = isUp ? '#10b981' : '#f43f5e';

    if (sparklineData.length <= 1) return <div className="text-[10px] text-slate-300 italic h-full flex items-center">No Data</div>;

    return (
      <ResponsiveContainer width="100%" height={height}>
        <AreaChart data={sparklineData}>
          <defs>
            <linearGradient id={`gradient-${h.symbol}`} x1="0" y1="0" x2="0" y2="1">
              <stop offset="5%" stopColor={color} stopOpacity={0.3}/>
              <stop offset="95%" stopColor={color} stopOpacity={0}/>
            </linearGradient>
          </defs>
          <Area 
            type="monotone" 
            dataKey="price" 
            stroke={color} 
            strokeWidth={2} 
            fill={`url(#gradient-${h.symbol})`} 
            isAnimationActive={false} 
          />
          <YAxis domain={['dataMin', 'dataMax']} hide />
        </AreaChart>
      </ResponsiveContainer>
    );
  };

  const renderCard = (h: Holding) => {
    const portfolioPercent = totalMarketValue > 0 ? (h.marketValue / totalMarketValue) * 100 : 0;
    const isEditing = editingPrice === h.symbol;

    return (
      <div key={h.symbol} className={`group relative flex flex-col justify-between bg-white dark:bg-slate-800 rounded-3xl border border-slate-200 dark:border-slate-700 shadow-sm hover:shadow-xl hover:-translate-y-1 transition-all duration-300 overflow-hidden ${h.shares === 0 ? 'opacity-60 grayscale hover:grayscale-0 hover:opacity-100' : ''}`}>

         <div className={`h-24 w-full absolute top-0 left-0 bg-gradient-to-b ${h.unrealizedPL >= 0 ? 'from-emerald-50 to-white dark:from-emerald-900/10 dark:to-slate-800' : 'from-rose-50 to-white dark:from-rose-900/10 dark:to-slate-800'}`}></div>

         <div className="relative z-10 p-5 flex-1 flex flex-col">
            <div className="flex justify-between items-start mb-4">
              <div className="flex items-center space-x-3">
                  <div className="w-12 h-12 rounded-2xl bg-white dark:bg-slate-700 shadow-sm flex items-center justify-center font-bold text-slate-700 dark:text-slate-200 text-sm border border-slate-100 dark:border-slate-600 shrink-0">
                    {h.symbol.substring(0, 2)}
                  </div>
                  <div className="min-w-0">
                    <div className="flex items-center gap-1.5">
                       <h3 className="font-bold text-slate-900 dark:text-white leading-tight truncate">{h.symbol}</h3>
                       {h.shares === 0 && <span className="text-[9px] font-bold bg-slate-100 text-slate-500 px-1.5 py-0.5 rounded">SOLD</span>}
                    </div>
                    <p className="text-xs text-slate-500 dark:text-slate-400 truncate max-w-[120px]">{h.name}</p>
                  </div>
              </div>
              <div className="text-right">
                   {isEditing ? (
                      <input 
                        type="number" 
                        value={tempPrice} 
                        onChange={(e) => setTempPrice(e.target.value)}
                        className="w-20 px-2 py-1 text-sm font-bold border-2 border-blue-500 rounded-lg bg-white dark:bg-slate-900 dark:text-white focus:outline-none text-right"
                        autoFocus
                        onBlur={() => handleSavePrice(h.symbol)}
                        onKeyDown={(e) => e.key === 'Enter' && handleSavePrice(h.symbol)}
                      />
                   ) : (
                      <div className="group/price cursor-pointer" onClick={() => handleEditClick(h.symbol, h.currentPrice)}>
                         <p className="text-lg font-bold text-slate-900 dark:text-white group-hover/price:text-blue-500 transition-colors">{formatCurrency(h.currentPrice)}</p>
                         <p className="text-[10px] text-slate-400 uppercase font-semibold">Current Price</p>
                      </div>
                   )}
              </div>
            </div>

            <div className="flex-1 space-y-4">
               {h.shares > 0 && (
                   <div className="h-16 w-full relative">
                       <div className="absolute inset-0 opacity-80">{renderSparkline(h, 60)}</div>
                   </div>
               )}

               <div className="grid grid-cols-2 gap-4">
                  <div>
                    <p className="text-[10px] uppercase text-slate-400 font-bold mb-1">Total Value</p>
                    <p className="text-base font-display font-bold text-slate-900 dark:text-white">{formatCurrency(h.marketValue)}</p>
                  </div>
                  <div className="text-right">
                    <p className="text-[10px] uppercase text-slate-400 font-bold mb-1">All Time Return</p>
                    <div className={`flex items-center justify-end font-bold text-sm ${h.unrealizedPL >= 0 ? 'text-emerald-600 dark:text-emerald-400' : 'text-rose-600 dark:text-rose-400'}`}>
                        {h.unrealizedPL >= 0 ? '+' : ''}{formatCurrency(h.unrealizedPL)}
                    </div>
                  </div>
               </div>
            </div>
         </div>

         <div className="relative z-10 px-5 py-3 border-t border-slate-100 dark:border-slate-700/50 bg-slate-50/50 dark:bg-slate-900/30 flex justify-between items-center text-xs">
             <div className="flex flex-col">
                 <span className="text-slate-400 font-semibold text-[10px] uppercase">Qty</span>
                 <span className="font-mono font-medium text-slate-600 dark:text-slate-300">{formatNumber(h.shares, 4)}</span>
             </div>
             <div className="flex flex-col items-center">
                 <span className="text-slate-400 font-semibold text-[10px] uppercase">Avg</span>
                 <span className="font-medium text-slate-600 dark:text-slate-300">{formatCurrency(h.avgCost)}</span>
             </div>
             <div className="flex flex-col items-end w-16">
                 <span className="text-slate-400 font-semibold text-[10px] uppercase">Weight</span>
                 <div className="w-full h-1.5 bg-slate-200 dark:bg-slate-700 rounded-full mt-1 overflow-hidden">
                    <div className="h-full bg-blue-500 rounded-full" style={{ width: `${Math.min(portfolioPercent, 100)}%` }}></div>
                 </div>
             </div>
         </div>
      </div>
    );
  };

  const renderTableRows = (list: Holding[]) => (
    <div className="bg-white dark:bg-slate-800 rounded-3xl shadow-sm border border-slate-200 dark:border-slate-700 overflow-hidden">
      {/* DESKTOP TABLE VIEW */}
      <div className="hidden md:block overflow-x-auto">
        <table className="w-full text-left text-sm">
          <thead className="bg-slate-50 dark:bg-slate-900/50 text-slate-500 dark:text-slate-400 border-b border-slate-200 dark:border-slate-700 text-xs uppercase tracking-wider">
             <tr>
               <th className="px-6 py-4 font-bold">Asset</th>
               <th className="px-4 py-4 font-bold w-32 hidden lg:table-cell">Trend</th>
               <th className="px-6 py-4 font-bold text-right">Price</th>
               <th className="px-6 py-4 font-bold text-right">Balance</th>
               <th className="px-6 py-4 font-bold text-right">Weight</th>
               <th className="px-6 py-4 font-bold text-right">Performance</th>
             </tr>
          </thead>
          <tbody className="divide-y divide-slate-100 dark:divide-slate-800">
             {list.map(h => {
               const portfolioPercent = totalMarketValue > 0 ? (h.marketValue / totalMarketValue) * 100 : 0;
               return (
               <tr key={h.symbol} className={`group hover:bg-slate-50 dark:hover:bg-slate-800/50 transition-colors ${h.shares === 0 ? 'opacity-50 grayscale hover:opacity-100 hover:grayscale-0' : ''}`}>
                  <td className="px-6 py-4">
                     <div className="flex items-center space-x-4">
                        <div className="w-10 h-10 rounded-xl bg-slate-100 dark:bg-slate-700 flex items-center justify-center font-bold text-slate-600 dark:text-slate-300 shadow-sm border border-slate-200 dark:border-slate-600">
                           {h.symbol.substring(0, 2)}
                        </div>
                        <div>
                           <div className="flex items-center gap-2">
                             <div className="font-bold text-slate-900 dark:text-white text-base">{h.symbol}</div>
                             {h.shares === 0 && <span className="text-[9px] font-bold px-1.5 py-0.5 rounded bg-slate-200 dark:bg-slate-600 text-slate-500">SOLD</span>}
                           </div>
                           <div className="flex items-center gap-2 mt-0.5">
                              <span className="text-xs text-slate-500 dark:text-slate-400">{h.name}</span>
                              <span className="w-1 h-1 rounded-full bg-slate-300 dark:bg-slate-600"></span>
                              <span className="text-[10px] px-1.5 py-0.5 rounded-md bg-slate-100 dark:bg-slate-700/50 text-slate-500 dark:text-slate-400 font-medium">{h.sector}</span>
                           </div>
                        </div>
                     </div>
                  </td>

                  <td className="px-4 py-4 hidden lg:table-cell">
                     <div className="h-10 w-28 opacity-70 group-hover:opacity-100 transition-opacity">
                        {renderSparkline(h, 40)}
                     </div>
                  </td>

                  <td className="px-6 py-4 text-right">
                      {editingPrice === h.symbol ? (
                        <input 
                          type="number" 
                          value={tempPrice} 
                          onChange={(e) => setTempPrice(e.target.value)}
                          className="w-24 px-2 py-1 text-sm font-bold border-2 border-blue-500 rounded-lg bg-white dark:bg-slate-900 dark:text-white focus:outline-none text-right"
                          autoFocus
                          onBlur={() => handleSavePrice(h.symbol)}
                          onKeyDown={(e) => e.key === 'Enter' && handleSavePrice(h.symbol)}
                        />
                      ) : (
                        <div className="flex flex-col items-end group/edit cursor-pointer" onClick={() => handleEditClick(h.symbol, h.currentPrice)}>
                           <div className="flex items-center gap-1.5 hover:text-blue-600 transition-colors">
