const MonthlyActivityView: React.FC<{ transactions: Transaction[] }> = ({ transactions }) => {
  const [range, setRange] = useState<number>(12); // Default 12 months for better trend view
  const [expandedMonth, setExpandedMonth] = useState<string | null>(null);

  // Data Calculation
  const monthlyData = useMemo(() => calculateMonthlyActivity(transactions), [transactions]);

  // Prepare data for display (Chart needs Oldest -> Newest)
  const displayData = range === 999 ? monthlyData : monthlyData.slice(0, range);
  const chartData = useMemo(() => {
     return [...displayData].reverse().map(d => ({
        ...d,
        netInvested: d.buyVolume - d.sellVolume // Net Accumulation
     }));
  }, [displayData]);

  // Insights Calculation
  const currentMonth = monthlyData[0] || { buyVolume: 0, sellVolume: 0, dividendIncome: 0, yearMonth: 'N/A' };
  const prevMonth = monthlyData[1] || { buyVolume: 0, sellVolume: 0, dividendIncome: 0 };

  // Calculate Average Investment (excluding 0 months to be fair)
  const activeMonths = monthlyData.filter(m => m.buyVolume > 0);
  const avgInvestment = activeMonths.length > 0 
    ? activeMonths.reduce((sum, m) => sum + (m.buyVolume - m.sellVolume), 0) / activeMonths.length 
    : 0;

  // Auto-expand latest month on mount if data exists
  useEffect(() => {
    if (monthlyData.length > 0 && !expandedMonth) {
      setExpandedMonth(monthlyData[0].yearMonth);
    }
  }, [monthlyData]);

  const toggleMonth = (ym: string) => {
    setExpandedMonth(expandedMonth === ym ? null : ym);
