                                  type="number" 
                                  value={tempTarget}
                                  onClick={(e) => e.stopPropagation()}
                                  onChange={(e) => setTempTarget(e.target.value)}
                                  onBlur={() => handleSaveTarget(h.symbol)}
                                  className="w-8 text-right text-xs border-b border-blue-500 bg-transparent outline-none font-bold text-blue-500"
                                  autoFocus
                               />
                           ) : (
                               <span className={`text-xs ${target > 0 ? 'text-slate-500 dark:text-slate-400' : 'text-blue-500'}`}>{target > 0 ? `${target}%` : '-'}</span>
                           )}
                        </div>
                     </div>
                  </div>
               </div>
             )
         })}
      </div>
    </div>
  );
};

