                        </div>
                      )}
                  </td>

                  <td className="px-6 py-4 text-right">
                     <div className="font-bold text-slate-900 dark:text-white">{formatCurrency(h.marketValue)}</div>
                     <div className="text-xs text-slate-500 font-mono mt-0.5">{formatNumber(h.shares, 4)} units</div>
