                        <span className="text-[10px] uppercase text-slate-400 font-bold">Alloc / Target</span>
                        <div className="flex items-center space-x-1 mt-0.5">
                           <span className="text-sm font-bold text-slate-700 dark:text-slate-300">{portfolioPercent.toFixed(0)}%</span>
