            {renderCompositionBar()}
            <div className="flex gap-4 mt-2 overflow-x-auto pb-1 no-scrollbar">
                {compositionData.map(c => (
                    <div key={c.type} className="flex items-center space-x-1.5 shrink-0">
                        <div className={`w-2 h-2 rounded-full ${c.color}`}></div>
                        <span className="text-xs font-medium text-slate-600 dark:text-slate-300">{c.type}</span>
                        <span className="text-xs text-slate-400">({c.percent.toFixed(0)}%)</span>
                    </div>
                ))}
            </div>
        </div>

        {/* Filters Toolbar */}
        <div className="flex flex-wrap items-center gap-3">
             <button 
               onClick={() => setGroupByCategory(!groupByCategory)}
               className={`flex items-center space-x-2 px-3 py-2 rounded-xl text-xs font-bold border transition-all ${
                 groupByCategory
                 ? 'bg-blue-50 border-blue-200 text-blue-600 dark:bg-blue-900/20 dark:border-blue-800 dark:text-blue-400'
                 : 'bg-white border-slate-200 text-slate-600 dark:bg-slate-800 dark:border-slate-700 dark:text-slate-400 hover:bg-slate-50 dark:hover:bg-slate-700'
               }`}
             >
                <Layers size={14} />
                <span>Group by Asset Class</span>
             </button>

             <button 
               onClick={() => setHideClosed(!hideClosed)}
               className={`flex items-center space-x-2 px-3 py-2 rounded-xl text-xs font-bold border transition-all ${
                 hideClosed
                 ? 'bg-emerald-50 border-emerald-200 text-emerald-600 dark:bg-emerald-900/20 dark:border-emerald-800 dark:text-emerald-400'
                 : 'bg-white border-slate-200 text-slate-600 dark:bg-slate-800 dark:border-slate-700 dark:text-slate-400 hover:bg-slate-50 dark:hover:bg-slate-700'
               }`}
             >
                {hideClosed ? <Eye size={14} /> : <EyeOff size={14} />}
                <span>{hideClosed ? 'Showing Active Only' : 'Showing All Positions'}</span>
             </button>

             <div className="ml-auto flex items-center space-x-2 bg-slate-100 dark:bg-slate-800 px-3 py-1.5 rounded-lg">
                <span className={`text-xs font-bold ${totalReturnPercent >= 0 ? 'text-emerald-600' : 'text-rose-600'}`}>
                    Total Return: {totalReturnPercent >= 0 ? '+' : ''}{totalReturnPercent.toFixed(2)}%
                </span>
             </div>
        </div>
      </div>

      {/* 2. Content Area */}

      <div className="animate-slide-up space-y-8">
            {groupByCategory ? (
               // GROUPED VIEW
               Object.keys(groupedHoldings).map((assetClass) => {
                  const items = groupedHoldings[assetClass as AssetClass];
                  if (!items || items.length === 0) return null;

                  return (
                     <div key={assetClass} className="space-y-4">
                        <div className="flex items-center space-x-3">
                           <span className="bg-slate-900 dark:bg-white text-white dark:text-slate-900 px-3 py-1 rounded-lg text-xs font-extrabold uppercase tracking-wide shadow-md">
                              {assetClass}
                           </span>
                           <div className="h-px bg-slate-200 dark:bg-slate-700 flex-1"></div>
                           <span className="text-xs font-bold text-slate-400 uppercase tracking-wider">{formatCurrency(items.reduce((sum, h) => sum + h.marketValue, 0))}</span>
                        </div>

                        {viewMode === 'grid' ? (
                           <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">
                              {items.map(h => renderCard(h))}
                           </div>
                        ) : (
                           renderTableRows(items)
                        )}
                     </div>
                  );
               })
            ) : (
               // UNGROUPED VIEW
               viewMode === 'grid' ? (
                  <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">
                     {displayHoldings.map(h => renderCard(h))}
                  </div>
               ) : (
                  renderTableRows(displayHoldings)
               )
            )}

            {displayHoldings.length === 0 && (
               <div className="py-24 flex flex-col items-center justify-center text-center p-8 rounded-3xl border-2 border-dashed border-slate-200 dark:border-slate-700 bg-slate-50/50 dark:bg-slate-800/50">
                  <div className="w-20 h-20 bg-white dark:bg-slate-800 rounded-full shadow-sm flex items-center justify-center mb-6">
                     <Briefcase size={40} className="text-slate-300" />
                  </div>
                  <h3 className="text-xl font-bold text-slate-900 dark:text-white">No Assets Found</h3>
                  <p className="text-slate-500 dark:text-slate-400 max-w-md mt-2 mb-6">
                     {holdings.length === 0
                        ? "Your portfolio is currently empty. Start by adding a transaction."
                        : (hideClosed 
                            ? "No active holdings found. Turn off 'Active Only' to see sold positions." 
                            : "No assets match your criteria.")}
                  </p>
               </div>
            )}
      </div>
    </div>
  );
};

export default Holdings;

import React, { useState, useMemo } from 'react';
import { Holding, Transaction, AssetClass } from '../types';
