import { AreaChart, Area, ResponsiveContainer, YAxis, XAxis } from 'recharts';
import { HoldingsSkeleton } from './LoadingSkeletons';

interface HoldingsProps {
  holdings: Holding[];
  transactions: Transaction[];
  onUpdatePrice: (symbol: string, newPrice: number) => void;
  onUpdateTarget: (symbol: string, target: number) => void;
  isLoading?: boolean;
}

const Holdings: React.FC<HoldingsProps> = ({ holdings, transactions, onUpdatePrice, onUpdateTarget, isLoading }) => {
  const [groupByCategory, setGroupByCategory] = useState(false);
  const [hideClosed, setHideClosed] = useState(true);

  // Price Editing State
  const [editingPrice, setEditingPrice] = useState<string | null>(null);
  const [tempPrice, setTempPrice] = useState<string>('');

  // Target Editing State
  const [editingTarget, setEditingTarget] = useState<string | null>(null);
  const [tempTarget, setTempTarget] = useState<string>('');

  const handleEditClick = (symbol: string, currentPrice: number) => {
    setEditingPrice(symbol);
    setTempPrice(currentPrice.toString());
  };

  const handleSavePrice = (symbol: string) => {
    const price = parseFloat(tempPrice);
    if (!isNaN(price) && price >= 0) {
      onUpdatePrice(symbol, price);
    }
    setEditingPrice(null);
  };

  const handleEditTargetClick = (symbol: string, currentTarget: number) => {
    setEditingTarget(symbol);
    setTempTarget(currentTarget.toString());
  };

  const handleSaveTarget = (symbol: string) => {
    const target = parseFloat(tempTarget);
    if (!isNaN(target) && target >= 0 && target <= 100) {
      onUpdateTarget(symbol, target);
    }
    setEditingTarget(null);
  };

  // --- DATA PROCESSING ---

  const displayHoldings = useMemo(() => {
    return hideClosed 
      ? holdings.filter(h => h.shares > 0.000001) 
      : holdings;
  }, [holdings, hideClosed]);

  const groupedHoldings = useMemo(() => {
    const groups: Partial<Record<AssetClass, Holding[]>> = {};
    displayHoldings.forEach(h => {
      if (!groups[h.assetClass]) groups[h.assetClass] = [];
      groups[h.assetClass]?.push(h);
    });
    return groups;
  }, [displayHoldings]);

  const { totalMarketValue, totalReturnPercent } = useMemo(() => {
    const mv = displayHoldings.reduce((sum, h) => sum + h.marketValue, 0);
    const cost = displayHoldings.reduce((sum, h) => sum + h.totalCost, 0);
    const pl = mv - cost;
    const pct = cost > 0 ? (pl / cost) * 100 : 0;
    return { totalMarketValue: mv, totalCost: cost, totalUnrealizedPL: pl, totalReturnPercent: pct };
  }, [displayHoldings]);

  const compositionData = useMemo(() => {
     if (totalMarketValue === 0) return [];
     return Object.keys(groupedHoldings).map(key => {
        const groupVal = groupedHoldings[key as AssetClass]!.reduce((sum, h) => sum + h.marketValue, 0);
        return {
           type: key,
           percent: (groupVal / totalMarketValue) * 100,
           color: key === 'Stock' ? 'bg-blue-500' : key === 'Crypto' ? 'bg-purple-500' : key === 'Cash' ? 'bg-emerald-500' : 'bg-orange-500'
        };
     }).sort((a,b) => b.percent - a.percent);
  }, [groupedHoldings, totalMarketValue]);

  if (isLoading) {
    return <HoldingsSkeleton />;
  }

  // --- RENDER HELPERS ---

  const renderCompositionBar = () => (
     <div className="w-full h-3 rounded-full overflow-hidden flex bg-slate-200 dark:bg-slate-700">
        {compositionData.map((seg) => (
           <div 
             key={seg.type} 
             className={`h-full ${seg.color} first:rounded-l-full last:rounded-r-full relative group`} 
             style={{ width: `${seg.percent}%` }}
           >
              <div className="absolute bottom-full mb-2 left-1/2 -translate-x-1/2 hidden group-hover:block bg-slate-900 text-white text-[10px] px-2 py-1 rounded whitespace-nowrap z-10">
                 {seg.type}: {seg.percent.toFixed(1)}%
              </div>
           </div>
        ))}
     </div>
  );

  const renderSparkline = (h: Holding, height = 60) => {
    const sparklineData = transactions
      .filter(t => t.symbol === h.symbol && (t.type === 'BUY' || t.type === 'SELL') && (t.price || 0) > 0)
      .sort((a, b) => new Date(a.date).getTime() - new Date(b.date).getTime())
      .map((t) => ({ date: new Date(t.date).getTime(), price: t.price! }));

    if (h.currentPrice > 0) {
        sparklineData.push({ date: Date.now(), price: h.currentPrice });
    }

    const isUp = h.unrealizedPL >= 0;
    const color = isUp ? '#10b981' : '#f43f5e';

    if (sparklineData.length < 2) return <div className="text-[10px] text-slate-300 italic h-full flex items-center justify-center">No Data</div>;

    return (
      <ResponsiveContainer width="100%" height={height}>
        <AreaChart data={sparklineData}>
          <defs>
            <linearGradient id={`gradient-${h.symbol}`} x1="0" y1="0" x2="0" y2="1">
              <stop offset="5%" stopColor={color} stopOpacity={0.3}/>
              <stop offset="95%" stopColor={color} stopOpacity={0}/>
            </linearGradient>
          </defs>
          <Area 
            type="monotone" 
            dataKey="price" 
            stroke={color} 
            strokeWidth={2} 
            fill={`url(#gradient-${h.symbol})`} 
            isAnimationActive={false} 
          />
          <YAxis domain={['dataMin', 'dataMax']} hide />
          <XAxis dataKey="date" hide />
        </AreaChart>
      </ResponsiveContainer>
    );
  };

  const renderCard = (h: Holding) => {
    const portfolioPercent = totalMarketValue > 0 ? (h.marketValue / totalMarketValue) * 100 : 0;
    const isEditingPrice = editingPrice === h.symbol;
    const isEditingTarget = editingTarget === h.symbol;
    const target = h.targetAllocation || 0;

    return (
      <div key={h.symbol} className={`group flex flex-col bg-white dark:bg-slate-800 rounded-3xl border border-slate-200 dark:border-slate-700 shadow-sm hover:shadow-xl hover:-translate-y-1 transition-all duration-300 overflow-hidden ${h.shares === 0 ? 'opacity-60 grayscale hover:grayscale-0 hover:opacity-100' : ''}`}>
         <div className="p-5 flex-1 flex flex-col">

            {/* Header: Icon, Name, Price */}
            <div className="flex justify-between items-start mb-4">
              <div className="flex items-center space-x-3 min-w-0">
                  <div className="w-10 h-10 rounded-2xl bg-slate-100 dark:bg-slate-700 flex items-center justify-center font-bold text-slate-700 dark:text-slate-200 text-sm shrink-0">
                    {h.symbol.substring(0, 2)}
                  </div>
                  <div className="min-w-0">
                    <h3 className="font-bold text-slate-900 dark:text-white leading-tight truncate">{h.symbol}</h3>
                    <p className="text-xs text-slate-500 dark:text-slate-400 truncate">{h.name}</p>
                  </div>
              </div>
              <div className="text-right shrink-0">
                   {isEditingPrice ? (
                      <input 
                        type="number" 
                        value={tempPrice} 
                        onChange={(e) => setTempPrice(e.target.value)}
                        className="w-20 px-2 py-1 text-sm font-bold border-2 border-blue-500 rounded-lg bg-white dark:bg-slate-900 dark:text-white focus:outline-none text-right"
                        autoFocus
                        onBlur={() => handleSavePrice(h.symbol)}
                        onKeyDown={(e) => e.key === 'Enter' && handleSavePrice(h.symbol)}
                      />
                   ) : (
                      <div className="cursor-pointer group/price" onClick={() => handleEditClick(h.symbol, h.currentPrice)}>
                         <p className="text-base font-bold text-slate-900 dark:text-white group-hover/price:text-blue-500 transition-colors">{formatCurrency(h.currentPrice)}</p>
                         <div className="flex items-center justify-end gap-1 text-[10px] text-slate-400">
                            <span className="uppercase font-semibold">Price</span>
                            <RefreshCw size={8} className="opacity-0 group-hover/price:opacity-100 transition-opacity" />
                         </div>
                      </div>
                   )}
              </div>
            </div>

            {/* Middle: Sparkline Chart */}
            <div className="h-16 w-full -mx-1 mb-4 opacity-80">
                {h.shares > 0 && renderSparkline(h)}
            </div>

            {/* Metrics Grid: Total Value & Unrealized P/L */}
            <div className="grid grid-cols-2 gap-4 mb-4 p-3 bg-slate-50 dark:bg-slate-900/50 rounded-xl">
               <div>
                 <p className="text-[9px] uppercase text-slate-400 font-bold mb-0.5">Total Value</p>
                 <p className="text-sm font-bold text-slate-900 dark:text-white">{formatCurrency(h.marketValue)}</p>
               </div>
               <div className="text-right">
                 <p className="text-[9px] uppercase text-slate-400 font-bold mb-0.5">Unrealized P/L</p>
                 <div className={`text-sm font-bold ${h.unrealizedPL >= 0 ? 'text-emerald-600 dark:text-emerald-400' : 'text-rose-600 dark:text-rose-400'}`}>
                     {h.unrealizedPL >= 0 ? '+' : ''}{formatCurrency(h.unrealizedPL)}
                 </div>
               </div>
            </div>

            {/* Footer: Allocation & Target */}
            <div className="flex justify-between items-center mt-auto pt-2 border-t border-slate-100 dark:border-slate-800">
               {/* Target Allocation Editor */}
               <div 
                  className="flex items-center space-x-2 cursor-pointer group/target px-2 py-1 rounded-lg hover:bg-slate-50 dark:hover:bg-slate-700/50 transition-colors -ml-2" 
                  onClick={() => !isEditingTarget && handleEditTargetClick(h.symbol, target)}
               >
                   <div className="bg-blue-100 dark:bg-blue-900/30 p-1.5 rounded-lg text-blue-600 dark:text-blue-400">
                      <Target size={14} />
                   </div>
                   <div>
                      <p className="text-[9px] font-bold text-slate-400 uppercase">Target</p>
                      <div className="h-4 flex items-center">
                         {isEditingTarget ? (
                            <div className="flex items-center">
                                <input 
                                   type="number" 
                                   value={tempTarget} 
                                   onChange={(e) => setTempTarget(e.target.value)}
                                   className="w-8 px-0 py-0 text-xs border-b-2 border-blue-500 bg-transparent outline-none font-bold text-slate-900 dark:text-white"
                                   autoFocus
                                   onClick={(e) => e.stopPropagation()}
                                   onBlur={() => handleSaveTarget(h.symbol)}
                                   onKeyDown={(e) => e.key === 'Enter' && handleSaveTarget(h.symbol)}
                                />
                                <span className="text-xs text-slate-500 font-bold">%</span>
                            </div>
                         ) : (
                            <div className="flex items-center gap-1">
                               <span className={`text-xs font-bold ${target > 0 ? 'text-slate-700 dark:text-slate-300' : 'text-blue-500'}`}>
                                  {target > 0 ? `${target}%` : 'Set %'}
                               </span>
                               {target > 0 && <span className="text-[9px] text-slate-400">({portfolioPercent.toFixed(1)}% Act)</span>}
                            </div>
                         )}
                      </div>
                   </div>
               </div>

               {/* Quantity */}
               <div className="text-right">
                   <p className="text-[9px] font-bold text-slate-400 uppercase">Qty</p>
                   <p className="text-xs font-bold text-slate-700 dark:text-slate-300 font-mono">{formatNumber(h.shares, 4)}</p>
               </div>
            </div>
         </div>
      </div>
    );
  };

  return (
    <div className="space-y-8 animate-fade-in pb-12">

      {/* 1. Header & Summary Stats */}
      <div className="flex flex-col gap-6">
        <div className="flex flex-col md:flex-row md:items-end justify-between gap-4">
           <div>
             <h2 className="text-3xl font-display font-bold text-slate-900 dark:text-white">Assets</h2>
             <p className="text-slate-500 dark:text-slate-400 mt-1">
                {displayHoldings.length} Positions across {Object.keys(groupedHoldings).length} Asset Classes
             </p>
           </div>
        </div>

        {/* Portfolio DNA Bar */}
        <div className="w-full">
            <div className="flex justify-between items-end mb-2">
                <span className="text-xs font-bold text-slate-400 uppercase tracking-wider">Portfolio Composition</span>
                <span className="text-xs font-bold text-slate-900 dark:text-white">{formatCurrency(totalMarketValue)}</span>
            </div>
            {renderCompositionBar()}
            <div className="flex gap-4 mt-2 overflow-x-auto pb-1 no-scrollbar">
                {compositionData.map(c => (
                    <div key={c.type} className="flex items-center space-x-1.5 shrink-0">
                        <div className={`w-2 h-2 rounded-full ${c.color}`}></div>
                        <span className="text-xs font-medium text-slate-600 dark:text-slate-300">{c.type}</span>
                        <span className="text-xs text-slate-400">({c.percent.toFixed(0)}%)</span>
                    </div>
                ))}
            </div>
        </div>

        {/* Filters Toolbar */}
        <div className="flex flex-wrap items-center gap-3">
             <button 
               onClick={() => setGroupByCategory(!groupByCategory)}
               className={`flex items-center space-x-2 px-3 py-2 rounded-xl text-xs font-bold border transition-all ${
                 groupByCategory
                 ? 'bg-blue-50 border-blue-200 text-blue-600 dark:bg-blue-900/20 dark:border-blue-800 dark:text-blue-400'
                 : 'bg-white border-slate-200 text-slate-600 dark:bg-slate-800 dark:border-slate-700 dark:text-slate-400 hover:bg-slate-50 dark:hover:bg-slate-700'
               }`}
             >
                <Layers size={14} />
                <span>Group by Asset Class</span>
             </button>

             <button 
               onClick={() => setHideClosed(!hideClosed)}
               className={`flex items-center space-x-2 px-3 py-2 rounded-xl text-xs font-bold border transition-all ${
                 hideClosed
                 ? 'bg-emerald-50 border-emerald-200 text-emerald-600 dark:bg-emerald-900/20 dark:border-emerald-800 dark:text-emerald-400'
                 : 'bg-white border-slate-200 text-slate-600 dark:bg-slate-800 dark:border-slate-700 dark:text-slate-400 hover:bg-slate-50 dark:hover:bg-slate-700'
               }`}
             >
                {hideClosed ? <Eye size={14} /> : <EyeOff size={14} />}
                <span>{hideClosed ? 'Showing Active Only' : 'Showing All Positions'}</span>
             </button>

             <div className="ml-auto flex items-center space-x-2 bg-slate-100 dark:bg-slate-800 px-3 py-1.5 rounded-lg">
                <span className={`text-xs font-bold ${totalReturnPercent >= 0 ? 'text-emerald-600' : 'text-rose-600'}`}>
                    Total Return: {totalReturnPercent >= 0 ? '+' : ''}{totalReturnPercent.toFixed(2)}%
                </span>
             </div>
        </div>
      </div>

      {/* 2. Content Area - Cards Grid */}
      <div className="animate-slide-up space-y-8">
            {groupByCategory ? (
               Object.keys(groupedHoldings).map((assetClass) => {
                  const items = groupedHoldings[assetClass as AssetClass];
                  if (!items || items.length === 0) return null;

                  return (
                     <div key={assetClass} className="space-y-4">
                        <div className="flex items-center space-x-3">
                           <span className="bg-slate-900 dark:bg-white text-white dark:text-slate-900 px-3 py-1 rounded-lg text-xs font-extrabold uppercase tracking-wide shadow-md">
                              {assetClass}
                           </span>
                           <div className="h-px bg-slate-200 dark:bg-slate-700 flex-1"></div>
                           <span className="text-xs font-bold text-slate-400 uppercase tracking-wider">{formatCurrency(items.reduce((sum, h) => sum + h.marketValue, 0))}</span>
                        </div>

                        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">
                           {items.map(h => renderCard(h))}
                        </div>
                     </div>
                  );
               })
            ) : (
               <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">
                  {displayHoldings.map(h => renderCard(h))}
               </div>
            )}

            {displayHoldings.length === 0 && (
               <div className="py-24 flex flex-col items-center justify-center text-center p-8 rounded-3xl border-2 border-dashed border-slate-200 dark:border-slate-700 bg-slate-50/50 dark:bg-slate-800/50">
                  <div className="w-20 h-20 bg-white dark:bg-slate-800 rounded-full shadow-sm flex items-center justify-center mb-6">
                     <Briefcase size={40} className="text-slate-300" />
                  </div>
                  <h3 className="text-xl font-bold text-slate-900 dark:text-white">No Assets Found</h3>
                  <p className="text-slate-500 dark:text-slate-400 max-w-md mt-2 mb-6">
                     {holdings.length === 0
                        ? "Your portfolio is currently empty. Start by adding a transaction."
                        : (hideClosed 
                            ? "No active holdings found. Turn off 'Active Only' to see sold positions." 
                            : "No assets match your criteria.")}
                  </p>
               </div>
            )}
      </div>
    </div>
  );
};

export default Holdings;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import Layout from './components/Layout';
import Dashboard from './components/Dashboard';
import Holdings from './components/Holdings';
import Reports from './components/Reports';
import History from './components/History';
import GoalModal from './components/GoalModal';
import { Transaction, TransactionType, AssetClass, Holding, Portfolio, FinancialGoal } from './types';
import { calculateHoldings, calculatePortfolioHistory, generateId, formatCurrency, formatNumber } from './utils';
import { X, Save, TrendingUp, TrendingDown, DollarSign, Wallet, Calendar, GitFork, AlertCircle, ArrowRight, Trash2, Zap, Calculator, Search, Clock, PlusCircle, MinusCircle, RefreshCcw, Split, Hash, ChevronDown, ArrowRightCircle, Globe, CheckCircle2, FileText, Banknote, Percent, Info } from 'lucide-react';
import { Spinner } from './components/LoadingSkeletons';

const POPULAR_SYMBOLS = [
  'AAPL', 'MSFT', 'GOOGL', 'AMZN', 'NVDA', 'TSLA', 'META', 'BRK.B', 'V', 'JNJ', 'WMT', 'JPM', // Tech/Blue Chip
  'VOO', 'VTI', 'QQQ', 'IVV', 'SCHD', 'JEPI', 'VUG', 'VTV', // ETFs
  'BTC', 'ETH', 'SOL', 'USDT', 'BNB', 'XRP', 'ADA' // Crypto
];

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState('dashboard');
  const [isAddModalOpen, setIsAddModalOpen] = useState(false);
  const [editingTransaction, setEditingTransaction] = useState<Transaction | null>(null);

  // Persistence for better UX
  const [lastTxDate, setLastTxDate] = useState<string>(() => localStorage.getItem('lastTxDate') || new Date().toISOString().split('T')[0]);

  // Goal Modal State
  const [isGoalModalOpen, setIsGoalModalOpen] = useState(false);

  // --- CONFIRMATION MODAL STATE ---
  const [confirmConfig, setConfirmConfig] = useState<{
    isOpen: boolean;
    title: string;
    message: string;
    onConfirm: () => void;
  }>({
    isOpen: false,
    title: '',
    message: '',
    onConfirm: () => {},
  });

  // --- PORTFOLIO MANAGEMENT STATE ---
  const [portfolios, setPortfolios] = useState<Portfolio[]>(() => {
    const saved = localStorage.getItem('portfolios');
    if (saved) return JSON.parse(saved);
    const legacyTx = localStorage.getItem('transactions');
    if (legacyTx) return [{ id: 'default', name: 'Main Portfolio' }];
    return [{ id: generateId(), name: 'My First Portfolio' }];
  });

  const [activePortfolioId, setActivePortfolioId] = useState<string>(() => {
    const saved = localStorage.getItem('activePortfolioId');
    const portfolios = JSON.parse(localStorage.getItem('portfolios') || '[]');
    if (saved && portfolios.some((p: Portfolio) => p.id === saved)) return saved;
    return portfolios.length > 0 ? portfolios[0].id : 'default';
  });

  // --- DATA STATE (Per Portfolio) - Synchronous Initialization ---
  const [transactions, setTransactions] = useState<Transaction[]>(() => {
    const key = `transactions_${activePortfolioId}`;
    const saved = localStorage.getItem(key);
    if (saved) return JSON.parse(saved);
    if (activePortfolioId === 'default') {
      const legacy = localStorage.getItem('transactions');
      if (legacy) return JSON.parse(legacy);
    }
    return [];
  });

  const [prices, setPrices] = useState<Record<string, number>>(() => {
    const key = `prices_${activePortfolioId}`;
    const saved = localStorage.getItem(key);
    if (saved) return JSON.parse(saved);
    if (activePortfolioId === 'default') {
      const legacy = localStorage.getItem('prices');
      if (legacy) return JSON.parse(legacy);
    }
    return {};
  });

  const [targets, setTargets] = useState<Record<string, number>>(() => {
    const key = `targets_${activePortfolioId}`;
    const saved = localStorage.getItem(key);
    if (saved) {
       try {
         // Fix: Handle null or invalid JSON gracefully
         const parsed = JSON.parse(saved);
         return parsed || {};
       } catch (e) {
         return {};
       }
    }
    return {};
  });

  const [goals, setGoals] = useState<FinancialGoal[]>(() => {
    const key = `goals_${activePortfolioId}`;
    const saved = localStorage.getItem(key);
    if (saved) return JSON.parse(saved);

    let legacyGoal = 100000;
    const legacyKey = `financialGoal_${activePortfolioId}`;
    const savedLegacy = localStorage.getItem(legacyKey);
    if (savedLegacy) legacyGoal = parseFloat(savedLegacy);
    else if (activePortfolioId === 'default' && localStorage.getItem('financialGoal')) legacyGoal = parseFloat(localStorage.getItem('financialGoal')!);

    return [{ id: generateId(), targetAmount: legacyGoal, startDate: new Date().toISOString(), isAchieved: false, notes: 'Initial Goal' }];
  });

  const [isDataLoaded, setIsDataLoaded] = useState(true);
  const [isLoading, setIsLoading] = useState(false);
  const isFirstMount = useRef(true);

  // --- PERSISTENCE ---
  useEffect(() => { localStorage.setItem('portfolios', JSON.stringify(portfolios)); }, [portfolios]);
  useEffect(() => { localStorage.setItem('activePortfolioId', activePortfolioId); }, [activePortfolioId]);

  useEffect(() => {
    if (isFirstMount.current) { isFirstMount.current = false; return; }
    setIsLoading(true);
    setIsDataLoaded(false);
    const loadData = () => {
        const txKey = `transactions_${activePortfolioId}`;
        const pricesKey = `prices_${activePortfolioId}`;
        const goalsKey = `goals_${activePortfolioId}`;
        const targetsKey = `targets_${activePortfolioId}`;

        const savedTx = localStorage.getItem(txKey);
        setTransactions(savedTx ? JSON.parse(savedTx) : []);

        const savedPrices = localStorage.getItem(pricesKey);
        setPrices(savedPrices ? JSON.parse(savedPrices) : {});

        const savedTargets = localStorage.getItem(targetsKey);
        // Safe parsing for targets
        try {
            const parsedTargets = savedTargets ? JSON.parse(savedTargets) : {};
            setTargets(parsedTargets || {});
        } catch {
            setTargets({});
        }

        const savedGoals = localStorage.getItem(goalsKey);
        setGoals(savedGoals ? JSON.parse(savedGoals) : []); 

        setIsDataLoaded(true);
        setTimeout(() => setIsLoading(false), 500);
    };
    requestAnimationFrame(loadData);
  }, [activePortfolioId]);

  useEffect(() => { if (isDataLoaded) localStorage.setItem(`transactions_${activePortfolioId}`, JSON.stringify(transactions)); }, [transactions, activePortfolioId, isDataLoaded]);
  useEffect(() => { if (isDataLoaded) localStorage.setItem(`prices_${activePortfolioId}`, JSON.stringify(prices)); }, [prices, activePortfolioId, isDataLoaded]);
  useEffect(() => { if (isDataLoaded) localStorage.setItem(`targets_${activePortfolioId}`, JSON.stringify(targets)); }, [targets, activePortfolioId, isDataLoaded]);
  useEffect(() => { if (isDataLoaded) localStorage.setItem(`goals_${activePortfolioId}`, JSON.stringify(goals)); }, [goals, activePortfolioId, isDataLoaded]);

  // --- CALCULATIONS ---
  const holdings = useMemo(() => calculateHoldings(transactions, prices, targets), [transactions, prices, targets]);
  const chartData = useMemo(() => calculatePortfolioHistory(transactions, prices), [transactions, prices]);
  const investedAmount = transactions.reduce((sum, t) => {
    if (t.type === TransactionType.DEPOSIT) return sum + (t.price || 0);
    if (t.type === TransactionType.WITHDRAW) return sum - (t.price || 0);
    return sum;
  }, 0);
  const cashBalance = useMemo(() => {
    let balance = 0;
    transactions.forEach(t => {
      if (t.type === TransactionType.DEPOSIT) balance += (t.price || 0);
      if (t.type === TransactionType.WITHDRAW) balance -= (t.price || 0);
      if (t.type === TransactionType.BUY) balance -= (t.price! * t.shares!) + (t.fee || 0);
      if (t.type === TransactionType.SELL) balance += (t.price! * t.shares!) - (t.fee || 0);
      if (t.type === TransactionType.DIVIDEND) balance += (t.price || 0);
    });
    return balance;
  }, [transactions]);
  const portfolioValue = holdings.reduce((sum, h) => sum + h.marketValue, 0);
  const totalNetWorth = portfolioValue + cashBalance;
  const activeGoal = useMemo(() => goals.find(g => !g.endDate) || { targetAmount: 100000 } as FinancialGoal, [goals]);

  // --- HANDLERS ---
  const handleOpenAddModal = () => { setEditingTransaction(null); setIsAddModalOpen(true); };
  const handleOpenEditModal = (tx: Transaction) => { setEditingTransaction(tx); setIsAddModalOpen(true); };

  const handleSaveTransaction = (tx: Transaction) => {
    return new Promise<void>((resolve) => {
      if (editingTransaction) setTransactions(prev => prev.map(t => t.id === tx.id ? tx : t));
      else setTransactions(prev => [...prev, tx]);

      // Update price reference
      if ((tx.type === TransactionType.BUY || tx.type === TransactionType.SELL) && tx.symbol && tx.price) {
        setPrices(prev => ({...prev, [tx.symbol!]: tx.price!}));
      }

      // Update Last Used Date Persistence
      setLastTxDate(tx.date);
      localStorage.setItem('lastTxDate', tx.date);

      setIsAddModalOpen(false); 
      setEditingTransaction(null); 
      resolve();
    });
  };

  const handleUpdatePrice = (symbol: string, newPrice: number) => setPrices(prev => ({ ...prev, [symbol]: newPrice }));
  const handleUpdateTarget = (symbol: string, target: number) => setTargets(prev => ({ ...prev, [symbol]: target }));

  const handleDeleteTransaction = (id: string) => {
    setTransactions(prev => prev.filter(t => t.id !== id));
    if (editingTransaction && editingTransaction.id === id) { setIsAddModalOpen(false); setEditingTransaction(null); }
  };
  const handleRequestDelete = (id: string) => {
      setConfirmConfig({ isOpen: true, title: 'Delete Transaction', message: 'Permanently remove this record?', onConfirm: () => { handleDeleteTransaction(id); setConfirmConfig(prev => ({ ...prev, isOpen: false })); } });
  };
  const handleImportTransactions = (importedTxs: Transaction[]) => {
      setTransactions(prev => {
          const currentMap = new Map(prev.map(t => [t.id, t]));
          importedTxs.forEach(t => { currentMap.set(t.id, t); });
          return Array.from(currentMap.values());
      });
  };

  // Portfolios
  const handleCreatePortfolio = (name: string) => { const newId = generateId(); setPortfolios([...portfolios, { id: newId, name }]); setActivePortfolioId(newId); };
  const handleRenamePortfolio = (id: string, newName: string) => { setPortfolios(prev => prev.map(p => p.id === id ? { ...p, name: newName } : p)); };
  const handleDeletePortfolio = (id: string) => {
    if (portfolios.length <= 1) { alert("Cannot delete last portfolio"); return; }
    setConfirmConfig({
        isOpen: true, title: 'Delete Portfolio', message: 'Delete entire portfolio and all data?', 
        onConfirm: () => {
             localStorage.removeItem(`transactions_${id}`); localStorage.removeItem(`prices_${id}`); localStorage.removeItem(`goals_${id}`); localStorage.removeItem(`targets_${id}`);
             const newPortfolios = portfolios.filter(p => p.id !== id); setPortfolios(newPortfolios);
             if (activePortfolioId === id) setActivePortfolioId(newPortfolios[0].id);
             setConfirmConfig(prev => ({ ...prev, isOpen: false }));
        }
    });
  };

  // Goals
  const handleSetNewGoal = (targetAmount: number, notes: string) => {
    const now = new Date().toISOString();
    setGoals(prev => [...prev.map(g => !g.endDate ? { ...g, endDate: now, isAchieved: totalNetWorth >= g.targetAmount } : g), { id: generateId(), targetAmount, startDate: now, isAchieved: false, notes }]);
  };
  const handleEditGoal = (updatedGoal: FinancialGoal) => setGoals(prev => prev.map(g => g.id === updatedGoal.id ? updatedGoal : g));
  const handleDeleteGoal = (id: string) => setGoals(prev => prev.filter(g => g.id !== id));

  return (
    <Layout 
      activeTab={activeTab} setActiveTab={setActiveTab} onOpenAddModal={handleOpenAddModal}
      portfolios={portfolios} activePortfolioId={activePortfolioId} onSwitchPortfolio={setActivePortfolioId}
      onCreatePortfolio={handleCreatePortfolio} onRenamePortfolio={handleRenamePortfolio} onDeletePortfolio={handleDeletePortfolio}
    >
      <div key={activePortfolioId} className="h-full">
        {activeTab === 'dashboard' && <Dashboard isLoading={isLoading} holdings={holdings} transactions={transactions} financialGoal={activeGoal.targetAmount} onOpenGoalModal={() => setIsGoalModalOpen(true)} investedAmount={investedAmount} cashBalance={cashBalance} portfolioValue={portfolioValue} chartData={chartData} />}
        {activeTab === 'holdings' && <Holdings isLoading={isLoading} holdings={holdings} transactions={transactions} onUpdatePrice={handleUpdatePrice} onUpdateTarget={handleUpdateTarget} />}
        {activeTab === 'history' && <History isLoading={isLoading} transactions={transactions} onDelete={handleRequestDelete} onEdit={handleOpenEditModal} onAdd={handleOpenAddModal} onImport={handleImportTransactions} />}
        {activeTab === 'reports' && <Reports isLoading={isLoading} transactions={transactions} currentPortfolioValue={portfolioValue + cashBalance} chartData={chartData} />}
      </div>

      {isAddModalOpen && (
        <div className="fixed inset-0 z-50 flex items-end sm:items-center justify-center sm:p-4">
          <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-sm animate-fade-in" onClick={() => setIsAddModalOpen(false)}></div>
          <div className="relative bg-white dark:bg-slate-900 w-full max-w-2xl rounded-t-3xl sm:rounded-3xl shadow-2xl overflow-hidden animate-slide-up flex flex-col max-h-[90dvh]">
            <AddTransactionForm 
              onClose={() => setIsAddModalOpen(false)} 
              onSave={handleSaveTransaction} 
              onDelete={handleRequestDelete} 
              cashBalance={cashBalance} 
              holdings={holdings} 
              prices={prices} 
              transactions={transactions} 
              initialData={editingTransaction}
              defaultDate={lastTxDate}
            />
          </div>
        </div>
      )}

      <GoalModal isOpen={isGoalModalOpen} onClose={() => setIsGoalModalOpen(false)} goals={goals} currentNetWorth={totalNetWorth} onSetGoal={handleSetNewGoal} onEditGoal={handleEditGoal} onDeleteGoal={handleDeleteGoal} />

      {confirmConfig.isOpen && (
        <div className="fixed inset-0 z-[70] flex items-center justify-center p-4 animate-fade-in">
          <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-sm" onClick={() => setConfirmConfig(prev => ({ ...prev, isOpen: false }))}></div>
          <div className="relative bg-white dark:bg-slate-900 rounded-2xl shadow-2xl w-full max-w-sm overflow-hidden animate-zoom-in p-6 text-center">
              <Trash2 size={40} className="mx-auto text-rose-500 mb-4" />
              <h3 className="text-lg font-bold text-slate-900 dark:text-white mb-2">{confirmConfig.title}</h3>
              <p className="text-sm text-slate-500 dark:text-slate-400 mb-6">{confirmConfig.message}</p>
              <div className="flex space-x-3">
                <button onClick={() => setConfirmConfig(prev => ({ ...prev, isOpen: false }))} className="flex-1 py-3 rounded-xl font-bold bg-slate-100 dark:bg-slate-800 text-slate-600 dark:text-slate-400">Cancel</button>
                <button onClick={confirmConfig.onConfirm} className="flex-1 py-3 rounded-xl font-bold bg-rose-600 text-white shadow-lg shadow-rose-600/20">Delete</button>
              </div>
          </div>
        </div>
      )}
    </Layout>
  );
};

interface AddTransactionFormProps {
  onClose: () => void;
  onSave: (t: Transaction) => Promise<void>;
  onDelete?: (id: string) => void;
  cashBalance: number;
  holdings: Holding[];
  prices: Record<string, number>;
  transactions: Transaction[];
  initialData: Transaction | null;
  defaultDate: string;
}

const AddTransactionForm: React.FC<AddTransactionFormProps> = ({ onClose, onSave, onDelete, cashBalance, holdings, prices, transactions, initialData, defaultDate }) => {
  const [step, setStep] = useState<'input' | 'review'>('input');

  const [type, setType] = useState<TransactionType>(TransactionType.BUY);
  const [date, setDate] = useState(defaultDate);
  const [symbol, setSymbol] = useState('');
  const [shares, setShares] = useState('');
  const [price, setPrice] = useState(''); // Price per share
  const [totalAmount, setTotalAmount] = useState(''); // Total transaction value
  const [fee, setFee] = useState('');
  const [assetClass, setAssetClass] = useState<AssetClass>(AssetClass.STOCK);
  const [exchangeRate, setExchangeRate] = useState(''); 
  const [notes, setNotes] = useState('');
  const [error, setError] = useState<string | null>(null);
  const [isSaving, setIsSaving] = useState(false);

  const [showSuggestions, setShowSuggestions] = useState(false);
  const wrapperRef = useRef<HTMLDivElement>(null);
  const notesRef = useRef<HTMLTextAreaElement>(null);

  // Validation logic helpers
  const needsSymbol = [TransactionType.BUY, TransactionType.SELL, TransactionType.DIVIDEND, TransactionType.SPLIT].includes(type);
  const needsShares = [TransactionType.BUY, TransactionType.SELL, TransactionType.SPLIT].includes(type);
  const needsPrice = type !== TransactionType.SPLIT;

  // FX Rate is relevant for: Deposits, Withdrawals, and Dividends (Foreign income)
  const hasExchangeRate = type === TransactionType.DEPOSIT || type === TransactionType.WITHDRAW || type === TransactionType.DIVIDEND;
  const isFunding = type === TransactionType.DEPOSIT || type === TransactionType.WITHDRAW;

  // Effects (Initialization, Auto-fill, Calculation)
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => { if (wrapperRef.current && !wrapperRef.current.contains(event.target as Node)) setShowSuggestions(false); };
    document.addEventListener("mousedown", handleClickOutside); return () => document.removeEventListener("mousedown", handleClickOutside);
  }, []);

  useEffect(() => {
    if (initialData) {
      setType(initialData.type); setDate(initialData.date); setSymbol(initialData.symbol || '');
      setShares(initialData.shares?.toString() || ''); setPrice(initialData.price?.toString() || '');
      setFee(initialData.fee?.toString() || ''); setAssetClass(initialData.assetClass || AssetClass.STOCK);
      setExchangeRate(initialData.exchangeRate?.toString() || ''); setNotes(initialData.notes || '');
      if (initialData.shares && initialData.price && (initialData.type === TransactionType.BUY || initialData.type === TransactionType.SELL)) {
         setTotalAmount((initialData.shares * initialData.price).toFixed(2));
      } else if (initialData.price) setTotalAmount(initialData.price.toString());
    }
  }, [initialData]);

  // Auto-fill price from holdings or market data when symbol changes (and no data set yet)
  useEffect(() => {
    if (!initialData && symbol && !price && !totalAmount) {
       const h = holdings.find(h => h.symbol === symbol.toUpperCase());
       if (h) { setAssetClass(h.assetClass); if (h.currentPrice > 0) setPrice(h.currentPrice.toString()); }
       else { const kp = prices[symbol.toUpperCase()]; if (kp) setPrice(kp.toString()); }
    }
  }, [symbol]);

  // --- Real-time Calculation Handlers ---
  const handleSharesChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const val = e.target.value;
    setShares(val);
    const s = parseFloat(val);
    const p = parseFloat(price);
    if (!isNaN(s) && !isNaN(p)) {
        setTotalAmount((s * p).toFixed(2));
    }
  };

  const handlePriceChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const val = e.target.value;
    setPrice(val);
    const p = parseFloat(val);
    const s = parseFloat(shares);
    // If we have shares, calc total
    if (!isNaN(p) && !isNaN(s)) {
        setTotalAmount((s * p).toFixed(2));
    } 
    // If we have total but no shares, calc shares? (Inverse flow)
    else if (!isNaN(p) && totalAmount && !shares) {
        const t = parseFloat(totalAmount);
        if (!isNaN(t) && p !== 0) setShares((t/p).toFixed(4));
    }
  };

  const handleTotalChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const val = e.target.value;
    setTotalAmount(val);
    const t = parseFloat(val);
    const p = parseFloat(price);
    // Standard: Total / Price = Shares
    if (!isNaN(t) && !isNaN(p) && p !== 0) {
        setShares((t / p).toFixed(4));
    }
  };

  // --- Auto-complete Logic ---
  const allSymbols = useMemo(() => {
    const fromHoldings = holdings.map(h => h.symbol);
    const fromHistory = transactions.map(t => t.symbol).filter(s => s) as string[];
    // Unique combined list
    return Array.from(new Set([...fromHoldings, ...fromHistory, ...POPULAR_SYMBOLS])).sort();
  }, [holdings, transactions]);

  const suggestions = useMemo(() => {
    if (!symbol) return [];
    const inputUpper = symbol.toUpperCase();
    return allSymbols.filter(s => s.includes(inputUpper)).slice(0, 6);
  }, [symbol, allSymbols]);

  // Max Button Handlers
  const handleMax = () => {
    const p = parseFloat(price);
    if (type === TransactionType.BUY) {
        if (p > 0) {
            const maxAmt = Math.max(0, cashBalance);
            setTotalAmount(maxAmt.toFixed(2));
            setShares((maxAmt / p).toFixed(4));
        } else {
            setTotalAmount(cashBalance.toFixed(2));
        }
    } else if (type === TransactionType.SELL) {
        const holding = holdings.find(h => h.symbol === symbol.toUpperCase());
        if (holding) {
            setShares(holding.shares.toString());
            if (p > 0) setTotalAmount((holding.shares * p).toFixed(2));
        }
    }
  };

  // IMPACT CALCULATIONS FOR SUMMARY
  const currentCashImpact = useMemo(() => {
     const qty = parseFloat(shares) || 0;
     const unitPrice = parseFloat(price) || 0;
     const feeVal = parseFloat(fee) || 0;
     const amt = parseFloat(totalAmount) || 0;

     if (type === TransactionType.BUY) return -((qty * unitPrice) + feeVal);
     if (type === TransactionType.SELL) return ((qty * unitPrice) - feeVal);
     if (type === TransactionType.DEPOSIT) return amt;
     if (type === TransactionType.WITHDRAW) return -amt;
     if (type === TransactionType.DIVIDEND) return amt;
     return 0;
  }, [type, shares, price, fee, totalAmount]);

  const originalCashImpact = useMemo(() => {
    if (!initialData) return 0;
    const qty = initialData.shares || 0;
    const unitPrice = initialData.price || 0;
    const feeVal = initialData.fee || 0;

    if (initialData.type === TransactionType.BUY) return -((qty * unitPrice) + feeVal);
    if (initialData.type === TransactionType.SELL) return ((qty * unitPrice) - feeVal);
    if (initialData.type === TransactionType.DEPOSIT) return unitPrice; 
    if (initialData.type === TransactionType.WITHDRAW) return -unitPrice;
    if (initialData.type === TransactionType.DIVIDEND) return unitPrice;
    return 0;
  }, [initialData]);

  const projectedCashBalance = cashBalance - originalCashImpact + currentCashImpact;
  const totalNetWorth = useMemo(() => {
     const invested = holdings.reduce((sum, h) => sum + h.marketValue, 0);
     return invested + cashBalance;
  }, [holdings, cashBalance]);

  const feePercentage = useMemo(() => {
     const feeVal = parseFloat(fee) || 0;
     const totalVal = parseFloat(totalAmount) || 0;
     if (feeVal > 0 && totalVal > 0) {
        return (feeVal / totalVal) * 100;
     }
     return 0;
  }, [fee, totalAmount]);

  // Validation
  const validate = () => {
    if (needsSymbol && !symbol) return "Asset Symbol is required.";
    if (!needsSymbol && !totalAmount) return "Amount is required.";
    if (type === TransactionType.SELL) {
        const holding = holdings.find(h => h.symbol === symbol.toUpperCase());
        const currentShares = holding ? holding.shares : 0;
        const originalShares = (initialData && initialData.type === TransactionType.SELL && initialData.symbol === symbol) ? (initialData.shares || 0) : 0;
        const available = currentShares + originalShares;
        if ((parseFloat(shares) || 0) > available) return `Insufficient shares. Owned: ${formatNumber(available)}. Selling: ${shares}.`;
    }
    if ((type === TransactionType.WITHDRAW || type === TransactionType.BUY) && projectedCashBalance < 0) {
        return "Insufficient funds. Transaction exceeds cash balance.";
    }
    return null;
  };

  const handleReview = (e: React.FormEvent) => {
      e.preventDefault();
      const errMsg = validate();
      if (errMsg) return setError(errMsg);
      setError(null);
      setStep('review');
  };

  const handleFinalSubmit = async () => {
    setIsSaving(true);
    await onSave({
      id: initialData ? initialData.id : generateId(),
      date, type, symbol: needsSymbol ? symbol.toUpperCase() : undefined,
      shares: needsShares ? parseFloat(shares) : undefined,
      // For types that don't need shares (Deposit, Withdraw, Dividend), use the total amount as price
      price: type === TransactionType.SPLIT ? 0 : (needsShares ? parseFloat(price) : parseFloat(totalAmount)),
      fee: (fee && (type === TransactionType.BUY || type === TransactionType.SELL)) ? parseFloat(fee) : undefined,
      assetClass: !needsSymbol ? AssetClass.CASH : assetClass,
      exchangeRate: exchangeRate ? parseFloat(exchangeRate) : 1, notes: notes || undefined
    });
    setIsSaving(false);
  };

  const getTypeConfig = (t: TransactionType) => {
    switch (t) {
        case TransactionType.BUY: return { color: 'emerald', icon: <TrendingUp size={16} /> }; // Green
        case TransactionType.DEPOSIT: return { color: 'orange', icon: <Wallet size={16} /> }; // Orange
        case TransactionType.SELL: return { color: 'rose', icon: <TrendingDown size={16} /> }; // Red
        case TransactionType.WITHDRAW: return { color: 'blue', icon: <Banknote size={16} /> }; // Blue
        case TransactionType.DIVIDEND: return { color: 'teal', icon: <DollarSign size={16} /> }; // Teal
        case TransactionType.SPLIT: return { color: 'purple', icon: <Split size={16} /> }; // Purple
        default: return { color: 'slate', icon: <CheckCircle2 size={16} /> };
    }
  }
  const theme = getTypeConfig(type);

  // SUMMARY BAR
  const summaryBox = useMemo(() => {
     const absImpact = Math.abs(currentCashImpact);
     const isPositiveFlow = currentCashImpact >= 0;
     const portfolioPercent = (totalNetWorth > 0) ? (absImpact / totalNetWorth) * 100 : 0;
     const impactColor = isPositiveFlow ? 'bg-emerald-500' : 'bg-rose-500';
     const impactTextColor = isPositiveFlow ? 'text-emerald-600' : 'text-rose-600';

     return (
         <div className="bg-slate-100 dark:bg-slate-800/80 rounded-2xl p-5 border border-slate-200 dark:border-slate-700 mt-4">
             <div className="flex justify-between items-start mb-4">
                 <div>
                    <p className="text-xs font-bold text-slate-500 uppercase tracking-wider">Net Cash Impact</p>
                    <h3 className={`text-2xl font-bold font-display ${impactTextColor}`}>
                        {isPositiveFlow ? '+' : '-'}{formatCurrency(absImpact)}
                    </h3>
                    <p className="text-[10px] text-slate-400 mt-1 font-medium flex items-center">
                        <Percent size={10} className="mr-1"/>
                        ≈ {portfolioPercent.toFixed(1)}% of Total Portfolio
                    </p>
                 </div>
                 <div className="text-right">
                    <p className="text-xs font-bold text-slate-500 uppercase tracking-wider">Projected Cash</p>
                    <p className="text-xl font-bold font-mono text-slate-800 dark:text-slate-200">{formatCurrency(projectedCashBalance)}</p>
                 </div>
             </div>

             {/* Progress Bar */}
             <div className="relative h-2.5 bg-slate-200 dark:bg-slate-700 rounded-full overflow-hidden">
                 <div className="absolute top-0 left-0 h-full bg-slate-400 dark:bg-slate-500 transition-all" style={{ width: '100%' }}></div>
                 {projectedCashBalance < cashBalance && (
                    <div className={`absolute top-0 right-0 h-full ${impactColor} transition-all animate-pulse`} style={{ width: `${((cashBalance - projectedCashBalance)/cashBalance)*100}%` }}></div>
                 )}
                 {projectedCashBalance > cashBalance && (
                     <div className={`absolute top-0 left-0 h-full ${impactColor} transition-all`} style={{ width: '100%' }}></div>
                 )}
             </div>
             <div className="flex justify-between text-[10px] text-slate-400 mt-1.5 font-bold uppercase">
                 <span>Before: {formatCurrency(cashBalance)}</span>
                 <span>After: {formatCurrency(projectedCashBalance)}</span>
             </div>
         </div>
     )
  }, [currentCashImpact, projectedCashBalance, cashBalance, totalNetWorth]);

  const handleNoteChange = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
     setNotes(e.target.value);
     e.target.style.height = 'auto';
     e.target.style.height = `${e.target.scrollHeight}px`;
  }

  // RENDER: REVIEW STEP
  if (step === 'review') {
      return (
          <div className="flex flex-col h-full bg-white dark:bg-slate-900">
             <div className="p-6 text-center border-b border-slate-100 dark:border-slate-800">
                <div className={`w-16 h-16 mx-auto rounded-full bg-${theme.color}-100 dark:bg-${theme.color}-900/30 text-${theme.color}-600 dark:text-${theme.color}-400 flex items-center justify-center mb-4 shadow-lg shadow-${theme.color}-500/20`}>
                   {theme.icon}
                </div>
                <h3 className="text-xl font-display font-bold text-slate-900 dark:text-white">Review Transaction</h3>
                <p className="text-sm text-slate-500">Please confirm details before saving.</p>
             </div>

             <div className="flex-1 overflow-y-auto p-6 space-y-6">
                 {/* Details Card */}
                 <div className="bg-slate-50 dark:bg-slate-800/50 rounded-2xl p-5 border border-slate-200 dark:border-slate-700 space-y-4">
                     <div className="flex justify-between border-b border-slate-200 dark:border-slate-700 pb-2">
                        <span className="text-sm text-slate-500">Date</span>
                        <span className="text-sm font-bold text-slate-900 dark:text-white">{date}</span>
                     </div>
                     <div className="flex justify-between border-b border-slate-200 dark:border-slate-700 pb-2">
                        <span className="text-sm text-slate-500">Type</span>
                        <span className={`text-sm font-bold uppercase text-${theme.color}-600`}>{type}</span>
                     </div>
                     {needsSymbol && (
                         <div className="flex justify-between border-b border-slate-200 dark:border-slate-700 pb-2">
                            <span className="text-sm text-slate-500">Asset</span>
                            <span className="text-sm font-bold text-slate-900 dark:text-white">{symbol} <span className="text-xs text-slate-400 font-normal">({assetClass})</span></span>
                         </div>
                     )}
                     <div className="flex justify-between border-b border-slate-200 dark:border-slate-700 pb-2">
                        <span className="text-sm text-slate-500">Total Amount</span>
                        <span className="text-lg font-bold text-slate-900 dark:text-white">{formatCurrency(parseFloat(totalAmount))}</span>
                     </div>
                     {needsShares && (
                        <div className="flex justify-between pt-1">
                            <span className="text-xs text-slate-400">Details</span>
                            <span className="text-xs text-slate-500">{shares} units @ {formatCurrency(parseFloat(price))}</span>
                        </div>
                     )}
                 </div>

                 {projectedCashBalance < 0 && (
                     <div className="bg-rose-50 text-rose-600 p-4 rounded-xl text-sm font-bold flex items-center">
                         <AlertCircle size={20} className="mr-3 shrink-0" />
                         WARNING: This transaction will result in a negative cash balance.
                     </div>
                 )}
             </div>

             <div className="p-6 border-t border-slate-100 dark:border-slate-800 flex gap-4">
                 <button onClick={() => setStep('input')} className="flex-1 py-3 rounded-xl font-bold bg-slate-100 dark:bg-slate-800 text-slate-600 dark:text-slate-300 hover:bg-slate-200 dark:hover:bg-slate-700 transition-colors">
                    Back to Edit
                 </button>
                 <button onClick={handleFinalSubmit} disabled={isSaving} className={`flex-1 py-3 rounded-xl font-bold text-white shadow-xl flex items-center justify-center space-x-2 bg-${theme.color}-600 hover:bg-${theme.color}-700 transition-all`}>
                    {isSaving ? <Spinner className="text-white" /> : (
                        <>
                            <CheckCircle2 size={18} />
                            <span>Confirm & Save</span>
                        </>
                    )}
                 </button>
             </div>
          </div>
      )
  }

  // RENDER: INPUT STEP
  return (
    <>
      <div className="shrink-0 px-6 py-4 border-b border-slate-100 dark:border-slate-800 flex justify-between items-center bg-white dark:bg-slate-900">
          <h3 className="text-lg font-display font-bold text-slate-900 dark:text-white">{initialData ? 'Edit Transaction' : 'New Transaction'}</h3>
          <button onClick={onClose} className="bg-slate-100 dark:bg-slate-800 p-2 rounded-full text-slate-500 hover:text-slate-800 dark:hover:text-white transition-colors"><X size={20} /></button>
      </div>

      <form onSubmit={handleReview} className="flex-1 overflow-y-auto min-h-0 p-6 custom-scrollbar bg-white dark:bg-slate-900">

        {/* 1. Transaction Type Selector with Icons */}
        <div className="mb-6">
           <label className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-3 block">Transaction Type</label>
           <div className="grid grid-cols-3 sm:grid-cols-6 gap-2">
              {[TransactionType.BUY, TransactionType.SELL, TransactionType.DEPOSIT, TransactionType.WITHDRAW, TransactionType.DIVIDEND, TransactionType.SPLIT].map(t => {
                 const isActive = type === t;
                 const config = getTypeConfig(t);
                 return (
                   <button
                      key={t} type="button" onClick={() => setType(t)}
                      className={`flex flex-col items-center justify-center py-2.5 px-1 rounded-xl text-[10px] sm:text-xs font-bold transition-all border ${
                         isActive 
                         ? `border-transparent bg-${config.color}-500 text-white shadow-md shadow-${config.color}-500/20 transform scale-105` 
                         : 'bg-white dark:bg-slate-800 border-slate-200 dark:border-slate-700 text-slate-500 dark:text-slate-400 hover:border-slate-300 dark:hover:border-slate-600 hover:bg-slate-50'
                      }`}
                   >
                      <div className="mb-1">{config.icon}</div>
                      {t}
                   </button>
                 )
              })}
           </div>
        </div>

        <div className="grid md:grid-cols-2 gap-8">
            {/* LEFT COLUMN: DETAILS */}
            <div className="space-y-5">
                <div className="flex items-center space-x-2 text-slate-800 dark:text-slate-200 border-b border-slate-100 dark:border-slate-800 pb-2">
                    <FileText size={18} />
                    <h4 className="font-bold text-sm uppercase tracking-wide">Transaction Details</h4>
                </div>

                <div>
                   <label className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-1.5 block">Date</label>
                   <div className="relative">
                      <Calendar className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={16} />
                      <input type="date" value={date} onChange={e => setDate(e.target.value)} className="w-full pl-10 pr-4 py-2.5 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl font-medium text-sm focus:ring-2 focus:ring-blue-500 outline-none transition-all" />
                   </div>
                </div>

                {needsSymbol && (
                    <div className="relative z-20" ref={wrapperRef}>
                        <label className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-1.5 block">Asset Symbol</label>
                        <div className="relative group">
                            <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400 group-focus-within:text-blue-500 transition-colors" size={18} />
                            <input 
                               type="text" placeholder="e.g. AAPL" value={symbol} 
                               onChange={e => { setSymbol(e.target.value); setShowSuggestions(true); }}
                               onFocus={() => setShowSuggestions(true)}
                               className="w-full pl-10 pr-4 py-3 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl text-lg font-bold uppercase tracking-wide focus:ring-2 focus:ring-blue-500 focus:bg-white dark:focus:bg-slate-800 outline-none transition-all"
                            />
                             {showSuggestions && suggestions.length > 0 && (
                                <div className="absolute top-full left-0 right-0 mt-2 bg-white dark:bg-slate-800 rounded-xl shadow-xl border border-slate-100 dark:border-slate-700 overflow-hidden z-50 animate-fade-in max-h-60 overflow-y-auto custom-scrollbar">
                                    <div className="px-3 py-2 bg-slate-50 dark:bg-slate-900/50 text-[10px] uppercase font-bold text-slate-400">Suggestions</div>
                                    {suggestions.map(s => (
                                        <div key={s} onMouseDown={(e) => { e.preventDefault(); setSymbol(s); setShowSuggestions(false); }} className="px-4 py-3 hover:bg-blue-50 dark:hover:bg-blue-900/20 cursor-pointer font-bold text-slate-700 dark:text-slate-200 flex justify-between items-center text-sm border-b border-slate-50 dark:border-slate-700/50 last:border-0 group">
                                           <span>{s}</span>
                                           <span className="text-xs text-blue-500 font-normal opacity-0 group-hover:opacity-100 transition-opacity flex items-center">
                                              Use <ArrowRightCircle size={12} className="ml-1"/>
                                           </span>
                                        </div>
                                    ))}
                                </div>
                            )}
                        </div>
                    </div>
                 )}

                 {needsSymbol && (
                    <div>
                        <label className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-1.5 block">Asset Class</label>
                        <select value={assetClass} onChange={e => setAssetClass(e.target.value as AssetClass)} className="w-full px-4 py-2.5 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl font-medium text-sm outline-none focus:ring-2 focus:ring-blue-500 transition-all cursor-pointer">
                            {Object.values(AssetClass).filter(a => a !== AssetClass.CASH).map(a => <option key={a} value={a}>{a}</option>)}
                        </select>
                    </div>
                 )}
            </div>

            {/* RIGHT COLUMN: FINANCIALS */}
            <div className="space-y-5">
                <div className="flex items-center space-x-2 text-slate-800 dark:text-slate-200 border-b border-slate-100 dark:border-slate-800 pb-2">
                    <DollarSign size={18} />
                    <h4 className="font-bold text-sm uppercase tracking-wide">Financials</h4>
                </div>

                {/* Amount / Price Fields */}
                {(needsPrice || isFunding) && (
                   <div>
                       <label className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-1.5 flex justify-between">
                           <span>{needsShares ? 'Total Amount' : 'Amount'}</span>
                           {type === TransactionType.BUY && (
                               <button type="button" onClick={handleMax} className="text-blue-500 hover:underline text-[10px]">Use Max Cash</button>
                           )}
                       </label>
                       <div className="relative group">
                           <span className={`absolute left-4 top-1/2 -translate-y-1/2 text-xl font-bold ${type === TransactionType.SELL || type === TransactionType.WITHDRAW ? 'text-rose-500' : 'text-emerald-500'}`}>$</span>
                           <input 
                              type="number" step="any" min="0" placeholder="0.00"
                              value={totalAmount}
                              onChange={handleTotalChange}
                              className="w-full pl-9 pr-4 py-2.5 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl text-2xl font-display font-bold text-slate-900 dark:text-white focus:ring-2 focus:ring-blue-500 focus:bg-white dark:focus:bg-slate-800 outline-none transition-all"
                           />
                       </div>
                   </div>
                 )}

                 <div className="grid grid-cols-2 gap-4">
                     {needsShares && (
                        <div>
                            <label className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-1.5 flex justify-between">
                                <span>Quantity</span>
                                {type === TransactionType.SELL && (
                                   <button type="button" onClick={handleMax} className="text-rose-500 hover:underline text-[10px]">Sell All</button>
                                )}
                            </label>
                            <input 
                                type="number" step="any" 
                                placeholder="0" 
                                value={shares}
                                onChange={handleSharesChange}
                                className="w-full px-3 py-2.5 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl font-medium text-sm focus:ring-2 focus:ring-blue-500 outline-none"
                            />
                        </div>
                     )}

                     {needsPrice && needsShares && (
                        <div>
                           <label className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-1.5 block">Price / Share</label>
                           <input 
                                type="number" step="any" placeholder="0.00" value={price}
                                onChange={handlePriceChange}
                                className="w-full px-3 py-2.5 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl font-medium text-sm focus:ring-2 focus:ring-blue-500 outline-none"
                            />
                        </div>
                     )}
                 </div>

                 {(type === TransactionType.BUY || type === TransactionType.SELL) && (
                    <div>
                        <label className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-1.5 block">Fee</label>
                        <input 
                             type="number" step="any" placeholder="0.00" value={fee} onChange={e => setFee(e.target.value)} 
                             className="w-full px-4 py-2 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl text-sm outline-none focus:ring-2 focus:ring-blue-500" 
                        />
                        {feePercentage > 0 && (
                           <div className="text-[10px] text-slate-400 mt-1 flex items-center">
                              <Info size={10} className="mr-1" />
                              ≈ {feePercentage.toFixed(2)}% of total amount
                           </div>
                        )}
                    </div>
                 )}

                 {hasExchangeRate && (
                    <div>
                       <label className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-1 block">Exchange Rate</label>
                       <input 
                         type="number" step="any" min="0" placeholder="1.0" 
                         value={exchangeRate} onChange={e => setExchangeRate(e.target.value)} 
                         className="w-full px-4 py-2 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl font-medium text-sm outline-none focus:ring-2 focus:ring-blue-500" 
                       />
                    </div>
                 )}
            </div>
        </div>

        {/* SUMMARY SECTION */}
        {summaryBox}

        {/* Notes Collapsible */}
        <details className="group mt-4" open={!!notes}>
            <summary className="flex items-center text-xs font-bold text-slate-400 uppercase tracking-wider cursor-pointer hover:text-blue-500 transition-colors w-fit">
               <span className="mr-2">Add Notes</span>
               <ChevronDown size={14} className="group-open:rotate-180 transition-transform" />
            </summary>
            <div className="mt-2 animate-slide-up">
                 <textarea 
                   ref={notesRef}
                   rows={2} 
                   placeholder="E.g. Monthly DCA, Rebalancing..." 
                   value={notes} 
                   onChange={handleNoteChange} 
                   className="w-full px-4 py-2 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl text-sm outline-none resize-none transition-all focus:border-blue-400 overflow-hidden min-h-[50px]" 
                 />
            </div>
        </details>

      </form>

      {/* 6. FOOTER ACTIONS */}
      <div className="px-6 py-4 border-t border-slate-100 dark:border-slate-800 bg-white dark:bg-slate-900 z-10 flex gap-3">
             {error && (
                <div className="absolute bottom-full left-0 w-full px-6 pb-2">
                    <div className="bg-rose-50 text-rose-600 px-4 py-2 rounded-xl text-sm font-bold flex items-center animate-slide-up shadow-sm border border-rose-100">
                        <AlertCircle size={16} className="mr-2" /> {error}
                    </div>
                </div>
             )}

             {initialData && onDelete && (
                 <button type="button" onClick={() => onDelete(initialData.id)} className="p-3 rounded-xl bg-rose-50 text-rose-500 hover:bg-rose-100 dark:bg-rose-900/10 dark:hover:bg-rose-900/20 transition-colors"><Trash2 size={20} /></button>
             )}
             <button 
                onClick={handleReview}
                title="Double check your details before saving"
                className={`flex-1 py-3 rounded-xl font-bold text-base text-white shadow-xl transition-all active:scale-95 flex items-center justify-center space-x-2 bg-${theme.color}-600 hover:bg-${theme.color}-700 shadow-${theme.color}-500/30`}
             >
                <span>Review & Save</span>
                <ArrowRight size={18} />
             </button>
      </div>
    </>
  );
};

export default App;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import Layout from './components/Layout';
import Dashboard from './components/Dashboard';
import Holdings from './components/Holdings';
import Reports from './components/Reports';
import History from './components/History';
import GoalModal from './components/GoalModal';
import { Transaction, TransactionType, AssetClass, Holding, Portfolio, FinancialGoal } from './types';
import { calculateHoldings, calculatePortfolioHistory, generateId, formatCurrency, formatNumber } from './utils';
import { X, Save, TrendingUp, TrendingDown, DollarSign, Wallet, Calendar, GitFork, AlertCircle, ArrowRight, Trash2, Zap, Calculator, Search, Clock, PlusCircle, MinusCircle, RefreshCcw, Split, Hash, ChevronDown, ArrowRightCircle, Globe, CheckCircle2, FileText, Banknote, Percent, Info } from 'lucide-react';
import { Spinner } from './components/LoadingSkeletons';

const POPULAR_SYMBOLS = [
  'AAPL', 'MSFT', 'GOOGL', 'AMZN', 'NVDA', 'TSLA', 'META', 'BRK.B', 'V', 'JNJ', 'WMT', 'JPM', // Tech/Blue Chip
  'VOO', 'VTI', 'QQQ', 'IVV', 'SCHD', 'JEPI', 'VUG', 'VTV', // ETFs
  'BTC', 'ETH', 'SOL', 'USDT', 'BNB', 'XRP', 'ADA' // Crypto
];

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState('dashboard');
  const [isAddModalOpen, setIsAddModalOpen] = useState(false);
  const [editingTransaction, setEditingTransaction] = useState<Transaction | null>(null);

  // Persistence for better UX
  const [lastTxDate, setLastTxDate] = useState<string>(() => localStorage.getItem('lastTxDate') || new Date().toISOString().split('T')[0]);

  // Goal Modal State
  const [isGoalModalOpen, setIsGoalModalOpen] = useState(false);

  // --- CONFIRMATION MODAL STATE ---
  const [confirmConfig, setConfirmConfig] = useState<{
    isOpen: boolean;
    title: string;
    message: string;
    onConfirm: () => void;
  }>({
    isOpen: false,
    title: '',
    message: '',
    onConfirm: () => {},
  });

  // --- PORTFOLIO MANAGEMENT STATE ---
  const [portfolios, setPortfolios] = useState<Portfolio[]>(() => {
    const saved = localStorage.getItem('portfolios');
    if (saved) return JSON.parse(saved);
    const legacyTx = localStorage.getItem('transactions');
    if (legacyTx) return [{ id: 'default', name: 'Main Portfolio' }];
    return [{ id: generateId(), name: 'My First Portfolio' }];
  });

  const [activePortfolioId, setActivePortfolioId] = useState<string>(() => {
    const saved = localStorage.getItem('activePortfolioId');
    const portfolios = JSON.parse(localStorage.getItem('portfolios') || '[]');
    if (saved && portfolios.some((p: Portfolio) => p.id === saved)) return saved;
    return portfolios.length > 0 ? portfolios[0].id : 'default';
  });

  // --- DATA STATE (Per Portfolio) - Synchronous Initialization ---
  const [transactions, setTransactions] = useState<Transaction[]>(() => {
    const key = `transactions_${activePortfolioId}`;
    const saved = localStorage.getItem(key);
    if (saved) return JSON.parse(saved);
    if (activePortfolioId === 'default') {
      const legacy = localStorage.getItem('transactions');
      if (legacy) return JSON.parse(legacy);
    }
    return [];
  });

  const [prices, setPrices] = useState<Record<string, number>>(() => {
    const key = `prices_${activePortfolioId}`;
    const saved = localStorage.getItem(key);
    if (saved) return JSON.parse(saved);
    if (activePortfolioId === 'default') {
      const legacy = localStorage.getItem('prices');
      if (legacy) return JSON.parse(legacy);
    }
    return {};
  });

  const [targets, setTargets] = useState<Record<string, number>>(() => {
    const key = `targets_${activePortfolioId}`;
    const saved = localStorage.getItem(key);
    if (saved) {
       try {
         // Fix: Handle null or invalid JSON gracefully
         const parsed = JSON.parse(saved);
         return parsed || {};
       } catch (e) {
         return {};
       }
    }
    return {};
  });

  const [goals, setGoals] = useState<FinancialGoal[]>(() => {
    const key = `goals_${activePortfolioId}`;
    const saved = localStorage.getItem(key);
    if (saved) return JSON.parse(saved);

    let legacyGoal = 100000;
    const legacyKey = `financialGoal_${activePortfolioId}`;
    const savedLegacy = localStorage.getItem(legacyKey);
    if (savedLegacy) legacyGoal = parseFloat(savedLegacy);
    else if (activePortfolioId === 'default' && localStorage.getItem('financialGoal')) legacyGoal = parseFloat(localStorage.getItem('financialGoal')!);

    return [{ id: generateId(), targetAmount: legacyGoal, startDate: new Date().toISOString(), isAchieved: false, notes: 'Initial Goal' }];
  });

  const [isDataLoaded, setIsDataLoaded] = useState(true);
  const [isLoading, setIsLoading] = useState(false);
  const isFirstMount = useRef(true);

  // --- PERSISTENCE ---
  useEffect(() => { localStorage.setItem('portfolios', JSON.stringify(portfolios)); }, [portfolios]);
  useEffect(() => { localStorage.setItem('activePortfolioId', activePortfolioId); }, [activePortfolioId]);

  useEffect(() => {
    if (isFirstMount.current) { isFirstMount.current = false; return; }
    setIsLoading(true);
    setIsDataLoaded(false);
    const loadData = () => {
        const txKey = `transactions_${activePortfolioId}`;
        const pricesKey = `prices_${activePortfolioId}`;
        const goalsKey = `goals_${activePortfolioId}`;
        const targetsKey = `targets_${activePortfolioId}`;

        const savedTx = localStorage.getItem(txKey);
        setTransactions(savedTx ? JSON.parse(savedTx) : []);

        const savedPrices = localStorage.getItem(pricesKey);
        setPrices(savedPrices ? JSON.parse(savedPrices) : {});

        const savedTargets = localStorage.getItem(targetsKey);
        // Safe parsing for targets
        try {
            const parsedTargets = savedTargets ? JSON.parse(savedTargets) : {};
            setTargets(parsedTargets || {});
        } catch {
            setTargets({});
        }

        const savedGoals = localStorage.getItem(goalsKey);
        setGoals(savedGoals ? JSON.parse(savedGoals) : []); 

        setIsDataLoaded(true);
        setTimeout(() => setIsLoading(false), 500);
    };
    requestAnimationFrame(loadData);
  }, [activePortfolioId]);

  useEffect(() => { if (isDataLoaded) localStorage.setItem(`transactions_${activePortfolioId}`, JSON.stringify(transactions)); }, [transactions, activePortfolioId, isDataLoaded]);
  useEffect(() => { if (isDataLoaded) localStorage.setItem(`prices_${activePortfolioId}`, JSON.stringify(prices)); }, [prices, activePortfolioId, isDataLoaded]);
  useEffect(() => { if (isDataLoaded) localStorage.setItem(`targets_${activePortfolioId}`, JSON.stringify(targets)); }, [targets, activePortfolioId, isDataLoaded]);
  useEffect(() => { if (isDataLoaded) localStorage.setItem(`goals_${activePortfolioId}`, JSON.stringify(goals)); }, [goals, activePortfolioId, isDataLoaded]);

  // --- CALCULATIONS ---
  const holdings = useMemo(() => calculateHoldings(transactions, prices, targets), [transactions, prices, targets]);
  const chartData = useMemo(() => calculatePortfolioHistory(transactions, prices), [transactions, prices]);
  const investedAmount = transactions.reduce((sum, t) => {
    if (t.type === TransactionType.DEPOSIT) return sum + (t.price || 0);
    if (t.type === TransactionType.WITHDRAW) return sum - (t.price || 0);
    return sum;
  }, 0);
  const cashBalance = useMemo(() => {
    let balance = 0;
    transactions.forEach(t => {
      if (t.type === TransactionType.DEPOSIT) balance += (t.price || 0);
      if (t.type === TransactionType.WITHDRAW) balance -= (t.price || 0);
      if (t.type === TransactionType.BUY) balance -= (t.price! * t.shares!) + (t.fee || 0);
      if (t.type === TransactionType.SELL) balance += (t.price! * t.shares!) - (t.fee || 0);
      if (t.type === TransactionType.DIVIDEND) balance += (t.price || 0);
    });
    return balance;
  }, [transactions]);
  const portfolioValue = holdings.reduce((sum, h) => sum + h.marketValue, 0);
  const totalNetWorth = portfolioValue + cashBalance;
  const activeGoal = useMemo(() => goals.find(g => !g.endDate) || { targetAmount: 100000 } as FinancialGoal, [goals]);

  // --- HANDLERS ---
  const handleOpenAddModal = () => { setEditingTransaction(null); setIsAddModalOpen(true); };
  const handleOpenEditModal = (tx: Transaction) => { setEditingTransaction(tx); setIsAddModalOpen(true); };

  const handleSaveTransaction = (tx: Transaction) => {
    return new Promise<void>((resolve) => {
      if (editingTransaction) setTransactions(prev => prev.map(t => t.id === tx.id ? tx : t));
      else setTransactions(prev => [...prev, tx]);

      // Update price reference
      if ((tx.type === TransactionType.BUY || tx.type === TransactionType.SELL) && tx.symbol && tx.price) {
        setPrices(prev => ({...prev, [tx.symbol!]: tx.price!}));
      }

      // Update Last Used Date Persistence
      setLastTxDate(tx.date);
      localStorage.setItem('lastTxDate', tx.date);

      setIsAddModalOpen(false); 
      setEditingTransaction(null); 
      resolve();
    });
  };

  const handleUpdatePrice = (symbol: string, newPrice: number) => setPrices(prev => ({ ...prev, [symbol]: newPrice }));
  const handleUpdateTarget = (symbol: string, target: number) => setTargets(prev => ({ ...prev, [symbol]: target }));

  const handleDeleteTransaction = (id: string) => {
    setTransactions(prev => prev.filter(t => t.id !== id));
    if (editingTransaction && editingTransaction.id === id) { setIsAddModalOpen(false); setEditingTransaction(null); }
  };
  const handleRequestDelete = (id: string) => {
      setConfirmConfig({ isOpen: true, title: 'Delete Transaction', message: 'Permanently remove this record?', onConfirm: () => { handleDeleteTransaction(id); setConfirmConfig(prev => ({ ...prev, isOpen: false })); } });
  };
  const handleImportTransactions = (importedTxs: Transaction[]) => {
      setTransactions(prev => {
          const currentMap = new Map(prev.map(t => [t.id, t]));
          importedTxs.forEach(t => { currentMap.set(t.id, t); });
          return Array.from(currentMap.values());
      });
  };

  // Portfolios
  const handleCreatePortfolio = (name: string) => { const newId = generateId(); setPortfolios([...portfolios, { id: newId, name }]); setActivePortfolioId(newId); };
  const handleRenamePortfolio = (id: string, newName: string) => { setPortfolios(prev => prev.map(p => p.id === id ? { ...p, name: newName } : p)); };
  const handleDeletePortfolio = (id: string) => {
    if (portfolios.length <= 1) { alert("Cannot delete last portfolio"); return; }
    setConfirmConfig({
        isOpen: true, title: 'Delete Portfolio', message: 'Delete entire portfolio and all data?', 
        onConfirm: () => {
             localStorage.removeItem(`transactions_${id}`); localStorage.removeItem(`prices_${id}`); localStorage.removeItem(`goals_${id}`); localStorage.removeItem(`targets_${id}`);
             const newPortfolios = portfolios.filter(p => p.id !== id); setPortfolios(newPortfolios);
             if (activePortfolioId === id) setActivePortfolioId(newPortfolios[0].id);
             setConfirmConfig(prev => ({ ...prev, isOpen: false }));
        }
    });
  };

  // Goals
  const handleSetNewGoal = (targetAmount: number, notes: string) => {
    const now = new Date().toISOString();
    setGoals(prev => [...prev.map(g => !g.endDate ? { ...g, endDate: now, isAchieved: totalNetWorth >= g.targetAmount } : g), { id: generateId(), targetAmount, startDate: now, isAchieved: false, notes }]);
  };
  const handleEditGoal = (updatedGoal: FinancialGoal) => setGoals(prev => prev.map(g => g.id === updatedGoal.id ? updatedGoal : g));
  const handleDeleteGoal = (id: string) => setGoals(prev => prev.filter(g => g.id !== id));

  return (
    <Layout 
      activeTab={activeTab} setActiveTab={setActiveTab} onOpenAddModal={handleOpenAddModal}
      portfolios={portfolios} activePortfolioId={activePortfolioId} onSwitchPortfolio={setActivePortfolioId}
      onCreatePortfolio={handleCreatePortfolio} onRenamePortfolio={handleRenamePortfolio} onDeletePortfolio={handleDeletePortfolio}
    >
      <div key={activePortfolioId} className="h-full">
        {activeTab === 'dashboard' && <Dashboard isLoading={isLoading} holdings={holdings} transactions={transactions} financialGoal={activeGoal.targetAmount} onOpenGoalModal={() => setIsGoalModalOpen(true)} investedAmount={investedAmount} cashBalance={cashBalance} portfolioValue={portfolioValue} chartData={chartData} />}
        {activeTab === 'holdings' && <Holdings isLoading={isLoading} holdings={holdings} transactions={transactions} onUpdatePrice={handleUpdatePrice} onUpdateTarget={handleUpdateTarget} />}
        {activeTab === 'history' && <History isLoading={isLoading} transactions={transactions} onDelete={handleRequestDelete} onEdit={handleOpenEditModal} onAdd={handleOpenAddModal} onImport={handleImportTransactions} />}
        {activeTab === 'reports' && <Reports isLoading={isLoading} transactions={transactions} currentPortfolioValue={portfolioValue + cashBalance} chartData={chartData} />}
      </div>

      {isAddModalOpen && (
        <div className="fixed inset-0 z-50 flex items-end sm:items-center justify-center sm:p-4">
          <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-sm animate-fade-in" onClick={() => setIsAddModalOpen(false)}></div>
          <div className="relative bg-white dark:bg-slate-900 w-full max-w-2xl rounded-t-3xl sm:rounded-3xl shadow-2xl overflow-hidden animate-slide-up flex flex-col max-h-[90dvh]">
            <AddTransactionForm 
              onClose={() => setIsAddModalOpen(false)} 
              onSave={handleSaveTransaction} 
              onDelete={handleRequestDelete} 
              cashBalance={cashBalance} 
              holdings={holdings} 
              prices={prices} 
              transactions={transactions} 
              initialData={editingTransaction}
              defaultDate={lastTxDate}
            />
          </div>
        </div>
      )}

      <GoalModal isOpen={isGoalModalOpen} onClose={() => setIsGoalModalOpen(false)} goals={goals} currentNetWorth={totalNetWorth} onSetGoal={handleSetNewGoal} onEditGoal={handleEditGoal} onDeleteGoal={handleDeleteGoal} />

      {confirmConfig.isOpen && (
        <div className="fixed inset-0 z-[70] flex items-center justify-center p-4 animate-fade-in">
          <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-sm" onClick={() => setConfirmConfig(prev => ({ ...prev, isOpen: false }))}></div>
          <div className="relative bg-white dark:bg-slate-900 rounded-2xl shadow-2xl w-full max-w-sm overflow-hidden animate-zoom-in p-6 text-center">
              <Trash2 size={40} className="mx-auto text-rose-500 mb-4" />
              <h3 className="text-lg font-bold text-slate-900 dark:text-white mb-2">{confirmConfig.title}</h3>
              <p className="text-sm text-slate-500 dark:text-slate-400 mb-6">{confirmConfig.message}</p>
              <div className="flex space-x-3">
                <button onClick={() => setConfirmConfig(prev => ({ ...prev, isOpen: false }))} className="flex-1 py-3 rounded-xl font-bold bg-slate-100 dark:bg-slate-800 text-slate-600 dark:text-slate-400">Cancel</button>
                <button onClick={confirmConfig.onConfirm} className="flex-1 py-3 rounded-xl font-bold bg-rose-600 text-white shadow-lg shadow-rose-600/20">Delete</button>
              </div>
          </div>
        </div>
      )}
    </Layout>
  );
};

interface AddTransactionFormProps {
  onClose: () => void;
  onSave: (t: Transaction) => Promise<void>;
  onDelete?: (id: string) => void;
  cashBalance: number;
  holdings: Holding[];
  prices: Record<string, number>;
  transactions: Transaction[];
  initialData: Transaction | null;
  defaultDate: string;
}

const AddTransactionForm: React.FC<AddTransactionFormProps> = ({ onClose, onSave, onDelete, cashBalance, holdings, prices, transactions, initialData, defaultDate }) => {
  const [step, setStep] = useState<'input' | 'review'>('input');

  const [type, setType] = useState<TransactionType>(TransactionType.BUY);
  const [date, setDate] = useState(defaultDate);
  const [symbol, setSymbol] = useState('');
  const [shares, setShares] = useState('');
  const [price, setPrice] = useState(''); // Price per share
  const [totalAmount, setTotalAmount] = useState(''); // Total transaction value
  const [fee, setFee] = useState('');
  const [assetClass, setAssetClass] = useState<AssetClass>(AssetClass.STOCK);
  const [exchangeRate, setExchangeRate] = useState(''); 
  const [notes, setNotes] = useState('');
  const [error, setError] = useState<string | null>(null);
  const [isSaving, setIsSaving] = useState(false);

  const [showSuggestions, setShowSuggestions] = useState(false);
  const wrapperRef = useRef<HTMLDivElement>(null);
  const notesRef = useRef<HTMLTextAreaElement>(null);

  // Validation logic helpers
  const needsSymbol = [TransactionType.BUY, TransactionType.SELL, TransactionType.DIVIDEND, TransactionType.SPLIT].includes(type);
  const needsShares = [TransactionType.BUY, TransactionType.SELL, TransactionType.SPLIT].includes(type);
  const needsPrice = type !== TransactionType.SPLIT;

  // FX Rate is relevant for: Deposits, Withdrawals, and Dividends (Foreign income)
  const hasExchangeRate = type === TransactionType.DEPOSIT || type === TransactionType.WITHDRAW || type === TransactionType.DIVIDEND;
  const isFunding = type === TransactionType.DEPOSIT || type === TransactionType.WITHDRAW;

  // Effects (Initialization, Auto-fill, Calculation)
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => { if (wrapperRef.current && !wrapperRef.current.contains(event.target as Node)) setShowSuggestions(false); };
    document.addEventListener("mousedown", handleClickOutside); return () => document.removeEventListener("mousedown", handleClickOutside);
  }, []);

  useEffect(() => {
    if (initialData) {
      setType(initialData.type); setDate(initialData.date); setSymbol(initialData.symbol || '');
      setShares(initialData.shares?.toString() || ''); setPrice(initialData.price?.toString() || '');
      setFee(initialData.fee?.toString() || ''); setAssetClass(initialData.assetClass || AssetClass.STOCK);
      setExchangeRate(initialData.exchangeRate?.toString() || ''); setNotes(initialData.notes || '');
      if (initialData.shares && initialData.price && (initialData.type === TransactionType.BUY || initialData.type === TransactionType.SELL)) {
         setTotalAmount((initialData.shares * initialData.price).toFixed(2));
      } else if (initialData.price) setTotalAmount(initialData.price.toString());
    }
  }, [initialData]);

  // Auto-fill price from holdings or market data when symbol changes (and no data set yet)
  useEffect(() => {
    if (!initialData && symbol && !price && !totalAmount) {
       const h = holdings.find(h => h.symbol === symbol.toUpperCase());
       if (h) { setAssetClass(h.assetClass); if (h.currentPrice > 0) setPrice(h.currentPrice.toString()); }
       else { const kp = prices[symbol.toUpperCase()]; if (kp) setPrice(kp.toString()); }
    }
  }, [symbol]);

  // --- Real-time Calculation Handlers ---
  const handleSharesChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const val = e.target.value;
    setShares(val);
    const s = parseFloat(val);
    const p = parseFloat(price);
    if (!isNaN(s) && !isNaN(p)) {
        setTotalAmount((s * p).toFixed(2));
    }
  };

  const handlePriceChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const val = e.target.value;
    setPrice(val);
    const p = parseFloat(val);
    const s = parseFloat(shares);
    // If we have shares, calc total
    if (!isNaN(p) && !isNaN(s)) {
        setTotalAmount((s * p).toFixed(2));
    } 
    // If we have total but no shares, calc shares? (Inverse flow)
    else if (!isNaN(p) && totalAmount && !shares) {
        const t = parseFloat(totalAmount);
        if (!isNaN(t) && p !== 0) setShares((t/p).toFixed(4));
    }
  };

  const handleTotalChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const val = e.target.value;
    setTotalAmount(val);
    const t = parseFloat(val);
    const p = parseFloat(price);
    // Standard: Total / Price = Shares
    if (!isNaN(t) && !isNaN(p) && p !== 0) {
        setShares((t / p).toFixed(4));
    }
  };

  // --- Auto-complete Logic ---
  const allSymbols = useMemo(() => {
    const fromHoldings = holdings.map(h => h.symbol);
    const fromHistory = transactions.map(t => t.symbol).filter(s => s) as string[];
    // Unique combined list
    return Array.from(new Set([...fromHoldings, ...fromHistory, ...POPULAR_SYMBOLS])).sort();
  }, [holdings, transactions]);

  const suggestions = useMemo(() => {
    if (!symbol) return [];
    const inputUpper = symbol.toUpperCase();
    return allSymbols.filter(s => s.includes(inputUpper)).slice(0, 6);
  }, [symbol, allSymbols]);

  // Max Button Handlers
  const handleMax = () => {
    const p = parseFloat(price);
    if (type === TransactionType.BUY) {
        if (p > 0) {
            const maxAmt = Math.max(0, cashBalance);
            setTotalAmount(maxAmt.toFixed(2));
            setShares((maxAmt / p).toFixed(4));
        } else {
            setTotalAmount(cashBalance.toFixed(2));
        }
    } else if (type === TransactionType.SELL) {
        const holding = holdings.find(h => h.symbol === symbol.toUpperCase());
        if (holding) {
            setShares(holding.shares.toString());
            if (p > 0) setTotalAmount((holding.shares * p).toFixed(2));
        }
    }
  };

  // IMPACT CALCULATIONS FOR SUMMARY
  const currentCashImpact = useMemo(() => {
     const qty = parseFloat(shares) || 0;
     const unitPrice = parseFloat(price) || 0;
     const feeVal = parseFloat(fee) || 0;
     const amt = parseFloat(totalAmount) || 0;

     if (type === TransactionType.BUY) return -((qty * unitPrice) + feeVal);
     if (type === TransactionType.SELL) return ((qty * unitPrice) - feeVal);
     if (type === TransactionType.DEPOSIT) return amt;
     if (type === TransactionType.WITHDRAW) return -amt;
     if (type === TransactionType.DIVIDEND) return amt;
     return 0;
  }, [type, shares, price, fee, totalAmount]);

  const originalCashImpact = useMemo(() => {
    if (!initialData) return 0;
    const qty = initialData.shares || 0;
    const unitPrice = initialData.price || 0;
    const feeVal = initialData.fee || 0;

    if (initialData.type === TransactionType.BUY) return -((qty * unitPrice) + feeVal);
    if (initialData.type === TransactionType.SELL) return ((qty * unitPrice) - feeVal);
    if (initialData.type === TransactionType.DEPOSIT) return unitPrice; 
    if (initialData.type === TransactionType.WITHDRAW) return -unitPrice;
    if (initialData.type === TransactionType.DIVIDEND) return unitPrice;
    return 0;
  }, [initialData]);

  const projectedCashBalance = cashBalance - originalCashImpact + currentCashImpact;
  const totalNetWorth = useMemo(() => {
     const invested = holdings.reduce((sum, h) => sum + h.marketValue, 0);
     return invested + cashBalance;
  }, [holdings, cashBalance]);

  const feePercentage = useMemo(() => {
     const feeVal = parseFloat(fee) || 0;
     const totalVal = parseFloat(totalAmount) || 0;
     if (feeVal > 0 && totalVal > 0) {
        return (feeVal / totalVal) * 100;
     }
     return 0;
  }, [fee, totalAmount]);

  // Validation
  const validate = () => {
    if (needsSymbol && !symbol) return "Asset Symbol is required.";
    if (!needsSymbol && !totalAmount) return "Amount is required.";
    if (type === TransactionType.SELL) {
        const holding = holdings.find(h => h.symbol === symbol.toUpperCase());
        const currentShares = holding ? holding.shares : 0;
        const originalShares = (initialData && initialData.type === TransactionType.SELL && initialData.symbol === symbol) ? (initialData.shares || 0) : 0;
        const available = currentShares + originalShares;
        if ((parseFloat(shares) || 0) > available) return `Insufficient shares. Owned: ${formatNumber(available)}. Selling: ${shares}.`;
    }
    if ((type === TransactionType.WITHDRAW || type === TransactionType.BUY) && projectedCashBalance < 0) {
        return "Insufficient funds. Transaction exceeds cash balance.";
    }
    return null;
  };

  const handleReview = (e: React.FormEvent) => {
      e.preventDefault();
      const errMsg = validate();
      if (errMsg) return setError(errMsg);
      setError(null);
      setStep('review');
  };

  const handleFinalSubmit = async () => {
    setIsSaving(true);
    await onSave({
      id: initialData ? initialData.id : generateId(),
      date, type, symbol: needsSymbol ? symbol.toUpperCase() : undefined,
      shares: needsShares ? parseFloat(shares) : undefined,
      // For types that don't need shares (Deposit, Withdraw, Dividend), use the total amount as price
      price: type === TransactionType.SPLIT ? 0 : (needsShares ? parseFloat(price) : parseFloat(totalAmount)),
      fee: (fee && (type === TransactionType.BUY || type === TransactionType.SELL)) ? parseFloat(fee) : undefined,
      assetClass: !needsSymbol ? AssetClass.CASH : assetClass,
      exchangeRate: exchangeRate ? parseFloat(exchangeRate) : 1, notes: notes || undefined
    });
    setIsSaving(false);
  };

  const getTypeConfig = (t: TransactionType) => {
    switch (t) {
        case TransactionType.BUY: return { color: 'emerald', icon: <TrendingUp size={16} /> }; // Green
        case TransactionType.DEPOSIT: return { color: 'orange', icon: <Wallet size={16} /> }; // Orange
        case TransactionType.SELL: return { color: 'rose', icon: <TrendingDown size={16} /> }; // Red
        case TransactionType.WITHDRAW: return { color: 'blue', icon: <Banknote size={16} /> }; // Blue
        case TransactionType.DIVIDEND: return { color: 'teal', icon: <DollarSign size={16} /> }; // Teal
        case TransactionType.SPLIT: return { color: 'purple', icon: <Split size={16} /> }; // Purple
        default: return { color: 'slate', icon: <CheckCircle2 size={16} /> };
    }
  }
  const theme = getTypeConfig(type);

  // SUMMARY BAR
  const summaryBox = useMemo(() => {
     const absImpact = Math.abs(currentCashImpact);
     const isPositiveFlow = currentCashImpact >= 0;
     const portfolioPercent = (totalNetWorth > 0) ? (absImpact / totalNetWorth) * 100 : 0;
     const impactColor = isPositiveFlow ? 'bg-emerald-500' : 'bg-rose-500';
     const impactTextColor = isPositiveFlow ? 'text-emerald-600' : 'text-rose-600';

     return (
         <div className="bg-slate-100 dark:bg-slate-800/80 rounded-2xl p-5 border border-slate-200 dark:border-slate-700 mt-4">
             <div className="flex justify-between items-start mb-4">
                 <div>
                    <p className="text-xs font-bold text-slate-500 uppercase tracking-wider">Net Cash Impact</p>
                    <h3 className={`text-2xl font-bold font-display ${impactTextColor}`}>
                        {isPositiveFlow ? '+' : '-'}{formatCurrency(absImpact)}
                    </h3>
                    <p className="text-[10px] text-slate-400 mt-1 font-medium flex items-center">
                        <Percent size={10} className="mr-1"/>
                        ≈ {portfolioPercent.toFixed(1)}% of Total Portfolio
                    </p>
                 </div>
                 <div className="text-right">
                    <p className="text-xs font-bold text-slate-500 uppercase tracking-wider">Projected Cash</p>
                    <p className="text-xl font-bold font-mono text-slate-800 dark:text-slate-200">{formatCurrency(projectedCashBalance)}</p>
                 </div>
             </div>

             {/* Progress Bar */}
             <div className="relative h-2.5 bg-slate-200 dark:bg-slate-700 rounded-full overflow-hidden">
                 <div className="absolute top-0 left-0 h-full bg-slate-400 dark:bg-slate-500 transition-all" style={{ width: '100%' }}></div>
                 {projectedCashBalance < cashBalance && (
                    <div className={`absolute top-0 right-0 h-full ${impactColor} transition-all animate-pulse`} style={{ width: `${((cashBalance - projectedCashBalance)/cashBalance)*100}%` }}></div>
                 )}
                 {projectedCashBalance > cashBalance && (
                     <div className={`absolute top-0 left-0 h-full ${impactColor} transition-all`} style={{ width: '100%' }}></div>
                 )}
             </div>
             <div className="flex justify-between text-[10px] text-slate-400 mt-1.5 font-bold uppercase">
                 <span>Before: {formatCurrency(cashBalance)}</span>
                 <span>After: {formatCurrency(projectedCashBalance)}</span>
             </div>
         </div>
     )
  }, [currentCashImpact, projectedCashBalance, cashBalance, totalNetWorth]);

  const handleNoteChange = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
     setNotes(e.target.value);
     e.target.style.height = 'auto';
     e.target.style.height = `${e.target.scrollHeight}px`;
  }

  // RENDER: REVIEW STEP
  if (step === 'review') {
      return (
          <div className="flex flex-col h-full bg-white dark:bg-slate-900">
             <div className="p-6 text-center border-b border-slate-100 dark:border-slate-800">
                <div className={`w-16 h-16 mx-auto rounded-full bg-${theme.color}-100 dark:bg-${theme.color}-900/30 text-${theme.color}-600 dark:text-${theme.color}-400 flex items-center justify-center mb-4 shadow-lg shadow-${theme.color}-500/20`}>
                   {theme.icon}
                </div>
                <h3 className="text-xl font-display font-bold text-slate-900 dark:text-white">Review Transaction</h3>
                <p className="text-sm text-slate-500">Please confirm details before saving.</p>
             </div>

             <div className="flex-1 overflow-y-auto p-6 space-y-6">
                 {/* Details Card */}
                 <div className="bg-slate-50 dark:bg-slate-800/50 rounded-2xl p-5 border border-slate-200 dark:border-slate-700 space-y-4">
                     <div className="flex justify-between border-b border-slate-200 dark:border-slate-700 pb-2">
                        <span className="text-sm text-slate-500">Date</span>
                        <span className="text-sm font-bold text-slate-900 dark:text-white">{date}</span>
                     </div>
                     <div className="flex justify-between border-b border-slate-200 dark:border-slate-700 pb-2">
                        <span className="text-sm text-slate-500">Type</span>
                        <span className={`text-sm font-bold uppercase text-${theme.color}-600`}>{type}</span>
                     </div>
                     {needsSymbol && (
                         <div className="flex justify-between border-b border-slate-200 dark:border-slate-700 pb-2">
                            <span className="text-sm text-slate-500">Asset</span>
                            <span className="text-sm font-bold text-slate-900 dark:text-white">{symbol} <span className="text-xs text-slate-400 font-normal">({assetClass})</span></span>
                         </div>
                     )}
                     <div className="flex justify-between border-b border-slate-200 dark:border-slate-700 pb-2">
                        <span className="text-sm text-slate-500">Total Amount</span>
                        <span className="text-lg font-bold text-slate-900 dark:text-white">{formatCurrency(parseFloat(totalAmount))}</span>
                     </div>
                     {needsShares && (
                        <div className="flex justify-between pt-1">
                            <span className="text-xs text-slate-400">Details</span>
                            <span className="text-xs text-slate-500">{shares} units @ {formatCurrency(parseFloat(price))}</span>
                        </div>
                     )}
                 </div>

                 {projectedCashBalance < 0 && (
                     <div className="bg-rose-50 text-rose-600 p-4 rounded-xl text-sm font-bold flex items-center">
                         <AlertCircle size={20} className="mr-3 shrink-0" />
                         WARNING: This transaction will result in a negative cash balance.
                     </div>
                 )}
             </div>

             <div className="p-6 border-t border-slate-100 dark:border-slate-800 flex gap-4">
                 <button onClick={() => setStep('input')} className="flex-1 py-3 rounded-xl font-bold bg-slate-100 dark:bg-slate-800 text-slate-600 dark:text-slate-300 hover:bg-slate-200 dark:hover:bg-slate-700 transition-colors">
                    Back to Edit
                 </button>
                 <button onClick={handleFinalSubmit} disabled={isSaving} className={`flex-1 py-3 rounded-xl font-bold text-white shadow-xl flex items-center justify-center space-x-2 bg-${theme.color}-600 hover:bg-${theme.color}-700 transition-all`}>
                    {isSaving ? <Spinner className="text-white" /> : (
                        <>
                            <CheckCircle2 size={18} />
                            <span>Confirm & Save</span>
                        </>
                    )}
                 </button>
             </div>
          </div>
      )
  }

  // RENDER: INPUT STEP
  return (
    <>
      <div className="shrink-0 px-6 py-4 border-b border-slate-100 dark:border-slate-800 flex justify-between items-center bg-white dark:bg-slate-900">
          <h3 className="text-lg font-display font-bold text-slate-900 dark:text-white">{initialData ? 'Edit Transaction' : 'New Transaction'}</h3>
          <button onClick={onClose} className="bg-slate-100 dark:bg-slate-800 p-2 rounded-full text-slate-500 hover:text-slate-800 dark:hover:text-white transition-colors"><X size={20} /></button>
      </div>

      <form onSubmit={handleReview} className="flex-1 overflow-y-auto min-h-0 p-6 custom-scrollbar bg-white dark:bg-slate-900">

        {/* 1. Transaction Type Selector with Icons */}
        <div className="mb-6">
           <label className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-3 block">Transaction Type</label>
           <div className="grid grid-cols-3 sm:grid-cols-6 gap-2">
              {[TransactionType.BUY, TransactionType.SELL, TransactionType.DEPOSIT, TransactionType.WITHDRAW, TransactionType.DIVIDEND, TransactionType.SPLIT].map(t => {
                 const isActive = type === t;
                 const config = getTypeConfig(t);
                 return (
                   <button
                      key={t} type="button" onClick={() => setType(t)}
                      className={`flex flex-col items-center justify-center py-2.5 px-1 rounded-xl text-[10px] sm:text-xs font-bold transition-all border ${
                         isActive 
                         ? `border-transparent bg-${config.color}-500 text-white shadow-md shadow-${config.color}-500/20 transform scale-105` 
                         : 'bg-white dark:bg-slate-800 border-slate-200 dark:border-slate-700 text-slate-500 dark:text-slate-400 hover:border-slate-300 dark:hover:border-slate-600 hover:bg-slate-50'
                      }`}
                   >
                      <div className="mb-1">{config.icon}</div>
                      {t}
                   </button>
                 )
              })}
           </div>
        </div>

        <div className="grid md:grid-cols-2 gap-8">
            {/* LEFT COLUMN: DETAILS */}
            <div className="space-y-5">
                <div className="flex items-center space-x-2 text-slate-800 dark:text-slate-200 border-b border-slate-100 dark:border-slate-800 pb-2">
                    <FileText size={18} />
                    <h4 className="font-bold text-sm uppercase tracking-wide">Transaction Details</h4>
                </div>

                <div>
                   <label className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-1.5 block">Date</label>
                   <div className="relative">
                      <Calendar className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={16} />
                      <input type="date" value={date} onChange={e => setDate(e.target.value)} className="w-full pl-10 pr-4 py-2.5 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl font-medium text-sm focus:ring-2 focus:ring-blue-500 outline-none transition-all" />
                   </div>
                </div>

                {needsSymbol && (
                    <div className="relative z-20" ref={wrapperRef}>
                        <label className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-1.5 block">Asset Symbol</label>
                        <div className="relative group">
                            <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400 group-focus-within:text-blue-500 transition-colors" size={18} />
                            <input 
                               type="text" placeholder="e.g. AAPL" value={symbol} 
                               onChange={e => { setSymbol(e.target.value); setShowSuggestions(true); }}
                               onFocus={() => setShowSuggestions(true)}
                               className="w-full pl-10 pr-4 py-3 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl text-lg font-bold uppercase tracking-wide focus:ring-2 focus:ring-blue-500 focus:bg-white dark:focus:bg-slate-800 outline-none transition-all"
                            />
                             {showSuggestions && suggestions.length > 0 && (
                                <div className="absolute top-full left-0 right-0 mt-2 bg-white dark:bg-slate-800 rounded-xl shadow-xl border border-slate-100 dark:border-slate-700 overflow-hidden z-50 animate-fade-in max-h-60 overflow-y-auto custom-scrollbar">
                                    <div className="px-3 py-2 bg-slate-50 dark:bg-slate-900/50 text-[10px] uppercase font-bold text-slate-400">Suggestions</div>
                                    {suggestions.map(s => (
                                        <div key={s} onMouseDown={(e) => { e.preventDefault(); setSymbol(s); setShowSuggestions(false); }} className="px-4 py-3 hover:bg-blue-50 dark:hover:bg-blue-900/20 cursor-pointer font-bold text-slate-700 dark:text-slate-200 flex justify-between items-center text-sm border-b border-slate-50 dark:border-slate-700/50 last:border-0 group">
                                           <span>{s}</span>
                                           <span className="text-xs text-blue-500 font-normal opacity-0 group-hover:opacity-100 transition-opacity flex items-center">
                                              Use <ArrowRightCircle size={12} className="ml-1"/>
                                           </span>
                                        </div>
                                    ))}
                                </div>
                            )}
                        </div>
                    </div>
                 )}

                 {needsSymbol && (
                    <div>
                        <label className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-1.5 block">Asset Class</label>
                        <select value={assetClass} onChange={e => setAssetClass(e.target.value as AssetClass)} className="w-full px-4 py-2.5 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl font-medium text-sm outline-none focus:ring-2 focus:ring-blue-500 transition-all cursor-pointer">
                            {Object.values(AssetClass).filter(a => a !== AssetClass.CASH).map(a => <option key={a} value={a}>{a}</option>)}
                        </select>
                    </div>
                 )}
            </div>

            {/* RIGHT COLUMN: FINANCIALS */}
            <div className="space-y-5">
                <div className="flex items-center space-x-2 text-slate-800 dark:text-slate-200 border-b border-slate-100 dark:border-slate-800 pb-2">
                    <DollarSign size={18} />
                    <h4 className="font-bold text-sm uppercase tracking-wide">Financials</h4>
                </div>

                {/* Amount / Price Fields */}
                {(needsPrice || isFunding) && (
                   <div>
                       <label className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-1.5 flex justify-between">
                           <span>{needsShares ? 'Total Amount' : 'Amount'}</span>
                           {type === TransactionType.BUY && (
                               <button type="button" onClick={handleMax} className="text-blue-500 hover:underline text-[10px]">Use Max Cash</button>
                           )}
                       </label>
                       <div className="relative group">
                           <span className={`absolute left-4 top-1/2 -translate-y-1/2 text-xl font-bold ${type === TransactionType.SELL || type === TransactionType.WITHDRAW ? 'text-rose-500' : 'text-emerald-500'}`}>$</span>
                           <input 
                              type="number" step="any" min="0" placeholder="0.00"
                              value={totalAmount}
                              onChange={handleTotalChange}
                              className="w-full pl-9 pr-4 py-2.5 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl text-2xl font-display font-bold text-slate-900 dark:text-white focus:ring-2 focus:ring-blue-500 focus:bg-white dark:focus:bg-slate-800 outline-none transition-all"
                           />
                       </div>
                   </div>
                 )}

                 <div className="grid grid-cols-2 gap-4">
                     {needsShares && (
                        <div>
                            <label className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-1.5 flex justify-between">
                                <span>Quantity</span>
                                {type === TransactionType.SELL && (
                                   <button type="button" onClick={handleMax} className="text-rose-500 hover:underline text-[10px]">Sell All</button>
                                )}
                            </label>
                            <input 
                                type="number" step="any" 
                                placeholder="0" 
                                value={shares}
                                onChange={handleSharesChange}
                                className="w-full px-3 py-2.5 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl font-medium text-sm focus:ring-2 focus:ring-blue-500 outline-none"
                            />
                        </div>
                     )}

                     {needsPrice && needsShares && (
                        <div>
                           <label className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-1.5 block">Price / Share</label>
                           <input 
                                type="number" step="any" placeholder="0.00" value={price}
                                onChange={handlePriceChange}
                                className="w-full px-3 py-2.5 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl font-medium text-sm focus:ring-2 focus:ring-blue-500 outline-none"
                            />
                        </div>
                     )}
                 </div>

                 {(type === TransactionType.BUY || type === TransactionType.SELL) && (
                    <div>
                        <label className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-1.5 block">Fee</label>
                        <input 
                             type="number" step="any" placeholder="0.00" value={fee} onChange={e => setFee(e.target.value)} 
                             className="w-full px-4 py-2 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl text-sm outline-none focus:ring-2 focus:ring-blue-500" 
                        />
                        {feePercentage > 0 && (
                           <div className="text-[10px] text-slate-400 mt-1 flex items-center">
                              <Info size={10} className="mr-1" />
                              ≈ {feePercentage.toFixed(2)}% of total amount
                           </div>
                        )}
                    </div>
                 )}

                 {hasExchangeRate && (
                    <div>
                       <label className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-1 block">Exchange Rate</label>
                       <input 
                         type="number" step="any" min="0" placeholder="1.0" 
                         value={exchangeRate} onChange={e => setExchangeRate(e.target.value)} 
                         className="w-full px-4 py-2 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl font-medium text-sm outline-none focus:ring-2 focus:ring-blue-500" 
                       />
                    </div>
                 )}
            </div>
        </div>

        {/* SUMMARY SECTION */}
        {summaryBox}

        {/* Notes Collapsible */}
        <details className="group mt-4" open={!!notes}>
            <summary className="flex items-center text-xs font-bold text-slate-400 uppercase tracking-wider cursor-pointer hover:text-blue-500 transition-colors w-fit">
               <span className="mr-2">Add Notes</span>
               <ChevronDown size={14} className="group-open:rotate-180 transition-transform" />
            </summary>
            <div className="mt-2 animate-slide-up">
                 <textarea 
                   ref={notesRef}
                   rows={2} 
                   placeholder="E.g. Monthly DCA, Rebalancing..." 
                   value={notes} 
                   onChange={handleNoteChange} 
                   className="w-full px-4 py-2 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl text-sm outline-none resize-none transition-all focus:border-blue-400 overflow-hidden min-h-[50px]" 
                 />
            </div>
        </details>

      </form>

      {/* 6. FOOTER ACTIONS */}
      <div className="px-6 py-4 border-t border-slate-100 dark:border-slate-800 bg-white dark:bg-slate-900 z-10 flex gap-3">
             {error && (
                <div className="absolute bottom-full left-0 w-full px-6 pb-2">
                    <div className="bg-rose-50 text-rose-600 px-4 py-2 rounded-xl text-sm font-bold flex items-center animate-slide-up shadow-sm border border-rose-100">
                        <AlertCircle size={16} className="mr-2" /> {error}
                    </div>
                </div>
             )}

             {initialData && onDelete && (
                 <button type="button" onClick={() => onDelete(initialData.id)} className="p-3 rounded-xl bg-rose-50 text-rose-500 hover:bg-rose-100 dark:bg-rose-900/10 dark:hover:bg-rose-900/20 transition-colors"><Trash2 size={20} /></button>
             )}
             <button 
                onClick={handleReview}
                title="Double check your details before saving"
                className={`flex-1 py-3 rounded-xl font-bold text-base text-white shadow-xl transition-all active:scale-95 flex items-center justify-center space-x-2 bg-${theme.color}-600 hover:bg-${theme.color}-700 shadow-${theme.color}-500/30`}
             >
                <span>Review & Save</span>
                <ArrowRight size={18} />
             </button>
      </div>
    </>
  );
};

export default App;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import Layout from './components/Layout';
import Dashboard from './components/Dashboard';
import Holdings from './components/Holdings';
import Reports from './components/Reports';
import History from './components/History';
import GoalModal from './components/GoalModal';
import { Transaction, TransactionType, AssetClass, Holding, Portfolio, FinancialGoal } from './types';
import { calculateHoldings, calculatePortfolioHistory, generateId, formatCurrency, formatNumber } from './utils';
import { X, Save, TrendingUp, TrendingDown, DollarSign, Wallet, Calendar, GitFork, AlertCircle, ArrowRight, Trash2, Zap, Calculator, Search, Clock, PlusCircle, MinusCircle, RefreshCcw, Split, Hash, ChevronDown, ArrowRightCircle, Globe, CheckCircle2, FileText, Banknote, Percent, Info } from 'lucide-react';
import { Spinner } from './components/LoadingSkeletons';

const POPULAR_SYMBOLS = [
  'AAPL', 'MSFT', 'GOOGL', 'AMZN', 'NVDA', 'TSLA', 'META', 'BRK.B', 'V', 'JNJ', 'WMT', 'JPM', // Tech/Blue Chip
  'VOO', 'VTI', 'QQQ', 'IVV', 'SCHD', 'JEPI', 'VUG', 'VTV', // ETFs
  'BTC', 'ETH', 'SOL', 'USDT', 'BNB', 'XRP', 'ADA' // Crypto
];

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState('dashboard');
  const [isAddModalOpen, setIsAddModalOpen] = useState(false);
  const [editingTransaction, setEditingTransaction] = useState<Partial<Transaction> | null>(null);

  // Persistence for better UX
  const [lastTxDate, setLastTxDate] = useState<string>(() => localStorage.getItem('lastTxDate') || new Date().toISOString().split('T')[0]);

  // Goal Modal State
  const [isGoalModalOpen, setIsGoalModalOpen] = useState(false);

  // --- CONFIRMATION MODAL STATE ---
  const [confirmConfig, setConfirmConfig] = useState<{
    isOpen: boolean;
    title: string;
    message: string;
    onConfirm: () => void;
  }>({
    isOpen: false,
    title: '',
    message: '',
    onConfirm: () => {},
  });

  // --- PORTFOLIO MANAGEMENT STATE ---
  const [portfolios, setPortfolios] = useState<Portfolio[]>(() => {
    const saved = localStorage.getItem('portfolios');
    if (saved) return JSON.parse(saved);
    const legacyTx = localStorage.getItem('transactions');
    if (legacyTx) return [{ id: 'default', name: 'Main Portfolio' }];
    return [{ id: generateId(), name: 'My First Portfolio' }];
  });

  const [activePortfolioId, setActivePortfolioId] = useState<string>(() => {
    const saved = localStorage.getItem('activePortfolioId');
    const portfolios = JSON.parse(localStorage.getItem('portfolios') || '[]');
    if (saved && portfolios.some((p: Portfolio) => p.id === saved)) return saved;
    return portfolios.length > 0 ? portfolios[0].id : 'default';
  });

  // --- DATA STATE (Per Portfolio) - Synchronous Initialization ---
  const [transactions, setTransactions] = useState<Transaction[]>(() => {
    const key = `transactions_${activePortfolioId}`;
    const saved = localStorage.getItem(key);
    if (saved) return JSON.parse(saved);
    if (activePortfolioId === 'default') {
      const legacy = localStorage.getItem('transactions');
      if (legacy) return JSON.parse(legacy);
    }
    return [];
  });

  const [prices, setPrices] = useState<Record<string, number>>(() => {
    const key = `prices_${activePortfolioId}`;
    const saved = localStorage.getItem(key);
    if (saved) return JSON.parse(saved);
    if (activePortfolioId === 'default') {
      const legacy = localStorage.getItem('prices');
      if (legacy) return JSON.parse(legacy);
    }
    return {};
  });

  const [targets, setTargets] = useState<Record<string, number>>(() => {
    const key = `targets_${activePortfolioId}`;
    const saved = localStorage.getItem(key);
    if (saved) {
       try {
         // Fix: Handle null or invalid JSON gracefully
         const parsed = JSON.parse(saved);
         return parsed || {};
       } catch (e) {
         return {};
       }
    }
    return {};
  });

  const [goals, setGoals] = useState<FinancialGoal[]>(() => {
    const key = `goals_${activePortfolioId}`;
    const saved = localStorage.getItem(key);
    if (saved) return JSON.parse(saved);

    let legacyGoal = 100000;
    const legacyKey = `financialGoal_${activePortfolioId}`;
    const savedLegacy = localStorage.getItem(legacyKey);
    if (savedLegacy) legacyGoal = parseFloat(savedLegacy);
    else if (activePortfolioId === 'default' && localStorage.getItem('financialGoal')) legacyGoal = parseFloat(localStorage.getItem('financialGoal')!);

    return [{ id: generateId(), targetAmount: legacyGoal, startDate: new Date().toISOString(), isAchieved: false, notes: 'Initial Goal' }];
  });

  const [isDataLoaded, setIsDataLoaded] = useState(true);
  const [isLoading, setIsLoading] = useState(false);
  const isFirstMount = useRef(true);

  // --- PERSISTENCE ---
  useEffect(() => { localStorage.setItem('portfolios', JSON.stringify(portfolios)); }, [portfolios]);
  useEffect(() => { localStorage.setItem('activePortfolioId', activePortfolioId); }, [activePortfolioId]);

  useEffect(() => {
    if (isFirstMount.current) { isFirstMount.current = false; return; }
    setIsLoading(true);
    setIsDataLoaded(false);
    const loadData = () => {
        const txKey = `transactions_${activePortfolioId}`;
        const pricesKey = `prices_${activePortfolioId}`;
        const goalsKey = `goals_${activePortfolioId}`;
        const targetsKey = `targets_${activePortfolioId}`;

        const savedTx = localStorage.getItem(txKey);
        setTransactions(savedTx ? JSON.parse(savedTx) : []);

        const savedPrices = localStorage.getItem(pricesKey);
        setPrices(savedPrices ? JSON.parse(savedPrices) : {});

        const savedTargets = localStorage.getItem(targetsKey);
        // Safe parsing for targets
        try {
            const parsedTargets = savedTargets ? JSON.parse(savedTargets) : {};
            setTargets(parsedTargets || {});
        } catch {
            setTargets({});
        }

        const savedGoals = localStorage.getItem(goalsKey);
        setGoals(savedGoals ? JSON.parse(savedGoals) : []); 

        setIsDataLoaded(true);
        setTimeout(() => setIsLoading(false), 500);
    };
    requestAnimationFrame(loadData);
  }, [activePortfolioId]);

  useEffect(() => { if (isDataLoaded) localStorage.setItem(`transactions_${activePortfolioId}`, JSON.stringify(transactions)); }, [transactions, activePortfolioId, isDataLoaded]);
  useEffect(() => { if (isDataLoaded) localStorage.setItem(`prices_${activePortfolioId}`, JSON.stringify(prices)); }, [prices, activePortfolioId, isDataLoaded]);
  useEffect(() => { if (isDataLoaded) localStorage.setItem(`targets_${activePortfolioId}`, JSON.stringify(targets)); }, [targets, activePortfolioId, isDataLoaded]);
  useEffect(() => { if (isDataLoaded) localStorage.setItem(`goals_${activePortfolioId}`, JSON.stringify(goals)); }, [goals, activePortfolioId, isDataLoaded]);

  // --- CALCULATIONS ---
  const holdings = useMemo(() => calculateHoldings(transactions, prices, targets), [transactions, prices, targets]);
  const chartData = useMemo(() => calculatePortfolioHistory(transactions, prices), [transactions, prices]);
  const investedAmount = transactions.reduce((sum, t) => {
    if (t.type === TransactionType.DEPOSIT) return sum + (t.price || 0);
    if (t.type === TransactionType.WITHDRAW) return sum - (t.price || 0);
    return sum;
  }, 0);
  const cashBalance = useMemo(() => {
    let balance = 0;
    transactions.forEach(t => {
      if (t.type === TransactionType.DEPOSIT) balance += (t.price || 0);
      if (t.type === TransactionType.WITHDRAW) balance -= (t.price || 0);
      if (t.type === TransactionType.BUY) balance -= (t.price! * t.shares!) + (t.fee || 0);
      if (t.type === TransactionType.SELL) balance += (t.price! * t.shares!) - (t.fee || 0);
      if (t.type === TransactionType.DIVIDEND) balance += (t.price || 0);
    });
    return balance;
  }, [transactions]);
  const portfolioValue = holdings.reduce((sum, h) => sum + h.marketValue, 0);
  const totalNetWorth = portfolioValue + cashBalance;
  const activeGoal = useMemo(() => goals.find(g => !g.endDate) || { targetAmount: 100000 } as FinancialGoal, [goals]);

  // --- HANDLERS ---
  const handleOpenAddModal = (initialState?: Partial<Transaction>) => { 
      setEditingTransaction(initialState || null); 
      setIsAddModalOpen(true); 
  };
  const handleOpenEditModal = (tx: Transaction) => { setEditingTransaction(tx); setIsAddModalOpen(true); };

  const handleSaveTransaction = (tx: Transaction) => {
    return new Promise<void>((resolve) => {
      if (editingTransaction && editingTransaction.id) {
         setTransactions(prev => prev.map(t => t.id === tx.id ? tx : t));
      } else {
         setTransactions(prev => [...prev, tx]);
      }

      // Update price reference
      if ((tx.type === TransactionType.BUY || tx.type === TransactionType.SELL) && tx.symbol && tx.price) {
        setPrices(prev => ({...prev, [tx.symbol!]: tx.price!}));
      }

      // Update Last Used Date Persistence
      setLastTxDate(tx.date);
      localStorage.setItem('lastTxDate', tx.date);

      setIsAddModalOpen(false); 
      setEditingTransaction(null); 
      resolve();
    });
  };

  const handleUpdatePrice = (symbol: string, newPrice: number) => setPrices(prev => ({ ...prev, [symbol]: newPrice }));
  const handleUpdateTarget = (symbol: string, target: number) => setTargets(prev => ({ ...prev, [symbol]: target }));

  const handleDeleteTransaction = (id: string) => {
    setTransactions(prev => prev.filter(t => t.id !== id));
    if (editingTransaction && editingTransaction.id === id) { setIsAddModalOpen(false); setEditingTransaction(null); }
  };
  const handleRequestDelete = (id: string) => {
      setConfirmConfig({ isOpen: true, title: 'Delete Transaction', message: 'Permanently remove this record?', onConfirm: () => { handleDeleteTransaction(id); setConfirmConfig(prev => ({ ...prev, isOpen: false })); } });
  };
  const handleImportTransactions = (importedTxs: Transaction[]) => {
      setTransactions(prev => {
          const currentMap = new Map(prev.map(t => [t.id, t]));
          importedTxs.forEach(t => { currentMap.set(t.id, t); });
          return Array.from(currentMap.values());
      });
  };

  // Portfolios
  const handleCreatePortfolio = (name: string) => { const newId = generateId(); setPortfolios([...portfolios, { id: newId, name }]); setActivePortfolioId(newId); };
  const handleRenamePortfolio = (id: string, newName: string) => { setPortfolios(prev => prev.map(p => p.id === id ? { ...p, name: newName } : p)); };
  const handleDeletePortfolio = (id: string) => {
    if (portfolios.length <= 1) { alert("Cannot delete last portfolio"); return; }
    setConfirmConfig({
        isOpen: true, title: 'Delete Portfolio', message: 'Delete entire portfolio and all data?', 
        onConfirm: () => {
             localStorage.removeItem(`transactions_${id}`); localStorage.removeItem(`prices_${id}`); localStorage.removeItem(`goals_${id}`); localStorage.removeItem(`targets_${id}`);
             const newPortfolios = portfolios.filter(p => p.id !== id); setPortfolios(newPortfolios);
             if (activePortfolioId === id) setActivePortfolioId(newPortfolios[0].id);
             setConfirmConfig(prev => ({ ...prev, isOpen: false }));
        }
    });
  };

  // Goals
  const handleSetNewGoal = (targetAmount: number, notes: string) => {
    const now = new Date().toISOString();
    setGoals(prev => [...prev.map(g => !g.endDate ? { ...g, endDate: now, isAchieved: totalNetWorth >= g.targetAmount } : g), { id: generateId(), targetAmount, startDate: now, isAchieved: false, notes }]);
  };
  const handleEditGoal = (updatedGoal: FinancialGoal) => setGoals(prev => prev.map(g => g.id === updatedGoal.id ? updatedGoal : g));
  const handleDeleteGoal = (id: string) => setGoals(prev => prev.filter(g => g.id !== id));

  return (
    <Layout 
      activeTab={activeTab} setActiveTab={setActiveTab} onOpenAddModal={() => handleOpenAddModal()}
      portfolios={portfolios} activePortfolioId={activePortfolioId} onSwitchPortfolio={setActivePortfolioId}
      onCreatePortfolio={handleCreatePortfolio} onRenamePortfolio={handleRenamePortfolio} onDeletePortfolio={handleDeletePortfolio}
    >
      <div key={activePortfolioId} className="h-full">
        {activeTab === 'dashboard' && <Dashboard isLoading={isLoading} holdings={holdings} transactions={transactions} financialGoal={activeGoal.targetAmount} onOpenGoalModal={() => setIsGoalModalOpen(true)} investedAmount={investedAmount} cashBalance={cashBalance} portfolioValue={portfolioValue} chartData={chartData} />}
        {activeTab === 'holdings' && (
            <Holdings 
                isLoading={isLoading} 
                holdings={holdings} 
                transactions={transactions} 
                cashBalance={cashBalance}
                onUpdatePrice={handleUpdatePrice} 
                onUpdateTarget={handleUpdateTarget} 
                onTrade={(symbol, type) => handleOpenAddModal({ symbol, type })}
            />
        )}
        {activeTab === 'history' && <History isLoading={isLoading} transactions={transactions} onDelete={handleRequestDelete} onEdit={handleOpenEditModal} onAdd={handleOpenAddModal} onImport={handleImportTransactions} />}
        {activeTab === 'reports' && <Reports isLoading={isLoading} transactions={transactions} currentPortfolioValue={portfolioValue + cashBalance} chartData={chartData} />}
      </div>

      {isAddModalOpen && (
        <div className="fixed inset-0 z-50 flex items-end sm:items-center justify-center sm:p-4">
          <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-sm animate-fade-in" onClick={() => setIsAddModalOpen(false)}></div>
          <div className="relative bg-white dark:bg-slate-900 w-full max-w-2xl rounded-t-3xl sm:rounded-3xl shadow-2xl overflow-hidden animate-slide-up flex flex-col max-h-[90dvh]">
            <AddTransactionForm 
              onClose={() => setIsAddModalOpen(false)} 
              onSave={handleSaveTransaction} 
              onDelete={handleRequestDelete} 
              cashBalance={cashBalance} 
              holdings={holdings} 
              prices={prices} 
              transactions={transactions} 
              initialData={editingTransaction as Transaction | null}
              defaultDate={lastTxDate}
            />
          </div>
        </div>
      )}

      <GoalModal isOpen={isGoalModalOpen} onClose={() => setIsGoalModalOpen(false)} goals={goals} currentNetWorth={totalNetWorth} onSetGoal={handleSetNewGoal} onEditGoal={handleEditGoal} onDeleteGoal={handleDeleteGoal} />

      {confirmConfig.isOpen && (
        <div className="fixed inset-0 z-[70] flex items-center justify-center p-4 animate-fade-in">
          <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-sm" onClick={() => setConfirmConfig(prev => ({ ...prev, isOpen: false }))}></div>
          <div className="relative bg-white dark:bg-slate-900 rounded-2xl shadow-2xl w-full max-w-sm overflow-hidden animate-zoom-in p-6 text-center">
              <Trash2 size={40} className="mx-auto text-rose-500 mb-4" />
              <h3 className="text-lg font-bold text-slate-900 dark:text-white mb-2">{confirmConfig.title}</h3>
              <p className="text-sm text-slate-500 dark:text-slate-400 mb-6">{confirmConfig.message}</p>
              <div className="flex space-x-3">
                <button onClick={() => setConfirmConfig(prev => ({ ...prev, isOpen: false }))} className="flex-1 py-3 rounded-xl font-bold bg-slate-100 dark:bg-slate-800 text-slate-600 dark:text-slate-400">Cancel</button>
                <button onClick={confirmConfig.onConfirm} className="flex-1 py-3 rounded-xl font-bold bg-rose-600 text-white shadow-lg shadow-rose-600/20">Delete</button>
              </div>
          </div>
        </div>
      )}
    </Layout>
  );
};

interface AddTransactionFormProps {
  onClose: () => void;
  onSave: (t: Transaction) => Promise<void>;
  onDelete?: (id: string) => void;
  cashBalance: number;
  holdings: Holding[];
  prices: Record<string, number>;
  transactions: Transaction[];
  initialData: Transaction | null;
  defaultDate: string;
}

const AddTransactionForm: React.FC<AddTransactionFormProps> = ({ onClose, onSave, onDelete, cashBalance, holdings, prices, transactions, initialData, defaultDate }) => {
  const [step, setStep] = useState<'input' | 'review'>('input');

  const [type, setType] = useState<TransactionType>(TransactionType.BUY);
  const [date, setDate] = useState(defaultDate);
  const [symbol, setSymbol] = useState('');
  const [shares, setShares] = useState('');
  const [price, setPrice] = useState(''); // Price per share
  const [totalAmount, setTotalAmount] = useState(''); // Total transaction value
  const [fee, setFee] = useState('');
  const [assetClass, setAssetClass] = useState<AssetClass>(AssetClass.STOCK);
  const [exchangeRate, setExchangeRate] = useState(''); 
  const [notes, setNotes] = useState('');
  const [error, setError] = useState<string | null>(null);
  const [isSaving, setIsSaving] = useState(false);

  const [showSuggestions, setShowSuggestions] = useState(false);
  const wrapperRef = useRef<HTMLDivElement>(null);
  const notesRef = useRef<HTMLTextAreaElement>(null);

  // Validation logic helpers
  const needsSymbol = [TransactionType.BUY, TransactionType.SELL, TransactionType.DIVIDEND, TransactionType.SPLIT].includes(type);
  const needsShares = [TransactionType.BUY, TransactionType.SELL, TransactionType.SPLIT].includes(type);
  const needsPrice = type !== TransactionType.SPLIT;

  // FX Rate is relevant for: Deposits, Withdrawals, and Dividends (Foreign income)
  const hasExchangeRate = type === TransactionType.DEPOSIT || type === TransactionType.WITHDRAW || type === TransactionType.DIVIDEND;
  const isFunding = type === TransactionType.DEPOSIT || type === TransactionType.WITHDRAW;

  // Effects (Initialization, Auto-fill, Calculation)
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => { if (wrapperRef.current && !wrapperRef.current.contains(event.target as Node)) setShowSuggestions(false); };
    document.addEventListener("mousedown", handleClickOutside); return () => document.removeEventListener("mousedown", handleClickOutside);
  }, []);

  useEffect(() => {
    if (initialData) {
      if (initialData.type) setType(initialData.type);
      if (initialData.date) setDate(initialData.date);
      if (initialData.symbol) setSymbol(initialData.symbol);
      if (initialData.shares) setShares(initialData.shares.toString());
      if (initialData.price) setPrice(initialData.price.toString());
      if (initialData.fee) setFee(initialData.fee.toString());
      if (initialData.assetClass) setAssetClass(initialData.assetClass);
      if (initialData.exchangeRate) setExchangeRate(initialData.exchangeRate.toString());
      if (initialData.notes) setNotes(initialData.notes);

      if (initialData.shares && initialData.price && (initialData.type === TransactionType.BUY || initialData.type === TransactionType.SELL)) {
         setTotalAmount((initialData.shares * initialData.price).toFixed(2));
      } else if (initialData.price) {
          setTotalAmount(initialData.price.toString());
      }
    }
  }, [initialData]);

  // Auto-fill price from holdings or market data when symbol changes (and no data set yet)
  useEffect(() => {
    if (!initialData && symbol && !price && !totalAmount) {
       const h = holdings.find(h => h.symbol === symbol.toUpperCase());
       if (h) { setAssetClass(h.assetClass); if (h.currentPrice > 0) setPrice(h.currentPrice.toString()); }
       else { const kp = prices[symbol.toUpperCase()]; if (kp) setPrice(kp.toString()); }
    }
  }, [symbol]);

  // --- Real-time Calculation Handlers ---
  const handleSharesChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const val = e.target.value;
    setShares(val);
    const s = parseFloat(val);
    const p = parseFloat(price);
    if (!isNaN(s) && !isNaN(p)) {
        setTotalAmount((s * p).toFixed(2));
    }
  };

  const handlePriceChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const val = e.target.value;
    setPrice(val);
    const p = parseFloat(val);
    const s = parseFloat(shares);
    // If we have shares, calc total
    if (!isNaN(p) && !isNaN(s)) {
        setTotalAmount((s * p).toFixed(2));
    } 
    // If we have total but no shares, calc shares? (Inverse flow)
    else if (!isNaN(p) && totalAmount && !shares) {
        const t = parseFloat(totalAmount);
        if (!isNaN(t) && p !== 0) setShares((t/p).toFixed(4));
    }
  };

  const handleTotalChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const val = e.target.value;
    setTotalAmount(val);
    const t = parseFloat(val);
    const p = parseFloat(price);
    // Standard: Total / Price = Shares
    if (!isNaN(t) && !isNaN(p) && p !== 0) {
        setShares((t / p).toFixed(4));
    }
  };

  // --- Auto-complete Logic ---
  const allSymbols = useMemo(() => {
    const fromHoldings = holdings.map(h => h.symbol);
    const fromHistory = transactions.map(t => t.symbol).filter(s => s) as string[];
    // Unique combined list
    return Array.from(new Set([...fromHoldings, ...fromHistory, ...POPULAR_SYMBOLS])).sort();
  }, [holdings, transactions]);

  const suggestions = useMemo(() => {
    if (!symbol) return [];
    const inputUpper = symbol.toUpperCase();
    return allSymbols.filter(s => s.includes(inputUpper)).slice(0, 6);
  }, [symbol, allSymbols]);

  // Max Button Handlers
  const handleMax = () => {
    const p = parseFloat(price);
    if (type === TransactionType.BUY) {
        if (p > 0) {
            const maxAmt = Math.max(0, cashBalance);
            setTotalAmount(maxAmt.toFixed(2));
            setShares((maxAmt / p).toFixed(4));
        } else {
            setTotalAmount(cashBalance.toFixed(2));
        }
    } else if (type === TransactionType.SELL) {
        const holding = holdings.find(h => h.symbol === symbol.toUpperCase());
        if (holding) {
            setShares(holding.shares.toString());
            if (p > 0) setTotalAmount((holding.shares * p).toFixed(2));
        }
    }
  };

  // IMPACT CALCULATIONS FOR SUMMARY
  const currentCashImpact = useMemo(() => {
     const qty = parseFloat(shares) || 0;
     const unitPrice = parseFloat(price) || 0;
     const feeVal = parseFloat(fee) || 0;
     const amt = parseFloat(totalAmount) || 0;

     if (type === TransactionType.BUY) return -((qty * unitPrice) + feeVal);
     if (type === TransactionType.SELL) return ((qty * unitPrice) - feeVal);
     if (type === TransactionType.DEPOSIT) return amt;
     if (type === TransactionType.WITHDRAW) return -amt;
     if (type === TransactionType.DIVIDEND) return amt;
     return 0;
  }, [type, shares, price, fee, totalAmount]);

  const originalCashImpact = useMemo(() => {
    if (!initialData) return 0;
    const qty = initialData.shares || 0;
    const unitPrice = initialData.price || 0;
    const feeVal = initialData.fee || 0;

    if (initialData.type === TransactionType.BUY) return -((qty * unitPrice) + feeVal);
    if (initialData.type === TransactionType.SELL) return ((qty * unitPrice) - feeVal);
    if (initialData.type === TransactionType.DEPOSIT) return unitPrice; 
    if (initialData.type === TransactionType.WITHDRAW) return -unitPrice;
    if (initialData.type === TransactionType.DIVIDEND) return unitPrice;
    return 0;
  }, [initialData]);

  const projectedCashBalance = cashBalance - originalCashImpact + currentCashImpact;
  const totalNetWorth = useMemo(() => {
     const invested = holdings.reduce((sum, h) => sum + h.marketValue, 0);
     return invested + cashBalance;
  }, [holdings, cashBalance]);

  const feePercentage = useMemo(() => {
     const feeVal = parseFloat(fee) || 0;
     const totalVal = parseFloat(totalAmount) || 0;
     if (feeVal > 0 && totalVal > 0) {
        return (feeVal / totalVal) * 100;
     }
     return 0;
  }, [fee, totalAmount]);

  // Validation
  const validate = () => {
    if (needsSymbol && !symbol) return "Asset Symbol is required.";
    if (!needsSymbol && !totalAmount) return "Amount is required.";
    if (type === TransactionType.SELL) {
        const holding = holdings.find(h => h.symbol === symbol.toUpperCase());
        const currentShares = holding ? holding.shares : 0;
        const originalShares = (initialData && initialData.type === TransactionType.SELL && initialData.symbol === symbol) ? (initialData.shares || 0) : 0;
        const available = currentShares + originalShares;
        if ((parseFloat(shares) || 0) > available) return `Insufficient shares. Owned: ${formatNumber(available)}. Selling: ${shares}.`;
    }
    if ((type === TransactionType.WITHDRAW || type === TransactionType.BUY) && projectedCashBalance < 0) {
        return "Insufficient funds. Transaction exceeds cash balance.";
    }
    return null;
  };

  const handleReview = (e: React.FormEvent) => {
      e.preventDefault();
      const errMsg = validate();
      if (errMsg) return setError(errMsg);
      setError(null);
      setStep('review');
  };

  const handleFinalSubmit = async () => {
    setIsSaving(true);
    await onSave({
      id: initialData && initialData.id ? initialData.id : generateId(),
      date, type, symbol: needsSymbol ? symbol.toUpperCase() : undefined,
      shares: needsShares ? parseFloat(shares) : undefined,
      // For types that don't need shares (Deposit, Withdraw, Dividend), use the total amount as price
      price: type === TransactionType.SPLIT ? 0 : (needsShares ? parseFloat(price) : parseFloat(totalAmount)),
      fee: (fee && (type === TransactionType.BUY || type === TransactionType.SELL)) ? parseFloat(fee) : undefined,
      assetClass: !needsSymbol ? AssetClass.CASH : assetClass,
      exchangeRate: exchangeRate ? parseFloat(exchangeRate) : 1, notes: notes || undefined
    });
    setIsSaving(false);
  };

  const getTypeConfig = (t: TransactionType) => {
    switch (t) {
        case TransactionType.BUY: return { color: 'emerald', icon: <TrendingUp size={16} /> }; // Green
        case TransactionType.DEPOSIT: return { color: 'orange', icon: <Wallet size={16} /> }; // Orange
        case TransactionType.SELL: return { color: 'rose', icon: <TrendingDown size={16} /> }; // Red
        case TransactionType.WITHDRAW: return { color: 'blue', icon: <Banknote size={16} /> }; // Blue
        case TransactionType.DIVIDEND: return { color: 'teal', icon: <DollarSign size={16} /> }; // Teal
        case TransactionType.SPLIT: return { color: 'purple', icon: <Split size={16} /> }; // Purple
        default: return { color: 'slate', icon: <CheckCircle2 size={16} /> };
    }
  }
  const theme = getTypeConfig(type);

  // SUMMARY BAR
  const summaryBox = useMemo(() => {
     const absImpact = Math.abs(currentCashImpact);
     const isPositiveFlow = currentCashImpact >= 0;
     const portfolioPercent = (totalNetWorth > 0) ? (absImpact / totalNetWorth) * 100 : 0;
     const impactColor = isPositiveFlow ? 'bg-emerald-500' : 'bg-rose-500';
     const impactTextColor = isPositiveFlow ? 'text-emerald-600' : 'text-rose-600';

     return (
         <div className="bg-slate-100 dark:bg-slate-800/80 rounded-2xl p-5 border border-slate-200 dark:border-slate-700 mt-4">
             <div className="flex justify-between items-start mb-4">
                 <div>
                    <p className="text-xs font-bold text-slate-500 uppercase tracking-wider">Net Cash Impact</p>
                    <h3 className={`text-2xl font-bold font-display ${impactTextColor}`}>
                        {isPositiveFlow ? '+' : '-'}{formatCurrency(absImpact)}
                    </h3>
                    <p className="text-[10px] text-slate-400 mt-1 font-medium flex items-center">
                        <Percent size={10} className="mr-1"/>
                        ≈ {portfolioPercent.toFixed(1)}% of Total Portfolio
                    </p>
                 </div>
                 <div className="text-right">
                    <p className="text-xs font-bold text-slate-500 uppercase tracking-wider">Projected Cash</p>
                    <p className="text-xl font-bold font-mono text-slate-800 dark:text-slate-200">{formatCurrency(projectedCashBalance)}</p>
                 </div>
             </div>

             {/* Progress Bar */}
             <div className="relative h-2.5 bg-slate-200 dark:bg-slate-700 rounded-full overflow-hidden">
                 <div className="absolute top-0 left-0 h-full bg-slate-400 dark:bg-slate-500 transition-all" style={{ width: '100%' }}></div>
                 {projectedCashBalance < cashBalance && (
                    <div className={`absolute top-0 right-0 h-full ${impactColor} transition-all animate-pulse`} style={{ width: `${((cashBalance - projectedCashBalance)/cashBalance)*100}%` }}></div>
                 )}
                 {projectedCashBalance > cashBalance && (
                     <div className={`absolute top-0 left-0 h-full ${impactColor} transition-all`} style={{ width: '100%' }}></div>
                 )}
             </div>
             <div className="flex justify-between text-[10px] text-slate-400 mt-1.5 font-bold uppercase">
                 <span>Before: {formatCurrency(cashBalance)}</span>
                 <span>After: {formatCurrency(projectedCashBalance)}</span>
             </div>
         </div>
     )
  }, [currentCashImpact, projectedCashBalance, cashBalance, totalNetWorth]);

  const handleNoteChange = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
     setNotes(e.target.value);
     e.target.style.height = 'auto';
     e.target.style.height = `${e.target.scrollHeight}px`;
  }

  // RENDER: REVIEW STEP
  if (step === 'review') {
      return (
          <div className="flex flex-col h-full bg-white dark:bg-slate-900">
             <div className="p-6 text-center border-b border-slate-100 dark:border-slate-800">
                <div className={`w-16 h-16 mx-auto rounded-full bg-${theme.color}-100 dark:bg-${theme.color}-900/30 text-${theme.color}-600 dark:text-${theme.color}-400 flex items-center justify-center mb-4 shadow-lg shadow-${theme.color}-500/20`}>
                   {theme.icon}
                </div>
                <h3 className="text-xl font-display font-bold text-slate-900 dark:text-white">Review Transaction</h3>
                <p className="text-sm text-slate-500">Please confirm details before saving.</p>
             </div>

             <div className="flex-1 overflow-y-auto p-6 space-y-6">
                 {/* Details Card */}
                 <div className="bg-slate-50 dark:bg-slate-800/50 rounded-2xl p-5 border border-slate-200 dark:border-slate-700 space-y-4">
                     <div className="flex justify-between border-b border-slate-200 dark:border-slate-700 pb-2">
                        <span className="text-sm text-slate-500">Date</span>
                        <span className="text-sm font-bold text-slate-900 dark:text-white">{date}</span>
                     </div>
                     <div className="flex justify-between border-b border-slate-200 dark:border-slate-700 pb-2">
                        <span className="text-sm text-slate-500">Type</span>
                        <span className={`text-sm font-bold uppercase text-${theme.color}-600`}>{type}</span>
                     </div>
                     {needsSymbol && (
                         <div className="flex justify-between border-b border-slate-200 dark:border-slate-700 pb-2">
                            <span className="text-sm text-slate-500">Asset</span>
                            <span className="text-sm font-bold text-slate-900 dark:text-white">{symbol} <span className="text-xs text-slate-400 font-normal">({assetClass})</span></span>
                         </div>
                     )}
                     <div className="flex justify-between border-b border-slate-200 dark:border-slate-700 pb-2">
                        <span className="text-sm text-slate-500">Total Amount</span>
                        <span className="text-lg font-bold text-slate-900 dark:text-white">{formatCurrency(parseFloat(totalAmount))}</span>
                     </div>
                     {needsShares && (
                        <div className="flex justify-between pt-1">
                            <span className="text-xs text-slate-400">Details</span>
                            <span className="text-xs text-slate-500">{shares} units @ {formatCurrency(parseFloat(price))}</span>
                        </div>
                     )}
                 </div>

                 {projectedCashBalance < 0 && (
                     <div className="bg-rose-50 text-rose-600 p-4 rounded-xl text-sm font-bold flex items-center">
                         <AlertCircle size={20} className="mr-3 shrink-0" />
                         WARNING: This transaction will result in a negative cash balance.
                     </div>
                 )}
             </div>

             <div className="p-6 border-t border-slate-100 dark:border-slate-800 flex gap-4">
                 <button onClick={() => setStep('input')} className="flex-1 py-3 rounded-xl font-bold bg-slate-100 dark:bg-slate-800 text-slate-600 dark:text-slate-300 hover:bg-slate-200 dark:hover:bg-slate-700 transition-colors">
                    Back to Edit
                 </button>
                 <button onClick={handleFinalSubmit} disabled={isSaving} className={`flex-1 py-3 rounded-xl font-bold text-white shadow-xl flex items-center justify-center space-x-2 bg-${theme.color}-600 hover:bg-${theme.color}-700 transition-all`}>
                    {isSaving ? <Spinner className="text-white" /> : (
                        <>
                            <CheckCircle2 size={18} />
                            <span>Confirm & Save</span>
                        </>
                    )}
                 </button>
             </div>
          </div>
      )
  }

  // RENDER: INPUT STEP
  return (
    <>
      <div className="shrink-0 px-6 py-4 border-b border-slate-100 dark:border-slate-800 flex justify-between items-center bg-white dark:bg-slate-900">
          <h3 className="text-lg font-display font-bold text-slate-900 dark:text-white">{initialData?.id ? 'Edit Transaction' : 'New Transaction'}</h3>
          <button onClick={onClose} className="bg-slate-100 dark:bg-slate-800 p-2 rounded-full text-slate-500 hover:text-slate-800 dark:hover:text-white transition-colors"><X size={20} /></button>
      </div>

      <form onSubmit={handleReview} className="flex-1 overflow-y-auto min-h-0 p-6 custom-scrollbar bg-white dark:bg-slate-900">

        {/* 1. Transaction Type Selector with Icons */}
        <div className="mb-6">
           <label className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-3 block">Transaction Type</label>
           <div className="grid grid-cols-3 sm:grid-cols-6 gap-2">
              {[TransactionType.BUY, TransactionType.SELL, TransactionType.DEPOSIT, TransactionType.WITHDRAW, TransactionType.DIVIDEND, TransactionType.SPLIT].map(t => {
                 const isActive = type === t;
                 const config = getTypeConfig(t);
                 return (
                   <button
                      key={t} type="button" onClick={() => setType(t)}
                      className={`flex flex-col items-center justify-center py-2.5 px-1 rounded-xl text-[10px] sm:text-xs font-bold transition-all border ${
                         isActive 
                         ? `border-transparent bg-${config.color}-500 text-white shadow-md shadow-${config.color}-500/20 transform scale-105` 
                         : 'bg-white dark:bg-slate-800 border-slate-200 dark:border-slate-700 text-slate-500 dark:text-slate-400 hover:border-slate-300 dark:hover:border-slate-600 hover:bg-slate-50'
                      }`}
                   >
                      <div className="mb-1">{config.icon}</div>
                      {t}
                   </button>
                 )
              })}
           </div>
        </div>

        <div className="grid md:grid-cols-2 gap-8">
            {/* LEFT COLUMN: DETAILS */}
            <div className="space-y-5">
                <div className="flex items-center space-x-2 text-slate-800 dark:text-slate-200 border-b border-slate-100 dark:border-slate-800 pb-2">
                    <FileText size={18} />
                    <h4 className="font-bold text-sm uppercase tracking-wide">Transaction Details</h4>
                </div>

                <div>
                   <label className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-1.5 block">Date</label>
                   <div className="relative">
                      <Calendar className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={16} />
                      <input type="date" value={date} onChange={e => setDate(e.target.value)} className="w-full pl-10 pr-4 py-2.5 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl font-medium text-sm focus:ring-2 focus:ring-blue-500 outline-none transition-all" />
                   </div>
                </div>

                {needsSymbol && (
                    <div className="relative z-20" ref={wrapperRef}>
                        <label className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-1.5 block">Asset Symbol</label>
                        <div className="relative group">
                            <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400 group-focus-within:text-blue-500 transition-colors" size={18} />
                            <input 
                               type="text" placeholder="e.g. AAPL" value={symbol} 
                               onChange={e => { setSymbol(e.target.value); setShowSuggestions(true); }}
                               onFocus={() => setShowSuggestions(true)}
                               className="w-full pl-10 pr-4 py-3 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl text-lg font-bold uppercase tracking-wide focus:ring-2 focus:ring-blue-500 focus:bg-white dark:focus:bg-slate-800 outline-none transition-all"
                            />
                             {showSuggestions && suggestions.length > 0 && (
                                <div className="absolute top-full left-0 right-0 mt-2 bg-white dark:bg-slate-800 rounded-xl shadow-xl border border-slate-100 dark:border-slate-700 overflow-hidden z-50 animate-fade-in max-h-60 overflow-y-auto custom-scrollbar">
                                    <div className="px-3 py-2 bg-slate-50 dark:bg-slate-900/50 text-[10px] uppercase font-bold text-slate-400">Suggestions</div>
                                    {suggestions.map(s => (
                                        <div key={s} onMouseDown={(e) => { e.preventDefault(); setSymbol(s); setShowSuggestions(false); }} className="px-4 py-3 hover:bg-blue-50 dark:hover:bg-blue-900/20 cursor-pointer font-bold text-slate-700 dark:text-slate-200 flex justify-between items-center text-sm border-b border-slate-50 dark:border-slate-700/50 last:border-0 group">
                                           <span>{s}</span>
                                           <span className="text-xs text-blue-500 font-normal opacity-0 group-hover:opacity-100 transition-opacity flex items-center">
                                              Use <ArrowRightCircle size={12} className="ml-1"/>
                                           </span>
                                        </div>
                                    ))}
                                </div>
                            )}
                        </div>
                    </div>
                 )}

                 {needsSymbol && (
                    <div>
                        <label className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-1.5 block">Asset Class</label>
                        <select value={assetClass} onChange={e => setAssetClass(e.target.value as AssetClass)} className="w-full px-4 py-2.5 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl font-medium text-sm outline-none focus:ring-2 focus:ring-blue-500 transition-all cursor-pointer">
                            {Object.values(AssetClass).filter(a => a !== AssetClass.CASH).map(a => <option key={a} value={a}>{a}</option>)}
                        </select>
                    </div>
                 )}
            </div>

            {/* RIGHT COLUMN: FINANCIALS */}
            <div className="space-y-5">
                <div className="flex items-center space-x-2 text-slate-800 dark:text-slate-200 border-b border-slate-100 dark:border-slate-800 pb-2">
                    <DollarSign size={18} />
                    <h4 className="font-bold text-sm uppercase tracking-wide">Financials</h4>
                </div>

                {/* Amount / Price Fields */}
                {(needsPrice || isFunding) && (
                   <div>
                       <label className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-1.5 flex justify-between">
                           <span>{needsShares ? 'Total Amount' : 'Amount'}</span>
                           {type === TransactionType.BUY && (
                               <button type="button" onClick={handleMax} className="text-blue-500 hover:underline text-[10px]">Use Max Cash</button>
                           )}
                       </label>
                       <div className="relative group">
                           <span className={`absolute left-4 top-1/2 -translate-y-1/2 text-xl font-bold ${type === TransactionType.SELL || type === TransactionType.WITHDRAW ? 'text-rose-500' : 'text-emerald-500'}`}>$</span>
                           <input 
                              type="number" step="any" min="0" placeholder="0.00"
                              value={totalAmount}
                              onChange={handleTotalChange}
                              className="w-full pl-9 pr-4 py-2.5 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl text-2xl font-display font-bold text-slate-900 dark:text-white focus:ring-2 focus:ring-blue-500 focus:bg-white dark:focus:bg-slate-800 outline-none transition-all"
                           />
                       </div>
                   </div>
                 )}

                 <div className="grid grid-cols-2 gap-4">
                     {needsShares && (
                        <div>
                            <label className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-1.5 flex justify-between">
                                <span>Quantity</span>
                                {type === TransactionType.SELL && (
                                   <button type="button" onClick={handleMax} className="text-rose-500 hover:underline text-[10px]">Sell All</button>
                                )}
                            </label>
                            <input 
                                type="number" step="any" 
                                placeholder="0" 
                                value={shares}
                                onChange={handleSharesChange}
                                className="w-full px-3 py-2.5 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl font-medium text-sm focus:ring-2 focus:ring-blue-500 outline-none"
                            />
                        </div>
                     )}

                     {needsPrice && needsShares && (
                        <div>
                           <label className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-1.5 block">Price / Share</label>
                           <input 
                                type="number" step="any" placeholder="0.00" value={price}
                                onChange={handlePriceChange}
                                className="w-full px-3 py-2.5 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl font-medium text-sm focus:ring-2 focus:ring-blue-500 outline-none"
                            />
                        </div>
                     )}
                 </div>

                 {(type === TransactionType.BUY || type === TransactionType.SELL) && (
                    <div>
                        <label className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-1.5 block">Fee</label>
                        <input 
                             type="number" step="any" placeholder="0.00" value={fee} onChange={e => setFee(e.target.value)} 
                             className="w-full px-4 py-2 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl text-sm outline-none focus:ring-2 focus:ring-blue-500" 
                        />
                        {feePercentage > 0 && (
                           <div className="text-[10px] text-slate-400 mt-1 flex items-center">
                              <Info size={10} className="mr-1" />
                              ≈ {feePercentage.toFixed(2)}% of total amount
                           </div>
                        )}
                    </div>
                 )}

                 {hasExchangeRate && (
                    <div>
                       <label className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-1 block">Exchange Rate</label>
                       <input 
                         type="number" step="any" min="0" placeholder="1.0" 
                         value={exchangeRate} onChange={e => setExchangeRate(e.target.value)} 
                         className="w-full px-4 py-2 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl font-medium text-sm outline-none focus:ring-2 focus:ring-blue-500" 
                       />
                    </div>
                 )}
            </div>
        </div>

        {/* SUMMARY SECTION */}
        {summaryBox}

        {/* Notes Collapsible */}
        <details className="group mt-4" open={!!notes}>
            <summary className="flex items-center text-xs font-bold text-slate-400 uppercase tracking-wider cursor-pointer hover:text-blue-500 transition-colors w-fit">
               <span className="mr-2">Add Notes</span>
               <ChevronDown size={14} className="group-open:rotate-180 transition-transform" />
            </summary>
            <div className="mt-2 animate-slide-up">
                 <textarea 
                   ref={notesRef}
                   rows={2} 
                   placeholder="E.g. Monthly DCA, Rebalancing..." 
                   value={notes} 
                   onChange={handleNoteChange} 
                   className="w-full px-4 py-2 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl text-sm outline-none resize-none transition-all focus:border-blue-400 overflow-hidden min-h-[50px]" 
                 />
            </div>
        </details>

      </form>

      {/* 6. FOOTER ACTIONS */}
      <div className="px-6 py-4 border-t border-slate-100 dark:border-slate-800 bg-white dark:bg-slate-900 z-10 flex gap-3">
             {error && (
                <div className="absolute bottom-full left-0 w-full px-6 pb-2">
                    <div className="bg-rose-50 text-rose-600 px-4 py-2 rounded-xl text-sm font-bold flex items-center animate-slide-up shadow-sm border border-rose-100">
                        <AlertCircle size={16} className="mr-2" /> {error}
                    </div>
                </div>
             )}

             {initialData?.id && onDelete && (
                 <button type="button" onClick={() => onDelete(initialData!.id)} className="p-3 rounded-xl bg-rose-50 text-rose-500 hover:bg-rose-100 dark:bg-rose-900/10 dark:hover:bg-rose-900/20 transition-colors"><Trash2 size={20} /></button>
             )}
             <button 
                onClick={handleReview}
                title="Double check your details before saving"
                className={`flex-1 py-3 rounded-xl font-bold text-base text-white shadow-xl transition-all active:scale-95 flex items-center justify-center space-x-2 bg-${theme.color}-600 hover:bg-${theme.color}-700 shadow-${theme.color}-500/30`}
             >
                <span>Review & Save</span>
                <ArrowRight size={18} />
             </button>
      </div>
    </>
  );
};

export default App;

import React, { useState, useMemo } from 'react';
import { Holding, Transaction, AssetClass, TransactionType } from '../types';
import { formatCurrency, formatNumber } from '../utils';
import { RefreshCw, Briefcase, Layers, Eye, EyeOff, Target, LayoutGrid, LayoutList, TrendingUp, TrendingDown, MoreHorizontal, ArrowUpDown, ArrowUp, ArrowDown, Wallet, DollarSign, Plus, Minus, Edit2, Lightbulb, AlertTriangle } from 'lucide-react';
import { AreaChart, Area, ResponsiveContainer, YAxis, XAxis, Tooltip, ReferenceLine } from 'recharts';
import { HoldingsSkeleton } from './LoadingSkeletons';

interface HoldingsProps {
  holdings: Holding[];
  transactions: Transaction[];
  cashBalance: number;
  onUpdatePrice: (symbol: string, newPrice: number) => void;
  onUpdateTarget: (symbol: string, target: number) => void;
  onTrade: (symbol: string, type: TransactionType) => void;
  isLoading?: boolean;
}

type SortField = 'marketValue' | 'unrealizedPL' | 'unrealizedPLPercent' | 'symbol' | 'totalCost' | 'shares' | 'weight';
type SortDirection = 'asc' | 'desc';

const Holdings: React.FC<HoldingsProps> = ({ holdings, transactions, cashBalance, onUpdatePrice, onUpdateTarget, onTrade, isLoading }) => {
  const [viewMode, setViewMode] = useState<'card' | 'table'>('card');
  const [groupByCategory, setGroupByCategory] = useState(false);
  const [hideClosed, setHideClosed] = useState(true);

  // Sorting State
  const [sortField, setSortField] = useState<SortField>('marketValue');
  const [sortDirection, setSortDirection] = useState<SortDirection>('desc');

  // Price Editing State
  const [editingPrice, setEditingPrice] = useState<string | null>(null);
  const [tempPrice, setTempPrice] = useState<string>('');

  // Target Editing State
  const [editingTarget, setEditingTarget] = useState<string | null>(null);
  const [tempTarget, setTempTarget] = useState<string>('');

  // --- HANDLERS ---
  const handleSort = (field: SortField) => {
     if (sortField === field) {
        setSortDirection(sortDirection === 'asc' ? 'desc' : 'asc');
     } else {
        setSortField(field);
        setSortDirection('desc'); // Default to desc for most metrics
     }
  };

  const handleEditPriceClick = (symbol: string, currentPrice: number, e: React.MouseEvent) => {
    e.stopPropagation();
    setEditingPrice(symbol);
    setTempPrice(currentPrice.toString());
  };

  const handleSavePrice = (symbol: string) => {
    const price = parseFloat(tempPrice);
    if (!isNaN(price) && price >= 0) {
      onUpdatePrice(symbol, price);
    }
    setEditingPrice(null);
  };

  const handleEditTargetClick = (symbol: string, currentTarget: number, e: React.MouseEvent) => {
    e.stopPropagation();
    setEditingTarget(symbol);
    setTempTarget(currentTarget.toString());
  };

  const handleSaveTarget = (symbol: string) => {
    const target = parseFloat(tempTarget);
    if (!isNaN(target) && target >= 0 && target <= 100) {
      onUpdateTarget(symbol, target);
    }
    setEditingTarget(null);
  };

  // --- DATA PROCESSING ---

  const { totalMarketValue, totalUnrealizedPL, totalCost } = useMemo(() => {
    const mv = holdings.reduce((sum, h) => sum + h.marketValue, 0);
    const cost = holdings.reduce((sum, h) => sum + h.totalCost, 0);
    const pl = mv - cost;
    return { totalMarketValue: mv, totalCost: cost, totalUnrealizedPL: pl };
  }, [holdings]);

  const netWorth = totalMarketValue + cashBalance;

  const displayHoldings = useMemo(() => {
    let filtered = hideClosed 
      ? holdings.filter(h => h.shares > 0.000001) 
      : holdings;

    // Enrich with weight and diff
    const enriched = filtered.map(h => {
        const weight = totalMarketValue > 0 ? (h.marketValue / totalMarketValue) * 100 : 0;
        const diff = weight - (h.targetAllocation || 0);
        return { ...h, weight, diff };
    });

    // Sorting
    return enriched.sort((a, b) => {
        let valA: any = a[sortField as keyof typeof a];
        let valB: any = b[sortField as keyof typeof b];

        // Handle undefined or special cases
        if (sortField === 'weight') {
            valA = a.weight;
            valB = b.weight;
        }

        if (valA < valB) return sortDirection === 'asc' ? -1 : 1;
        if (valA > valB) return sortDirection === 'asc' ? 1 : -1;
        return 0;
    });

  }, [holdings, hideClosed, sortField, sortDirection, totalMarketValue]);

  const groupedHoldings = useMemo(() => {
    if (!groupByCategory) return null;
    const groups: Partial<Record<AssetClass, typeof displayHoldings>> = {};
    displayHoldings.forEach(h => {
      if (!groups[h.assetClass]) groups[h.assetClass] = [];
      groups[h.assetClass]?.push(h);
    });
    return groups;
  }, [displayHoldings, groupByCategory]);

  const bestPerformer = useMemo(() => {
     if (displayHoldings.length === 0) return null;
     return [...displayHoldings].sort((a,b) => b.unrealizedPLPercent - a.unrealizedPLPercent)[0];
  }, [displayHoldings]);

  if (isLoading) return <HoldingsSkeleton />;

  // --- COMPONENTS ---

  const renderSparkline = (h: Holding, height = 50) => {
    const sparklineData = transactions
      .filter(t => t.symbol === h.symbol && (t.type === 'BUY' || t.type === 'SELL') && (t.price || 0) > 0)
      .sort((a, b) => new Date(a.date).getTime() - new Date(b.date).getTime())
      .map((t) => ({ date: t.date, price: t.price! }));

    // Add current price point
    if (h.currentPrice > 0) {
        sparklineData.push({ date: 'Now', price: h.currentPrice });
    }

    const isUp = h.unrealizedPL >= 0;
    const color = isUp ? '#10b981' : '#f43f5e'; // Emerald-500 or Rose-500

    if (sparklineData.length < 2) return <div className="text-[10px] text-slate-300 italic h-full flex items-center justify-center">No Data</div>;

    return (
      <ResponsiveContainer width="100%" height={height}>
        <AreaChart data={sparklineData} margin={{ top: 5, right: 0, left: 0, bottom: 0 }}>
          <defs>
            <linearGradient id={`gradient-${h.symbol}`} x1="0" y1="0" x2="0" y2="1">
              <stop offset="5%" stopColor={color} stopOpacity={0.2}/>
              <stop offset="95%" stopColor={color} stopOpacity={0}/>
            </linearGradient>
          </defs>
          <Tooltip 
             contentStyle={{ backgroundColor: '#1e293b', borderColor: '#334155', borderRadius: '8px', padding: '4px 8px' }}
             itemStyle={{ color: '#fff', fontSize: '10px', fontWeight: 'bold' }}
             labelStyle={{ display: 'none' }}
             formatter={(value: any) => [formatCurrency(value), 'Price']}
          />
          <Area 
            type="monotone" 
            dataKey="price" 
            stroke={color} 
            strokeWidth={2} 
            fill={`url(#gradient-${h.symbol})`} 
            isAnimationActive={false} 
          />
          {/* Baseline if possible, though strict 0 might be far off scale. Use start price as baseline visually? */}
        </AreaChart>
      </ResponsiveContainer>
    );
  };

  const renderCard = (h: any) => {
    const isEditingPrice = editingPrice === h.symbol;
    const isEditingTarget = editingTarget === h.symbol;
    const target = h.targetAllocation || 0;

    return (
      <div key={h.symbol} className={`group flex flex-col bg-white dark:bg-slate-800 rounded-2xl border border-slate-200 dark:border-slate-700 shadow-sm hover:shadow-xl hover:-translate-y-1 transition-all duration-300 overflow-hidden relative ${h.shares === 0 ? 'opacity-60 grayscale' : ''}`}>
         <div className="p-4 flex-1 flex flex-col">

            {/* Header: Icon, Name, Price */}
            <div className="flex justify-between items-start mb-3">
              <div className="flex items-center space-x-3 min-w-0">
                  <div className={`w-10 h-10 rounded-xl flex items-center justify-center font-bold text-sm shrink-0 shadow-sm ${
                      h.unrealizedPL >= 0 ? 'bg-emerald-50 text-emerald-700 dark:bg-emerald-900/20 dark:text-emerald-400' : 'bg-rose-50 text-rose-700 dark:bg-rose-900/20 dark:text-rose-400'
                  }`}>
                    {h.symbol.substring(0, 2)}
                  </div>
                  <div className="min-w-0">
                    <h3 className="font-bold text-slate-900 dark:text-white leading-tight truncate">{h.symbol}</h3>
                    <div className="flex items-center gap-1.5 text-xs text-slate-500 dark:text-slate-400">
                         <span className="truncate">{h.name}</span>
                    </div>
                  </div>
              </div>
              <div className="text-right shrink-0">
                   {isEditingPrice ? (
                      <input 
                        type="number" 
                        value={tempPrice} 
                        onChange={(e) => setTempPrice(e.target.value)}
                        className="w-20 px-2 py-1 text-sm font-bold border-2 border-blue-500 rounded-lg bg-white dark:bg-slate-900 dark:text-white focus:outline-none text-right"
                        autoFocus
                        onBlur={() => handleSavePrice(h.symbol)}
                        onKeyDown={(e) => e.key === 'Enter' && handleSavePrice(h.symbol)}
                        onClick={(e) => e.stopPropagation()}
                      />
                   ) : (
                      <div className="cursor-pointer group/price" onClick={(e) => handleEditPriceClick(h.symbol, h.currentPrice, e)}>
                         <p className="text-base font-extrabold text-slate-900 dark:text-white group-hover/price:text-blue-500 transition-colors">{formatCurrency(h.currentPrice)}</p>
                         <div className="flex items-center justify-end gap-1 text-[10px] text-slate-400 uppercase font-bold tracking-wider">
                            <span>Price</span>
                            <Edit2 size={8} className="opacity-0 group-hover/price:opacity-100 transition-opacity" />
                         </div>
                      </div>
                   )}
              </div>
            </div>

            {/* Sparkline */}
            <div className="h-12 w-full -mx-2 mb-3 opacity-90">
                {h.shares > 0 && renderSparkline(h, 45)}
            </div>

            {/* Metrics Grid */}
            <div className="grid grid-cols-2 gap-x-4 gap-y-3 mb-4">
               <div>
                 <p className="text-[10px] uppercase text-slate-500 dark:text-slate-400 font-bold mb-0.5">Value</p>
                 <p className="text-sm font-extrabold text-slate-900 dark:text-white">{formatCurrency(h.marketValue)}</p>
                 <div className="text-[10px] text-slate-400 font-medium">
                     {h.weight.toFixed(1)}% of Portfolio
                 </div>
               </div>
               <div className="text-right">
                 <p className="text-[10px] uppercase text-slate-500 dark:text-slate-400 font-bold mb-0.5">Unrealized P/L</p>
                 <div className={`text-sm font-extrabold ${h.unrealizedPL >= 0 ? 'text-emerald-600 dark:text-emerald-400' : 'text-rose-600 dark:text-rose-400'}`}>
                     {h.unrealizedPL >= 0 ? '+' : ''}{formatCurrency(h.unrealizedPL)}
                 </div>
                 <div className={`text-[10px] font-bold ${h.unrealizedPLPercent >= 0 ? 'text-emerald-600 dark:text-emerald-400' : 'text-rose-600 dark:text-rose-400'}`}>
                    {h.unrealizedPLPercent >= 0 ? <ArrowUp size={10} className="inline mr-0.5"/> : <ArrowDown size={10} className="inline mr-0.5"/>}
                    {h.unrealizedPLPercent.toFixed(2)}%
                 </div>
               </div>
            </div>

            {/* Target & Rebalance Info */}
            <div className="bg-slate-50 dark:bg-slate-900/50 rounded-xl p-2.5 mb-3 flex justify-between items-center border border-slate-100 dark:border-slate-700/50">
                <div className="flex items-center gap-2" onClick={(e) => !isEditingTarget && handleEditTargetClick(h.symbol, target, e)}>
                    <Target size={14} className="text-slate-400" />
                    {isEditingTarget ? (
                        <div className="flex items-center">
                            <input 
                                type="number" 
                                value={tempTarget} 
                                onChange={(e) => setTempTarget(e.target.value)}
                                className="w-10 px-0 py-0 text-xs border-b-2 border-blue-500 bg-transparent outline-none font-bold text-slate-900 dark:text-white"
                                autoFocus
                                onClick={(e) => e.stopPropagation()}
                                onBlur={() => handleSaveTarget(h.symbol)}
                                onKeyDown={(e) => e.key === 'Enter' && handleSaveTarget(h.symbol)}
                            />
                            <span className="text-xs text-slate-500 font-bold">%</span>
                        </div>
                    ) : (
                        <div className="flex flex-col cursor-pointer hover:opacity-70">
                           <span className="text-[10px] font-bold uppercase text-slate-400">Target</span>
                           <span className="text-xs font-bold text-slate-700 dark:text-slate-300">{target > 0 ? `${target}%` : '-'}</span>
                        </div>
                    )}
                </div>

                {/* Diff Indicator */}
                <div className="text-right">
                    <span className="text-[10px] font-bold uppercase text-slate-400">Diff</span>
                    <div className={`text-xs font-bold ${Math.abs(h.diff) < 1 ? 'text-slate-400' : h.diff > 0 ? 'text-emerald-500' : 'text-amber-500'}`}>
                        {h.diff > 0 ? '+' : ''}{h.diff.toFixed(1)}%
                    </div>
                </div>
            </div>

            {/* Quick Actions (Hover Visible on Desktop, Always on Mobile) */}
            <div className="flex items-center gap-2 mt-auto pt-2 border-t border-slate-100 dark:border-slate-800 opacity-100 sm:opacity-0 sm:group-hover:opacity-100 transition-opacity">
               <button onClick={() => onTrade(h.symbol, TransactionType.BUY)} className="flex-1 py-1.5 rounded-lg bg-emerald-50 dark:bg-emerald-900/20 text-emerald-700 dark:text-emerald-400 text-xs font-bold flex items-center justify-center hover:bg-emerald-100 dark:hover:bg-emerald-900/40 transition-colors">
                  <Plus size={12} className="mr-1" /> Buy
               </button>
               <button onClick={() => onTrade(h.symbol, TransactionType.SELL)} className="flex-1 py-1.5 rounded-lg bg-rose-50 dark:bg-rose-900/20 text-rose-700 dark:text-rose-400 text-xs font-bold flex items-center justify-center hover:bg-rose-100 dark:hover:bg-rose-900/40 transition-colors">
                  <Minus size={12} className="mr-1" /> Sell
               </button>
            </div>
         </div>
      </div>
    );
  };

  const renderSummaryRow = () => (
      <div className="grid grid-cols-2 md:grid-cols-4 gap-4 mb-8">
          {/* Net Worth */}
          <div className="bg-slate-900 dark:bg-slate-800 text-white p-5 rounded-2xl shadow-lg relative overflow-hidden group">
              <div className="absolute top-0 right-0 p-4 opacity-10 group-hover:scale-110 transition-transform"><Wallet size={48} /></div>
              <p className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-1">Total Net Worth</p>
              <h3 className="text-2xl md:text-3xl font-display font-bold">{formatCurrency(netWorth)}</h3>
              <div className="flex gap-3 mt-3 text-[10px] font-bold uppercase text-slate-400">
                  <span>Cash: {formatCurrency(cashBalance)}</span>
                  <span>Assets: {formatCurrency(totalMarketValue)}</span>
              </div>
          </div>

          {/* Unrealized P/L */}
          <div className={`p-5 rounded-2xl border shadow-sm ${totalUnrealizedPL >= 0 ? 'bg-emerald-50 border-emerald-100 dark:bg-emerald-900/10 dark:border-emerald-800' : 'bg-rose-50 border-rose-100 dark:bg-rose-900/10 dark:border-rose-800'}`}>
              <p className={`text-xs font-bold uppercase tracking-wider mb-1 ${totalUnrealizedPL >= 0 ? 'text-emerald-600 dark:text-emerald-400' : 'text-rose-600 dark:text-rose-400'}`}>Unrealized P/L</p>
              <h3 className={`text-2xl font-display font-bold ${totalUnrealizedPL >= 0 ? 'text-emerald-700 dark:text-emerald-300' : 'text-rose-700 dark:text-rose-300'}`}>
                  {totalUnrealizedPL >= 0 ? '+' : ''}{formatCurrency(totalUnrealizedPL)}
              </h3>
               <div className={`mt-2 text-xs font-bold ${totalCost > 0 ? (totalUnrealizedPL >= 0 ? 'text-emerald-600' : 'text-rose-600') : 'text-slate-400'}`}>
                  {totalCost > 0 ? ((totalUnrealizedPL/totalCost)*100).toFixed(2) : 0}% Return
               </div>
          </div>

           {/* Asset Count */}
           <div className="bg-white dark:bg-slate-800 p-5 rounded-2xl border border-slate-200 dark:border-slate-700 shadow-sm flex flex-col justify-between">
              <div>
                 <p className="text-xs font-bold text-slate-500 uppercase tracking-wider mb-1">Active Positions</p>
                 <h3 className="text-2xl font-display font-bold text-slate-900 dark:text-white">{displayHoldings.length}</h3>
              </div>
              <div className="mt-2 text-[10px] text-slate-400 font-bold uppercase flex gap-2">
                 <span className="bg-blue-50 text-blue-600 px-1.5 py-0.5 rounded">Stock: {holdings.filter(h => h.assetClass === 'Stock' && h.shares > 0).length}</span>
                 <span className="bg-purple-50 text-purple-600 px-1.5 py-0.5 rounded">Crypto: {holdings.filter(h => h.assetClass === 'Crypto' && h.shares > 0).length}</span>
              </div>
          </div>

           {/* Best Performer Summary */}
           <div className="bg-white dark:bg-slate-800 p-5 rounded-2xl border border-slate-200 dark:border-slate-700 shadow-sm flex flex-col justify-between relative overflow-hidden">
               {bestPerformer ? (
                   <>
                       <div className="absolute right-0 top-0 p-3 opacity-5"><TrendingUp size={60} /></div>
                       <p className="text-xs font-bold text-slate-500 uppercase tracking-wider mb-1">Top Performer</p>
                       <div className="flex items-center gap-2">
                           <div className="w-8 h-8 rounded-lg bg-emerald-100 dark:bg-emerald-900/30 text-emerald-600 dark:text-emerald-400 flex items-center justify-center font-bold text-xs">
                               {bestPerformer.symbol.substring(0,2)}
                           </div>
                           <div>
                               <h3 className="text-lg font-bold text-slate-900 dark:text-white leading-none">{bestPerformer.symbol}</h3>
                               <p className="text-emerald-500 font-bold text-sm">+{bestPerformer.unrealizedPLPercent.toFixed(1)}%</p>
                           </div>
                       </div>
                   </>
               ) : (
                   <div className="flex h-full items-center justify-center text-slate-400 text-xs italic">No data available</div>
               )}
           </div>
      </div>
  );

  const renderTableHead = (label: string, field: SortField, align = 'left') => (
      <th 
         className={`px-4 py-3 text-xs font-bold text-slate-500 dark:text-slate-400 uppercase tracking-wider cursor-pointer hover:bg-slate-100 dark:hover:bg-slate-700 transition-colors ${align === 'right' ? 'text-right' : 'text-left'}`}
         onClick={() => handleSort(field)}
      >
         <div className={`flex items-center gap-1 ${align === 'right' ? 'justify-end' : 'justify-start'}`}>
            {label}
            {sortField === field && <ArrowUpDown size={12} className={sortDirection === 'asc' ? 'rotate-180' : ''} />}
         </div>
      </th>
  );

  return (
    <div className="space-y-6 animate-fade-in pb-20">

      {/* 1. Summary Dashboard */}
      {renderSummaryRow()}

      {/* 2. Controls Toolbar */}
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4 bg-white dark:bg-slate-900 p-1 rounded-xl sticky top-20 z-20">
         <div className="flex items-center gap-2">
            <h2 className="text-xl font-display font-bold text-slate-900 dark:text-white mr-4">Holdings</h2>

            <button 
               onClick={() => setGroupByCategory(!groupByCategory)}
               className={`flex items-center gap-2 px-3 py-1.5 rounded-lg text-xs font-bold border transition-all ${groupByCategory ? 'bg-blue-50 border-blue-200 text-blue-700 dark:bg-blue-900/30 dark:border-blue-800 dark:text-blue-400' : 'border-transparent text-slate-500 hover:bg-slate-100 dark:hover:bg-slate-800'}`}
            >
               <Layers size={14} /> Group
            </button>
            <button 
               onClick={() => setHideClosed(!hideClosed)}
               className={`flex items-center gap-2 px-3 py-1.5 rounded-lg text-xs font-bold border transition-all ${hideClosed ? 'bg-emerald-50 border-emerald-200 text-emerald-700 dark:bg-emerald-900/30 dark:border-emerald-800 dark:text-emerald-400' : 'border-transparent text-slate-500 hover:bg-slate-100 dark:hover:bg-slate-800'}`}
            >
               {hideClosed ? <Eye size={14} /> : <EyeOff size={14} />} Active
            </button>
         </div>

         {/* View Toggle */}
         <div className="flex bg-slate-100 dark:bg-slate-800 p-1 rounded-lg self-end md:self-auto">
             <button onClick={() => setViewMode('card')} className={`p-1.5 rounded-md transition-all ${viewMode === 'card' ? 'bg-white dark:bg-slate-600 shadow text-blue-600 dark:text-white' : 'text-slate-400'}`}>
                <LayoutGrid size={16} />
             </button>
             <button onClick={() => setViewMode('table')} className={`p-1.5 rounded-md transition-all ${viewMode === 'table' ? 'bg-white dark:bg-slate-600 shadow text-blue-600 dark:text-white' : 'text-slate-400'}`}>
                <LayoutList size={16} />
             </button>
         </div>
      </div>

      {/* 3. CONTENT AREA */}
      <div className="animate-slide-up min-h-[400px]">
          {viewMode === 'card' ? (
             <div className="space-y-8">
                {groupByCategory ? (
                    Object.keys(groupedHoldings || {}).map((assetClass) => {
                        const items = groupedHoldings![assetClass as AssetClass]!;
                        if (!items || items.length === 0) return null;
                        return (
                            <div key={assetClass} className="space-y-4">
                                <div className="flex items-center space-x-3">
                                <span className="bg-slate-900 dark:bg-white text-white dark:text-slate-900 px-3 py-1 rounded-lg text-xs font-extrabold uppercase tracking-wide shadow-md">
                                    {assetClass}
                                </span>
                                <div className="h-px bg-slate-200 dark:bg-slate-700 flex-1"></div>
                                </div>
                                <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">
                                {items.map(h => renderCard(h))}
                                </div>
                            </div>
                        );
                    })
                ) : (
                    <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">
                        {displayHoldings.map(h => renderCard(h))}
                    </div>
                )}
             </div>
          ) : (
            // --- TABLE VIEW ---
            <div className="bg-white dark:bg-slate-800 rounded-2xl shadow-sm border border-slate-200 dark:border-slate-700 overflow-hidden">
                <div className="overflow-x-auto">
                    <table className="w-full text-left border-collapse">
                        <thead>
                            <tr className="bg-slate-50 dark:bg-slate-900/50 border-b border-slate-200 dark:border-slate-700">
                                {renderTableHead('Symbol', 'symbol')}
                                <th className="px-4 py-3 text-xs font-bold text-slate-500 dark:text-slate-400 uppercase tracking-wider">Asset Class</th>
                                <th className="px-4 py-3 text-xs font-bold text-slate-500 dark:text-slate-400 uppercase tracking-wider text-right">Price</th>
                                {renderTableHead('Shares', 'shares', 'right')}
                                {renderTableHead('Avg Cost', 'totalCost', 'right')}
                                {renderTableHead('Value', 'marketValue', 'right')}
                                {renderTableHead('Unrealized P/L', 'unrealizedPL', 'right')}
                                {renderTableHead('Weight', 'weight', 'right')}
                                <th className="px-4 py-3 text-xs font-bold text-slate-500 dark:text-slate-400 uppercase tracking-wider text-right">Target</th>
                                <th className="px-4 py-3 text-xs font-bold text-slate-500 dark:text-slate-400 uppercase tracking-wider text-center">Action</th>
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-slate-100 dark:divide-slate-700">
                            {displayHoldings.map((h) => {
                                const isEditingPrice = editingPrice === h.symbol;
                                const isEditingTarget = editingTarget === h.symbol;
                                const target = h.targetAllocation || 0;

                                return (
                                <tr key={h.symbol} className="hover:bg-slate-50 dark:hover:bg-slate-700/30 transition-colors group">
                                    <td className="px-4 py-3">
                                        <div className="flex items-center gap-3">
                                            <div className="w-8 h-8 rounded-lg bg-slate-100 dark:bg-slate-700 flex items-center justify-center font-bold text-xs text-slate-700 dark:text-slate-300">
                                                {h.symbol.substring(0,2)}
                                            </div>
                                            <div>
                                                <div className="font-bold text-slate-900 dark:text-white">{h.symbol}</div>
                                                <div className="text-[10px] text-slate-500 dark:text-slate-400 truncate max-w-[100px]">{h.name}</div>
                                            </div>
                                        </div>
                                    </td>
                                    <td className="px-4 py-3">
                                        <span className="px-2 py-1 rounded-md text-[10px] font-bold uppercase bg-slate-100 dark:bg-slate-700 text-slate-500 dark:text-slate-300">
                                            {h.assetClass}
                                        </span>
                                    </td>
                                    <td className="px-4 py-3 text-right font-mono font-medium text-slate-900 dark:text-white">
                                         {isEditingPrice ? (
                                            <input 
                                                type="number" 
                                                value={tempPrice} 
                                                onChange={(e) => setTempPrice(e.target.value)}
                                                className="w-20 px-1 py-0.5 text-right text-sm border border-blue-500 rounded bg-white dark:bg-slate-900 focus:outline-none"
                                                autoFocus
                                                onBlur={() => handleSavePrice(h.symbol)}
                                                onKeyDown={(e) => e.key === 'Enter' && handleSavePrice(h.symbol)}
                                            />
                                         ) : (
                                            <div className="flex items-center justify-end gap-1 cursor-pointer hover:text-blue-500" onClick={(e) => handleEditPriceClick(h.symbol, h.currentPrice, e)}>
                                                {formatCurrency(h.currentPrice)}
                                            </div>
                                         )}
                                    </td>
                                    <td className="px-4 py-3 text-right text-sm text-slate-600 dark:text-slate-300">{formatNumber(h.shares)}</td>
                                    <td className="px-4 py-3 text-right text-sm text-slate-500 dark:text-slate-400">{formatCurrency(h.avgCost)}</td>
                                    <td className="px-4 py-3 text-right font-bold text-slate-900 dark:text-white">{formatCurrency(h.marketValue)}</td>
                                    <td className="px-4 py-3 text-right">
                                        <div className={`font-bold text-sm ${h.unrealizedPL >= 0 ? 'text-emerald-600 dark:text-emerald-400' : 'text-rose-600 dark:text-rose-400'}`}>
                                            {formatCurrency(h.unrealizedPL)}
                                        </div>
                                        <div className={`text-[10px] font-bold ${h.unrealizedPLPercent >= 0 ? 'text-emerald-500' : 'text-rose-500'}`}>
                                            {h.unrealizedPLPercent.toFixed(2)}%
                                        </div>
                                    </td>
                                    <td className="px-4 py-3 text-right">
                                        <div className="font-bold text-slate-700 dark:text-slate-300 text-sm">{h.weight.toFixed(1)}%</div>
                                        <div className={`text-[10px] font-medium ${Math.abs(h.diff) < 1 ? 'text-slate-400' : h.diff > 0 ? 'text-emerald-500' : 'text-amber-500'}`}>
                                            {h.diff > 0 ? '+' : ''}{h.diff.toFixed(1)}%
                                        </div>
                                    </td>
                                    <td className="px-4 py-3 text-right">
                                         <div className="flex justify-end items-center gap-2" onClick={(e) => !isEditingTarget && handleEditTargetClick(h.symbol, target, e)}>
                                            {isEditingTarget ? (
                                                <input 
                                                    type="number" 
                                                    value={tempTarget} 
                                                    onChange={(e) => setTempTarget(e.target.value)}
                                                    className="w-12 px-1 py-0.5 text-right text-xs border border-blue-500 rounded bg-white dark:bg-slate-900 focus:outline-none"
                                                    autoFocus
                                                    onBlur={() => handleSaveTarget(h.symbol)}
                                                    onKeyDown={(e) => e.key === 'Enter' && handleSaveTarget(h.symbol)}
                                                />
                                            ) : (
                                                <span className={`cursor-pointer hover:underline text-xs font-bold ${target > 0 ? 'text-slate-600 dark:text-slate-300' : 'text-slate-400'}`}>
                                                    {target > 0 ? `${target}%` : 'Set'}
                                                </span>
                                            )}
                                         </div>
                                    </td>
                                    <td className="px-4 py-3">
                                        <div className="flex items-center justify-center gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                                            <button onClick={() => onTrade(h.symbol, TransactionType.BUY)} className="p-1.5 rounded hover:bg-emerald-50 dark:hover:bg-emerald-900/20 text-emerald-600" title="Buy">
                                                <Plus size={14} />
                                            </button>
                                            <button onClick={() => onTrade(h.symbol, TransactionType.SELL)} className="p-1.5 rounded hover:bg-rose-50 dark:hover:bg-rose-900/20 text-rose-600" title="Sell">
                                                <Minus size={14} />
                                            </button>
                                        </div>
                                    </td>
                                </tr>
                            )})}
                        </tbody>
                    </table>
                </div>
            </div>
          )}

          {/* Empty State */}
          {displayHoldings.length === 0 && (
              <div className="py-24 flex flex-col items-center justify-center text-center p-8 rounded-3xl border-2 border-dashed border-slate-200 dark:border-slate-700 bg-slate-50/50 dark:bg-slate-800/50">
                  <div className="w-20 h-20 bg-white dark:bg-slate-800 rounded-full shadow-sm flex items-center justify-center mb-6">
                      <Briefcase size={40} className="text-slate-300" />
                  </div>
                  <h3 className="text-xl font-bold text-slate-900 dark:text-white">No Assets Found</h3>
                  <p className="text-slate-500 dark:text-slate-400 max-w-md mt-2 mb-6">
                      {holdings.length === 0
                      ? "Your portfolio is currently empty. Start by adding a transaction."
                      : "No assets match your criteria."}
                  </p>
              </div>
          )}
      </div>

      {/* 10. Insights Section */}
      {displayHoldings.length > 0 && (
         <div className="bg-gradient-to-r from-indigo-50 to-blue-50 dark:from-slate-800 dark:to-slate-800 border border-blue-100 dark:border-slate-700 rounded-2xl p-6 mt-8">
             <div className="flex items-start gap-4">
                 <div className="p-3 bg-white dark:bg-slate-700 rounded-xl text-amber-500 shadow-sm">
                     <Lightbulb size={24} />
                 </div>
                 <div>
                     <h3 className="text-lg font-bold text-slate-900 dark:text-white">Portfolio Insights</h3>
                     <div className="mt-2 space-y-2 text-sm text-slate-600 dark:text-slate-300">
                         {bestPerformer && (
                            <p className="flex items-center gap-2">
                                <TrendingUp size={16} className="text-emerald-500" />
                                <span>
                                    <strong>Best Performer:</strong> {bestPerformer.symbol} is leading with <span className="text-emerald-600 dark:text-emerald-400 font-bold">+{bestPerformer.unrealizedPLPercent.toFixed(1)}%</span> return.
                                </span>
                            </p>
                         )}
                         {displayHoldings.some(h => h.diff > 5) && (
                            <p className="flex items-center gap-2">
                                <AlertTriangle size={16} className="text-amber-500" />
                                <span>
                                    <strong>Rebalance Alert:</strong> Some assets are >5% over your target allocation. Consider trimming.
                                </span>
                            </p>
                         )}
                     </div>
                 </div>
             </div>
         </div>
      )}

    </div>
  );
};

export default Holdings;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import Layout from './components/Layout';
import Dashboard from './components/Dashboard';
import Holdings from './components/Holdings';
import Reports from './components/Reports';
import History from './components/History';
import GoalModal from './components/GoalModal';
import { Transaction, TransactionType, AssetClass, Holding, Portfolio, FinancialGoal } from './types';
import { calculateHoldings, calculatePortfolioHistory, generateId, formatCurrency, formatNumber } from './utils';
import { X, Save, TrendingUp, TrendingDown, DollarSign, Wallet, Calendar, GitFork, AlertCircle, ArrowRight, Trash2, Zap, Calculator, Search, Clock, PlusCircle, MinusCircle, RefreshCcw, Split, Hash, ChevronDown, ArrowRightCircle, Globe, CheckCircle2, FileText, Banknote, Percent, Info } from 'lucide-react';
import { Spinner } from './components/LoadingSkeletons';

const POPULAR_SYMBOLS = [
  'AAPL', 'MSFT', 'GOOGL', 'AMZN', 'NVDA', 'TSLA', 'META', 'BRK.B', 'V', 'JNJ', 'WMT', 'JPM', // Tech/Blue Chip
  'VOO', 'VTI', 'QQQ', 'IVV', 'SCHD', 'JEPI', 'VUG', 'VTV', // ETFs
  'BTC', 'ETH', 'SOL', 'USDT', 'BNB', 'XRP', 'ADA' // Crypto
];

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState('dashboard');
  const [isAddModalOpen, setIsAddModalOpen] = useState(false);
  const [editingTransaction, setEditingTransaction] = useState<Partial<Transaction> | null>(null);

  // Persistence for better UX
  const [lastTxDate, setLastTxDate] = useState<string>(() => localStorage.getItem('lastTxDate') || new Date().toISOString().split('T')[0]);

  // Goal Modal State
  const [isGoalModalOpen, setIsGoalModalOpen] = useState(false);

  // --- CONFIRMATION MODAL STATE ---
  const [confirmConfig, setConfirmConfig] = useState<{
    isOpen: boolean;
    title: string;
    message: string;
    onConfirm: () => void;
  }>({
    isOpen: false,
    title: '',
    message: '',
    onConfirm: () => {},
  });

  // --- PORTFOLIO MANAGEMENT STATE ---
  const [portfolios, setPortfolios] = useState<Portfolio[]>(() => {
    const saved = localStorage.getItem('portfolios');
    if (saved) return JSON.parse(saved);
    const legacyTx = localStorage.getItem('transactions');
    if (legacyTx) return [{ id: 'default', name: 'Main Portfolio' }];
    return [{ id: generateId(), name: 'My First Portfolio' }];
  });

  const [activePortfolioId, setActivePortfolioId] = useState<string>(() => {
    const saved = localStorage.getItem('activePortfolioId');
    const portfolios = JSON.parse(localStorage.getItem('portfolios') || '[]');
    if (saved && portfolios.some((p: Portfolio) => p.id === saved)) return saved;
    return portfolios.length > 0 ? portfolios[0].id : 'default';
  });

  // --- DATA STATE (Per Portfolio) - Synchronous Initialization ---
  const [transactions, setTransactions] = useState<Transaction[]>(() => {
    const key = `transactions_${activePortfolioId}`;
    const saved = localStorage.getItem(key);
    if (saved) return JSON.parse(saved);
    if (activePortfolioId === 'default') {
      const legacy = localStorage.getItem('transactions');
      if (legacy) return JSON.parse(legacy);
    }
    return [];
  });

  const [prices, setPrices] = useState<Record<string, number>>(() => {
    const key = `prices_${activePortfolioId}`;
    const saved = localStorage.getItem(key);
    if (saved) return JSON.parse(saved);
    if (activePortfolioId === 'default') {
      const legacy = localStorage.getItem('prices');
      if (legacy) return JSON.parse(legacy);
    }
    return {};
  });

  const [targets, setTargets] = useState<Record<string, number>>(() => {
    const key = `targets_${activePortfolioId}`;
    const saved = localStorage.getItem(key);
    if (saved) {
       try {
         // Fix: Handle null or invalid JSON gracefully
         const parsed = JSON.parse(saved);
         return parsed || {};
       } catch (e) {
         return {};
       }
    }
    return {};
  });

  const [goals, setGoals] = useState<FinancialGoal[]>(() => {
    const key = `goals_${activePortfolioId}`;
    const saved = localStorage.getItem(key);
    if (saved) return JSON.parse(saved);

    let legacyGoal = 100000;
    const legacyKey = `financialGoal_${activePortfolioId}`;
    const savedLegacy = localStorage.getItem(legacyKey);
    if (savedLegacy) legacyGoal = parseFloat(savedLegacy);
    else if (activePortfolioId === 'default' && localStorage.getItem('financialGoal')) legacyGoal = parseFloat(localStorage.getItem('financialGoal')!);

    return [{ id: generateId(), targetAmount: legacyGoal, startDate: new Date().toISOString(), isAchieved: false, notes: 'Initial Goal' }];
  });

  const [isDataLoaded, setIsDataLoaded] = useState(true);
  const [isLoading, setIsLoading] = useState(false);
  const isFirstMount = useRef(true);

  // --- PERSISTENCE ---
  useEffect(() => { localStorage.setItem('portfolios', JSON.stringify(portfolios)); }, [portfolios]);
  useEffect(() => { localStorage.setItem('activePortfolioId', activePortfolioId); }, [activePortfolioId]);

  useEffect(() => {
    if (isFirstMount.current) { isFirstMount.current = false; return; }
    setIsLoading(true);
    setIsDataLoaded(false);
    const loadData = () => {
        const txKey = `transactions_${activePortfolioId}`;
        const pricesKey = `prices_${activePortfolioId}`;
        const goalsKey = `goals_${activePortfolioId}`;
        const targetsKey = `targets_${activePortfolioId}`;

        const savedTx = localStorage.getItem(txKey);
        setTransactions(savedTx ? JSON.parse(savedTx) : []);

        const savedPrices = localStorage.getItem(pricesKey);
        setPrices(savedPrices ? JSON.parse(savedPrices) : {});

        const savedTargets = localStorage.getItem(targetsKey);
        // Safe parsing for targets
        try {
            const parsedTargets = savedTargets ? JSON.parse(savedTargets) : {};
            setTargets(parsedTargets || {});
        } catch {
            setTargets({});
        }

        const savedGoals = localStorage.getItem(goalsKey);
        setGoals(savedGoals ? JSON.parse(savedGoals) : []); 

        setIsDataLoaded(true);
        setTimeout(() => setIsLoading(false), 500);
    };
    requestAnimationFrame(loadData);
  }, [activePortfolioId]);

  useEffect(() => { if (isDataLoaded) localStorage.setItem(`transactions_${activePortfolioId}`, JSON.stringify(transactions)); }, [transactions, activePortfolioId, isDataLoaded]);
  useEffect(() => { if (isDataLoaded) localStorage.setItem(`prices_${activePortfolioId}`, JSON.stringify(prices)); }, [prices, activePortfolioId, isDataLoaded]);
  useEffect(() => { if (isDataLoaded) localStorage.setItem(`targets_${activePortfolioId}`, JSON.stringify(targets)); }, [targets, activePortfolioId, isDataLoaded]);
  useEffect(() => { if (isDataLoaded) localStorage.setItem(`goals_${activePortfolioId}`, JSON.stringify(goals)); }, [goals, activePortfolioId, isDataLoaded]);

  // --- CALCULATIONS ---
  const holdings = useMemo(() => calculateHoldings(transactions, prices, targets), [transactions, prices, targets]);
  const chartData = useMemo(() => calculatePortfolioHistory(transactions, prices), [transactions, prices]);
  const investedAmount = transactions.reduce((sum, t) => {
    if (t.type === TransactionType.DEPOSIT) return sum + (t.price || 0);
    if (t.type === TransactionType.WITHDRAW) return sum - (t.price || 0);
    return sum;
  }, 0);
  const cashBalance = useMemo(() => {
    let balance = 0;
    transactions.forEach(t => {
      if (t.type === TransactionType.DEPOSIT) balance += (t.price || 0);
      if (t.type === TransactionType.WITHDRAW) balance -= (t.price || 0);
      if (t.type === TransactionType.BUY) balance -= (t.price! * t.shares!) + (t.fee || 0);
      if (t.type === TransactionType.SELL) balance += (t.price! * t.shares!) - (t.fee || 0);
      if (t.type === TransactionType.DIVIDEND) balance += (t.price || 0);
    });
    return balance;
  }, [transactions]);
  const portfolioValue = holdings.reduce((sum, h) => sum + h.marketValue, 0);
  const totalNetWorth = portfolioValue + cashBalance;
  const activeGoal = useMemo(() => goals.find(g => !g.endDate) || { targetAmount: 100000 } as FinancialGoal, [goals]);

  // --- HANDLERS ---
  const handleOpenAddModal = (initialState?: Partial<Transaction>) => { 
      setEditingTransaction(initialState || null); 
      setIsAddModalOpen(true); 
  };
  const handleOpenEditModal = (tx: Transaction) => { setEditingTransaction(tx); setIsAddModalOpen(true); };

  const handleSaveTransaction = (tx: Transaction) => {
    return new Promise<void>((resolve) => {
      if (editingTransaction && editingTransaction.id) {
         setTransactions(prev => prev.map(t => t.id === tx.id ? tx : t));
      } else {
         setTransactions(prev => [...prev, tx]);
      }

      // Update price reference
      if ((tx.type === TransactionType.BUY || tx.type === TransactionType.SELL) && tx.symbol && tx.price) {
        setPrices(prev => ({...prev, [tx.symbol!]: tx.price!}));
      }

      // Update Last Used Date Persistence
      setLastTxDate(tx.date);
      localStorage.setItem('lastTxDate', tx.date);

      setIsAddModalOpen(false); 
      setEditingTransaction(null); 
      resolve();
    });
  };

  const handleUpdatePrice = (symbol: string, newPrice: number) => setPrices(prev => ({ ...prev, [symbol]: newPrice }));
  const handleUpdateTarget = (symbol: string, target: number) => setTargets(prev => ({ ...prev, [symbol]: target }));

  const handleDeleteTransaction = (id: string) => {
    setTransactions(prev => prev.filter(t => t.id !== id));
    if (editingTransaction && editingTransaction.id === id) { setIsAddModalOpen(false); setEditingTransaction(null); }
  };
  const handleRequestDelete = (id: string) => {
      setConfirmConfig({ isOpen: true, title: 'Delete Transaction', message: 'Permanently remove this record?', onConfirm: () => { handleDeleteTransaction(id); setConfirmConfig(prev => ({ ...prev, isOpen: false })); } });
  };
  const handleImportTransactions = (importedTxs: Transaction[]) => {
      setTransactions(prev => {
          const currentMap = new Map(prev.map(t => [t.id, t]));
          importedTxs.forEach(t => { currentMap.set(t.id, t); });
          return Array.from(currentMap.values());
      });
  };

  // Portfolios
  const handleCreatePortfolio = (name: string) => { const newId = generateId(); setPortfolios([...portfolios, { id: newId, name }]); setActivePortfolioId(newId); };
  const handleRenamePortfolio = (id: string, newName: string) => { setPortfolios(prev => prev.map(p => p.id === id ? { ...p, name: newName } : p)); };
  const handleDeletePortfolio = (id: string) => {
    if (portfolios.length <= 1) { alert("Cannot delete last portfolio"); return; }
    setConfirmConfig({
        isOpen: true, title: 'Delete Portfolio', message: 'Delete entire portfolio and all data?', 
        onConfirm: () => {
             localStorage.removeItem(`transactions_${id}`); localStorage.removeItem(`prices_${id}`); localStorage.removeItem(`goals_${id}`); localStorage.removeItem(`targets_${id}`);
             const newPortfolios = portfolios.filter(p => p.id !== id); setPortfolios(newPortfolios);
             if (activePortfolioId === id) setActivePortfolioId(newPortfolios[0].id);
             setConfirmConfig(prev => ({ ...prev, isOpen: false }));
        }
    });
  };

  // Goals
  const handleSetNewGoal = (targetAmount: number, notes: string) => {
    const now = new Date().toISOString();
    setGoals(prev => [...prev.map(g => !g.endDate ? { ...g, endDate: now, isAchieved: totalNetWorth >= g.targetAmount } : g), { id: generateId(), targetAmount, startDate: now, isAchieved: false, notes }]);
  };
  const handleEditGoal = (updatedGoal: FinancialGoal) => setGoals(prev => prev.map(g => g.id === updatedGoal.id ? updatedGoal : g));
  const handleDeleteGoal = (id: string) => setGoals(prev => prev.filter(g => g.id !== id));

  return (
    <Layout 
      activeTab={activeTab} setActiveTab={setActiveTab} onOpenAddModal={() => handleOpenAddModal()}
      portfolios={portfolios} activePortfolioId={activePortfolioId} onSwitchPortfolio={setActivePortfolioId}
      onCreatePortfolio={handleCreatePortfolio} onRenamePortfolio={handleRenamePortfolio} onDeletePortfolio={handleDeletePortfolio}
    >
      <div key={activePortfolioId} className="h-full">
        {activeTab === 'dashboard' && <Dashboard isLoading={isLoading} holdings={holdings} transactions={transactions} financialGoal={activeGoal.targetAmount} onOpenGoalModal={() => setIsGoalModalOpen(true)} investedAmount={investedAmount} cashBalance={cashBalance} portfolioValue={portfolioValue} chartData={chartData} />}
        {activeTab === 'holdings' && (
            <Holdings 
                isLoading={isLoading} 
                holdings={holdings} 
                transactions={transactions} 
                cashBalance={cashBalance}
                onUpdatePrice={handleUpdatePrice} 
                onUpdateTarget={handleUpdateTarget} 
                onTrade={(symbol, type) => handleOpenAddModal({ symbol, type })}
            />
        )}
        {activeTab === 'history' && <History isLoading={isLoading} transactions={transactions} onDelete={handleRequestDelete} onEdit={handleOpenEditModal} onAdd={handleOpenAddModal} onImport={handleImportTransactions} />}
        {activeTab === 'reports' && <Reports isLoading={isLoading} transactions={transactions} holdings={holdings} currentPortfolioValue={portfolioValue + cashBalance} chartData={chartData} />}
      </div>

      {isAddModalOpen && (
        <div className="fixed inset-0 z-50 flex items-end sm:items-center justify-center sm:p-4">
          <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-sm animate-fade-in" onClick={() => setIsAddModalOpen(false)}></div>
          <div className="relative bg-white dark:bg-slate-900 w-full max-w-2xl rounded-t-3xl sm:rounded-3xl shadow-2xl overflow-hidden animate-slide-up flex flex-col max-h-[90dvh]">
            <AddTransactionForm 
              onClose={() => setIsAddModalOpen(false)} 
              onSave={handleSaveTransaction} 
              onDelete={handleRequestDelete} 
              cashBalance={cashBalance} 
              holdings={holdings} 
              prices={prices} 
              transactions={transactions} 
              initialData={editingTransaction as Transaction | null}
              defaultDate={lastTxDate}
            />
          </div>
        </div>
      )}

      <GoalModal isOpen={isGoalModalOpen} onClose={() => setIsGoalModalOpen(false)} goals={goals} currentNetWorth={totalNetWorth} onSetGoal={handleSetNewGoal} onEditGoal={handleEditGoal} onDeleteGoal={handleDeleteGoal} />

      {confirmConfig.isOpen && (
        <div className="fixed inset-0 z-[70] flex items-center justify-center p-4 animate-fade-in">
          <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-sm" onClick={() => setConfirmConfig(prev => ({ ...prev, isOpen: false }))}></div>
          <div className="relative bg-white dark:bg-slate-900 rounded-2xl shadow-2xl w-full max-w-sm overflow-hidden animate-zoom-in p-6 text-center">
              <Trash2 size={40} className="mx-auto text-rose-500 mb-4" />
              <h3 className="text-lg font-bold text-slate-900 dark:text-white mb-2">{confirmConfig.title}</h3>
              <p className="text-sm text-slate-500 dark:text-slate-400 mb-6">{confirmConfig.message}</p>
              <div className="flex space-x-3">
                <button onClick={() => setConfirmConfig(prev => ({ ...prev, isOpen: false }))} className="flex-1 py-3 rounded-xl font-bold bg-slate-100 dark:bg-slate-800 text-slate-600 dark:text-slate-400">Cancel</button>
                <button onClick={confirmConfig.onConfirm} className="flex-1 py-3 rounded-xl font-bold bg-rose-600 text-white shadow-lg shadow-rose-600/20">Delete</button>
              </div>
          </div>
        </div>
      )}
    </Layout>
  );
};

interface AddTransactionFormProps {
  onClose: () => void;
  onSave: (t: Transaction) => Promise<void>;
  onDelete?: (id: string) => void;
  cashBalance: number;
  holdings: Holding[];
  prices: Record<string, number>;
  transactions: Transaction[];
  initialData: Transaction | null;
  defaultDate: string;
}

const AddTransactionForm: React.FC<AddTransactionFormProps> = ({ onClose, onSave, onDelete, cashBalance, holdings, prices, transactions, initialData, defaultDate }) => {
  const [step, setStep] = useState<'input' | 'review'>('input');

  const [type, setType] = useState<TransactionType>(TransactionType.BUY);
  const [date, setDate] = useState(defaultDate);
  const [symbol, setSymbol] = useState('');
  const [shares, setShares] = useState('');
  const [price, setPrice] = useState(''); // Price per share
  const [totalAmount, setTotalAmount] = useState(''); // Total transaction value
  const [fee, setFee] = useState('');
  const [assetClass, setAssetClass] = useState<AssetClass>(AssetClass.STOCK);
  const [exchangeRate, setExchangeRate] = useState(''); 
  const [notes, setNotes] = useState('');
  const [error, setError] = useState<string | null>(null);
  const [isSaving, setIsSaving] = useState(false);

  const [showSuggestions, setShowSuggestions] = useState(false);
  const wrapperRef = useRef<HTMLDivElement>(null);
  const notesRef = useRef<HTMLTextAreaElement>(null);

  // Validation logic helpers
  const needsSymbol = [TransactionType.BUY, TransactionType.SELL, TransactionType.DIVIDEND, TransactionType.SPLIT].includes(type);
  const needsShares = [TransactionType.BUY, TransactionType.SELL, TransactionType.SPLIT].includes(type);
  const needsPrice = type !== TransactionType.SPLIT;

  // FX Rate is relevant for: Deposits, Withdrawals, and Dividends (Foreign income)
  const hasExchangeRate = type === TransactionType.DEPOSIT || type === TransactionType.WITHDRAW || type === TransactionType.DIVIDEND;
  const isFunding = type === TransactionType.DEPOSIT || type === TransactionType.WITHDRAW;

  // Effects (Initialization, Auto-fill, Calculation)
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => { if (wrapperRef.current && !wrapperRef.current.contains(event.target as Node)) setShowSuggestions(false); };
    document.addEventListener("mousedown", handleClickOutside); return () => document.removeEventListener("mousedown", handleClickOutside);
  }, []);

  useEffect(() => {
    if (initialData) {
      if (initialData.type) setType(initialData.type);
      if (initialData.date) setDate(initialData.date);
      if (initialData.symbol) setSymbol(initialData.symbol);
      if (initialData.shares) setShares(initialData.shares.toString());
      if (initialData.price) setPrice(initialData.price.toString());
      if (initialData.fee) setFee(initialData.fee.toString());
      if (initialData.assetClass) setAssetClass(initialData.assetClass);
      if (initialData.exchangeRate) setExchangeRate(initialData.exchangeRate.toString());
      if (initialData.notes) setNotes(initialData.notes);

      if (initialData.shares && initialData.price && (initialData.type === TransactionType.BUY || initialData.type === TransactionType.SELL)) {
         setTotalAmount((initialData.shares * initialData.price).toFixed(2));
      } else if (initialData.price) {
          setTotalAmount(initialData.price.toString());
      }
    }
  }, [initialData]);

  // Auto-fill price from holdings or market data when symbol changes (and no data set yet)
  useEffect(() => {
    if (!initialData && symbol && !price && !totalAmount) {
       const h = holdings.find(h => h.symbol === symbol.toUpperCase());
       if (h) { setAssetClass(h.assetClass); if (h.currentPrice > 0) setPrice(h.currentPrice.toString()); }
       else { const kp = prices[symbol.toUpperCase()]; if (kp) setPrice(kp.toString()); }
    }
  }, [symbol]);

  // --- Real-time Calculation Handlers ---
  const handleSharesChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const val = e.target.value;
    setShares(val);
    const s = parseFloat(val);
    const p = parseFloat(price);
    if (!isNaN(s) && !isNaN(p)) {
        setTotalAmount((s * p).toFixed(2));
    }
  };

  const handlePriceChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const val = e.target.value;
    setPrice(val);
    const p = parseFloat(val);
    const s = parseFloat(shares);
    // If we have shares, calc total
    if (!isNaN(p) && !isNaN(s)) {
        setTotalAmount((s * p).toFixed(2));
    } 
    // If we have total but no shares, calc shares? (Inverse flow)
    else if (!isNaN(p) && totalAmount && !shares) {
        const t = parseFloat(totalAmount);
        if (!isNaN(t) && p !== 0) setShares((t/p).toFixed(4));
    }
  };

  const handleTotalChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const val = e.target.value;
    setTotalAmount(val);
    const t = parseFloat(val);
    const p = parseFloat(price);
    // Standard: Total / Price = Shares
    if (!isNaN(t) && !isNaN(p) && p !== 0) {
        setShares((t / p).toFixed(4));
    }
  };

  // --- Auto-complete Logic ---
  const allSymbols = useMemo(() => {
    const fromHoldings = holdings.map(h => h.symbol);
    const fromHistory = transactions.map(t => t.symbol).filter(s => s) as string[];
    // Unique combined list
    return Array.from(new Set([...fromHoldings, ...fromHistory, ...POPULAR_SYMBOLS])).sort();
  }, [holdings, transactions]);

  const suggestions = useMemo(() => {
    if (!symbol) return [];
    const inputUpper = symbol.toUpperCase();
    return allSymbols.filter(s => s.includes(inputUpper)).slice(0, 6);
  }, [symbol, allSymbols]);

  // Max Button Handlers
  const handleMax = () => {
    const p = parseFloat(price);
    if (type === TransactionType.BUY) {
        if (p > 0) {
            const maxAmt = Math.max(0, cashBalance);
            setTotalAmount(maxAmt.toFixed(2));
            setShares((maxAmt / p).toFixed(4));
        } else {
            setTotalAmount(cashBalance.toFixed(2));
        }
    } else if (type === TransactionType.SELL) {
        const holding = holdings.find(h => h.symbol === symbol.toUpperCase());
        if (holding) {
            setShares(holding.shares.toString());
            if (p > 0) setTotalAmount((holding.shares * p).toFixed(2));
        }
    }
  };

  // IMPACT CALCULATIONS FOR SUMMARY
  const currentCashImpact = useMemo(() => {
     const qty = parseFloat(shares) || 0;
     const unitPrice = parseFloat(price) || 0;
     const feeVal = parseFloat(fee) || 0;
     const amt = parseFloat(totalAmount) || 0;

     if (type === TransactionType.BUY) return -((qty * unitPrice) + feeVal);
     if (type === TransactionType.SELL) return ((qty * unitPrice) - feeVal);
     if (type === TransactionType.DEPOSIT) return amt;
     if (type === TransactionType.WITHDRAW) return -amt;
     if (type === TransactionType.DIVIDEND) return amt;
     return 0;
  }, [type, shares, price, fee, totalAmount]);

  const originalCashImpact = useMemo(() => {
    if (!initialData) return 0;
    const qty = initialData.shares || 0;
    const unitPrice = initialData.price || 0;
    const feeVal = initialData.fee || 0;

    if (initialData.type === TransactionType.BUY) return -((qty * unitPrice) + feeVal);
    if (initialData.type === TransactionType.SELL) return ((qty * unitPrice) - feeVal);
    if (initialData.type === TransactionType.DEPOSIT) return unitPrice; 
    if (initialData.type === TransactionType.WITHDRAW) return -unitPrice;
    if (initialData.type === TransactionType.DIVIDEND) return unitPrice;
    return 0;
  }, [initialData]);

  const projectedCashBalance = cashBalance - originalCashImpact + currentCashImpact;
  const totalNetWorth = useMemo(() => {
     const invested = holdings.reduce((sum, h) => sum + h.marketValue, 0);
     return invested + cashBalance;
  }, [holdings, cashBalance]);

  const feePercentage = useMemo(() => {
     const feeVal = parseFloat(fee) || 0;
     const totalVal = parseFloat(totalAmount) || 0;
     if (feeVal > 0 && totalVal > 0) {
        return (feeVal / totalVal) * 100;
     }
     return 0;
  }, [fee, totalAmount]);

  // Validation
  const validate = () => {
    if (needsSymbol && !symbol) return "Asset Symbol is required.";
    if (!needsSymbol && !totalAmount) return "Amount is required.";
    if (type === TransactionType.SELL) {
        const holding = holdings.find(h => h.symbol === symbol.toUpperCase());
        const currentShares = holding ? holding.shares : 0;
        const originalShares = (initialData && initialData.type === TransactionType.SELL && initialData.symbol === symbol) ? (initialData.shares || 0) : 0;
        const available = currentShares + originalShares;
        if ((parseFloat(shares) || 0) > available) return `Insufficient shares. Owned: ${formatNumber(available)}. Selling: ${shares}.`;
    }
    if ((type === TransactionType.WITHDRAW || type === TransactionType.BUY) && projectedCashBalance < 0) {
        return "Insufficient funds. Transaction exceeds cash balance.";
    }
    return null;
  };

  const handleReview = (e: React.FormEvent) => {
      e.preventDefault();
      const errMsg = validate();
      if (errMsg) return setError(errMsg);
      setError(null);
      setStep('review');
  };

  const handleFinalSubmit = async () => {
    setIsSaving(true);
    await onSave({
      id: initialData && initialData.id ? initialData.id : generateId(),
      date, type, symbol: needsSymbol ? symbol.toUpperCase() : undefined,
      shares: needsShares ? parseFloat(shares) : undefined,
      // For types that don't need shares (Deposit, Withdraw, Dividend), use the total amount as price
      price: type === TransactionType.SPLIT ? 0 : (needsShares ? parseFloat(price) : parseFloat(totalAmount)),
      fee: (fee && (type === TransactionType.BUY || type === TransactionType.SELL)) ? parseFloat(fee) : undefined,
      assetClass: !needsSymbol ? AssetClass.CASH : assetClass,
      exchangeRate: exchangeRate ? parseFloat(exchangeRate) : 1, notes: notes || undefined
    });
    setIsSaving(false);
  };

  const getTypeConfig = (t: TransactionType) => {
    switch (t) {
        case TransactionType.BUY: return { color: 'emerald', icon: <TrendingUp size={16} /> }; // Green
        case TransactionType.DEPOSIT: return { color: 'orange', icon: <Wallet size={16} /> }; // Orange
        case TransactionType.SELL: return { color: 'rose', icon: <TrendingDown size={16} /> }; // Red
        case TransactionType.WITHDRAW: return { color: 'blue', icon: <Banknote size={16} /> }; // Blue
        case TransactionType.DIVIDEND: return { color: 'teal', icon: <DollarSign size={16} /> }; // Teal
        case TransactionType.SPLIT: return { color: 'purple', icon: <Split size={16} /> }; // Purple
        default: return { color: 'slate', icon: <CheckCircle2 size={16} /> };
    }
  }
  const theme = getTypeConfig(type);

  // SUMMARY BAR
  const summaryBox = useMemo(() => {
     const absImpact = Math.abs(currentCashImpact);
     const isPositiveFlow = currentCashImpact >= 0;
     const portfolioPercent = (totalNetWorth > 0) ? (absImpact / totalNetWorth) * 100 : 0;
     const impactColor = isPositiveFlow ? 'bg-emerald-500' : 'bg-rose-500';
     const impactTextColor = isPositiveFlow ? 'text-emerald-600' : 'text-rose-600';

     return (
         <div className="bg-slate-100 dark:bg-slate-800/80 rounded-2xl p-5 border border-slate-200 dark:border-slate-700 mt-4">
             <div className="flex justify-between items-start mb-4">
                 <div>
                    <p className="text-xs font-bold text-slate-500 uppercase tracking-wider">Net Cash Impact</p>
                    <h3 className={`text-2xl font-bold font-display ${impactTextColor}`}>
                        {isPositiveFlow ? '+' : '-'}{formatCurrency(absImpact)}
                    </h3>
                    <p className="text-[10px] text-slate-400 mt-1 font-medium flex items-center">
                        <Percent size={10} className="mr-1"/>
                        ≈ {portfolioPercent.toFixed(1)}% of Total Portfolio
                    </p>
                 </div>
                 <div className="text-right">
                    <p className="text-xs font-bold text-slate-500 uppercase tracking-wider">Projected Cash</p>
                    <p className="text-xl font-bold font-mono text-slate-800 dark:text-slate-200">{formatCurrency(projectedCashBalance)}</p>
                 </div>
             </div>

             {/* Progress Bar */}
             <div className="relative h-2.5 bg-slate-200 dark:bg-slate-700 rounded-full overflow-hidden">
                 <div className="absolute top-0 left-0 h-full bg-slate-400 dark:bg-slate-500 transition-all" style={{ width: '100%' }}></div>
                 {projectedCashBalance < cashBalance && (
                    <div className={`absolute top-0 right-0 h-full ${impactColor} transition-all animate-pulse`} style={{ width: `${((cashBalance - projectedCashBalance)/cashBalance)*100}%` }}></div>
                 )}
                 {projectedCashBalance > cashBalance && (
                     <div className={`absolute top-0 left-0 h-full ${impactColor} transition-all`} style={{ width: '100%' }}></div>
                 )}
             </div>
             <div className="flex justify-between text-[10px] text-slate-400 mt-1.5 font-bold uppercase">
                 <span>Before: {formatCurrency(cashBalance)}</span>
                 <span>After: {formatCurrency(projectedCashBalance)}</span>
             </div>
         </div>
     )
  }, [currentCashImpact, projectedCashBalance, cashBalance, totalNetWorth]);

  const handleNoteChange = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
     setNotes(e.target.value);
     e.target.style.height = 'auto';
     e.target.style.height = `${e.target.scrollHeight}px`;
  }

  // RENDER: REVIEW STEP
  if (step === 'review') {
      return (
          <div className="flex flex-col h-full bg-white dark:bg-slate-900">
             <div className="p-6 text-center border-b border-slate-100 dark:border-slate-800">
                <div className={`w-16 h-16 mx-auto rounded-full bg-${theme.color}-100 dark:bg-${theme.color}-900/30 text-${theme.color}-600 dark:text-${theme.color}-400 flex items-center justify-center mb-4 shadow-lg shadow-${theme.color}-500/20`}>
                   {theme.icon}
                </div>
                <h3 className="text-xl font-display font-bold text-slate-900 dark:text-white">Review Transaction</h3>
                <p className="text-sm text-slate-500">Please confirm details before saving.</p>
             </div>

             <div className="flex-1 overflow-y-auto p-6 space-y-6">
                 {/* Details Card */}
                 <div className="bg-slate-50 dark:bg-slate-800/50 rounded-2xl p-5 border border-slate-200 dark:border-slate-700 space-y-4">
                     <div className="flex justify-between border-b border-slate-200 dark:border-slate-700 pb-2">
                        <span className="text-sm text-slate-500">Date</span>
                        <span className="text-sm font-bold text-slate-900 dark:text-white">{date}</span>
                     </div>
                     <div className="flex justify-between border-b border-slate-200 dark:border-slate-700 pb-2">
                        <span className="text-sm text-slate-500">Type</span>
                        <span className={`text-sm font-bold uppercase text-${theme.color}-600`}>{type}</span>
                     </div>
                     {needsSymbol && (
                         <div className="flex justify-between border-b border-slate-200 dark:border-slate-700 pb-2">
                            <span className="text-sm text-slate-500">Asset</span>
                            <span className="text-sm font-bold text-slate-900 dark:text-white">{symbol} <span className="text-xs text-slate-400 font-normal">({assetClass})</span></span>
                         </div>
                     )}
                     <div className="flex justify-between border-b border-slate-200 dark:border-slate-700 pb-2">
                        <span className="text-sm text-slate-500">Total Amount</span>
                        <span className="text-lg font-bold text-slate-900 dark:text-white">{formatCurrency(parseFloat(totalAmount))}</span>
                     </div>
                     {needsShares && (
                        <div className="flex justify-between pt-1">
                            <span className="text-xs text-slate-400">Details</span>
                            <span className="text-xs text-slate-500">{shares} units @ {formatCurrency(parseFloat(price))}</span>
                        </div>
                     )}
                 </div>

                 {projectedCashBalance < 0 && (
                     <div className="bg-rose-50 text-rose-600 p-4 rounded-xl text-sm font-bold flex items-center">
                         <AlertCircle size={20} className="mr-3 shrink-0" />
                         WARNING: This transaction will result in a negative cash balance.
                     </div>
                 )}
             </div>

             <div className="p-6 border-t border-slate-100 dark:border-slate-800 flex gap-4">
                 <button onClick={() => setStep('input')} className="flex-1 py-3 rounded-xl font-bold bg-slate-100 dark:bg-slate-800 text-slate-600 dark:text-slate-300 hover:bg-slate-200 dark:hover:bg-slate-700 transition-colors">
                    Back to Edit
                 </button>
                 <button onClick={handleFinalSubmit} disabled={isSaving} className={`flex-1 py-3 rounded-xl font-bold text-white shadow-xl flex items-center justify-center space-x-2 bg-${theme.color}-600 hover:bg-${theme.color}-700 transition-all`}>
                    {isSaving ? <Spinner className="text-white" /> : (
                        <>
                            <CheckCircle2 size={18} />
                            <span>Confirm & Save</span>
                        </>
                    )}
                 </button>
             </div>
          </div>
      )
  }

  // RENDER: INPUT STEP
  return (
    <>
      <div className="shrink-0 px-6 py-4 border-b border-slate-100 dark:border-slate-800 flex justify-between items-center bg-white dark:bg-slate-900">
          <h3 className="text-lg font-display font-bold text-slate-900 dark:text-white">{initialData?.id ? 'Edit Transaction' : 'New Transaction'}</h3>
          <button onClick={onClose} className="bg-slate-100 dark:bg-slate-800 p-2 rounded-full text-slate-500 hover:text-slate-800 dark:hover:text-white transition-colors"><X size={20} /></button>
      </div>

      <form onSubmit={handleReview} className="flex-1 overflow-y-auto min-h-0 p-6 custom-scrollbar bg-white dark:bg-slate-900">

        {/* 1. Transaction Type Selector with Icons */}
        <div className="mb-6">
           <label className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-3 block">Transaction Type</label>
           <div className="grid grid-cols-3 sm:grid-cols-6 gap-2">
              {[TransactionType.BUY, TransactionType.SELL, TransactionType.DEPOSIT, TransactionType.WITHDRAW, TransactionType.DIVIDEND, TransactionType.SPLIT].map(t => {
                 const isActive = type === t;
                 const config = getTypeConfig(t);
                 return (
                   <button
                      key={t} type="button" onClick={() => setType(t)}
                      className={`flex flex-col items-center justify-center py-2.5 px-1 rounded-xl text-[10px] sm:text-xs font-bold transition-all border ${
                         isActive 
                         ? `border-transparent bg-${config.color}-500 text-white shadow-md shadow-${config.color}-500/20 transform scale-105` 
                         : 'bg-white dark:bg-slate-800 border-slate-200 dark:border-slate-700 text-slate-500 dark:text-slate-400 hover:border-slate-300 dark:hover:border-slate-600 hover:bg-slate-50'
                      }`}
                   >
                      <div className="mb-1">{config.icon}</div>
                      {t}
                   </button>
                 )
              })}
           </div>
        </div>

        <div className="grid md:grid-cols-2 gap-8">
            {/* LEFT COLUMN: DETAILS */}
            <div className="space-y-5">
                <div className="flex items-center space-x-2 text-slate-800 dark:text-slate-200 border-b border-slate-100 dark:border-slate-800 pb-2">
                    <FileText size={18} />
                    <h4 className="font-bold text-sm uppercase tracking-wide">Transaction Details</h4>
                </div>

                <div>
                   <label className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-1.5 block">Date</label>
                   <div className="relative">
                      <Calendar className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={16} />
                      <input type="date" value={date} onChange={e => setDate(e.target.value)} className="w-full pl-10 pr-4 py-2.5 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl font-medium text-sm focus:ring-2 focus:ring-blue-500 outline-none transition-all" />
                   </div>
                </div>

                {needsSymbol && (
                    <div className="relative z-20" ref={wrapperRef}>
                        <label className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-1.5 block">Asset Symbol</label>
                        <div className="relative group">
                            <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400 group-focus-within:text-blue-500 transition-colors" size={18} />
                            <input 
                               type="text" placeholder="e.g. AAPL" value={symbol} 
                               onChange={e => { setSymbol(e.target.value); setShowSuggestions(true); }}
                               onFocus={() => setShowSuggestions(true)}
                               className="w-full pl-10 pr-4 py-3 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl text-lg font-bold uppercase tracking-wide focus:ring-2 focus:ring-blue-500 focus:bg-white dark:focus:bg-slate-800 outline-none transition-all"
                            />
                             {showSuggestions && suggestions.length > 0 && (
                                <div className="absolute top-full left-0 right-0 mt-2 bg-white dark:bg-slate-800 rounded-xl shadow-xl border border-slate-100 dark:border-slate-700 overflow-hidden z-50 animate-fade-in max-h-60 overflow-y-auto custom-scrollbar">
                                    <div className="px-3 py-2 bg-slate-50 dark:bg-slate-900/50 text-[10px] uppercase font-bold text-slate-400">Suggestions</div>
                                    {suggestions.map(s => (
                                        <div key={s} onMouseDown={(e) => { e.preventDefault(); setSymbol(s); setShowSuggestions(false); }} className="px-4 py-3 hover:bg-blue-50 dark:hover:bg-blue-900/20 cursor-pointer font-bold text-slate-700 dark:text-slate-200 flex justify-between items-center text-sm border-b border-slate-50 dark:border-slate-700/50 last:border-0 group">
                                           <span>{s}</span>
                                           <span className="text-xs text-blue-500 font-normal opacity-0 group-hover:opacity-100 transition-opacity flex items-center">
                                              Use <ArrowRightCircle size={12} className="ml-1"/>
                                           </span>
                                        </div>
                                    ))}
                                </div>
                            )}
                        </div>
                    </div>
                 )}

                 {needsSymbol && (
                    <div>
                        <label className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-1.5 block">Asset Class</label>
                        <select value={assetClass} onChange={e => setAssetClass(e.target.value as AssetClass)} className="w-full px-4 py-2.5 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl font-medium text-sm outline-none focus:ring-2 focus:ring-blue-500 transition-all cursor-pointer">
                            {Object.values(AssetClass).filter(a => a !== AssetClass.CASH).map(a => <option key={a} value={a}>{a}</option>)}
                        </select>
                    </div>
                 )}
            </div>

            {/* RIGHT COLUMN: FINANCIALS */}
            <div className="space-y-5">
