const GrowthView: React.FC<{ transactions: Transaction[], holdings: Holding[], currentPortfolioValue: number, chartData: ChartDataPoint[] }> = ({ transactions, holdings, currentPortfolioValue, chartData }) => {
   const [returnRange, setReturnRange] = useState<'6M' | '1Y' | 'ALL'>('ALL');

   const { netFundingUSD } = useMemo(() => calculateFundingStats(transactions), [transactions]);
   const monthlyReturns = useMemo(() => calculateMonthlyReturns(chartData), [chartData]);

   // --- KPI Calculations ---
   const totalROI = netFundingUSD > 0 ? ((currentPortfolioValue - netFundingUSD) / netFundingUSD) * 100 : 0;
   const maxDrawdown = useMemo(() => calculateMaxDrawdown(chartData), [chartData]);
   const winRate = useMemo(() => calculateWinRate(monthlyReturns), [monthlyReturns]);

   // Time in Market
   const firstTxDate = useMemo(() => {
       if(transactions.length === 0) return null;
       const sorted = [...transactions].sort((a, b) => new Date(a.date).getTime() - new Date(b.date).getTime());
       return new Date(sorted[0].date);
   }, [transactions]);

   const daysInMarket = useMemo(() => {
       if(!firstTxDate) return 0;
       const diffTime = Math.abs(new Date().getTime() - firstTxDate.getTime());
       return Math.ceil(diffTime / (1000 * 60 * 60 * 24)); 
   }, [firstTxDate]);

   const yearsInMarket = daysInMarket / 365.25;

   // CAGR (Simple Approximation)
   const cagr = useMemo(() => {
       if (yearsInMarket < 1 || netFundingUSD <= 0) return totalROI; // Fallback to ROI if < 1 year
       return (Math.pow(currentPortfolioValue / netFundingUSD, 1 / yearsInMarket) - 1) * 100;
   }, [currentPortfolioValue, netFundingUSD, yearsInMarket, totalROI]);

   // Benchmark Simulation (8% Annual Growth on Invested Capital)
   const enhancedChartData = useMemo(() => {
       return chartData.map(point => {
           const pointDate = point.date === 'Now' ? new Date() : new Date(point.date);
           const daysSinceStart = firstTxDate ? (pointDate.getTime() - firstTxDate.getTime()) / (1000 * 60 * 60 * 24) : 0;
           const years = daysSinceStart / 365.25;
           // Simple compounded benchmark: Invested * (1.08 ^ years)
           const benchmark = point.invested * Math.pow(1.08, years);
           return { ...point, benchmark };
       });
   }, [chartData, firstTxDate]);

   // Filtered Monthly Returns
   const displayedReturns = useMemo(() => {
       if (returnRange === 'ALL') return monthlyReturns;
       const months = returnRange === '6M' ? 6 : 12;
       return monthlyReturns.slice(-months);
   }, [monthlyReturns, returnRange]);

   const avgMonthlyReturn = displayedReturns.length > 0 
       ? displayedReturns.reduce((sum, m) => sum + m.value, 0) / displayedReturns.length 
       : 0;

   // Performance Breakdown
   const sortedHoldings = useMemo(() => {
       return [...holdings].sort((a, b) => b.unrealizedPL - a.unrealizedPL);
   }, [holdings]);

   if (chartData.length === 0) {
       return (
           <div className="flex flex-col items-center justify-center p-12 bg-slate-50 dark:bg-slate-800/50 rounded-3xl border-2 border-dashed border-slate-200 dark:border-slate-700">
               <Activity size={48} className="text-slate-300 mb-4" />
               <h3 className="text-lg font-bold text-slate-600 dark:text-slate-300">Not Enough Data</h3>
               <p className="text-slate-400 text-sm">Add transactions to generate growth reports.</p>
           </div>
       );
   }

   return (
      <div className="space-y-8 animate-slide-up">

         {/* 1. Summary Insight Row */}
         <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
             {[
                 { label: 'Total ROI', value: `${totalROI > 0 ? '+' : ''}${totalROI.toFixed(2)}%`, sub: 'All Time Return', icon: <TrendingUp size={18} />, color: totalROI >= 0 ? 'text-emerald-500' : 'text-rose-500' },
                 { label: 'CAGR', value: `${cagr.toFixed(2)}%`, sub: 'Annualized Growth', icon: <Activity size={18} />, color: 'text-blue-500' },
                 { label: 'Max Drawdown', value: `-${maxDrawdown.toFixed(2)}%`, sub: 'Peak to Trough', icon: <TrendingDown size={18} />, color: 'text-rose-500' },
                 { label: 'Win Rate', value: `${winRate.toFixed(0)}%`, sub: `${monthlyReturns.filter(m => m.value > 0).length} / ${monthlyReturns.length} Months`, icon: <Trophy size={18} />, color: 'text-amber-500' },
             ].map((item, idx) => (
                 <div key={idx} className="bg-white dark:bg-slate-800 p-5 rounded-2xl border border-slate-200 dark:border-slate-700 shadow-sm hover:shadow-md transition-shadow">
                     <div className="flex justify-between items-start mb-2">
                         <span className="text-xs font-bold text-slate-400 uppercase tracking-wider">{item.label}</span>
                         <div className={`p-1.5 rounded-lg bg-slate-50 dark:bg-slate-900 ${item.color}`}>{item.icon}</div>
                     </div>
                     <h3 className={`text-2xl font-display font-bold ${item.color === 'text-emerald-500' || item.color === 'text-rose-500' ? item.color : 'text-slate-900 dark:text-white'}`}>
                         {item.value}
                     </h3>
                     <p className="text-[10px] text-slate-400 mt-1 font-medium">{item.sub}</p>
                 </div>
             ))}
         </div>

         {/* 2. Wealth Growth Curve with Benchmark */}
         <div className="bg-white dark:bg-slate-800 p-6 md:p-8 rounded-3xl border border-slate-200 dark:border-slate-700 shadow-sm">
            <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center mb-8 gap-4">
                <div>
                    <h3 className="text-lg font-bold text-slate-900 dark:text-white flex items-center gap-2">
                        Wealth Growth Curve
                    </h3>
                    <p className="text-xs text-slate-500 dark:text-slate-400 mt-1">
                        Market Value vs. Cost Basis vs. Simulated Benchmark (8%)
                    </p>
                </div>
                <div className="flex items-center gap-4 text-xs font-bold">
                    <div className="flex items-center text-blue-500"><div className="w-2.5 h-2.5 bg-blue-500 rounded-full mr-2"></div> Market Value</div>
                    <div className="flex items-center text-slate-400"><div className="w-2.5 h-2.5 bg-slate-400/50 rounded-full mr-2"></div> Cost Basis</div>
                    <div className="flex items-center text-slate-300"><div className="w-2.5 h-2.5 bg-slate-200 rounded-full mr-2"></div> Benchmark</div>
                </div>
