                        <Line type="monotone" dataKey="benchmark" stroke="#cbd5e1" strokeWidth={2} dot={false} name="benchmark" opacity={0.7} />
                    </AreaChart>
                </ResponsiveContainer>
            </div>
         </div>

         {/* 3. Monthly Returns & Performance Attribution */}
         <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">

             {/* Monthly Returns */}
             <div className="bg-white dark:bg-slate-800 p-6 rounded-3xl border border-slate-200 dark:border-slate-700 shadow-sm flex flex-col">
