                            <XAxis dataKey="yearMonth" axisLine={false} tickLine={false} tick={{fill: '#94a3b8', fontSize: 10}} dy={10} minTickGap={20} tickFormatter={(val) => val.split('-')[1]} />
                            <YAxis hide />
                            <Tooltip cursor={{fill: 'transparent'}} content={<CustomTooltip formatter={(val: number) => `${val.toFixed(2)}%`} />} />
                            <ReferenceLine y={0} stroke="#e2e8f0" />
                            <Bar dataKey="value" radius={[4, 4, 4, 4]}>
