                         <tbody className="divide-y divide-slate-100 dark:divide-slate-700">
                             {sortedHoldings.map(h => (
                                 <tr key={h.symbol} className="group hover:bg-slate-50 dark:hover:bg-slate-700/30">
                                     <td className="py-3 font-bold text-slate-700 dark:text-slate-200 group-hover:text-blue-600 dark:group-hover:text-blue-400 transition-colors">
