const FundingView: React.FC<{ transactions: Transaction[], currentPortfolioValue: number }> = ({ transactions, currentPortfolioValue }) => {
    const stats = useMemo(() => calculateFundingStats(transactions), [transactions]);
    const { netFundingUSD, netFundingLocal, avgFxCost, fundingTxs } = stats;

    // Sort funding txs descending
    const sortedTxs = useMemo(() => [...fundingTxs].sort((a,b) => new Date(b.date).getTime() - new Date(a.date).getTime()), [fundingTxs]);

    if (fundingTxs.length === 0) {
        return <EmptyState message="No deposits or withdrawals yet." />;
    }

    // Chart Data: Cumulative Net Funding
    const cumulativeFundingData = useMemo(() => {
        let runningTotal = 0;
        const chronological = [...fundingTxs].sort((a,b) => new Date(a.date).getTime() - new Date(b.date).getTime());
        return chronological.map(tx => {
            const amount = tx.price || 0;
            if (tx.type === TransactionType.DEPOSIT) runningTotal += amount;
            else runningTotal -= amount;
            return {
                date: tx.date,
                netInvested: runningTotal
            };
        });
    }, [fundingTxs]);

    // Check if we should show FX details (if rate != 1)
    const showFx = avgFxCost > 0 && Math.abs(avgFxCost - 1) > 0.001;

    return (
        <div className="space-y-6 animate-slide-up">
            <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                <div className="bg-gradient-to-br from-blue-600 to-indigo-700 p-6 rounded-2xl text-white shadow-lg shadow-blue-500/20">
                    <p className="text-blue-100 text-xs font-bold uppercase tracking-wider mb-1">Net Invested Capital</p>
                    <h3 className="text-3xl font-display font-bold">{formatCurrency(netFundingUSD)}</h3>
                    <div className="mt-2 text-xs bg-white/20 w-fit px-2 py-1 rounded-lg backdrop-blur-sm">
                        Total Cash In - Total Cash Out
                    </div>
                </div>
                <KpiCard label="Portfolio Value" value={formatCurrency(currentPortfolioValue)} icon={<Wallet size={18} />} />
                <KpiCard 
                    label="All Time Return" 
                    value={formatCurrency(currentPortfolioValue - netFundingUSD)} 
                    icon={currentPortfolioValue >= netFundingUSD ? <TrendingUp size={18} /> : <TrendingDown size={18} />}
                    color={currentPortfolioValue >= netFundingUSD ? 'text-emerald-600' : 'text-rose-600'}
                />
            </div>

            {showFx && (
                <div className="bg-white dark:bg-slate-800 p-5 rounded-2xl border border-slate-200 dark:border-slate-700 shadow-sm flex flex-col md:flex-row gap-6">
                    <div className="flex items-center gap-3">
                        <div className="p-2 bg-indigo-50 dark:bg-indigo-900/30 text-indigo-600 dark:text-indigo-400 rounded-lg">
                            <Coins size={20} />
                        </div>
                        <div>
                            <p className="text-xs font-bold text-slate-500 uppercase tracking-wider">Avg Exchange Rate</p>
                            <p className="text-xl font-mono font-bold text-slate-900 dark:text-white">{avgFxCost.toFixed(4)}</p>
                        </div>
                    </div>
                    <div className="w-px bg-slate-200 dark:bg-slate-700 hidden md:block"></div>
                    <div>
                        <p className="text-xs font-bold text-slate-500 uppercase tracking-wider">Total Invested (Local Currency)</p>
                        <p className="text-xl font-mono font-bold text-slate-900 dark:text-white">{formatNumber(netFundingLocal)} <span className="text-sm font-normal text-slate-400">Local</span></p>
                    </div>
                </div>
            )}

            <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
                {/* Funding History Chart */}
                <div className="bg-white dark:bg-slate-800 p-6 rounded-3xl border border-slate-200 dark:border-slate-700 shadow-sm">
                    <h3 className="text-lg font-bold text-slate-900 dark:text-white mb-6">Invested Capital Over Time</h3>
                    <div className="h-[300px]">
                        <ResponsiveContainer width="100%" height="100%">
                            <AreaChart data={cumulativeFundingData} margin={{ top: 10, right: 10, left: 0, bottom: 0 }}>
                                <defs>
                                    <linearGradient id="colorFunding" x1="0" y1="0" x2="0" y2="1">
                                        <stop offset="5%" stopColor="#6366f1" stopOpacity={0.2}/>
                                        <stop offset="95%" stopColor="#6366f1" stopOpacity={0}/>
                                    </linearGradient>
                                </defs>
                                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#e2e8f0" opacity={0.3} />
                                <XAxis dataKey="date" axisLine={false} tickLine={false} tick={{fill: '#94a3b8', fontSize: 11}} dy={10} minTickGap={40} />
                                <YAxis axisLine={false} tickLine={false} tick={{fill: '#94a3b8', fontSize: 11}} tickFormatter={(val) => `${val >= 1000 ? (val/1000).toFixed(0) + 'k' : val}`} />
                                <Tooltip content={<CustomTooltip />} />
                                <Area type="stepAfter" dataKey="netInvested" stroke="#6366f1" strokeWidth={2} fill="url(#colorFunding)" />
                            </AreaChart>
                        </ResponsiveContainer>
                    </div>
                </div>

                {/* Transaction Log */}
                <div className="bg-white dark:bg-slate-800 rounded-3xl border border-slate-200 dark:border-slate-700 shadow-sm overflow-hidden flex flex-col">
                    <div className="p-6 border-b border-slate-100 dark:border-slate-700">
                        <h3 className="font-bold text-slate-900 dark:text-white">Recent Funding</h3>
                    </div>
                    <div className="overflow-y-auto custom-scrollbar flex-1 max-h-[300px]">
                        <table className="w-full text-sm text-left">
