                            </thead>
                            <tbody className="divide-y divide-slate-100 dark:divide-slate-800">
                                {sortedTxs.map((tx) => (
                                    <tr key={tx.id} className="hover:bg-slate-50 dark:hover:bg-slate-700/30">
                                        <td className="px-6 py-3 font-medium text-slate-900 dark:text-white">{new Date(tx.date).toLocaleDateString()}</td>
                                        <td className="px-6 py-3">
                                            <span className={`px-2 py-1 rounded text-[10px] font-bold uppercase ${
                                                tx.type === 'DEPOSIT' 
                                                ? 'bg-blue-100 text-blue-700 dark:bg-blue-900/30 dark:text-blue-400' 
                                                : 'bg-orange-100 text-orange-700 dark:bg-orange-900/30 dark:text-orange-400'
                                            }`}>
                                                {tx.type}
                                            </span>
                                        </td>
                                        {showFx && (
                                            <td className="px-6 py-3 text-right font-mono text-slate-500 dark:text-slate-400">
                                                {tx.exchangeRate ? tx.exchangeRate.toFixed(2) : '-'}
                                            </td>
                                        )}
                                        <td className={`px-6 py-3 text-right font-bold font-mono ${tx.type === 'DEPOSIT' ? 'text-blue-600' : 'text-orange-600'}`}>
                                            {tx.type === 'DEPOSIT' ? '+' : '-'}{formatCurrency(tx.price || 0)}
                                        </td>
                                    </tr>
                                ))}
                            </tbody>
                        </table>
                    </div>
                </div>
            </div>
        </div>
    );
};


const GrowthView: React.FC<{ transactions: Transaction[], holdings: Holding[], currentPortfolioValue: number, chartData: ChartDataPoint[] }> = ({ transactions, holdings, currentPortfolioValue, chartData }) => {
   const [returnRange, setReturnRange] = useState<'6M' | '1Y' | 'ALL'>('ALL');

   const { netFundingUSD } = useMemo(() => calculateFundingStats(transactions), [transactions]);
   const monthlyReturns = useMemo(() => calculateMonthlyReturns(chartData), [chartData]);

   // --- KPI Calculations ---
   const totalROI = netFundingUSD > 0 ? ((currentPortfolioValue - netFundingUSD) / netFundingUSD) * 100 : 0;
   const maxDrawdown = useMemo(() => calculateMaxDrawdown(chartData), [chartData]);
   const winRate = useMemo(() => calculateWinRate(monthlyReturns), [monthlyReturns]);

   // Time in Market
   const firstTxDate = useMemo(() => {
       if(transactions.length === 0) return null;
       const sorted = [...transactions].sort((a, b) => new Date(a.date).getTime() - new Date(b.date).getTime());
       return new Date(sorted[0].date);
   }, [transactions]);

   const daysInMarket = useMemo(() => {
       if(!firstTxDate) return 0;
       const diffTime = Math.abs(new Date().getTime() - firstTxDate.getTime());
       return Math.ceil(diffTime / (1000 * 60 * 60 * 24)); 
   }, [firstTxDate]);

   const yearsInMarket = daysInMarket / 365.25;

   // CAGR (Simple Approximation)
   const cagr = useMemo(() => {
       if (yearsInMarket < 1 || netFundingUSD <= 0) return totalROI; // Fallback to ROI if < 1 year
       return (Math.pow(currentPortfolioValue / netFundingUSD, 1 / yearsInMarket) - 1) * 100;
   }, [currentPortfolioValue, netFundingUSD, yearsInMarket, totalROI]);

   // Benchmark Simulation (8% Annual Growth on Invested Capital)
   const enhancedChartData = useMemo(() => {
       return chartData.map(point => {
           const pointDate = point.date === 'Now' ? new Date() : new Date(point.date);
           const daysSinceStart = firstTxDate ? (pointDate.getTime() - firstTxDate.getTime()) / (1000 * 60 * 60 * 24) : 0;
           const years = daysSinceStart / 365.25;
           // Simple compounded benchmark: Invested * (1.08 ^ years)
           const benchmark = point.invested * Math.pow(1.08, years);
           return { ...point, benchmark };
       });
   }, [chartData, firstTxDate]);

   // Filtered Monthly Returns
   const displayedReturns = useMemo(() => {
       if (returnRange === 'ALL') return monthlyReturns;
       const months = returnRange === '6M' ? 6 : 12;
       return monthlyReturns.slice(-months);
   }, [monthlyReturns, returnRange]);

   const avgMonthlyReturn = displayedReturns.length > 0 
       ? displayedReturns.reduce((sum, m) => sum + m.value, 0) / displayedReturns.length 
       : 0;

   // Performance Breakdown
   const sortedHoldings = useMemo(() => {
       return [...holdings].sort((a, b) => b.unrealizedPL - a.unrealizedPL);
   }, [holdings]);

   if (chartData.length === 0) {
       return <EmptyState message="Not enough data to generate growth report." />;
   }

   return (
      <div className="space-y-8 animate-slide-up">

         {/* 1. Summary Insight Row */}
         <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
             <KpiCard label="Total ROI" value={`${totalROI > 0 ? '+' : ''}${totalROI.toFixed(2)}%`} sub="All Time Return" icon={<TrendingUp size={18} />} color={totalROI >= 0 ? 'text-emerald-500' : 'text-rose-500'} />
             <KpiCard label="CAGR" value={`${cagr.toFixed(2)}%`} sub="Annualized Growth" icon={<Activity size={18} />} color="text-blue-500" />
             <KpiCard label="Max Drawdown" value={`-${maxDrawdown.toFixed(2)}%`} sub="Peak to Trough" icon={<TrendingDown size={18} />} color="text-rose-500" />
             <KpiCard label="Win Rate" value={`${winRate.toFixed(0)}%`} sub={`${monthlyReturns.filter(m => m.value > 0).length} / ${monthlyReturns.length} Months`} icon={<Trophy size={18} />} color="text-amber-500" />
         </div>

         {/* 2. Wealth Growth Curve with Benchmark */}
         <div className="bg-white dark:bg-slate-800 p-6 md:p-8 rounded-3xl border border-slate-200 dark:border-slate-700 shadow-sm">
            <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center mb-8 gap-4">
                <div>
                    <h3 className="text-lg font-bold text-slate-900 dark:text-white flex items-center gap-2">
                        Wealth Growth Curve
                    </h3>
                    <p className="text-xs text-slate-500 dark:text-slate-400 mt-1">
                        Market Value vs. Cost Basis vs. Simulated Benchmark (8%)
                    </p>
                </div>
                <div className="flex items-center gap-4 text-xs font-bold">
                    <div className="flex items-center text-blue-500"><div className="w-2.5 h-2.5 bg-blue-500 rounded-full mr-2"></div> Market Value</div>
                    <div className="flex items-center text-slate-400"><div className="w-2.5 h-2.5 bg-slate-400/50 rounded-full mr-2"></div> Cost Basis</div>
                    <div className="flex items-center text-slate-300"><div className="w-2.5 h-2.5 bg-slate-200 rounded-full mr-2"></div> Benchmark</div>
                </div>
            </div>

            <div className="h-[350px] w-full">
                <ResponsiveContainer width="100%" height="100%">
                    <AreaChart data={enhancedChartData} margin={{ top: 10, right: 0, left: 0, bottom: 0 }}>
                        <defs>
                            <linearGradient id="colorMv" x1="0" y1="0" x2="0" y2="1">
                                <stop offset="5%" stopColor="#3b82f6" stopOpacity={0.3}/>
                                <stop offset="95%" stopColor="#3b82f6" stopOpacity={0}/>
                            </linearGradient>
                        </defs>
                        <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#e2e8f0" opacity={0.4} />
                        <XAxis dataKey="date" axisLine={false} tickLine={false} tick={{fill: '#94a3b8', fontSize: 11}} dy={10} minTickGap={50} />
                        <YAxis axisLine={false} tickLine={false} tick={{fill: '#94a3b8', fontSize: 11}} tickFormatter={(val) => `${val >= 1000 ? (val/1000).toFixed(0) + 'k' : val}`} />
                        <Tooltip content={<CustomTooltip />} />
                        <Area type="monotone" dataKey="value" stroke="#3b82f6" strokeWidth={3} fill="url(#colorMv)" name="value" />
                        <Area type="monotone" dataKey="invested" stroke="#94a3b8" strokeDasharray="4 4" strokeWidth={2} fill="transparent" name="invested" />
                        <Line type="monotone" dataKey="benchmark" stroke="#cbd5e1" strokeWidth={2} dot={false} name="benchmark" opacity={0.7} />
                    </AreaChart>
                </ResponsiveContainer>
            </div>
         </div>

         {/* 3. Monthly Returns & Performance Attribution */}
         <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">

             {/* Monthly Returns */}
             <div className="bg-white dark:bg-slate-800 p-6 rounded-3xl border border-slate-200 dark:border-slate-700 shadow-sm flex flex-col">
                 <div className="flex justify-between items-center mb-6">
                     <div>
                        <h3 className="font-bold text-slate-900 dark:text-white">Monthly Returns</h3>
                        <p className="text-xs text-slate-500">Avg: <span className={avgMonthlyReturn >= 0 ? 'text-emerald-500' : 'text-rose-500'}>{avgMonthlyReturn > 0 ? '+' : ''}{avgMonthlyReturn.toFixed(2)}%</span></p>
                     </div>
                     <div className="flex bg-slate-100 dark:bg-slate-900 p-1 rounded-lg">
                        {['6M', '1Y', 'ALL'].map(r => (
                            <button 
                                key={r} 
                                onClick={() => setReturnRange(r as any)}
                                className={`px-3 py-1 text-[10px] font-bold rounded-md transition-all ${returnRange === r ? 'bg-white dark:bg-slate-700 shadow text-slate-900 dark:text-white' : 'text-slate-400'}`}
                            >
                                {r}
                            </button>
                        ))}
                     </div>
                 </div>

                 <div className="flex-1 min-h-[250px]">
                    <ResponsiveContainer width="100%" height="100%">
                        <BarChart data={displayedReturns} margin={{ top: 20, right: 0, left: 0, bottom: 0 }}>
                            <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#e2e8f0" opacity={0.3} />
                            <XAxis dataKey="yearMonth" axisLine={false} tickLine={false} tick={{fill: '#94a3b8', fontSize: 10}} dy={10} minTickGap={20} tickFormatter={(val) => val.split('-')[1]} />
                            <YAxis hide />
                            <Tooltip cursor={{fill: 'transparent'}} content={<CustomTooltip formatter={(val: number) => `${val.toFixed(2)}%`} />} />
                            <ReferenceLine y={0} stroke="#e2e8f0" />
                            <Bar dataKey="value" radius={[4, 4, 4, 4]}>
                                {displayedReturns.map((entry, index) => (
                                    <Cell key={`cell-${index}`} fill={entry.value >= 0 ? '#10b981' : '#f43f5e'} />
                                ))}
                            </Bar>
                        </BarChart>
                    </ResponsiveContainer>
                 </div>
             </div>

             {/* Performance Breakdown */}
             <div className="bg-white dark:bg-slate-800 p-6 rounded-3xl border border-slate-200 dark:border-slate-700 shadow-sm flex flex-col">
                 <div className="mb-6">
                     <h3 className="font-bold text-slate-900 dark:text-white">Performance Breakdown</h3>
                     <p className="text-xs text-slate-500">Top contributors to your growth</p>
                 </div>

                 <div className="flex-1 overflow-y-auto custom-scrollbar pr-2 max-h-[300px]">
                     <table className="w-full text-left text-sm">
                         <thead className="sticky top-0 bg-white dark:bg-slate-800 z-10 text-[10px] uppercase text-slate-400 font-bold border-b border-slate-100 dark:border-slate-700">
                             <tr>
                                 <th className="pb-2">Asset</th>
                                 <th className="pb-2 text-right">ROI</th>
                                 <th className="pb-2 text-right">Gain/Loss</th>
                                 <th className="pb-2 text-right">Weight</th>
                             </tr>
                         </thead>
                         <tbody className="divide-y divide-slate-100 dark:divide-slate-700">
                             {sortedHoldings.map(h => (
                                 <tr key={h.symbol} className="group hover:bg-slate-50 dark:hover:bg-slate-700/30">
                                     <td className="py-3 font-bold text-slate-700 dark:text-slate-200 group-hover:text-blue-600 dark:group-hover:text-blue-400 transition-colors">
                                         {h.symbol}
                                     </td>
                                     <td className={`py-3 text-right font-bold ${h.unrealizedPLPercent >= 0 ? 'text-emerald-500' : 'text-rose-500'}`}>
                                         {h.unrealizedPLPercent > 0 ? '+' : ''}{h.unrealizedPLPercent.toFixed(1)}%
                                     </td>
                                     <td className={`py-3 text-right font-mono text-xs ${h.unrealizedPL >= 0 ? 'text-emerald-600 dark:text-emerald-400' : 'text-rose-600 dark:text-rose-400'}`}>
                                         {formatCurrency(h.unrealizedPL)}
                                     </td>
                                     <td className="py-3 text-right text-slate-400 text-xs">
                                         {currentPortfolioValue > 0 ? ((h.marketValue / currentPortfolioValue) * 100).toFixed(1) : 0}%
                                     </td>
                                 </tr>
                             ))}
                         </tbody>
                     </table>
                 </div>
             </div>
         </div>

         {/* 4. Time In Market Context */}
         <div className="bg-gradient-to-r from-slate-100 to-white dark:from-slate-800 dark:to-slate-900 p-6 rounded-2xl border border-slate-200 dark:border-slate-700 flex items-center justify-between">
             <div className="flex items-center gap-4">
                 <div className="p-3 bg-white dark:bg-slate-800 rounded-full shadow-sm text-slate-400">
                     <Clock size={24} />
                 </div>
                 <div>
                     <h4 className="font-bold text-slate-900 dark:text-white">Time in Market</h4>
                     <p className="text-xs text-slate-500">
                         Invested since <span className="font-bold">{firstTxDate?.toLocaleDateString()}</span> — {daysInMarket} days compounding
                     </p>
                 </div>
             </div>
             <div className="hidden sm:block text-right">
                 <p className="text-[10px] uppercase font-bold text-slate-400">Current Streak</p>
                 <p className="text-sm font-bold text-slate-700 dark:text-slate-300">{displayedReturns.filter(m => m.value > 0).length} Positive Months (Last {displayedReturns.length})</p>
             </div>
         </div>

      </div>
   );
};

