    const sortedTxs = useMemo(() => [...fundingTxs].sort((a,b) => new Date(b.date).getTime() - new Date(a.date).getTime()), [fundingTxs]);

    if (fundingTxs.length === 0) {
        return <EmptyState message="No deposits or withdrawals yet." />;
