const CustomTooltip = ({ active, payload, label, formatter }: any) => {
  if (active && payload && payload.length) {
    return (
      <div className="bg-white/95 dark:bg-slate-900/95 backdrop-blur-md border border-slate-200 dark:border-slate-700 p-4 rounded-xl shadow-xl transition-colors duration-200 z-50">
        {label && <p className="text-xs font-bold text-slate-500 dark:text-slate-400 uppercase tracking-wider mb-2">{label}</p>}
        <div className="space-y-1.5">
          {payload.map((entry: any, index: number) => {
             const nameMap: Record<string, string> = {
                'netInvested': 'Net Flow',
                'dividendIncome': 'Dividends',
                'value': 'Value',
                'invested': 'Cost Basis',
                'benchmark': 'Benchmark (8%)',
                'buyVolume': 'Buy Volume',
                'sellVolume': 'Sell Volume',
                'deposit': 'Deposits',
                'withdraw': 'Withdrawals'
             };
             const displayName = nameMap[entry.name] || entry.name;

             // Don't show if value is 0 unless it's the only thing
             if (payload.length > 1 && entry.value === 0) return null;

             return (
              <div key={index} className="flex items-center justify-between gap-6 text-sm">
                <div className="flex items-center">
                  <div className="w-2.5 h-2.5 rounded-full mr-2 shadow-sm" style={{ backgroundColor: entry.color }}></div>
                  <span className="text-slate-600 dark:text-slate-300 font-medium capitalize">
                      {displayName}
                  </span>
                </div>
                <span className="font-bold text-slate-900 dark:text-white font-mono tabular-nums">
                  {formatter ? formatter(entry.value, entry.name, entry) : formatCurrency(entry.value)}
                </span>
              </div>
            );
          })}
        </div>
      </div>
    );
  }
  return null;
};

