                    <div className="relative">
                        <select 
                            value={selectedYear} 
                            onChange={(e) => setSelectedYear(e.target.value)}
                            className="appearance-none bg-slate-100 dark:bg-slate-700 border border-slate-200 dark:border-slate-600 text-slate-700 dark:text-slate-200 text-xs font-bold rounded-xl pl-3 pr-8 py-2 focus:ring-2 focus:ring-blue-500 outline-none cursor-pointer"
