                    <div className="flex items-center text-slate-400"><div className="w-2.5 h-2.5 bg-slate-400/50 rounded-full mr-2"></div> Cost Basis</div>
                    <div className="flex items-center text-slate-300"><div className="w-2.5 h-2.5 bg-slate-200 rounded-full mr-2"></div> Benchmark</div>
                </div>
            </div>

            <div className="h-[350px] w-full">
                <ResponsiveContainer width="100%" height="100%">
                    <AreaChart data={enhancedChartData} margin={{ top: 10, right: 0, left: 0, bottom: 0 }}>
                        <defs>
