};

const FundingView: React.FC<{ transactions: Transaction[], currentPortfolioValue: number }> = ({ transactions, currentPortfolioValue }) => {
    const [selectedYear, setSelectedYear] = useState<string>('ALL');
    const [currentFxRate, setCurrentFxRate] = useState<string>('');

    // Filter Funding Transactions Only
    const fundingTxs = useMemo(() => 
        transactions.filter(t => t.type === TransactionType.DEPOSIT || t.type === TransactionType.WITHDRAW), 
    [transactions]);

    // Available Years
    const years = useMemo(() => {
        const uniqueYears = Array.from(new Set(fundingTxs.map(t => new Date(t.date).getFullYear().toString()))).sort().reverse();
        return ['ALL', ...uniqueYears];
    }, [fundingTxs]);

    // Filter by Year
    const filteredTxs = useMemo(() => {
        if (selectedYear === 'ALL') return fundingTxs;
        return fundingTxs.filter(t => t.date.startsWith(selectedYear));
    }, [fundingTxs, selectedYear]);

    const stats = useMemo(() => calculateFundingStats(filteredTxs), [filteredTxs]);
    const { netFundingUSD, avgFxCost } = stats;

    // Sort funding txs descending for Table
    const sortedTxs = useMemo(() => [...filteredTxs].sort((a,b) => new Date(b.date).getTime() - new Date(a.date).getTime()), [filteredTxs]);

    // Aggregates for Summary Bar
    const totalDeposits = useMemo(() => filteredTxs.filter(t => t.type === TransactionType.DEPOSIT).reduce((sum, t) => sum + (t.price || 0), 0), [filteredTxs]);
    const totalWithdrawals = useMemo(() => filteredTxs.filter(t => t.type === TransactionType.WITHDRAW).reduce((sum, t) => sum + (t.price || 0), 0), [filteredTxs]);

    if (fundingTxs.length === 0) {
        return <EmptyState message="No deposits or withdrawals yet." />;
    }

    // Chart Data: Cumulative Net Funding (based on filtered view)
    const cumulativeFundingData = useMemo(() => {
        let runningTotal = 0;
        const chronological = [...filteredTxs].sort((a,b) => new Date(a.date).getTime() - new Date(b.date).getTime());
        return chronological.map(tx => {
            const amount = tx.price || 0;
            if (tx.type === TransactionType.DEPOSIT) runningTotal += amount;
            else runningTotal -= amount;
            return {
                date: tx.date,
                netInvested: runningTotal
            };
        });
    }, [filteredTxs]);

    // Calculate Total Potential Gain/Loss based on Current FX Input
    const currentRateNum = parseFloat(currentFxRate);
    const fxAnalysis = useMemo(() => {
       if (!currentFxRate || isNaN(currentRateNum) || netFundingUSD === 0) return null;

       // Estimated Local Value of Net Funding Now = Net Funding USD * Current Rate
       const currentLocalValue = netFundingUSD * currentRateNum;
       // Actual Local Cost (calculated in stats)
       const actualLocalCost = stats.netFundingLocal;

       const diff = currentLocalValue - actualLocalCost;
       return { diff, currentLocalValue };
    }, [currentRateNum, netFundingUSD, stats.netFundingLocal, currentFxRate]);

    return (
        <div className="space-y-6 animate-slide-up">
            {/* 1. Summary Bar */}
            <SummaryBar>
                <SummaryMetric 
                    label="Net Invested" 
