                    icon={<Wallet size={16} />}
                    color="blue"
                />
                <div className="hidden md:block w-px bg-slate-100 dark:bg-slate-700 mx-4 self-stretch"></div>

                {/* FX Comparison Block */}
                <div className="col-span-2 bg-gradient-to-r from-purple-50 to-indigo-50 dark:from-slate-700/50 dark:to-slate-700/30 rounded-xl p-4 border border-indigo-100 dark:border-slate-600 flex flex-col justify-between">
                    <div className="flex items-center justify-between mb-3">
                        <div className="flex items-center gap-2">
                             <div className="p-1.5 rounded-lg bg-white dark:bg-slate-800 text-purple-600 dark:text-purple-400 shadow-sm">
                                <Globe size={16} />
                             </div>
                             <span className="text-xs font-bold text-slate-500 dark:text-slate-300 uppercase tracking-wider">FX Rate Analysis</span>
                        </div>
                        <div className="text-[10px] font-bold text-slate-400 bg-white dark:bg-slate-800 px-2 py-1 rounded-md shadow-sm border border-slate-100 dark:border-slate-600">
                             Weighted Avg: <span className="text-slate-900 dark:text-white">{avgFxCost.toFixed(4)}</span>
                        </div>
                    </div>

                    <div className="flex items-end gap-4">
                        <div className="flex-1">
                            <label className="text-[10px] font-bold text-slate-400 uppercase mb-1 block">Current Market Rate</label>
                            <div className="relative">
                                <input 
                                    type="number" 
                                    step="0.0001"
                                    placeholder="e.g. 35.5"
                                    value={currentFxRate}
                                    onChange={(e) => setCurrentFxRate(e.target.value)}
                                    className="w-full pl-8 pr-3 py-2 text-sm font-bold rounded-lg bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-600 focus:ring-2 focus:ring-purple-500 outline-none text-slate-900 dark:text-white"
                                />
                                <Calculator size={14} className="absolute left-2.5 top-1/2 -translate-y-1/2 text-slate-400" />
                            </div>
                        </div>

                        {fxAnalysis && (
                            <div className="flex-1 text-right animate-fade-in">
                                <div className="text-[10px] font-bold text-slate-400 uppercase mb-0.5">Unrealized FX P/L</div>
                                <div className={`text-lg font-bold font-mono leading-none ${fxAnalysis.diff >= 0 ? 'text-emerald-600 dark:text-emerald-400' : 'text-rose-600 dark:text-rose-400'}`}>
                                    {fxAnalysis.diff >= 0 ? '+' : ''}{formatNumber(fxAnalysis.diff, 2)}
                                </div>
                                <div className="text-[10px] text-slate-500 dark:text-slate-400 font-medium mt-1">
                                    in Local Currency
                                </div>
