                                </tr>
                            </thead>
                            <tbody className="divide-y divide-slate-100 dark:divide-slate-800">
                                {sortedTxs.map((tx) => {
                                    // Calculate per-transaction FX Impact if current rate is set
                                    let fxGainLoss = null;
                                    if (currentRateNum > 0 && tx.exchangeRate && tx.type === 'DEPOSIT') {
                                        // USD Amount * (Current Rate - Tx Rate)
                                        fxGainLoss = (tx.price || 0) * (currentRateNum - tx.exchangeRate);
                                    }

                                    return (
                                    <tr key={tx.id} className="hover:bg-slate-50 dark:hover:bg-slate-700/30 transition-colors">
