                                className={`px-3 py-1 text-[10px] font-bold rounded-md transition-all ${returnRange === r ? 'bg-white dark:bg-slate-700 shadow text-slate-900 dark:text-white' : 'text-slate-400 hover:text-slate-600 dark:hover:text-slate-200'}`}
                            >
                                {r}
