    const totalDeposits = useMemo(() => filteredTxs.filter(t => t.type === TransactionType.DEPOSIT).reduce((sum, t) => sum + (t.price || 0), 0), [filteredTxs]);
    const totalWithdrawals = useMemo(() => filteredTxs.filter(t => t.type === TransactionType.WITHDRAW).reduce((sum, t) => sum + (t.price || 0), 0), [filteredTxs]);

    if (fundingTxs.length === 0) {
