       // Estimated Local Value of Net Funding Now = Net Funding USD * Current Rate
       const currentLocalValue = netFundingUSD * currentRateNum;
       // Actual Local Cost (calculated in stats)
       const actualLocalCost = stats.netFundingLocal;

       const diff = currentLocalValue - actualLocalCost;
       return { diff, currentLocalValue };
