                        <XAxis dataKey="date" axisLine={false} tickLine={false} tick={{fill: '#94a3b8', fontSize: 11}} dy={10} minTickGap={50} />
                        <YAxis axisLine={false} tickLine={false} tick={{fill: '#94a3b8', fontSize: 11}} tickFormatter={(val) => `${val >= 1000 ? (val/1000).toFixed(0) + 'k' : val}`} />
                        <Tooltip content={<CustomTooltip />} />
                        <Area type="monotone" dataKey="value" stroke="#3b82f6" strokeWidth={3} fill="url(#colorMv)" name="value" />
                        <Area type="monotone" dataKey="invested" stroke="#94a3b8" strokeDasharray="4 4" strokeWidth={2} fill="transparent" name="invested" />
                        <Line type="monotone" dataKey="benchmark" stroke="#cbd5e1" strokeWidth={2} dot={false} name="benchmark" opacity={0.7} />
                    </AreaChart>
                </ResponsiveContainer>
            </div>
         </div>

         {/* 3. Monthly Returns & Performance Attribution */}
         <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">

             {/* Monthly Returns */}
             <div className="bg-white dark:bg-slate-800 p-6 rounded-2xl border border-slate-200 dark:border-slate-700 shadow-sm flex flex-col">
                 <div className="flex justify-between items-center mb-6">
                     <div>
                        <h3 className="font-bold text-slate-900 dark:text-white">Monthly Returns</h3>
                        <p className="text-xs text-slate-500">Avg: <span className={avgMonthlyReturn >= 0 ? 'text-emerald-500' : 'text-rose-500'}>{avgMonthlyReturn > 0 ? '+' : ''}{avgMonthlyReturn.toFixed(2)}%</span></p>
                     </div>
                     <div className="flex bg-slate-100 dark:bg-slate-900 p-1 rounded-lg">
                        {['6M', '1Y', 'ALL'].map(r => (
                            <button 
                                key={r} 
                                onClick={() => setReturnRange(r as any)}
                                className={`px-3 py-1 text-[10px] font-bold rounded-md transition-all ${returnRange === r ? 'bg-white dark:bg-slate-700 shadow text-slate-900 dark:text-white' : 'text-slate-400 hover:text-slate-600 dark:hover:text-slate-200'}`}
                            >
                                {r}
                            </button>
                        ))}
                     </div>
                 </div>

                 <div className="flex-1 min-h-[250px]">
                    <ResponsiveContainer width="100%" height="100%">
                        <BarChart data={displayedReturns} margin={{ top: 20, right: 0, left: 0, bottom: 0 }}>
                            <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#e2e8f0" opacity={0.3} />
                            <XAxis dataKey="yearMonth" axisLine={false} tickLine={false} tick={{fill: '#94a3b8', fontSize: 10}} dy={10} minTickGap={20} tickFormatter={(val) => val.split('-')[1]} />
                            <YAxis hide />
                            <Tooltip cursor={{fill: 'transparent'}} content={<CustomTooltip formatter={(val: number) => `${val.toFixed(2)}%`} />} />
                            <ReferenceLine y={0} stroke="#e2e8f0" strokeDasharray="3 3" />
                            <Bar dataKey="value" radius={[4, 4, 4, 4]}>
                                {displayedReturns.map((entry, index) => (
                                    <Cell key={`cell-${index}`} fill={entry.value >= 0 ? '#10b981' : '#f43f5e'} />
                                ))}
                            </Bar>
                        </BarChart>
                    </ResponsiveContainer>
                 </div>
             </div>

             {/* Performance Breakdown */}
             <div className="bg-white dark:bg-slate-800 p-6 rounded-2xl border border-slate-200 dark:border-slate-700 shadow-sm flex flex-col">
                 <div className="mb-6">
                     <h3 className="font-bold text-slate-900 dark:text-white">Performance Breakdown</h3>
                     <p className="text-xs text-slate-500">Top contributors to your growth</p>
                 </div>

                 <div className="flex-1 overflow-y-auto custom-scrollbar pr-2 max-h-[300px]">
                     <table className="w-full text-left text-sm">
                         <thead className="sticky top-0 bg-white dark:bg-slate-800 z-10 text-[10px] uppercase text-slate-400 font-bold border-b border-slate-100 dark:border-slate-700">
                             <tr>
                                 <th className="pb-2">Asset</th>
                                 <th className="pb-2 text-right">ROI</th>
                                 <th className="pb-2 text-right">Gain/Loss</th>
                                 <th className="pb-2 text-right">Weight</th>
                             </tr>
                         </thead>
                         <tbody className="divide-y divide-slate-100 dark:divide-slate-700">
                             {sortedHoldings.map(h => (
                                 <tr key={h.symbol} className="group hover:bg-slate-50 dark:hover:bg-slate-700/30 transition-colors">
                                     <td className="py-3 font-bold text-slate-700 dark:text-slate-200 group-hover:text-blue-600 dark:group-hover:text-blue-400">
                                         {h.symbol}
                                     </td>
                                     <td className={`py-3 text-right font-bold ${h.unrealizedPLPercent >= 0 ? 'text-emerald-500' : 'text-rose-500'}`}>
                                         {h.unrealizedPLPercent > 0 ? '+' : ''}{h.unrealizedPLPercent.toFixed(1)}%
                                     </td>
                                     <td className={`py-3 text-right font-mono text-xs font-bold ${h.unrealizedPL >= 0 ? 'text-emerald-600 dark:text-emerald-400' : 'text-rose-600 dark:text-rose-400'}`}>
                                         {formatCurrency(h.unrealizedPL)}
                                     </td>
                                     <td className="py-3 text-right text-slate-400 text-xs">
                                         {currentPortfolioValue > 0 ? ((h.marketValue / currentPortfolioValue) * 100).toFixed(1) : 0}%
                                     </td>
                                 </tr>
                             ))}
                         </tbody>
                     </table>
                 </div>
             </div>
         </div>

         {/* 4. Time In Market Context */}
         <div className="bg-gradient-to-r from-slate-100 to-white dark:from-slate-800 dark:to-slate-900 p-6 rounded-2xl border border-slate-200 dark:border-slate-700 flex items-center justify-between">
             <div className="flex items-center gap-4">
                 <div className="p-3 bg-white dark:bg-slate-800 rounded-full shadow-sm text-slate-400">
                     <Clock size={24} />
                 </div>
                 <div>
                     <h4 className="font-bold text-slate-900 dark:text-white">Time in Market</h4>
                     <p className="text-xs text-slate-500">
                         Invested since <span className="font-bold text-slate-700 dark:text-slate-300">{firstTxDate?.toLocaleDateString()}</span> — {daysInMarket} days compounding
                     </p>
                 </div>
             </div>
             <div className="hidden sm:block text-right">
                 <p className="text-[10px] uppercase font-bold text-slate-400">Current Streak</p>
                 <p className="text-sm font-bold text-slate-700 dark:text-slate-300">{displayedReturns.filter(m => m.value > 0).length} Positive Months (Last {displayedReturns.length})</p>
             </div>
         </div>

      </div>
   );
};

const EmptyState = ({ message, subMessage }: { message: string, subMessage?: string }) => (
    <div className="flex flex-col items-center justify-center py-20 text-center bg-slate-50 dark:bg-slate-800/50 rounded-3xl border-2 border-dashed border-slate-200 dark:border-slate-700">
        <Activity size={40} className="text-slate-300 mb-4" />
        <h3 className="text-lg font-bold text-slate-600 dark:text-slate-300">{message}</h3>
        {subMessage && <p className="text-slate-400 text-sm mt-1">{subMessage}</p>}
    </div>
);

export default Reports;

import React, { useState, useEffect, useRef } from 'react';
import { LayoutDashboard, PieChart, History, FileText, Menu, X, Sun, Moon, Plus, TrendingUp, ChevronDown, Trash2, Briefcase, Check, Edit2 } from 'lucide-react';
import { TransactionType, Portfolio } from '../types';

interface LayoutProps {
  children: React.ReactNode;
  activeTab: string;
  setActiveTab: (tab: string) => void;
  onOpenAddModal: () => void;
  // New Props for Portfolio Management
  portfolios: Portfolio[];
  activePortfolioId: string;
  onSwitchPortfolio: (id: string) => void;
  onCreatePortfolio: (name: string) => void;
  onRenamePortfolio: (id: string, newName: string) => void;
  onDeletePortfolio: (id: string) => void;
}

const Layout: React.FC<LayoutProps> = ({ 
  children, activeTab, setActiveTab, onOpenAddModal,
  portfolios, activePortfolioId, onSwitchPortfolio, onCreatePortfolio, onRenamePortfolio, onDeletePortfolio
}) => {
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const [darkMode, setDarkMode] = useState(false);

  // Portfolio Dropdown & Modal State
  const [isPortfolioDropdownOpen, setIsPortfolioDropdownOpen] = useState(false);
  const [isCreateModalOpen, setIsCreateModalOpen] = useState(false);
  const [newPortfolioName, setNewPortfolioName] = useState('');

  // Rename State
  const [isRenameModalOpen, setIsRenameModalOpen] = useState(false);
  const [portfolioToRename, setPortfolioToRename] = useState<Portfolio | null>(null);
  const [renameValue, setRenameValue] = useState('');

  const dropdownRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    // Check local storage or system preference
    if (localStorage.getItem('theme') === 'dark' || (!localStorage.getItem('theme') && window.matchMedia('(prefers-color-scheme: dark)').matches)) {
      setDarkMode(true);
      document.documentElement.classList.add('dark');
    } else {
      setDarkMode(false);
      document.documentElement.classList.remove('dark');
    }
  }, []);

  // Close dropdown when clicking outside
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
        setIsPortfolioDropdownOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const toggleDarkMode = () => {
    const newMode = !darkMode;
    setDarkMode(newMode);
    if (newMode) {
      document.documentElement.classList.add('dark');
      localStorage.setItem('theme', 'dark');
    } else {
      document.documentElement.classList.remove('dark');
      localStorage.setItem('theme', 'light');
    }
  };

  const navItems = [
    { id: 'dashboard', label: 'Overview', icon: <LayoutDashboard size={20} /> },
    { id: 'holdings', label: 'Holdings', icon: <PieChart size={20} /> },
    { id: 'history', label: 'History', icon: <History size={20} /> },
    { id: 'reports', label: 'Reports', icon: <FileText size={20} /> },
  ];

  const activePortfolio = portfolios.find(p => p.id === activePortfolioId) || portfolios[0];

  const handleCreateClick = () => {
    setNewPortfolioName('');
    setIsCreateModalOpen(true);
    setIsPortfolioDropdownOpen(false);
  };

  const handleCreateSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (newPortfolioName.trim()) {
      onCreatePortfolio(newPortfolioName.trim());
      setIsCreateModalOpen(false);
    }
  };

  const handleRenameClick = (e: React.MouseEvent, p: Portfolio) => {
    e.stopPropagation();
    setPortfolioToRename(p);
    setRenameValue(p.name);
    setIsRenameModalOpen(true);
    setIsPortfolioDropdownOpen(false);
  };

  const handleRenameSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (portfolioToRename && renameValue.trim()) {
      onRenamePortfolio(portfolioToRename.id, renameValue.trim());
      setIsRenameModalOpen(false);
      setPortfolioToRename(null);
    }
  };

  return (
    <div className="min-h-screen flex flex-col bg-slate-50 dark:bg-[#0b1120] transition-colors duration-300 font-sans selection:bg-indigo-500 selection:text-white">

      {/* TOP NAVIGATION BAR */}
      <header className="sticky top-0 z-40 w-full bg-white/80 dark:bg-slate-900/80 backdrop-blur-xl border-b border-slate-200/60 dark:border-slate-800/60">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex items-center justify-between h-16 sm:h-20">

            {/* Left: Branding & Portfolio Switcher */}
            <div className="flex items-center gap-4 md:gap-8">
              {/* Logo */}
              <div className="flex items-center gap-2.5 shrink-0 group cursor-pointer" onClick={() => setActiveTab('dashboard')}>
                <div className="w-9 h-9 bg-gradient-to-br from-indigo-600 to-blue-600 rounded-xl flex items-center justify-center shadow-lg shadow-indigo-500/20 group-hover:scale-105 transition-transform">
                  <TrendingUp className="text-white" size={20} strokeWidth={2.5} />
                </div>
                <span className="hidden md:block text-lg font-display font-bold text-slate-900 dark:text-white tracking-tight">My Portfolio</span>
              </div>

              {/* Desktop Nav Items */}
              <nav className="hidden md:flex items-center gap-1">
                {navItems.map((item) => (
                  <button
                    key={item.id}
                    onClick={() => setActiveTab(item.id)}
                    className={`flex items-center space-x-2 px-4 py-2.5 rounded-full text-sm font-bold transition-all duration-200 ${
                      activeTab === item.id
                        ? 'bg-slate-100 dark:bg-slate-800 text-indigo-600 dark:text-indigo-400'
                        : 'text-slate-500 dark:text-slate-400 hover:bg-slate-50 dark:hover:bg-slate-800/50 hover:text-slate-700 dark:hover:text-slate-200'
                    }`}
                  >
                    {item.icon}
                    <span>{item.label}</span>
                  </button>
                ))}
              </nav>
            </div>

            {/* Right: Actions */}
            <div className="flex items-center gap-2 sm:gap-3">

              {/* Portfolio Switcher */}
              <div className="relative" ref={dropdownRef}>
                 <button 
                   onClick={() => setIsPortfolioDropdownOpen(!isPortfolioDropdownOpen)}
                   className="flex items-center gap-2 px-3 py-2 rounded-xl bg-slate-50 dark:bg-slate-800/50 border border-slate-200 dark:border-slate-700 hover:border-slate-300 dark:hover:border-slate-600 transition-all group"
                 >
                    <Briefcase size={16} className="text-slate-400 group-hover:text-indigo-500 transition-colors" />
                    <span className="hidden sm:block text-sm font-bold text-slate-700 dark:text-slate-200 max-w-[100px] truncate">{activePortfolio?.name}</span>
                    <ChevronDown size={14} className="text-slate-400" />
                 </button>

                  {isPortfolioDropdownOpen && (
                    <div className="absolute top-full right-0 mt-2 w-72 bg-white dark:bg-slate-900 rounded-2xl shadow-2xl shadow-slate-200/50 dark:shadow-black/50 border border-slate-100 dark:border-slate-800 overflow-hidden z-50 animate-in fade-in zoom-in-95 duration-200 origin-top-right">
                      <div className="p-3 border-b border-slate-100 dark:border-slate-800">
                          <p className="text-xs font-bold text-slate-400 uppercase tracking-wider px-2 mb-2">Switch Portfolio</p>
                          <div className="max-h-60 overflow-y-auto custom-scrollbar space-y-1">
                              {portfolios.map(p => (
                                <div key={p.id} className="flex items-center group/item">
                                  <button
                                    onClick={() => {
                                      onSwitchPortfolio(p.id);
                                      setIsPortfolioDropdownOpen(false);
                                    }}
                                    className={`flex-1 text-left px-3 py-2.5 rounded-xl text-sm font-bold transition-colors flex items-center justify-between ${
                                      activePortfolioId === p.id 
                                      ? 'bg-indigo-50 text-indigo-700 dark:bg-indigo-900/30 dark:text-indigo-400' 
                                      : 'text-slate-600 dark:text-slate-300 hover:bg-slate-50 dark:hover:bg-slate-800'
                                    }`}
                                  >
                                    <span className="truncate">{p.name}</span>
                                    {activePortfolioId === p.id && <Check size={14} />}
                                  </button>

                                  <div className="flex items-center gap-1 opacity-0 group-hover/item:opacity-100 transition-opacity pl-1">
                                      <button 
                                          onClick={(e) => handleRenameClick(e, p)}
                                          className="p-2 text-slate-400 hover:text-indigo-500 hover:bg-indigo-50 dark:hover:bg-indigo-900/20 rounded-lg transition-colors"
                                          title="Rename"
                                      >
                                          <Edit2 size={14} />
                                      </button>
                                      {portfolios.length > 1 && (
                                        <button 
                                          onClick={(e) => { e.stopPropagation(); onDeletePortfolio(p.id); }}
                                          className="p-2 text-slate-400 hover:text-rose-500 hover:bg-rose-50 dark:hover:bg-rose-900/20 rounded-lg transition-colors"
                                          title="Delete"
                                        >
                                          <Trash2 size={14} />
                                        </button>
                                      )}
                                  </div>
                                </div>
                              ))}
                          </div>
                      </div>
                      <div className="p-2 bg-slate-50 dark:bg-slate-800/50">
                          <button 
                            onClick={handleCreateClick}
                            className="w-full flex items-center justify-center space-x-2 text-sm font-bold text-indigo-600 dark:text-indigo-400 hover:bg-white dark:hover:bg-slate-700 py-2.5 rounded-xl transition-all shadow-sm"
                          >
                            <Plus size={16} strokeWidth={3} />
                            <span>Create New Portfolio</span>
                          </button>
                      </div>
                    </div>
                  )}
              </div>

              {/* Theme Toggle */}
              <button
                onClick={toggleDarkMode}
                className="p-2.5 rounded-xl text-slate-500 hover:bg-slate-100 dark:hover:bg-slate-800 transition-colors"
                aria-label="Toggle Theme"
              >
                {darkMode ? <Sun size={20} /> : <Moon size={20} />}
              </button>

              {/* Main Add Button (Desktop) */}
              <button
                onClick={() => onOpenAddModal()}
                className="hidden md:flex items-center space-x-2 bg-slate-900 dark:bg-white text-white dark:text-slate-900 hover:opacity-90 px-5 py-2.5 rounded-xl font-bold shadow-lg shadow-slate-900/20 hover:shadow-xl transition-all active:scale-95"
              >
                <Plus size={20} strokeWidth={3} />
                <span>Add Transaction</span>
              </button>
            </div>
          </div>
        </div>
      </header>

      {/* CREATE PORTFOLIO MODAL */}
      {isCreateModalOpen && (
        <div className="fixed inset-0 z-[60] flex items-center justify-center p-4 animate-fade-in">
          <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-sm" onClick={() => setIsCreateModalOpen(false)}></div>
          <div className="relative bg-white dark:bg-slate-900 rounded-3xl shadow-2xl w-full max-w-sm overflow-hidden animate-zoom-in border border-slate-200 dark:border-slate-700">
             <div className="p-6">
               <div className="w-12 h-12 bg-indigo-100 dark:bg-indigo-900/30 rounded-2xl flex items-center justify-center text-indigo-600 dark:text-indigo-400 mb-4">
                  <Briefcase size={24} />
               </div>
               <h3 className="text-xl font-bold font-display text-slate-900 dark:text-white mb-2">Create Portfolio</h3>
               <p className="text-sm text-slate-500 dark:text-slate-400 mb-6">Give your new portfolio a name to get started.</p>

               <form onSubmit={handleCreateSubmit}>
                 <div className="mb-4">
                   <label className="block text-xs font-bold text-slate-500 uppercase tracking-wider mb-2">Name</label>
                   <input 
                     type="text" 
                     autoFocus
                     placeholder="e.g. Retirement Fund"
                     value={newPortfolioName}
                     onChange={(e) => setNewPortfolioName(e.target.value)}
                     className="w-full px-4 py-3 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl text-slate-900 dark:text-white focus:ring-2 focus:ring-indigo-500 outline-none font-bold"
                   />
                 </div>

                 <div className="flex space-x-3">
                   <button 
                     type="button"
                     onClick={() => setIsCreateModalOpen(false)}
                     className="flex-1 py-3 rounded-xl font-bold text-slate-600 dark:text-slate-400 hover:bg-slate-100 dark:hover:bg-slate-800 transition-colors"
                   >
                     Cancel
                   </button>
                   <button 
                     type="submit"
                     disabled={!newPortfolioName.trim()}
                     className="flex-1 py-3 rounded-xl font-bold bg-indigo-600 text-white hover:bg-indigo-700 transition-colors disabled:opacity-50 disabled:cursor-not-allowed flex items-center justify-center space-x-2 shadow-lg shadow-indigo-500/20"
                   >
                     <Check size={18} />
                     <span>Create</span>
                   </button>
                 </div>
               </form>
             </div>
          </div>
        </div>
      )}

      {/* RENAME PORTFOLIO MODAL */}
      {isRenameModalOpen && (
        <div className="fixed inset-0 z-[60] flex items-center justify-center p-4 animate-fade-in">
          <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-sm" onClick={() => setIsRenameModalOpen(false)}></div>
          <div className="relative bg-white dark:bg-slate-900 rounded-3xl shadow-2xl w-full max-w-sm overflow-hidden animate-zoom-in border border-slate-200 dark:border-slate-700">
             <div className="p-6">
               <h3 className="text-lg font-bold font-display text-slate-900 dark:text-white mb-4">Rename Portfolio</h3>
               <form onSubmit={handleRenameSubmit}>
                 <div className="mb-6">
                   <label className="block text-xs font-bold text-slate-500 uppercase tracking-wider mb-2">Name</label>
                   <input 
                     type="text" 
                     autoFocus
                     value={renameValue}
                     onChange={(e) => setRenameValue(e.target.value)}
                     className="w-full px-4 py-3 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl text-slate-900 dark:text-white focus:ring-2 focus:ring-indigo-500 outline-none font-bold"
                   />
                 </div>

                 <div className="flex space-x-3">
                   <button 
                     type="button"
                     onClick={() => setIsRenameModalOpen(false)}
                     className="flex-1 py-3 rounded-xl font-bold text-slate-600 dark:text-slate-400 hover:bg-slate-100 dark:hover:bg-slate-800 transition-colors"
                   >
                     Cancel
                   </button>
                   <button 
                     type="submit"
                     disabled={!renameValue.trim()}
                     className="flex-1 py-3 rounded-xl font-bold bg-indigo-600 text-white hover:bg-indigo-700 transition-colors disabled:opacity-50 disabled:cursor-not-allowed flex items-center justify-center space-x-2"
                   >
                     <Check size={18} />
                     <span>Save</span>
                   </button>
                 </div>
               </form>
             </div>
          </div>
        </div>
      )}

      {/* Main Content Area */}
      <main className="flex-1 w-full max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-6 md:py-8 animate-fade-in mb-20 md:mb-0">
        {children}
      </main>

      {/* Mobile Bottom Navigation & FAB */}
      <div className="md:hidden fixed bottom-0 left-0 w-full z-40">
         {/* Floating Action Button (FAB) */}
         <div className="absolute bottom-20 right-4 pointer-events-none">
            <button
                onClick={() => onOpenAddModal()}
                className="pointer-events-auto w-14 h-14 bg-indigo-600 text-white rounded-full shadow-xl shadow-indigo-600/30 flex items-center justify-center active:scale-95 transition-transform"
            >
                <Plus size={28} strokeWidth={2.5} />
            </button>
         </div>

         {/* Bottom Nav Bar */}
         <div className="bg-white/95 dark:bg-slate-900/95 backdrop-blur-xl border-t border-slate-200 dark:border-slate-800 pb-safe pt-1 px-4 flex justify-between items-center h-[70px]">
            {navItems.map((item) => {
                const isActive = activeTab === item.id;
                return (
                    <button
                        key={item.id}
                        onClick={() => setActiveTab(item.id)}
                        className={`flex flex-col items-center justify-center w-full h-full space-y-1 transition-colors ${
                            isActive ? 'text-indigo-600 dark:text-indigo-400' : 'text-slate-400 dark:text-slate-500 hover:text-slate-600 dark:hover:text-slate-300'
                        }`}
                    >
                        <div className={`p-1 rounded-xl transition-all ${isActive ? 'bg-indigo-50 dark:bg-indigo-900/20 translate-y-[-2px]' : ''}`}>
                            {item.icon}
                        </div>
                        <span className="text-[10px] font-bold">{item.label}</span>
                    </button>
                )
            })}
         </div>
      </div>
    </div>
  );
};

export default Layout;

import React, { useMemo, useState } from 'react';
import { Holding, Transaction, ChartDataPoint, TransactionType } from '../types';
import { formatCurrency, formatNumber } from '../utils';
import { 
  AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, 
  PieChart, Pie, Cell
} from 'recharts';
import { 
  ArrowUpRight, ArrowDownRight, TrendingUp, TrendingDown, 
  Wallet, Target, Activity, ChevronLeft, PieChart as PieChartIcon, 
  Clock, DollarSign, Zap, Star, Plus, Coins, ArrowRight
} from 'lucide-react';
import { DashboardSkeleton } from './LoadingSkeletons';

interface DashboardProps {
  holdings: Holding[];
  transactions: Transaction[];
  financialGoal: number;
  setFinancialGoal?: (val: number) => void;
  onOpenGoalModal: () => void;
  investedAmount: number;
  cashBalance: number;
  portfolioValue: number;
  chartData: ChartDataPoint[];
  isLoading?: boolean;
  // New props for quick actions
  onQuickAction: (type: TransactionType) => void;
}

const COLORS = ['#3b82f6', '#10b981', '#f59e0b', '#ef4444', '#8b5cf6', '#ec4899', '#6366f1', '#14b8a6'];

const CustomTooltip = ({ active, payload, label }: any) => {
  if (active && payload && payload.length) {
    return (
      <div className="bg-white/95 dark:bg-slate-900/95 backdrop-blur-md border border-slate-200 dark:border-slate-700 p-4 rounded-xl shadow-xl transition-colors duration-200">
        {label && <p className="text-xs font-bold text-slate-500 dark:text-slate-400 uppercase tracking-wider mb-2">{label}</p>}
        <div className="space-y-1.5">
          {payload.map((entry: any, index: number) => (
            <div key={index} className="flex items-center justify-between gap-6 text-sm">
              <div className="flex items-center">
                 <div className="w-2.5 h-2.5 rounded-full mr-2 shadow-sm" style={{ backgroundColor: entry.color }}></div>
                 <span className="text-slate-600 dark:text-slate-300 font-medium capitalize">
                    {entry.name === 'value' ? 'Market Value' : entry.name === 'invested' ? 'Net Invested' : entry.name}
                 </span>
              </div>
              <span className="font-bold text-slate-900 dark:text-white font-mono tabular-nums">
                {formatCurrency(entry.value)}
              </span>
            </div>
          ))}
        </div>
      </div>
    );
  }
  return null;
};

const Dashboard: React.FC<DashboardProps> = ({ 
  holdings, transactions, financialGoal, onOpenGoalModal, investedAmount, portfolioValue, cashBalance, chartData, isLoading, onQuickAction
}) => {
  const [selectedCategory, setSelectedCategory] = useState<string | null>(null);

  const totalNetWorth = portfolioValue + cashBalance;
  const totalUnrealizedPL = holdings.reduce((sum, h) => sum + h.unrealizedPL, 0);
  const totalPLPercent = investedAmount > 0 ? (totalUnrealizedPL / investedAmount) * 100 : 0;

  // --- DERIVED DATA ---

  // 1. Allocation Data
  const categoryData = useMemo(() => {
    const data = holdings
      .filter(h => h.marketValue > 0)
      .map(h => ({ name: h.assetClass, value: h.marketValue }))
      .reduce((acc: any[], curr) => {
        const existing = acc.find(item => item.name === curr.name);
        if (existing) existing.value += curr.value;
        else acc.push({ ...curr });
        return acc;
      }, []);

    if (cashBalance > 0) {
       const cashCategory = data.find(item => item.name === 'Cash');
       if (cashCategory) cashCategory.value += cashBalance;
       else data.push({ name: 'Cash', value: cashBalance });
    }
    return data.sort((a, b) => b.value - a.value);
  }, [holdings, cashBalance]);

  const assetData = useMemo(() => {
    if (!selectedCategory) return [];
    const assets = holdings
      .filter(h => h.assetClass === selectedCategory && h.marketValue > 0)
      .map(h => ({ name: h.symbol, value: h.marketValue, fullName: h.name }));

    if (selectedCategory === 'Cash' && cashBalance > 0) {
        assets.push({ name: 'Wallet', value: cashBalance, fullName: 'Available Balance' });
    }
    return assets.sort((a, b) => b.value - a.value);
  }, [holdings, selectedCategory, cashBalance]);

  const activeChartData = selectedCategory ? assetData : categoryData;
  const activeTotalValue = activeChartData.reduce((sum, item) => sum + item.value, 0);

  // 2. Top Movers (Best performing assets by %)
  const topMovers = useMemo(() => {
     return [...holdings]
        .filter(h => h.marketValue > 0) // Only active
        .sort((a, b) => b.unrealizedPLPercent - a.unrealizedPLPercent)
        .slice(0, 3);
  }, [holdings]);

  // 3. Recent Transactions
  const recentTransactions = useMemo(() => {
     return [...transactions]
        .sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime())
        .slice(0, 4);
  }, [transactions]);

  if (isLoading) return <DashboardSkeleton />;

  // --- EMPTY STATE (Welcome Guide) ---
  if (transactions.length === 0) {
      return (
          <div className="space-y-8 animate-fade-in py-8">
              <div className="text-center space-y-4 max-w-2xl mx-auto">
                  <h2 className="text-4xl font-display font-bold text-slate-900 dark:text-white">Welcome to your Portfolio!</h2>
                  <p className="text-lg text-slate-500 dark:text-slate-400">
                      Track your investments, analyze performance, and reach your financial goals. Let's get you set up.
                  </p>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-3 gap-6 max-w-4xl mx-auto mt-12">
                  <div 
                    onClick={() => onQuickAction(TransactionType.DEPOSIT)}
                    className="group bg-white dark:bg-slate-800 p-8 rounded-3xl border border-slate-200 dark:border-slate-700 shadow-sm hover:shadow-xl hover:-translate-y-1 transition-all cursor-pointer flex flex-col items-center text-center"
                  >
                      <div className="w-16 h-16 bg-blue-100 dark:bg-blue-900/30 rounded-2xl flex items-center justify-center text-blue-600 dark:text-blue-400 mb-6 group-hover:scale-110 transition-transform">
                          <Wallet size={32} />
                      </div>
                      <h3 className="text-xl font-bold text-slate-900 dark:text-white mb-2">1. Add Cash</h3>
                      <p className="text-sm text-slate-500 mb-6">Record your initial deposit to start tracking your available capital.</p>
                      <span className="text-blue-600 font-bold text-sm flex items-center">Start Now <ArrowRight size={16} className="ml-1"/></span>
                  </div>

                  <div 
                    onClick={() => onQuickAction(TransactionType.BUY)}
                    className="group bg-white dark:bg-slate-800 p-8 rounded-3xl border border-slate-200 dark:border-slate-700 shadow-sm hover:shadow-xl hover:-translate-y-1 transition-all cursor-pointer flex flex-col items-center text-center"
                  >
                      <div className="w-16 h-16 bg-emerald-100 dark:bg-emerald-900/30 rounded-2xl flex items-center justify-center text-emerald-600 dark:text-emerald-400 mb-6 group-hover:scale-110 transition-transform">
                          <TrendingUp size={32} />
                      </div>
                      <h3 className="text-xl font-bold text-slate-900 dark:text-white mb-2">2. Buy Assets</h3>
                      <p className="text-sm text-slate-500 mb-6">Log your stocks, crypto, or ETFs purchases to see your portfolio grow.</p>
                      <span className="text-emerald-600 font-bold text-sm flex items-center">Start Now <ArrowRight size={16} className="ml-1"/></span>
                  </div>

                  <div 
                    onClick={onOpenGoalModal}
                    className="group bg-white dark:bg-slate-800 p-8 rounded-3xl border border-slate-200 dark:border-slate-700 shadow-sm hover:shadow-xl hover:-translate-y-1 transition-all cursor-pointer flex flex-col items-center text-center"
                  >
                      <div className="w-16 h-16 bg-purple-100 dark:bg-purple-900/30 rounded-2xl flex items-center justify-center text-purple-600 dark:text-purple-400 mb-6 group-hover:scale-110 transition-transform">
                          <Target size={32} />
                      </div>
                      <h3 className="text-xl font-bold text-slate-900 dark:text-white mb-2">3. Set a Goal</h3>
                      <p className="text-sm text-slate-500 mb-6">Define your financial target to keep yourself motivated.</p>
                      <span className="text-purple-600 font-bold text-sm flex items-center">Start Now <ArrowRight size={16} className="ml-1"/></span>
                  </div>
              </div>
          </div>
      );
  }

  return (
    <div className="space-y-6 animate-fade-in pb-12">

      {/* --- QUICK ACTIONS --- */}
      <div className="flex gap-4 overflow-x-auto pb-2 no-scrollbar">
          <button onClick={() => onQuickAction(TransactionType.DEPOSIT)} className="flex items-center gap-2 px-4 py-2.5 bg-white dark:bg-slate-800 rounded-xl border border-slate-200 dark:border-slate-700 shadow-sm hover:bg-slate-50 dark:hover:bg-slate-700 transition-colors whitespace-nowrap">
              <div className="bg-blue-100 dark:bg-blue-900/30 text-blue-600 p-1 rounded-lg"><Plus size={14} strokeWidth={3}/></div>
              <span className="text-sm font-bold text-slate-700 dark:text-slate-200">Deposit Cash</span>
          </button>
          <button onClick={() => onQuickAction(TransactionType.BUY)} className="flex items-center gap-2 px-4 py-2.5 bg-white dark:bg-slate-800 rounded-xl border border-slate-200 dark:border-slate-700 shadow-sm hover:bg-slate-50 dark:hover:bg-slate-700 transition-colors whitespace-nowrap">
              <div className="bg-emerald-100 dark:bg-emerald-900/30 text-emerald-600 p-1 rounded-lg"><TrendingUp size={14} strokeWidth={2.5}/></div>
              <span className="text-sm font-bold text-slate-700 dark:text-slate-200">Buy Asset</span>
          </button>
          <button onClick={() => onQuickAction(TransactionType.DIVIDEND)} className="flex items-center gap-2 px-4 py-2.5 bg-white dark:bg-slate-800 rounded-xl border border-slate-200 dark:border-slate-700 shadow-sm hover:bg-slate-50 dark:hover:bg-slate-700 transition-colors whitespace-nowrap">
              <div className="bg-amber-100 dark:bg-amber-900/30 text-amber-600 p-1 rounded-lg"><Coins size={14} strokeWidth={2.5}/></div>
              <span className="text-sm font-bold text-slate-700 dark:text-slate-200">Record Dividend</span>
          </button>
      </div>

      {/* --- ROW 1: PRIMARY METRICS --- */}
      <div className="grid grid-cols-1 md:grid-cols-12 gap-6">

        {/* Total Net Worth Card (Simple & Bold) */}
        <div className="md:col-span-7 relative overflow-hidden rounded-3xl p-8 bg-slate-900 text-white shadow-2xl shadow-slate-900/20 flex flex-col justify-center min-h-[220px]">
          <div className="absolute inset-0 bg-gradient-to-br from-indigo-900 to-slate-950"></div>
          {/* Abstract blobs */}
          <div className="absolute -top-24 -right-24 w-64 h-64 bg-indigo-500/20 rounded-full blur-[80px]"></div>
          <div className="absolute -bottom-24 -left-24 w-64 h-64 bg-blue-500/20 rounded-full blur-[80px]"></div>

          <div className="relative z-10">
             <div className="flex items-center gap-2 mb-3">
                <div className="p-1.5 bg-white/10 rounded-lg backdrop-blur-md">
                    <Wallet size={18} className="text-indigo-200" />
                </div>
                <p className="text-indigo-200 font-bold text-sm uppercase tracking-wider">Total Net Worth</p>
             </div>
             <h2 className="text-5xl sm:text-6xl font-display font-bold tracking-tight text-white mb-6">
               {formatCurrency(totalNetWorth)}
             </h2>

             <div className="flex gap-6">
                 <div className="bg-white/10 backdrop-blur-md px-4 py-2.5 rounded-xl border border-white/5">
                     <p className="text-[10px] text-indigo-200 font-bold uppercase tracking-wider mb-0.5">Cash</p>
                     <p className="text-lg font-bold font-mono">{formatCurrency(cashBalance)}</p>
                 </div>
                 <div className="bg-white/10 backdrop-blur-md px-4 py-2.5 rounded-xl border border-white/5">
                     <p className="text-[10px] text-indigo-200 font-bold uppercase tracking-wider mb-0.5">Invested</p>
                     <p className="text-lg font-bold font-mono">{formatCurrency(portfolioValue)}</p>
                 </div>
             </div>
          </div>
        </div>

        {/* Right Column: P/L & Goal */}
        <div className="md:col-span-5 flex flex-col gap-6">

            {/* P/L Card */}
            <div className={`flex-1 rounded-3xl p-6 border shadow-sm flex flex-col justify-center relative overflow-hidden ${
                totalUnrealizedPL >= 0 
                ? 'bg-emerald-50 border-emerald-100 dark:bg-emerald-900/10 dark:border-emerald-900/30' 
                : 'bg-rose-50 border-rose-100 dark:bg-rose-900/10 dark:border-rose-900/30'
            }`}>
                 <div className="relative z-10">
                    <div className="flex items-center gap-2 mb-2">
                        {totalUnrealizedPL >= 0 ? <TrendingUp size={18} className="text-emerald-600" /> : <TrendingDown size={18} className="text-rose-600" />}
                        <p className={`text-xs font-bold uppercase tracking-wider ${totalUnrealizedPL >= 0 ? 'text-emerald-600 dark:text-emerald-400' : 'text-rose-600 dark:text-rose-400'}`}>Total Profit / Loss</p>
                    </div>
                    <h3 className={`text-3xl font-bold font-display ${totalUnrealizedPL >= 0 ? 'text-emerald-700 dark:text-emerald-400' : 'text-rose-700 dark:text-rose-400'}`}>
                        {totalUnrealizedPL >= 0 ? '+' : ''}{formatCurrency(totalUnrealizedPL)}
                    </h3>
                    <div className={`mt-3 inline-flex items-center px-3 py-1.5 rounded-xl text-xs font-bold w-fit bg-white/60 dark:bg-black/20 backdrop-blur-sm ${totalPLPercent >= 0 ? 'text-emerald-700 dark:text-emerald-400' : 'text-rose-700 dark:text-rose-400'}`}>
                        {totalPLPercent >= 0 ? <ArrowUpRight size={14} className="mr-1"/> : <ArrowDownRight size={14} className="mr-1"/>}
                        {Math.abs(totalPLPercent).toFixed(2)}% Return
                    </div>
                 </div>
            </div>

            {/* Goal Progress */}
            <div className="bg-white dark:bg-slate-800 rounded-3xl p-5 border border-slate-200 dark:border-slate-700 flex items-center gap-4 cursor-pointer hover:border-indigo-300 transition-colors shadow-sm" onClick={onOpenGoalModal}>
                <div className="w-12 h-12 rounded-2xl bg-indigo-100 dark:bg-indigo-900/30 flex items-center justify-center text-indigo-600 dark:text-indigo-400 shrink-0">
                   <Target size={24} />
                </div>
                <div className="flex-1">
                    <div className="flex justify-between items-center mb-1.5">
                        <p className="text-xs font-bold text-slate-500 dark:text-slate-400 uppercase">Goal Progress</p>
                        <p className="text-xs font-bold text-indigo-600 dark:text-indigo-400">{((totalNetWorth / financialGoal) * 100).toFixed(0)}%</p>
                    </div>
                    <div className="w-full bg-slate-100 dark:bg-slate-700 h-2.5 rounded-full overflow-hidden">
                        <div className="bg-indigo-500 h-full rounded-full transition-all duration-1000" style={{ width: `${Math.min((totalNetWorth / financialGoal) * 100, 100)}%` }}></div>
                    </div>
                </div>
            </div>
        </div>
      </div>

      {/* --- ROW 2: CHARTS & MOVERS --- */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">

        {/* Wealth Chart (Span 2) */}
        <div className="lg:col-span-2 bg-white dark:bg-slate-800 rounded-3xl p-6 md:p-8 border border-slate-200 dark:border-slate-700 shadow-sm">
           <div className="flex items-center justify-between mb-8">
             <div>
                <h3 className="text-lg font-bold text-slate-900 dark:text-white">Growth History</h3>
                <p className="text-xs text-slate-500 mt-1">Value over time vs Invested capital</p>
             </div>
             <div className="hidden sm:flex items-center space-x-4 text-xs font-bold">
                  <div className="flex items-center text-blue-500"><div className="w-2 h-2 bg-blue-500 rounded-full mr-2"></div> Market Value</div>
                  <div className="flex items-center text-slate-400"><div className="w-2 h-2 bg-slate-300 rounded-full mr-2"></div> Cost Basis</div>
              </div>
           </div>

           <div className="h-[280px] w-full">
            {chartData.length > 0 ? (
              <ResponsiveContainer width="100%" height="100%">
              <AreaChart data={chartData} margin={{ top: 10, right: 10, left: 0, bottom: 0 }}>
                <defs>
                  <linearGradient id="colorValue" x1="0" y1="0" x2="0" y2="1">
                    <stop offset="5%" stopColor="#3b82f6" stopOpacity={0.2}/>
                    <stop offset="95%" stopColor="#3b82f6" stopOpacity={0}/>
                  </linearGradient>
                </defs>
                <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" opacity={0.4} vertical={false} />
                <XAxis 
                  dataKey="date" 
                  axisLine={false} tickLine={false} tick={{fill: '#94a3b8', fontSize: 11}} dy={15} minTickGap={40} 
                />
                <YAxis 
                  axisLine={false} tickLine={false} tick={{fill: '#94a3b8', fontSize: 11}} 
                  tickFormatter={(val) => val >= 1000 ? (val/1000).toFixed(0) + 'k' : val}
                />
                <Tooltip content={<CustomTooltip />} />
                <Area type="monotone" dataKey="value" stroke="#3b82f6" strokeWidth={3} fillOpacity={1} fill="url(#colorValue)" />
                <Area type="monotone" dataKey="invested" stroke="#cbd5e1" strokeDasharray="4 4" strokeWidth={2} fill="transparent" />
              </AreaChart>
            </ResponsiveContainer>
            ) : (
              <div className="flex h-full flex-col items-center justify-center text-slate-400 bg-slate-50 dark:bg-slate-900/50 rounded-2xl border-2 border-dashed border-slate-200 dark:border-slate-700">
                <Activity className="mb-2 opacity-50" size={32} />
                <p>No data to display yet.</p>
              </div>
            )}
          </div>
        </div>

        {/* Top Movers (Span 1) */}
        <div className="bg-white dark:bg-slate-800 rounded-3xl p-6 border border-slate-200 dark:border-slate-700 shadow-sm flex flex-col">
           <div className="flex items-center justify-between mb-4">
              <h3 className="font-bold text-slate-900 dark:text-white flex items-center">
                 <Star size={18} className="text-amber-400 mr-2 fill-amber-400" /> Top Performers
              </h3>
           </div>

           <div className="flex-1 space-y-3">
              {topMovers.length > 0 ? (
                 topMovers.map((h, i) => (
                    <div key={h.symbol} className="flex items-center justify-between p-3 rounded-2xl bg-slate-50 dark:bg-slate-900/50 hover:bg-slate-100 dark:hover:bg-slate-900 transition-colors">
                       <div className="flex items-center space-x-3">
                          <div className={`w-10 h-10 rounded-xl flex items-center justify-center text-xs font-bold text-slate-700 dark:text-slate-200 bg-white dark:bg-slate-800 shadow-sm border border-slate-100 dark:border-slate-700`}>
                             {h.symbol.substring(0,2)}
                          </div>
                          <div>
                             <div className="font-bold text-sm text-slate-900 dark:text-white">{h.symbol}</div>
                             <div className="text-[10px] text-slate-500 uppercase font-bold">{h.assetClass}</div>
                          </div>
                       </div>
                       <div className="text-right">
                          <div className="text-xs font-bold text-emerald-600 dark:text-emerald-400 flex items-center justify-end">
                             <ArrowUpRight size={12} className="mr-0.5" />
                             {h.unrealizedPLPercent.toFixed(2)}%
                          </div>
                          <div className="text-[10px] text-slate-400 font-mono">
                             {formatCurrency(h.marketValue)}
                          </div>
                       </div>
                    </div>
                 ))
              ) : (
                 <div className="h-full flex flex-col items-center justify-center text-slate-400 text-sm italic opacity-70">
                    <Star size={32} className="mb-2 opacity-50" />
                    <span>No active positions</span>
                 </div>
              )}
           </div>
        </div>
      </div>

      {/* --- ROW 3: ALLOCATION & RECENT ACTIVITY --- */}
      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">

        {/* Allocation Donut */}
        <div className="bg-white dark:bg-slate-800 rounded-3xl p-6 md:p-8 border border-slate-200 dark:border-slate-700 shadow-sm flex flex-col relative h-[340px]">
           <div className="flex items-center justify-between mb-2">
               <div>
                  <h3 className="font-bold text-slate-900 dark:text-white flex items-center">
                    <PieChartIcon size={18} className="mr-2 text-slate-400" /> Allocation
                  </h3>
                  <p className="text-xs text-slate-500 mt-0.5">{selectedCategory || 'By Asset Class'}</p>
               </div>
               {selectedCategory && (
                  <button onClick={() => setSelectedCategory(null)} className="p-1.5 bg-slate-100 dark:bg-slate-700 rounded-full text-slate-500 hover:text-slate-900 transition-colors">
                     <ChevronLeft size={16} />
                  </button>
               )}
           </div>

           <div className="flex items-center h-full">
              {/* Chart Side */}
              <div className="flex-1 h-[200px] relative">
                  {activeChartData.length > 0 ? (
                     <ResponsiveContainer width="100%" height="100%">
                      <PieChart>
                        <Pie
                          data={activeChartData}
                          cx="50%"
                          cy="50%"
                          innerRadius={55}
                          outerRadius={75}
                          paddingAngle={5}
                          dataKey="value"
                          cornerRadius={5}
                          onClick={(data) => {
                             const clickedName = data.name || data.payload?.name;
                             if (!selectedCategory && clickedName && clickedName !== 'Wallet') {
                                setSelectedCategory(clickedName);
                             }
                          }}
                          className={!selectedCategory ? 'cursor-pointer' : ''}
                        >
                          {activeChartData.map((entry, index) => (
                            <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} strokeWidth={0} />
                          ))}
                        </Pie>
                        <Tooltip content={<CustomTooltip />} />
                      </PieChart>
                    </ResponsiveContainer>
                  ) : (
                     <div className="text-slate-300 flex flex-col items-center justify-center h-full">
                        <PieChartIcon size={40} className="mb-2" />
                        <span className="text-sm">No assets</span>
                     </div>
                  )}
                  {/* Center Text */}
                  {activeChartData.length > 0 && (
                     <div className="absolute inset-0 flex flex-col items-center justify-center pointer-events-none">
                        <span className="text-[10px] text-slate-400 font-bold uppercase tracking-wider">Total</span>
                        <span className="text-sm font-bold text-slate-900 dark:text-white">{formatCurrency(activeTotalValue).split('.')[0]}</span>
                     </div>
                  )}
              </div>

              {/* Legend Side */}
              <div className="w-40 pl-4 h-[200px] overflow-y-auto custom-scrollbar space-y-2">
                 {activeChartData.map((entry, idx) => (
                    <div key={idx} className="flex items-center justify-between text-xs cursor-pointer group hover:bg-slate-50 dark:hover:bg-slate-700/50 p-1 rounded-lg" onClick={() => !selectedCategory && setSelectedCategory(entry.name)}>
                       <div className="flex items-center">
                          <div className="w-2.5 h-2.5 rounded-full mr-2" style={{ backgroundColor: COLORS[idx % COLORS.length] }}></div>
                          <span className="text-slate-600 dark:text-slate-300 font-medium truncate max-w-[70px]">{entry.name}</span>
                       </div>
                       <div className="font-bold text-slate-900 dark:text-white">
                          {((entry.value / activeTotalValue) * 100).toFixed(0)}%
                       </div>
                    </div>
                 ))}
              </div>
           </div>
        </div>

        {/* Recent Activity Feed */}
        <div className="bg-white dark:bg-slate-800 rounded-3xl p-6 md:p-8 border border-slate-200 dark:border-slate-700 shadow-sm flex flex-col h-[340px]">
           <div className="flex items-center justify-between mb-4">
              <h3 className="font-bold text-slate-900 dark:text-white flex items-center">
                 <Clock size={18} className="mr-2 text-slate-400" /> Recent Activity
              </h3>
           </div>

           <div className="flex-1 overflow-y-auto custom-scrollbar pr-2 space-y-3">
              {recentTransactions.length > 0 ? (
                 recentTransactions.map((tx) => (
                   <div key={tx.id} className="flex items-center justify-between p-3 rounded-2xl bg-slate-50 dark:bg-slate-900/50">
                      <div className="flex items-center space-x-3">
                          <div className={`w-9 h-9 rounded-xl flex items-center justify-center text-xs font-bold ${
                             tx.type === 'BUY' ? 'bg-blue-100 text-blue-600 dark:bg-blue-900/30 dark:text-blue-400' :
                             tx.type === 'SELL' ? 'bg-rose-100 text-rose-600 dark:bg-rose-900/30 dark:text-rose-400' :
                             tx.type === 'DIVIDEND' ? 'bg-emerald-100 text-emerald-600 dark:bg-emerald-900/30 dark:text-emerald-400' :
                             'bg-slate-200 text-slate-600 dark:bg-slate-700 dark:text-slate-300'
                          }`}>
                              {tx.type === 'BUY' ? <TrendingUp size={16} /> : 
                               tx.type === 'SELL' ? <TrendingDown size={16} /> :
                               tx.type === 'DIVIDEND' ? <Coins size={16} /> : 
                               tx.type === 'DEPOSIT' ? <Plus size={16} /> : <ArrowRight size={16} />}
                          </div>
                          <div>
                             <div className="font-bold text-sm text-slate-900 dark:text-white">{tx.symbol || tx.type}</div>
                             <div className="text-[10px] text-slate-400">{new Date(tx.date).toLocaleDateString()}</div>
                          </div>
                      </div>
                      <div className="text-right">
                         <div className={`text-sm font-bold font-mono ${
                            (tx.type === 'SELL' || tx.type === 'DIVIDEND' || tx.type === 'DEPOSIT') ? 'text-emerald-600 dark:text-emerald-400' : 'text-slate-900 dark:text-white'
                         }`}>
                             {(tx.type === 'SELL' || tx.type === 'DIVIDEND' || tx.type === 'DEPOSIT') ? '+' : ''}
                             {formatCurrency((tx.price || 0) * (tx.shares || 1))}
                         </div>
                         {tx.type === 'BUY' && tx.shares && <div className="text-[10px] text-slate-400">{formatNumber(tx.shares)} units</div>}
                      </div>
                   </div>
                 ))
              ) : (
                 <div className="h-full flex flex-col items-center justify-center text-slate-400 text-sm italic opacity-70">
                    <Clock size={32} className="mb-2 opacity-50" />
                    <span>No transactions yet</span>
                 </div>
              )}
           </div>
        </div>

      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import Layout from './components/Layout';
import Dashboard from './components/Dashboard';
import Holdings from './components/Holdings';
import Reports from './components/Reports';
import History from './components/History';
import GoalModal from './components/GoalModal';
import { Transaction, TransactionType, AssetClass, Holding, Portfolio, FinancialGoal } from './types';
import { calculateHoldings, calculatePortfolioHistory, generateId, formatCurrency, formatNumber } from './utils';
import { X, Save, TrendingUp, TrendingDown, DollarSign, Wallet, Calendar, GitFork, AlertCircle, ArrowRight, Trash2, Zap, Calculator, Search, Clock, PlusCircle, MinusCircle, RefreshCcw, Split, Hash, ChevronDown, ArrowRightCircle, Globe, CheckCircle2, FileText, Banknote, Percent, Info, Coins, Plus } from 'lucide-react';
import { Spinner } from './components/LoadingSkeletons';

const POPULAR_SYMBOLS = [
  'AAPL', 'MSFT', 'GOOGL', 'AMZN', 'NVDA', 'TSLA', 'META', 'BRK.B', 'V', 'JNJ', 'WMT', 'JPM', // Tech/Blue Chip
  'VOO', 'VTI', 'QQQ', 'IVV', 'SCHD', 'JEPI', 'VUG', 'VTV', // ETFs
  'BTC', 'ETH', 'SOL', 'USDT', 'BNB', 'XRP', 'ADA' // Crypto
];

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState('dashboard');
  const [isAddModalOpen, setIsAddModalOpen] = useState(false);
  const [editingTransaction, setEditingTransaction] = useState<Partial<Transaction> | null>(null);

  // Persistence for better UX
  const [lastTxDate, setLastTxDate] = useState<string>(() => localStorage.getItem('lastTxDate') || new Date().toISOString().split('T')[0]);

  // Goal Modal State
  const [isGoalModalOpen, setIsGoalModalOpen] = useState(false);

  // --- CONFIRMATION MODAL STATE ---
  const [confirmConfig, setConfirmConfig] = useState<{
    isOpen: boolean;
    title: string;
    message: string;
    onConfirm: () => void;
  }>({
    isOpen: false,
    title: '',
    message: '',
    onConfirm: () => {},
  });

  // --- PORTFOLIO MANAGEMENT STATE ---
  const [portfolios, setPortfolios] = useState<Portfolio[]>(() => {
    const saved = localStorage.getItem('portfolios');
    if (saved) return JSON.parse(saved);
    const legacyTx = localStorage.getItem('transactions');
    if (legacyTx) return [{ id: 'default', name: 'Main Portfolio' }];
    return [{ id: generateId(), name: 'My First Portfolio' }];
  });

  const [activePortfolioId, setActivePortfolioId] = useState<string>(() => {
    const saved = localStorage.getItem('activePortfolioId');
    const portfolios = JSON.parse(localStorage.getItem('portfolios') || '[]');
    if (saved && portfolios.some((p: Portfolio) => p.id === saved)) return saved;
    return portfolios.length > 0 ? portfolios[0].id : 'default';
  });

  // --- DATA STATE (Per Portfolio) - Synchronous Initialization ---
  const [transactions, setTransactions] = useState<Transaction[]>(() => {
    const key = `transactions_${activePortfolioId}`;
    const saved = localStorage.getItem(key);
    if (saved) return JSON.parse(saved);
    if (activePortfolioId === 'default') {
      const legacy = localStorage.getItem('transactions');
      if (legacy) return JSON.parse(legacy);
    }
    return [];
  });

  const [prices, setPrices] = useState<Record<string, number>>(() => {
    const key = `prices_${activePortfolioId}`;
    const saved = localStorage.getItem(key);
    if (saved) return JSON.parse(saved);
    if (activePortfolioId === 'default') {
      const legacy = localStorage.getItem('prices');
      if (legacy) return JSON.parse(legacy);
    }
    return {};
  });

  const [targets, setTargets] = useState<Record<string, number>>(() => {
    const key = `targets_${activePortfolioId}`;
    const saved = localStorage.getItem(key);
    if (saved) {
       try {
         // Fix: Handle null or invalid JSON gracefully
         const parsed = JSON.parse(saved);
         return parsed || {};
       } catch (e) {
         return {};
       }
    }
    return {};
  });

  const [goals, setGoals] = useState<FinancialGoal[]>(() => {
    const key = `goals_${activePortfolioId}`;
    const saved = localStorage.getItem(key);
    if (saved) return JSON.parse(saved);

    let legacyGoal = 100000;
    const legacyKey = `financialGoal_${activePortfolioId}`;
    const savedLegacy = localStorage.getItem(legacyKey);
    if (savedLegacy) legacyGoal = parseFloat(savedLegacy);
    else if (activePortfolioId === 'default' && localStorage.getItem('financialGoal')) legacyGoal = parseFloat(localStorage.getItem('financialGoal')!);

    return [{ id: generateId(), targetAmount: legacyGoal, startDate: new Date().toISOString(), isAchieved: false, notes: 'Initial Goal' }];
  });

  const [isDataLoaded, setIsDataLoaded] = useState(true);
  const [isLoading, setIsLoading] = useState(false);
  const isFirstMount = useRef(true);

  // --- PERSISTENCE ---
  useEffect(() => { localStorage.setItem('portfolios', JSON.stringify(portfolios)); }, [portfolios]);
  useEffect(() => { localStorage.setItem('activePortfolioId', activePortfolioId); }, [activePortfolioId]);

  useEffect(() => {
    if (isFirstMount.current) { isFirstMount.current = false; return; }
    setIsLoading(true);
    setIsDataLoaded(false);
    const loadData = () => {
        const txKey = `transactions_${activePortfolioId}`;
        const pricesKey = `prices_${activePortfolioId}`;
        const goalsKey = `goals_${activePortfolioId}`;
        const targetsKey = `targets_${activePortfolioId}`;

        const savedTx = localStorage.getItem(txKey);
        setTransactions(savedTx ? JSON.parse(savedTx) : []);

        const savedPrices = localStorage.getItem(pricesKey);
        setPrices(savedPrices ? JSON.parse(savedPrices) : {});

        const savedTargets = localStorage.getItem(targetsKey);
        // Safe parsing for targets
        try {
            const parsedTargets = savedTargets ? JSON.parse(savedTargets) : {};
            setTargets(parsedTargets || {});
        } catch {
            setTargets({});
        }

        const savedGoals = localStorage.getItem(goalsKey);
        setGoals(savedGoals ? JSON.parse(savedGoals) : []); 

        setIsDataLoaded(true);
        setTimeout(() => setIsLoading(false), 500);
    };
    requestAnimationFrame(loadData);
  }, [activePortfolioId]);

  useEffect(() => { if (isDataLoaded) localStorage.setItem(`transactions_${activePortfolioId}`, JSON.stringify(transactions)); }, [transactions, activePortfolioId, isDataLoaded]);
  useEffect(() => { if (isDataLoaded) localStorage.setItem(`prices_${activePortfolioId}`, JSON.stringify(prices)); }, [prices, activePortfolioId, isDataLoaded]);
  useEffect(() => { if (isDataLoaded) localStorage.setItem(`targets_${activePortfolioId}`, JSON.stringify(targets)); }, [targets, activePortfolioId, isDataLoaded]);
  useEffect(() => { if (isDataLoaded) localStorage.setItem(`goals_${activePortfolioId}`, JSON.stringify(goals)); }, [goals, activePortfolioId, isDataLoaded]);

  // --- CALCULATIONS ---
  const holdings = useMemo(() => calculateHoldings(transactions, prices, targets), [transactions, prices, targets]);
  const chartData = useMemo(() => calculatePortfolioHistory(transactions, prices), [transactions, prices]);
  const investedAmount = transactions.reduce((sum, t) => {
    if (t.type === TransactionType.DEPOSIT) return sum + (t.price || 0);
    if (t.type === TransactionType.WITHDRAW) return sum - (t.price || 0);
    return sum;
  }, 0);
  const cashBalance = useMemo(() => {
    let balance = 0;
    transactions.forEach(t => {
      if (t.type === TransactionType.DEPOSIT) balance += (t.price || 0);
      if (t.type === TransactionType.WITHDRAW) balance -= (t.price || 0);
      if (t.type === TransactionType.BUY) balance -= (t.price! * t.shares!) + (t.fee || 0);
      if (t.type === TransactionType.SELL) balance += (t.price! * t.shares!) - (t.fee || 0);
      if (t.type === TransactionType.DIVIDEND) balance += (t.price || 0);
    });
    return balance;
  }, [transactions]);
  const portfolioValue = holdings.reduce((sum, h) => sum + h.marketValue, 0);
  const totalNetWorth = portfolioValue + cashBalance;
  const activeGoal = useMemo(() => goals.find(g => !g.endDate) || { targetAmount: 100000 } as FinancialGoal, [goals]);

  // --- HANDLERS ---
  const handleOpenAddModal = (initialState?: Partial<Transaction>) => { 
      setEditingTransaction(initialState || null); 
      setIsAddModalOpen(true); 
  };
  const handleOpenEditModal = (tx: Transaction) => { setEditingTransaction(tx); setIsAddModalOpen(true); };

  const handleSaveTransaction = (tx: Transaction) => {
    return new Promise<void>((resolve) => {
      if (editingTransaction && editingTransaction.id) {
         setTransactions(prev => prev.map(t => t.id === tx.id ? tx : t));
      } else {
         setTransactions(prev => [...prev, tx]);
      }

      // Update price reference
      if ((tx.type === TransactionType.BUY || tx.type === TransactionType.SELL) && tx.symbol && tx.price) {
        setPrices(prev => ({...prev, [tx.symbol!]: tx.price!}));
      }

      // Update Last Used Date Persistence
      setLastTxDate(tx.date);
      localStorage.setItem('lastTxDate', tx.date);

      setIsAddModalOpen(false); 
      setEditingTransaction(null); 
      resolve();
    });
  };

  const handleUpdatePrice = (symbol: string, newPrice: number) => setPrices(prev => ({ ...prev, [symbol]: newPrice }));
  const handleUpdateTarget = (symbol: string, target: number) => setTargets(prev => ({ ...prev, [symbol]: target }));

  const handleDeleteTransaction = (id: string) => {
    setTransactions(prev => prev.filter(t => t.id !== id));
    if (editingTransaction && editingTransaction.id === id) { setIsAddModalOpen(false); setEditingTransaction(null); }
  };
  const handleRequestDelete = (id: string) => {
      setConfirmConfig({ isOpen: true, title: 'Delete Transaction', message: 'Permanently remove this record?', onConfirm: () => { handleDeleteTransaction(id); setConfirmConfig(prev => ({ ...prev, isOpen: false })); } });
  };
  const handleImportTransactions = (importedTxs: Transaction[]) => {
      setTransactions(prev => {
          const currentMap = new Map(prev.map(t => [t.id, t]));
          importedTxs.forEach(t => { currentMap.set(t.id, t); });
          return Array.from(currentMap.values());
      });
  };

  // Portfolios
  const handleCreatePortfolio = (name: string) => { const newId = generateId(); setPortfolios([...portfolios, { id: newId, name }]); setActivePortfolioId(newId); };
  const handleRenamePortfolio = (id: string, newName: string) => { setPortfolios(prev => prev.map(p => p.id === id ? { ...p, name: newName } : p)); };
  const handleDeletePortfolio = (id: string) => {
    if (portfolios.length <= 1) { alert("Cannot delete last portfolio"); return; }
    setConfirmConfig({
        isOpen: true, title: 'Delete Portfolio', message: 'Delete entire portfolio and all data?', 
        onConfirm: () => {
             localStorage.removeItem(`transactions_${id}`); localStorage.removeItem(`prices_${id}`); localStorage.removeItem(`goals_${id}`); localStorage.removeItem(`targets_${id}`);
             const newPortfolios = portfolios.filter(p => p.id !== id); setPortfolios(newPortfolios);
             if (activePortfolioId === id) setActivePortfolioId(newPortfolios[0].id);
             setConfirmConfig(prev => ({ ...prev, isOpen: false }));
        }
    });
  };

  // Goals
  const handleSetNewGoal = (targetAmount: number, notes: string) => {
    const now = new Date().toISOString();
    setGoals(prev => [...prev.map(g => !g.endDate ? { ...g, endDate: now, isAchieved: totalNetWorth >= g.targetAmount } : g), { id: generateId(), targetAmount, startDate: now, isAchieved: false, notes }]);
  };
  const handleEditGoal = (updatedGoal: FinancialGoal) => setGoals(prev => prev.map(g => g.id === updatedGoal.id ? updatedGoal : g));
  const handleDeleteGoal = (id: string) => setGoals(prev => prev.filter(g => g.id !== id));

  return (
    <Layout 
      activeTab={activeTab} setActiveTab={setActiveTab} onOpenAddModal={() => handleOpenAddModal()}
      portfolios={portfolios} activePortfolioId={activePortfolioId} onSwitchPortfolio={setActivePortfolioId}
      onCreatePortfolio={handleCreatePortfolio} onRenamePortfolio={handleRenamePortfolio} onDeletePortfolio={handleDeletePortfolio}
    >
      <div key={activePortfolioId} className="h-full">
        {activeTab === 'dashboard' && (
            <Dashboard 
                isLoading={isLoading} 
                holdings={holdings} 
                transactions={transactions} 
                financialGoal={activeGoal.targetAmount} 
                onOpenGoalModal={() => setIsGoalModalOpen(true)} 
                investedAmount={investedAmount} 
                cashBalance={cashBalance} 
                portfolioValue={portfolioValue} 
                chartData={chartData} 
                onQuickAction={(type) => handleOpenAddModal({ type })}
            />
        )}
        {activeTab === 'holdings' && (
            <Holdings 
                isLoading={isLoading} 
                holdings={holdings} 
                transactions={transactions} 
                cashBalance={cashBalance}
                onUpdatePrice={handleUpdatePrice} 
                onUpdateTarget={handleUpdateTarget} 
                onTrade={(symbol, type) => handleOpenAddModal({ symbol, type })}
            />
        )}
        {activeTab === 'history' && <History isLoading={isLoading} transactions={transactions} onDelete={handleRequestDelete} onEdit={handleOpenEditModal} onAdd={handleOpenAddModal} onImport={handleImportTransactions} />}
        {activeTab === 'reports' && <Reports isLoading={isLoading} transactions={transactions} holdings={holdings} currentPortfolioValue={portfolioValue + cashBalance} chartData={chartData} />}
      </div>

      {isAddModalOpen && (
        <div className="fixed inset-0 z-50 flex items-end sm:items-center justify-center sm:p-4">
          <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-sm animate-fade-in" onClick={() => setIsAddModalOpen(false)}></div>
          <div className="relative bg-white dark:bg-slate-900 w-full max-w-2xl rounded-t-3xl sm:rounded-3xl shadow-2xl overflow-hidden animate-slide-up flex flex-col max-h-[90dvh]">
            <AddTransactionForm 
              onClose={() => setIsAddModalOpen(false)} 
              onSave={handleSaveTransaction} 
              onDelete={handleRequestDelete} 
              cashBalance={cashBalance} 
              holdings={holdings} 
              prices={prices} 
              transactions={transactions} 
              initialData={editingTransaction as Transaction | null}
              defaultDate={lastTxDate}
            />
          </div>
        </div>
      )}

      <GoalModal isOpen={isGoalModalOpen} onClose={() => setIsGoalModalOpen(false)} goals={goals} currentNetWorth={totalNetWorth} onSetGoal={handleSetNewGoal} onEditGoal={handleEditGoal} onDeleteGoal={handleDeleteGoal} />

      {confirmConfig.isOpen && (
        <div className="fixed inset-0 z-[70] flex items-center justify-center p-4 animate-fade-in">
          <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-sm" onClick={() => setConfirmConfig(prev => ({ ...prev, isOpen: false }))}></div>
          <div className="relative bg-white dark:bg-slate-900 rounded-2xl shadow-2xl w-full max-w-sm overflow-hidden animate-zoom-in p-6 text-center">
              <Trash2 size={40} className="mx-auto text-rose-500 mb-4" />
              <h3 className="text-lg font-bold text-slate-900 dark:text-white mb-2">{confirmConfig.title}</h3>
              <p className="text-sm text-slate-500 dark:text-slate-400 mb-6">{confirmConfig.message}</p>
              <div className="flex space-x-3">
                <button onClick={() => setConfirmConfig(prev => ({ ...prev, isOpen: false }))} className="flex-1 py-3 rounded-xl font-bold bg-slate-100 dark:bg-slate-800 text-slate-600 dark:text-slate-400">Cancel</button>
                <button onClick={confirmConfig.onConfirm} className="flex-1 py-3 rounded-xl font-bold bg-rose-600 text-white shadow-lg shadow-rose-600/20">Delete</button>
              </div>
          </div>
        </div>
      )}
    </Layout>
  );
};

interface AddTransactionFormProps {
  onClose: () => void;
  onSave: (t: Transaction) => Promise<void>;
  onDelete?: (id: string) => void;
  cashBalance: number;
  holdings: Holding[];
  prices: Record<string, number>;
  transactions: Transaction[];
  initialData: Transaction | null;
  defaultDate: string;
}

const AddTransactionForm: React.FC<AddTransactionFormProps> = ({ onClose, onSave, onDelete, cashBalance, holdings, prices, transactions, initialData, defaultDate }) => {
  const [step, setStep] = useState<'input' | 'review'>('input');

  const [type, setType] = useState<TransactionType>(TransactionType.BUY);
  const [date, setDate] = useState(defaultDate);
  const [symbol, setSymbol] = useState('');
  const [shares, setShares] = useState('');
  const [price, setPrice] = useState(''); // Price per share
  const [totalAmount, setTotalAmount] = useState(''); // Total transaction value
  const [fee, setFee] = useState('');
  const [assetClass, setAssetClass] = useState<AssetClass>(AssetClass.STOCK);
  const [exchangeRate, setExchangeRate] = useState(''); 
  const [notes, setNotes] = useState('');
  const [error, setError] = useState<string | null>(null);
  const [isSaving, setIsSaving] = useState(false);

  const [showSuggestions, setShowSuggestions] = useState(false);
  const wrapperRef = useRef<HTMLDivElement>(null);
  const notesRef = useRef<HTMLTextAreaElement>(null);

  // Validation logic helpers
  const needsSymbol = [TransactionType.BUY, TransactionType.SELL, TransactionType.DIVIDEND, TransactionType.SPLIT].includes(type);
  const needsShares = [TransactionType.BUY, TransactionType.SELL, TransactionType.SPLIT].includes(type);
  const needsPrice = type !== TransactionType.SPLIT;

  // FX Rate is relevant for: Deposits, Withdrawals, and Dividends (Foreign income)
  const hasExchangeRate = type === TransactionType.DEPOSIT || type === TransactionType.WITHDRAW || type === TransactionType.DIVIDEND;
  const isFunding = type === TransactionType.DEPOSIT || type === TransactionType.WITHDRAW;

  // Effects (Initialization, Auto-fill, Calculation)
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => { if (wrapperRef.current && !wrapperRef.current.contains(event.target as Node)) setShowSuggestions(false); };
    document.addEventListener("mousedown", handleClickOutside); return () => document.removeEventListener("mousedown", handleClickOutside);
  }, []);

  useEffect(() => {
    if (initialData) {
      if (initialData.type) setType(initialData.type);
      if (initialData.date) setDate(initialData.date);
      if (initialData.symbol) setSymbol(initialData.symbol);
      if (initialData.shares) setShares(initialData.shares.toString());
      if (initialData.price) setPrice(initialData.price.toString());
      if (initialData.fee) setFee(initialData.fee.toString());
      if (initialData.assetClass) setAssetClass(initialData.assetClass);
      if (initialData.exchangeRate) setExchangeRate(initialData.exchangeRate.toString());
      if (initialData.notes) setNotes(initialData.notes);

      if (initialData.shares && initialData.price && (initialData.type === TransactionType.BUY || initialData.type === TransactionType.SELL)) {
         setTotalAmount((initialData.shares * initialData.price).toFixed(2));
      } else if (initialData.price) {
          setTotalAmount(initialData.price.toString());
      }
    }
  }, [initialData]);

  // Auto-fill price from holdings or market data when symbol changes (and no data set yet)
  useEffect(() => {
    if (!initialData && symbol && !price && !totalAmount) {
       const h = holdings.find(h => h.symbol === symbol.toUpperCase());
       if (h) { setAssetClass(h.assetClass); if (h.currentPrice > 0) setPrice(h.currentPrice.toString()); }
       else { const kp = prices[symbol.toUpperCase()]; if (kp) setPrice(kp.toString()); }
    }
  }, [symbol]);

  // --- Real-time Calculation Handlers ---
  const handleSharesChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const val = e.target.value;
    setShares(val);
    const s = parseFloat(val);
    const p = parseFloat(price);
    if (!isNaN(s) && !isNaN(p)) {
        setTotalAmount((s * p).toFixed(2));
    }
  };

  const handlePriceChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const val = e.target.value;
    setPrice(val);
    const p = parseFloat(val);
    const s = parseFloat(shares);
    // If we have shares, calc total
    if (!isNaN(p) && !isNaN(s)) {
        setTotalAmount((s * p).toFixed(2));
    } 
    // If we have total but no shares, calc shares? (Inverse flow)
    else if (!isNaN(p) && totalAmount && !shares) {
        const t = parseFloat(totalAmount);
        if (!isNaN(t) && p !== 0) setShares((t/p).toFixed(4));
    }
  };

  const handleTotalChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const val = e.target.value;
    setTotalAmount(val);
    const t = parseFloat(val);
    const p = parseFloat(price);
    // Standard: Total / Price = Shares
    if (!isNaN(t) && !isNaN(p) && p !== 0) {
        setShares((t / p).toFixed(4));
    }
  };

  // --- Auto-complete Logic ---
  const allSymbols = useMemo(() => {
    const fromHoldings = holdings.map(h => h.symbol);
    const fromHistory = transactions.map(t => t.symbol).filter(s => s) as string[];
    // Unique combined list
    return Array.from(new Set([...fromHoldings, ...fromHistory, ...POPULAR_SYMBOLS])).sort();
  }, [holdings, transactions]);

  const suggestions = useMemo(() => {
    if (!symbol) return [];
    const inputUpper = symbol.toUpperCase();
    return allSymbols.filter(s => s.includes(inputUpper)).slice(0, 6);
  }, [symbol, allSymbols]);

  // Max Button Handlers
  const handleMax = () => {
    const p = parseFloat(price);
    if (type === TransactionType.BUY) {
        if (p > 0) {
            const maxAmt = Math.max(0, cashBalance);
            setTotalAmount(maxAmt.toFixed(2));
            setShares((maxAmt / p).toFixed(4));
        } else {
            setTotalAmount(cashBalance.toFixed(2));
        }
    } else if (type === TransactionType.SELL) {
        const holding = holdings.find(h => h.symbol === symbol.toUpperCase());
        if (holding) {
            setShares(holding.shares.toString());
            if (p > 0) setTotalAmount((holding.shares * p).toFixed(2));
        }
    }
  };

  // IMPACT CALCULATIONS FOR SUMMARY
  const currentCashImpact = useMemo(() => {
     const qty = parseFloat(shares) || 0;
     const unitPrice = parseFloat(price) || 0;
     const feeVal = parseFloat(fee) || 0;
     const amt = parseFloat(totalAmount) || 0;

     if (type === TransactionType.BUY) return -((qty * unitPrice) + feeVal);
     if (type === TransactionType.SELL) return ((qty * unitPrice) - feeVal);
     if (type === TransactionType.DEPOSIT) return amt;
     if (type === TransactionType.WITHDRAW) return -amt;
     if (type === TransactionType.DIVIDEND) return amt;
     return 0;
  }, [type, shares, price, fee, totalAmount]);

  const originalCashImpact = useMemo(() => {
    if (!initialData) return 0;
    const qty = initialData.shares || 0;
    const unitPrice = initialData.price || 0;
    const feeVal = initialData.fee || 0;

    if (initialData.type === TransactionType.BUY) return -((qty * unitPrice) + feeVal);
    if (initialData.type === TransactionType.SELL) return ((qty * unitPrice) - feeVal);
    if (initialData.type === TransactionType.DEPOSIT) return unitPrice; 
    if (initialData.type === TransactionType.WITHDRAW) return -unitPrice;
    if (initialData.type === TransactionType.DIVIDEND) return unitPrice;
    return 0;
  }, [initialData]);

  const projectedCashBalance = cashBalance - originalCashImpact + currentCashImpact;
  const totalNetWorth = useMemo(() => {
     const invested = holdings.reduce((sum, h) => sum + h.marketValue, 0);
     return invested + cashBalance;
  }, [holdings, cashBalance]);

  const feePercentage = useMemo(() => {
     const feeVal = parseFloat(fee) || 0;
     const totalVal = parseFloat(totalAmount) || 0;
     if (feeVal > 0 && totalVal > 0) {
        return (feeVal / totalVal) * 100;
     }
     return 0;
  }, [fee, totalAmount]);

  // Validation
  const validate = () => {
    if (needsSymbol && !symbol) return "Asset Symbol is required.";
    if (!needsSymbol && !totalAmount) return "Amount is required.";
    if (type === TransactionType.SELL) {
        const holding = holdings.find(h => h.symbol === symbol.toUpperCase());
        const currentShares = holding ? holding.shares : 0;
        const originalShares = (initialData && initialData.type === TransactionType.SELL && initialData.symbol === symbol) ? (initialData.shares || 0) : 0;
        const available = currentShares + originalShares;
        if ((parseFloat(shares) || 0) > available) return `Insufficient shares. Owned: ${formatNumber(available)}. Selling: ${shares}.`;
    }
    if ((type === TransactionType.WITHDRAW || type === TransactionType.BUY) && projectedCashBalance < 0) {
        return "Insufficient funds. Transaction exceeds cash balance.";
    }
    return null;
  };

  const handleReview = (e: React.FormEvent) => {
      e.preventDefault();
      const errMsg = validate();
      if (errMsg) return setError(errMsg);
      setError(null);
      setStep('review');
  };

  const handleFinalSubmit = async () => {
    setIsSaving(true);
    await onSave({
      id: initialData && initialData.id ? initialData.id : generateId(),
      date, type, symbol: needsSymbol ? symbol.toUpperCase() : undefined,
      shares: needsShares ? parseFloat(shares) : undefined,
      // For types that don't need shares (Deposit, Withdraw, Dividend), use the total amount as price
      price: type === TransactionType.SPLIT ? 0 : (needsShares ? parseFloat(price) : parseFloat(totalAmount)),
      fee: (fee && (type === TransactionType.BUY || type === TransactionType.SELL)) ? parseFloat(fee) : undefined,
      assetClass: !needsSymbol ? AssetClass.CASH : assetClass,
      exchangeRate: exchangeRate ? parseFloat(exchangeRate) : 1, notes: notes || undefined
    });
    setIsSaving(false);
  };

  const getTypeConfig = (t: TransactionType) => {
    switch (t) {
        case TransactionType.BUY: return { color: 'emerald', label: 'Buy Asset', icon: <TrendingUp size={18} /> }; // Green
        case TransactionType.DEPOSIT: return { color: 'blue', label: 'Deposit Cash', icon: <Wallet size={18} /> }; // Blue
        case TransactionType.SELL: return { color: 'rose', label: 'Sell Asset', icon: <TrendingDown size={18} /> }; // Red
        case TransactionType.WITHDRAW: return { color: 'orange', label: 'Withdraw', icon: <Banknote size={18} /> }; // Orange
        case TransactionType.DIVIDEND: return { color: 'teal', label: 'Dividend', icon: <Coins size={18} /> }; // Teal
        case TransactionType.SPLIT: return { color: 'purple', label: 'Stock Split', icon: <Split size={18} /> }; // Purple
        default: return { color: 'slate', label: t, icon: <CheckCircle2 size={18} /> };
    }
  }
  const theme = getTypeConfig(type);

  // SUMMARY BAR
  const summaryBox = useMemo(() => {
     const absImpact = Math.abs(currentCashImpact);
     const isPositiveFlow = currentCashImpact >= 0;
     const portfolioPercent = (totalNetWorth > 0) ? (absImpact / totalNetWorth) * 100 : 0;
     const impactColor = isPositiveFlow ? 'bg-emerald-500' : 'bg-rose-500';
     const impactTextColor = isPositiveFlow ? 'text-emerald-600' : 'text-rose-600';

     return (
         <div className="bg-slate-100 dark:bg-slate-800/80 rounded-2xl p-5 border border-slate-200 dark:border-slate-700 mt-4">
             <div className="flex justify-between items-start mb-4">
                 <div>
                    <p className="text-xs font-bold text-slate-500 uppercase tracking-wider">Net Cash Impact</p>
                    <h3 className={`text-2xl font-bold font-display ${impactTextColor}`}>
                        {isPositiveFlow ? '+' : '-'}{formatCurrency(absImpact)}
                    </h3>
                    <p className="text-[10px] text-slate-400 mt-1 font-medium flex items-center">
                        <Percent size={10} className="mr-1"/>
                        ≈ {portfolioPercent.toFixed(1)}% of Total Portfolio
                    </p>
                 </div>
                 <div className="text-right">
                    <p className="text-xs font-bold text-slate-500 uppercase tracking-wider">Projected Cash</p>
                    <p className="text-xl font-bold font-mono text-slate-800 dark:text-slate-200">{formatCurrency(projectedCashBalance)}</p>
                 </div>
             </div>

             {/* Progress Bar */}
             <div className="relative h-2.5 bg-slate-200 dark:bg-slate-700 rounded-full overflow-hidden">
                 <div className="absolute top-0 left-0 h-full bg-slate-400 dark:bg-slate-500 transition-all" style={{ width: '100%' }}></div>
                 {projectedCashBalance < cashBalance && (
                    <div className={`absolute top-0 right-0 h-full ${impactColor} transition-all animate-pulse`} style={{ width: `${((cashBalance - projectedCashBalance)/cashBalance)*100}%` }}></div>
                 )}
                 {projectedCashBalance > cashBalance && (
                     <div className={`absolute top-0 left-0 h-full ${impactColor} transition-all`} style={{ width: '100%' }}></div>
                 )}
             </div>
             <div className="flex justify-between text-[10px] text-slate-400 mt-1.5 font-bold uppercase">
                 <span>Before: {formatCurrency(cashBalance)}</span>
                 <span>After: {formatCurrency(projectedCashBalance)}</span>
             </div>
         </div>
     )
  }, [currentCashImpact, projectedCashBalance, cashBalance, totalNetWorth]);

  const handleNoteChange = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
     setNotes(e.target.value);
     e.target.style.height = 'auto';
     e.target.style.height = `${e.target.scrollHeight}px`;
  }

  // RENDER: REVIEW STEP
  if (step === 'review') {
      return (
          <div className="flex flex-col h-full bg-white dark:bg-slate-900">
             <div className="p-6 text-center border-b border-slate-100 dark:border-slate-800">
                <div className={`w-16 h-16 mx-auto rounded-full bg-${theme.color}-100 dark:bg-${theme.color}-900/30 text-${theme.color}-600 dark:text-${theme.color}-400 flex items-center justify-center mb-4 shadow-lg shadow-${theme.color}-500/20`}>
                   {theme.icon}
                </div>
                <h3 className="text-xl font-display font-bold text-slate-900 dark:text-white">Review Transaction</h3>
                <p className="text-sm text-slate-500">Please confirm details before saving.</p>
             </div>

             <div className="flex-1 overflow-y-auto p-6 space-y-6">
                 {/* Details Card */}
                 <div className="bg-slate-50 dark:bg-slate-800/50 rounded-2xl p-5 border border-slate-200 dark:border-slate-700 space-y-4">
                     <div className="flex justify-between border-b border-slate-200 dark:border-slate-700 pb-2">
                        <span className="text-sm text-slate-500">Date</span>
                        <span className="text-sm font-bold text-slate-900 dark:text-white">{date}</span>
                     </div>
                     <div className="flex justify-between border-b border-slate-200 dark:border-slate-700 pb-2">
                        <span className="text-sm text-slate-500">Type</span>
                        <span className={`text-sm font-bold uppercase text-${theme.color}-600`}>{theme.label}</span>
                     </div>
                     {needsSymbol && (
                         <div className="flex justify-between border-b border-slate-200 dark:border-slate-700 pb-2">
                            <span className="text-sm text-slate-500">Asset</span>
                            <span className="text-sm font-bold text-slate-900 dark:text-white">{symbol} <span className="text-xs text-slate-400 font-normal">({assetClass})</span></span>
                         </div>
                     )}
                     <div className="flex justify-between border-b border-slate-200 dark:border-slate-700 pb-2">
                        <span className="text-sm text-slate-500">Total Amount</span>
                        <span className="text-lg font-bold text-slate-900 dark:text-white">{formatCurrency(parseFloat(totalAmount))}</span>
                     </div>
                     {needsShares && (
                        <div className="flex justify-between pt-1">
                            <span className="text-xs text-slate-400">Details</span>
                            <span className="text-xs text-slate-500">{shares} units @ {formatCurrency(parseFloat(price))}</span>
                        </div>
                     )}
                 </div>

                 {projectedCashBalance < 0 && (
                     <div className="bg-rose-50 text-rose-600 p-4 rounded-xl text-sm font-bold flex items-center">
                         <AlertCircle size={20} className="mr-3 shrink-0" />
                         WARNING: This transaction will result in a negative cash balance.
                     </div>
                 )}
             </div>

             <div className="p-6 border-t border-slate-100 dark:border-slate-800 flex gap-4">
                 <button onClick={() => setStep('input')} className="flex-1 py-3 rounded-xl font-bold bg-slate-100 dark:bg-slate-800 text-slate-600 dark:text-slate-300 hover:bg-slate-200 dark:hover:bg-slate-700 transition-colors">
                    Back to Edit
                 </button>
                 <button onClick={handleFinalSubmit} disabled={isSaving} className={`flex-1 py-3 rounded-xl font-bold text-white shadow-xl flex items-center justify-center space-x-2 bg-${theme.color}-600 hover:bg-${theme.color}-700 transition-all`}>
                    {isSaving ? <Spinner className="text-white" /> : (
                        <>
                            <CheckCircle2 size={18} />
                            <span>Confirm & Save</span>
                        </>
                    )}
                 </button>
             </div>
          </div>
      )
  }

  // RENDER: INPUT STEP
  return (
    <>
      <div className="shrink-0 px-6 py-4 border-b border-slate-100 dark:border-slate-800 flex justify-between items-center bg-white dark:bg-slate-900">
          <h3 className="text-lg font-display font-bold text-slate-900 dark:text-white">{initialData?.id ? 'Edit Transaction' : 'New Transaction'}</h3>
          <button onClick={onClose} className="bg-slate-100 dark:bg-slate-800 p-2 rounded-full text-slate-500 hover:text-slate-800 dark:hover:text-white transition-colors"><X size={20} /></button>
      </div>

      <form onSubmit={handleReview} className="flex-1 overflow-y-auto min-h-0 p-6 custom-scrollbar bg-white dark:bg-slate-900">

        {/* 1. Transaction Type Selector (Large Cards) */}
        <div className="mb-8">
           <label className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-3 block">What would you like to do?</label>
           <div className="grid grid-cols-2 sm:grid-cols-3 gap-3">
              {[TransactionType.BUY, TransactionType.DEPOSIT, TransactionType.SELL, TransactionType.WITHDRAW, TransactionType.DIVIDEND, TransactionType.SPLIT].map(t => {
                 const isActive = type === t;
                 const config = getTypeConfig(t);
                 return (
                   <button
                      key={t} type="button" onClick={() => setType(t)}
                      className={`flex items-center gap-3 p-3 rounded-xl text-left transition-all border ${
                         isActive 
                         ? `border-${config.color}-500 bg-${config.color}-50 dark:bg-${config.color}-900/20 text-${config.color}-700 dark:text-${config.color}-400 ring-1 ring-${config.color}-500` 
                         : 'bg-white dark:bg-slate-800 border-slate-200 dark:border-slate-700 text-slate-500 dark:text-slate-400 hover:border-slate-300 dark:hover:border-slate-600'
                      }`}
                   >
                      <div className={`p-2 rounded-lg ${isActive ? `bg-${config.color}-200 dark:bg-${config.color}-900/50` : 'bg-slate-100 dark:bg-slate-700'}`}>
                        {config.icon}
                      </div>
                      <span className="text-xs sm:text-sm font-bold">{config.label}</span>
                   </button>
                 )
              })}
           </div>
        </div>

        {/* 2. Date Input (Full Width) */}
        <div className="mb-6">
            <label className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-2 block">When did this happen?</label>
            <div className="relative">
                <Calendar className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
                <input type="date" value={date} onChange={e => setDate(e.target.value)} className="w-full pl-12 pr-4 py-3 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl font-medium text-sm focus:ring-2 focus:ring-blue-500 outline-none transition-all cursor-pointer" />
            </div>
        </div>

        {/* 3. Dynamic Inputs Based on Type */}
        <div className="grid md:grid-cols-2 gap-8">

            {/* LEFT COLUMN: ASSET INFO */}
            {needsSymbol ? (
                <div className="space-y-5">
                    <div className="flex items-center space-x-2 text-slate-800 dark:text-slate-200 border-b border-slate-100 dark:border-slate-800 pb-2">
                        <FileText size={18} />
                        <h4 className="font-bold text-sm uppercase tracking-wide">Asset Details</h4>
                    </div>

                    <div className="relative z-20" ref={wrapperRef}>
                        <label className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-1.5 block">Asset Symbol</label>
                        <div className="relative group">
                            <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400 group-focus-within:text-blue-500 transition-colors" size={18} />
                            <input 
                               type="text" placeholder="e.g. AAPL, BTC" value={symbol} 
                               onChange={e => { setSymbol(e.target.value); setShowSuggestions(true); }}
                               onFocus={() => setShowSuggestions(true)}
                               className="w-full pl-10 pr-4 py-3 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl text-lg font-bold uppercase tracking-wide focus:ring-2 focus:ring-blue-500 focus:bg-white dark:focus:bg-slate-800 outline-none transition-all"
                            />
                             {showSuggestions && suggestions.length > 0 && (
                                <div className="absolute top-full left-0 right-0 mt-2 bg-white dark:bg-slate-800 rounded-xl shadow-xl border border-slate-100 dark:border-slate-700 overflow-hidden z-50 animate-fade-in max-h-60 overflow-y-auto custom-scrollbar">
                                    <div className="px-3 py-2 bg-slate-50 dark:bg-slate-900/50 text-[10px] uppercase font-bold text-slate-400">Suggestions</div>
                                    {suggestions.map(s => (
                                        <div key={s} onMouseDown={(e) => { e.preventDefault(); setSymbol(s); setShowSuggestions(false); }} className="px-4 py-3 hover:bg-blue-50 dark:hover:bg-blue-900/20 cursor-pointer font-bold text-slate-700 dark:text-slate-200 flex justify-between items-center text-sm border-b border-slate-50 dark:border-slate-700/50 last:border-0 group">
                                           <span>{s}</span>
                                           <span className="text-xs text-blue-500 font-normal opacity-0 group-hover:opacity-100 transition-opacity flex items-center">
                                              Use <ArrowRightCircle size={12} className="ml-1"/>
                                           </span>
                                        </div>
                                    ))}
                                </div>
                            )}
                        </div>
                    </div>

                    <div>
                        <label className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-1.5 block">Asset Class</label>
                        <select value={assetClass} onChange={e => setAssetClass(e.target.value as AssetClass)} className="w-full px-4 py-2.5 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl font-medium text-sm outline-none focus:ring-2 focus:ring-blue-500 transition-all cursor-pointer">
                            {Object.values(AssetClass).filter(a => a !== AssetClass.CASH).map(a => <option key={a} value={a}>{a}</option>)}
                        </select>
                    </div>
                </div>
            ) : (
                <div className="hidden md:block">
                    {/* Spacer for non-asset transactions to balance layout */}
                    <div className="h-full flex items-center justify-center text-slate-300 dark:text-slate-700">
                        <Wallet size={100} strokeWidth={1} />
                    </div>
                </div>
            )}

            {/* RIGHT COLUMN: FINANCIALS */}
            <div className="space-y-5">
                <div className="flex items-center space-x-2 text-slate-800 dark:text-slate-200 border-b border-slate-100 dark:border-slate-800 pb-2">
                    <DollarSign size={18} />
                    <h4 className="font-bold text-sm uppercase tracking-wide">Financials</h4>
                </div>

                {/* Amount / Price Fields */}
                {(needsPrice || isFunding) && (
                   <div>
                       <label className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-1.5 flex justify-between">
                           <span>{needsShares ? 'Total Amount' : 'Amount'}</span>
                           {type === TransactionType.BUY && (
                               <button type="button" onClick={handleMax} className="text-blue-500 hover:underline text-[10px] font-bold">Max Cash</button>
                           )}
                       </label>
                       <div className="relative group">
                           <span className={`absolute left-4 top-1/2 -translate-y-1/2 text-xl font-bold ${type === TransactionType.SELL || type === TransactionType.WITHDRAW ? 'text-rose-500' : 'text-emerald-500'}`}>$</span>
                           <input 
                              type="number" step="any" min="0" placeholder="0.00"
                              value={totalAmount}
                              onChange={handleTotalChange}
                              className="w-full pl-9 pr-4 py-3 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl text-2xl font-display font-bold text-slate-900 dark:text-white focus:ring-2 focus:ring-blue-500 focus:bg-white dark:focus:bg-slate-800 outline-none transition-all"
                           />
                       </div>
                   </div>
                 )}

                 <div className="grid grid-cols-2 gap-4">
                     {needsShares && (
                        <div>
                            <label className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-1.5 flex justify-between">
                                <span>Quantity</span>
                                {type === TransactionType.SELL && (
                                   <button type="button" onClick={handleMax} className="text-rose-500 hover:underline text-[10px] font-bold">All</button>
                                )}
                            </label>
                            <input 
                                type="number" step="any" 
                                placeholder="0" 
                                value={shares}
                                onChange={handleSharesChange}
                                className="w-full px-4 py-3 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl font-medium text-sm focus:ring-2 focus:ring-blue-500 outline-none"
                            />
                        </div>
                     )}

                     {needsPrice && needsShares && (
                        <div>
                           <label className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-1.5 block">Price / Share</label>
                           <input 
                                type="number" step="any" placeholder="0.00" value={price}
                                onChange={handlePriceChange}
                                className="w-full px-4 py-3 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl font-medium text-sm focus:ring-2 focus:ring-blue-500 outline-none"
                            />
                        </div>
                     )}
                 </div>

                 {(type === TransactionType.BUY || type === TransactionType.SELL) && (
                    <div>
                        <label className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-1.5 block">Transaction Fee</label>
                        <input 
                             type="number" step="any" placeholder="0.00" value={fee} onChange={e => setFee(e.target.value)} 
                             className="w-full px-4 py-2 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl text-sm outline-none focus:ring-2 focus:ring-blue-500" 
                        />
                        {feePercentage > 0 && (
                           <div className="text-[10px] text-slate-400 mt-1 flex items-center">
                              <Info size={10} className="mr-1" />
                              ≈ {feePercentage.toFixed(2)}% of total amount
                           </div>
                        )}
                    </div>
                 )}

                 {hasExchangeRate && (
                    <div>
                       <label className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-1 block">Exchange Rate (Optional)</label>
                       <input 
                         type="number" step="any" min="0" placeholder="1.0" 
                         value={exchangeRate} onChange={e => setExchangeRate(e.target.value)} 
                         className="w-full px-4 py-2 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl font-medium text-sm outline-none focus:ring-2 focus:ring-blue-500" 
                       />
                    </div>
                 )}
            </div>
        </div>

        {/* SUMMARY SECTION */}
        {summaryBox}

        {/* Notes Collapsible */}
        <details className="group mt-4" open={!!notes}>
            <summary className="flex items-center text-xs font-bold text-slate-400 uppercase tracking-wider cursor-pointer hover:text-blue-500 transition-colors w-fit">
               <span className="mr-2">Add Notes</span>
               <ChevronDown size={14} className="group-open:rotate-180 transition-transform" />
            </summary>
            <div className="mt-2 animate-slide-up">
                 <textarea 
                   ref={notesRef}
                   rows={2} 
                   placeholder="E.g. Monthly DCA, Rebalancing..." 
                   value={notes} 
                   onChange={handleNoteChange} 
                   className="w-full px-4 py-2 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl text-sm outline-none resize-none transition-all focus:border-blue-400 overflow-hidden min-h-[50px]" 
                 />
            </div>
        </details>

      </form>

      {/* 6. FOOTER ACTIONS */}
      <div className="px-6 py-4 border-t border-slate-100 dark:border-slate-800 bg-white dark:bg-slate-900 z-10 flex gap-3">
             {error && (
                <div className="absolute bottom-full left-0 w-full px-6 pb-2">
                    <div className="bg-rose-50 text-rose-600 px-4 py-2 rounded-xl text-sm font-bold flex items-center animate-slide-up shadow-sm border border-rose-100">
                        <AlertCircle size={16} className="mr-2" /> {error}
                    </div>
                </div>
             )}

             {initialData?.id && onDelete && (
                 <button type="button" onClick={() => onDelete(initialData!.id)} className="p-3 rounded-xl bg-rose-50 text-rose-500 hover:bg-rose-100 dark:bg-rose-900/10 dark:hover:bg-rose-900/20 transition-colors"><Trash2 size={20} /></button>
             )}
             <button 
                onClick={handleReview}
                title="Double check your details before saving"
                className={`flex-1 py-3 rounded-xl font-bold text-base text-white shadow-xl transition-all active:scale-95 flex items-center justify-center space-x-2 bg-${theme.color}-600 hover:bg-${theme.color}-700 shadow-${theme.color}-500/30`}
             >
                <span>Review & Save</span>
                <ArrowRight size={18} />
             </button>
      </div>
    </>
  );
};

export default App;

import React, { useMemo, useState } from 'react';
import { Holding, Transaction, ChartDataPoint, TransactionType } from '../types';
import { formatCurrency, formatNumber } from '../utils';
import { 
  AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, 
  PieChart, Pie, Cell
} from 'recharts';
import { 
  ArrowUpRight, ArrowDownRight, TrendingUp, TrendingDown, 
  Wallet, Target, Activity, ChevronLeft, PieChart as PieChartIcon, 
  Clock, DollarSign, Zap, Star, Plus, Coins, ArrowRight
} from 'lucide-react';
import { DashboardSkeleton } from './LoadingSkeletons';

interface DashboardProps {
  holdings: Holding[];
  transactions: Transaction[];
  financialGoal: number;
  setFinancialGoal?: (val: number) => void;
  onOpenGoalModal: () => void;
  investedAmount: number;
  cashBalance: number;
  portfolioValue: number;
  chartData: ChartDataPoint[];
  isLoading?: boolean;
  // New props for quick actions (Used in Empty State)
  onQuickAction: (type: TransactionType) => void;
}

const COLORS = ['#3b82f6', '#10b981', '#f59e0b', '#ef4444', '#8b5cf6', '#ec4899', '#6366f1', '#14b8a6'];

const CustomTooltip = ({ active, payload, label }: any) => {
  if (active && payload && payload.length) {
    return (
      <div className="bg-white/95 dark:bg-slate-900/95 backdrop-blur-md border border-slate-200 dark:border-slate-700 p-4 rounded-xl shadow-xl transition-colors duration-200">
        {label && <p className="text-xs font-bold text-slate-500 dark:text-slate-400 uppercase tracking-wider mb-2">{label}</p>}
        <div className="space-y-1.5">
          {payload.map((entry: any, index: number) => (
            <div key={index} className="flex items-center justify-between gap-6 text-sm">
              <div className="flex items-center">
                 <div className="w-2.5 h-2.5 rounded-full mr-2 shadow-sm" style={{ backgroundColor: entry.color }}></div>
                 <span className="text-slate-600 dark:text-slate-300 font-medium capitalize">
                    {entry.name === 'value' ? 'Market Value' : entry.name === 'invested' ? 'Net Invested' : entry.name}
                 </span>
              </div>
              <span className="font-bold text-slate-900 dark:text-white font-mono tabular-nums">
                {formatCurrency(entry.value)}
              </span>
            </div>
          ))}
        </div>
      </div>
    );
  }
  return null;
};

const Dashboard: React.FC<DashboardProps> = ({ 
  holdings, transactions, financialGoal, onOpenGoalModal, investedAmount, portfolioValue, cashBalance, chartData, isLoading, onQuickAction
}) => {
  const [selectedCategory, setSelectedCategory] = useState<string | null>(null);

  const totalNetWorth = portfolioValue + cashBalance;
  const totalUnrealizedPL = holdings.reduce((sum, h) => sum + h.unrealizedPL, 0);
  const totalPLPercent = investedAmount > 0 ? (totalUnrealizedPL / investedAmount) * 100 : 0;

  // --- DERIVED DATA ---

  // 1. Allocation Data
  const categoryData = useMemo(() => {
    const data = holdings
      .filter(h => h.marketValue > 0)
      .map(h => ({ name: h.assetClass, value: h.marketValue }))
      .reduce((acc: any[], curr) => {
        const existing = acc.find(item => item.name === curr.name);
        if (existing) existing.value += curr.value;
        else acc.push({ ...curr });
        return acc;
      }, []);

    if (cashBalance > 0) {
       const cashCategory = data.find(item => item.name === 'Cash');
       if (cashCategory) cashCategory.value += cashBalance;
       else data.push({ name: 'Cash', value: cashBalance });
    }
    return data.sort((a, b) => b.value - a.value);
  }, [holdings, cashBalance]);

  const assetData = useMemo(() => {
    if (!selectedCategory) return [];
    const assets = holdings
      .filter(h => h.assetClass === selectedCategory && h.marketValue > 0)
      .map(h => ({ name: h.symbol, value: h.marketValue, fullName: h.name }));

    if (selectedCategory === 'Cash' && cashBalance > 0) {
        assets.push({ name: 'Wallet', value: cashBalance, fullName: 'Available Balance' });
    }
    return assets.sort((a, b) => b.value - a.value);
  }, [holdings, selectedCategory, cashBalance]);

  const activeChartData = selectedCategory ? assetData : categoryData;
  const activeTotalValue = activeChartData.reduce((sum, item) => sum + item.value, 0);

  // 2. Top Movers (Best performing assets by %)
  const topMovers = useMemo(() => {
     return [...holdings]
        .filter(h => h.marketValue > 0) // Only active
        .sort((a, b) => b.unrealizedPLPercent - a.unrealizedPLPercent)
        .slice(0, 3);
  }, [holdings]);

  // 3. Recent Transactions
  const recentTransactions = useMemo(() => {
     return [...transactions]
        .sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime())
        .slice(0, 4);
  }, [transactions]);

  if (isLoading) return <DashboardSkeleton />;

  // --- EMPTY STATE (Welcome Guide) ---
  if (transactions.length === 0) {
      return (
          <div className="space-y-8 animate-fade-in py-8">
              <div className="text-center space-y-4 max-w-2xl mx-auto">
                  <h2 className="text-4xl font-display font-bold text-slate-900 dark:text-white">Welcome to your Portfolio!</h2>
                  <p className="text-lg text-slate-500 dark:text-slate-400">
                      Track your investments, analyze performance, and reach your financial goals. Let's get you set up.
                  </p>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-3 gap-6 max-w-4xl mx-auto mt-12">
                  <div 
                    onClick={() => onQuickAction(TransactionType.DEPOSIT)}
                    className="group bg-white dark:bg-slate-800 p-8 rounded-3xl border border-slate-200 dark:border-slate-700 shadow-sm hover:shadow-xl hover:-translate-y-1 transition-all cursor-pointer flex flex-col items-center text-center"
                  >
                      <div className="w-16 h-16 bg-blue-100 dark:bg-blue-900/30 rounded-2xl flex items-center justify-center text-blue-600 dark:text-blue-400 mb-6 group-hover:scale-110 transition-transform">
                          <Wallet size={32} />
                      </div>
                      <h3 className="text-xl font-bold text-slate-900 dark:text-white mb-2">1. Add Cash</h3>
                      <p className="text-sm text-slate-500 mb-6">Record your initial deposit to start tracking your available capital.</p>
                      <span className="text-blue-600 font-bold text-sm flex items-center">Start Now <ArrowRight size={16} className="ml-1"/></span>
                  </div>

                  <div 
                    onClick={() => onQuickAction(TransactionType.BUY)}
                    className="group bg-white dark:bg-slate-800 p-8 rounded-3xl border border-slate-200 dark:border-slate-700 shadow-sm hover:shadow-xl hover:-translate-y-1 transition-all cursor-pointer flex flex-col items-center text-center"
                  >
                      <div className="w-16 h-16 bg-emerald-100 dark:bg-emerald-900/30 rounded-2xl flex items-center justify-center text-emerald-600 dark:text-emerald-400 mb-6 group-hover:scale-110 transition-transform">
                          <TrendingUp size={32} />
                      </div>
                      <h3 className="text-xl font-bold text-slate-900 dark:text-white mb-2">2. Buy Assets</h3>
                      <p className="text-sm text-slate-500 mb-6">Log your stocks, crypto, or ETFs purchases to see your portfolio grow.</p>
                      <span className="text-emerald-600 font-bold text-sm flex items-center">Start Now <ArrowRight size={16} className="ml-1"/></span>
                  </div>

                  <div 
                    onClick={onOpenGoalModal}
                    className="group bg-white dark:bg-slate-800 p-8 rounded-3xl border border-slate-200 dark:border-slate-700 shadow-sm hover:shadow-xl hover:-translate-y-1 transition-all cursor-pointer flex flex-col items-center text-center"
                  >
                      <div className="w-16 h-16 bg-purple-100 dark:bg-purple-900/30 rounded-2xl flex items-center justify-center text-purple-600 dark:text-purple-400 mb-6 group-hover:scale-110 transition-transform">
                          <Target size={32} />
                      </div>
                      <h3 className="text-xl font-bold text-slate-900 dark:text-white mb-2">3. Set a Goal</h3>
                      <p className="text-sm text-slate-500 mb-6">Define your financial target to keep yourself motivated.</p>
                      <span className="text-purple-600 font-bold text-sm flex items-center">Start Now <ArrowRight size={16} className="ml-1"/></span>
                  </div>
              </div>
          </div>
      );
  }

  return (
    <div className="space-y-6 animate-fade-in pb-12">

      {/* --- ROW 1: PRIMARY METRICS --- */}
      <div className="grid grid-cols-1 md:grid-cols-12 gap-6">

        {/* Total Net Worth Card (Simple & Bold) */}
        <div className="md:col-span-7 relative overflow-hidden rounded-3xl p-8 bg-slate-900 text-white shadow-2xl shadow-slate-900/20 flex flex-col justify-center min-h-[220px]">
          <div className="absolute inset-0 bg-gradient-to-br from-indigo-900 to-slate-950"></div>
          {/* Abstract blobs */}
          <div className="absolute -top-24 -right-24 w-64 h-64 bg-indigo-500/20 rounded-full blur-[80px]"></div>
          <div className="absolute -bottom-24 -left-24 w-64 h-64 bg-blue-500/20 rounded-full blur-[80px]"></div>

          <div className="relative z-10">
             <div className="flex items-center gap-2 mb-3">
                <div className="p-1.5 bg-white/10 rounded-lg backdrop-blur-md">
                    <Wallet size={18} className="text-indigo-200" />
                </div>
                <p className="text-indigo-200 font-bold text-sm uppercase tracking-wider">Total Net Worth</p>
             </div>
             <h2 className="text-5xl sm:text-6xl font-display font-bold tracking-tight text-white mb-6">
               {formatCurrency(totalNetWorth)}
             </h2>

             <div className="flex gap-6">
                 <div className="bg-white/10 backdrop-blur-md px-4 py-2.5 rounded-xl border border-white/5">
                     <p className="text-[10px] text-indigo-200 font-bold uppercase tracking-wider mb-0.5">Cash</p>
                     <p className="text-lg font-bold font-mono">{formatCurrency(cashBalance)}</p>
                 </div>
                 <div className="bg-white/10 backdrop-blur-md px-4 py-2.5 rounded-xl border border-white/5">
                     <p className="text-[10px] text-indigo-200 font-bold uppercase tracking-wider mb-0.5">Invested</p>
                     <p className="text-lg font-bold font-mono">{formatCurrency(portfolioValue)}</p>
                 </div>
             </div>
          </div>
        </div>

        {/* Right Column: P/L & Goal */}
        <div className="md:col-span-5 flex flex-col gap-6">

            {/* P/L Card */}
            <div className={`flex-1 rounded-3xl p-6 border shadow-sm flex flex-col justify-center relative overflow-hidden ${
                totalUnrealizedPL >= 0 
                ? 'bg-emerald-50 border-emerald-100 dark:bg-emerald-900/10 dark:border-emerald-900/30' 
                : 'bg-rose-50 border-rose-100 dark:bg-rose-900/10 dark:border-rose-900/30'
            }`}>
                 <div className="relative z-10">
                    <div className="flex items-center gap-2 mb-2">
                        {totalUnrealizedPL >= 0 ? <TrendingUp size={18} className="text-emerald-600" /> : <TrendingDown size={18} className="text-rose-600" />}
                        <p className={`text-xs font-bold uppercase tracking-wider ${totalUnrealizedPL >= 0 ? 'text-emerald-600 dark:text-emerald-400' : 'text-rose-600 dark:text-rose-400'}`}>Total Profit / Loss</p>
                    </div>
                    <h3 className={`text-3xl font-bold font-display ${totalUnrealizedPL >= 0 ? 'text-emerald-700 dark:text-emerald-400' : 'text-rose-700 dark:text-rose-400'}`}>
                        {totalUnrealizedPL >= 0 ? '+' : ''}{formatCurrency(totalUnrealizedPL)}
                    </h3>
                    <div className={`mt-3 inline-flex items-center px-3 py-1.5 rounded-xl text-xs font-bold w-fit bg-white/60 dark:bg-black/20 backdrop-blur-sm ${totalPLPercent >= 0 ? 'text-emerald-700 dark:text-emerald-400' : 'text-rose-700 dark:text-rose-400'}`}>
                        {totalPLPercent >= 0 ? <ArrowUpRight size={14} className="mr-1"/> : <ArrowDownRight size={14} className="mr-1"/>}
                        {Math.abs(totalPLPercent).toFixed(2)}% Return
                    </div>
                 </div>
            </div>

            {/* Goal Progress */}
            <div className="bg-white dark:bg-slate-800 rounded-3xl p-5 border border-slate-200 dark:border-slate-700 flex items-center gap-4 cursor-pointer hover:border-indigo-300 transition-colors shadow-sm" onClick={onOpenGoalModal}>
                <div className="w-12 h-12 rounded-2xl bg-indigo-100 dark:bg-indigo-900/30 flex items-center justify-center text-indigo-600 dark:text-indigo-400 shrink-0">
                   <Target size={24} />
                </div>
                <div className="flex-1">
                    <div className="flex justify-between items-center mb-1.5">
                        <p className="text-xs font-bold text-slate-500 dark:text-slate-400 uppercase">Goal Progress</p>
                        <p className="text-xs font-bold text-indigo-600 dark:text-indigo-400">{((totalNetWorth / financialGoal) * 100).toFixed(0)}%</p>
                    </div>
                    <div className="w-full bg-slate-100 dark:bg-slate-700 h-2.5 rounded-full overflow-hidden">
                        <div className="bg-indigo-500 h-full rounded-full transition-all duration-1000" style={{ width: `${Math.min((totalNetWorth / financialGoal) * 100, 100)}%` }}></div>
                    </div>
                </div>
            </div>
        </div>
      </div>

      {/* --- ROW 2: CHARTS & MOVERS --- */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">

        {/* Wealth Chart (Span 2) */}
        <div className="lg:col-span-2 bg-white dark:bg-slate-800 rounded-3xl p-6 md:p-8 border border-slate-200 dark:border-slate-700 shadow-sm">
           <div className="flex items-center justify-between mb-8">
             <div>
                <h3 className="text-lg font-bold text-slate-900 dark:text-white">Growth History</h3>
                <p className="text-xs text-slate-500 mt-1">Value over time vs Invested capital</p>
             </div>
             <div className="hidden sm:flex items-center space-x-4 text-xs font-bold">
                  <div className="flex items-center text-blue-500"><div className="w-2 h-2 bg-blue-500 rounded-full mr-2"></div> Market Value</div>
                  <div className="flex items-center text-slate-400"><div className="w-2 h-2 bg-slate-300 rounded-full mr-2"></div> Cost Basis</div>
              </div>
           </div>

           <div className="h-[280px] w-full">
            {chartData.length > 0 ? (
              <ResponsiveContainer width="100%" height="100%">
              <AreaChart data={chartData} margin={{ top: 10, right: 10, left: 0, bottom: 0 }}>
                <defs>
                  <linearGradient id="colorValue" x1="0" y1="0" x2="0" y2="1">
                    <stop offset="5%" stopColor="#3b82f6" stopOpacity={0.2}/>
                    <stop offset="95%" stopColor="#3b82f6" stopOpacity={0}/>
                  </linearGradient>
                </defs>
                <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" opacity={0.4} vertical={false} />
                <XAxis 
                  dataKey="date" 
                  axisLine={false} tickLine={false} tick={{fill: '#94a3b8', fontSize: 11}} dy={15} minTickGap={40} 
                />
                <YAxis 
                  axisLine={false} tickLine={false} tick={{fill: '#94a3b8', fontSize: 11}} 
                  tickFormatter={(val) => val >= 1000 ? (val/1000).toFixed(0) + 'k' : val}
                />
                <Tooltip content={<CustomTooltip />} />
                <Area type="monotone" dataKey="value" stroke="#3b82f6" strokeWidth={3} fillOpacity={1} fill="url(#colorValue)" />
                <Area type="monotone" dataKey="invested" stroke="#cbd5e1" strokeDasharray="4 4" strokeWidth={2} fill="transparent" />
              </AreaChart>
            </ResponsiveContainer>
            ) : (
              <div className="flex h-full flex-col items-center justify-center text-slate-400 bg-slate-50 dark:bg-slate-900/50 rounded-2xl border-2 border-dashed border-slate-200 dark:border-slate-700">
                <Activity className="mb-2 opacity-50" size={32} />
                <p>No data to display yet.</p>
              </div>
            )}
          </div>
        </div>

        {/* Top Movers (Span 1) */}
        <div className="bg-white dark:bg-slate-800 rounded-3xl p-6 border border-slate-200 dark:border-slate-700 shadow-sm flex flex-col">
           <div className="flex items-center justify-between mb-4">
              <h3 className="font-bold text-slate-900 dark:text-white flex items-center">
                 <Star size={18} className="text-amber-400 mr-2 fill-amber-400" /> Top Performers
              </h3>
           </div>

           <div className="flex-1 space-y-3">
              {topMovers.length > 0 ? (
                 topMovers.map((h, i) => (
                    <div key={h.symbol} className="flex items-center justify-between p-3 rounded-2xl bg-slate-50 dark:bg-slate-900/50 hover:bg-slate-100 dark:hover:bg-slate-900 transition-colors">
                       <div className="flex items-center space-x-3">
                          <div className={`w-10 h-10 rounded-xl flex items-center justify-center text-xs font-bold text-slate-700 dark:text-slate-200 bg-white dark:bg-slate-800 shadow-sm border border-slate-100 dark:border-slate-700`}>
                             {h.symbol.substring(0,2)}
                          </div>
                          <div>
                             <div className="font-bold text-sm text-slate-900 dark:text-white">{h.symbol}</div>
                             <div className="text-[10px] text-slate-500 uppercase font-bold">{h.assetClass}</div>
                          </div>
                       </div>
                       <div className="text-right">
                          <div className="text-xs font-bold text-emerald-600 dark:text-emerald-400 flex items-center justify-end">
                             <ArrowUpRight size={12} className="mr-0.5" />
                             {h.unrealizedPLPercent.toFixed(2)}%
                          </div>
                          <div className="text-[10px] text-slate-400 font-mono">
                             {formatCurrency(h.marketValue)}
                          </div>
                       </div>
                    </div>
                 ))
              ) : (
                 <div className="h-full flex flex-col items-center justify-center text-slate-400 text-sm italic opacity-70">
                    <Star size={32} className="mb-2 opacity-50" />
                    <span>No active positions</span>
                 </div>
              )}
           </div>
        </div>
      </div>

      {/* --- ROW 3: ALLOCATION & RECENT ACTIVITY --- */}
      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">

        {/* Allocation Donut */}
        <div className="bg-white dark:bg-slate-800 rounded-3xl p-6 md:p-8 border border-slate-200 dark:border-slate-700 shadow-sm flex flex-col relative h-[340px]">
           <div className="flex items-center justify-between mb-2">
               <div>
                  <h3 className="font-bold text-slate-900 dark:text-white flex items-center">
                    <PieChartIcon size={18} className="mr-2 text-slate-400" /> Allocation
                  </h3>
                  <p className="text-xs text-slate-500 mt-0.5">{selectedCategory || 'By Asset Class'}</p>
               </div>
               {selectedCategory && (
                  <button onClick={() => setSelectedCategory(null)} className="p-1.5 bg-slate-100 dark:bg-slate-700 rounded-full text-slate-500 hover:text-slate-900 transition-colors">
                     <ChevronLeft size={16} />
                  </button>
               )}
           </div>

           <div className="flex items-center h-full">
              {/* Chart Side */}
              <div className="flex-1 h-[200px] relative">
                  {activeChartData.length > 0 ? (
                     <ResponsiveContainer width="100%" height="100%">
                      <PieChart>
                        <Pie
                          data={activeChartData}
                          cx="50%"
                          cy="50%"
                          innerRadius={55}
                          outerRadius={75}
                          paddingAngle={5}
                          dataKey="value"
                          cornerRadius={5}
                          onClick={(data) => {
                             const clickedName = data.name || data.payload?.name;
                             if (!selectedCategory && clickedName && clickedName !== 'Wallet') {
                                setSelectedCategory(clickedName);
                             }
                          }}
                          className={!selectedCategory ? 'cursor-pointer' : ''}
                        >
                          {activeChartData.map((entry, index) => (
                            <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} strokeWidth={0} />
                          ))}
                        </Pie>
                        <Tooltip content={<CustomTooltip />} />
                      </PieChart>
                    </ResponsiveContainer>
                  ) : (
                     <div className="text-slate-300 flex flex-col items-center justify-center h-full">
                        <PieChartIcon size={40} className="mb-2" />
                        <span className="text-sm">No assets</span>
                     </div>
                  )}
                  {/* Center Text */}
                  {activeChartData.length > 0 && (
                     <div className="absolute inset-0 flex flex-col items-center justify-center pointer-events-none">
                        <span className="text-[10px] text-slate-400 font-bold uppercase tracking-wider">Total</span>
                        <span className="text-sm font-bold text-slate-900 dark:text-white">{formatCurrency(activeTotalValue).split('.')[0]}</span>
                     </div>
                  )}
              </div>

              {/* Legend Side */}
              <div className="w-40 pl-4 h-[200px] overflow-y-auto custom-scrollbar space-y-2">
                 {activeChartData.map((entry, idx) => (
                    <div key={idx} className="flex items-center justify-between text-xs cursor-pointer group hover:bg-slate-50 dark:hover:bg-slate-700/50 p-1 rounded-lg" onClick={() => !selectedCategory && setSelectedCategory(entry.name)}>
                       <div className="flex items-center">
                          <div className="w-2.5 h-2.5 rounded-full mr-2" style={{ backgroundColor: COLORS[idx % COLORS.length] }}></div>
                          <span className="text-slate-600 dark:text-slate-300 font-medium truncate max-w-[70px]">{entry.name}</span>
                       </div>
                       <div className="font-bold text-slate-900 dark:text-white">
                          {((entry.value / activeTotalValue) * 100).toFixed(0)}%
                       </div>
                    </div>
                 ))}
              </div>
           </div>
        </div>

        {/* Recent Activity Feed */}
        <div className="bg-white dark:bg-slate-800 rounded-3xl p-6 md:p-8 border border-slate-200 dark:border-slate-700 shadow-sm flex flex-col h-[340px]">
           <div className="flex items-center justify-between mb-4">
              <h3 className="font-bold text-slate-900 dark:text-white flex items-center">
                 <Clock size={18} className="mr-2 text-slate-400" /> Recent Activity
              </h3>
           </div>

           <div className="flex-1 overflow-y-auto custom-scrollbar pr-2 space-y-3">
              {recentTransactions.length > 0 ? (
                 recentTransactions.map((tx) => (
                   <div key={tx.id} className="flex items-center justify-between p-3 rounded-2xl bg-slate-50 dark:bg-slate-900/50">
                      <div className="flex items-center space-x-3">
                          <div className={`w-9 h-9 rounded-xl flex items-center justify-center text-xs font-bold ${
                             tx.type === 'BUY' ? 'bg-blue-100 text-blue-600 dark:bg-blue-900/30 dark:text-blue-400' :
                             tx.type === 'SELL' ? 'bg-rose-100 text-rose-600 dark:bg-rose-900/30 dark:text-rose-400' :
                             tx.type === 'DIVIDEND' ? 'bg-emerald-100 text-emerald-600 dark:bg-emerald-900/30 dark:text-emerald-400' :
                             'bg-slate-200 text-slate-600 dark:bg-slate-700 dark:text-slate-300'
                          }`}>
                              {tx.type === 'BUY' ? <TrendingUp size={16} /> : 
                               tx.type === 'SELL' ? <TrendingDown size={16} /> :
                               tx.type === 'DIVIDEND' ? <Coins size={16} /> : 
                               tx.type === 'DEPOSIT' ? <Plus size={16} /> : <ArrowRight size={16} />}
                          </div>
                          <div>
                             <div className="font-bold text-sm text-slate-900 dark:text-white">{tx.symbol || tx.type}</div>
                             <div className="text-[10px] text-slate-400">{new Date(tx.date).toLocaleDateString()}</div>
                          </div>
                      </div>
                      <div className="text-right">
                         <div className={`text-sm font-bold font-mono ${
                            (tx.type === 'SELL' || tx.type === 'DIVIDEND' || tx.type === 'DEPOSIT') ? 'text-emerald-600 dark:text-emerald-400' : 'text-slate-900 dark:text-white'
                         }`}>
                             {(tx.type === 'SELL' || tx.type === 'DIVIDEND' || tx.type === 'DEPOSIT') ? '+' : ''}
                             {formatCurrency((tx.price || 0) * (tx.shares || 1))}
                         </div>
                         {tx.type === 'BUY' && tx.shares && <div className="text-[10px] text-slate-400">{formatNumber(tx.shares)} units</div>}
                      </div>
                   </div>
                 ))
              ) : (
                 <div className="h-full flex flex-col items-center justify-center text-slate-400 text-sm italic opacity-70">
                    <Clock size={32} className="mb-2 opacity-50" />
                    <span>No transactions yet</span>
                 </div>
              )}
           </div>
        </div>

      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState, useMemo } from 'react';
import { Holding, Transaction, AssetClass, TransactionType } from '../types';
import { formatCurrency, formatNumber } from '../utils';
import { RefreshCw, Briefcase, Layers, Eye, EyeOff, Target, LayoutGrid, LayoutList, TrendingUp, TrendingDown, MoreHorizontal, ArrowUpDown, ArrowUp, ArrowDown, Wallet, DollarSign, Plus, Minus, Edit2, Lightbulb, AlertTriangle, PieChart as PieChartIcon, ArrowRightLeft, Scale, CheckCircle2 } from 'lucide-react';
import { AreaChart, Area, ResponsiveContainer, YAxis, XAxis, Tooltip, ReferenceLine, PieChart, Pie, Cell, Legend } from 'recharts';
import { HoldingsSkeleton } from './LoadingSkeletons';

interface HoldingsProps {
  holdings: Holding[];
  transactions: Transaction[];
  cashBalance: number;
  onUpdatePrice: (symbol: string, newPrice: number) => void;
  onUpdateTarget: (symbol: string, target: number) => void;
  onTrade: (symbol: string, type: TransactionType) => void;
  isLoading?: boolean;
}

type SortField = 'marketValue' | 'unrealizedPL' | 'unrealizedPLPercent' | 'symbol' | 'totalCost' | 'shares' | 'weight';
type SortDirection = 'asc' | 'desc';

const COLORS = ['#3b82f6', '#10b981', '#f59e0b', '#ef4444', '#8b5cf6', '#ec4899', '#6366f1', '#14b8a6'];

const Holdings: React.FC<HoldingsProps> = ({ holdings, transactions, cashBalance, onUpdatePrice, onUpdateTarget, onTrade, isLoading }) => {
  const [viewMode, setViewMode] = useState<'card' | 'table'>('card');
  const [groupByCategory, setGroupByCategory] = useState(false);
  const [hideClosed, setHideClosed] = useState(true);

  // Chart State
  const [allocationMetric, setAllocationMetric] = useState<'assetClass' | 'symbol'>('assetClass');

  // Sorting State
  const [sortField, setSortField] = useState<SortField>('marketValue');
  const [sortDirection, setSortDirection] = useState<SortDirection>('desc');

  // Price Editing State
  const [editingPrice, setEditingPrice] = useState<string | null>(null);
  const [tempPrice, setTempPrice] = useState<string>('');

  // Target Editing State
  const [editingTarget, setEditingTarget] = useState<string | null>(null);
  const [tempTarget, setTempTarget] = useState<string>('');

  // --- HANDLERS ---
  const handleSort = (field: SortField) => {
     if (sortField === field) {
        setSortDirection(sortDirection === 'asc' ? 'desc' : 'asc');
     } else {
        setSortField(field);
        setSortDirection('desc'); // Default to desc for most metrics
     }
  };

  const handleEditPriceClick = (symbol: string, currentPrice: number, e: React.MouseEvent) => {
    e.stopPropagation();
    setEditingPrice(symbol);
    setTempPrice(currentPrice.toString());
  };

  const handleSavePrice = (symbol: string) => {
    const price = parseFloat(tempPrice);
    if (!isNaN(price) && price >= 0) {
      onUpdatePrice(symbol, price);
    }
    setEditingPrice(null);
  };

  const handleEditTargetClick = (symbol: string, currentTarget: number, e: React.MouseEvent) => {
    e.stopPropagation();
    setEditingTarget(symbol);
    setTempTarget(currentTarget.toString());
  };

  const handleSaveTarget = (symbol: string) => {
    const target = parseFloat(tempTarget);
    if (!isNaN(target) && target >= 0 && target <= 100) {
      onUpdateTarget(symbol, target);
    }
    setEditingTarget(null);
  };

  // --- DATA PROCESSING ---

  const { totalMarketValue, totalUnrealizedPL, totalCost } = useMemo(() => {
    const mv = holdings.reduce((sum, h) => sum + h.marketValue, 0);
    const cost = holdings.reduce((sum, h) => sum + h.totalCost, 0);
    const pl = mv - cost;
    return { totalMarketValue: mv, totalCost: cost, totalUnrealizedPL: pl };
  }, [holdings]);

  const netWorth = totalMarketValue + cashBalance;

  // Enhanced Allocation Analysis (Chart & Rebalancing)
  const allocationAnalysis = useMemo(() => {
    // Calculate implied cash target (100% - sum of all asset targets)
    const totalDefinedTarget = holdings.reduce((sum, h) => sum + (h.targetAllocation || 0), 0);
    const impliedCashTarget = Math.max(0, 100 - totalDefinedTarget);

    let data: any[] = [];

    if (allocationMetric === 'assetClass') {
        const groups: Record<string, { value: number, target: number }> = {};

        // Initialize groups
        Object.values(AssetClass).forEach(ac => {
            if (ac !== AssetClass.CASH) groups[ac] = { value: 0, target: 0 };
        });

        // Fill Data
        holdings.forEach(h => {
            if (!groups[h.assetClass]) groups[h.assetClass] = { value: 0, target: 0 };
            groups[h.assetClass].value += h.marketValue;
            groups[h.assetClass].target += (h.targetAllocation || 0);
        });

        // Add Cash
        groups['Cash'] = { value: cashBalance, target: impliedCashTarget };

        // Convert to Array & Filter empty unless it has a target
        data = Object.entries(groups)
            .filter(([_, stats]) => stats.value > 0 || stats.target > 0)
            .map(([name, stats]) => ({
                name,
                value: stats.value,
                targetPct: stats.target,
                actualPct: netWorth > 0 ? (stats.value / netWorth) * 100 : 0
            }));

    } else {
        // By Symbol
        data = holdings.map(h => ({
            name: h.symbol,
            value: h.marketValue,
            targetPct: h.targetAllocation || 0,
            actualPct: netWorth > 0 ? (h.marketValue / netWorth) * 100 : 0
        }));

        // Add Cash
        if (cashBalance > 0 || impliedCashTarget > 0) {
            data.push({
                name: 'Cash',
                value: cashBalance,
                targetPct: impliedCashTarget,
                actualPct: netWorth > 0 ? (cashBalance / netWorth) * 100 : 0
            });
        }
    }

    // Calculate Action Values & Sort
    return data.map(item => {
        // Drift: Positive means Overweight, Negative means Underweight
        const driftPct = item.actualPct - item.targetPct;
        // Action Value: How much to Buy (+) or Sell (-) to reach target
        const actionValue = (item.targetPct - item.actualPct) / 100 * netWorth;
        return { ...item, driftPct, actionValue };
    }).sort((a, b) => b.value - a.value);

  }, [holdings, allocationMetric, cashBalance, netWorth]);

  const displayHoldings = useMemo(() => {
    let filtered = hideClosed 
      ? holdings.filter(h => h.shares > 0.000001) 
      : holdings;

    // Enrich with weight and diff
    const enriched = filtered.map(h => {
        const weight = totalMarketValue > 0 ? (h.marketValue / totalMarketValue) * 100 : 0;
        const diff = weight - (h.targetAllocation || 0);
        return { ...h, weight, diff };
    });

    // Sorting
    return enriched.sort((a, b) => {
        let valA: any = a[sortField as keyof typeof a];
        let valB: any = b[sortField as keyof typeof b];

        // Handle undefined or special cases
        if (sortField === 'weight') {
            valA = a.weight;
            valB = b.weight;
        }

        if (valA < valB) return sortDirection === 'asc' ? -1 : 1;
        if (valA > valB) return sortDirection === 'asc' ? 1 : -1;
        return 0;
    });

  }, [holdings, hideClosed, sortField, sortDirection, totalMarketValue]);

  const groupedHoldings = useMemo(() => {
    if (!groupByCategory) return null;
    const groups: Partial<Record<AssetClass, typeof displayHoldings>> = {};
    displayHoldings.forEach(h => {
      if (!groups[h.assetClass]) groups[h.assetClass] = [];
      groups[h.assetClass]?.push(h);
    });
    return groups;
  }, [displayHoldings, groupByCategory]);

  const bestPerformer = useMemo(() => {
     if (displayHoldings.length === 0) return null;
     return [...displayHoldings].sort((a,b) => b.unrealizedPLPercent - a.unrealizedPLPercent)[0];
  }, [displayHoldings]);

  if (isLoading) return <HoldingsSkeleton />;

  // --- COMPONENTS ---

  const renderSparkline = (h: Holding, height = 50) => {
    const sparklineData = transactions
      .filter(t => t.symbol === h.symbol && (t.type === 'BUY' || t.type === 'SELL') && (t.price || 0) > 0)
      .sort((a, b) => new Date(a.date).getTime() - new Date(b.date).getTime())
      .map((t) => ({ date: t.date, price: t.price! }));

    // Add current price point
    if (h.currentPrice > 0) {
        sparklineData.push({ date: 'Now', price: h.currentPrice });
    }

    const isUp = h.unrealizedPL >= 0;
    const color = isUp ? '#10b981' : '#f43f5e'; // Emerald-500 or Rose-500

    if (sparklineData.length < 2) return <div className="text-[10px] text-slate-300 italic h-full flex items-center justify-center">No Data</div>;

    return (
      <ResponsiveContainer width="100%" height={height}>
        <AreaChart data={sparklineData} margin={{ top: 5, right: 0, left: 0, bottom: 0 }}>
          <defs>
            <linearGradient id={`gradient-${h.symbol}`} x1="0" y1="0" x2="0" y2="1">
              <stop offset="5%" stopColor={color} stopOpacity={0.2}/>
              <stop offset="95%" stopColor={color} stopOpacity={0}/>
            </linearGradient>
          </defs>
          <Tooltip 
             contentStyle={{ backgroundColor: '#1e293b', borderColor: '#334155', borderRadius: '8px', padding: '4px 8px' }}
             itemStyle={{ color: '#fff', fontSize: '10px', fontWeight: 'bold' }}
             labelStyle={{ display: 'none' }}
             formatter={(value: any) => [formatCurrency(value), 'Price']}
          />
          <Area 
            type="monotone" 
            dataKey="price" 
            stroke={color} 
            strokeWidth={2} 
            fill={`url(#gradient-${h.symbol})`} 
            isAnimationActive={false} 
          />
          {/* Baseline if possible, though strict 0 might be far off scale. Use start price as baseline visually? */}
        </AreaChart>
      </ResponsiveContainer>
    );
  };

  const renderCard = (h: any) => {
    const isEditingPrice = editingPrice === h.symbol;
    const isEditingTarget = editingTarget === h.symbol;
    const target = h.targetAllocation || 0;

    return (
      <div key={h.symbol} className={`group flex flex-col bg-white dark:bg-slate-800 rounded-2xl border border-slate-200 dark:border-slate-700 shadow-sm hover:shadow-xl hover:-translate-y-1 transition-all duration-300 overflow-hidden relative ${h.shares === 0 ? 'opacity-60 grayscale' : ''}`}>
         <div className="p-4 flex-1 flex flex-col">

            {/* Header: Icon, Name, Price */}
            <div className="flex justify-between items-start mb-3">
              <div className="flex items-center space-x-3 min-w-0">
                  <div className={`w-10 h-10 rounded-xl flex items-center justify-center font-bold text-sm shrink-0 shadow-sm ${
                      h.unrealizedPL >= 0 ? 'bg-emerald-50 text-emerald-700 dark:bg-emerald-900/20 dark:text-emerald-400' : 'bg-rose-50 text-rose-700 dark:bg-rose-900/20 dark:text-rose-400'
                  }`}>
                    {h.symbol.substring(0, 2)}
                  </div>
                  <div className="min-w-0">
                    <h3 className="font-bold text-slate-900 dark:text-white leading-tight truncate">{h.symbol}</h3>
                    <div className="flex items-center gap-1.5 text-xs text-slate-500 dark:text-slate-400">
                         <span className="truncate">{h.name}</span>
                    </div>
                  </div>
              </div>
              <div className="text-right shrink-0">
                   {isEditingPrice ? (
                      <input 
                        type="number" 
                        value={tempPrice} 
                        onChange={(e) => setTempPrice(e.target.value)}
                        className="w-20 px-2 py-1 text-sm font-bold border-2 border-blue-500 rounded-lg bg-white dark:bg-slate-900 dark:text-white focus:outline-none text-right"
                        autoFocus
                        onBlur={() => handleSavePrice(h.symbol)}
                        onKeyDown={(e) => e.key === 'Enter' && handleSavePrice(h.symbol)}
                        onClick={(e) => e.stopPropagation()}
                      />
                   ) : (
                      <div className="cursor-pointer group/price" onClick={(e) => handleEditPriceClick(h.symbol, h.currentPrice, e)}>
                         <p className="text-base font-extrabold text-slate-900 dark:text-white group-hover/price:text-blue-500 transition-colors">{formatCurrency(h.currentPrice)}</p>
                         <div className="flex items-center justify-end gap-1 text-[10px] text-slate-400 uppercase font-bold tracking-wider">
                            <span>Price</span>
                            <Edit2 size={8} className="opacity-0 group-hover/price:opacity-100 transition-opacity" />
                         </div>
                      </div>
                   )}
              </div>
            </div>

            {/* Sparkline */}
            <div className="h-12 w-full -mx-2 mb-3 opacity-90">
                {h.shares > 0 && renderSparkline(h, 45)}
            </div>

            {/* Metrics Grid */}
            <div className="grid grid-cols-2 gap-x-4 gap-y-3 mb-4">
               <div>
                 <p className="text-[10px] uppercase text-slate-500 dark:text-slate-400 font-bold mb-0.5">Value</p>
                 <p className="text-sm font-extrabold text-slate-900 dark:text-white">{formatCurrency(h.marketValue)}</p>
                 <div className="text-[10px] text-slate-400 font-medium">
                     {h.weight.toFixed(1)}% of Portfolio
                 </div>
               </div>
               <div className="text-right">
                 <p className="text-[10px] uppercase text-slate-500 dark:text-slate-400 font-bold mb-0.5">Unrealized P/L</p>
                 <div className={`text-sm font-extrabold ${h.unrealizedPL >= 0 ? 'text-emerald-600 dark:text-emerald-400' : 'text-rose-600 dark:text-rose-400'}`}>
                     {h.unrealizedPL >= 0 ? '+' : ''}{formatCurrency(h.unrealizedPL)}
                 </div>
                 <div className={`text-[10px] font-bold ${h.unrealizedPLPercent >= 0 ? 'text-emerald-600 dark:text-emerald-400' : 'text-rose-600 dark:text-rose-400'}`}>
                    {h.unrealizedPLPercent >= 0 ? <ArrowUp size={10} className="inline mr-0.5"/> : <ArrowDown size={10} className="inline mr-0.5"/>}
                    {h.unrealizedPLPercent.toFixed(2)}%
                 </div>
               </div>
            </div>

            {/* Target & Rebalance Info */}
            <div className="bg-slate-50 dark:bg-slate-900/50 rounded-xl p-2.5 mb-3 flex justify-between items-center border border-slate-100 dark:border-slate-700/50">
                <div className="flex items-center gap-2" onClick={(e) => !isEditingTarget && handleEditTargetClick(h.symbol, target, e)}>
                    <Target size={14} className="text-slate-400" />
                    {isEditingTarget ? (
                        <div className="flex items-center">
                            <input 
                                type="number" 
                                value={tempTarget} 
                                onChange={(e) => setTempTarget(e.target.value)}
                                className="w-10 px-0 py-0 text-xs border-b-2 border-blue-500 bg-transparent outline-none font-bold text-slate-900 dark:text-white"
                                autoFocus
                                onClick={(e) => e.stopPropagation()}
                                onBlur={() => handleSaveTarget(h.symbol)}
                                onKeyDown={(e) => e.key === 'Enter' && handleSaveTarget(h.symbol)}
                            />
                            <span className="text-xs text-slate-500 font-bold">%</span>
                        </div>
                    ) : (
                        <div className="flex flex-col cursor-pointer hover:opacity-70">
                           <span className="text-[10px] font-bold uppercase text-slate-400">Target</span>
                           <span className="text-xs font-bold text-slate-700 dark:text-slate-300">{target > 0 ? `${target}%` : '-'}</span>
                        </div>
                    )}
                </div>

                {/* Diff Indicator */}
                <div className="text-right">
                    <span className="text-[10px] font-bold uppercase text-slate-400">Diff</span>
                    <div className={`text-xs font-bold ${Math.abs(h.diff) < 1 ? 'text-slate-400' : h.diff > 0 ? 'text-emerald-500' : 'text-amber-500'}`}>
                        {h.diff > 0 ? '+' : ''}{h.diff.toFixed(1)}%
                    </div>
                </div>
            </div>

            {/* Quick Actions (Hover Visible on Desktop, Always on Mobile) */}
            <div className="flex items-center gap-2 mt-auto pt-2 border-t border-slate-100 dark:border-slate-800 opacity-100 sm:opacity-0 sm:group-hover:opacity-100 transition-opacity">
               <button onClick={() => onTrade(h.symbol, TransactionType.BUY)} className="flex-1 py-1.5 rounded-lg bg-emerald-50 dark:bg-emerald-900/20 text-emerald-700 dark:text-emerald-400 text-xs font-bold flex items-center justify-center hover:bg-emerald-100 dark:hover:bg-emerald-900/40 transition-colors">
                  <Plus size={12} className="mr-1" /> Buy
               </button>
               <button onClick={() => onTrade(h.symbol, TransactionType.SELL)} className="flex-1 py-1.5 rounded-lg bg-rose-50 dark:bg-rose-900/20 text-rose-700 dark:text-rose-400 text-xs font-bold flex items-center justify-center hover:bg-rose-100 dark:hover:bg-rose-900/40 transition-colors">
                  <Minus size={12} className="mr-1" /> Sell
               </button>
            </div>
         </div>
      </div>
    );
  };

  const renderSummaryRow = () => (
      <div className="grid grid-cols-2 md:grid-cols-4 gap-4 mb-8">
          {/* Net Worth */}
          <div className="bg-slate-900 dark:bg-slate-800 text-white p-5 rounded-2xl shadow-lg relative overflow-hidden group">
              <div className="absolute top-0 right-0 p-4 opacity-10 group-hover:scale-110 transition-transform"><Wallet size={48} /></div>
              <p className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-1">Total Net Worth</p>
              <h3 className="text-2xl md:text-3xl font-display font-bold">{formatCurrency(netWorth)}</h3>
              <div className="flex gap-3 mt-3 text-[10px] font-bold uppercase text-slate-400">
                  <span>Cash: {formatCurrency(cashBalance)}</span>
                  <span>Assets: {formatCurrency(totalMarketValue)}</span>
              </div>
          </div>

          {/* Unrealized P/L */}
          <div className={`p-5 rounded-2xl border shadow-sm ${totalUnrealizedPL >= 0 ? 'bg-emerald-50 border-emerald-100 dark:bg-emerald-900/10 dark:border-emerald-800' : 'bg-rose-50 border-rose-100 dark:bg-rose-900/10 dark:border-rose-800'}`}>
              <p className={`text-xs font-bold uppercase tracking-wider mb-1 ${totalUnrealizedPL >= 0 ? 'text-emerald-600 dark:text-emerald-400' : 'text-rose-600 dark:text-rose-400'}`}>Unrealized P/L</p>
              <h3 className={`text-2xl font-display font-bold ${totalUnrealizedPL >= 0 ? 'text-emerald-700 dark:text-emerald-300' : 'text-rose-700 dark:text-rose-300'}`}>
                  {totalUnrealizedPL >= 0 ? '+' : ''}{formatCurrency(totalUnrealizedPL)}
              </h3>
               <div className={`mt-2 text-xs font-bold ${totalCost > 0 ? (totalUnrealizedPL >= 0 ? 'text-emerald-600' : 'text-rose-600') : 'text-slate-400'}`}>
                  {totalCost > 0 ? ((totalUnrealizedPL/totalCost)*100).toFixed(2) : 0}% Return
               </div>
          </div>

           {/* Asset Count */}
           <div className="bg-white dark:bg-slate-800 p-5 rounded-2xl border border-slate-200 dark:border-slate-700 shadow-sm flex flex-col justify-between">
              <div>
                 <p className="text-xs font-bold text-slate-500 uppercase tracking-wider mb-1">Active Positions</p>
                 <h3 className="text-2xl font-display font-bold text-slate-900 dark:text-white">{displayHoldings.length}</h3>
              </div>
              <div className="mt-2 text-[10px] text-slate-400 font-bold uppercase flex gap-2">
                 <span className="bg-blue-50 text-blue-600 px-1.5 py-0.5 rounded">Stock: {holdings.filter(h => h.assetClass === 'Stock' && h.shares > 0).length}</span>
                 <span className="bg-purple-50 text-purple-600 px-1.5 py-0.5 rounded">Crypto: {holdings.filter(h => h.assetClass === 'Crypto' && h.shares > 0).length}</span>
              </div>
          </div>

           {/* Best Performer Summary */}
           <div className="bg-white dark:bg-slate-800 p-5 rounded-2xl border border-slate-200 dark:border-slate-700 shadow-sm flex flex-col justify-between relative overflow-hidden">
               {bestPerformer ? (
                   <>
                       <div className="absolute right-0 top-0 p-3 opacity-5"><TrendingUp size={60} /></div>
                       <p className="text-xs font-bold text-slate-500 uppercase tracking-wider mb-1">Top Performer</p>
                       <div className="flex items-center gap-2">
                           <div className="w-8 h-8 rounded-lg bg-emerald-100 dark:bg-emerald-900/30 text-emerald-600 dark:text-emerald-400 flex items-center justify-center font-bold text-xs">
                               {bestPerformer.symbol.substring(0,2)}
                           </div>
                           <div>
                               <h3 className="text-lg font-bold text-slate-900 dark:text-white leading-none">{bestPerformer.symbol}</h3>
                               <p className="text-emerald-500 font-bold text-sm">+{bestPerformer.unrealizedPLPercent.toFixed(1)}%</p>
                           </div>
                       </div>
                   </>
               ) : (
                   <div className="flex h-full items-center justify-center text-slate-400 text-xs italic">No data available</div>
               )}
           </div>
      </div>
  );

  const renderTableHead = (label: string, field: SortField, align = 'left') => (
      <th 
         className={`px-4 py-3 text-xs font-bold text-slate-500 dark:text-slate-400 uppercase tracking-wider cursor-pointer hover:bg-slate-100 dark:hover:bg-slate-700 transition-colors ${align === 'right' ? 'text-right' : 'text-left'}`}
         onClick={() => handleSort(field)}
      >
         <div className={`flex items-center gap-1 ${align === 'right' ? 'justify-end' : 'justify-start'}`}>
            {label}
            {sortField === field && <ArrowUpDown size={12} className={sortDirection === 'asc' ? 'rotate-180' : ''} />}
         </div>
      </th>
  );

  return (
    <div className="space-y-6 animate-fade-in pb-20">

      {/* 1. Summary Dashboard */}
      {renderSummaryRow()}

      {/* 2. Enhanced Allocation Analysis (NEW) */}
      {allocationAnalysis.length > 0 && (
         <div className="bg-white dark:bg-slate-800 rounded-3xl border border-slate-200 dark:border-slate-700 p-6 md:p-8 flex flex-col lg:flex-row gap-8 mb-8 relative overflow-hidden shadow-sm">

             {/* Chart Section */}
             <div className="lg:w-1/3 flex flex-col items-center">
                 <div className="w-full flex items-center justify-between mb-4">
                     <h3 className="text-lg font-bold text-slate-900 dark:text-white flex items-center">
                        <PieChartIcon size={20} className="mr-2 text-slate-400"/> Allocation
                     </h3>
                     <div className="bg-slate-100 dark:bg-slate-700 p-1 rounded-lg flex text-xs font-bold">
                         <button onClick={() => setAllocationMetric('assetClass')} className={`px-3 py-1.5 rounded-md transition-all ${allocationMetric === 'assetClass' ? 'bg-white dark:bg-slate-600 shadow text-slate-900 dark:text-white' : 'text-slate-500 dark:text-slate-400'}`}>Class</button>
                         <button onClick={() => setAllocationMetric('symbol')} className={`px-3 py-1.5 rounded-md transition-all ${allocationMetric === 'symbol' ? 'bg-white dark:bg-slate-600 shadow text-slate-900 dark:text-white' : 'text-slate-500 dark:text-slate-400'}`}>Symbol</button>
                     </div>
                 </div>

                 <div className="w-full h-[260px] relative">
                      <ResponsiveContainer width="100%" height="100%">
                          <PieChart>
                              <Pie
                                  data={allocationAnalysis}
                                  cx="50%"
                                  cy="50%"
                                  innerRadius={65}
                                  outerRadius={85}
                                  paddingAngle={4}
                                  dataKey="value"
                                  cornerRadius={6}
                                  stroke="none"
                              >
                                  {allocationAnalysis.map((entry, index) => (
                                      <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                                  ))}
                              </Pie>
                              <Tooltip 
                                contentStyle={{ backgroundColor: '#1e293b', borderColor: '#334155', borderRadius: '8px', padding: '8px' }}
                                itemStyle={{ color: '#fff', fontSize: '12px', fontWeight: 'bold' }}
                                formatter={(value: number) => formatCurrency(value)}
                              />
                          </PieChart>
                      </ResponsiveContainer>
                      <div className="absolute inset-0 flex flex-col items-center justify-center pointer-events-none">
                          <p className="text-[10px] font-bold uppercase text-slate-400 tracking-widest">Total</p>
                          <p className="text-xl font-bold text-slate-900 dark:text-white">{formatCurrency(netWorth).split('.')[0]}</p>
                      </div>
                 </div>
             </div>

             {/* Rebalancing & Target List */}
             <div className="flex-1 border-l border-slate-100 dark:border-slate-700 pl-0 lg:pl-8 pt-4 lg:pt-0">
                 <div className="flex items-center gap-2 mb-4 text-sm font-bold text-slate-500 uppercase tracking-wide">
