                                        <td className="px-6 py-4 text-right font-medium text-slate-600 dark:text-slate-300">{row.transactionCount}</td>
                                        <td className="px-6 py-4 text-right text-slate-600 dark:text-slate-300">{formatCurrency(row.buyVolume)}</td>
                                        <td className="px-6 py-4 text-right text-slate-600 dark:text-slate-300">{formatCurrency(row.sellVolume)}</td>
