                      </h3>
                      <span className={`text-sm font-bold ${totalUnrealizedPL >= 0 ? 'text-emerald-600' : 'text-rose-600'}`}>
                          ({totalReturnPercent >= 0 ? '+' : ''}{totalReturnPercent.toFixed(2)}%)
                      </span>
                  </div>
              </div>
              {/* Mini visual bar for return */}
              <div className="w-full h-1.5 bg-white/50 dark:bg-black/20 rounded-full mt-3 overflow-hidden">
                  <div className={`h-full ${totalUnrealizedPL >= 0 ? 'bg-emerald-500' : 'bg-rose-500'}`} style={{ width: `${Math.min(Math.abs(totalReturnPercent), 100)}%` }}></div>
              </div>
          </div>

           {/* 3. Interactive Asset Filter */}
           <div className="bg-white dark:bg-slate-800 p-5 rounded-2xl border border-slate-200 dark:border-slate-700 shadow-sm flex flex-col">
              <p className="text-xs font-bold text-slate-500 uppercase tracking-wider mb-3">Active Positions</p>
              <div className="flex items-center gap-2 mb-2">
                 <h3 className="text-3xl font-display font-bold text-slate-900 dark:text-white">{holdings.filter(h => h.shares > 0).length}</h3>
                 <span className="text-xs text-slate-400 font-medium">Assets</span>
              </div>
              <div className="flex gap-2 mt-auto">
                 {['ALL', 'Stock', 'Crypto'].map((type) => (
                     <button 
                        key={type}
                        onClick={() => setActiveFilter(type as any)}
                        className={`px-2.5 py-1 rounded-lg text-[10px] font-bold uppercase transition-all ${
                            activeFilter === type 
                            ? 'bg-slate-900 text-white dark:bg-white dark:text-slate-900 shadow-md' 
                            : 'bg-slate-100 text-slate-500 dark:bg-slate-700 dark:text-slate-400 hover:bg-slate-200'
                        }`}
                     >
                        {type}
                     </button>
                 ))}
              </div>
          </div>

           {/* 4. Top Performer */}
           <div className="bg-white dark:bg-slate-800 p-5 rounded-2xl border border-slate-200 dark:border-slate-700 shadow-sm relative overflow-hidden flex flex-col justify-between">
               {bestPerformer ? (
                   <>
                       <div className="flex justify-between items-start">
                           <p className="text-xs font-bold text-slate-500 uppercase tracking-wider">Top Performer</p>
                           <span className="px-2 py-0.5 rounded text-[9px] font-bold uppercase bg-blue-50 text-blue-600 dark:bg-blue-900/30 dark:text-blue-400">{bestPerformer.assetClass}</span>
                       </div>
                       <div className="mt-2">
                           <h3 className="text-xl font-bold text-slate-900 dark:text-white leading-none mb-1">{bestPerformer.symbol}</h3>
                           <p className="text-emerald-500 font-bold text-lg flex items-center">
                               <TrendingUp size={16} className="mr-1" />
                               +{bestPerformer.unrealizedPLPercent.toFixed(1)}%
                           </p>
                       </div>
                   </>
               ) : (
                   <div className="flex h-full items-center justify-center text-slate-400 text-xs italic">No data available</div>
               )}
           </div>
      </div>
  );

  const renderTableHead = (label: string, field: SortField, align = 'left', tooltip?: string) => (
      <th 
         className={`sticky top-0 z-10 bg-slate-50 dark:bg-slate-900 border-b border-slate-200 dark:border-slate-700 px-4 py-3 text-xs font-bold text-slate-500 dark:text-slate-400 uppercase tracking-wider cursor-pointer hover:bg-slate-100 dark:hover:bg-slate-800 transition-colors ${align === 'right' ? 'text-right' : 'text-left'}`}
         onClick={() => handleSort(field)}
         title={tooltip}
      >
         <div className={`flex items-center gap-1 ${align === 'right' ? 'justify-end' : 'justify-start'}`}>
            {label}
            {sortField === field && <ArrowUpDown size={12} className={sortDirection === 'asc' ? 'rotate-180' : ''} />}
         </div>
      </th>
  );

  return (
    <div className="space-y-8 animate-fade-in pb-20">

      {/* 1. Summary Dashboard */}
      {renderSummaryRow()}

      {/* 2. Rebalancing & Allocation Section */}
      {allocationAnalysis.length > 0 && (
         <div className="bg-white dark:bg-slate-800 rounded-3xl border border-slate-200 dark:border-slate-700 p-6 md:p-8 flex flex-col lg:flex-row gap-8 relative overflow-hidden shadow-sm">

             {/* Chart Section */}
             <div className="lg:w-1/3 flex flex-col items-center border-b lg:border-b-0 lg:border-r border-slate-100 dark:border-slate-700 pb-6 lg:pb-0 lg:pr-8">
                 <div className="w-full flex items-center justify-between mb-4">
                     <h3 className="text-lg font-bold text-slate-900 dark:text-white flex items-center">
                        <PieChartIcon size={20} className="mr-2 text-slate-400"/> Allocation
                     </h3>
                     <div className="bg-slate-100 dark:bg-slate-700 p-1 rounded-lg flex text-xs font-bold">
                         <button onClick={() => setAllocationMetric('assetClass')} className={`px-3 py-1.5 rounded-md transition-all ${allocationMetric === 'assetClass' ? 'bg-white dark:bg-slate-600 shadow text-slate-900 dark:text-white' : 'text-slate-500 dark:text-slate-400'}`}>Class</button>
                         <button onClick={() => setAllocationMetric('symbol')} className={`px-3 py-1.5 rounded-md transition-all ${allocationMetric === 'symbol' ? 'bg-white dark:bg-slate-600 shadow text-slate-900 dark:text-white' : 'text-slate-500 dark:text-slate-400'}`}>Symbol</button>
                     </div>
                 </div>

                 <div className="w-full h-[260px] relative">
                      <ResponsiveContainer width="100%" height="100%">
                          <PieChart>
                              <Pie data={allocationAnalysis} cx="50%" cy="50%" innerRadius={65} outerRadius={85} paddingAngle={4} dataKey="value" cornerRadius={6} stroke="none">
                                  {allocationAnalysis.map((entry, index) => <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />)}
                              </Pie>
                              <Tooltip contentStyle={{ backgroundColor: '#1e293b', borderColor: '#334155', borderRadius: '8px', padding: '8px' }} itemStyle={{ color: '#fff', fontSize: '12px', fontWeight: 'bold' }} formatter={(value: number) => formatCurrency(value)} />
                          </PieChart>
                      </ResponsiveContainer>
                      <div className="absolute inset-0 flex flex-col items-center justify-center pointer-events-none">
                          <p className="text-[10px] font-bold uppercase text-slate-400 tracking-widest">Total</p>
                          <p className="text-xl font-bold text-slate-900 dark:text-white">{formatCurrency(netWorth).split('.')[0]}</p>
                          <p className="text-xs text-slate-500 font-medium mt-1">100%</p>
                      </div>
                 </div>
             </div>

             {/* Rebalancing Analysis List */}
             <div className="flex-1">
                 <div className="flex items-center justify-between mb-4">
                    <div className="flex items-center gap-2 text-sm font-bold text-slate-500 uppercase tracking-wide">
                        <Scale size={16} /> <span>Rebalancing Analysis</span>
                    </div>
                    {/* Header for columns */}
                    <div className="hidden sm:flex text-[10px] font-bold text-slate-400 uppercase gap-8 pr-4">
                        <span className="w-16 text-right">Target</span>
                        <span className="w-16 text-right">Actual</span>
                        <span className="w-20 text-right">Action</span>
                    </div>
                 </div>

                 <div className="grid grid-cols-1 gap-3 max-h-[320px] overflow-y-auto custom-scrollbar pr-2">
                     {allocationAnalysis.map((item, idx) => {
                         const barColor = COLORS[idx % COLORS.length];
                         const actionType = item.actionValue > 0 ? 'Buy' : 'Sell';
                         const showAction = Math.abs(item.actionValue) > 10;
                         const driftStatus = item.driftPct > 5 ? 'Overweight' : item.driftPct < -5 ? 'Underweight' : 'Balanced';
                         const driftColor = driftStatus === 'Overweight' ? 'text-amber-500' : driftStatus === 'Underweight' ? 'text-blue-500' : 'text-emerald-500';
                         const isEditing = editingTarget === item.name;

                         return (
                             <div key={item.name} className="bg-slate-50 dark:bg-slate-900/50 p-3 rounded-xl border border-slate-100 dark:border-slate-800 flex flex-col sm:flex-row sm:items-center justify-between gap-3">
                                 {/* Asset Info */}
                                 <div className="flex items-center gap-3 flex-1 min-w-0">
                                     <div className="w-3 h-3 rounded-full shrink-0" style={{ backgroundColor: barColor }}></div>
                                     <div className="min-w-0">
                                         <div className="flex items-center gap-2">
                                            <span className="font-bold text-slate-900 dark:text-white text-sm truncate">{item.name}</span>
                                            <span className={`text-[9px] font-bold px-1.5 py-0.5 rounded border ${driftStatus === 'Balanced' ? 'border-emerald-200 text-emerald-600 bg-emerald-50 dark:bg-emerald-900/20' : driftStatus === 'Overweight' ? 'border-amber-200 text-amber-600 bg-amber-50 dark:bg-amber-900/20' : 'border-blue-200 text-blue-600 bg-blue-50 dark:bg-blue-900/20'}`}>
                                                {driftStatus}
                                            </span>
                                         </div>
                                         <div className="text-xs text-slate-500 font-mono mt-0.5">{formatCurrency(item.value)}</div>
                                     </div>
                                 </div>

                                 {/* Metrics Grid (Mobile: Grid, Desktop: Flex) */}
                                 <div className="grid grid-cols-3 sm:flex sm:items-center gap-4 sm:gap-8 border-t sm:border-0 border-slate-200 dark:border-slate-700 pt-2 sm:pt-0">

                                     {/* Target Input */}
                                     <div className="text-center sm:text-right w-full sm:w-16">
                                         <span className="sm:hidden text-[10px] font-bold text-slate-400 uppercase block mb-1">Target</span>
                                         <div onClick={(e) => !isEditing && handleEditTargetClick(item.name, item.targetPct, e)} className="cursor-pointer hover:bg-slate-200 dark:hover:bg-slate-700 rounded px-1 -mr-1 transition-colors">
                                             {isEditing ? (
                                                 <input 
                                                    autoFocus type="number" value={tempTarget} onChange={(e) => setTempTarget(e.target.value)}
                                                    onBlur={() => handleSaveTarget(item.name)} onKeyDown={(e) => e.key === 'Enter' && handleSaveTarget(item.name)}
                                                    className="w-12 text-right font-bold bg-transparent border-b-2 border-blue-500 outline-none text-sm"
                                                 />
                                             ) : (
                                                 <span className="text-sm font-bold text-slate-700 dark:text-slate-300">{item.targetPct}%</span>
                                             )}
                                         </div>
                                     </div>

                                     {/* Actual % */}
                                     <div className="text-center sm:text-right w-full sm:w-16">
                                         <span className="sm:hidden text-[10px] font-bold text-slate-400 uppercase block mb-1">Actual</span>
                                         <span className={`text-sm font-bold ${driftColor}`}>{item.actualPct.toFixed(1)}%</span>
                                     </div>

                                     {/* Action Suggestion */}
                                     <div className="text-center sm:text-right w-full sm:w-20 flex justify-center sm:justify-end">
                                         {showAction ? (
                                             <div className={`flex flex-col items-end`}>
                                                 <span className={`text-[10px] font-bold uppercase ${actionType === 'Buy' ? 'text-blue-600' : 'text-rose-600'}`}>{actionType}</span>
                                                 <span className="text-xs font-mono font-bold text-slate-700 dark:text-slate-300">{formatCurrency(Math.abs(item.actionValue)).split('.')[0]}</span>
                                             </div>
                                         ) : (
                                             <span className="text-emerald-500 font-bold text-xs flex items-center"><CheckCircle2 size={14} /></span>
                                         )}
                                     </div>
                                 </div>
                             </div>
                         )
                     })}
                 </div>
             </div>
         </div>
      )}

      {/* 3. Performance Summary Strip */}
      <div className="bg-gradient-to-r from-slate-100 to-white dark:from-slate-800 dark:to-slate-900 border border-slate-200 dark:border-slate-700 rounded-2xl p-6 flex flex-col md:flex-row justify-between items-center gap-6">
          <div className="flex items-center gap-4">
              <div className="p-3 bg-white dark:bg-slate-700 rounded-full shadow-sm text-slate-400">
                  <Activity size={24} />
              </div>
