                                                                        </span>
                                                                    </td>
                                                                    <td className="px-4 py-3 font-bold text-slate-900 dark:text-white">{tx.symbol || '-'}</td>
                                                                    <td className="px-4 py-3 text-right font-mono font-medium text-slate-800 dark:text-slate-200">
                                                                        {formatCurrency((tx.shares && (tx.type === 'BUY' || tx.type === 'SELL')) ? (tx.shares * (tx.price||0)) : (tx.price||0))}
                                                                    </td>
                                                                    <td className="px-4 py-3 text-right text-slate-500">
                                                                        {tx.shares ? `${tx.shares} @ ${formatCurrency(tx.price||0)}` : '-'}
                                                                    </td>
                                                                </tr>
                                                            ))}
                                                        </tbody>
                                                    </table>
                                                </div>
                                            </td>
                                        </tr>
                                    )}
                                </React.Fragment>
                            ))}
                        </tbody>
                    </table>
                </div>
            </div>
        </div>
    );
};

