                        </div>
                        <div className={`text-2xl font-display font-bold ${netFundingUSD >= 0 ? 'text-emerald-500' : 'text-rose-500'}`}>
                            {netFundingUSD >= 0 ? '+' : ''}{formatCurrency(netFundingUSD)}
