                                            {val > 0 ? '+' : ''}{val.toFixed(2)}%
                                         </p>
                                      </div>
                                   )
                                }
                                return null;
                             }}
                          />
                          <ReferenceLine y={0} stroke="#94a3b8" />
                          <Bar dataKey="value" radius={[2, 2, 0, 0]}>
                             {displayedReturns.map((entry, index) => (
                                <Cell key={`cell-${index}`} fill={entry.value >= 0 ? '#10b981' : '#f43f5e'} />
                             ))}
                          </Bar>
                       </BarChart>
                    </ResponsiveContainer>
                 </div>

                 <div className="mt-4 pt-4 border-t border-slate-100 dark:border-slate-700 flex justify-between text-xs font-medium text-slate-500">
                    <span>Avg Monthly Return: <span className={avgMonthlyReturn >= 0 ? "text-emerald-500" : "text-rose-500"}>{avgMonthlyReturn > 0 ? '+' : ''}{avgMonthlyReturn.toFixed(2)}%</span></span>
                    <span>Best: <span className="text-emerald-500">+{Math.max(...displayedReturns.map(d => d.value), 0).toFixed(2)}%</span></span>
                 </div>
             </div>
         </div>

         {/* 4. Holdings Performance Table (Winners/Losers) */}
         <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
             <div className="bg-white dark:bg-slate-800 rounded-3xl border border-slate-200 dark:border-slate-700 shadow-sm p-6">
                <h3 className="font-bold text-slate-900 dark:text-white mb-4 flex items-center">
                   <TrendingUp size={18} className="text-emerald-500 mr-2" /> Top Winners
                </h3>
                <div className="space-y-3">
                   {sortedHoldings.filter(h => h.unrealizedPL > 0).slice(0, 5).map(h => (
                      <div key={h.symbol} className="flex items-center justify-between p-3 bg-emerald-50 dark:bg-emerald-900/10 rounded-xl">
                         <div className="flex items-center gap-3">
                            <div className="font-bold text-slate-900 dark:text-white">{h.symbol}</div>
                            <div className="text-xs text-slate-500">{h.assetClass}</div>
                         </div>
                         <div className="text-right">
                            <div className="text-sm font-bold text-emerald-600 dark:text-emerald-400">+{formatCurrency(h.unrealizedPL)}</div>
                            <div className="text-xs text-emerald-600/70">+{h.unrealizedPLPercent.toFixed(2)}%</div>
                         </div>
                      </div>
                   ))}
                   {sortedHoldings.filter(h => h.unrealizedPL > 0).length === 0 && (
                      <div className="text-center text-slate-400 text-sm py-4 italic">No profitable positions yet.</div>
                   )}
                </div>
             </div>

             <div className="bg-white dark:bg-slate-800 rounded-3xl border border-slate-200 dark:border-slate-700 shadow-sm p-6">
                <h3 className="font-bold text-slate-900 dark:text-white mb-4 flex items-center">
                   <TrendingDown size={18} className="text-rose-500 mr-2" /> Top Losers
                </h3>
                <div className="space-y-3">
                   {[...sortedHoldings].reverse().filter(h => h.unrealizedPL < 0).slice(0, 5).map(h => (
                      <div key={h.symbol} className="flex items-center justify-between p-3 bg-rose-50 dark:bg-rose-900/10 rounded-xl">
                         <div className="flex items-center gap-3">
                            <div className="font-bold text-slate-900 dark:text-white">{h.symbol}</div>
                            <div className="text-xs text-slate-500">{h.assetClass}</div>
                         </div>
                         <div className="text-right">
                            <div className="text-sm font-bold text-rose-600 dark:text-rose-400">{formatCurrency(h.unrealizedPL)}</div>
                            <div className="text-xs text-rose-600/70">{h.unrealizedPLPercent.toFixed(2)}%</div>
                         </div>
                      </div>
                   ))}
                   {sortedHoldings.filter(h => h.unrealizedPL < 0).length === 0 && (
                      <div className="text-center text-slate-400 text-sm py-4 italic">No losing positions. Great job!</div>
                   )}
                </div>
             </div>
         </div>

      </div>
   );
};

export default Reports;

import React, { useState, useEffect, useRef } from 'react';
import { LayoutDashboard, PieChart, History, FileText, Menu, X, Sun, Moon, Plus, TrendingUp, ChevronDown, Trash2, Briefcase, Check, Edit2, Globe, Coins, Calculator } from 'lucide-react';
import { TransactionType, Portfolio } from '../types';

interface LayoutProps {
  children: React.ReactNode;
  activeTab: string;
  setActiveTab: (tab: string) => void;
  onOpenAddModal: () => void;
  // Portfolio Props
  portfolios: Portfolio[];
  activePortfolioId: string;
  onSwitchPortfolio: (id: string) => void;
  onCreatePortfolio: (name: string) => void;
  onRenamePortfolio: (id: string, newName: string) => void;
  onDeletePortfolio: (id: string) => void;
  // Currency Props
  currency: string;
  exchangeRate: number;
  onCurrencyChange: (currency: string) => void;
  onExchangeRateChange: (rate: number) => void;
}

const CURRENCIES = [
  { code: 'USD', symbol: '$', label: 'US Dollar' },
  { code: 'THB', symbol: '฿', label: 'Thai Baht' },
  { code: 'EUR', symbol: '€', label: 'Euro' },
  { code: 'GBP', symbol: '£', label: 'British Pound' },
  { code: 'JPY', symbol: '¥', label: 'Japanese Yen' },
  { code: 'CNY', symbol: '¥', label: 'Chinese Yuan' },
  { code: 'SGD', symbol: 'S$', label: 'Singapore Dollar' },
];

const Layout: React.FC<LayoutProps> = ({ 
  children, activeTab, setActiveTab, onOpenAddModal,
  portfolios, activePortfolioId, onSwitchPortfolio, onCreatePortfolio, onRenamePortfolio, onDeletePortfolio,
  currency, exchangeRate, onCurrencyChange, onExchangeRateChange
}) => {
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const [darkMode, setDarkMode] = useState(false);

  // Dropdown States
  const [isPortfolioDropdownOpen, setIsPortfolioDropdownOpen] = useState(false);
  const [isCurrencyDropdownOpen, setIsCurrencyDropdownOpen] = useState(false);

  // Modal States
  const [isCreateModalOpen, setIsCreateModalOpen] = useState(false);
  const [newPortfolioName, setNewPortfolioName] = useState('');
  const [isRenameModalOpen, setIsRenameModalOpen] = useState(false);
  const [portfolioToRename, setPortfolioToRename] = useState<Portfolio | null>(null);
  const [renameValue, setRenameValue] = useState('');

  const dropdownRef = useRef<HTMLDivElement>(null);
  const currencyDropdownRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    // Check local storage or system preference
    if (localStorage.getItem('theme') === 'dark' || (!localStorage.getItem('theme') && window.matchMedia('(prefers-color-scheme: dark)').matches)) {
      setDarkMode(true);
      document.documentElement.classList.add('dark');
    } else {
      setDarkMode(false);
      document.documentElement.classList.remove('dark');
    }
  }, []);

  // Close dropdowns when clicking outside
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
        setIsPortfolioDropdownOpen(false);
      }
      if (currencyDropdownRef.current && !currencyDropdownRef.current.contains(event.target as Node)) {
        setIsCurrencyDropdownOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const toggleDarkMode = () => {
    const newMode = !darkMode;
    setDarkMode(newMode);
    if (newMode) {
      document.documentElement.classList.add('dark');
      localStorage.setItem('theme', 'dark');
    } else {
      document.documentElement.classList.remove('dark');
      localStorage.setItem('theme', 'light');
    }
  };

  const navItems = [
    { id: 'dashboard', label: 'Overview', icon: <LayoutDashboard size={20} /> },
    { id: 'holdings', label: 'Holdings', icon: <PieChart size={20} /> },
    { id: 'history', label: 'History', icon: <History size={20} /> },
    { id: 'reports', label: 'Reports', icon: <FileText size={20} /> },
  ];

  const activePortfolio = portfolios.find(p => p.id === activePortfolioId) || portfolios[0];

  const handleCreateClick = () => {
    setNewPortfolioName('');
    setIsCreateModalOpen(true);
    setIsPortfolioDropdownOpen(false);
  };

  const handleCreateSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (newPortfolioName.trim()) {
      onCreatePortfolio(newPortfolioName.trim());
      setIsCreateModalOpen(false);
    }
  };

  const handleRenameClick = (e: React.MouseEvent, p: Portfolio) => {
    e.stopPropagation();
    setPortfolioToRename(p);
    setRenameValue(p.name);
    setIsRenameModalOpen(true);
    setIsPortfolioDropdownOpen(false);
  };

  const handleRenameSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (portfolioToRename && renameValue.trim()) {
      onRenamePortfolio(portfolioToRename.id, renameValue.trim());
      setIsRenameModalOpen(false);
      setPortfolioToRename(null);
    }
  };

  return (
    <div className="min-h-screen flex flex-col bg-slate-50 dark:bg-[#0b1120] transition-colors duration-300 font-sans selection:bg-indigo-500 selection:text-white">

