                </div>
                <span className="font-bold text-slate-900 dark:text-white font-mono tabular-nums">
                  {formatter ? formatter(entry.value, entry.name, entry) : entry.value}
                </span>
              </div>
            );
          })}
        </div>
      </div>
    );
  }
  return null;
};

