                                                                    </td>
                                                                    <td className="px-4 py-3 text-right text-slate-500">
                                                                        {tx.shares ? `${tx.shares} @ ${formatMoney(tx.price||0)}` : '-'}
                                                                    </td>
                                                                </tr>
                                                            ))}
                                                        </tbody>
                                                    </table>
                                                </div>
                                            </td>
                                        </tr>
                                    )}
                                </React.Fragment>
                            ))}
                        </tbody>
                    </table>
                </div>
            </div>
        </div>
    );
};

const DividendsView: React.FC<{ transactions: Transaction[], formatMoney: (val: number) => string }> = ({ transactions, formatMoney }) => {
