                    {losers.length > 0 ? losers.map(h => (
                        <div key={h.symbol} className="bg-rose-50 dark:bg-rose-900/10 p-3 rounded-xl">
                            <div className="flex justify-between items-start mb-1">
                                <span className="font-bold text-sm text-slate-900 dark:text-white">{h.symbol}</span>
                                <span className="text-xs font-bold text-rose-600 dark:text-rose-400">{h.unrealizedPLPercent.toFixed(1)}%</span>
                            </div>
                            <div className="text-[10px] text-slate-500 font-mono">{formatMoney(h.marketValue)}</div>
                        </div>
                    )) : <div className="text-xs text-slate-400 italic">No losers yet</div>}
                </div>
           </div>
        </div>

        {/* Recent Activity Feed */}
        <div className="bg-white dark:bg-slate-800 rounded-3xl p-6 border border-slate-200 dark:border-slate-700 shadow-sm flex flex-col h-full animate-slide-up" style={{ animationDelay: '0.4s' }}>
           <div className="flex items-center justify-between mb-4">
              <h3 className="font-bold text-slate-900 dark:text-white flex items-center">
                 <Clock size={18} className="mr-2 text-slate-400" /> Recent Activity
              </h3>
           </div>

           <div className="flex-1 overflow-y-auto custom-scrollbar pr-2 space-y-3">
              {recentTransactions.length > 0 ? (
                 recentTransactions.map((tx, i) => (
                   <div 
                        key={tx.id} 
                        className="flex items-center justify-between p-3 rounded-2xl bg-slate-50 dark:bg-slate-900/50"
                   >
                      <div className="flex items-center space-x-3">
                          <div className={`w-9 h-9 rounded-xl flex items-center justify-center text-xs font-bold ${
                             tx.type === 'BUY' ? 'bg-blue-100 text-blue-600 dark:bg-blue-900/30 dark:text-blue-400' :
                             tx.type === 'SELL' ? 'bg-rose-100 text-rose-600 dark:bg-rose-900/30 dark:text-rose-400' :
                             tx.type === 'DIVIDEND' ? 'bg-emerald-100 text-emerald-600 dark:bg-emerald-900/30 dark:text-emerald-400' :
                             'bg-slate-200 text-slate-600 dark:bg-slate-700 dark:text-slate-300'
                          }`}>
                              {tx.type === 'BUY' ? <TrendingUp size={16} /> : 
                               tx.type === 'SELL' ? <TrendingDown size={16} /> :
                               tx.type === 'DIVIDEND' ? <Coins size={16} /> : 
                               tx.type === 'DEPOSIT' ? <Plus size={16} /> : <ArrowRight size={16} />}
                          </div>
                          <div>
                             <div className="font-bold text-sm text-slate-900 dark:text-white">{tx.symbol || tx.type}</div>
                             <div className="text-[10px] text-slate-400">{new Date(tx.date).toLocaleDateString()}</div>
                          </div>
                      </div>
                      <div className="text-right">
                         <div className={`text-sm font-bold font-mono ${
                            (tx.type === 'SELL' || tx.type === 'DIVIDEND' || tx.type === 'DEPOSIT') ? 'text-emerald-600 dark:text-emerald-400' : 'text-slate-900 dark:text-white'
                         }`}>
                             {(tx.type === 'SELL' || tx.type === 'DIVIDEND' || tx.type === 'DEPOSIT') ? '+' : ''}
                             {formatMoney((tx.price || 0) * (tx.shares || 1))}
                         </div>
                         {tx.type === 'BUY' && tx.shares && <div className="text-[10px] text-slate-400">{formatNumber(tx.shares)} units</div>}
                      </div>
                   </div>
                 ))
              ) : (
                 <div className="h-full flex flex-col items-center justify-center text-slate-400 text-sm italic opacity-70">
                    <Clock size={32} className="mb-2 opacity-50" />
                    <span>No transactions yet</span>
                 </div>
              )}
           </div>
        </div>

      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState, useMemo } from 'react';
import { Holding, Transaction, AssetClass, TransactionType } from '../types';
import { formatNumber } from '../utils';
import { 
  TrendingUp, TrendingDown, Wallet, DollarSign, Plus, Minus, Edit2, 
  PieChart as PieChartIcon, ArrowRight, LayoutGrid, LayoutList, 
  Layers, AlertTriangle, Lightbulb, CheckCircle2, ArrowUpDown, Filter, ChevronDown, ChevronRight
} from 'lucide-react';
import { 
  ResponsiveContainer, PieChart, Pie, Cell, Tooltip 
} from 'recharts';
import { HoldingsSkeleton } from './LoadingSkeletons';

interface HoldingsProps {
  holdings: Holding[];
  transactions: Transaction[];
  cashBalance: number;
  onUpdatePrice: (symbol: string, newPrice: number) => void;
  onUpdateTarget: (symbol: string, target: number) => void;
  onTrade: (symbol: string, type: TransactionType) => void;
  isLoading?: boolean;
  formatMoney: (amount: number) => string;
}

type SortField = 'marketValue' | 'unrealizedPL' | 'unrealizedPLPercent' | 'symbol' | 'weight';
type SortDirection = 'asc' | 'desc';

const COLORS = ['#3b82f6', '#10b981', '#f59e0b', '#ef4444', '#8b5cf6', '#ec4899', '#6366f1', '#14b8a6'];

const Holdings: React.FC<HoldingsProps> = ({ holdings, transactions, cashBalance, onUpdatePrice, onUpdateTarget, onTrade, isLoading, formatMoney }) => {
  // View State
  const [viewMode, setViewMode] = useState<'card' | 'table'>('table');
  const [isGrouped, setIsGrouped] = useState(true); // Group by Asset Class in table
  const [showClosed, setShowClosed] = useState(false);
  const [activeAssetFilter, setActiveAssetFilter] = useState<string>('ALL');

  // Sorting
  const [sortField, setSortField] = useState<SortField>('marketValue');
  const [sortDirection, setSortDirection] = useState<SortDirection>('desc');

  // Editing
  const [editingId, setEditingId] = useState<string | null>(null); // composite key symbol-field
  const [tempValue, setTempValue] = useState<string>('');

  // --- DATA PROCESSING ---

  const { totalMarketValue, totalCost, totalUnrealizedPL, netWorth } = useMemo(() => {
    const mv = holdings.reduce((sum, h) => sum + h.marketValue, 0);
    const cost = holdings.reduce((sum, h) => sum + h.totalCost, 0);
    return { 
        totalMarketValue: mv, 
        totalCost: cost, 
        totalUnrealizedPL: mv - cost,
        netWorth: mv + cashBalance
    };
  }, [holdings, cashBalance]);

  const totalReturnPercent = totalCost > 0 ? (totalUnrealizedPL / totalCost) * 100 : 0;

  // Processed Holdings with Weights & Drift
  const processedHoldings = useMemo(() => {
    let data = holdings;
    if (!showClosed) data = data.filter(h => h.shares > 0.000001);
    if (activeAssetFilter !== 'ALL') data = data.filter(h => h.assetClass === activeAssetFilter);

    return data.map(h => {
        const weight = netWorth > 0 ? (h.marketValue / netWorth) * 100 : 0;
        const target = h.targetAllocation || 0;
        const drift = weight - target;
        const actionValue = (target - weight) / 100 * netWorth; // Positive = Buy, Negative = Sell
        return { ...h, weight, drift, actionValue };
    });
  }, [holdings, showClosed, activeAssetFilter, netWorth]);

  // Grouping Logic for Table
  const groupedHoldings = useMemo(() => {
      if (!isGrouped) return null;
      const groups: Record<string, typeof processedHoldings> = {};

      // Add Cash group first if balance exists
      if (cashBalance > 0) {
          groups['Cash'] = []; // Special handling in render
      }

      processedHoldings.forEach(h => {
          if (!groups[h.assetClass]) groups[h.assetClass] = [];
          groups[h.assetClass].push(h);
      });

      // Sort assets within groups
      Object.keys(groups).forEach(key => {
          groups[key].sort((a, b) => b.marketValue - a.marketValue);
      });

      return groups;
  }, [processedHoldings, isGrouped, cashBalance]);

  // Flat Sorted List for Card/Ungrouped View
  const sortedHoldings = useMemo(() => {
      return [...processedHoldings].sort((a, b) => {
        const valA = a[sortField];
        const valB = b[sortField];
        return sortDirection === 'asc' ? (valA > valB ? 1 : -1) : (valA < valB ? 1 : -1);
      });
  }, [processedHoldings, sortField, sortDirection]);

  // Allocation Data for Chart
  const allocationData = useMemo(() => {
      const groups: Record<string, number> = {};
      holdings.forEach(h => {
          if (h.marketValue > 0) groups[h.assetClass] = (groups[h.assetClass] || 0) + h.marketValue;
      });
      if (cashBalance > 0) groups['Cash'] = cashBalance;

      return Object.entries(groups)
        .map(([name, value]) => ({ name, value }))
        .sort((a, b) => b.value - a.value);
  }, [holdings, cashBalance]);

  // Insights Logic
  const insights = useMemo(() => {
      const msgs = [];
      // 1. Cash Drag
      const cashWeight = (cashBalance / netWorth) * 100;
      if (cashWeight > 25) msgs.push({ type: 'info', text: `High Cash: ${cashWeight.toFixed(0)}% of portfolio is uninvested.` });

      // 2. Rebalancing Needed
      const driftAlert = processedHoldings.find(h => Math.abs(h.drift) > 5);
      if (driftAlert) msgs.push({ type: 'warning', text: `Rebalance Needed: ${driftAlert.symbol} has drifted ${Math.abs(driftAlert.drift).toFixed(1)}% from target.` });

      // 3. Diversification (Simplified)
      if (allocationData.length < 3 && netWorth > 10000) msgs.push({ type: 'tip', text: 'Consider diversifying into more asset classes.' });

      return msgs;
  }, [cashBalance, netWorth, processedHoldings, allocationData]);


  // --- HANDLERS ---

  const startEdit = (id: string, value: number) => {
      setEditingId(id);
      setTempValue(value.toString());
  };

  const commitEdit = (symbol: string, field: 'price' | 'target') => {
      const val = parseFloat(tempValue);
      if (!isNaN(val) && val >= 0) {
          if (field === 'price') onUpdatePrice(symbol, val);
          if (field === 'target') onUpdateTarget(symbol, val);
      }
      setEditingId(null);
  };

  const handleSort = (field: SortField) => {
      if (sortField === field) setSortDirection(prev => prev === 'asc' ? 'desc' : 'asc');
      else { setSortField(field); setSortDirection('desc'); }
  };

  if (isLoading) return <HoldingsSkeleton />;

  // --- RENDER HELPERS ---

  const renderEditableCell = (h: typeof processedHoldings[0], field: 'price' | 'target', suffix: string = '') => {
      const id = `${h.symbol}-${field}`;
      const isEditing = editingId === id;
      const value = field === 'price' ? h.currentPrice : h.targetAllocation;

      if (isEditing) {
          return (
              <input 
                  autoFocus
                  type="number"
                  value={tempValue}
                  onChange={e => setTempValue(e.target.value)}
                  onBlur={() => commitEdit(h.symbol, field)}
                  onKeyDown={e => e.key === 'Enter' && commitEdit(h.symbol, field)}
                  className="w-20 px-2 py-1 text-right text-xs font-bold border-2 border-indigo-500 rounded bg-white dark:bg-slate-900 outline-none"
              />
          );
      }

      return (
          <div 
            onClick={() => startEdit(id, value || 0)}
            className="group/edit flex items-center justify-end gap-1 cursor-pointer hover:text-indigo-500 transition-colors"
          >
              <span className={field === 'target' && !value ? 'text-slate-300' : ''}>
                  {field === 'price' ? formatMoney(value) : (value ? `${value}%` : '-')}
              </span>
              <Edit2 size={10} className="opacity-0 group-hover/edit:opacity-100 transition-opacity" />
          </div>
      );
  };

  const renderActionBadge = (actionValue: number) => {
      if (Math.abs(actionValue) < 10) return <span className="text-emerald-500"><CheckCircle2 size={16} /></span>;
      const type = actionValue > 0 ? 'Buy' : 'Sell';
      return (
          <span className={`text-[10px] font-bold px-2 py-0.5 rounded-full uppercase ${actionValue > 0 ? 'bg-blue-100 text-blue-700 dark:bg-blue-900/30 dark:text-blue-400' : 'bg-rose-100 text-rose-700 dark:bg-rose-900/30 dark:text-rose-400'}`}>
              {type} {formatMoney(Math.abs(actionValue))}
          </span>
      );
  };

  // --- MAIN RENDER ---

  return (
    <div className="space-y-6 animate-fade-in pb-20">

      {/* 1. PORTFOLIO HEADER SUMMARY */}
      <div className="bg-white dark:bg-slate-800 rounded-3xl p-6 border border-slate-200 dark:border-slate-700 shadow-sm flex flex-col md:flex-row justify-between gap-6">
          <div className="flex-1">
              <p className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-1">Total Net Worth</p>
              <div className="flex items-baseline gap-3">
                  <h2 className="text-4xl font-display font-bold text-slate-900 dark:text-white">{formatMoney(netWorth)}</h2>
                  <span className={`text-sm font-bold px-2 py-0.5 rounded-lg ${totalUnrealizedPL >= 0 ? 'bg-emerald-100 text-emerald-700 dark:bg-emerald-900/30 dark:text-emerald-400' : 'bg-rose-100 text-rose-700 dark:bg-rose-900/30 dark:text-rose-400'}`}>
                      {totalUnrealizedPL >= 0 ? '+' : ''}{formatMoney(totalUnrealizedPL)} ({totalReturnPercent.toFixed(2)}%)
                  </span>
              </div>
              <div className="flex gap-4 mt-4">
                  <div className="flex items-center gap-2 text-xs font-medium text-slate-500 dark:text-slate-400">
                      <div className="w-2 h-2 rounded-full bg-blue-500"></div>
                      Assets: <span className="text-slate-900 dark:text-white font-bold">{formatMoney(totalMarketValue)}</span>
                  </div>
                  <div className="flex items-center gap-2 text-xs font-medium text-slate-500 dark:text-slate-400">
                      <div className="w-2 h-2 rounded-full bg-emerald-500"></div>
                      Cash: <span className="text-slate-900 dark:text-white font-bold">{formatMoney(cashBalance)}</span>
                  </div>
              </div>
          </div>

          {/* Right Side: Composition & Insights */}
          <div className="flex-1 flex gap-4 md:border-l border-slate-100 dark:border-slate-800 md:pl-6">
              {/* Mini Pie */}
              <div className="relative w-24 h-24 shrink-0">
                  <ResponsiveContainer width="100%" height="100%">
                      <PieChart>
                          <Pie data={allocationData} innerRadius={25} outerRadius={40} paddingAngle={2} dataKey="value">
                              {allocationData.map((entry, index) => <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />)}
                          </Pie>
                      </PieChart>
                  </ResponsiveContainer>
              </div>

              {/* Insights List */}
              <div className="flex-1 space-y-2">
                  <p className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-2">Portfolio Health</p>
                  {insights.length > 0 ? (
                      insights.slice(0, 2).map((msg, i) => (
                          <div key={i} className="flex items-start gap-2 text-xs text-slate-600 dark:text-slate-300 bg-slate-50 dark:bg-slate-700/30 p-2 rounded-lg">
                              {msg.type === 'warning' ? <AlertTriangle size={14} className="text-amber-500 shrink-0 mt-0.5" /> : <Lightbulb size={14} className="text-blue-500 shrink-0 mt-0.5" />}
                              <span className="leading-tight">{msg.text}</span>
                          </div>
                      ))
                  ) : (
                      <div className="flex items-center gap-2 text-xs text-emerald-600 dark:text-emerald-400 bg-emerald-50 dark:bg-emerald-900/10 p-2 rounded-lg">
                          <CheckCircle2 size={14} />
                          <span>All targets aligned. Good job!</span>
                      </div>
                  )}
              </div>
          </div>
      </div>

      {/* 2. CONTROLS TOOLBAR */}
      <div className="flex flex-col sm:flex-row justify-between items-center gap-4 sticky top-[72px] z-20 bg-slate-50/90 dark:bg-[#0b1120]/90 backdrop-blur-md py-2">
          {/* Filters */}
          <div className="flex items-center gap-2 overflow-x-auto no-scrollbar w-full sm:w-auto">
              <button 
                  onClick={() => setActiveAssetFilter('ALL')} 
                  className={`px-3 py-1.5 rounded-xl text-xs font-bold transition-colors whitespace-nowrap ${activeAssetFilter === 'ALL' ? 'bg-slate-900 text-white dark:bg-white dark:text-slate-900' : 'bg-white dark:bg-slate-800 text-slate-600 dark:text-slate-300 border border-slate-200 dark:border-slate-700'}`}
              >
                  All Assets
              </button>
              {Object.values(AssetClass).filter(a => a !== 'Cash').map(ac => (
                  <button 
                      key={ac} 
                      onClick={() => setActiveAssetFilter(ac)}
                      className={`px-3 py-1.5 rounded-xl text-xs font-bold transition-colors whitespace-nowrap ${activeAssetFilter === ac ? 'bg-slate-900 text-white dark:bg-white dark:text-slate-900' : 'bg-white dark:bg-slate-800 text-slate-600 dark:text-slate-300 border border-slate-200 dark:border-slate-700'}`}
                  >
                      {ac}
                  </button>
              ))}
          </div>

          {/* View Toggles */}
          <div className="flex items-center gap-2 ml-auto">
              <div className="flex bg-white dark:bg-slate-800 p-1 rounded-xl border border-slate-200 dark:border-slate-700">
                  <button onClick={() => setViewMode('table')} className={`p-1.5 rounded-lg transition-all ${viewMode === 'table' ? 'bg-slate-100 dark:bg-slate-700 text-indigo-600 dark:text-white shadow-sm' : 'text-slate-400'}`}>
                      <LayoutList size={16} />
                  </button>
                  <button onClick={() => setViewMode('card')} className={`p-1.5 rounded-lg transition-all ${viewMode === 'card' ? 'bg-slate-100 dark:bg-slate-700 text-indigo-600 dark:text-white shadow-sm' : 'text-slate-400'}`}>
                      <LayoutGrid size={16} />
                  </button>
              </div>

              {viewMode === 'table' && (
                  <button 
                    onClick={() => setIsGrouped(!isGrouped)}
                    className={`flex items-center gap-1.5 px-3 py-2 rounded-xl text-xs font-bold border transition-colors ${isGrouped ? 'bg-indigo-50 border-indigo-200 text-indigo-600 dark:bg-indigo-900/20 dark:border-indigo-800 dark:text-indigo-400' : 'bg-white dark:bg-slate-800 border-slate-200 dark:border-slate-700 text-slate-500'}`}
                  >
                      <Layers size={14} /> Grouped
                  </button>
              )}
          </div>
      </div>

      {/* 3. HOLDINGS CONTENT */}
      {viewMode === 'card' ? (
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-4 animate-slide-up">
              {sortedHoldings.map(h => (
                  <div key={h.symbol} className="bg-white dark:bg-slate-800 p-5 rounded-2xl border border-slate-200 dark:border-slate-700 shadow-sm hover:shadow-md transition-shadow relative group">
                      <div className="flex justify-between items-start mb-3">
                          <div>
                              <div className="flex items-center gap-2">
                                  <h3 className="font-bold text-slate-900 dark:text-white">{h.symbol}</h3>
                                  <span className="text-[10px] font-bold px-1.5 py-0.5 bg-slate-100 dark:bg-slate-700 text-slate-500 rounded uppercase">{h.assetClass}</span>
                              </div>
                              <p className="text-xs text-slate-500">{h.name}</p>
                          </div>
                          <div className={`w-8 h-8 rounded-lg flex items-center justify-center text-xs font-bold ${h.unrealizedPL >= 0 ? 'bg-emerald-50 text-emerald-600 dark:bg-emerald-900/20' : 'bg-rose-50 text-rose-600 dark:bg-rose-900/20'}`}>
                              {h.unrealizedPL >= 0 ? <TrendingUp size={14} /> : <TrendingDown size={14} />}
                          </div>
                      </div>

                      <div className="space-y-2 mb-4">
                          <div className="flex justify-between items-end">
                              <span className="text-xs text-slate-400 font-medium">Value</span>
                              <span className="text-lg font-bold font-mono text-slate-900 dark:text-white">{formatMoney(h.marketValue)}</span>
                          </div>
                          <div className="flex justify-between items-end">
                              <span className="text-xs text-slate-400 font-medium">Return</span>
                              <span className={`text-sm font-bold ${h.unrealizedPLPercent >= 0 ? 'text-emerald-500' : 'text-rose-500'}`}>
                                  {h.unrealizedPLPercent >= 0 ? '+' : ''}{h.unrealizedPLPercent.toFixed(2)}%
                              </span>
                          </div>
                      </div>

                      <div className="pt-3 border-t border-slate-100 dark:border-slate-700 flex gap-2">
                          <button onClick={() => onTrade(h.symbol, TransactionType.BUY)} className="flex-1 py-1.5 rounded-lg bg-emerald-50 dark:bg-emerald-900/20 text-emerald-600 text-xs font-bold hover:bg-emerald-100 transition-colors">Buy</button>
                          <button onClick={() => onTrade(h.symbol, TransactionType.SELL)} className="flex-1 py-1.5 rounded-lg bg-rose-50 dark:bg-rose-900/20 text-rose-600 text-xs font-bold hover:bg-rose-100 transition-colors">Sell</button>
                      </div>
                  </div>
              ))}
          </div>
      ) : (
          <div className="bg-white dark:bg-slate-800 rounded-2xl border border-slate-200 dark:border-slate-700 shadow-sm overflow-hidden animate-slide-up">
              <div className="overflow-x-auto custom-scrollbar">
                  <table className="w-full text-left text-sm">
                      <thead className="bg-slate-50 dark:bg-slate-900/50 text-slate-500 dark:text-slate-400 font-bold uppercase text-[10px] tracking-wider">
                          <tr>
                              <th className="px-6 py-4">Asset</th>
                              {!isGrouped && <th className="px-4 py-4">Class</th>}
                              <th className="px-4 py-4 text-right">Price</th>
                              <th className="px-4 py-4 text-right">Shares</th>
                              <th className="px-4 py-4 text-right cursor-pointer hover:text-indigo-500" onClick={() => handleSort('marketValue')}>
                                  <div className="flex items-center justify-end gap-1">Value <ArrowUpDown size={10} /></div>
                              </th>
                              <th className="px-4 py-4 w-24 text-center">Weight</th>
                              <th className="px-4 py-4 text-right cursor-pointer hover:text-indigo-500" onClick={() => handleSort('unrealizedPLPercent')}>
                                  <div className="flex items-center justify-end gap-1">Return <ArrowUpDown size={10} /></div>
                              </th>
                              <th className="px-4 py-4 text-right">Target</th>
                              <th className="px-4 py-4 text-right">Action</th>
                              <th className="px-4 py-4 text-center">Trade</th>
                          </tr>
                      </thead>
                      <tbody className="divide-y divide-slate-100 dark:divide-slate-800">
                          {isGrouped && groupedHoldings ? (
                              Object.entries(groupedHoldings).map(([group, items]) => (
                                  <React.Fragment key={group}>
                                      {/* Group Header */}
                                      <tr className="bg-slate-50/80 dark:bg-slate-800/80">
                                          <td colSpan={10} className="px-4 py-2">
                                              <div className="flex items-center gap-2">
                                                  <span className="px-2 py-1 rounded bg-slate-200 dark:bg-slate-700 text-xs font-bold uppercase text-slate-600 dark:text-slate-300">{group}</span>
                                                  <span className="text-xs font-medium text-slate-400">{items.length} assets</span>
                                                  {group === 'Cash' && cashBalance > 0 && (
                                                       <span className="ml-auto text-xs font-bold text-slate-900 dark:text-white font-mono">{formatMoney(cashBalance)}</span>
                                                  )}
                                              </div>
                                          </td>
                                      </tr>
                                      {/* Cash Row Special Case */}
                                      {group === 'Cash' && cashBalance > 0 && (
                                          <tr className="hover:bg-slate-50 dark:hover:bg-slate-700/20">
                                              <td className="px-6 py-4 font-bold text-slate-900 dark:text-white">Wallet (Available Cash)</td>
                                              <td className="px-4 py-4 text-right opacity-50">-</td>
                                              <td className="px-4 py-4 text-right opacity-50">-</td>
                                              <td className="px-4 py-4 text-right font-mono font-bold text-slate-900 dark:text-white">{formatMoney(cashBalance)}</td>
                                              <td className="px-4 py-4 text-center">
                                                  <div className="text-xs font-bold text-slate-500">{((cashBalance/netWorth)*100).toFixed(1)}%</div>
                                                  <div className="w-full h-1 bg-slate-100 rounded-full mt-1 overflow-hidden"><div className="h-full bg-emerald-400" style={{ width: `${(cashBalance/netWorth)*100}%` }}></div></div>
                                              </td>
