                                                  {renderEditableCell(h, 'price')}
                                              </td>
                                              <td className="px-4 py-4 text-right text-xs text-slate-500">{formatNumber(h.shares)}</td>
                                              <td className="px-4 py-4 text-right font-mono font-bold text-slate-900 dark:text-white">{formatMoney(h.marketValue)}</td>
                                              <td className="px-4 py-4">
                                                  <div className="flex flex-col items-center">
                                                      <span className="text-xs font-bold text-slate-600 dark:text-slate-400">{h.weight.toFixed(1)}%</span>
                                                      <div className="w-16 h-1.5 bg-slate-100 dark:bg-slate-700 rounded-full mt-1 overflow-hidden">
                                                          <div className="h-full bg-blue-500" style={{ width: `${Math.min(h.weight, 100)}%` }}></div>
                                                      </div>
                                                  </div>
                                              </td>
                                              <td className="px-4 py-4 text-right">
                                                  <div className={`text-xs font-bold ${h.unrealizedPLPercent >= 0 ? 'text-emerald-600 dark:text-emerald-400' : 'text-rose-600 dark:text-rose-400'}`}>
                                                      {h.unrealizedPLPercent >= 0 ? '+' : ''}{h.unrealizedPLPercent.toFixed(2)}%
                                                  </div>
                                                  <div className="text-[10px] text-slate-400">{formatMoney(h.unrealizedPL)}</div>
                                              </td>
                                              <td className="px-4 py-4 text-right font-mono text-sm text-slate-700 dark:text-slate-300">
                                                  {renderEditableCell(h, 'target')}
                                              </td>
                                              <td className="px-4 py-4 text-right">
                                                  {renderActionBadge(h.actionValue)}
                                              </td>
                                              <td className="px-4 py-4">
                                                  <div className="flex justify-center gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                                                      <button onClick={() => onTrade(h.symbol, TransactionType.BUY)} className="p-1.5 hover:bg-emerald-50 text-emerald-600 rounded"><Plus size={14} /></button>
                                                      <button onClick={() => onTrade(h.symbol, TransactionType.SELL)} className="p-1.5 hover:bg-rose-50 text-rose-600 rounded"><Minus size={14} /></button>
                                                  </div>
                                              </td>
                                          </tr>
                                      ))}
                                  </React.Fragment>
                              ))
                          ) : (
                              /* Ungrouped (Flat List) Rows */
                              sortedHoldings.map(h => (
                                  <tr key={h.symbol} className="hover:bg-slate-50 dark:hover:bg-slate-700/20 transition-colors group">
                                      <td className="px-6 py-4">
                                          <div className="flex items-center gap-3">
                                              <div className="w-8 h-8 rounded-lg bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 flex items-center justify-center text-[10px] font-bold shadow-sm">
                                                  {h.symbol.substring(0,2)}
                                              </div>
                                              <div>
                                                  <div className="font-bold text-slate-900 dark:text-white text-sm">{h.symbol}</div>
                                                  <div className="text-xs text-slate-500 truncate max-w-[120px]">{h.name}</div>
                                              </div>
                                          </div>
                                      </td>
                                      <td className="px-4 py-4"><span className="px-2 py-0.5 bg-slate-100 dark:bg-slate-700 text-[10px] font-bold uppercase rounded text-slate-500">{h.assetClass}</span></td>
                                      <td className="px-4 py-4 text-right font-mono text-sm text-slate-700 dark:text-slate-300">
                                          {renderEditableCell(h, 'price')}
                                      </td>
                                      <td className="px-4 py-4 text-right text-xs text-slate-500">{formatNumber(h.shares)}</td>
                                      <td className="px-4 py-4 text-right font-mono font-bold text-slate-900 dark:text-white">{formatMoney(h.marketValue)}</td>
                                      <td className="px-4 py-4 text-center">
                                          <div className="flex flex-col items-center">
                                              <span className="text-xs font-bold text-slate-600 dark:text-slate-400">{h.weight.toFixed(1)}%</span>
                                              <div className="w-16 h-1.5 bg-slate-100 dark:bg-slate-700 rounded-full mt-1 overflow-hidden">
                                                  <div className="h-full bg-blue-500" style={{ width: `${Math.min(h.weight, 100)}%` }}></div>
                                              </div>
                                          </div>
                                      </td>
                                      <td className="px-4 py-4 text-right">
                                          <div className={`text-xs font-bold ${h.unrealizedPLPercent >= 0 ? 'text-emerald-600 dark:text-emerald-400' : 'text-rose-600 dark:text-rose-400'}`}>
                                              {h.unrealizedPLPercent >= 0 ? '+' : ''}{h.unrealizedPLPercent.toFixed(2)}%
                                          </div>
                                      </td>
                                      <td className="px-4 py-4 text-right font-mono text-sm text-slate-700 dark:text-slate-300">
                                          {renderEditableCell(h, 'target')}
                                      </td>
                                      <td className="px-4 py-4 text-right">
                                          {renderActionBadge(h.actionValue)}
                                      </td>
                                      <td className="px-4 py-4">
                                          <div className="flex justify-center gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                                              <button onClick={() => onTrade(h.symbol, TransactionType.BUY)} className="p-1.5 hover:bg-emerald-50 text-emerald-600 rounded"><Plus size={14} /></button>
                                              <button onClick={() => onTrade(h.symbol, TransactionType.SELL)} className="p-1.5 hover:bg-rose-50 text-rose-600 rounded"><Minus size={14} /></button>
                                          </div>
                                      </td>
                                  </tr>
                              ))
                          )}
                      </tbody>
                  </table>
              </div>
          </div>
      )}
    </div>
  );
};

export default Holdings;

import React, { useState, useMemo } from 'react';
import { Holding, Transaction, AssetClass, TransactionType } from '../types';
import { formatNumber } from '../utils';
import { 
  TrendingUp, TrendingDown, Wallet, DollarSign, Plus, Minus, Edit2, 
  PieChart as PieChartIcon, ArrowRight, LayoutGrid, LayoutList, 
  Layers, AlertTriangle, Lightbulb, CheckCircle2, ArrowUpDown, Filter, ChevronDown, ChevronRight, MoreHorizontal, Target
} from 'lucide-react';
import { 
  ResponsiveContainer, PieChart, Pie, Cell, Tooltip, Legend 
} from 'recharts';
import { HoldingsSkeleton } from './LoadingSkeletons';

interface HoldingsProps {
  holdings: Holding[];
  transactions: Transaction[];
  cashBalance: number;
  onUpdatePrice: (symbol: string, newPrice: number) => void;
  onUpdateTarget: (symbol: string, target: number) => void;
  onTrade: (symbol: string, type: TransactionType) => void;
  isLoading?: boolean;
  formatMoney: (amount: number) => string;
}

type SortField = 'marketValue' | 'unrealizedPL' | 'unrealizedPLPercent' | 'symbol' | 'weight' | 'name';
type SortDirection = 'asc' | 'desc';

const COLORS = ['#3b82f6', '#10b981', '#f59e0b', '#ef4444', '#8b5cf6', '#ec4899', '#6366f1', '#14b8a6'];

const Holdings: React.FC<HoldingsProps> = ({ holdings, transactions, cashBalance, onUpdatePrice, onUpdateTarget, onTrade, isLoading, formatMoney }) => {
  // View State
  const [viewMode, setViewMode] = useState<'card' | 'table'>('table');
  const [isGrouped, setIsGrouped] = useState(true); 
  const [searchTerm, setSearchTerm] = useState('');

  // Sorting
  const [sortField, setSortField] = useState<SortField>('marketValue');
  const [sortDirection, setSortDirection] = useState<SortDirection>('desc');

  // Editing
  const [editingId, setEditingId] = useState<string | null>(null); 
  const [tempValue, setTempValue] = useState<string>('');

  // --- DATA PROCESSING ---

  const { totalMarketValue, totalCost, totalUnrealizedPL, netWorth } = useMemo(() => {
    const mv = holdings.reduce((sum, h) => sum + h.marketValue, 0);
    const cost = holdings.reduce((sum, h) => sum + h.totalCost, 0);
    return { 
        totalMarketValue: mv, 
        totalCost: cost, 
        totalUnrealizedPL: mv - cost,
        netWorth: mv + cashBalance
    };
  }, [holdings, cashBalance]);

  const totalReturnPercent = totalCost > 0 ? (totalUnrealizedPL / totalCost) * 100 : 0;

  // Processed Holdings
  const processedHoldings = useMemo(() => {
    let data = holdings.filter(h => h.shares > 0.000001); // Filter closed positions

    // Search Filter
    if (searchTerm) {
        const lower = searchTerm.toLowerCase();
        data = data.filter(h => h.symbol.toLowerCase().includes(lower) || h.name.toLowerCase().includes(lower));
    }

    return data.map(h => {
        const weight = netWorth > 0 ? (h.marketValue / netWorth) * 100 : 0;
        const target = h.targetAllocation || 0;
        const drift = weight - target;
        // Calculate rebalance amount: if target is 10% and current is 12%, we need to sell 2%
        // Target Value = NetWorth * (Target% / 100)
        // Current Value = h.marketValue
        // Action = Target Value - Current Value
        const actionValue = (netWorth * (target / 100)) - h.marketValue;
        return { ...h, weight, drift, actionValue };
    });
  }, [holdings, searchTerm, netWorth]);

  // Grouping Logic
  const groupedHoldings = useMemo(() => {
      if (!isGrouped) return null;
      const groups: Record<string, typeof processedHoldings> = {};

      // Sort keys to make sure they appear in a consistent order if needed, or predefined order
      const assetOrder = Object.values(AssetClass);

      processedHoldings.forEach(h => {
          if (!groups[h.assetClass]) groups[h.assetClass] = [];
          groups[h.assetClass].push(h);
      });

      // Sort assets within groups
      Object.keys(groups).forEach(key => {
          groups[key].sort((a, b) => {
             const valA = a[sortField];
             const valB = b[sortField];
             // Handle string sorting for symbol/name
             if (typeof valA === 'string' && typeof valB === 'string') {
                 return sortDirection === 'asc' ? valA.localeCompare(valB) : valB.localeCompare(valA);
             }
             // Numeric sorting
             return sortDirection === 'asc' ? (valA as number) - (valB as number) : (valB as number) - (valA as number);
          });
      });

      return groups;
  }, [processedHoldings, isGrouped, sortField, sortDirection]);

  // Flat Sorted List
  const sortedHoldings = useMemo(() => {
      return [...processedHoldings].sort((a, b) => {
        const valA = a[sortField];
        const valB = b[sortField];
        if (typeof valA === 'string' && typeof valB === 'string') {
             return sortDirection === 'asc' ? valA.localeCompare(valB) : valB.localeCompare(valA);
        }
        return sortDirection === 'asc' ? (valA as number) - (valB as number) : (valB as number) - (valA as number);
      });
  }, [processedHoldings, sortField, sortDirection]);

  // Allocation Chart Data
  const allocationData = useMemo(() => {
      const groups: Record<string, number> = {};
      holdings.forEach(h => {
          if (h.marketValue > 0) groups[h.assetClass] = (groups[h.assetClass] || 0) + h.marketValue;
      });
      if (cashBalance > 0) groups['Cash'] = cashBalance;

      return Object.entries(groups)
        .map(([name, value]) => ({ name, value }))
        .sort((a, b) => b.value - a.value);
  }, [holdings, cashBalance]);


  // --- HANDLERS ---

  const startEdit = (id: string, value: number, e: React.MouseEvent) => {
      e.stopPropagation();
      setEditingId(id);
      setTempValue(value.toString());
  };

  const commitEdit = (symbol: string, field: 'price' | 'target') => {
      const val = parseFloat(tempValue);
      if (!isNaN(val) && val >= 0) {
          if (field === 'price') onUpdatePrice(symbol, val);
          if (field === 'target') onUpdateTarget(symbol, val);
      }
      setEditingId(null);
  };

  const handleSort = (field: SortField) => {
      if (sortField === field) setSortDirection(prev => prev === 'asc' ? 'desc' : 'asc');
      else { setSortField(field); setSortDirection('desc'); }
  };

  if (isLoading) return <HoldingsSkeleton />;

  // --- RENDER HELPERS ---

  const renderEditableCell = (h: typeof processedHoldings[0], field: 'price' | 'target') => {
      const id = `${h.symbol}-${field}`;
      const isEditing = editingId === id;
      const value = field === 'price' ? h.currentPrice : h.targetAllocation;

      if (isEditing) {
          return (
              <input 
                  autoFocus
                  type="number"
                  value={tempValue}
                  onChange={e => setTempValue(e.target.value)}
                  onBlur={() => commitEdit(h.symbol, field)}
                  onKeyDown={e => e.key === 'Enter' && commitEdit(h.symbol, field)}
                  onClick={e => e.stopPropagation()}
                  className="w-20 px-2 py-1 text-right text-sm border-2 border-blue-500 rounded bg-white dark:bg-slate-900 outline-none shadow-sm"
              />
          );
      }

      return (
          <div 
            onClick={(e) => startEdit(id, value || 0, e)}
            className={`group/edit flex items-center justify-end gap-1 cursor-pointer py-1 px-2 rounded hover:bg-slate-100 dark:hover:bg-slate-800 transition-all ${field === 'target' && !value ? 'text-slate-300' : ''}`}
          >
              <span className="font-mono">
                  {field === 'price' ? formatMoney(value) : (value ? `${value}%` : '-')}
              </span>
              <Edit2 size={10} className="opacity-0 group-hover/edit:opacity-100 text-slate-400 transition-opacity" />
          </div>
      );
  };

  const renderSortIcon = (field: SortField) => {
      if (sortField !== field) return <ArrowUpDown size={12} className="text-slate-300 opacity-0 group-hover:opacity-50 transition-opacity" />;
      return sortDirection === 'asc' ? <ArrowUpDown size={12} className="text-blue-500 rotate-180" /> : <ArrowUpDown size={12} className="text-blue-500" />;
  };

  return (
    <div className="space-y-8 animate-fade-in pb-20">

      {/* 1. METRICS HEADER */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
          <div className="bg-white dark:bg-slate-800 p-6 rounded-3xl border border-slate-200 dark:border-slate-700 shadow-sm relative overflow-hidden group">
              <div className="relative z-10">
                  <p className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-2">Net Worth</p>
                  <h2 className="text-4xl font-display font-bold text-slate-900 dark:text-white">{formatMoney(netWorth)}</h2>
              </div>
              <div className="absolute right-6 top-6 p-3 bg-blue-50 dark:bg-blue-900/20 text-blue-600 dark:text-blue-400 rounded-2xl">
                  <Wallet size={24} />
              </div>
          </div>

          <div className="bg-white dark:bg-slate-800 p-6 rounded-3xl border border-slate-200 dark:border-slate-700 shadow-sm relative overflow-hidden group">
              <div className="relative z-10">
                  <p className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-2">Total Return</p>
                  <div className="flex items-baseline gap-2">
                      <h2 className={`text-4xl font-display font-bold ${totalUnrealizedPL >= 0 ? 'text-emerald-500' : 'text-rose-500'}`}>
                          {totalUnrealizedPL >= 0 ? '+' : ''}{formatMoney(totalUnrealizedPL)}
                      </h2>
                  </div>
                  <p className={`text-sm font-bold mt-1 ${totalUnrealizedPL >= 0 ? 'text-emerald-600 dark:text-emerald-400' : 'text-rose-600 dark:text-rose-400'}`}>
                      {totalReturnPercent.toFixed(2)}% All Time
                  </p>
              </div>
              <div className={`absolute right-6 top-6 p-3 rounded-2xl ${totalUnrealizedPL >= 0 ? 'bg-emerald-50 dark:bg-emerald-900/20 text-emerald-600 dark:text-emerald-400' : 'bg-rose-50 dark:bg-rose-900/20 text-rose-600 dark:text-rose-400'}`}>
                  {totalUnrealizedPL >= 0 ? <TrendingUp size={24} /> : <TrendingDown size={24} />}
              </div>
          </div>

          <div className="bg-white dark:bg-slate-800 p-6 rounded-3xl border border-slate-200 dark:border-slate-700 shadow-sm flex flex-col justify-between">
              <div className="flex justify-between items-center mb-4">
                  <p className="text-xs font-bold text-slate-400 uppercase tracking-wider">Asset Allocation</p>
                  <span className="text-xs font-bold text-slate-500">{allocationData.length} Classes</span>
              </div>
              {/* Mini Bar Chart for Allocation */}
              <div className="space-y-3">
                  {allocationData.slice(0, 3).map((item, idx) => (
                      <div key={item.name} className="flex items-center gap-3 text-sm">
                          <div className="w-2 h-2 rounded-full" style={{ backgroundColor: COLORS[idx % COLORS.length] }}></div>
                          <span className="flex-1 font-medium text-slate-700 dark:text-slate-300">{item.name}</span>
                          <span className="font-bold text-slate-900 dark:text-white">{((item.value / netWorth) * 100).toFixed(1)}%</span>
                          <div className="w-16 h-1.5 bg-slate-100 dark:bg-slate-700 rounded-full overflow-hidden">
                              <div className="h-full rounded-full" style={{ width: `${(item.value / netWorth) * 100}%`, backgroundColor: COLORS[idx % COLORS.length] }}></div>
                          </div>
                      </div>
                  ))}
              </div>
          </div>
      </div>

      {/* 2. MAIN CONTENT AREA */}
      <div className="bg-white dark:bg-slate-800 rounded-3xl border border-slate-200 dark:border-slate-700 shadow-sm overflow-hidden flex flex-col min-h-[500px]">

          {/* Toolbar */}
          <div className="p-5 border-b border-slate-100 dark:border-slate-800 flex flex-col sm:flex-row justify-between items-center gap-4 bg-slate-50/50 dark:bg-slate-900/30">
              <div className="flex items-center gap-2 w-full sm:w-auto">
                  <h3 className="text-lg font-bold text-slate-900 dark:text-white mr-4">Assets</h3>
                  <div className="relative flex-1 sm:flex-none">
                      <input 
                          type="text" 
                          placeholder="Filter assets..." 
                          value={searchTerm}
                          onChange={(e) => setSearchTerm(e.target.value)}
                          className="pl-3 pr-4 py-2 w-full sm:w-64 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl text-sm font-medium focus:ring-2 focus:ring-blue-500 outline-none transition-all"
                      />
                  </div>
              </div>

              <div className="flex bg-white dark:bg-slate-800 p-1 rounded-xl border border-slate-200 dark:border-slate-700">
                  <button onClick={() => setViewMode('table')} className={`p-2 rounded-lg transition-all ${viewMode === 'table' ? 'bg-slate-100 dark:bg-slate-700 text-blue-600 dark:text-white shadow-sm' : 'text-slate-400'}`}>
                      <LayoutList size={18} />
                  </button>
                  <button onClick={() => setViewMode('card')} className={`p-2 rounded-lg transition-all ${viewMode === 'card' ? 'bg-slate-100 dark:bg-slate-700 text-blue-600 dark:text-white shadow-sm' : 'text-slate-400'}`}>
                      <LayoutGrid size={18} />
                  </button>
              </div>
          </div>

          {/* Table View */}
          {viewMode === 'table' && (
              <div className="overflow-x-auto custom-scrollbar flex-1">
                  <table className="w-full text-sm text-left">
                      <thead className="bg-slate-50 dark:bg-[#151e2e] text-slate-500 dark:text-slate-400 font-bold uppercase text-[10px] tracking-wider border-b border-slate-200 dark:border-slate-700">
                          <tr>
                              <th className="px-6 py-4 cursor-pointer hover:text-slate-700 dark:hover:text-slate-200 group" onClick={() => handleSort('symbol')}>
                                  <div className="flex items-center gap-1">Asset {renderSortIcon('symbol')}</div>
                              </th>
                              <th className="px-4 py-4 text-right cursor-pointer hover:text-slate-700 dark:hover:text-slate-200 group" onClick={() => handleSort('marketValue')}>
                                  <div className="flex items-center justify-end gap-1">Market Value {renderSortIcon('marketValue')}</div>
                              </th>
                              <th className="px-4 py-4 text-right">Price</th>
                              <th className="px-4 py-4 text-right">Holdings</th>
                              <th className="px-4 py-4 text-right cursor-pointer hover:text-slate-700 dark:hover:text-slate-200 group" onClick={() => handleSort('unrealizedPLPercent')}>
                                  <div className="flex items-center justify-end gap-1">Return {renderSortIcon('unrealizedPLPercent')}</div>
                              </th>
                              <th className="px-4 py-4 text-center w-32 cursor-pointer hover:text-slate-700 dark:hover:text-slate-200 group" onClick={() => handleSort('weight')}>
                                  <div className="flex items-center justify-center gap-1">Alloc {renderSortIcon('weight')}</div>
                              </th>
                              <th className="px-4 py-4 text-right">Target</th>
                              <th className="px-4 py-4 text-right">Action</th>
                              <th className="px-6 py-4 text-center">Trade</th>
                          </tr>
                      </thead>
                      <tbody className="divide-y divide-slate-100 dark:divide-slate-800">
                          {/* Cash Row (Always Top if exists) */}
                          {cashBalance > 0 && (
                              <tr className="bg-emerald-50/30 dark:bg-emerald-900/5 hover:bg-emerald-50/50 dark:hover:bg-emerald-900/10 transition-colors">
                                  <td className="px-6 py-4">
                                      <div className="flex items-center gap-3">
                                          <div className="w-9 h-9 rounded-xl bg-emerald-100 dark:bg-emerald-900/30 text-emerald-600 dark:text-emerald-400 flex items-center justify-center">
                                              <DollarSign size={18} />
                                          </div>
                                          <div>
                                              <div className="font-bold text-slate-900 dark:text-white">Cash</div>
                                              <div className="text-xs text-slate-500">Available Balance</div>
                                          </div>
                                      </div>
                                  </td>
                                  <td className="px-4 py-4 text-right font-bold font-mono text-slate-900 dark:text-white">{formatMoney(cashBalance)}</td>
                                  <td className="px-4 py-4 text-right opacity-40">-</td>
                                  <td className="px-4 py-4 text-right opacity-40">-</td>
                                  <td className="px-4 py-4 text-right opacity-40">-</td>
                                  <td className="px-4 py-4 text-center">
                                      <div className="inline-flex flex-col items-center w-full">
                                          <span className="text-xs font-bold text-slate-600 dark:text-slate-400">{((cashBalance/netWorth)*100).toFixed(1)}%</span>
                                          <div className="w-16 h-1.5 bg-slate-200 dark:bg-slate-700 rounded-full mt-1 overflow-hidden">
                                              <div className="h-full bg-emerald-500" style={{ width: `${(cashBalance/netWorth)*100}%` }}></div>
                                          </div>
                                      </div>
                                  </td>
                                  <td className="px-4 py-4 text-right opacity-40">-</td>
                                  <td className="px-4 py-4 text-right opacity-40">-</td>
                                  <td className="px-6 py-4 text-center">
                                      <button onClick={() => onTrade('CASH', TransactionType.DEPOSIT)} className="p-1.5 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg hover:border-emerald-500 hover:text-emerald-500 transition-colors">
                                          <Plus size={14} />
                                      </button>
                                  </td>
                              </tr>
                          )}

                          {isGrouped && groupedHoldings ? (
                              Object.entries(groupedHoldings).map(([group, items]) => (
                                  <React.Fragment key={group}>
                                      <tr className="bg-slate-50 dark:bg-slate-900 border-y border-slate-100 dark:border-slate-800">
                                          <td colSpan={9} className="px-6 py-2 text-xs font-bold text-slate-500 uppercase tracking-wider flex items-center gap-2">
                                              <div className="w-1.5 h-1.5 rounded-full bg-slate-400"></div> {group} ({items.length})
                                          </td>
                                      </tr>
                                      {items.map(h => (
                                          <tr key={h.symbol} className="hover:bg-slate-50 dark:hover:bg-slate-800/50 transition-colors group">
                                              <td className="px-6 py-4">
                                                  <div className="flex items-center gap-3">
                                                      <div className="w-9 h-9 rounded-xl bg-slate-100 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 flex items-center justify-center font-bold text-xs shadow-sm text-slate-600 dark:text-slate-300">
                                                          {h.symbol.substring(0,2)}
                                                      </div>
                                                      <div>
                                                          <div className="font-bold text-slate-900 dark:text-white text-sm">{h.symbol}</div>
                                                          <div className="text-xs text-slate-500 truncate max-w-[120px]">{h.name}</div>
                                                      </div>
                                                  </div>
                                              </td>
                                              <td className="px-4 py-4 text-right font-bold font-mono text-slate-900 dark:text-white">
                                                  {formatMoney(h.marketValue)}
                                              </td>
                                              <td className="px-4 py-4 text-right">
                                                  {renderEditableCell(h, 'price')}
                                              </td>
                                              <td className="px-4 py-4 text-right">
                                                  <div className="text-sm font-medium text-slate-700 dark:text-slate-300">{formatNumber(h.shares)}</div>
                                                  <div className="text-[10px] text-slate-400">Avg: {formatMoney(h.avgCost)}</div>
                                              </td>
                                              <td className="px-4 py-4 text-right">
                                                  <div className={`text-sm font-bold ${h.unrealizedPLPercent >= 0 ? 'text-emerald-600 dark:text-emerald-400' : 'text-rose-600 dark:text-rose-400'}`}>
                                                      {h.unrealizedPLPercent >= 0 ? '+' : ''}{h.unrealizedPLPercent.toFixed(2)}%
                                                  </div>
                                                  <div className="text-[10px] text-slate-400">{formatMoney(h.unrealizedPL)}</div>
                                              </td>
                                              <td className="px-4 py-4 text-center">
                                                  <div className="inline-flex flex-col items-center w-full">
                                                      <span className="text-xs font-bold text-slate-600 dark:text-slate-400">{h.weight.toFixed(1)}%</span>
                                                      <div className="w-16 h-1.5 bg-slate-100 dark:bg-slate-700 rounded-full mt-1 overflow-hidden">
                                                          <div className="h-full bg-blue-500" style={{ width: `${Math.min(h.weight, 100)}%` }}></div>
                                                      </div>
                                                  </div>
                                              </td>
                                              <td className="px-4 py-4 text-right">
                                                  {renderEditableCell(h, 'target')}
                                              </td>
                                              <td className="px-4 py-4 text-right">
                                                  {Math.abs(h.actionValue) > (netWorth * 0.005) ? ( // Only show if action > 0.5% of portfolio
                                                      <span className={`text-[10px] font-bold px-2 py-1 rounded-md uppercase ${h.actionValue > 0 ? 'bg-blue-50 text-blue-600 dark:bg-blue-900/20 dark:text-blue-400' : 'bg-amber-50 text-amber-600 dark:bg-amber-900/20 dark:text-amber-400'}`}>
                                                          {h.actionValue > 0 ? 'Buy' : 'Sell'} {formatMoney(Math.abs(h.actionValue))}
                                                      </span>
                                                  ) : (
                                                      <span className="text-xs text-slate-300 dark:text-slate-600">-</span>
                                                  )}
                                              </td>
                                              <td className="px-6 py-4 text-center">
                                                  <div className="flex justify-center gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
                                                      <button onClick={() => onTrade(h.symbol, TransactionType.BUY)} className="p-1.5 rounded-lg bg-emerald-50 dark:bg-emerald-900/20 text-emerald-600 hover:bg-emerald-100 transition-colors" title="Buy More">
                                                          <Plus size={14} />
                                                      </button>
                                                      <button onClick={() => onTrade(h.symbol, TransactionType.SELL)} className="p-1.5 rounded-lg bg-rose-50 dark:bg-rose-900/20 text-rose-600 hover:bg-rose-100 transition-colors" title="Sell">
                                                          <Minus size={14} />
                                                      </button>
                                                  </div>
                                              </td>
                                          </tr>
                                      ))}
                                  </React.Fragment>
                              ))
                          ) : (
                              // Flat List
                              sortedHoldings.map(h => (
                                  <tr key={h.symbol} className="hover:bg-slate-50 dark:hover:bg-slate-800/50 transition-colors group">
                                      <td className="px-6 py-4">
                                          <div className="flex items-center gap-3">
                                              <div className="w-9 h-9 rounded-xl bg-slate-100 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 flex items-center justify-center font-bold text-xs shadow-sm text-slate-600 dark:text-slate-300">
                                                  {h.symbol.substring(0,2)}
                                              </div>
                                              <div>
                                                  <div className="font-bold text-slate-900 dark:text-white text-sm">{h.symbol}</div>
                                                  <div className="flex items-center gap-2">
                                                      <span className="text-xs text-slate-500">{h.name}</span>
                                                      <span className="text-[9px] font-bold uppercase px-1.5 py-0.5 bg-slate-100 dark:bg-slate-700 text-slate-500 rounded">{h.assetClass}</span>
                                                  </div>
                                              </div>
                                          </div>
                                      </td>
                                      <td className="px-4 py-4 text-right font-bold font-mono text-slate-900 dark:text-white">
                                          {formatMoney(h.marketValue)}
                                      </td>
                                      <td className="px-4 py-4 text-right">
                                          {renderEditableCell(h, 'price')}
                                      </td>
                                      <td className="px-4 py-4 text-right">
                                          <div className="text-sm font-medium text-slate-700 dark:text-slate-300">{formatNumber(h.shares)}</div>
                                          <div className="text-[10px] text-slate-400">Avg: {formatMoney(h.avgCost)}</div>
                                      </td>
                                      <td className="px-4 py-4 text-right">
                                          <div className={`text-sm font-bold ${h.unrealizedPLPercent >= 0 ? 'text-emerald-600 dark:text-emerald-400' : 'text-rose-600 dark:text-rose-400'}`}>
                                              {h.unrealizedPLPercent >= 0 ? '+' : ''}{h.unrealizedPLPercent.toFixed(2)}%
                                          </div>
                                          <div className="text-[10px] text-slate-400">{formatMoney(h.unrealizedPL)}</div>
                                      </td>
                                      <td className="px-4 py-4 text-center">
                                          <div className="inline-flex flex-col items-center w-full">
                                              <span className="text-xs font-bold text-slate-600 dark:text-slate-400">{h.weight.toFixed(1)}%</span>
                                              <div className="w-16 h-1.5 bg-slate-100 dark:bg-slate-700 rounded-full mt-1 overflow-hidden">
                                                  <div className="h-full bg-blue-500" style={{ width: `${Math.min(h.weight, 100)}%` }}></div>
                                              </div>
                                          </div>
                                      </td>
                                      <td className="px-4 py-4 text-right">
                                          {renderEditableCell(h, 'target')}
                                      </td>
                                      <td className="px-4 py-4 text-right">
                                          {Math.abs(h.actionValue) > (netWorth * 0.005) ? (
                                              <span className={`text-[10px] font-bold px-2 py-1 rounded-md uppercase ${h.actionValue > 0 ? 'bg-blue-50 text-blue-600 dark:bg-blue-900/20 dark:text-blue-400' : 'bg-amber-50 text-amber-600 dark:bg-amber-900/20 dark:text-amber-400'}`}>
                                                  {h.actionValue > 0 ? 'Buy' : 'Sell'} {formatMoney(Math.abs(h.actionValue))}
                                              </span>
                                          ) : (
                                              <span className="text-xs text-slate-300 dark:text-slate-600">-</span>
                                          )}
                                      </td>
                                      <td className="px-6 py-4 text-center">
                                          <div className="flex justify-center gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
                                              <button onClick={() => onTrade(h.symbol, TransactionType.BUY)} className="p-1.5 rounded-lg bg-emerald-50 dark:bg-emerald-900/20 text-emerald-600 hover:bg-emerald-100 transition-colors" title="Buy More">
                                                  <Plus size={14} />
                                              </button>
                                              <button onClick={() => onTrade(h.symbol, TransactionType.SELL)} className="p-1.5 rounded-lg bg-rose-50 dark:bg-rose-900/20 text-rose-600 hover:bg-rose-100 transition-colors" title="Sell">
                                                  <Minus size={14} />
                                              </button>
                                          </div>
                                      </td>
                                  </tr>
                              ))
                          )}

                          {/* Empty State */}
                          {sortedHoldings.length === 0 && (
                              <tr>
                                  <td colSpan={9} className="px-6 py-12 text-center text-slate-400">
                                      <div className="w-16 h-16 bg-slate-50 dark:bg-slate-800 rounded-full flex items-center justify-center mx-auto mb-3">
                                          <Layers size={24} className="opacity-50" />
                                      </div>
                                      <p className="text-sm font-medium">No assets found matching your criteria.</p>
                                  </td>
                              </tr>
                          )}
                      </tbody>
                  </table>
              </div>
          )}

          {/* Card View */}
          {viewMode === 'card' && (
              <div className="p-5 grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-4 animate-fade-in flex-1 content-start">
                  {sortedHoldings.map(h => (
                      <div key={h.symbol} className="bg-white dark:bg-slate-800 p-5 rounded-2xl border border-slate-200 dark:border-slate-700 shadow-sm hover:shadow-md transition-shadow relative group">
                          <div className="flex justify-between items-start mb-4">
                              <div className="flex items-center gap-3">
                                  <div className="w-10 h-10 rounded-xl bg-slate-50 dark:bg-slate-700/50 flex items-center justify-center font-bold text-xs text-slate-600 dark:text-slate-300 border border-slate-100 dark:border-slate-600">
                                      {h.symbol.substring(0,2)}
                                  </div>
                                  <div>
                                      <h3 className="font-bold text-slate-900 dark:text-white">{h.symbol}</h3>
                                      <p className="text-xs text-slate-500">{h.assetClass}</p>
                                  </div>
                              </div>
                              <div className={`text-xs font-bold px-2 py-1 rounded-lg ${h.unrealizedPLPercent >= 0 ? 'bg-emerald-50 text-emerald-600 dark:bg-emerald-900/20' : 'bg-rose-50 text-rose-600 dark:bg-rose-900/20'}`}>
                                  {h.unrealizedPLPercent >= 0 ? '+' : ''}{h.unrealizedPLPercent.toFixed(1)}%
                              </div>
                          </div>

                          <div className="space-y-3 mb-5">
                              <div className="flex justify-between items-end">
                                  <span className="text-xs text-slate-400 font-medium">Value</span>
                                  <span className="text-lg font-bold font-mono text-slate-900 dark:text-white">{formatMoney(h.marketValue)}</span>
                              </div>
                              <div className="flex justify-between items-center">
                                  <span className="text-xs text-slate-400 font-medium">Allocation</span>
                                  <div className="flex items-center gap-2">
                                      <div className="w-16 h-1.5 bg-slate-100 dark:bg-slate-700 rounded-full overflow-hidden">
                                          <div className="h-full bg-blue-500" style={{ width: `${Math.min(h.weight, 100)}%` }}></div>
                                      </div>
                                      <span className="text-xs font-bold text-slate-600 dark:text-slate-300">{h.weight.toFixed(1)}%</span>
                                  </div>
                              </div>
                          </div>

                          <div className="flex gap-2">
                              <button onClick={() => onTrade(h.symbol, TransactionType.BUY)} className="flex-1 py-2 rounded-xl bg-slate-50 dark:bg-slate-700/50 text-slate-600 dark:text-slate-300 text-xs font-bold hover:bg-emerald-50 hover:text-emerald-600 dark:hover:bg-emerald-900/20 dark:hover:text-emerald-400 transition-colors">Buy</button>
                              <button onClick={() => onTrade(h.symbol, TransactionType.SELL)} className="flex-1 py-2 rounded-xl bg-slate-50 dark:bg-slate-700/50 text-slate-600 dark:text-slate-300 text-xs font-bold hover:bg-rose-50 hover:text-rose-600 dark:hover:bg-rose-900/20 dark:hover:text-rose-400 transition-colors">Sell</button>
                          </div>
                      </div>
                  ))}
              </div>
          )}
      </div>
    </div>
  );
};

export default Holdings;
